window.XZ=window.XZ||{};(window.XZ.bank=window.XZ.bank||{})["生物化学"]=[["1988-N53",0,"第4节 蛋白质的理化性质","双缩脲反应",1988,53,"A","","在下列检测蛋白质的方法中，哪一种取决于完整的肽键",[["A","凯氏滴定法"],["B","双缩脲反应"],["C","280nm紫外吸收法"],["D","茚三酮反应"],["E","纳氏试剂法"]],"B","双缩脲反应（B对）是指在碱性溶液（NaOH）中，蛋白质和多肽分子中的肽键与硫酸铜共热呈现紫色或红色反应的现象，这一现象的发生取决于完整的肽键，可以用于检测蛋白质水解程度。凯氏滴定法（A错）是根据蛋白质中氮的含量恒定（约16%）的原理，通过测定样品中氮的含量从而推测蛋白质含量。280nm紫外吸收法（C错）主要用于检测含有共轭双键的酪氨酸和色氨酸在280nm紫外光下的最大吸收值而间接测定蛋白质的含量。茚三酮反应（十版生物化学P11）（D错）是指茚三酮水合物在弱酸性溶液中与氨基酸共加热时生成的蓝紫色的化合物的现象，此化合物在570nm波长处有最大吸收峰值，可作为氨基酸定量分析方法。纳氏试剂法（E错）（Nessler）是一种利用紫外-可见分光光度法原理测定空气中、水体中氮含量的方法。","","N"],["1988-N54",12,"第3节 真核生物mRNA的转录、加工和降解","前体mRNA5’-端加“帽”",1988,54,"A","","真核生物mRNA的5'末端的帽子结构是",[["A","-mGpppmN"],["B","-m²CpppmN"],["C","-m²ApppmN"],["D","-m⁷GpppmN"],["E","-m⁷ApppmN"]],"D","真核生物mRNA的5＇-末端的帽子结构是-m⁷Gpppm²N（D对），其生成过程（P284图15-13 真核mRNA的5＇-帽结构及加帽过程）为：首先，新生RNA的5＇-端核苷酸（N）的γ-磷酸被水解，在鸟苷酸转移酶的作用下与另一个GTP分子的5＇-端结合，形成5＇，5＇-三磷酸结构；然后由S-腺苷甲硫氨酸（SAM）先后提供甲基（m）使加上去的鸟嘌呤的N7和原新生RNA的5＇-端核苷酸（N）的核糖2＇-O甲基化，最终形成-m⁷Gpppm²N。","","N"],["1988-N55",1,"","",1988,55,"A","","酶抑制作用的的研究有且了解一些方面的内容，例外的是",[["A","酶活性中心功能基团的组成与性质"],["B","酶的专一性及其类型"],["C","酶的作用机制"],["D","药物和毒物的作用机理"],["E","活细胞内酶活性的调节方式"]],"A","略","","N"],["1988-N56",4,"第3节 糖的有氧氧化","丙酮酸氧化脱羧",1988,56,"A","","下列何种营养成分缺乏可造成体内丙酮酸积累",[["A","吡哆醇"],["B","硫胺素"],["C","叶酸"],["D","维生素PP"],["E","生物素"]],"B","细胞内丙酮酸的去路包括加氢生成乳酸、羧化生成草酰乙酸和氧化脱羧生成乙酰辅酶A等，其中氧化脱羧生成乙酰辅酶A是主要去路，由丙酮酸脱氢酶复合体催化，其辅酶包括焦磷酸硫胺素（TPP）、硫辛酸、FAD、NAD⁺和CoA，可记忆为赴美（辅酶A）交流（TPP，焦磷酸硫胺素）时留心（硫辛酸）谎（FAD，黄素腺嘌呤二核苷酸）言（NAD⁺，烟酰胺腺嘌呤二核苷酸）（亦可记忆为SPA，即名称中带有S、P、A字母的，注：硫的化学符号为S），缺乏这些辅酶，丙酮酸将无法被脱羧生成乙酰辅酶A，因此缺乏硫胺素（B对）可导致丙酮酸氧化脱羧受阻，造成丙酮酸积累。值得注意的是NAD⁺是维生素PP在体内的活性形式，维生素PP缺乏时，NAD⁺也缺乏，也可导致丙酮酸氧化脱羧受阻，促进丙酮酸积累，然而，在更上游的糖酵解阶段， 3-磷酸甘油醛的脱氢反应也是以NAD⁺为辅酶的，若NAD⁺缺乏，则糖酵解途径受阻，即作为糖酵解产物的丙酮酸的生成受阻，故维生素PP缺乏（NAD⁺缺乏）时，不会造成体内丙酮酸积累。","","N"],["1988-N57",7,"第1节 生物氧化与能量代谢","物质能量代谢的概述",1988,57,"A","","下列哪种物质不是高能化合物",[["A","3-磷酸甘油醛"],["B","磷酸肌酸"],["C","1，3-二磷酸甘油酸"],["D","乙酰CoA"],["E","磷酸烯醇式丙酮酸"]],"A","高能化合物指含有高能键的化合物，可大致记忆为以下四类：①NTP、NDP；②含有CoA的化合物（D对）；③可进行底物水平磷酸化的化合物，如1，3-二磷酸甘油酸（C对）、磷酸烯醇式丙酮酸（E对）、琥珀酰CoA；④磷酸肌酸（B对）。3-磷酸甘油醛（十版生物化学P108）为糖酵解的中间产物，不是高能化合物（A错，为本题正确答案）。","","N"],["1988-N58",11,"第1节 DNA复制的基本规律","DNA以半保留方式进行复制",1988,58,"A","","DNA复制是按半保留方式进行的，如将一个完全放射标记的双链DNA分子置于没有放射标记物的溶液中，进行两轮复制，如此所产生的四个DNA分子的放射活性将会",[["A","半数分子没有放射性"],["B","所有分子都有放射性"],["C","半数分子的两条链都有放射性"],["D","一个分子的两条链都有放射性"],["E","四个分子都不含放射性"]],"A","DNA的复制为半保留复制，子代细胞的DNA，一股单链从亲代完整地接受过来，另一股单联则完全重新合成，故无论复制几代，有放射性标记的DNA分子均为两个。当进行两轮复制时，共产生四个DNA分子，所以有放射和没放射性的分子各占一半（A对），有放射性的分子只有一条链有放射性。","","N"],["1988-N59",13,"第3节 肽链的合成过程","转位",1988,59,"A","","关于核蛋白体上的移位，下列哪种陈述是正确的",[["A","空载tRNA的脱落发生在A位上"],["B","肽酰tRNA的转位要求EF-G和GTP"],["C","核蛋白体沿mRNA 3'→5'方向相对移动"],["D","核蛋白体与mRNA相对移动距离相当于1个核苷酸的长度"],["E","肽酰-tRNA由P位转向A位"]],"B","原核生物的核糖体上有A位、P位和E位这3个重要的功能部位，在肽链合成中，分别作为氨基酰-tRNA进位、肽酰-tRNA结合和tRNA脱落排出的位置（A错）。延长因子EF-G有转位酶活性，由EF-Tu结合并水解1分子GTP供能，促进肽酰-tRNA的转位（B对）。核蛋白体（核糖体）的移动方向即蛋白质的合成方向，该方向与与复制和转录一样，都是5’→3’方向进行的（C错）。三个相邻的核苷酸组成一个密码子，编码一种氨基酸，成肽反应后，核蛋白体需要向mRNA的3’端移动一个密码子的距离，相当于3个核苷酸的长度（D错）。肽酰-tRNA在A位成肽，成肽后位于 A 位的肽酰-tRNA 移动到 P 位（E错）。","","N"],["1988-N60",9,"第3节 代谢调节的主要方式","别构调节对酶活性的调节",1988,60,"A","","有关变构酶的叙述哪项是错误的",[["A","能接受变构调节的酶常是两个以上的亚基组成的聚合体"],["B","G-6-P是己糖激酶的变构抑制剂"],["C","AMP是磷酸果糖激酶的变构激活剂"],["D","ATP是柠檬酸合成酶的变构激活剂"],["E","乙酰CoA是丙酮酸羧化酶的变构激活剂"]],"D","变构调节是指体内一些代谢物与酶结合使其构象发生改变，从而影响酶的活性的调节方式，能接受变构调节的酶常是两个以上的亚基（包括催化亚基、调节亚基等）组成的聚合体（A对）。G-6-P（葡糖-6-磷酸）是己糖激酶的反应产物，对己糖激酶有变构抑制作用（B对）。磷酸果糖激酶和柠檬酸合酶均为糖有氧氧化的关键酶，能够被AMP变构激活（C对），而被ATP变构抑制（D错，为本题正确答案）。乙酰CoA激活丙酮酸羧化酶（E对），使丙酮酸转变为草酰乙酸，加速糖异生。","","N"],["1988-N61",21,"第4节 胆色素的代谢与黄疸","结合",1988,61,"A","","关于未结合胆红素在肝内的转变。下列哪种说法是正确的",[["A","不经转变直接由胆道排出"],["B","正常情况下主要与1分子葡萄糖醛酸形成复合物"],["C","胆红素硫酸酯约占总结合胆红素30％"],["D","葡萄糖醛酸的半缩醛基与胆红素上羟基形成苷"],["E","葡萄糖醛酸的半缩醛基与胆红素丙酸基的羧基形成酯"]],"E","未结合胆红素又称游离胆红素，水溶性小，不能直接由胆道排出（A错）。未结合胆红素在肝内可与葡萄糖醛酸、硫酸等强极性物质发生结合反应生成结合胆红素，以提高胆红素的水溶性：大部分情况下，在滑面内质网UDP-葡糖醛酸基转移酶（UGT）的催化下，由UDPGA提供葡糖醛酸基，胆红素分子的丙酸基与葡糖醛酸以酯键结合（E对D错），生成葡糖醛酸胆红素。由于胆红素分子中含有2个羧基，正常情况下主要与2分子葡萄糖醛酸形成复合物（B错）。未结合胆红素亦可与活性硫酸根结合生成胆红素硫酸酯，胆红素硫酸酯约占总结合胆红素的15%（C错）。","","N"],["1988-N80",4,"第2节 糖的无氧氧化","已糖激酶",1988,80,"B","","与糖酵解有关的酶",[["A","己糖激酶"],["B","磷酸烯醇式丙酮酸羧激酶"],["C","丙酮酸脱氢酶"],["D","α-酮戊二酸脱氢酶"],["E","乙酰CoA羧化酶"]],"A","己糖激酶是糖酵解的关键酶（A对）。磷酸烯醇式丙酮酸羧激酶是糖异生的关键酶（十版生物化学P128）（B错）。丙酮酸脱氢酶（复合体）是丙酮酸氧化脱羧的关键酶（十版生物化学P113）（C错）。α-酮戊二酸脱氢酶（复合体）是三羧酸循环的关键酶（十版生物化学P115）（D错）。乙酰CoA羧化酶是软脂酸合成的关键酶（十版生物化学P152）（E错）。","","N"],["1988-N81",5,"第3节 甘油三酯代谢","软脂酸合成的过程",1988,81,"B","","与脂酸合成有关",[["A","己糖激酶"],["B","磷酸烯醇式丙酮酸羧激酶"],["C","丙酮酸脱氢酶"],["D","α-酮戊二酸脱氢酶"],["E","乙酰CoA羧化酶"]],"E","乙酰CoA羧化酶为脂肪酸合成的关键酶（E对）。己糖激酶（A错）为糖酵解的关键酶。磷酸烯醇式丙酮酸羧激酶（十版生物化学P130）（B错）为糖异生的关键酶。丙酮酸脱氢酶复合体（十版生物化学P113）（C错）是丙酮酸氧化脱羧生成乙酰CoA时的关键酶。α-酮戊二酸脱氢酶（十版生物化学P120）（D错）是三羧酸循环中的关键酶。","","N"],["1988-N84",6,"第4节 个别氨基酸的代谢","酪氨酸的代谢",1988,84,"B","","尿黑酸尿症患者缺乏",[["A","转氨酶"],["B","对羟苯丙酮酸氧化酶"],["C","苯丙氨酸羟化酶"],["D","尿黑酸氧化酶"]],"D","尿黑酸是酪氨酸的代谢中间产物之一，正常情况下尿黑酸可在尿黑酸氧化酶的催化下进一步代谢成延胡索酸和乙酰乙酸。尿黑酸尿症患者缺乏尿黑酸氧化酶（D对），使尿黑酸分解受阻，大量尿黑酸从尿中排出产生尿黑酸尿症。","","N"],["1988-N85",6,"第4节 个别氨基酸的代谢","苯丙氨酸的代谢",1988,85,"B","","苯丙酮酸尿症患者缺乏",[["A","转氨酶"],["B","对羟苯丙酮酸氧化酶"],["C","苯丙氨酸羟化酶"],["D","尿黑酸氧化酶"]],"C","正常情况下，苯丙氨酸的主要代谢途径是在苯丙氨酸羟化酶的催化下生成酪氨酸，有少量苯丙氨酸可在苯丙氨酸转氨酶的催化生成苯丙酮酸。体内缺乏苯丙氨酸羟化酶（C对）时，不能将苯丙氨酸羟化为酪氨酸，苯丙氨酸经转氨基作用大量生成苯丙酮酸，大量苯丙酮酸及其部分代谢产物由尿排出，称为苯丙酮酸尿症。","","N"],["1988-N86",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径的概述",1988,86,"B","","下面分别表示嘌呤环结构中各原子的编号，谷氨酰胺提供哪些原子",[["A","C₄、C₅、N₇"],["B","N₃、N₉"],["C","C₂、C₈"],["D","N₁"],["E","C₄"]],"B","由图10-2可知，谷氨酰胺提供了嘌呤环结构中的第3位（N₃）及第9位（N₉）氮原子（B对）。","","N"],["1988-N87",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径的概述",1988,87,"B","","下面分别表示嘌呤环结构中各原子的编号，天冬氨酸提供哪些原子",[["A","C₄、C₅、N₇"],["B","N₃、N₉"],["C","C₂、C₈"],["D","N₁"],["E","C₄"]],"D","由图10-2可知，天冬氨酸提供了嘌呤环结构中的第1位（N₁）氮原子（D对）。","","N"],["1988-N100",21,"第4节 胆色素的代谢与黄疸","肝细胞性黄疸",1988,100,"X","","肝细胞性黄疸时胆红素变化的特点是",[["A","血清非结合胆红素增高"],["B","血清结合胆红素增高"],["C","血清凡登白试验呈双相反应"],["D","尿中胆红素阳性"],["E","以上都正确"]],"E","肝细胞性黄疸时，由于肝细胞功能受损，导致肝对胆红素的摄取、转化和排泄出现障碍，相当量的非结合胆红素潴留在血液中，因此血清非结合胆红素增高（A对）。部分未受损的肝细胞仍可生成结合胆红素，但因肝细胞损害和肝小叶结构破坏，结合胆红素无法正常排入胆小管内，而是反流入血，因此血清结合胆红素也增高（B对）。由于血清中非结合胆红素和结合胆红素均增高，故血清凡登白试验（即重氮试剂反应）呈双相反应（C对）。血清中的结合胆红素可以透过肾小球滤过膜，随尿液排出体外，因此尿中胆红素阳性（D对）。本题ABCD均对，正确答案为E。","","N"],["1988-N143",17,"第3节 细胞受体介导的细胞内信号转导","细胞内受体的作用",1988,143,"X","","类固醇激素作用机制",[["A","启动DNA转录"],["B","促进mRNA形成"],["C","诱导新蛋白质生成"],["D","也可直接作用于细胞膜"]],"ABC","类固醇激素的受体位于胞内，通常为转录因子。在没有激素作用时，受体（转录因子）与抑制蛋白（热休克蛋白）形成复合物，阻止受体向细胞核移动及其与DNA的结合；当激素与受体结合时，受体构象发生变化，导致抑制蛋白与其解聚，暴露出受体的核内转移部位及DNA结合部位，激素-受体复合物向核内转移，并结合在特异基因的激素反应元件上，启动DNA转录（A对），促进mRNA形成（B对），进而诱导新蛋白质生成（C对），引起细胞功能改变。八版生理学P408明确指出肾上腺皮质激素（类固醇激素）也可与靶细胞膜中的受体（D对）结合，通过第二信使产生快速效应，但当年给出的参考答案仅为ABC。","","N"],["1988-N144",2,"第4节 核酸的理化性质","核酸复性或形成杂交双链",1988,144,"X","","使变性DNA复性的条件是",[["A","温度要逐渐冷下来"],["B","DNA不均一时易复性"],["C","DNA浓度高时易复性"],["D","DNA溶液中盐浓度高时不易复性"]],"AC","某些理化因素可以导致DNA之间的氢键断裂，使DNA双链解离成单链，称为DNA变性。变性的条件缓慢除去后（A对），两条解离的互补链可以重新配对，恢复原来的双螺旋结构，这称为复性。但是，将热变性的DNA迅速冷却至4℃以下，两条解离的互补链还来不及形成双链，所以DNA不能发生复性，这一特性被用来保持DNA的变性状态。DNA不均一时，互补配对的可能性较小，复性相对困难（B错）。DNA浓度高时，互补配对的可能性增大，复性较容易（C对）。盐浓度高时，溶液离子强度增高，可以加速DNA复性（D错）。","","N"],["1988-N145",1,"第1节 酶的分子结构与功能","酶的分子组成",1988,145,"X","","能转变成含一个焦磷酸基辅酶的维生素是",[["A","尼克酰胺"],["B","核黄素"],["C","泛酸"],["D","吡哆醇"]],"ABC","维生素B2在小肠粘膜黄素激酶的作用下转变成FMN（核黄素），在细胞内进一步受焦磷酸化酶的催化生成FAD，FMN及FAD为维生素B2的活性形式（B对）。尼克酸经酶促反应可与腺嘌呤，核糖，磷酸组成NAD+和NADP+两种活性形式（A对）。泛酸可在体内磷酸化生成CoA（C对）。维生素B6吡哆醇，吡哆醛及吡哆胺，在体内以磷酸吡哆醇，磷酸吡哆醛，磷酸吡哆胺等三种活性形式存在，均不含有焦磷酸（D错）。","","N"],["1988-N146",7,"第2节 线粒体氧化体系与呼吸链","铁硫蛋白",1988,146,"X","","铁硫蛋白是",[["A","铁的贮存形式"],["B","往往以复合物的形式存在"],["C","参与铁的运输"],["D","参加线粒体递电子体系"]],"BD","铁硫蛋白往往以复合物（复合体Ⅰ、Ⅱ、Ⅲ均含有铁硫蛋白）（B对）的形式参加线粒体递电子体系（氧化呼吸链）（D对）的传递过程。铁的贮存形式是铁蛋白（A错）。参与铁的运输的是运铁蛋白（C错）。","","N"],["1988-N147",22,"第3节 血细胞物质代谢","红细胞内的糖无氧氧化的特殊途径",1988,147,"X","","红细胞中2，3-BPG具有哪些功能",[["A","调节红细胞中糖酵解"],["B","作为主要阴离子与阳离子平衡"],["C","是一种缓冲剂"],["D","主要在于调节Hb与O₂的亲和力，促进O₂的释放"]],"AD","2，3-二磷酸甘油酸旁路是红细胞内特有的一种代谢途径，它是在糖酵解中间产物1，3-二磷酸甘油酸处形成了分支（十版生物化学P355图26-5 甘油酸-2，3-二磷酸支路），经2，3-BPG转变为3-磷酸甘油酸，因此2，3-磷酸甘油酸可以作为一种红细胞内的一种储能形式，在红细胞能量不足时返回糖酵解供能，所以红细胞中的红细胞中2，3-BPG可以调节红细胞中的糖酵解（A对）。但2，3-BPG在红细胞内主要的功能并不是调节糖酵解，而是调节血红蛋白运氧，2，3-BPG可以降低血红蛋白与O₂的亲和力，促进氧气的释放（D对）。2，3-二磷酸甘油酸不是主要阴离子（B错），血浆中与阳离子平衡的主要阴离子为Cl⁻、HCO₃⁻和部分蛋白质。2，3-BPG缓冲作用（C错）有限，血浆中的主要缓冲对为HCO₃⁻和H₂CO₃。","","N"],["1988-N149",9,"第2节 代谢的相互联系","氨基酸与脂质的转变",1988,149,"X","","肝脏可利用氨基酸合成下列哪些含氮化合物",[["A","嘌呤及嘧啶类衍生物"],["B","肌酸"],["C","乙醇胺"],["D","胆碱"]],"ABCD","肝脏内氨基酸的代谢十分活跃，除了分解氨基酸、合成非必需氨基酸之外，还可利用一些氨基酸合成各种含氮化合物，如：利用天冬氨酸、谷氨酰胺、甘氨酸合成嘌呤（十版生物化学P218）及嘧啶（十版生物化学P225）类衍生物（A对）；利用甘氨酸、精氨酸合成肌酸（十版生物化学P189）（B对）；利用丝氨酸脱羧基（十版生物化学P155）合成乙醇胺（C对），而乙醇胺甲基化可进一步生成胆碱（D对）。","","N"],["1989-N50",0,"第1节 蛋白质的分子组成","氨基酸的分类",1989,50,"A","","在生理pH条件下，下列哪种氨基酸带正电荷",[["A","丙氨酸"],["B","酪氨酸"],["C","赖氨酸"],["D","色氨酸"],["E","异亮氨酸"]],"C","当pH<pI（等电点）时，氨基酸的氨基可结合氢离子而带正电荷，当pH>pI时，氨基酸的羧基解离出氢离子而带负电荷，由（十版生物化学P9表1-1 氨基酸分类）可知赖氨酸的pI为9.74，丙氨酸的pI为6.00，酪氨酸的pI为5.66，色氨酸的pI为5.89，异亮氨酸pI为6.02，人体内生理pH为7.35～7.45，故在生理情况下赖氨酸（C对）带正电荷，其余四者带负电荷。","","N"],["1989-N51",2,"第4节 核酸的理化性质","DNA变性",1989,51,"A","","双链DNA的Tm高是由下列哪组碱基含量高引起的",[["A","腺嘌呤（A）＋鸟嘌呤（G）"],["B","胞嘧啶（C）＋胸腺嘧啶（T）"],["C","腺嘌呤（A）＋胸腺嘧啶（T）"],["D","胞嘧啶（C）＋鸟嘌呤（G）"],["E","腺嘌呤（A）＋胞嘧啶（C）"]],"D","Tm（解链温度）是指DNA解链过程中，溶液在260nm处的吸光度达到最大值一半时所对应的温度。Tm值与DNA分子的GC含量有关，G+C含量越高，Tm值越高（D对）。","","N"],["1989-N52",1,"第4节 酶的调节","酶原的激活",1989,52,"A","","下列哪种胃肠道消化酶不是以无活性的酶原方式分泌的",[["A","核糖核酸酶"],["B","胰蛋白酶"],["C","糜蛋白酶"],["D","羧基肽酶"],["E","胃蛋白酶"]],"A","有些酶在细胞内合成、初分泌、或在其发挥催化功能前处于无活化状态，这种无活性的酶称为酶原。这些酶原需要通过激活过程才能产生有活性的酶。胃肠道消化酶如胃蛋白酶（E对）、胰蛋白酶（B对）、糜蛋白酶（C对）、羧基肽酶（D对）、核糖核酸酶（A对））等通常都是以无活性的酶原形式存在，被各种激活物激活后才具有消化蛋白的活性：胃蛋白酶原由H⁺/胃蛋白酶激活；胰蛋白酶原由肠激酶/胰蛋白酶激活；糜蛋白酶原、羧基肽酶原和核糖核酸酶原均由胰蛋白酶激活。故本题无正确答案，原参考答案为A。","","N"],["1989-N53",3,"第2节 水溶性维生素","维生素PP",1989,53,"A","","能扩张小血管及降低血清胆固醇的维生素是",[["A","维生素D"],["B","大剂量尼克酰胺"],["C","大剂量尼克酸"],["D","维生素A"],["E","维生素E"]],"C","烟酸，曾称为尼克酸（C对），是维生素PP的一种（另一种是烟酰胺，曾称为尼克酰胺），它以NAD⁺和NADP⁺的形式存在时，是体内多种不需氧脱氢酶的辅酶。近年来，烟酸作为药物已用于临床治疗高胆固醇血症，烟酸能抑制脂肪动员，使肝中VLDL的合成下降，从而降低血浆胆固醇。但如此大量服用烟酸或烟酰胺会引发血管扩张、脸颊潮红、痤疮及胃肠不适等毒性症状。","","N"],["1989-N54",4,"第2节 糖的无氧氧化","丙酮酸激酶",1989,54,"A","","不易逆行的糖酵解反应是",[["A","磷酸甘油糖酵解反应"],["B","丙酮酸激酶反应"],["C","醛缩酶反应"],["D","磷酸甘油酸激酶反应"],["E","以上都不是"]],"B","糖酵解中关键酶包括己糖激酶（葡糖激酶），磷酸果糖激酶-1和丙酮酸激酶（B对），关键酶催的反应均为不可逆反应。","","N"],["1989-N55",5,"第5节 胆固醇代谢","胆固醇的转化",1989,55,"A","","人体内胆固醇分解代谢的产物是",[["A","乙酰CoA"],["B","CO₂和H₂O"],["C","酮体"],["D","甲羟乙酸"],["E","胆汁酸"]],"E","胆固醇的去路：①被肝转化为胆汁酸（E对），这是胆固醇的主要去路。②在肾上腺皮质、睾丸、卵巢等处合成类固醇激素，包括醛固酮、皮质醇、雄激素、雌激素、孕激素等；③在皮肤被氧化为7-脱氢胆固醇，经紫外线照射转变为维生素D₃。","","N"],["1989-N56",22,"第2节 血红素的合成","血红素合成的概述",1989,56,"A","","下列不含血红素的物质为",[["A","过氧化氢酶"],["B","过氧化物酶"],["C","细胞色素"],["D","铁硫蛋白"],["E","肌红蛋白"]],"D","血红素是红细胞的主要成分血红蛋白的辅基，也是其他含血红素蛋白如肌红蛋白（E对）、细胞色素（C对）、过氧化氢酶（A对）及过氧化物酶（B对）等的辅基。铁硫蛋白（十版生物化学P199）为呼吸链蛋白，其辅基为Fe-S（铁硫中心），不含血红素（D错，为本题正确答案）。","","N"],["1989-N57",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶核苷酸从头合成途径的概述",1989,57,"A","","天冬氨酸可参与下列何种物质的合成",[["A","卟啉环"],["B","类固醇"],["C","脑磷脂"],["D","辅酶A"],["E","嘧啶"]],"E","天冬氨酸是嘧啶碱（E对）的合成原料之一。卟啉环（血红素由卟啉环与Fe²⁺螯合而成）（十版生物化学P485）（A错）的合成原料是琥珀酰CoA和甘氨酸。类固醇（B错）的合成原料是胆固醇。脑磷脂（磷脂酰乙醇胺）（C错）的合成原料包括甘油、脂肪酸、磷酸盐和丝氨酸（丝氨酸脱羧生成乙醇胺）（十版生物化学P155）。辅酶A（D错）的合成原料包括β-巯基乙胺、泛酸、腺嘌呤、核糖核酸、磷酸等（七版生物化学P441）。","","N"],["1989-N59",21,"第4节 胆色素的代谢与黄疸","胆色素代谢的概述",1989,59,"A","","体内胆色素主要来自下列哪一种物质的分解",[["A","铁卟啉化合物"],["B","胆固醇"],["C","类固醇激素"],["D","胆汁酸"],["E","肌酸"]],"A","体内胆色素主要来自于铁卟啉类化合物（包括血红蛋白、肌红蛋白、细胞色素等）（A对）的分解。","","N"],["1989-N81",21,"第4节 胆色素的代谢与黄疸","肝细胞性黄疸",1989,81,"B","","肝细胞性黄疸",[["A","胆红素来源过多"],["B","胆红素摄取障碍"],["C","胆红素结合障碍"],["D","胆红素排泄障碍"],["E","胆红素摄取、结合与排泄障碍"]],"E","临床上常根据黄疸发病的原因不同，将黄疸分为溶血性黄疸、阻塞性黄疸和肝细胞性黄疸三类。其中肝细胞性黄疸是指由于肝细胞功能受损，使肝细胞对胆红素的摄取、结合和排泄均出现障碍（E对）而导致的黄疸。","","N"],["1989-N82",21,"第4节 胆色素的代谢与黄疸","溶血性黄疸",1989,82,"B","","溶血性黄疸",[["A","胆红素来源过多"],["B","胆红素摄取障碍"],["C","胆红素结合障碍"],["D","胆红素排泄障碍"],["E","胆红素摄取、结合与排泄障碍"]],"A","临床上常根据黄疸发病的原因不同，将黄疸分为溶血性黄疸、阻塞性黄疸和肝细胞性黄疸三类。其中溶血性黄疸又称肝前性黄疸，是由于红细胞的大量破坏，在单核-吞噬细胞系统产生胆红素过多，即胆红素来源过多（A对），超过了肝细胞摄取、转化和排泄胆红素的能力，造成血液中未结合胆红素浓度显著增高所致。","","N"],["1989-N107",4,"第5节 糖原的合成与分解","糖原合成",1989,107,"C","","ATP",[["A","脂酸合成需要"],["B","糖原合成需要"],["C","二者都需要"],["D","二者都不需要"]],"C","糖原合成的过程：①葡萄糖磷酸化为葡糖-6-磷酸，反应消耗1分子ATP；②葡糖-6-磷酸变构为葡糖-1-磷酸；③葡糖-1-磷酸活化为UDPG，反应消耗一份子UTP；④UDPG连接形成直链和支链。因此糖原合成是耗能过程，消耗一分子ATP（B对）和一分子UTP。软脂酸合成的过程：①乙酰CoA转化为丙二酸单酰CoA，反应消耗一分子ATP（A对）；②软脂酸以丙二酸单酰CoA为基本原料经7次缩合、还原（NADPH参与）、脱水、再还原（NADPH参与）基本反应循环合成。本题AB均对，正确答案为C。","","N"],["1989-N108",5,"第3节 甘油三酯代谢","软脂酸合成的原料",1989,108,"C","","NADPH+H⁺",[["A","脂酸合成需要"],["B","糖原合成需要"],["C","二者都需要"],["D","二者都不需要"]],"A","脂肪酸经缩合、加氢、脱水、再加氢的基本反应循环合成而来，其中加氢反应需要NADPH+H⁺参与（十版生物化学P155 图8-6 软脂酸的生物合成）（A对）。糖原合成的基本过程包括葡萄糖→葡糖-6-磷酸→葡糖-1-磷酸→UDPG→糖原，此过程中没有加氢还原反应，因此不需要NADPH+H⁺（B错）。","","N"],["1989-N109",6,"第4节 个别氨基酸的代谢","一碳单位的概念及运载体",1989,109,"C","","运载一碳单位的辅酶是",[["A","维生素B₆"],["B","四氢叶酸"],["C","两者均有"],["D","两者均无"]],"B","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的基团，包括甲基、甲烯基、甲炔基、甲酰基及亚氨甲基等，一碳单位不能游离存在，常与四氢叶酸（B对）结合而转运和参与代谢。维生素B₆（十版生物化学P100）（A错）的活性形式为磷酸吡哆醛，后者参与氨基的转运。","","N"],["1989-N110",6,"第2节 氨基酸的一般代谢","氨基转移酶的辅酶和作用机制",1989,110,"C","","转氨酶的辅酶是",[["A","维生素B₆"],["B","四氢叶酸"],["C","两者均有"],["D","两者均无"]],"A","体内存在着多种转氨酶，各种转氨酶的辅酶都是维生素B₆（A对）的磷酸酯，即磷酸吡哆醛。四氢叶酸（十版生物化学P187）（B错）主要作为一碳单位的转运体，是一碳单位转移酶的辅酶。","","N"],["1989-N149",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物前体RNA加工过程概的概述",1989,149,"X","","下列关于转录的说法中，哪些是正确的",[["A","凡是RNA的合成过程都称为转录"],["B","tRNA不能从DNA基因上直接转录，而是rRNA原始转录本的降解产物"],["C","对一个基因来说，两条DNA链均可转录"],["D","真核生物的原始转录产物多是无功能的RNA分子"]],"D","转录是以DNA为模板合成RNA的过程，对于真核生物而言，原始转录产物多为无功能的RNA分子（D对），需进行加工修饰才具有相应功能。RNA的合成有两种方式，一种是DNA指导的RNA合成，称为转录，另一种是RNA指导的RNA合成，称为复制（A错）。与mRNA一样，tRNA也从DNA基因上直接转录而来（P293图15-24 前体tRNA的剪接）（B错）。一般情况下，对具体某一个基因来说，只有其中一条DNA链参与转录，这条DNA链称为模板链（C错）， 然而，真核基因组中转录生成的 RNA 中有20% 以上存在反义RNA , 提示某些 DNA 双链区域在不同的时间点两条链都可以作为模板进行转录（十版生物化学P278）。本题的参考答案为D，原X型题为不定项选择题，可有单个或多个正确答案。","","N"],["1989-N150",14,"第2节 原核基因表达调控","操纵子",1989,150,"X","","操纵子包括下列哪些结构",[["A","启动基因"],["B","操纵基因"],["C","结构基因"],["D","调节基因"]],"ABCD","原核生物大多数基因表达调控是通过操纵子机制实现的，操纵子由结构基因（C对）与调控序列组成。结构基因是能转录出RNA的DNA区段（七版生物化学P267），而调控序列只是起调节和控制作用，包括启动子（启动基因）（A对）、操纵元件（操纵基因）（B对）以及一定距离外的调节基因（D对）。","","N"],["1989-N151",9,"第3节 代谢调节的主要方式","饥饿时的机体代谢",1989,151,"X","","短期饥饿时体内的代谢特点是",[["A","脂肪动员加强"],["B","肝脏酮体生成增加"],["C","糖异生作用加强"],["D","胰岛素释放增加"]],"ABC","短期饥饿通常指1～3天未进食，此时体内肝糖原已耗尽，血糖趋于降低，胰岛素分泌极少（D错）。短期饥饿时，机体从葡萄糖氧化供能转变为脂肪氧化供能，因此脂肪动员加强（A对）；脂肪动员所释放的脂肪酸经代谢转变可生成酮体，因此肝脏酮体生成也增加（B对）；同时，饥饿和血糖降低还可导致肝糖异生作用加强（C对）；此外，骨骼肌蛋白质的分解也会增强，分解的氨基酸进入肝后作为氧化供能及糖异生的原料。","","N"],["1989-N154",21,"第4节 胆色素的代谢与黄疸","结合",1989,154,"X","","未结合胆红素的特征是",[["A","可与清蛋白、球蛋白结合成复合物"],["B","易于透过生物膜造成毒性"],["C","是血浆中胆红素的存在形式"],["D","分子小，易于从尿中排出"]],"ABC","未结合胆红素是血浆中胆红素的存在形式（C对），又称血胆红素。未结合胆红素脂溶性大而水溶性小，易于透过生物膜造成毒性（B对），在血浆中需要与清蛋白（最主要）、球蛋白（α₁-球蛋白）结合成复合物（A对），一方面增加了水溶性，有利于血液运输；另一方面限制了胆红素透过生物膜产生细胞毒性。未结合胆红素因与清蛋白、球蛋白结合，不能透过肾小球滤过膜，故不能从尿中排出（D错）。","","N"],["1990-N6",21,"第4节 胆色素的代谢与黄疸","溶血性黄疸",1990,6,"A","","溶血性黄疸时，胆红素代谢主要特点是",[["A","血清非结合胆红素增多"],["B","血清结合胆红素明显增多"],["C","血清凡登白试验呈直接反应"],["D","尿胆红素阳性"],["E","尿（粪）胆原减少"]],"A","溶血性黄疸又称肝前性黄疸，是由于红细胞的大量破坏，在单核-吞噬细胞系统产生胆红素（非结合胆红素）过多，肝细胞对胆红素摄取、转化和排泄的量增加（结合胆红素合成和排泄增加），并到一定程度会超过肝细胞的处理能力，造成血清非结合胆红素增多（A对）所致。非结合胆红素分子内有氢键存在，不能与重氮试剂发生直接反应，只有在加入乙醇或尿素等破坏氢键后，才能与重氮试剂反应，故血清凡登白试验呈间接反应（C错）。非结合胆红素在血液中常与清蛋白结合而运输，不能透过肾小球滤过膜进入尿液中，故尿胆红素呈阴性（D错）。溶血性黄疸时，肝细胞组织结构并未受损，合成增加的结合胆红素全部排入肠腔（不会返流入血），与正常人一样，血清中不会出现结合胆红素（B错）。排泄入肠道的结合胆红素增加使肠道内生成的胆素原（d-尿胆素原、中胆素原、粪胆素原）（E错）也增加，进而被肠黏膜细胞重吸收进入肠肝循环的胆素原增加，最终尿中的尿胆素原（E错）也增加。","","N"],["1990-N51",0,"第1节 蛋白质的分子组成","肽的生理活性及多样性",1990,51,"A","","下列关于对谷胱甘肽的叙述中，哪一个说法是错误的",[["A","它是一个三肽"],["B","是一种具有两性性质的肽"],["C","是一种酸性肽"],["D","在体内是一种还原剂"],["E","它有两种离子形式"]],"E","谷胱甘肽是由谷氨酸，半胱氨酸和甘氨酸组成的三肽（A对）。谷胱甘肽含有两个羧基和一个氨基（十版生物化学P12 图1-5），因此谷胱甘肽是一种两性性质的酸性肽（BC对）。谷胱甘肽是体内重要的还原剂（D对），可以保护体内蛋白质或酶分子中的巯基免遭氧化，使蛋白质或酶处在活性状态。谷胱甘肽有还原型（GSH）和氧化型（GSSG）两种分子形式，而不是两种离子形式（E错，为本题正确答案）。","","N"],["1990-N52",2,"第2节 DNA和空间结构与功能","DNA的双螺旋结构",1990,52,"A","","下列关于DNA双螺旋结构模型的叙述中，除了哪一项外其余都是正确的",[["A","两股核苷酸链呈反向平行"],["B","两股链间有严格的碱基配对关系"],["C","为右手螺旋，每个含10对碱基"],["D","极性磷酸二酯键位于双螺旋内侧"],["E","螺旋直径约为2nm"]],"D","DNA两条链中一条链的5’→3’方向是自上而下，而另一条链的5’→3’方向是从自下而上，呈现出反向平行的特征（A对）。DNA两条链的碱基之间以氢键相结合，形成互补碱基对（B对）。DNA两条链围绕着同一个螺旋轴形成右手螺旋的结构，直径为2.37nm（E错，为本题正确答案），每个螺旋有10.5个（C错，为本题正确答案）碱基对，每两个相邻碱基对平面之间的垂直距离为0.34nm。在DNA双螺旋结构中，脱氧核糖、磷酸基团及二者形成的磷酸二酯键位于外侧（D错，为本题正确答案）而碱基位于内侧，两条链才得以通过碱基互补配对。故本题正确答案为CDE，但当年官方给出的参考答案仅为D。","","N"],["1990-N53",1,"第1节 酶的分子结构与功能","酶的分子组成",1990,53,"A","","酶的辅基",[["A","也称辅酶"],["B","通过非共价键与酶蛋白结合"],["C","由活性中心的氨基酸残基组成"],["D","与酶活性有关，但在反应中不被修饰或发生改变"],["E","不能用透析方法与酶蛋白分开"]],"E","辅酶和辅基为两种不同的辅助因子（A错），前者与酶蛋白结合疏松，可以用透析或超滤的方法除去，后者与酶蛋白共价结合（结合紧密）（B错），不易用透析或超滤的方法除去（E对）。辅酶和辅基多为小分子的有机化合物或金属离子（不由氨基酸残基组成）（C错）。在酶促反应中，辅因子参与传递电子，质子（或基团）或起运载体作用，在反应中可能被修饰或发生改变（D错）。","","N"],["1990-N54",1,"第1节 酶的分子结构与功能","酶的分子组成",1990,54,"A","","下列哪种维生素是辅酶A的成分",[["A","核黄素"],["B","泛酸"],["C","硫胺素"],["D","钴胺素"],["E","吡哆胺"]],"B","泛酸即维生素B₅，是辅酶A（CoA）的成分（B对）。核黄素即维生素B₂，是黄素腺嘌呤二核苷酸（FAD）的成分（A错）。硫胺素即维生素B₁，是焦磷酸硫胺素（TPP）的成分（C错）。钴胺素即维生素B₁₂，为辅酶B₁₂的成分（D错）。吡哆胺即维生素B₆的一种，为磷酸吡哆醛的成分（E错）。","","N"],["1990-N55",4,"第3节 糖的有氧氧化","三羧酸循环的过程",1990,55,"A","","在三羧酸循环和有关的呼吸链中，生成ATP最多的阶段是",[["A","柠檬酸→异柠檬酸"],["B","异柠檬酸→α-酮戊二酸"],["C","α-酮戊二酸→琥珀酸"],["D","琥珀酸→苹果酸"],["E","苹果酸→草酰乙酸"]],"C","三羧酸循环各步骤及能量生成情况：①乙酰辅酶A+草酰乙酸→柠檬酸（0个ATP）；②柠檬酸→异柠檬酸（0个ATP）；③异柠檬酸→α-酮戊二酸（2.5个ATP）；④α-酮戊二酸→琥珀酰CoA（2.5个ATP）；⑤琥珀酰CoA→琥珀酸（1个GTP或ATP，相当于1个ATP）；⑥琥珀酸→延胡索酸（1.5个ATP）；⑦延胡索酸→苹果酸（0个ATP）；⑧苹果酸→草酰乙酸（2.5个ATP）。因此从柠檬酸→异柠檬酸生成0个ATP，α-酮戊二酸→琥珀酰CoA生成2.5个ATP，α-酮戊二酸→琥珀酸生成3.5个ATP（C对），琥珀酸→苹果酸生成1.5个ATP，苹果酸→草酰乙酸生成2.5个ATP。","","N"],["1990-N56",5,"第5节 胆固醇代谢","胆固醇的合成场所",1990,56,"A","","人体合成及供应全身胆固醇能力最强的组织是",[["A","肾上腺与脑"],["B","肝与小肠"],["C","肝与脑"],["D","小肠与肾上腺"],["E","肾上腺与性腺"]],"B","体内胆固醇来源于食物及内源性合成。除脑组织（AC错）和成熟红细胞外，几乎全身各组织均可合成胆固醇，肝和小肠（B对）是主要合成器官，其中肝脏占合成总量的70%～80%，小肠占10%。肾上腺、性腺均可合成胆固醇，但合成量很小（DE错）。","","N"],["1990-N57",7,"第2节 线粒体氧化体系与呼吸链","甘油-3-磷酸穿梭",1990,57,"A","","下列能自由透过线粒体膜的物质是",[["A","NADH"],["B","草酰乙酸"],["C","脂酰CoA"],["D","磷酸二羟丙酮"],["E","乙酰CoA"]],"D","线粒体基质与胞质之间有线粒体内外膜相隔，外膜对物质的通透性高，选择性低，线粒体内膜含有与代谢物转运相关的转运蛋白体系，对各种物质进行选择性转运。胞质中生成的NADH（A错）需经α-磷酸甘油穿梭（脑和骨骼肌）或苹果酸-天冬氨酸穿梭（肝和心肌）进入线粒体中进行电子传递。草酰乙酸（B错）需经苹果酸脱氢酶作用，还原成苹果酸，或经谷草转氨酶的作用生成天冬氨酸从线粒体进入胞质进行糖异生（十版生物化学P131）。脂酰CoA（C错）需在肉碱脂酰转移酶催化下通过肉碱的协助才能进入线粒体进行β-氧化（十版生物化学P146）。在NADH的α-磷酸甘油穿梭中，磷酸二羟丙酮（Ｄ对）作为电子供体在线粒体和胞质中自由穿梭才能保证该循环不断进行。乙酰CoA（E错）通过柠檬酸-丙酮酸循环（P153）才通过线粒体膜运往胞质用于脂肪酸的合成。","","N"],["1990-N58",6,"第4节 个别氨基酸的代谢","含硫氨基酸的概述",1990,58,"A","","下列氨基酸中哪一种是体内蛋白质中所没有的含硫氨基酸",[["A","同型半胱氨酸"],["B","甲硫氨酸"],["C","半胱氨酸"],["D","胱氨酸"],["E","鸟氨酸"]],"A","参与人体蛋白质合成的氨基酸只有20种，但是在自然界中，人们发现的氨基酸已有300余种，选项中同型半胱氨酸（A）和鸟氨酸（E）均不存在于人体蛋白质中，其中同型半胱氨酸为含硫氨基酸（A对E错）。甲硫氨酸（B错）、半胱氨酸（C错）、胱氨酸（D错）均为人体蛋白质内存在的含硫氨基酸。","","N"],["1990-N59",4,"第5节 糖原的合成与分解","糖原合成",1990,59,"A","","从量上说，餐后肝内葡萄糖去路最多的代谢途径是",[["A","糖原合成"],["B","糖酵解"],["C","糖有氧氧化"],["D","磷酸戊糖途径"],["E","转变为其它单糖"]],"A","肝是血糖调节激素的主要靶器官。肝细胞主要通过调节糖原合成与分解、糖酵解、糖异生途径等维持血糖的相对恒定，以保障全身各组织，尤其是大脑和红细胞的能量供应。肝内葡萄糖的去路主要包括氧化分解、糖原合成、磷酸戊糖途径、合成脂肪酸及氨基酸等（十版生物化学P132）。餐后血糖水平较高，ATP和葡糖-6-磷酸水平较高时，能别构激活糖原合酶，促进糖原合成（A对），为餐后血糖主要的去路。正常进食时，肝仅氧化少量葡萄糖（与肝细胞葡糖激酶对葡萄糖亲和力很低有关 十版生物化学P131）（BC错），主要由氧化脂肪酸获得能量。磷酸戊糖途径（D错）及转变为其它单糖（E错）均不是餐后血糖的主要去路。","","N"],["1990-N107",9,"第3节 代谢调节的主要方式","饥饿时的机体代谢",1990,107,"C","","肝糖原",[["A","空腹12小时血糖主要来源"],["B","饥饿2～3天血糖主要来源"],["C","二者都不是"],["D","二者都是"]],"C","正常情况下体内直接供能物质是葡萄糖，人体的血糖必须维持一定的浓度才能保证机体重要组织器官正常的能量供应。血糖供应的来源主要是肝糖原和糖异生作用，最新教材观点为餐后12小时（12-18小时）肝糖原即可被耗尽，肝糖原耗尽后，主要靠糖异生补充血糖（AB均错，C为正确答案）。八版及更早版本教材的数据为餐后16小时（16-24小时）以后才主要靠糖异生补充血糖，故原参考答案为A。","","N"],["1990-N108",9,"第3节 代谢调节的主要方式","饥饿时的机体代谢",1990,108,"C","","甘油",[["A","空腹12小时血糖主要来源"],["B","饥饿2-3天血糖主要来源"],["C","二者都不是"],["D","二者都是"]],"B","正常情况下体内直接供能物质是葡萄糖，人体的血糖必须维持一定的浓度才能保证机体重要组织器官正常的能量供应。空腹状态下，血糖主要由肝糖原供应，但体内糖原的储备有限，如果没有补充，10多小时肝糖原即被耗尽，血糖来源断绝，此时机体处于饥饿状态，饥饿使体内糖异生作用增强，糖异生的主要原料为氨基酸，部分来自乳酸及甘油。因此，甘油只是饥饿2-3天血糖的来源之一，并非主要来源，本题的参考答案为B，并不严谨。","","N"],["1990-N109",6,"第3节 氨的代谢","鸟氨酸循环过程",1990,109,"C","","尿素合成的部位是",[["A","线粒体"],["B","细胞浆"],["C","两者都对"],["D","两者都不对"]],"C","尿素合成的步骤：①1分子NH₃和CO₂在氨基甲酰磷酸合成酶的催化下生成氨甲酰磷酸，反应在线粒体中进行；②氨基甲酰磷酸在鸟氨酸氨基甲酰转移酶的作用下，将氨基甲酰部分转移到鸟氨酸上生成瓜氨酸，反应在线粒体中进行；③瓜氨酸由线粒体转运至胞质，与天冬氨酸在精氨酸代琥珀酸合成酶催化下生成精氨酸代琥珀酸；④精氨酸代琥珀酸在精氨酸代琥珀酸裂解酶的催化下裂解为精氨酸，释放出延胡索酸，反应在胞质内进行；⑤精氨酸被精氨酸酶水解为尿素和鸟氨酸，反应在胞质内进行。以上前两个步骤在线粒体（A对）内进行，后三个步骤在胞浆（胞质）（B对）内进行。本题AB均对，正确答案为C。","","N"],["1990-N110",6,"第3节 氨的代谢","鸟氨酸循环过程",1990,110,"C","","尿素合成中氨基甲酰磷酸的合成部位是",[["A","线粒体"],["B","细胞浆"],["C","两者都对"],["D","两者都不对"]],"A","尿素和嘧啶的生物合成都始于氨基甲酰磷酸，但尿素合成中的氨基甲酰磷酸是在肝线粒体（A对）中由氨基甲酰磷酸合成酶Ⅰ（CPS-Ⅰ）催化生成的，而嘧啶合成中的氨基甲酰磷酸则是在细胞浆（细胞质）（B错）中用谷氨酰胺为氮源，由氨基甲酰磷酸合成酶Ⅱ催化生成的。","","N"],["1990-N149",11,"第2节 DNA复制的酶学和拓扑学","DNA连接酶的作用",1990,149,"X","","需要连接酶的是",[["A","DNA复制时"],["B","DNA损伤切除修复时"],["C","DNA的体外重组"],["D","RNA的转录"]],"ABC","DNA连接酶可以连接DNA链的3’-OH末端和另一DNA链的5’-P末端，二者间生成磷酸二酯键，从而将两段相邻的DNA链连接成完整的链。DNA复制时（A对），后随链的合成是不连续的，最后总留有缺口，需要DNA连接酶连接。DNA损伤切除修复时（B对），需要将损伤的碱基或核苷酸切除，最后也会留有缺口，需要DNA连接酶连接（十版生物化学P254）。DNA体外重组时（C对），可通过DNA连接酶将目的DNA和载体结合。RNA的转录是由RNA聚合酶（RNA pol）催化（十版生物化学P409）（D错）。","","N"],["1990-N150",13,"第2节 蛋白质合成体系","tRNA是氨基酸和密码子之间的特异连接物",1990,150,"X","","在蛋白质的生物合成中",[["A","氨基酸活化形成氨基酰-tRNA"],["B","tRNA携带氨基酸"],["C","mRNA起模板作用"],["D","rRNA是合成蛋白的场所"]],"ABC","蛋白质是以mRNA为模板（C对），由tRNA携带氨基酸（氨基酸活化形成氨基酰-tRNA）（AB对），在以rRNA为组分的核糖体内合成的（D错）。","","N"],["1990-N151",9,"第3节 代谢调节的主要方式","饥饿时的机体代谢",1990,151,"X","","短期饥饿时体内的代谢特点是",[["A","脂肪动员加强"],["B","肝脏酮体生成增加"],["C","糖异生作用加强"],["D","胰岛素释放增加"]],"ABC","短期饥饿通常指1～3天未进食，此时体内肝糖原已耗尽，血糖趋于降低，胰岛素分泌极少（D错）。短期饥饿时，机体从葡萄糖氧化供能转变为脂肪氧化供能，因此脂肪动员加强（A对）；脂肪动员所释放的脂肪酸经代谢转变可生成酮体，因此肝脏酮体生成也增加（B对）；同时，饥饿和血糖降低还可导致肝糖异生作用加强（C对）；此外，骨骼肌蛋白质的分解也会增强，分解的氨基酸进入肝后作为氧化供能及糖异生的原料。","","N"],["1990-N152",9,"第2节 代谢的相互联系","氨基酸与脂质的转变",1990,152,"X","","肝脏可利用氨基酸合成下列哪些含氮化合物",[["A","嘌呤及嘧啶类衍生物"],["B","肌酸"],["C","乙醇胺"],["D","胆碱"]],"ABCD","肝脏内氨基酸的代谢十分活跃，除了分解氨基酸、合成非必需氨基酸之外，还可利用一些氨基酸合成各种含氮化合物，如：利用天冬氨酸、谷氨酰胺、甘氨酸合成嘌呤（十版生物化学P218）及嘧啶（十版生物化学P225）类衍生物（A对）；利用甘氨酸、精氨酸合成肌酸（十版生物化学P189）（B对）；利用丝氨酸脱羧基（十版生物化学P155）合成乙醇胺（C对），而乙醇胺甲基化可进一步生成胆碱（D对）。","","N"],["1990-N153",6,"第3节 氨的代谢","鸟氨酸循环过程",1990,153,"X","","下列哪些反应可叫做生物转化",[["A","NH₃→尿素"],["B","乳酸→糖"],["C","胆红素→胆红素葡萄糖醛酸"],["D","乙酰CoA→CO₂+H₂O"]],"AC","生物转化是指机体在排出非营养物质之前，为了使它们的水溶性提高，极性增强而对其进行的代谢转变过程。NH₃（氨）（A对）和胆红素（C对）均属于机体内的非营养物质，前者主要在肝内通过鸟氨酸循环（尿素循环）（十版生物化学P182）合成水溶性和极性更高的尿素，继而排出体外，后者主要在内质网与葡糖醛酸基结合（十版生物化学P477）生成水溶性和极性更高的胆红素葡萄糖醛酸（即结合胆红素），继而排出体外，因此这两个过程均可叫做生物转化。乳酸（B错）通过糖异生途径转变为葡萄糖，以及乙酰CoA（D错）通过三羧酸循环彻底氧化成CO₂和H₂O均为机体内能源物质的代谢过程，与生物转化无关。","","N"],["1991-N7",0,"第2节 蛋白质的分子结构","蛋白质的二级结构",1991,7,"A","","蛋白质二级结构中通常不存在的构象",[["A","α-螺旋"],["B","β-折叠"],["C","α-转角"],["D","β-转角"],["E","无规则卷曲"]],"C","二级结构是指蛋白质分子中某一段肽链的局部空间结构，也就是该段肽链的主链骨架C原子的相对空间位置，并不涉及氨基酸残基侧链的构象。蛋白质的二级结构主要包括α-螺旋（A对）、β-折叠（B对）、β-转角（D对）、Ω环和无规卷曲（Ω环为九版后教材更新内容，替换了八版教材的无规卷曲，但是无规卷曲也是事实存在的）（E对）。不存在α-转角的构象类型（C错，为本题正确答案）。","","N"],["1991-N8",2,"第3节 RNA和空间结构与功能","mRNA的结构及功能",1991,8,"A","","下列关于RNA的说法哪项是正确的",[["A","只有rRNA、mRNA和tRNA三种"],["B","mRNA中含有遗传密码"],["C","tRNA是最小的一种RNA"],["D","胞浆中只有mRNA"],["E","rRNA是合成蛋白质的场所"]],"B","rRNA与核糖体蛋白共同构成核糖体，为蛋白质生物合成所需要的mRNA，tRNA以及多种蛋白因子提供了相互结合和相互作用的空间，E选项不严谨。生物体内目前已发现的RNA有十余种，rRNA、mRNA和tRNA只是其中最主要的三种类型（A错）。tRNA也只是在rRNA、mRNA和tRNA三者中最小，所有RNA中最小的应为miRNA（C错）。mRNA含有遗传密码（B对），为蛋白质的生物合成提供模板。rRNA、mRNA、tRNA、miRNA等多种RNA均存在于胞浆中（D错）。","","N"],["1991-N9",1,"第2节 酶的工作原理","降低反应的活化能",1991,9,"A","","酶能加速化学反应的进行是由于哪一种效应",[["A","向反应体系提供能量"],["B","降低反应的自由能变化"],["C","降低反应的活化能"],["D","降低底物的能量水平"],["E","提高产物的能量水平"]],"C","化学反应中，由于反应物分子中所含的能量高低不一，所含自由能较低的反应物分子，很难发生化学反应，若将低自由能的反应物分子（基态）转变为能量较高的过渡态分子，化学反应就有可能发生。活化能是指在一定温度下，1摩尔反应物从基态转变成过渡态所需要的自由能，即过渡态中间物比基态反应物高出的那部分能量。酶的作用就是降低反应的活化能（C对），促进反应的发生。","","N"],["1991-N10",2,"第1节 核酸的化学组成及其一级结构","碱基",1991,10,"A","","RNA和DNA彻底水解后的产物",[["A","核糖相同，部分碱基不同"],["B","碱基相同，核糖不同"],["C","碱基不同，核糖不同"],["D","碱基不同，核糖相同"],["E","完全不同"]],"C","DNA彻底水解后生成A，G，T，C和脱氧核糖，RNA彻底水解后生成A，U，G，C和核糖，故两者彻底水解后碱基不同，核糖也不同（C对）。","","N"],["1991-N11",5,"第5节 胆固醇代谢","胆固醇的合成过程",1991,11,"A","","胆固醇生物合成时的限速酶是",[["A","HMG辅酶A合成酶"],["B","HMG辅酶A还原酶"],["C","HMG辅酶A裂解酶"],["D","卵磷脂胆固醇脂酰转移酶"],["E","脂酰辅酶A胆固醇脂酰转移酶"]],"B","胆固醇生物合成时的限速酶（关键酶）是HMG辅酶A还原酶（B对）。HMG辅酶A合成酶（A错）为胆固醇合成（十版生物化学P159）和酮体合成（十版生物化学P149）的非限速酶。HMG辅酶A裂解酶（C错）为酮体合成（十版生物化学P149）的非限速酶。卵磷脂胆固醇脂酰转移酶（十版生物化学P168）（D错）和脂酰辅酶A胆固醇脂酰转移酶（十版生物化学P160）（E错）均为催化胆固醇酯生物合成的酶。","","N"],["1991-N17",7,"第4节 氧化磷酸化的影响因素","毒性气体阻断电子传递过程",1991,17,"A","","氰化物中毒是由于抑制了哪种细胞色素",[["A","a"],["B","b"],["C","c"],["D","aa₃"],["E","c₁"]],"D","细胞色素是氧化呼吸链的重要组成部分，广泛存在于呼吸链各复合体中，许多化合物可作用于复合体中的细胞色素而抑制电子的传递。氰化物（CN⁻）可抑制复合体Ⅳ中细胞色素a₃（而非细胞色素a）（A错），进而抑制细胞色素aa₃复合物（阻断电子由Cyt a到CuB-Cyt a₃间传递）（D对）。氰化物抑制的是细胞色素c氧化酶（复合体Ⅳ）而不是Cyt c（C错）。抗霉素A可抑制复合体Ⅲ中细胞色素b（阻断Cyt bH到泛醌间的电子传递）（B错）。八版教材中未提及Cyt c₁的抑制剂（E错）。","","N"],["1991-N18",17,"第1节 细胞信号转导概述","受体的分型",1991,18,"A","","哪项不是激素与受体结合的共同特征",[["A","有一定特异性"],["B","在细胞质膜上进行结合"],["C","有高度的亲和力"],["D","结合曲线呈可饱和状态"],["E","通过氢键、盐键或疏水作用相结合"]],"B","激素（配体）与其受体结合的共同特征：①有高度专一性，受体与特定配体特异性结合（A对）；②有高度的亲和力（C对），即使体内的化学信号的浓度很低也可以发生反应；③可饱和性（D对），细胞内受体和细胞表面受体的数目都是有限的，增加配体浓度，可使受体与配体的结合达到饱和；④可逆性，受体与配体通过氢键、盐键或疏水键等非共价键结合（E对），当生物效应发生后，配体即与受体解离，受体可恢复到原来的状态再次接受配体信息；⑤特定的作用模式，受体的分布和含量具有组织和细胞特异性，并呈现特定的作用模式。根据受体在细胞中的位置，可将受体分为细胞表面受体和细胞内受体。水溶性激素与细胞表面受体在质膜上进行结合，而脂溶性的激素与细胞内受体在细胞内进行结合，因此激素与受体并不全都在质膜上进行结合（B错，为本题正确答案）。","","N"],["1991-N19",11,"第2节 DNA复制的酶学和拓扑学","DNA复制的概述",1991,19,"A","","DNA复制需要①DNA聚合酶Ⅲ②解链蛋白③DNA聚合酶Ⅰ④DNA指导的RNA聚合酶⑤DNA连接酶。其作用的顺序是",[["A","④→③→①→②→⑤"],["B","②→③→④→①→⑤"],["C","④→②→①→⑤→③"],["D","④→②→①→③→⑤"],["E","②→④→①→③→⑤"]],"E","DNA的复制过程：解链蛋白（解螺旋酶）（②）解开DNA双链为单链，SSB稳定已解开的单链，拓扑异构酶理顺DNA链→DNA指导的RNA聚合酶（引物酶）（④）催化合成引物→在引物的引导下，DNA聚合酶Ⅲ（①）促进DNA链由5’向3’方向延长→复制结束后，RNA酶水解RNA引物，DNA聚合酶Ⅰ（③）填补引物空隙→最后由DNA连接酶（⑤）连接缺口。故作用的顺序为②→④→①→③→⑤（E对）。","","N"],["1991-N21",12,"第3节 真核生物mRNA的转录、加工和降解","前体mRNA的剪接",1991,21,"A","","DNA上的内含子（intron）是",[["A","不被转录的序列"],["B","被转录但不被翻译的序列"],["C","被转录也被翻译的序列"],["D","编码序列"],["E","以上都不对"]],"B","基因是由成千上万个核苷酸对组成。组成基因的核苷酸序列可以分为不同区段。在基因表达的过程中，不同区段所起的作用不同。能够转录为相应信使RNA，进而指导蛋白质合成（编码蛋白质）的区段叫做编码区，不能被转录并编码蛋白质的区段叫做非编码区（A错）。真核生物的编码区是由编码序列外显子（D错）和非编码序列内含子组成的，其中内含子将在转录后加工中被剪接去除，不能继续被翻译（B对），外显子则将保留并被翻译出来（翻译成蛋白质）（C错）。","","N"],["1991-N70",6,"第3节 氨的代谢","谷氨酰胺",1991,70,"A","","脑中氨的主要去路是",[["A","合成尿素"],["B","扩散入血"],["C","合成谷氨酰胺"],["D","合成氨基酸"],["E","合成嘌呤"]],"C","氨是体内的有毒物质，各组织必须以无毒的形式通过血液将氨运输到肝脏代谢。氨可以通过丙氨酸-葡萄糖循环将氨转变为丙氨酸从骨骼肌运往肝，也可以通过谷氨酰胺（C对）从脑和骨骼肌运往肝或肾。","","N"],["1991-N71",21,"第4节 胆色素的代谢与黄疸","胆素原进入体循环",1991,71,"A","","正常人尿中的主要色素是",[["A","胆红素"],["B","尿胆素"],["C","胆绿素"],["D","胆汁酸"],["E","血红素"]],"B","在正常人体内，结合胆红素（A错）随胆汁进入肠道后，可在肠道细菌的作用下还原生成胆素原。大部分胆素原随粪便排出体外，小部分胆素原可被肠黏膜细胞重吸收后经门静脉入肝，进入门静脉的胆素原90%以原形随胆汁排入肠腔，形成胆素原的肠肝循环，剩余的10%则可进入体循环，经肾小球滤过后随尿排出，称为尿胆素原，尿胆素原与空气接触后被氧化成尿胆素（B对），此为尿中的主要色素。胆绿素（十版生物化学P474）（C错）是胆红素合成过程中的中间产物。胆汁酸（十版生物化学P472）（D错）是体内胆固醇最主要的代谢产物。血红素（十版生物化学P485）（E错）是血红蛋白的辅基，可代谢生成胆色素。","","N"],["1991-N85",17,"第2节 细胞内信号转导分子","第二信使的概述",1991,85,"B","","哪项不是细胞内传递信息的第二信使",[["A","cAMP"],["B","cGMP"],["C","甘油一酯"],["D","甘油二酯"],["E","三磷酸肌醇（IP₃）"]],"C","第二信使是指外源信息在细胞内的信号转导分子，常见的第二信使包括：环腺苷酸（cAMP）（A对）、环鸟苷酸（cGMP）（B对）、甘油二酯（DAG）（D对）、三磷酸肌醇（IP₃）（E对）、磷脂酰肌醇-3，4，5-三磷酸（PIP₃）、Ca²⁺等。因此不属于第二信使的是甘油一酯（C错，为本题正确答案）。","","N"],["1991-N86",17,"第2节 细胞内信号转导分子","脂类衍生出的细胞内第二信使",1991,86,"B","","能促进蛋白激酶C活性的第二信使是",[["A","cAMP"],["B","cGMP"],["C","甘油一酯"],["D","甘油二酯"],["E","三磷酸肌醇（IP₃）"]],"D","甘油二酯（D对）能激活蛋白激酶C（PKC），PKC被激活后，可使多种蛋白质底物的丝氨酸或苏氨酸残基发生磷酸化，改变其活性状态。cAMP（A错）激活的是PKA（蛋白激酶A）（十版生物化学P389）。cGMP（B错）激活的是PKG（蛋白激酶G）。三磷酸肌醇（IP₃）（E错）激活的是Ca²⁺通道（IP₃受体），促进细胞钙库内的Ca²⁺迅速释放，使细胞质内Ca²⁺浓度升高（九版生理学P28）。甘油一酯不属于第二信使（C错）。","","N"],["1991-N101",3,"第2节 水溶性维生素","泛酸",1991,101,"C","","构成辅酶A的是",[["A","遍多酸（泛酸）"],["B","吡哆醛"],["C","两者都是"],["D","两者都不是"]],"A","遍多酸（泛酸）（A对）因广泛存在于组织中而得名，是辅酶A和酰基载体蛋白的组成成分。吡哆醛（B错）是维生素B₆的一种（十版生物化学P99），参与构成磷酸吡哆醛。","","N"],["1991-N102",6,"第2节 氨基酸的一般代谢","氨基转移酶的辅酶和作用机制",1991,102,"C","","构成转氨酶的是",[["A","泛酸"],["B","吡哆醛"],["C","两者都是"],["D","两者都不是"]],"B","体内存在着多种转氨酶，各种转氨酶的辅酶都是维生素B₆的磷酸酯，即磷酸吡哆醛（B对）。泛酸（十版生物化学P99）（A错）又名遍多酸，是辅酶A和酰基载体蛋白的组成成分。","","N"],["1991-N116",13,"第2节 蛋白质合成体系","蛋白质合成所需酶类和蛋白质因子",1991,116,"X","","蛋白质生物合成过程需要",[["A","mRNA"],["B","ATP"],["C","GTP"],["D","转肽酶"]],"ABCD","蛋白质生物合成即翻译，翻译过程包括起始、延长和终止三个阶段。翻译的起始是指mRNA、起始氨基酰-tRNA分别与核糖体结合而形成翻译起始复合物的过程。翻译的延长包括进位、成肽、转位三个步骤：进位是指一个氨基酰-tRNA按照mRNA模板（A对）的指令进入并结合到核糖体A位的过程；成肽是指在转肽酶（D对）的催化下，进入核糖体A位的氨基酰-tRNA运载的氨基酸与先前位于核糖体P位的氨基酸或多肽形成肽键的过程；转位是指成肽反应后，核糖体向mRNA的3’移动一个密码子的距离，以空出A位接受新的氨基酰tRNA进位的过程。翻译的终止是指终止密码子和释放因子导致肽链合成停止的过程。以上多个步骤需要消耗能量：参与进位的氨基酰-tRNA的合成过程需要消耗ATP（B对），进位、转位和翻译终止过程均需要消耗GTP（C对）。","","N"],["1991-N117",5,"第5节 胆固醇代谢","胆固醇的合成原料",1991,117,"X","","葡萄糖在体内代谢时通常可转变成",[["A","酮体"],["B","胆固醇"],["C","脂肪酸"],["D","乙酰乙酸"]],"BC","酮体（包括乙酰乙酸、β-羟丁酸和丙酮）、胆固醇和脂肪酸的合成原料均为乙酰CoA。其中，合成胆固醇（B对）和脂肪酸（C对）的乙酰CoA均可来自于葡萄糖在体内的代谢。而合成酮体（如乙酰乙酸）（AD错）的乙酰CoA则只能来源于脂肪酸的β-氧化，与葡萄糖在体内的代谢无关。","","N"],["1991-N118",6,"第4节 个别氨基酸的代谢","一碳单位的主要功能",1991,118,"X","","一碳单位是合成下列哪些物质所需要的原料",[["A","腺嘌呤"],["B","胆固醇"],["C","胸腺嘧啶"],["D","血红素"]],"AC","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的基团，其主要功能是参与嘌呤（所有嘌呤）和嘧啶（胸腺嘧啶）的合成（AC对）。合成胆固醇（十版生物化学P159）（B错）所需要的原料为乙酰CoA、NADPH。合成血红素（十版生物化学P485）（D错）所需要的原料为琥珀酰CoA、甘氨酸和Fe²⁺。","","N"],["1991-N120",6,"第2节 氨基酸的一般代谢","联合脱氨基作用",1991,120,"X","","催化联合脱氨基作用所需的酶是",[["A","L-氨基酸氧化酶"],["B","L-谷氨酸脱氢酶"],["C","谷氨酰胺酶"],["D","转氨酶"]],"BD","联合脱氨基作用包括转氨基作用和谷氨酸氧化脱氨两个方面。转氨基作用指各种氨基酸的氨基在转氨酶（D对）的作用下转移至α-酮戊二酸生成L-谷氨酸。谷氨酸氧化脱氨是指L-谷氨酸在L-谷氨酸脱氢酶（B对）的作用下脱下氨基。（十版生物化学P178）（A错）可将氨基酸氧化分解成相应的α-酮酸并脱去氨基，是联合脱氨基作用及嘌呤核苷酸循环之外的一种罕见的脱氨基方式。谷氨酰胺酶（十版生物化学P181）（C错）可将谷氨酰胺分解为谷氨酸和氨，介导氨从脑和骨骼肌等组织运往肝或肾的过程。","","N"],["1991-N152",7,"第2节 线粒体氧化体系与呼吸链","细胞质中的NADH被氧化",1991,152,"X","","胞液中NADH通过何种途径进入线粒体",[["A","3-磷酸甘油-磷酸二羟丙酮穿梭作用"],["B","柠檬酸-丙酮酸穿梭作用"],["C","苹果酸-天冬氨酸穿梭作用"],["D","草酰乙酸-丙酮酸穿梭作用"]],"AC","胞液中NADH通过两种穿梭机制进入线粒体的氧化呼吸链：①α-磷酸甘油穿梭（3-磷酸甘油-磷酸二羟丙酮穿梭）（A对），该穿梭机制主要存在于脑和骨骼肌中，1分子NADH经此穿梭能生成1.5分子ATP。②苹果酸-天冬氨酸穿梭（C对）主要存在于肝和心肌中，1分子NADH经此穿梭能生成2.5分子ATP。柠檬酸-丙酮酸穿梭（十版生物化学P151）（B错）介导线粒体中乙酰CoA进入胞质（进行脂酸合成）。草酰乙酸不能自由通透线粒体，不存在草酰乙酸-丙酮酸穿梭作用（穿梭的前提是自由通透）（D错）。","","N"],["1992-N39",0,"第1节 蛋白质的分子组成","氨基酸的分类",1992,39,"A","","含有两个氨基的氨基酸是",[["A","谷氨酸"],["B","丝氨酸"],["C","酪氨酸"],["D","赖氨酸"],["E","苏氨酸"]],"D","含有两个氨基的氨基酸有赖氨酸（D对）、天冬酰胺、谷氨酰胺和精氨酸（含两个氨基，一个亚氨基）。按照官能团取大不取小的原则，也可认为含有两个氨基的氨基酸只有赖氨酸一种（天冬酰胺和谷氨酰胺含一个氨基和一个酰胺基，精氨酸含一个氨基和一个胍基）。","","N"],["1992-N40",0,"第2节 蛋白质的分子结构","蛋白质的一级结构",1992,40,"A","","维系蛋白质一级结构的主要化学键是",[["A","盐键"],["B","疏水键"],["C","氢键"],["D","二硫键"],["E","肽键"]],"E","在蛋白质结构中，有四级结构，一级结构是指肽链中氨基酸自N端至C端的排列顺序，其连接键为肽键（E对），此外蛋白质分子中所有的二硫键（D错）也属于一级结构的范畴。二级结构是指蛋白质分子中某一段肽链的局部空间结构，包括α-螺旋、β-折叠、β-转角和Ω环，主要以氢键（C错）维持其稳定性。三级结构是整条肽链中全部氨基酸残基的相对空间位置，维系三级结构主要依靠疏水键（B错），盐键（A错），氢键（C错）及范德华力。四级结构是指蛋白质分子中各亚基的空间排布及亚基接触部位的布局和相互作用，维系四级结构依靠各亚基之间的非共价键。","","N"],["1992-N41",2,"第1节 核酸的化学组成及其一级结构","碱基",1992,41,"A","","RNA和DNA彻底水解后的产物",[["A","核糖相同，部分碱基不同"],["B","碱基相同，核糖不同"],["C","碱基不同，核糖不同"],["D","碱基不同，核糖相同"],["E","部分碱基不同，核糖不同"]],"E","DNA彻底水解后生成A，G，T，C和脱氧核糖，RNA彻底水解后生成A，U，G，C和核糖，故两者彻底水解后部分碱基不同，核糖不同（E对）。本题中选项C碱基不同，核糖不同的说法也是正确的，但部分碱基不同是最佳答案。","","N"],["1992-N42",1,"第3节 酶促反应动力学","竞争性抑制",1992,42,"A","","丙二酸对于琥珀酸脱氢酶的影响属于",[["A","反馈抑制"],["B","底物抑制"],["C","竞争性抑制"],["D","非竞争性抑制"],["E","别构调节"]],"C","竞争性抑制作用是指抑制剂和酶的底物在结构上相似，可与底物竞争结合酶的活性中心，从而阻碍酶与底物形成中间产物。丙二酸（HOOC-CH₂-COOH）与琥珀酸（HOOC-CH₂-CH₂-COOH）结构类似，可与其竞争性结合琥珀酸脱氢酶，故丙二酸对琥珀酸脱氢酶的抑制作用是竞争性抑制作用（C对）。","","N"],["1992-N43",9,"第3节 代谢调节的主要方式","饥饿时的机体代谢",1992,43,"A","","短期饥饿时，血糖浓度的维持主要靠",[["A","肝糖原分解"],["B","肌糖原分解"],["C","组织中葡萄糖的利用降低"],["D","糖异生作用"],["E","酮体转变成糖"]],"D","短期饥饿通常指1～3天未进食（十版生物化学P238），此时机体内的肝糖原已经被耗尽，不能提供血糖来源（A错），血糖浓度的维持主要靠糖异生作用（D对）。肌肉中缺乏葡糖-6-磷酸酶，肌糖原分解产生的葡糖-6-磷酸不能转变为葡萄糖，因而无法补充血糖（B错），仅能为肌肉活动供能。组织中葡萄糖的利用降低有利于血糖浓度的维持，但不是血糖浓度维持的主要原因（C错）。酮体可转变为乙酰辅酶A进入三羧酸循环进行彻底氧化，但不能异生为葡萄糖（E错）。","","N"],["1992-N44",4,"第2节 糖的无氧氧化","糖酵解",1992,44,"A","","位于糖酵解、糖异生、磷酸戊糖途径、糖原合成及糖原分解各条代谢途径交汇点上的化合物是",[["A","1-磷酸葡萄糖"],["B","6-磷酸葡萄糖"],["C","1，6-二磷酸果糖"],["D","3-磷酸甘油醛"],["E","6-磷酸果糖"]],"B","位于糖酵解、糖异生、磷酸戊糖途径、糖原合成及糖原分解各条代谢途径交汇点上的化合物是6-磷酸葡萄糖（B对）：经磷酸己糖异构酶催化生成6-磷酸果糖进入糖酵解（十版生物化学P107）；经葡萄糖-6-磷酸酶催化生成葡萄糖为糖异生（十版生物化学P128）及糖原分解（十版生物化学P124）的终末反应；经葡糖-6磷酸脱氢酶催化生成6-磷酸葡萄糖内酯进入磷酸戊糖途径（十版生物化学P121）；经磷酸葡萄糖变位酶催化生成1-磷酸葡萄糖进入糖原合成途径（P106）。","","N"],["1992-N45",5,"第3节 甘油三酯代谢","酮体的概述",1992,45,"A","","酮体包括",[["A","草酰乙酸、β-羟丁酸、丙酮"],["B","乙酰乙酸、β-羟丁酸、丙酮酸"],["C","乙酰乙酸、β-羟丁酸、丙酮"],["D","乙酰辅酶A、β-羟丁酸、丙酮"],["E","草酰乙酸、β-羟丁酸、丙酮酸"]],"C","酮体是脂肪酸在肝脏氧化分解时的中间代谢产物，包括乙酰乙酸、β-羟丁酸和丙酮（C对）。","","N"],["1992-N46",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸分解代谢的终产物",1992,46,"A","","下列哪种代谢异常，可引起血中尿酸含量增高",[["A","蛋白质分解代谢增加"],["B","胆红素代谢增加"],["C","胆汁酸代谢增加"],["D","嘌呤核苷酸分解代谢增加"],["E","嘧啶核苷酸分解代谢增加"]],"D","尿酸是人体嘌呤分解代谢的终产物，水溶性较差。当体内嘌呤核苷酸分解代谢增加（如白血病、恶性肿瘤等）时，可导致血中尿酸含量增高（D对）。蛋白质分解代谢增加（A错）时，可引起血氨增高（十版生物化学P171-172）。胆红素代谢增加（B错）时，可引起血中游离胆红素含量增高（十版生物化学P479）。嘧啶核苷酸分解代谢增加（如白血病、恶性肿瘤等）时，可引起尿中β-氨基异丁酸（胸腺嘧啶代谢产物）含量增高（十版生物化学P227）。","","N"],["1992-N47",7,"第1节 生物氧化与能量代谢","ATP为核苷酸相互转变提供能量",1992,47,"A","","关于ATP在能量代谢中的作用，哪项是错误的",[["A","体内合成反应所需的能量均由ATP直接供给"],["B","能量的生成、贮存、释放和利用都以ATP为中心"],["C","ATP的化学能可转变为机械能、渗透能、电能以及热能等"],["D","ATP经过氧化磷酸化作用生成"],["E","体内ATP的含量极少而转换极快"]],"A","ATP主要经氧化磷酸化作用生成（D对），是细胞可直接利用的能量形式，但并非体内所有的合成反应所需的能量均由ATP直接供给，如UTP、CTP、GTP分别可为糖原、磷脂、蛋白质等合成提供能量（A错，为本题正确答案）。ATP也是体内最重要的高能磷酸化合物，体内能量的生成、贮存、释放和利用都以ATP为中心（B对），ATP的化学能可转变为机械能、渗透能、电能以及热能等（C对）。体内ATP数量极少，氧化呼吸链中断后，极短时间内即可消耗殆尽，但因为正常状态下ATP与ADP间转换极快（E对），因而可以保证生命活动的正常进行。","","N"],["1992-N48",21,"第4节 胆色素的代谢与黄疸","结合",1992,48,"A","","肝中与胆红素结合的最主要基团是",[["A","硫酸根"],["B","乙酰基"],["C","葡萄糖醛酸基"],["D","甲基"],["E","以上都不是"]],"C","胆红素在肝中的结合反应发生在滑面内质网内，主要是在UDP-葡糖醛酸基转移酶（UGT）的催化下，与葡萄糖醛酸基（C对）结合生成葡糖醛酸胆红素，即结合胆红素（肝胆红素）。胆红素与硫酸根（A错）、乙酰基（B错）、甲基（D错）均可发生结合反应，但较为少见。","","N"],["1992-N49",5,"第5节 胆固醇代谢","胆固醇的转化",1992,49,"A","","胆固醇在体内代谢的主要去路是",[["A","转变成胆红素"],["B","转变成胆汁酸"],["C","转变成维生素D"],["D","转变成类固醇激素"],["E","转变成类固醇"]],"B","胆固醇的去路：①被肝转化为胆汁酸（B对），这是胆固醇的主要去路。②在肾上腺皮质、睾丸、卵巢等合成类固醇激素，包括醛固酮、皮质醇、雄激素、雌激素、孕激素等；③在皮肤被氧化为7-脱氢胆固醇，经紫外线照射转变为维生素D₃。","","N"],["1992-N50",6,"第4节 个别氨基酸的代谢","酪氨酸的代谢",1992,50,"A","","去甲肾上腺素可来自",[["A","色氨酸"],["B","酪氨酸"],["C","赖氨酸"],["D","脯氨酸"],["E","苏氨酸"]],"B","酪氨酸（B对）经羟化（生成多巴）、脱羧（生成多巴胺）、再羟化等步骤即可生成去甲肾上腺素。","","N"],["1992-N99",6,"第2节 氨基酸的一般代谢","氨基转移酶的辅酶和作用机制",1992,99,"B","","氨基转移酶的辅酶是",[["A","亚铁血红蛋白"],["B","尼克酰胺"],["C","磷酸吡哆醛"],["D","黄素腺嘌呤"],["E","辅酶A"]],"C","氨基转移酶即转氨酶，各种氨基转移酶的辅酶都是维生素B₆的磷酸酯，即磷酸吡哆醛（C对）。尼克酰胺（B错）（十版生物化学P98）主要活性形式为NAD⁺/NADP⁺，后者为不需氧脱氢酶的辅酶。黄素腺嘌呤（D错）（十版生物化学P97）主要活性形式为FAD，后者是氧化还原酶的辅酶。","","N"],["1992-N100",3,"第2节 水溶性维生素","维生素PP",1992,100,"B","","乳酸脱氢酶的辅酶含",[["A","亚铁血红蛋白"],["B","尼克酰胺"],["C","磷酸吡多醛"],["D","黄素腺嘌呤"],["E","辅酶A"]],"B","乳酸脱氢酶催化丙酮酸生成乳酸，所需要的氢原子由NADH+H⁺提供，因此其辅基为尼克酰胺（NAD⁺为尼克酰胺腺嘌呤二核苷酸）（B对）。亚铁血红蛋白参与O₂的携带与运输，与H⁺的转运无关（A错）。磷酸吡哆醛（十版生物化学P100）（C错）是体内百余种酶的辅酶，参与氨基酸脱氨与转氨作用、鸟氨酸循环、血红素的合成和糖原分解等，在代谢中发挥着重要作用。与尼克酰胺腺嘌呤二核苷酸（NAD⁺）一样，黄素腺嘌呤（FAD）（D错）是氧化呼吸链中重要的递氢体，是体内氧化还原酶如脂酰CoA脱氢酶、琥珀酸脱氢酶、黄嘌呤氧化酶等的辅酶（十版生物化学P97），但不是乳酸脱氢酶的辅酶。辅酶A（E错）是酰基转移酶的辅酶（十版生物化学P99）。","","N"],["1992-N101",13,"第2节 蛋白质合成体系","遗传密码的作用",1992,101,"B","","遗传密码中的起始密码子是",[["A","UAA"],["B","UUA"],["C","UGG"],["D","AUG"],["E","GAU"]],"D","遗传密码中的起始密码子是AUG（D对），AUG也是甲硫氨酸（蛋氨酸）的密码子。UAA（A错）为终止密码子。UUA（B错）为亮氨酸的密码子。UGG（C错）为色氨酸的密码子。GAU（E错）为天冬氨酸的密码子。","","N"],["1992-N102",13,"第2节 蛋白质合成体系","遗传密码的作用",1992,102,"B","","遗传密码中的终止密码子是",[["A","UAA"],["B","UUA"],["C","UGG"],["D","AUG"],["E","GAU"]],"A","遗传密码中的终止密码子包括UAA（A对）、UAG和UGA。UUA（B错）为亮氨酸的密码子。UGG（C错）为色氨酸的遗传密码。AUG（D错）为起始密码子。GAU（E错）为天冬氨酸的密码子。","","N"],["1992-N117",2,"第3节 RNA和空间结构与功能","mRNA的结构及功能",1992,117,"C","","mRNA的作用",[["A","转录DNA上的信息"],["B","指导蛋白质的合成"],["C","两者都是"],["D","两者都不是"]],"C","mRNA即信使RNA，是以DNA模板转录而来（A对），含有密码子，指导蛋白质的合成（B对）。本题AB均对，正确答案为C。","","N"],["1992-N118",2,"第3节 RNA和空间结构与功能","rRNA的结构及功能",1992,118,"C","","rRNA的作用",[["A","转录DNA上的信息"],["B","指导蛋白质的合成"],["C","两者都是"],["D","两者都不是"]],"D","核糖体rRNA是细胞内含量最多的RNA，约占RNA总量的80%以上，其主要作用为与核糖体蛋白共同构成核糖体，为蛋白质的生物合成提供场所。转录DNA上的信息（A错）和指导蛋白质的合成（B错）均为mRNA的作用。本题AB均错，正确答案为D。","","N"],["1992-N119",21,"第4节 胆色素的代谢与黄疸","结合",1992,119,"C","","经肠道随粪便排出的是",[["A","胆红素"],["B","胆素原"],["C","两者均有"],["D","两者均无"]],"B","结合胆红素（A错）随胆汁进入肠道后，可在回肠下段和结肠的肠菌作用下脱去葡糖醛酸基，还原成d-尿胆素原和中胆素原，其中，中胆素原又可进一步还原生成粪胆素原。以上d-尿胆素原、中胆素原和粪胆素原统称胆素原，大部分胆素原随粪便排出（B对）。","","N"],["1992-N120",21,"第4节 胆色素的代谢与黄疸","肝细胞性黄疸",1992,120,"C","","肝细胞性黄疸时尿中可以出现的是",[["A","胆红素"],["B","胆素原"],["C","两者均有"],["D","两者均无"]],"C","因肝细胞功能受损，导致肝对胆红素的摄取、转化和排泄出现障碍，大量游离胆红素潴留在血液中而引起的黄疸为肝细胞性黄疸。肝细胞性黄疸时，由于肝细胞肿胀，压迫毛细胆管，造成肝内毛细胆管阻塞，使未受损肝细胞生成的结合胆红素返流入血，结合胆红素可以透过肾小球滤过膜，随尿液排出体外，称为尿胆红素（A对）。在正常人体内，结合胆红素随胆汁进入肠道后，可在肠道细菌的作用下还原生成胆素原。大部分胆素原随粪便排出体外，小部分胆素原可被肠黏膜细胞重吸收后经门静脉入肝，进入门静脉的胆素原90%以原形随胆汁排入肠腔，形成胆素原的肠肝循环，剩余的10%则可进入体循环，经肾小球滤过后随尿排出，称为尿胆素原。肝细胞性黄疸时，随胆汁进入肠道的结合胆红素（肝细胞合成能力下降）减少，肠道内生成的胆素原及肠肝循环重吸收的胆素原均减少，但由于肝细胞性黄疸时本应随胆汁排入肠道的胆素原返流入血，透过肾小球滤过膜随尿液排出体外的胆素原并不一定减少，无论如何变化，尿中是可以出现胆素原的（B对）。本题AB均对，正确答案为C。","","N"],["1992-N153",16,"第2节 重组DNA技术","DNA克隆过程的步骤",1992,153,"X","","遗传工程的主要内容包括",[["A","载体和目的基因的分离"],["B","限制性内切酶的切割，并把载体和目的基因合成重组"],["C","DNA重组体的转化表达"],["D","DNA重组体的扩增、筛选与鉴定"]],"ABCD","遗传工程又称基因工程、重组DNA技术、分子克隆、DNA克隆等（十版生物化学P369）。遗传工程的主要内容（步骤）包括：分离、获取目的基因和合适的载体（A对，注意A选项表述容易引起歧义）→通过限制性内切酶的切割，将载体和目的基因合成重组（B对），形成DNA重组体→通过转化或转染技术，将DNA重组体（携带目的基因的载体）转入受体细胞（C对）→对被转入了DNA重组体的受体细胞进行扩增、筛选与鉴定（D对），最终得到含目的基因克隆（位于DNA重组体内）的细胞。","","N"],["1992-N154",12,"第1节 RNA的生物合成概述","以DNA为模板的RNA合成",1992,154,"X","","RNA转录时碱基的配对原则是",[["A","A-U"],["B","T-A"],["C","C-G"],["D","G-A"]],"ABC","生物体以DNA为模板合成RNA的过程称为转录。DNA中存在的碱基为A（腺嘌呤）、G（鸟嘌呤）、C（胞嘧啶）、T（胸腺嘧啶），RNA中存在的碱基为A（腺嘌呤）、G（鸟嘌呤）、C（胞嘧啶）、U（尿嘧啶），转录时碱基配对方式包括A-U（A对）、T-A（B对）、C-G（C对）。","","N"],["1992-N155",22,"第1节 血浆蛋白质","血浆蛋白质的功能",1992,155,"X","","血清清蛋白的生理功能是",[["A","维持胶体渗透压"],["B","结合运输某些物质"],["C","具有某些酶的作用"],["D","缓冲作用和免疫作用"]],"AB","由于清蛋白的分子量小，在血浆内的总含量大、摩尔浓度高，加之在生理pH条件下，其电负性高，能使水分子聚集其分子表面，故血清清蛋白能维持胶体渗透压（A对）。此外，血清清蛋白表面分布有众多的亲脂性结合位点，可结合运输脂肪酸、Ca²⁺、胆红素、磺胺等多种物质（B对）。血清中具有酶的作用（C错）、缓冲作用和免疫作用（D错）的蛋白均为球蛋白。","","N"],["1992-N156",5,"第6节 血浆脂蛋白及其代谢","低密度脂蛋白的功能和代谢途径",1992,156,"X","","低密度脂蛋白（LDL）的主要功能是",[["A","转运甘油三酯从肝到各组织"],["B","转运磷脂酰胆碱"],["C","转运甘油三酯从小肠到肝及肝外组织"],["D","转运胆固醇从肝到组织"]],"D","低密度脂蛋白（LDL）的主要功能是转运内源性胆固醇，即转运胆固醇从肝到组织（D对）。低密度脂蛋白可转运磷脂酰胆碱（卵磷脂），但不是其主要功能（B错）。转运甘油三酯从肝到各组织（即转运内源性甘油三酯）（A错）是极低密度脂蛋白的主要功能。转运甘油三酯从小肠到肝及肝外组织（即转运外源性甘油三酯）（C错）是乳糜微粒的主要功能。","","N"],["1993-N17",12,"第3节 真核生物mRNA的转录、加工和降解","前体mRNA的剪接",1993,17,"A","","DNA上的外显子（exon）是",[["A","不被转录的序列"],["B","被转录但不被翻译的序列"],["C","被转录也被翻译的序列"],["D","调节基因序列"],["E","以上都不对"]],"C","在真核生物DNA编码序列中，最终出现在成熟mRNA分子中、作为模板指导蛋白质翻译的序列称之为外显子序列，因此外显子是被转录也被翻译的序列（C对）。不被转录的序列（A错）是非编码序列（十版生物化学P285）。被转录但不被翻译的序列（B错）是编码序列中间隔外显子的内含子（十版生物化学P285）。调节基因序列（D错）是原核生物操纵子调控序列的一部分（十版生物化学P320），乳糖操纵子中编码阻遏蛋白的I基因即属于调节基因序列。","","N"],["1993-N18",16,"第2节 重组DNA技术","限制性核酸内切酶",1993,18,"A","","下列关于限制性内切酶的叙述哪一项是错误的",[["A","它能识别DNA特定的碱基顺序，并在特定的位点切断DNA"],["B","切割点附近的碱基顺序一般呈回文结构"],["C","它能专一降解经甲基化修饰的DNA"],["D","是重组DNA的重要工具酶"],["E","主要从细菌中获得"]],"C","限制性核酸内切酶是一种从细菌中（E对）获得的参与DNA重组的重要工具酶（D对），其主要功能是能识别DNA特定的回文结构（B对）序列，并在特定的位点切断DNA（A对）。大部分限制性内切酶对DNA甲基化敏感，经甲基化修饰的DNA将不能被限制性内切酶降解（C错，为本题正确答案）。","","N"],["1993-N19",1,"第3节 酶促反应动力学","酶促反应动力学参数",1993,19,"A","","Km值的概念应是",[["A","在一般情况下是酶-底物复合物的解离常数"],["B","是达到Vmax所必须的底物浓度的一半"],["C","同一种酶的各种同工酶Km值相同"],["D","是达到1／2Vmax的底物浓度"],["E","是与底物的性质无关的特征性常数"]],"D","Km即米氏常数，它是酶的特征性常数，它在数值上等于酶促反应速率为最大反应速率一半时的底物浓度（D对B错）。Km的值的并非固定不变，它与酶的结构、底物结构（E错）、反应环境的pH、温度和离子强度有关。同工酶是指催化相同的反应但理化性质不同的酶，它们的Km通常是不同的（C错）。酶（E）-底物（S）复合物的解离常数为Ks（十版生物化学P43）（A错）。","","N"],["1993-N20",0,"第5节 蛋白质的分离、纯化与结构分析","层析",1993,20,"A","","用凝胶过滤层析（交联葡聚糖凝胶）柱分离蛋白质时，下列哪项是正确的",[["A","分子体积最大的蛋白质最先洗脱下来"],["B","分子体积最小的蛋白质最先洗脱下来"],["C","不带电荷的蛋白质最先洗脱下来"],["D","带电荷的蛋白质最先洗脱下来"],["E","没有被吸附的蛋白质最先洗脱下来"]],"A","凝胶过滤层析，又称为分子筛层析，是一种根据蛋白质分子大小不同对蛋白质进行分离的方法。它的层析柱中充满了不同大小孔径的凝胶颗粒，小分子的蛋白质可以通过小孔暂时进入颗粒中，而大分子蛋白质不能进入颗粒直接流出，因此最先被洗脱的是分子量最大的蛋白质（A对B错）。根据蛋白质所带电荷不同进行层析的方法是离子交换层析（CD错）。没有被吸附的蛋白质最先洗脱下来（E错）为亲和层析的特点。","","N"],["1993-N21",5,"第3节 甘油三酯代谢","酮体的氧化利用",1993,21,"A","","酮体不能在肝中氧化的主要原因是肝中缺乏下列哪种酶",[["A","HMG-CoA裂解酶"],["B","HMG-CoA还原酶"],["C","琥珀酰CoA转硫酶"],["D","乙酰乙酸裂解酶"],["E","乙酰乙酸CoA脱酰酶"]],"C","酮体包括乙酰乙酸、β-羟丁酸和丙酮。丙酮生产量很少，可经肺呼出，乙酰乙酸、β-羟丁酸则在肝外组织被氧化利用，由于β-羟丁酸的利用是先在β-羟丁酸脱氢酶催化下，脱氢生成乙酰乙酸，再转变为乙酰CoA被氧化，因此酮体的氧化主要指乙酰乙酸的氧化。乙酰乙酸的氧化有两条途径：一是在心、肾、脑及骨骼肌线粒体，由琥珀酰CoA转硫酶催化生成乙酰乙酰CoA；二是在肾、心和脑线粒体，由乙酰乙酸硫激酶催化，直接活化生成乙酰乙酰CoA。肝组织因缺乏琥珀酰CoA转硫酶（C对）和乙酰乙酸硫激酶这两种利用酮体的酶，不能利用酮体。HMG-CoA裂解酶（十版生物化学P149）（A错）为参与酮体合成的酶。HMG-CoA还原酶（十版生物化学P159）（B错）为参与胆固醇合成的酶（关键酶）。人体内不存在乙酰乙酸裂解酶（D错）和乙酰乙酸CoA脱酰酶（E错）这两种酶。","","N"],["1993-N22",6,"第2节 氨基酸的一般代谢","联合脱氨基作用",1993,22,"A","","参与联合脱氨基过程的维生素有",[["A","维生素B₁、B₂"],["B","维生素B₁、PP"],["C","维生素B₆、B₁"],["D","维生素B₆、PP"],["E","维生素B₆、B₂"]],"D","联合脱氨基过程包括转氨基和谷氨酸氧化脱氨两步反应，分别由转氨酶和L-谷氨酸脱氢酶催化。转氨酶的辅酶为磷酸吡哆醛，包含维生素B₆（D对），起传递氨基的作用。L-谷氨酸脱氢酶的辅酶为NAD⁺，包含维生素PP（D对），参与转运谷氨酸氧化脱氨基反应中脱下的H⁺和电子。维生素B₁（十版生物化学P97）又称硫胺素，其活性形式为TPP（焦磷酸硫胺素），参与丙酮酸脱氢酶复合体（十版生物化学P113）、α-酮戊二酸脱氢酶复合体（十版生物化学P115）等催化的氧化脱羧过程。维生素B₂亦称核黄素，其活性形式为FAD和FMN（十版生物化学P97），参与琥珀酸脱氢酶、脂酰CoA脱氢酶等催化的氧化脱氢过程。","","N"],["1993-N23",7,"第1节 生物氧化与能量代谢","能量捕获和释放利用的重要分子",1993,23,"A","","人体活动主要的直接供能物质是",[["A","葡萄糖"],["B","脂肪酸"],["C","磷酸肌酸"],["D","GTP"],["E","ATP"]],"E","ATP（E对）是体内能量转移和磷酸核苷化合物相互转变的核心，是人体活动主要的直接供能物质。GTP（D错）、UTP、CTP可为糖原、磷脂、蛋白质等合成提供能量，但它们一般不能从物质氧化过程中直接生成，只能在核苷二磷酸激酶的催化下，从ATP中获得高能磷酸键而产生。磷酸肌酸（十版生物化学P189）（C错）为肌肉的能量储存形式。葡萄糖（A错）、脂肪酸（B错）可生成ATP，为间接供能物质。","","N"],["1993-N24",22,"第2节 血红素的合成","血红素合成的步骤总结",1993,24,"A","","下列关于血红蛋白的叙述哪一项是错误的",[["A","由球蛋白及血红素构成"],["B","由珠蛋白及血红素构成"],["C","有别构（变构）效应"],["D","是体内主要的含铁蛋白质"],["E","在血液运输O₂及CO₂中起重要作用"]],"A","血红蛋白（Hb）由4个亚基构成，其中每个亚基又由一分子的珠蛋白和一分子的血红素构成（B对）（A错，为本题正确答案），是体内主要的含铁蛋白质（血红素含Fe²⁺）（D对），在血液运输O₂及CO₂中起重要作用（E对）。在运输O₂的过程中，Hb的4个亚基之间具有别构（变构）效应（C对）：当Hb中第一个亚基与O₂结合以后，促进第二及第三个亚基与O₂的结合，当前3个亚基与O₂结合后，又大大促进第四个亚基与O₂结合，这种效应称为别构（变构）效应。","","N"],["1993-N25",7,"第3节 氧化磷酸化与ATP的生成","根据P_O比值确定氧化磷酸化耦联部位",1993,25,"A","","1克分子琥珀酸脱氢生成延胡索酸时，脱下的一对氢经过呼吸链氧化生成水，同时生成多少克分子ATP",[["A","1"],["B","2"],["C","3"],["D","4"],["E","5"]],"B","克分子为旧制单位，现称为摩尔。琥珀酸脱氢生成延胡索酸时，脱下的一对氢由FAD接受，转变为FADH₂，进入FADH₂氧化呼吸链（十版生物化学P116），最终生成1.5分子ATP（六版及以前教材为2分子ATP）。故1克分子琥珀酸脱氢生成延胡索酸时可生成1.5克分子ATP（2克分子ATP）（B对）。按十版教材观点本题无正确答案，但给出的参考答案为B。","","N"],["1993-N26",5,"第5节 胆固醇代谢","胆固醇的转化",1993,26,"A","","胆固醇是下列哪一种化合物的前体",[["A","维生素A"],["B","辅酶A"],["C","乙酰辅酶A"],["D","胆红素"],["E","皮质醇"]],"E","胆固醇的去路：①被肝转化为胆汁酸，这是胆固醇的主要去路；②在肾上腺皮质、睾丸、卵巢等合成类固醇激素，包括醛固酮、皮质醇（E对）、雄激素、雌激素、孕激素等；③在皮肤被氧化为7-脱氢胆固醇，经紫外线照射转变为维生素D₃。","","N"],["1993-N27",5,"第3节 甘油三酯代谢","软脂酸合成的场所",1993,27,"A","","在胞浆内进行的代谢途径有",[["A","三羧酸循环"],["B","氧化磷酸化"],["C","丙酮酸羧化"],["D","脂酸β氧化"],["E","脂酸合成"]],"E","线粒体是能量加工工厂，三羧酸循环（十版生物化学P114）（A错）、氧化磷酸化（十版生物化学P207）（B错）在线粒体中进行。脂肪酸β-氧化（十版生物化学P146）（D错）第一个步骤在胞浆中，其余在线粒体中进行。丙酮酸羧化（十版生物化学P128）（C错）为丙酮酸糖异生时的第一个反应，在线粒体中进行。脂肪酸合成（十版生物化学P152）（E对）在胞浆中进行。","","N"],["1993-N85",6,"第3节 氨的代谢","氨代谢的概述",1993,85,"B","","体内蛋白质分解代谢的最终产物是",[["A","尿素"],["B","氨"],["C","氨基酸"],["D","核苷酸"],["E","β-氨基异丁酸"]],"A","体内蛋白质代谢生成氨基酸（C错），氨基酸代谢生成氨（B错），氨最终在肝内代谢生成尿素（A对）。核苷酸（十版生物化学P217）（D错）是体内核酸分解代谢的中间产物。β-氨基异丁酸（十版生物化学P218）（E错）是胸腺嘧啶在体内分解代谢的最终产物。","","N"],["1993-N86",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶核苷酸的分解代谢的终产物",1993,86,"B","","体内核酸分解代谢的最终产物是",[["A","尿素"],["B","氨"],["C","氨基酸"],["D","核苷酸"],["E","β-氨基异丁酸"]],"E","核酸由核苷酸组成，核苷酸包括嘌呤核苷酸和嘧啶核苷酸两种，其中嘌呤核苷酸分解代谢的最终产物是尿酸（十版生物化学P223），嘧啶核苷酸分解代谢的最终产物是尿素、CO₂、H₂O等（十版生物化学P227）。本题给出的参考答案为E，但E选项并不严谨，因为β-氨基异丁酸只是胸腺嘧啶分解代谢的中间产物，该产物可进一步转化为琥珀酰CoA，最终进入柠檬酸循环被彻底氧化为CO₂和H₂O。","","N"],["1993-N87",13,"第1节 蛋白质合成的概述","翻译的概念",1993,87,"B","","将RNA核苷酸顺序的信息转变为氨基酸顺序的过程",[["A","复制"],["B","转录"],["C","反转录"],["D","翻译"],["E","翻译后加工"]],"D","DNA核苷酸顺序的信息转变为氨基酸顺序需要经历转录和翻译两个过程：转录（B错）将DNA核苷酸顺序的信息转变为mRNA核苷酸顺序，翻译（D对）则进一步将mRNA的核苷酸顺序的信息转变为氨基酸顺序。复制（十版生物化学P255）（A错）是指将母链DNA核苷酸顺序的信息转变为子链DNA核苷酸顺序的过程。反转录（十版生物化学P269）（C错）是指将RNA核苷酸顺序的信息转变为DNA核苷酸顺序的过程。翻译后加工（十版生物化学P306）（E错）只是对蛋白质本身进行水解切除或化学修饰等加工，不涉及信息传递过程。","","N"],["1993-N88",11,"第5节 逆转录","逆转录病毒的相关概念及步骤",1993,88,"B","","将病毒RNA的核苷酸顺序的信息，在宿主体内转变为脱氧核苷酸顺序的过程是",[["A","复制"],["B","转录"],["C","反转录"],["D","翻译"],["E","翻译后加工"]],"C","将RNA的信息传递给DNA（脱氧核苷酸）的过程称为反转录（逆转录）（C对）。","","N"],["1993-N113",13,"第2节 蛋白质合成体系","核糖体是蛋白质合成的场所",1993,113,"C","","血浆白蛋白生物合成的场所",[["A","线粒体"],["B","胞液"],["C","两者都是"],["D","两者都不是"]],"D","蛋白质的合成场所是核糖体（旧称核蛋白体），合成蛋白质肽链所需要的mRNA与tRNA结合、肽键形成等过程全部是在核糖体上完成的（D对）。胞液（B错）是糖（葡萄糖、糖原等）和脂（脂肪酸、胆固醇等）生物合成的场所。线粒体（A错）主要是物质分解代谢有氧氧化的场所（也作为血红素、尿素等非营养物质生物合成的场所）。","","N"],["1993-N114",6,"第3节 氨的代谢","鸟氨酸循环过程",1993,114,"C","","尿素生成的场所",[["A","线粒体"],["B","胞液"],["C","两者都是"],["D","两者都不是"]],"C","尿素生成的步骤：①1分子NH₃和CO₂在氨基甲酰磷酸合成酶的催化下生成氨甲酰磷酸，反应在线粒体中进行；②氨基甲酰磷酸在鸟氨酸氨基甲酰转移酶的作用下，将氨基甲酰部分转移到鸟氨酸上生成瓜氨酸，反应在线粒体中进行；③瓜氨酸由线粒体转运至胞质，与天冬氨酸在精氨酸代琥珀酸合成酶催化下生成精氨酸代琥珀酸；④精氨酸代琥珀酸在精氨酸代琥珀酸裂解酶的催化下裂解为精氨酸，释放出延胡索酸，反应在胞质内进行；⑤精氨酸被精氨酸酶水解为尿素和鸟氨酸，，反应在胞质内进行。以上前两个步骤在线粒体（A对）内进行，后三个步骤在胞液（胞质）（B对）内进行。本题AB均对，正确答案为C。","","N"],["1993-N135",0,"第5节 蛋白质的分离、纯化与结构分析","电泳",1993,135,"X","","聚丙烯酰胺凝胶电泳时，蛋白质的泳动速度取决于",[["A","蛋白质的分子量"],["B","蛋白质的分子形状"],["C","蛋白质所在溶液的PH值"],["D","蛋白质所在溶液的离子强度"]],"ABCD","聚丙烯酰胺凝胶电泳是根据蛋白质分子量大小和带电量不同对蛋白质进行分离的方法。蛋白质在电场中泳动速度受多种因素的影响，如分子量小的较分子量大的泳动速率快（A对），系因蛋白质横截面积小，所受阻力较小。相同分子量的蛋白质分子，球状较杆状泳动速率快（B对）。在相同pH的溶液中，带电多的蛋白质泳动速率快（C对），系因所受电场牵引力大。蛋白质分子在电场中的泳动受溶液中离子强度牵制，溶液中离子强度越低，蛋白质分子泳动速率越快（D对）。","","N"],["1993-N137",2,"第2节 DNA和空间结构与功能","DNA的双螺旋结构",1993,137,"X","","DNA双螺旋结构中的碱基对主要是",[["A","腺嘌呤--胸腺嘧啶"],["B","胞嘧啶--鸟嘌呤"],["C","尿嘧啶--鸟嘌呤"],["D","腺嘌呤--尿嘧啶"]],"AB","根据Chargaff规则，生物体内腺嘌呤（A）与胸腺嘧啶（T）的摩尔数相等，而鸟嘌呤（G）与胞嘧啶（C）的摩尔数相等，这是因为在DNA中，因为腺嘌呤（A）只能与胸腺嘧啶（T）配对（A对），鸟嘌呤（G）只能与胞嘧啶（C）配对（B对）。尿嘧啶（U）存在于RNA中，而不存在于DNA中（CD错）。","","N"],["1993-N138",6,"第1节 营养必需氨基酸与氨基酸代谢概述","蛋白质营养价值的决定因素",1993,138,"X","","下列氨基酸哪些是人类必需氨基酸",[["A","苯丙氨酸"],["B","酪氨酸"],["C","丝氨酸"],["D","苏氨酸"]],"AD","本知识点在九版之后的教材有重大更新，八版教材人体必需氨基酸（体内不能合成，必须靠食物供给）为八种，分别为亮氨酸、异亮氨酸、苏氨酸、缬氨酸、赖氨酸、甲硫氨酸、苯丙氨酸和色氮酸，九版后教材将组氨酸也列入了人体必需氨基酸的范畴。故根据最新教材，人体必需氨基酸为九种，分别为亮氨酸、异亮氨酸、苏氨酸（D对）、缬氨酸、赖氨酸、甲硫氨酸、苯丙氨酸（A对）、色氨酸和组氨酸。可记忆为“一家族人来写两三本书”，一（异亮氨酸）家（甲硫氨酸）族（组氨酸）人来（赖氨酸）写（缬氨酸）两（亮氨酸）三（色氨酸）本（苯丙氨酸）书（苏氨酸）。或“写一两本淡色书出来”，写（缬氨酸）一（异亮氨酸）两（亮氨酸）本（苯丙氨酸）淡（蛋氨酸/甲硫氨酸）色（色氨酸）书（苏氨酸）出（组氨酸）来（赖氨酸）。或“组队来写一两本淡色书”，组（组氨酸）队来（赖氨酸）写（缬氨酸）一（异亮氨酸）两（亮氨酸）本（苯丙氨酸）淡（蛋氨酸/甲硫氨酸）色（色氨酸）书（苏氨酸）。","","N"],["1993-N139",21,"第1节 肝在物质代谢中的作用","蛋白质合成及分解",1993,139,"X","","下列哪些物质的合成过程仅在肝脏进行",[["A","糖原"],["B","尿素"],["C","血浆蛋白"],["D","酮体"]],"B","机体合成尿素所必需的氨-依赖的氨基甲酰磷酸合成酶I及鸟氨酸氨基甲酰转移酶只存在于肝细胞线粒体。所以，肝是机体合成尿素的特异器官（B对），其他组织、器官不能进行尿素合成。糖原（A错）除在肝脏合成外，还可在肌肉内合成（十版生物化学P123）。绝大多数血浆蛋白在肝脏合成，如白蛋白、纤维蛋白原等，还有少量血浆蛋白是由其他组织细胞合成的（C错），如γ球蛋白（免疫球蛋白）是由浆细胞合成的（七版生物化学P393）。酮体（D错）主要在肝脏内合成（十版生物化学P148），在肾脏内也可少量合成（十版生物化学P501）。注意：当年的X型题为不定项选择题，答案可能为一个或者多个。","","N"],["1994-N1",0,"第2节 蛋白质的分子结构","蛋白质的二级结构",1994,1,"A","","维系蛋白质分子中α-螺旋和β-片层的化学键是",[["A","肽键"],["B","离子键"],["C","二硫键"],["D","氢键"],["E","疏水键"]],"D","α-螺旋和β-片层（β-折叠的旧称）均蛋白质的二级结构，维系蛋白质二级结构的主要化学键是氢键（D对）。肽键（A错）和二硫键（C错）为维系蛋白质一级结构的化学键（十版生物化学P13）。疏水键（E错）和离子键（盐键）（B错）为维系蛋白质三级结构的化学键（十版生物化学P17）。","","N"],["1994-N2",4,"第3节 糖的有氧氧化","三羧酸循环的过程",1994,2,"A","","与下列α-氨基酸相应的α-酮酸，何者是三羧酸循环的中间产物",[["A","丙氨酸"],["B","鸟氨酸"],["C","缬氨酸"],["D","赖氨酸"],["E","谷氨酸"]],"E","丙氨酸相应的α-酮酸是丙酮酸，丙酮酸是糖酵解的中间产物（A错）。谷氨酸的相应的α-酮酸是α-酮戊二酸，α-酮戊二酸可由异柠檬酸在异柠檬酸脱氢酶的催化下生成的，是三羧酸循环的中间产物（E对）。其余三种氨基酸相应的α-酮酸不常见。","","N"],["1994-N3",0,"第4节 蛋白质的理化性质","变性",1994,3,"A","","下列关于免疫球蛋白变性的叙述，哪项是不正确的",[["A","原有的抗体活性降低或丧失"],["B","溶解度增加"],["C","易被蛋白酶水解"],["D","蛋白质的空间构象破坏"],["E","蛋白质的一级结构并无改变"]],"B","免疫球蛋白的化学本质是蛋白质，其变性后的表现同蛋白质变性。蛋白质变性是指某些物理和化学因素作用下，其特定的空间构象被破坏（D对），理化性质及生物学活性丧失。蛋白质变性后：溶解度降低（B错，为本题正确答案），黏度增加，结晶能力消失，生物学活性丧失（A对），易被蛋白酶水解（C对）。蛋白质变性仅涉及空间结构的改变，其一级结构即氨基酸的排列顺序没有变化（E对）。","","N"],["1994-N4",1,"第1节 酶的分子结构与功能","酶的分子组成",1994,4,"A","","B族维生素的主要生理功能是参与组成辅酶，下述哪项叙述是错误的",[["A","尼克酰胺参与组成脱氢酶的辅酶"],["B","吡哆醛参与组成转氨酶的辅酶"],["C","生物素参与组成辅酶Q"],["D","泛酸参与组成辅酶A"],["E","核黄素参与组成黄酶的辅酶"]],"C","生物素属于B族维生素，是丙酮酸羧化酶、乙酰CoA羧化酶等多种羧化酶的辅基，与辅酶Q无关（C错，为本题正确答案）。辅酶Q又名泛醌，是生物体内少数与B族维生素无关的辅酶，在氧化呼吸链中发挥重要作用（递氢）。","","N"],["1994-N5",7,"第1节 生物氧化与能量代谢","物质能量代谢的概述",1994,5,"A","","下列哪种化合物中不含高能磷酸键",[["A","1，6-二磷酸果糖"],["B","二磷酸腺苷"],["C","1，3-二磷酸甘油酸"],["D","磷酸烯醇式丙酮酸"],["E","磷酸肌酸"]],"A","含有高能磷酸键的化合物可记忆为以下三种：①NTP、NDP（B对）；②可进行底物水平磷酸化的化合物，如1，3-二磷酸甘油酸（C对）、磷酸烯醇式丙酮酸（D对）；③磷酸肌酸（E对）。1，6二磷酸果糖（十版生物化学P108）分子中第1、6位是普通磷酸酯键，而不是高能磷酸键（A错，为本题正确答案）。","","N"],["1994-N6",4,"第3节 糖的有氧氧化","糖分解供能的主要方式",1994,6,"A","","1分子乙酰辅酶A经三羧酸循环和氧化磷酸化，共可生成几分子ATP（高能磷酸键）",[["A","2"],["B","4"],["C","8"],["D","10"],["E","12"]],"D","三羧酸循环过程中生成能量的步骤：①异柠檬酸→α-酮戊二酸（2.5个ATP）②α-酮戊二酸→琥珀酰CoA（2.5个ATP）③琥珀酰CoA→琥珀酸（1个GTP或ATP，相当于1个ATP）④琥珀酸→延胡索酸（1.5个ATP）⑤苹果酸→草酰乙酸（2.5个ATP）。因此1分子乙酰辅酶A经三羧酸循环和氧化磷酸化，共可生成10分子ATP。六版及以前的教材认为1分子NADH+H⁺的氢传递给氧时，可生成3个（现为2.5个）ATP，1分子FADH₂的氢被氧化时，可生成2个（现为1.5个）ATP，因此原答案为12分子ATP（E错），按照十版教材观点，应为10分子ATP（D对ABC错）。","","N"],["1994-N7",4,"第2节 糖的无氧氧化","磷酸果糖激酶-1",1994,7,"A","","指出何者是酵解过程中可被别构调节的限速酶",[["A","磷酸己糖异构酶"],["B","6-磷酸果糖激酶-1"],["C","醛缩酶"],["D","3-磷酸甘油醛脱氢酶"],["E","乳酸脱氢酶"]],"B","糖酵解过程的限速酶（关键酶）包括己糖激酶、磷酸果糖激酶-1（B对）和丙酮酸激酶，三者均可受别构效应剂的别构调节。磷酸己糖异构酶（A错）、醛缩酶（C错）、3-磷酸甘油醛脱氢酶（D错）、乳酸脱氢酶（E错）催化的反应均为可逆反应，非糖酵解过程中的限速酶。","","N"],["1994-N8",5,"第5节 胆固醇代谢","胆固醇的合成原料",1994,8,"A","","葡萄糖在体内代谢时，通常不会转变生成的化合物是",[["A","乙酰乙酸"],["B","胆固醇"],["C","脂肪酸"],["D","丙氨酸"],["E","核糖"]],"A","葡萄糖在体内代谢时，线粒体内产生的乙酰CoA可通过柠檬酸-丙酮酸循环（十版生物化学P151）进入胞质中，转变生成胆固醇（B对）和脂肪酸（C对）。葡萄糖的糖酵解途径产物丙酮酸可在转氨酶（十版生物化学P177）的作用下生成丙氨酸（D对）。葡萄糖可经磷酸戊糖途径（十版生物化学P122）生成磷酸核糖（E对）。乙酰乙酸（A错，为本题正确答案）属于酮体，酮体（十版生物化学P149）由脂肪酸β-氧化生成的乙酰CoA转变生成，葡萄糖分解产生的乙酰CoA不能用于生成酮体。","","N"],["1994-N9",12,"第1节 RNA的生物合成概述","以DNA为模板的RNA合成",1994,9,"A","","以5'…ACTAGTCAG…3'（DNA链）为模板合成相应mRNA链的核苷酸序列为",[["A","5'…TGATCAGTC…3'"],["B","5'…UGAUCAGUC…3'"],["C","5'…CUGACUAGU…3'"],["D","5'…CTGACTAGT…3'"],["E","5'…CAGCUGACU…3'"]],"C","生物体以DNA为模板合成RNA的过程称为转录，转录的碱基配对方式为A-U、T-A、C-G，因此以5’…ACTAGTCAG…3’为模板合成相应mRNA链的核苷酸序列为3’…UGAUCAGUC…5’，即5’…CUGACUAGU…3’（无论是DNA链还是RNA链，书写方式均应为5’→3’方向）（C对）。","","N"],["1994-N10",1,"第3节 酶促反应动力学","酶促反应动力学的概念",1994,10,"A","","通常测定酶活性的反应体系中，哪项叙述是不适当的",[["A","作用物的浓度愈高愈好"],["B","应选择该酶作用的最适pH"],["C","反应温度宜接近最适温度"],["D","合适的温育时间"],["E","有的酶需要加入激活剂"]],"A","酶促反应速率可受多种因素的影响，如酶浓度，底物浓度，pH，温度，抑制剂及激活剂等。最适pH（B对）、最适温度（C对）、合适的温育时间（D对）以及适当的激活剂（E对）均有助于酶促反应的快速进行。由于底物（作用物）浓度对酶促反应速度的影响呈矩形双曲线（十版生物化学P41），在底物浓度较低时，反应速率随底物浓度增加而加快，当底物浓度增加到一定限度时，反应速率将几乎不再增加，因此底物的浓度并不是愈高愈好（A错，为本题正确答案）。","","N"],["1994-N11",13,"第2节 蛋白质合成体系","遗传密码的作用",1994,11,"A","","能出现在蛋白质分子中的下列氨基酸，哪一种没有遗传密码",[["A","色氨酸"],["B","蛋氨酸"],["C","谷氨酰胺"],["D","脯氨酸"],["E","羟脯氨酸"]],"E","羟脯氨酸（E对）没有遗传密码，它是在蛋白质加工过程中，经脯氨酸羟基化修饰而来（七版生物化学P311）。色氨酸（A错）的遗传密码为UGG。蛋氨酸（甲硫氨酸）（B错）的遗传密码为AUG。谷氨酰胺（C错）的遗传密码为CAA、CAG。脯氨酸（D错）的遗传密码为CCU、CCC、CCA、CCG。","","N"],["1994-N12",7,"第1节 生物氧化与能量代谢","能量捕获和释放利用的重要分子",1994,12,"A","","人体活动主要的直接供能物质是",[["A","葡萄糖"],["B","脂肪酸"],["C","磷酸肌酸"],["D","GTP"],["E","ATP"]],"E","ATP（E对）是体内能量转移和磷酸核苷化合物相互转变的核心，是人体活动主要的直接供能物质。GTP（D错）、UTP、CTP可为糖原、磷脂、蛋白质等合成提供能量，但它们一般不能从物质氧化过程中直接生成，只能在核苷二磷酸激酶的催化下，从ATP中获得高能磷酸键而产生。磷酸肌酸（十版生物化学P189）（C错）为肌肉的能量储存形式。葡萄糖（A错）、脂肪酸（B错）可生成ATP，为间接供能物质。","","N"],["1994-N13",13,"第3节 肽链的合成过程","肽链合成过程的概述",1994,13,"A","","在体内，氨基酸合成蛋白质时，其活化方式为",[["A","磷酸化"],["B","与蛋氨酸相结合"],["C","生成氨基酰辅酶A"],["D","生成氨基酰tRNA"],["E","与起始因子相结合"]],"D","氨基酰-tRNA（D对）是体内氨基酸合成蛋白质时的活化形式，它是以氨基酸和特异的tRNA为底物，由氨基酰-tRNA合成酶催化而生成，每个氨基酸活化时需消耗2个来自ATP的高能磷酸键。","","N"],["1994-N14",11,"第2节 DNA复制的酶学和拓扑学","DNA复制的概述",1994,14,"A","","合成DNA的原料是",[["A","dAMP，dGMP，dCMP，dTMP"],["B","dATP，dGTP，dCTP，dTTP"],["C","dADP，dGDP，dCDP，dTDP"],["D","dATP，dGTP，dCTP，dUTP"],["E","dAMP，dGMP，dCMP，dUMP"]],"B","DNA合成的原料为模板DNA（两股链均参与复制）、dNTP（N代表A，T，C，G）（B对）、以及DNA聚合酶，合成的产物为子代双链DNA。RNA合成原料为模板链（单股链参与合成）、NTP（N代表A，U，C，G）、以及RNA聚合酶，转录产物为mRNA，tRNA，rRNA。","","N"],["1994-N93",5,"第5节 胆固醇代谢","胆固醇的合成原料",1994,93,"B","","体内合成胆固醇的主要原料是",[["A","乙酰辅酶A"],["B","乙酰乙酰辅酶A"],["C","丙酰辅酶A"],["D","草酰乙酸"],["E","葡萄糖"]],"A","胆固醇合成需要乙酰CoA（A对）供碳源，NADPH供氢及ATP供能，合成1分子胆固醇需18分子乙酰CoA、36分子ATP及16分子NADPH。乙酰乙酰辅酶A（B错）为酮体合成（十版生物化学P149）及胆固醇合成（十版生物化学P159）的中间产物。丙酰辅酶A（十版生物化学P148）（C错）为奇数碳脂肪酸β-氧化的中间产物。草酰乙酸（十版生物化学P114）（D错）为三羧酸循环的中间产物。葡萄糖（E错）可转化为乙酰辅酶A，再作为胆固醇合成的原料。","","N"],["1994-N94",5,"第3节 甘油三酯代谢","软脂酸合成的原料",1994,94,"B","","体内合成长链脂肪酸的主要原料是",[["A","乙酰辅酶A"],["B","乙酰乙酰辅酶A"],["C","丙酰辅酶A"],["D","草酰乙酸"],["E","葡萄糖"]],"A","体内合成长链脂肪酸的主要原料是葡萄糖（E错）代谢产生的乙酰CoA（A对）。草酰乙酸（十版生物化学P130）（D错）为糖异生的中间产物，可以作为糖异生的原料。乙酰乙酰辅酶A（B错）为酮体合成（十版生物化学P149）和胆固醇合成（十版生物化学P159）的中间产物。丙酰辅酶A（十版生物化学P148）（C错）为奇数碳原子脂肪酸β-氧化及支链氨基酸氧化分解的产物。","","N"],["1994-N95",21,"第4节 胆色素的代谢与黄疸","胆红素来源",1994,95,"B","","体内血红素代谢的终产物是",[["A","乙酰辅酶A"],["B","CO₂及H₂O"],["C","胆汁酸"],["D","铁卟啉"],["E","胆色素"]],"E","化学结构上，血红素属于铁卟啉（D错）化合物，由卟啉环和Fe²⁺螯合而成，其代谢终产物是胆色素（E对）。乙酰辅酶A（A错）是体内能源物质氧化分解的重要中间产物。CO₂及H₂O（B错）是体内能源物质氧化分解的终产物。胆汁酸（十版生物化学P472）（C错）是胆固醇的主要代谢产物。","","N"],["1994-N96",5,"第5节 胆固醇代谢","胆固醇的转化",1994,96,"B","","体内胆固醇代谢的终产物是",[["A","乙酰辅酶A"],["B","CO₂及H₂O"],["C","胆汁酸"],["D","铁卟啉"],["E","胆色素"]],"C","胆固醇的去路：①被肝转化为胆汁酸（C对），这是胆固醇的主要去路；②在肾上腺皮质、睾丸、卵巢等合成类固醇激素，包括醛固酮、皮质醇、雄激素、雌激素、孕激素等；③在皮肤被氧化为7-脱氢胆固醇，经紫外线照射转变为维生素D₃。","","N"],["1994-N119",7,"第2节 线粒体氧化体系与呼吸链","氧化呼吸链概述",1994,119,"C","","构成呼吸链的成员有",[["A","细胞色素P₄₅₀"],["B","铁硫蛋白"],["C","两者都是"],["D","两者都不是"]],"B","呼吸链又称氧化呼吸链，由位于线粒体内膜上的4种蛋白酶复合体组成，分别称之为复合体Ⅰ、Ⅱ、Ⅲ和Ⅳ，每个复合体又由多种酶蛋白和辅助因子组成，包括铁硫蛋白（B对）、细胞色素b、细胞色素c₁、细胞色素aa₃、FMN、FAD等，但不包括细胞色素P450（A错），细胞色素P450存在于微粒体中，参与类固醇激素、胆汁酸及胆色素等的生成及药物、毒物的生物转化过程。","","N"],["1994-N120",7,"第5节 其他氧化和抗氧化体系","单加氧酶",1994,120,"C","","参与生物转化的酶有",[["A","细胞色素P₄₅₀"],["B","铁硫蛋白"],["C","两者都是"],["D","两者都不是"]],"A","生物转化作用是指机体在排出有毒性的非营养物质前对他们进行代谢转变，使其水溶性提高，极性增强，易于通过胆汁或尿排出。人微粒体细胞色素P450（A对）单加氧酶催化氧分子中的一个氧原子加到底物分子上，另一个氧原子被氢（来自底物NADPH+H⁺）还原成水，参与类固醇激素、胆汁酸及胆色素等的生成及药物、毒物的生物转化过程。铁硫蛋白（十版生物化学P199）是一种递电子体，是复合体Ⅰ、Ⅱ、Ⅲ的重要组成部分，参与呼吸链的氧化过程，不参与生物转化（B错）。","","N"],["1994-N139",5,"第6节 血浆脂蛋白及其代谢","高脂血症",1994,139,"X","","通常高脂蛋白血症中，下列哪种脂蛋白可能增高",[["A","乳糜微粒"],["B","极低密度脂蛋白"],["C","高密度脂蛋白"],["D","低密度脂蛋白"]],"ABD","血浆脂质水平异常升高，超过正常范围上限称为高脂血症。由于血脂在血中以脂蛋白形式存在和运输，因此高脂血症也可认为是高脂蛋白血症。高脂蛋白血症可分为六型，其中I型乳糜微粒（A对）增高，Ⅱa型低密度脂蛋白（D对）增高，Ⅱb型低密度及极低密度脂蛋白（BD对）同时升高，Ⅳ型极低密度脂蛋白（B对）增高，Ⅴ型极低密度脂蛋白和乳糜微粒（AB对）同时增高。高密度脂蛋白被称为人体“好的脂蛋白”，它的含量增高对人体是有益的，一般不会引起任何症状，所以不包含在高脂蛋白血症中。","","N"],["1994-N140",15,"第1节 印迹法和探针技术","概述",1994,140,"X","","进行基因工程实验时，常用的技术有",[["A","分子杂交技术"],["B","DNA探针技术"],["C","质粒重组技术"],["D","基因调控技术"]],"ABC","分子杂交技术（A对）是基因工程的常用实验技术，分子杂交技术可以用来研究DNA片段在基因组中的定位、鉴定核酸分子间的序列相似性、检测特定基因在待检样品中存在与否等（八版生物化学P53）。DNA探针技术（B对）正是分子杂交技术原理的具体运用，该技术利用带有特殊可检测标记的核酸片段与待检样品的核酸片段进行分子杂交，以检测样品中是否存在特定基因序列（十版生物化学P337）。质粒重组技术（C对）是质粒为载体，以获取大量能进行自我复制的特定DNA片段为目的重组DNA技术（十版生物化学P371），该技术在基因工程实验中极为常见。基因调控技术（D错）指所有用于调节和控制基因表达的实验技术，是一个集合概念，并非某一具体基因工程实验技术名称。","","N"],["1994-N141",21,"第1节 肝在物质代谢中的作用","肝脏的主要代谢途径及联系",1994,141,"X","","狗切除肝脏后，在未死亡前，可观察到哪些物质代谢指标会有重大变化",[["A","血氨增高"],["B","血清游离胆红素增高"],["C","血酮体增高"],["D","血浆蛋白质降低"]],"ABD","肝脏是尿素合成的主要器官，所以肝脏被切除后，氨的代谢减少，血氨增高（A对）。血中的游离胆红素主要在肝内转化为结合胆红素，肝脏被切除后，血中游离胆红素增高（B对）。肝脏是酮体产生的最主要器官（十版生物化学P460），故肝脏切除后，酮体的生成减少，血中酮体的含量会降低（C错）。除γ-球蛋白外，几乎其他所有的血浆蛋白质均由肝脏合成，因此肝切除后，血浆蛋白质降低（D对）。","","N"],["1995-N1",0,"第1节 蛋白质的分子组成","氨基酸的基本结构单位",1995,1,"A","","不出现于蛋白质中的氨基酸是",[["A","半胱氨酸"],["B","胱氨酸"],["C","瓜氨酸"],["D","精氨酸"],["E","赖氨酸"]],"C","瓜氨酸（C对）不出现于蛋白质中，而是作为尿素合成的中间产物，由鸟氨酸和氨基甲酰磷酸在鸟氨酸氨基甲酰转移酶的催化下形成，以氨基酸的形式参与尿素合成（十版生物化学P182图9-8 尿素生成的鸟氨酸循环）。注：不出现于蛋白质中的氨基酸有很多（自然界中发现的氨基酸种类有300余种，但参与蛋白质合成的氨基酸只有20种），但常考的只有生物化学教材有提及的瓜氨酸、鸟氨酸和同型半胱氨酸等。","","N"],["1995-N2",2,"第2节 DNA和空间结构与功能","DNA的双螺旋结构",1995,2,"A","","DNA复制时，以5'TAGA 3'为模板，合成产物的互补结构为",[["A","5'TCTA3'"],["B","5'UCUA3'"],["C","5'ATCT3'"],["D","5'AUCU3'"],["E","5'GCGA3'"]],"A","在DNA内部，碱基之间的配对方式为A-T和C-G。由于DNA双链两条链之间呈反向平行排列，故5’TAGA3’的互补结构为3’ATCT5’，即5’TCTA3’（A对）。","","N"],["1995-N3",5,"第5节 胆固醇代谢","胆固醇的合成过程",1995,3,"A","","合成胆固醇的限速酶是",[["A","HMG-CoA合成酶"],["B","HMG-CoA还原酶"],["C","HMG-CoA裂解酶"],["D","甲羟戊酸激酶"],["E","鲨烯环氧酶"]],"B","胆固醇生物合成时的限速酶（关键酶）是HMG-CoA还原酶（B对）。HMG-CoA合成酶（亦为酮体合成的非限速酶）（A错）、甲羟戊酸激酶（D错）和鲨烯环氧酶（E错）均为胆固醇生物合成时的非限速酶。HMG-CoA裂解酶（C错）为酮体合成（十版生物化学P149）的非限速酶。","","N"],["1995-N4",14,"第2节 原核基因表达调控","操纵子",1995,4,"A","","操纵子的基因表达调节系统属于",[["A","复制水平调节"],["B","转录水平调节"],["C","翻译水平调节"],["D","翻译后水平调节"],["E","逆转录水平调节"]],"B","操纵子是原核基因转录调控的基本单位，其基因表达调节系统属于转录水平的调节（B对）。","","N"],["1995-N5",7,"第2节 线粒体氧化体系与呼吸链","苹果酸-天冬氨酸穿梭",1995,5,"A","","苹果酸穿梭作用的生理意义在于",[["A","将草酰乙酸带入线粒体彻底氧化"],["B","维持线粒体内外有机酸的平衡"],["C","进行谷氨酸、草酰乙酸转氨基作用"],["D","为三羧酸循环提供足够的草酰乙酸"],["E","将胞液中NADH+H⁺的2H带入线粒体内"]],"E","苹果酸穿梭又称苹果酸-天冬氨酸穿梭，其生理意义在于将胞液中NADH+H⁺的2H带入线粒体内（E对）：胞液中生成的NADH+H⁺不能自由通过线粒体内膜，而NADH+H⁺只有进入线粒体后才能彻底氧化生成水和ATP，通过苹果酸穿梭作用将胞液中的NADH+H⁺的两个H⁺交给草酰乙酸生成苹果酸，苹果酸可自由通过线粒体内膜，进入线粒体后，苹果酸再转变成草酰乙酸，生成NADH+H⁺。","","N"],["1995-N6",9,"第2节 代谢的相互联系","糖、脂质和蛋白质代谢联系的概述",1995,6,"A","","糖与脂肪酸及氨基酸三者代谢的交叉点是",[["A","磷酸烯醇式丙酮酸"],["B","丙酮酸"],["C","延胡索酸"],["D","琥珀酸"],["E","乙酰CoA"]],"E","糖与脂肪酸及氨基酸三者代谢的交叉点是乙酰CoA（E对）：在糖代谢中，乙酰CoA是丙酮酸氧化脱羧的产物；在脂代谢中，乙酰CoA既是脂酸β-氧化的产物，又是软脂酸、胆固醇、酮体等合成的原料；在氨基酸代谢中，氨基酸可以转变成柠檬酸循环或糖酵解途径中的各中间产物，最终生成乙酰CoA。磷酸烯醇式丙酮酸（A错）和丙酮酸（B错）分别为糖酵解途径的中间产物和产物，延胡索酸（C错）和琥珀酸（D错）为三羧酸循环的中间产物，以上四种物质分别为糖与部分氨基酸的代谢交叉点（参见P210 图 10-1），但均与脂肪酸代谢无关。","","N"],["1995-N7",1,"第4节 酶的调节","别构调节",1995,7,"A","","下列哪项不是酶的别（变）构调节的特点",[["A","反应动力学遵守米氏方程"],["B","限速酶多受别构调节"],["C","变构剂与酶的结合是可逆的"],["D","酶活性可因与变构剂结合而促进或抑制"],["E","别构酶常由多亚基组成"]],"A","体内一些代谢物可与某些酶的活性中心外的某个部位非共价可逆（C对）结合，引起酶的构象改变，从而改变酶的活性，酶的这种调节方式称为酶的别构调节，也称为变构调节。可以受别构调节的酶称为别构酶，常由多亚基组成（E对），由于多亚基之间存在正协同效应或负协同效应，因此其反应动力学不遵守米氏方程（A错，为本题正确答案）。物质代谢过程中各限速酶（关键酶）多受别构调节（B对），酶活性可因与变构剂结合而促进或抑制（D对）。","","N"],["1995-N8",13,"第5节 蛋白质合成的干扰和抑制","影响成肽的抗生素",1995,8,"A","","氯霉素的抗菌作用是由于抑制了细菌的",[["A","细胞色素氧化酶"],["B","嘌呤核苷酸代谢"],["C","二氢叶酸还原酶"],["D","核蛋白体上的转肽酶"],["E","基因表达"]],"D","氯霉素的抗菌作用机制：氯霉素可结合核糖体（核蛋白体）的50S亚基，抑制细菌蛋白质合成过程中由转肽酶（D对）催化的肽键形成。","","N"],["1995-N9",4,"第3节 糖的有氧氧化","三羧酸循环的过程",1995,9,"A","","指出下列化学结构式的生化名称HOOC-CH₂-CH₂-CO-COOH",[["A","草酰乙酸"],["B","柠檬酸"],["C","谷氨酸"],["D","α-酮戊二酸"],["E","苹果酸"]],"D","化学结构式HOOC-CH₂-CH₂-CO-COOH中含五个碳原子（戊）、两个羧酸基、一个α酮基，其生化名称为α-酮戊二酸（D对）。","","N"],["1995-N10",23,"第1节 脑的生物化学","葡萄糖是脑的主要能量来源",1995,10,"A","","静息状态时，体内耗氧量最多的器官是",[["A","肝"],["B","心"],["C","脑"],["D","骨骼肌"],["E","红细胞"]],"C","人脑重量仅占体重2%，但其耗氧量占静息时全身耗氧总量的20%～25%，是静息状态下单位重量组织耗氧量最大的器官（C对）。肝（七版生物化学P409）（A错）和心（九版生理学P141）（B错）均为代谢活跃，血供丰富的器官，静息时耗氧量均较大。骨骼肌（D错）运动状态下耗氧量较大，但静息时耗氧量较小。红细胞（E错）可运输氧气，但成熟的红细胞没有线粒体，只能依赖糖的无氧氧化提供能量（十版生物化学P488），因此红细胞本身的耗氧量极少。","","N"],["1995-N11",21,"第4节 胆色素的代谢与黄疸","胆素原进入体循环",1995,11,"A","","正常人尿中的主要色素是",[["A","胆红素"],["B","尿胆素"],["C","胆绿素"],["D","胆汁酸"],["E","血红素"]],"B","在正常人体内，结合胆红素（A错）随胆汁进入肠道后，可在肠道细菌的作用下还原生成胆素原。大部分胆素原随粪便排出体外，小部分胆素原可被肠黏膜细胞重吸收后经门静脉入肝，进入门静脉的胆素原90%以原形随胆汁排入肠腔，形成胆素原的肠肝循环，剩余的10%则可进入体循环，经肾小球滤过后随尿排出，称为尿胆素原，尿胆素原与空气接触后被氧化成尿胆素（B对），此为尿中的主要色素。胆绿素（十版生物化学P474）（C错）是胆红素合成过程中的中间产物。胆汁酸（十版生物化学P472）（D错）是体内胆固醇最主要的代谢产物。血红素（十版生物化学P485）（E错）是血红蛋白的辅基，可代谢生成胆色素。","","N"],["1995-N12",5,"第3节 甘油三酯代谢","酮体的生成的意义",1995,12,"A","","肝脏在脂肪代谢中产生过多酮体主要由于",[["A","肝功能不好"],["B","肝中脂肪代谢紊乱"],["C","酮体是病理性代谢产物"],["D","脂肪摄食过多"],["E","糖的供应不足"]],"E","正常情况下，血中酮体含量很少，但在饥饿、高脂低糖膳食及糖尿病时，由于糖的供应不足（E对），脂肪动员加强，脂肪酸氧化增多，酮体生成过多，超过肝外组织利用酮体的能力，可以引起血中酮体升高。酮体主要由肝脏生成，肝功能不好的患者酮体生成一般会减少（A错）。酮体是肝向肝外组织输出能量的重要形式（十版生物化学P149），不属于病理性代谢产物（C错）。肝中脂肪代谢紊乱（B错）、脂肪摄食过多（D错）多导致血脂升高。","","N"],["1995-N93",5,"第6节 血浆脂蛋白及其代谢","极低密度脂蛋白的功能和代谢途径",1995,93,"B","","运输内源性甘油三酯的主要脂蛋白是",[["A","乳糜微粒"],["B","极低密度脂蛋白"],["C","低密度脂蛋白"],["D","高密度脂蛋白"],["E","极高密度脂蛋白"]],"B","运输内源性甘油三酯的主要脂蛋白是极低密度脂蛋白（B对）。乳糜微粒（A错）主要转运外源性甘油三酯及胆固醇。低密度脂蛋白（C错）主要转运内源性胆固醇。高密度脂蛋白（D错）主要逆向转运胆固醇。极高密度脂蛋白（E错）在生物化学教材中未提及，其主要功能为转运游离脂肪酸。","","N"],["1995-N94",5,"第6节 血浆脂蛋白及其代谢","高密度脂蛋白的功能和代谢途径",1995,94,"B","","有助于防止动脉粥样硬化的脂蛋白是",[["A","乳糜微粒"],["B","极低密度脂蛋白"],["C","低密度脂蛋白"],["D","高密度脂蛋白"],["E","极高密度脂蛋白"]],"D","高密度脂蛋白（HDL）主要逆向转运胆固醇，有助于预防动脉粥样硬化（D对），其机制主要为：HDL可将肝外组织，包括将动脉壁、巨噬细胞等组织细胞的胆固醇转运至肝，降低了动脉壁胆固醇含量，同时还具有抑制LDL氧化的作用等。乳糜微粒（CM）（A错）主要转运外源性甘油三酯及胆固醇（十版生物化学P164），极低密度脂蛋白（VLDL）（B错）主要转运内源性甘油三酯（十版生物化学P165），低密度脂蛋白（LDL）（C错）主要转运内源性胆固醇（十版生物化学P165），极高密度脂蛋白（E错）在生物化学教材中未提及，其主要转运游离脂肪酸。以上四者均可使体内胆固醇、甘油三酯或脂肪酸（饱和脂肪酸）增加，导致动脉粥样硬化的形成。","","N"],["1995-N95",6,"第2节 氨基酸的一般代谢","氨基转移酶的分布、种类及作用",1995,95,"B","","体内最广泛存在，活性最高的转氨酶是将氨基转移给",[["A","丙酮酸"],["B","谷氨酸"],["C","α-酮戊二酸"],["D","草酰乙酸"],["E","甘氨酸"]],"C","体内存在着多种转氨酶，不同氨基酸与α-酮酸之间的转氨基作用只能由专一的转氨酶催化。在各种转氨酶中，以L-谷氨酸和α-酮酸的转氨酶最为重要（十版生物化学P177）。正常时，转氨酶主要存在于细胞内，血清中活性很低，肝组织中ALT（丙氨酸转氨酶）的活性最高，心肌组织中AST（天冬氨酸转氨酶）的活性最高，因此体内最广泛存在，活性最高的转氨酶应该是ALT或AST，而这两种转氨酶都是将氨基转移给α-酮戊二酸（C对）。","","N"],["1995-N96",6,"第4节 个别氨基酸的代谢","一碳单位的来源及转换",1995,96,"B","","代谢时能直接生成一碳单位的化合物是",[["A","丙酮酸"],["B","谷氨酸"],["C","α-酮戊二酸"],["D","草酰乙酸"],["E","甘氨酸"]],"E","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的基团，包括甲基、甲烯基、甲炔基、甲酰基及亚氨甲基等。可直接生成一碳单位的氨基酸包括丝氨酸、甘氨酸（E对）、组氨酸和色氨酸，记忆的口诀为施（丝氨酸）舍（色氨酸）一根竹（组氨酸）竿（甘氨酸）。","","N"],["1995-N119",4,"第8节 血糖及其调节","胰岛素",1995,119,"C","","胰岛素缺乏所致的糖尿病，主要表现为",[["A","促糖异生"],["B","酮体生成增多"],["C","两者都是"],["D","两者都不是"]],"C","胰岛素缺乏时，糖利用障碍，血糖升高，大量糖经肾排出，同时机体动用非糖物质异生为糖，糖异生增强（A对）。由于糖利用障碍，脂肪酸氧化分解增强，生成乙酰CoA增加，糖代谢障碍又使草酰乙酸减少，乙酰CoA进入柠檬酸循环受阻，导致乙酰CoA大量堆积，酮体生成增多（B对）。本题AB均对，正确答案为C。","","N"],["1995-N120",9,"第2节 代谢的相互联系","物质代谢与能量代谢的关联",1995,120,"C","","饥饿时的主要表现为",[["A","促糖异生"],["B","酮体生成增多"],["C","两者都是"],["D","两者都不是"]],"C","人体血糖必须维持一定的浓度才能维持重要器官的正常功能。饥饿状态下，血糖浓度降低，机体进行了一系列调节：一方面，机体动用非糖物质异生为糖，糖异生增强（A对）；另一方面，胰高血糖素等脂解激素分泌增多，脂肪动员增强，脂肪酸β-氧化及酮体生成增多（B对），减少葡萄糖的利用，从而维持血糖的正常水平。本题AB均对，正确答案为C。","","N"],["1995-N121",17,"第2节 细胞内信号转导分子","第二信使的概述",1995,121,"C","","细胞内的第二信使物质是",[["A","cAMP"],["B","Ca²⁺"],["C","两者都是"],["D","两者都不是"]],"C","第二信使是指外源信息在细胞内的信号转导分子，常见的第二信使包括：Ca²⁺（B 对）、环腺苷 酸（cAMP）（A 对）、环鸟苷酸（cGMP）、环腺苷二磷酸核糖、甘油二酯（DAG）、三磷酸肌醇（IP₃）、花生四烯酸、神经酰胺、一氧化氮和一氧化碳等。本题 AB 均对，正确答案为 C。","","N"],["1995-N122",17,"第3节 细胞受体介导的细胞内信号转导","cAMP-PKA通路",1995,122,"C","","肾上腺素作用于其膜受体时所产生的化学物质是",[["A","cAMP"],["B","Ca²⁺"],["C","两者都是"],["D","两者都不是"]],"A","肾上腺素可作用于其相应的膜受体，激活腺苷酸环化酶，使cAMP（A对）增加，进而改变PKA的活化状态，调控下游相关反应。PKA可通过磷酸化作用于Ca²⁺离子通道，调节Ca²⁺的浓度和分布改变（十版生物化学P396），但Ca²⁺不是肾上腺素直接作用于膜受体产生的（B错）。","","N"],["1995-N139",0,"第4节 蛋白质的理化性质","变性",1995,139,"X","","酶变性时的表现",[["A","溶解度降低"],["B","易受蛋白酶水解"],["C","酶活性丧失"],["D","紫外线（280nm）吸收增强"]],"ABCD","绝大多数酶属于蛋白质（极少数是核酸），其变性后的表现同蛋白质变性。蛋白质的变性是指某些物理和化学因素作用下，其特定的空间构象被破坏，理化性质及生物学活性丧失。蛋白质变性后：溶解度降低（A对），黏度增加，结晶能力消失，生物学活性丧失（C对），易被蛋白酶水解（B对）。变性后由于空间结构松散，包含在内部的芳香族基团暴露，其吸光度可能发生变化，但对280nm的紫外线吸收未必增强（D选项存在争议）。","","N"],["1995-N140",16,"第2节 重组DNA技术","常用工具酶",1995,140,"X","","从带有遗传信息的mRNA构建成DNA重组体，要利用",[["A","质粒"],["B","限制性核酸内切酶"],["C","DNA连接酶"],["D","反转录酶"]],"ABCD","从带有遗传信息的mRNA构建成DNA重组体，需要通过以下步骤：①目的DNA的分离获取：利用反转录酶（D对）将mRNA反转录成cDNA，再以cDNA为模板，利用特异性引物，通过PCR反应获取大量目的DNA片段；②载体的选择与构建：选择、构建适合用来运载目的DNA的基因载体，最常用的基因载体为质粒载体（A对）；③目的DNA与载体连接：利用限制性核酸内切酶（RE）（B对），对目的DNA和基因载体进行切割，形成可以互补配对的黏性末端，再利用DNA连接酶（C对）对黏性末端进行连接，至此，DNA重组体初步构建完成。在实际的科研工作中，DNA重组体构建完成后还需要转入受体细胞，并对其进行筛选和鉴定。","","N"],["1995-N142",0,"第2节 蛋白质的分子结构","蛋白质的二级结构",1995,142,"X","","蛋白质二级结构中存在的构象",[["A","α-螺旋"],["B","β-螺旋"],["C","α-转角"],["D","β-转角"]],"AD","二级结构是指蛋白质分子中某一段肽链的局部空间结构，也就是该段肽链的主链骨架C原子的相对空间位置，并不涉及氨基酸残基侧链的构象。二级结构包括α-螺旋（A对）、β-折叠、β-转角（D对）和Ω环（Ω环为九版后教材更新内容，替换了八版教材的无规卷曲，但是无规卷曲也是事实存在的）。不存在β-螺旋（B错）和α-转角（C错）的构象类型。","","N"],["1996-N19",5,"第4节 磷脂代谢","甘油二酯合成途径",1996,19,"A","","合成卵磷脂时所需的活性胆碱是",[["A","ADP-胆碱"],["B","GDP-胆碱"],["C","TDP-胆碱"],["D","UDP-胆碱"],["E","CDP-胆碱"]],"E","卵磷脂即磷脂酰胆碱，通过甘油二酯途径合成：胆碱被活化成CDP-胆碱（E对）后，与甘油二酯缩合，生成磷脂酰胆碱（卵磷脂）。","","N"],["1996-N20",5,"第5节 胆固醇代谢","胆固醇的合成过程",1996,20,"A","","细胞内催化脂酰基转移到胆固醇生成胆固醇酯的酶是",[["A","ACAT"],["B","LCAT"],["C","磷脂酶C"],["D","磷脂酶D"],["E","肉碱脂酰转移酶"]],"A","细胞内胆固醇酯与血浆中胆固醇酯的合成途径不同。细胞内胆固醇酯的合成：脂酰CoA和胆固醇在ACAT（脂酰CoA胆固醇脂酰转移酶）（A对）的作用下生成胆固醇酯。血浆中胆固醇酯的合成：卵磷脂和胆固醇在LCAT（卵磷脂胆固醇酯酰转移酶）（B错）的作用下生成胆固醇酯和溶血卵磷脂。磷脂酶C（C错）和磷脂酶D（D错）为参与甘油磷脂降解（十版生物化学P158）的酶。肉碱脂酰转移酶（十版生物化学P146）（E错）为参与脂肪酸β-氧化的酶。","","N"],["1996-N21",5,"第3节 甘油三酯代谢","脂肪酸的氧化方式",1996,21,"A","","下列脂肪降解和氧化产物可以转化为糖的有",[["A","硬脂酸"],["B","乙酰CoA"],["C","酮体"],["D","丙酰CoA"],["E","油酸"]],"D","由于丙酮酸生成乙酰CoA的反应（由丙酮酸脱氢酶复合体催化）是不可逆的，所以乙酰CoA不能逆行生成丙酮酸（B错），且所有代谢产物为乙酰CoA的物质包括硬脂酸（A错），油酸（E错）及酮体（C错）都不能异生为糖。丙酰CoA经β-羧化酶及异构酶作用，可转变为琥珀酰CoA，琥珀酰CoA可经柠檬酸循环转变为草酰乙酸，草酰乙酸可被彻底氧化（草酰乙酸→磷酸烯醇式丙酮酸→丙酮酸→乙酰CoA，乙酰CoA再进入柠檬酸循环被彻底氧化），也可经糖异生途径转化为糖（D对）。","","N"],["1996-N22",2,"第3节 RNA和空间结构与功能","tRNA的结构及功能",1996,22,"A","","稀有核苷酸存在于下列哪一类核酸中",[["A","rRNA"],["B","mRNA"],["C","tRNA"],["D","核仁DNA"],["E","线粒体DNA"]],"C","稀有碱基是指除A、C、G、U外的一些碱基，包括双氢尿嘧啶（DHU）、假尿嘧啶核苷（ψ）和甲基化的嘌呤（m⁷G，m⁷A）等。tRNA分子中含有多种稀有碱基（C对），约占所有碱基的10%-20%，它们均是转录后修饰而成的。需要注意的是稀有核苷酸只是多存在于tRNA分子中，在mRNA等其他分子中也可以存在。","","N"],["1996-N24",5,"第3节 甘油三酯代谢","软脂酸合成的过程",1996,24,"A","","胞浆中合成脂肪酸的限速酶是",[["A","β-酮脂酰合成酶"],["B","硫解酶"],["C","乙酰CoA羧化酶"],["D","脂酰转移酶"],["E","β-酮脂酰还原酶"]],"C","乙酰CoA转化成丙二酸单酰CoA是脂肪酸合成的第一步反应，催化此反应的乙酰CoA羧化酶是脂肪酸合成的限速酶（C对）。β酮脂酰合成酶（A错）、β-酮脂酰还原酶（E错）均参与脂肪酸的合成，但为非限速酶。硫解酶（乙酰基转移酶）（B错）参与脂肪酸的β氧化。脂酰转移酶（D错）即脂酰CoA转移酶，为参与甘油三酯合成（十版生物化学P150）或磷脂合成的限速酶。","","N"],["1996-N25",6,"第4节 个别氨基酸的代谢","半胱氨酸转变为牛磺酸",1996,25,"A","","牛磺酸是由下列哪种氨基酸代谢而来",[["A","蛋氨酸"],["B","半胱氨酸"],["C","苏氨酸"],["D","甘氨酸"],["E","谷氨酸"]],"B","半胱氨酸代谢可产生多种重要的生理活性物质：①转变为含有二硫键的胱氨酸，二硫键对于维持蛋白质空间构象稳定性具有重要作用；②转变为牛磺酸（B对），牛磺酸是结合胆汁酸的组成成分之一；③生成活性硫酸根PAPS；④参与谷胱甘肽的合成，谷胱甘肽是体内重要的还原保护剂。","","N"],["1996-N26",4,"第3节 糖的有氧氧化","丙酮酸氧化脱羧",1996,26,"A","","丙酮酸脱氢酶系中不含哪一种辅酶",[["A","硫胺素焦磷酸酯"],["B","硫辛酸"],["C","NAD⁺"],["D","FAD"],["E","磷酸吡哆醛"]],"E","丙酮酸脱氢酶复合体是葡萄糖有氧氧化的关键酶之一，催化丙酮酸脱氢脱羧生成乙酰CoA。参与反应的辅酶有焦磷酸硫胺素（TPP）（A对），硫辛酸（B对），FAD（D对），NAD⁺（C对）和CoA，可记忆为赴美（辅酶A）交流（TPP，焦磷酸硫胺素）时留心（硫辛酸）谎（FAD，黄素腺嘌呤二核苷酸）言（NAD⁺，烟酰胺腺嘌呤二核苷酸）（亦可记忆为SPA，即名称中带有S、P、A字母的，注：硫的化学符号为S）。磷酸吡哆醛（十版生物化学P100）（E错，为本题正确答案）是体内百余种酶的辅酶，参与氨基酸脱氨与转氨作用、鸟氨酸循环、血红素的合成和糖原分解等，在代谢中发挥着重要作用。","","N"],["1996-N27",4,"第6节 糖异生","糖异生的过程",1996,27,"A","","在体内不能直接由草酰乙酸转变而来的化合物是",[["A","天门冬氨酸"],["B","磷酸烯醇式丙酮酸"],["C","苹果酸"],["D","柠檬酸"],["E","乙酰乙酸"]],"E","草酰乙酸不能直接变成乙酰乙酸（酮体），后者是由脂肪酸β-氧化产生的乙酰CoA合成而来（E错，为本题正确答案）。草酰乙酸是天冬氨酸的α酮酸，草酰乙酸经氨基化可生成天冬氨酸（A对），此反应可发生糖异生过程中草酰乙酸以天冬氨酸的形式转运出线粒体的过程，还可发生在嘌呤核苷酸循环中其他氨基酸将氨基转移给天冬氨酸的过程。草酰乙酸由磷酸烯醇式丙酮酸羧激酶催化生成磷酸烯醇式丙酮酸（B对）是糖异生过程中的关健反应之一。草酰乙酸可以在苹果酸脱氢酶的催化下生成苹果酸，该反应见于草酰乙酸经苹果酸由线粒体转运至胞质的过程，还见于三羧酸循环最后一步的逆反应（C对）。草酰乙酸与乙酰CoA在柠檬酸合酶的作用下可以生成柠檬酸，该反应是三羧酸循环的第一步（D对）。","","N"],["1996-N28",5,"第3节 甘油三酯代谢","脂肪酸氧化产能",1996,28,"A","","1克软脂酸（相对分子质量256）较1克葡萄糖（相对分子质量180）彻底氧化所生成的ATP高多少倍",[["A","2"],["B","2.5"],["C","3"],["D","3.5"],["E","5"]],"B","1分子软脂酸共有16个碳原子，需经7次β-氧化，生成7分子FADH₂、7分子NADH及8分子乙酰CoA，FADH₂、NADH经电子传递链分别产生1.5个、2.5个ATP，乙酰CoA进入三羧酸循环彻底氧化分解产生10个ATP。因此1分子软脂酸彻底氧化共生成（7×1.5）+（7×2.5）+（8×10）=108分子ATP，考虑脂肪酸活化消耗2个高能磷酸键，相当于2分子ATP，1分子软脂酸彻底氧化净生成106分子ATP，即1mol（1mol=6.02×10²³个分子）软脂酸彻底氧化可净生成106mol ATP，则1克软脂酸可以生成1/256×106=106/256mol ATP。1分子葡萄糖彻底氧化分解产生30个或32个ATP，即1mol葡萄糖彻底氧化分解产生30mol或32mol ATP，则1克葡萄糖彻底氧化分解产生30/180mol或32/180mol ATP。进一步可计算出1克软脂酸彻底氧化所生成ATP量是1克葡萄糖彻底氧化所生成ATP量的2.5倍（B对）或2.33倍（而非高出2.5倍或2.33倍，原题表述不严谨）。","","N"],["1996-N29",8,"第3节 嘧啶核苷酸的合成与分解代谢","dTMP的生成",1996,29,"A","","dTMP合成的直接前体是",[["A","UDP"],["B","dUMP"],["C","UMP"],["D","dUDP"],["E","dCMP"]],"B","脱氧核糖核苷酸的生成主要是在二磷酸核苷水平进行的，即NDP→dNDP（N代表A、G、U、C等碱基）。但脱氧胸腺嘧啶核苷酸的合成是在一磷酸核苷水平进行的：dTMP是由dUMP（B对）经甲基化而生成。","","N"],["1996-N30",11,"第2节 DNA复制的酶学和拓扑学","DNA复制的概述",1996,30,"A","","DNA复制时下列哪一种酶是不需要的",[["A","DDDP"],["B","DDRP"],["C","RDDP"],["D","连接酶"],["E","拓扑异构酶"]],"C","DNA复制是在多种酶催化下的核苷酸聚合过程：首先解螺旋酶解开DNA双链，单链DNA结合蛋白稳定已解开的单链以及拓扑异构酶（E对）理顺DNA链，随后引物酶（依赖DNA的RNA聚合酶，DNA Dependent RNA Polymerase，DDRP）（B对）催化引物RNA链的合成，在引物的引导下，DNA聚合酶（依赖DNA的DNA聚合酶，DNA Dependent DNA Polymerase，DDDP）（A对）促进DNA链沿5’→3’方向延长，在复制终止后，由RNA酶水解RNA引物，DNA pol I填补空隙，最终DNA连接酶（D对）填补缺口。复制过程中不需要逆转录酶（依赖RNA的DNA聚合酶，RNA Dependent DNA Polymerase，RDDP）（C错，为本题正确答案）参与。","","N"],["1996-N31",4,"第2节 糖的无氧氧化","磷酸果糖激酶-1",1996,31,"A","","6-磷酸果糖激酶-1的变构激活剂是",[["A","1，6-二磷酸果糖"],["B","2，6-二磷酸果糖"],["C","ATP"],["D","GTP"],["E","柠檬酸"]],"AB","6-磷酸果糖激酶-1是调节糖酵解流量最重要的一种酶，它是一个四聚体，受多种别构（变构）效应剂的影响，其别构激活剂包括AMP、ADP、果糖-1，6-二磷酸（A对）和果糖-2，6-二磷酸（B对）等，其中别构激活作用最强的是果糖-2，6-二磷酸，故当年给出的参考答案为B。ATP（C错）和柠檬酸（E错）为6-磷酸果糖激酶-1的别构抑制剂。GTP（D错）为L-谷氨酸脱氢酶的别构抑制剂（十版生物化学P178）。本题正确答案为AB，原答案为B。","","N"],["1996-N32",7,"第3节 氧化磷酸化与ATP的生成","根据P_O比值确定氧化磷酸化耦联部位",1996,32,"A","","下列哪种物质脱下的一对氢经呼吸链传递后P/O比约为3",[["A","β-羟丁酸"],["B","琥珀酸"],["C","α-磷酸甘油"],["D","抗坏血酸"],["E","脂酰CoA"]],"A","β-羟丁酸经β-羟丁酸脱氢酶催化脱氢，脱下的氢被NAD⁺接受生成NADH，通过NADH氧化呼吸链传递，P/O比值约为2.5（六版及之前教材为3）（A对）。琥珀酸（B错）、α-磷酸甘油（C错）和脂酰CoA（E错）脱下的一对氢被FAD接受，通过琥珀酸氧化呼吸链传递，P/O比值均为1.5（六版及之前教材为2）。抗坏血酸（D错）脱下的氢直接通过细胞色素c传递，P/O比值约为1。","","N"],["1996-N99",12,"第3节 真核生物mRNA的转录、加工和降解","不同RNA聚合酶催化不同RNA的合成",1996,99,"B","","RNA聚合酶Ⅱ催化生成的产物是",[["A","mRNA"],["B","tRNA及5S rRNA"],["C","18S，28S，5.8S及5S rRNA"],["D","18S，28S及5.8S rRNA"],["E","18S，28S rRNA"]],"A","真核生物主要有三种不同的 RNA 聚合酶，分别为 RNA 聚合酶Ⅰ、RNA 聚合酶Ⅱ和RNA 聚合酶Ⅲ（九版后教材新提及了植物中还存在RNA 聚合酶Ⅳ和RNA 聚合酶Ⅴ）。RNA聚合酶Ⅰ催化生成的产物为rRNA的前体45S rRNA，45S rRNA再加工成28S、5.8S及18S rRNA（CDE错）；RNA聚合酶Ⅱ催化生成的产物为mRNA前体hnRNA（A对）、lncRNA、piRNA和miRNA；RNA聚合酶Ⅲ催化生成的产物为tRNA，5S rRNA和snRNA（B错）。","","N"],["1996-N100",12,"第3节 真核生物mRNA的转录、加工和降解","不同RNA聚合酶催化不同RNA的合成",1996,100,"B","","RNA聚合酶Ⅲ催化生成的产物是",[["A","mRNA"],["B","tRNA及5S rRNA"],["C","18S，28S，5.8S及5S rRNA"],["D","18S，28S及5.8S rRNA"],["E","18S，28SrRNA"]],"B","真核生物主要有三种不同的 RNA 聚合酶，分别为 RNA 聚合酶Ⅰ、RNA 聚合酶Ⅱ和RNA 聚合酶Ⅲ（九版后教材新提及了植物中还存在RNA 聚合酶Ⅳ和RNA 聚合酶Ⅴ）。RNA聚合酶Ⅰ催化生成的产物为rRNA的前体45S rRNA，45S rRNA再加工成28S、5.8S及18S rRNA（CDE错）；RNA聚合酶Ⅱ催化生成的产物为mRNA前体hnRNA（A错）、lncRNA、piRNA和miRNA；RNA聚合酶Ⅲ催化生成的产物为tRNA，5S rRNA和snRNA（记忆为3个三：three→t，三五牌香烟→5，san→sn）（B对）。","","N"],["1996-N121",1,"第3节 酶促反应动力学","三种可逆性抑制的比较",1996,121,"C","","其Vmax较无抑制剂时减小",[["A","非竞争性抑制"],["B","反竞争性抑制"],["C","二者都是"],["D","二者都不是"]],"C","可逆性抑制剂对酶的抑制作用可以分为三种：竞争性抑制、非竞争性抑制和反竞争性抑制。竞争性抑制时Km值增大，Vmax不变，非竞争性抑制时Km不变，Vmax变小（A对），反竞争性抑制时Km值和Vmax均变小（B对）。本题AB均对，正确答案为C。","","N"],["1996-N122",1,"第3节 酶促反应动力学","三种可逆性抑制的比较",1996,122,"C","","其Km值较无抑制剂时减小",[["A","非竞争性抑制"],["B","反竞争性抑制"],["C","二者都是"],["D","二者都不是"]],"B","可逆性抑制剂对酶的抑制作用可以分为三种：竞争性抑制、非竞争性抑制和反竞争性抑制。竞争性抑制时Km值增大，Vmax不变，非竞争性抑制时Km不变（A错），Vmax变小，反竞争性抑制时Km值和Vmax均变小（B对）。","","N"],["1996-N123",4,"第5节 糖原的合成与分解","酶促磷酸化修饰的反向调节",1996,123,"C","","磷酸化时活性增高",[["A","糖原合成酶"],["B","糖原磷酸化酶"],["C","二者都是"],["D","二者都不是"]],"B","糖原合酶与糖原磷酸化酶分别是糖原合成和糖原分解的关键酶，其酶的活性都受到磷酸化和去磷酸化的共价修饰调节。两种酶磷酸化和去磷酸化的方式相似，但结果却相反：糖原磷酸化酶磷酸化时活性增高（B对），糖原合酶磷酸化时却丧失活性（A错）。","","N"],["1996-N124",4,"第5节 糖原的合成与分解","酶促磷酸化修饰的反向调节",1996,124,"C","","磷酸化时丧失活性",[["A","糖原合成酶"],["B","糖原磷酸化酶"],["C","二者都是"],["D","二者都不是"]],"A","糖原合酶与糖原磷酸化酶分别是糖原合成和糖原分解的关键酶，其酶的活性都受到磷酸化和去磷酸化的共价修饰调节。两种酶磷酸化和去磷酸化的方式相似，但结果却相反：糖原磷酸化酶磷酸化时活性增高（B错），糖原合酶磷酸化时却丧失活性（A对）。","","N"],["1996-N143",21,"第3节 胆汁与胆汁酸的代谢","胆汁酸的分类",1996,143,"X","","属于次级胆汁酸的有",[["A","7-脱氧胆酸"],["B","牛磺胆酸"],["C","石胆酸"],["D","鹅脱氧胆酸"]],"AC","胆汁酸按其来源可分为初级胆汁酸和次级胆汁酸。其中初级胆汁酸是指在肝细胞内以胆固醇为原料直接合成的胆汁酸，包括胆酸、鹅脱氧胆酸（D错）及其与甘氨酸或牛磺酸（B错）的结合产物。次级胆汁酸是指初级胆汁酸在肠细菌作用下，第7位α羟基脱氧生成的胆汁酸，包括脱氧胆酸（A对）和石胆酸（C对）及其与甘氨酸或牛磺酸的结合产物。","","N"],["1996-N144",2,"第1节 核酸的化学组成及其一级结构","核苷酸",1996,144,"X","","下列哪些辅酶含腺嘌呤",[["A","NAD⁺"],["B","FAD"],["C","辅酶A"],["D","FMN"]],"ABC","NAD⁺（A对）为烟酰胺（N）腺嘌呤（A）二核苷酸（D），FAD（B对）为黄素（F）腺嘌呤（A）二核苷酸（D），辅酶A（C对）由泛酸、腺嘌呤（A）、核糖核酸、磷酸等组成，三者均含腺嘌呤（A）。FMN为黄素（F）单核苷酸（MN），不含腺嘌呤（A）（D错）。","","N"],["1996-N145",7,"第2节 线粒体氧化体系与呼吸链","黄素核苷酸类化合物",1996,145,"X","","同时传递电子和质子（H⁺）的辅酶有",[["A","辅酶Q"],["B","铁硫蛋白"],["C","FMN"],["D","细胞色素aa₃"]],"AC","能够传递氢的酶蛋白或辅助因子称为递氢体，能够传递电子的则称为递电子体。由于递氢的过程也传递电子，因此递氢体都是递电子体，但递电子体并不都是递氢体。既是递电子体，又是递氢体的包括NAD⁺、NADP⁺、FAD、辅酶Q（A对）和FMN（C对）等。单纯递电子体包括铁硫蛋白（B错）和细胞色素（D错）。","","N"],["1996-N146",6,"第4节 个别氨基酸的代谢","甲硫氨酸循环",1996,146,"X","","S-腺苷蛋氨酸是合成下列那些物质所需之原料",[["A","肾上腺素"],["B","肌酸"],["C","磷脂酰胆碱"],["D","肉毒碱"]],"ABCD","S-腺苷蛋氨酸（SAM）为甲硫氨酸的活性形式，可以为体内约50余种物质提供甲基。肾上腺素（十版生物化学P188）（A对）、肌酸（B对）、磷脂酰胆碱（乙醇胺从SAM获得3个甲基生成胆碱）（C对）、肉毒碱（D对）的合成均需要S-腺苷蛋氨酸（十版生物化学P188）提供甲基。","","N"],["1997-N19",0,"第1节 蛋白质的分子组成","氨基酸的分类",1997,19,"A","","含有两个羧基的氨基酸是",[["A","谷氨酸"],["B","丝氨酸"],["C","酪氨酸"],["D","赖氨酸"],["E","苏氨酸"]],"A","含有两个羧基的氨基酸有天冬氨酸和谷氨酸（A对），二者均为酸性氨基酸，可记忆为三（酸）伏（谷氨酸）天（天冬氨酸）。","","N"],["1997-N20",2,"第1节 核酸的化学组成及其一级结构","核酸的一级结构",1997,20,"A","","核酸中核苷酸之间的连接方式是",[["A","2＇，3＇-磷酸二酯键"],["B","3＇，5＇-磷酸二酯键"],["C","2＇，5＇-磷酸二酯键"],["D","1＇，5＇-糖苷键"],["E","氢键"]],"B","核酸中核苷酸之间的连接方式是3＇，5＇-磷酸二酯键，脱氧核苷酸之间的连接方式同样是3＇，5＇-磷酸二酯键（B对）。碱基与碱基之间的连接方式是氢键，核糖与碱基之间的连接方式是糖苷键，核苷与磷酸之间的连接方式是酯键。","","N"],["1997-N21",4,"第3节 糖的有氧氧化","三羧酸循环的概念",1997,21,"A","","三羧酸循环主要是在亚细胞器的哪一部位进行的",[["A","细胞核"],["B","细胞液"],["C","微粒体"],["D","线粒体"],["E","高尔基体"]],"D","糖的有氧氧化分三个阶段：第一阶段葡萄糖在细胞液经糖酵解生成丙酮酸；第二阶段丙酮酸进入线粒体氧化脱羧生成乙酰CoA；第三阶段乙酰CoA在线粒体内（D对）进入三羧酸循环。人微粒体（十版生物化学P237）（C错）含细胞色素P450单加氧酶，参与类固醇激素、胆汁酸及胆色素等物质的生成以及药物、毒物的生物转化过程。高尔基体（E错）主要进行分泌型蛋白质合成后的加工及转运。","","N"],["1997-N22",5,"第3节 甘油三酯代谢","脂肪酰CoA进入线粒体",1997,22,"A","","脂肪酸氧化的限速酶是",[["A","肉碱脂酰转移酶Ⅰ"],["B","Δ²烯酰水化酶"],["C","脂酰辅酶A脱氢酶"],["D","L-β羟脂酰辅酶A脱氢酶"],["E","β酮脂酰辅酶A硫解酶"]],"A","脂酰CoA进入线粒体是脂肪酸β-氧化的限速步骤，而脂酰CoA进入线粒体需要肉碱脂酰转移酶I的作用，因此肉碱脂酰转移酶I（A对）是脂肪酸β-氧化的关键酶（限速酶）。Δ²烯酰水化酶（B错）、脂酰辅酶A脱氢酶（C错）、L-β羟脂酰辅酶A脱氢酶（D错）、β酮脂酰辅酶A硫解酶（E错）均为脂肪酸β-氧化的非限速酶。","","N"],["1997-N23",5,"第6节 血浆脂蛋白及其代谢","极低密度脂蛋白的功能和代谢途径",1997,23,"A","","运载内源性甘油三酯的主要脂蛋白是",[["A","乳糜微粒"],["B","HDL"],["C","IDL"],["D","LDL"],["E","VLDL"]],"E","运载内源性甘油三酯的主要脂蛋白是VLDL（极低密度脂蛋白）（E对）。乳糜微粒（A错）主要转运外源性甘油三酯及胆固醇。HDL（高密度脂蛋白）（B错）主要逆向转运胆固醇。LDL（低密度脂蛋白）（D错）主要转运内源性胆固醇。IDL（中密度脂蛋白）（C错）是VLDL在血浆中向LDL转化的中间产物（十版生物化学P162）。","","N"],["1997-N24",9,"第3节 代谢调节的主要方式","别构调节对酶活性的调节",1997,24,"A","","乙酰辅酶A是哪个酶的变构激活剂",[["A","糖原磷酸化酶"],["B","丙酮酸羧化酶"],["C","6-磷酸果糖激酶-1"],["D","柠檬酸合成酶"],["E","异柠檬酸脱氢酶"]],"B","丙酮酸羧化酶是糖异生最重要的调节酶。乙酰CoA是丙酮酸羧化酶的变构激活剂（B对），当体内的糖或脂类分解增多，乙酰CoA含量增多时，一方面作为代谢产物抑制丙酮酸脱氢酶复合体，阻止糖的氧化利用，另一方面可以激活丙酮酸羧化酶，使丙酮酸变成草酰乙酸，加速糖异生。在三羧酸循环过程中，乙酰CoA作为柠檬酸合酶的底物，可以变构激活柠檬酸合酶（D对），促进柠檬酸的合成速率。故BD均对，原参考答案仅为B。AMP能别构激活糖原磷酸化酶（A错）、6-磷酸果糖激酶-1（C错）、异柠檬酸脱氢酶（E错），从而促进ATP的合成，乙酰辅酶A不是其别构激活剂。","","N"],["1997-N25",17,"第2节 细胞内信号转导分子","蛋白质酪氨酸激酶的作用",1997,25,"A","","可磷酸化蛋白质上酪氨酸残基的蛋白激酶是",[["A","蛋白激酶C"],["B","依赖于cAMP的蛋白激酶"],["C","依赖于cGMP的蛋白激酶"],["D","Src蛋白激酶"],["E","磷酸化酶b激酶"]],"D","Src蛋白激酶（D对）属于蛋白酪氨酸激酶，可接受受体传递的信号发生磷酸化而激活，并通过催化底物的酪氨酸磷酸化向下游传递信号。蛋白激酶C（A错）、依赖于cAMP的蛋白激酶（即蛋白激酶A）（B错）、依赖于cGMP的蛋白激酶（即蛋白激酶G）（C错）、磷酸化酶b激酶（E错）均属于可磷酸化蛋白质上丝氨酸残基和苏氨酸残基的丝氨酸/苏氨酸激酶。","","N"],["1997-N26",5,"第4节 磷脂代谢","甘油磷脂的降解",1997,26,"A","","磷酯酰肌醇4，5-二磷酸可为下列哪一种酶水解成甘油二酯和1，4，5-三磷酸肌醇",[["A","磷酯酶A₁"],["B","磷酯酶A₂"],["C","磷酯酶B"],["D","磷酯酶C"],["E","磷酯酶D"]],"D","生物体内存在多种降解甘油磷脂的磷脂酶，包括磷脂酶A₁、A₂、B₁、B₂、C及D，它们分别作用于甘油磷脂分子中不同的酯键。磷脂酶A₁、A₂（AB错）分别水解甘油磷脂的1、2位酯键并分别产生溶血磷脂2、1和对应的不饱和脂肪酸。磷脂酶B₁、B₂（C错）分别水解溶血磷脂1、2中的1、2位酯键，生成甘油磷酸X（X为胆碱、丝氨酸、肌醇等取代基）和对应的不饱和脂肪酸。磷脂酶C（D对）水解甘油磷脂中3位磷酸酯键，生成甘油二酯和磷酸X（X为胆碱、丝氨酸、肌醇等取代基），当甘油磷脂为磷酯酰肌醇4，5-二磷酸时，磷酸X为1，4，5-三磷酸肌醇。磷脂酶D（E错）水解甘油磷脂中磷酸取代基酯键，生成磷脂酸和X（X为胆碱、丝氨酸、肌醇等取代基）。","","N"],["1997-N27",1,"第6节 酶在医学中的应用","酶与疾病的关联",1997,27,"A","","通常血清中酶活性升高的主要原因是",[["A","体内代谢降低使酶的降解减少"],["B","细胞受损使细胞内酶释放入血"],["C","细胞内外某些酶被激活"],["D","酶由尿中排出减少"],["E","在某些器官中制造增加"]],"B","正常情况下，在组织细胞内发挥催化作用的酶在血清中含量甚微。当细胞受损，细胞内酶释放入血时（B对），血清中相应的酶活性会出现升高。如急性肝炎时血清丙氨酸转氨酶（ALT）的活性升高，急性胰腺炎时血、尿淀粉酶的活性升高等。","","N"],["1997-N28",0,"第3节 蛋白质结构与功能的关系","蛋白质的功能依赖特定空间结构",1997,28,"A","","HbO₂解离曲线是S形的原因是",[["A","Hb含有Fe²⁺"],["B","Hb含四条肽链"],["C","Hb存在于红细胞内"],["D","Hb属于变构蛋白"],["E","由于存在有2，3-DPG"]],"D","HbO₂解离曲线呈S形是因为：在氧分压较低时，Hb与氧结合较困难，曲线较缓，随着氧分压提高，Hb发生变构效应（Hb属于变构蛋白，氧分子与Hb的一个亚基结合后可引起其他亚基发生构象改变）（D对），与氧结合越来越容易，曲线越来越陡，斜率不断增大，最终曲线呈S形。","","N"],["1997-N29",13,"","",1997,29,"A","","干扰素抑制蛋白生物合成是因为",[["A","活化蛋白激酶，而使eIF-2磷酸化"],["B","抑制肽链延长因子"],["C","阻碍氨基酰tRNA与小亚基结合"],["D","抑制转肽酶"],["E","使核蛋白体60S亚基失活"]],"A","干扰素是真核细胞被病毒感染后分泌的一类具有抗病毒作用的蛋白质，其抗病毒作用机制有两种：一是干扰素能活化一种特异的蛋白激酶，使蛋白质翻译的起始因子eIF-2磷酸化而失活（A对），从而抑制病毒蛋白质合成；二是可活化一种特异的核酸内切酶（RNase L），使蛋白质翻译的模板mRNA被降解，从而阻断病毒蛋白质合成。抑制肽链延长因子（B错）的是白喉毒素。阻碍氨基酰tRNA与小亚基结合（C错）的是四环素。抑制转肽酶（D错）是氯霉素、红霉素和林可霉素。使核蛋白体60S亚基（真核生物大亚基）（E错）失活的是蓖麻毒素。","","N"],["1997-N30",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸分解代谢的终产物",1997,30,"A","","人体内嘌呤分解代谢的最终产物是",[["A","尿素"],["B","胺"],["C","肌酸"],["D","β-丙氨酸"],["E","尿酸"]],"E","尿酸（E对）是人体内嘌呤分解代谢的最终产物，嘌呤代谢紊乱引起体内尿酸含量增高并沉积可引起痛风。尿素（十版生物化学P182）（A错）是氨分解代谢的最终产物。胺（十版生物化学P185）（B错）是氨基酸脱羧基作用的产物。β-丙氨酸（十版生物化学P227）（D错）是胞嘧啶分解代谢的产物。","","N"],["1997-N31",18,"第1节 DNA损伤","体外因素",1997,31,"A","","紫外线对DNA的损伤主要是",[["A","引起碱基置换"],["B","导致碱基缺失"],["C","发生碱基插入"],["D","使磷酸二酯键断裂"],["E","形成嘧啶二聚物"]],"E","紫外线（物理因素）对DNA的损伤的机制主要是DNA链上相邻的2个嘧啶碱基发生共价交联形成嘧啶二聚物（E对）。碱基置换（A错）、碱基缺失（B错）、碱基插入（C错）、磷酸二酯键断裂（D错）均为化学因素所致的DNA损伤（十版生物化学P404）。","","N"],["1997-N32",17,"第5节 细胞信号转导异常与疾病","信号转导分子的异常激活与失活",1997,32,"A","","能使GTP结合蛋白中的GS亚基丧失GTP酶活性的是",[["A","霍乱毒素"],["B","百日咳毒素"],["C","白喉毒素"],["D","抗霉素A"],["E","鱼藤酮"]],"A","GTP结合蛋白即G蛋白，由α、β、γ三种亚基构成，其中α亚基具有GTP酶活性，是G蛋白的主要功能亚基，根据α亚基的功能不同，可将G蛋白分为Gs（兴奋性G蛋白）、Gi（抑制性G蛋白）、Gq等类型（九版生理学P27）。因此题干表述稍有歧义，GS并不是亚基类型，而是G蛋白类型。能与G蛋白的亚基结合并使之丧失GTP酶活性的是霍乱毒素（A对）：霍乱毒素能与Gs蛋白的α亚基结合，使其发生ADP-核糖化修饰，抑制其GTP酶活性，导致Gs蛋白被持续激活而致病。百日咳毒素（B错）的致病机制与霍乱毒素极为相似，其能与Gi蛋白（区别于霍乱毒素抑制的Gs蛋白）的α亚基结合，使其发生ADP-核糖化修饰，抑制其GTP酶活性，导致Gi蛋白被持续激活而致病。白喉毒素（十版生物化学P313）（C错）是真核细胞蛋白质合成的抑制剂，能使真核生物延长因子eEF-2发生ADP糖基化失活，阻止肽链延长。抗霉素A（十版生物化学P212）（D错）为呼吸链中复合体Ⅲ的抑制剂，能抑制复合体Ⅲ中Cyt b与Cyt c₁间的电子传递，从而阻断呼吸链。鱼藤酮（十版生物化学P212）（E错）为呼吸链中复合体Ⅰ的抑制剂，能抑制复合体I中铁硫中心与泛醌的电子传递，从而阻断呼吸链。","","N"],["1997-N49",21,"第4节 胆色素的代谢与黄疸","阻塞性黄疸",1997,49,"A","","血清碱性磷酸酶明显升高，可见于哪种黄疸",[["A","肝细胞性黄疸"],["B","溶血性黄疸"],["C","Rotor综合征引起的黄疸"],["D","Gilbert综合征引起的黄疸"],["E","阻塞性黄疸"]],"E","血清碱性磷酸酶（ALP）大部分由骨细胞产生，小部分来自肝，经胆汁排入肠道。在骨生长、妊娠和脂肪餐后等生理情况下，ALP水平可升高，排除上述生理因素及骨骼疾病，血清ALP明显升高提示肝胆疾病。阻塞性黄疸（E对）时，胆汁的排泄受阻，可导致血清ALP明显升高。肝细胞性黄疸（A错）时可有轻度胆汁返流，血清ALP正常或轻度升高。溶血性黄疸（B错）、Rotor综合征引起的黄疸（C错）和Gilbert综合征引起的黄疸（D错）均无肝细胞组织结构异常，不出现胆汁返流，血清ALP不会升高。","","N"],["1997-N99",6,"第3节 氨的代谢","丙氨酸-葡萄糖循环",1997,99,"B","","将肌肉中的氨以无毒形式运送至肝脏",[["A","丙氨酸-葡萄糖循环"],["B","柠檬酸-丙酮酸循环"],["C","三羧酸循环"],["D","鸟氨酸循环"],["E","乳酸循环"]],"A","氨是体内的有毒物质，各组织必须以无毒的形式将氨运输到肝脏代谢。氨可以通过丙氨酸-葡萄糖循环（A对）将氨转变为丙氨酸从骨骼肌运往肝，也可以通过谷氨酰胺从脑和骨骼肌运往肝或肾。柠檬酸-丙酮酸循环（十版生物化学P151）（B错）参与脂酸合成，作用是将乙酰CoA从线粒体运送到胞质。三羧酸循环（十版生物化学P114）（C错）又称柠檬酸循环，是三大营养物质代谢的最终代谢通路。鸟氨酸循环（十版生物化学P182）（D错）又称尿素循环，参与尿素的生成。乳酸循环（十版生物化学P132）（E错）参与骨骼肌中乳酸的转移和利用。","","N"],["1997-N100",5,"第3节 甘油三酯代谢","软脂酸合成的原料",1997,100,"B","","为机体合成脂肪酸提供NADPH",[["A","丙氨酸-葡萄糖循环"],["B","柠檬酸-丙酮酸循环"],["C","三羧酸循环"],["D","鸟氨酸循环"],["E","乳酸循环"]],"B","柠檬酸-丙酮酸循环（P154 图7-5）参与脂肪酸合成，作用是将乙酰CoA从线粒体运送到胞质，该循环中有苹果酸的参与，苹果酸在苹果酸酶的作用下脱氢生成丙酮酸，脱下来的氢由NADPH接受，这是体内除磷酸戊糖途径外生成NADPH的特例，生成的NADPH最终参与脂肪酸合成（B对）。丙氨酸-葡萄糖循环（十版生物化学P181）（A错）介导骨骼肌与肝脏之间氨的转运。三羧酸循环（十版生物化学P117）（C错）是三大营养物质（糖、脂肪、氨基酸）有氧氧化的最终代谢通路及代谢联系的枢纽。鸟氨酸循环（十版生物化学P182）（D错）即尿素循环，为尿素合成过程。肌收缩（尤其是氧供应不足时）通过糖无氧氧化生成乳酸，乳酸透过细胞膜弥散进入血液后，再入肝异生为葡萄糖。葡萄糖释入血液后又可被肌摄取，由此构成了一个循环，称为乳酸循环（十版生物化学P132）。乳酸循环的意义在于利用乳酸，防止因乳酸堆积而引起酸中毒，与脂肪酸合成代谢无关（E错）。","","N"],["1997-N121",6,"第4节 个别氨基酸的代谢","一碳单位的来源及转换",1997,121,"C","","生成一碳单位的氨基酸是",[["A","丝氨酸"],["B","蛋氨酸"],["C","二者均是"],["D","二者均不是"]],"A","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的基团，包括甲基、甲烯基、甲炔基、甲酰基及亚氨甲基等。可生成一碳单位的氨基酸包括丝氨酸（A对）、甘氨酸、组氨酸和色氨酸，记忆的口诀为施（丝氨酸）舍（色氨酸）一根竹（组氨酸）竿（甘氨酸）。蛋氨酸（甲硫氨酸）（B错）通过S-腺苷甲硫氨酸（SAM）提供“活性甲基”（一碳单位），但蛋氨酸的甲基来源于直接生成一碳单位的氨基酸（由同型半胱氨酸接受其他氨基酸产生的一碳单位而生成），因此蛋氨酸只是转移一碳单位（与四氢叶酸和维生素B₁₂类似），并不生成一碳单位。","","N"],["1997-N122",6,"第2节 氨基酸的一般代谢","α-酮酸转变成糖和脂质",1997,122,"C","","生酮氨基酸是",[["A","丝氨酸"],["B","蛋氨酸"],["C","二者均是"],["D","二者均不是"]],"D","根据代谢产物的不同可以将氨基酸分为三类：①生酮氨基酸：亮氨酸、赖氨酸，记忆口诀为同（酮）样（亮）来（赖）；②生酮兼生糖氨基酸：异亮氨酸、苯丙氨酸、酪氨酸、色氨酸、苏氨酸，记忆口诀为一（异）本（苯）落（酪）色（色）书（苏）；③生糖氨基酸：除了上述两类的所有氨基酸。综上，丝氨酸和蛋氨酸（甲硫氨酸）都属于生糖氨基酸（D对）。","","N"],["1997-N123",7,"第2节 线粒体氧化体系与呼吸链","甘油-3-磷酸穿梭",1997,123,"C","","3-磷酸甘油醛在3-磷酸甘油醛脱氢酶作用下脱下的氢",[["A","进入呼吸链生成3分子ATP"],["B","进入呼吸链生成2分子ATP"],["C","二者均对"],["D","二者均不对"]],"C","3-磷酸甘油醛在胞质中经3-磷酸甘油醛脱氢酶作用脱氢，脱下的氢被NAD⁺接受转变为NADH，NADH不能自由透过线粒体内膜，生成的NADH需进入线粒体后才能进入氧化呼吸链。进入线粒体有两种穿梭途径：在脑和骨骼肌中，经α-磷酸甘油穿梭途径，能产生1.5分子ATP（旧版教材为2分子ATP）（B）；在肝和心肌中，经苹果酸-天冬氨酸穿梭途径，能产生2.5分子ATP（旧版教材为3分子ATP）（A）。根据十版教材观点本题AB均错，正确答案为D，官方给出的参考答案为C。","","N"],["1997-N124",7,"第3节 氧化磷酸化与ATP的生成","根据P_O比值确定氧化磷酸化耦联部位",1997,124,"C","","谷氨酸在谷氨脱氢酶作用下脱下的氢",[["A","进入呼吸链生成3分子ATP"],["B","进入呼吸链生成2分子ATP"],["C","二者均对"],["D","二者均不对"]],"A","谷氨酸在谷氨酸脱氢酶作用下脱氢，脱下的氢可被NAD⁺接受生成NADH，也可被NADP⁺接受生成NADPH，但NADPH不参与生物氧化，而NADH进入NADH氧化呼吸链，产生2.5分子ATP（六版及之前教材为3分子ATP）（A对）。","","N"],["1997-N143",13,"第1节 蛋白质合成的概述","翻译的概念",1997,143,"X","","将DNA核苷酸顺序的信息转变成为氨基酸顺序的过程包括",[["A","复制"],["B","转录"],["C","反转录"],["D","翻译"]],"BD","将DNA核苷酸顺序的信息转变为氨基酸顺序需要经历转录和翻译（BD对）两个过程：转录将DNA核苷酸顺序的信息转变为mRNA核苷酸顺序，翻译则进一步将mRNA的核苷酸顺序的信息转变为氨基酸顺序。复制（十版生物化学P255）（A错）是指将母链DNA核苷酸顺序的信息转变为子链DNA核苷酸顺序的过程。反转录（十版生物化学P269）（C错）是指将RNA核苷酸顺序的信息转变为DNA核苷酸顺序的过程。","","N"],["1997-N144",1,"第3节 酶促反应动力学","酶促反应动力学的概念",1997,144,"X","","测定酶活性的必要条件是",[["A","最适pH"],["B","适宜温度"],["C","足够的底物浓度"],["D","足够的激活物"]],"ABC","测定酶的活性的必要条件是保证酶促反应在最适宜的条件下进行，影响酶促反应的因素均是恒定的，所测定的结果才是某一状态下酶的活性。酶的催化活性会受酸碱度和温度的影响，因此，测定酶的活性需要在最适pH（A对）、适宜温度（B对）的条件下进行。底物浓度对酶促反应速率的影响呈矩形双曲线，底物足够时对酶活性的影响才能忽略不计（C对）。激活剂（激动物）可提高酶促反应速率，大多数金属离子激活剂对酶促反应是不可缺少的，称为必需激活剂，有些酶即使激活剂不存在时，仍有一定的催化活性，称为非必需激活剂，另有一些酶催化不需要激活剂，因此测定酶活性足够的激活剂不是必需的（D错）。","","N"],["1997-N145",0,"第4节 蛋白质的理化性质","变性",1997,145,"X","","蛋白质变性时",[["A","空间结构破坏，一级结构无改变"],["B","280nm处光吸收增加"],["C","溶解度降低"],["D","生物学功能改变"]],"ABCD","蛋白质的变性是指在某些物理和化学因素作用下，蛋白质特定的空间构象被破坏，理化性质及生物学活性丧失。一般认为蛋白质变性主要发生二硫键和非共价键的破坏，不涉及氨基酸的序列改变，但二硫键也属于一级结构，故A选项不严谨。蛋白质变性后：溶解度降低（C对），黏度增加，结晶能力消失，生物学活性丧失（D对），易被蛋白酶水解。各版教材未提及蛋白质变性后吸光度的变化，故B项不作解析。官方参考答案为ABCD。","","N"],["1997-N146",6,"第1节 营养必需氨基酸与氨基酸代谢概述","蛋白质在小肠中被水解成氨基酸和寡肽",1997,146,"X","","属于内肽酶的是",[["A","胰蛋白酶"],["B","糜蛋白酶"],["C","弹性蛋白酶"],["D","羧基肽酶"]],"ABC","胰液中的蛋白酶基本上分为两大类，即内肽酶和外肽酶。内肽酶可以特异地水解蛋白质内部的一些肽键，而外肽酶可以特异地水解蛋白质或多肽末端的肽键。内肽酶主要包括胰蛋白酶（A对）、胰凝乳蛋白酶（糜蛋白酶）（B对）和弹性蛋白酶（C对）。外肽酶主要包括羧基肽酶（D错）和氨基肽酶。","","N"],["1998-N19",6,"第4节 个别氨基酸的代谢","含硫氨基酸的概述",1998,19,"A","","以下哪种氨基酸是含硫的氨基酸",[["A","谷氨酸"],["B","赖氨酸"],["C","亮氨酸"],["D","蛋氨酸"],["E","酪氨酸"]],"D","含硫氨基酸有三种：半胱氨酸、胱氨酸和甲硫氨酸。甲硫氨酸又称为蛋氨酸（D对）。谐音记忆为刘（硫）邦（半胱氨酸）光（胱氨酸）蛋（蛋氨酸）。","","N"],["1998-N20",2,"第4节 核酸的理化性质","DNA变性",1998,20,"A","","不同的核酸分子其解链温度（Tm）不同，以下关于Tm的说法正确的是",[["A","DNA中C-G对比例愈高，Tm愈高"],["B","DNA中A-T对比例愈高，Tm愈高"],["C","核酸愈纯，Tm范围愈大"],["D","核酸分子愈小，Tm范围愈大"],["E","Tm较高的核酸常常是RNA"]],"A","在DNA解链过程中，紫外吸光度的变化（△A₂₆₀）达到最大变化值一半时所对应的温度为DNA的解链温度（Tm），Tm值与DNA分子的GC含量有关，G+C含量越高，Tm值越高（A对B错），这与C≡G碱基对之间有3个氢键，A=T碱基对之间仅2个氢键，破坏C≡G需要的温度更高有关。核酸愈纯，核酸分子愈小，Tm范围均愈小（CD错）。DNA分子具有双螺旋结构，而RNA分子一般以单链存在，所以Tm较高的核酸常常是DNA（E错）。","","N"],["1998-N21",1,"第3节 酶促反应动力学","竞争性抑制",1998,21,"A","","酶竞争性抑制作用的特点是",[["A","Km值不变，Vmax降低"],["B","Km值降低，Vmax不变"],["C","Km值增高，Vmax不变"],["D","Km值不变，Vmax增加"],["E","Km值降低，Vmax降低"]],"C","竞争性抑制作用是抑制剂与酶作用的一种方式，由于抑制剂和酶的底物在结构上相似，可与底物竞争结合酶的活性中心（因而实际可与底物结合的酶量减少，底物与酶的亲和力下降，即Km值增大），从而阻碍酶与底物形成中间产物，但是当酶量足够多时，抑制剂与酶的结合饱和之后仍有足够的酶参加反应，此时的最大反应速率与无抑制剂时是相同的，即Vmax不变（C对）。","","N"],["1998-N22",1,"第1节 酶的分子结构与功能","同工酶催化相同的化学反应",1998,22,"A","","下列关于同工酶概念的叙述，哪一项是正确的",[["A","是结构相同，而存在部位不同的一组酶"],["B","是催化相同化学反应，而酶的分子结构不同、理化性质可各异的一组酶"],["C","是催化的反应和酶的性质都相似，而分布不同的一组酶"],["D","是催化相同反应的所有酶"],["E","以上都不正确"]],"B","同工酶是指催化相同的化学反应，但酶分子的分子结构和理化性质不同的一组酶（B对AC错）。同工酶可存在于同一部位（AC错），例如，心肌细胞中同时存在LDH1、LDH2、LDH3。同工酶本质上是不同的，这是因为组成它们的氨基酸一级结构不同，但这些酶的活性中心的三维结构相同或相似，因此它们可以催化相同的化学反应，但并不是催化相同反应的所有的酶都是同工酶（D错）。","","N"],["1998-N23",9,"第3节 代谢调节的主要方式","饥饿时的机体代谢",1998,23,"A","","饥饿可以使肝内哪种代谢途径增强",[["A","脂肪合成"],["B","糖原合成"],["C","糖酵解"],["D","糖异生"],["E","磷酸戊糖途径"]],"D","饥饿时，体内葡萄糖的供应减少，肝糖原逐渐消耗殆尽，导致血糖降低，机体启动一系列升血糖的调节机制：增加血糖来源的肝脏糖异生（D对）作用加强，增加血糖去路（利用）的脂肪合成（A错）、糖原合成（B错）、糖酵解（C错）和磷酸戊糖途径（E错）等代谢途径则减弱。","","N"],["1998-N24",5,"第3节 甘油三酯代谢","脂肪酸氧化产能",1998,24,"A","","脂肪酸在肝脏进行β-氧化时，不生成下列何种物质",[["A","NADH＋H⁺"],["B","FADH₂"],["C","H₂O"],["D","乙酰CoA"],["E","脂酰CoA"]],"C","脂肪酸在肝脏进行β-氧化时须先在线粒体外活化形成脂酰CoA（E对），脂酰CoA进入线粒体，经脱氢、加水（加H₂O，而非生成H₂O，脂肪酸合成方可生成H₂O）（C错，为本题正确答案）、再脱氢、硫解等四步循环反应，彻底氧化生成NADH（A对）、FADH₂（B对）和乙酰CoA（D对）。","","N"],["1998-N25",6,"第3节 氨的代谢","鸟氨酸循环过程",1998,25,"A","","通过鸟氨酸循环生成尿素时，其分子中的两个氮原子一个直接来自游离的氨，另一个直接来源于",[["A","鸟氨酸"],["B","瓜氨酸"],["C","精氨酸"],["D","天冬氨酸"],["E","甘氨酸"]],"D","尿素的分子式为H₂N-CO-NH₂，尿素分子中第一个氮原子来源于NH₃，第二个氮原子来源于天冬氨酸（D对）。鸟氨酸循环的大致步骤：①NH₃（第一个氮原子来源）、CO₂和ATP缩合成氨基甲酰磷酸；②氨基甲酰磷酸与鸟氨酸反应生成瓜氨酸；③瓜氨酸与天冬氨酸（第二个氮原子来源）反应生成精氨酸代琥珀酸；④精氨酸代琥珀酸裂解生成精氨酸与延胡索酸，反应产物精氨酸中保留了来自游离NH₃和天冬氨酸分子中的氮；⑤精氨酸水解释放尿素并生成鸟氨酸，鸟氨酸再次进入线粒体参与合成瓜氨酸，如此反复，进行鸟氨酸循环。","","N"],["1998-N26",7,"第2节 线粒体氧化体系与呼吸链","甘油-3-磷酸穿梭",1998,26,"A","","线粒体外NADH经α-磷酸甘油穿梭作用进入线粒体内完成氧化磷酸化，其P/O比值为",[["A","0"],["B","1"],["C","2"],["D","2.5"],["E","3"]],"C","NADH不能自由透过线粒体内膜，细胞质中NADH进入线粒体有两种穿梭机制：①α-磷酸甘油穿梭机制，该机制主要存在于脑和骨骼肌中，1分子NADH经此穿梭产生1.5分子ATP（旧版教材为2分子ATP），即其P/O比值为1.5（2）（C对）；②苹果酸-天冬氨酸穿梭机制，该机制主要存在于肝、肾和心肌中（记忆为心肝肾宝，因此产生的能量较高），1分子NADH经此穿梭产生2.5分子ATP（旧版教材为3分子ATP），即其P/O比值为2.5（3）。按照十版教材观点为1.5，该题无正确答案，但原答案选C。","","N"],["1998-N27",8,"第2节 嘌呤核苷酸的合成与分解代谢","脱氧核苷酸的生成",1998,27,"A","","脱氧核糖核苷酸的生成方式主要是",[["A","直接由核糖还原"],["B","由核苷还原"],["C","由一磷酸核苷还原"],["D","由二磷酸核苷还原"],["E","由三磷酸核苷还原"]],"D","脱氧核糖核苷酸不能由核糖直接还原（A错）再连接上碱基和磷酸而生成，而是通过相应的核苷酸的直接还原作用生成，这种还原作用主要在二磷酸核苷（D对）水平进行，即NDP→dNDP（N代表A、G、U、C等碱基）。唯一例外的是脱氧胸腺嘧啶核苷酸（dTMP）的合成是在一磷酸水平进行的（由dUMP经甲基化而生成）。","","N"],["1998-N28",11,"第3节 原核生物DNA复制过程","引物合成和起始复合物的形成",1998,28,"A","","以下哪些代谢过程需要以RNA为引物",[["A","体内DNA复制"],["B","转录"],["C","RNA复制"],["D","翻译"],["E","反转录"]],"A","体内DNA复制（A对）时，母链DNA解成单链后，不会立即按照模板序列将dNTP聚合为DNA子链，这是因为DNA聚合酶不具备催化两个游离dNTP形成磷酸二酯键的能力，只能催化核酸片段的3＇-OH末端与dNTP间的聚合，因此在复制起始部位需要以RNA为引物（RNA引物由引物酶催化合成：引物酶可催化两个游离的NTP形成磷酸二酯键，从而合成RNA引物），RNA引物可为DNA的合成3＇-OH末端。转录（B错）和RNA复制（C错）本身即为RNA的聚合过程，不需要RNA引物。翻译（D错）为蛋白质的合成过程，不需要RNA引物（D错）。反转录（逆转录）合成是需要RNA引物的（反转录是以RNA为模板合成双链DNA的过程，合成DNA链需要引物），如逆转录病毒可用自身的tRNA作为引物（十版生物化学P269），因此E选项也应当是正确的。","","N"],["1998-N29",18,"第2节 DNA损伤修复","切除修复",1998,29,"A","","下列哪种酶不参与DNA损伤的切除修复过程",[["A","核酸内切酶"],["B","核酸外切酶"],["C","DNA聚合酶"],["D","DNA连接酶"],["E","核酸限制性内切酶"]],"E","DNA损伤的切除修复主要包括碱基切除修复和核苷酸切除修复两种类型。其中碱基切除修复过程主要包括四步：①识别水解：DNA 糖苷酶（八版教材名为DNA 糖基化酶）特异性识别DNA链中已受损的碱基并将其水解去除，产生一个无碱基位点；②切除：核酸内切酶（A对）识别无碱基位点，切除受损的核苷酸；③合成：DNA聚合酶（C对）在缺口处以另一条链为模板修补合成互补序列；④连接：由DNA连接酶（D对）将切口重新连接，使DNA恢复正常结构。核苷酸切除修复过程与碱基切除修复相似（具体过程见P409），同样需要核酸内切酶（A对）、DNA聚合酶（C对）和DNA连接酶（D对）的参与。核酸外切酶（B对）参与碱基错配修复（十版生物化学P408）过程，碱基错配修复为碱基切除修复的特殊类型。核酸限制性内切酶（十版生物化学P369）（E错，为本题正确答案）只能特异性识别特定核苷酸序列，主要用于基因工程，不参与DNA损伤修复。","","N"],["1998-N30",13,"第2节 蛋白质合成体系","遗传密码的特点",1998,30,"A","","下列关于氨基酸密码的描述，哪一项是错误的",[["A","密码有种属特异性，所以不同生物合成不同的蛋白质"],["B","密码阅读有方向性，5'端起始，3'端终止"],["C","一种氨基酸可有一种以上的密码"],["D","一种密码只代表一种氨基酸"],["E","密码第3位（即3'端）碱基在决定掺入氨基酸的特异性方面重要性较小"]],"A","遗传密码具有以下几个重要特点：①方向性，翻译时遗传密码的阅读方向只能从5’至3’，即从mRNA 5’端的起始密码子AUG开始，按5’→3’的方向逐一阅读，直至3’端终止密码子终止（B对）；②连续性，mRNA的密码子之间没有间隔核苷酸，即从起始密码子开始，密码子被连续阅读，直至终止密码子出现；③简并性，64个密码子中有61个编码氨基酸，而氨基酸只有20种，因此有的氨基酸可有一种以上的密码（但一种密码只代表一种氨基酸）（CD对），此为遗传密码的简并性；④摆动性，mRNA密码子的第3位碱基与tRNA反密码子的第1位碱基之间并不严格配对，出现摆动，此为遗传密码的摆动性。摆动性导致密码子第3位碱基的改变往往不改变其编码的氨基酸种类，即密码子第3位碱基在决定掺入氨基酸的特异性方面重要性较小（E对）；⑤通用性，从细菌到人类的所有生物都使用着同一套遗传密码（A错，为本题正确答案）。","","N"],["1998-N31",4,"第4节 戊糖磷酸途径","戊糖磷酸途径的意义",1998,31,"A","","成熟红细胞中只保存两条对其生存和功能发挥重要作用的代谢途径，其一是糖无氧酵解，其二是",[["A","DNA合成"],["B","RNA合成"],["C","蛋白质合成"],["D","三羧酸循环"],["E","磷酸戊糖途径"]],"E","成熟红细胞除了质膜和胞质外，无其他细胞器（如线粒体、内质网、细胞核等），因此DNA合成（A错）、RNA合成（B错）、蛋白质合成（C错）及三羧酸循环（D错）等反应无法在成熟的红细胞进行。糖酵解和磷酸戊糖途径是在细胞液内进行的，且红细胞内存在催化糖酵解及磷酸戊糖途径（E对）所需的酶和中间代谢物，因此这两种反应途径可在红细胞内可以进行。","","N"],["1998-N32",21,"第4节 胆色素的代谢与黄疸","结合",1998,32,"A","","下列对直接胆红素的说法哪一项是错误的",[["A","为胆红素葡萄糖醛酸二酯"],["B","水溶性较大"],["C","不易透过生物膜"],["D","不能通过肾脏随尿排出"],["E","与重氮试剂起反应的速度快，呈直接反应"]],"D","直接胆红素即结合胆红素，是指在肝与葡糖醛酸结合转化的胆红素，主要为胆红素葡糖醛酸二酯（A对）。直接胆红素水溶性较大（B对），不易透过生物膜（C对），可以通过肾小球随尿排出（D错，为本题正确答案）。直接胆红素分子内不再有氢键，分子中间的甲烯桥不再深埋于分子内部，故与重氮试剂起反应的速度快，呈直接反应（E对）。","","N"],["1998-N97",4,"第6节 糖异生","糖异生的关键酶及耗能",1998,97,"B","","糖异生途径的关键酶是",[["A","磷酸甘油酸激酶"],["B","烯醇化酶"],["C","丙酮酸激酶"],["D","丙酮酸脱氢酶复合体"],["E","丙酮酸羧化酶"]],"E","糖异生是指非糖化合物（乳酸、甘油、生糖氨基酸等）转变为葡萄糖或糖原的过程，进行糖异生的器官主要是肝。糖异生的关键酶有丙酮酸羧化酶（E对）、磷酸烯醇丙酮酸羧激酶、果糖二磷酸酶-1和葡萄糖-6-磷酸酶。磷酸甘油酸激酶（A错）和烯醇化酶（B错）催化的是可逆反应，它们均不是关键酶。丙酮酸激酶（十版生物化学P110）是糖酵解的关键酶（C错）。丙酮酸脱氢酶复合体（十版生物化学P113）是丙酮酸氧化脱羧的关键酶（D错）。","","N"],["1998-N98",4,"第2节 糖的无氧氧化","丙酮酸激酶",1998,98,"B","","糖酵解途径的关键酶是",[["A","磷酸甘油酸激酶"],["B","烯醇化酶"],["C","丙酮酸激酶"],["D","丙酮酸脱氢酶复合体"],["E","丙酮酸羧化酶"]],"C","糖酵解的关键酶包括葡萄糖激酶、6-磷酸果糖激酶-1和丙酮酸激酶（C对）。磷酸甘油酸激酶（A错）和烯醇化酶（B错）为糖酵解途径的非关键酶。丙酮酸脱氢酶复合体为丙酮酸氧化脱羧的关键酶（十版生物化学P113）（D错）。丙酮酸羧化酶为糖异生的关键酶（十版生物化学P128）（E错）。","","N"],["1998-N123",12,"第3节 真核生物mRNA的转录、加工和降解","前体mRNA的剪接",1998,123,"C","","DNA上的内含子（intron）是指",[["A","不被转录的序列"],["B","被转录但不被翻译的序列"],["C","二者均是"],["D","二者均不是"]],"B","真核生物的DNA编码序列由相间排列的外显子（exon）和内含子（intron）组成（十版生物化学P244），其中内含子将在转录后加工中被剪接去除，不能继续被翻译（B对），外显子则将保留并被翻译出来。不被转录的序列（A错）是非编码序列（十版生物化学P285）。","","N"],["1998-N124",12,"第3节 真核生物mRNA的转录、加工和降解","前体mRNA的剪接",1998,124,"C","","DNA上的外显子（exon）是指",[["A","不被转录的序列"],["B","被转录但不被翻译的序列"],["C","二者均是"],["D","二者均不是"]],"D","真核生物的DNA编码序列由相间排列的外显子（exon）和内含子（intron）组成（十版生物化学P244），其中内含子将在转录后加工中被剪接去除，不能继续被翻译，外显子则将保留并被翻译出来（B错）。不被转录的序列（A错）是非编码序列（十版生物化学P285）。本题AB均错，正确答案为D。","","N"],["1998-N125",21,"第2节 肝的生物转化作用","氧化反应",1998,125,"C","","属于单加氧酶系的是",[["A","25-羟维生素D₃-1α-羟化酶"],["B","维生素D₃-25-羟化酶"],["C","二者都是"],["D","二者都不是"]],"C","单加氧酶系是氧化机体内非营养物质最重要的酶，因底物的氧化产物是羟化物，所以该酶又称为羟化酶，其氧化作用也称羟化作用。其氧化作用/羟化作用的过程为：催化氧分子中的一个氧原子添加到底物分子上，而另一个氧原子则被NADPH还原成水。单加氧酶系的氧化作用/羟化作用可以参与体内许多重要物质的羟化过程，如维生素D₃羟化成为具有生物学活性的维生素1，25-（OH）₂D₃，参与此反应的维生素D₃-25-羟化酶（B对）和25-羟维生素D₃-1α羟化酶（A对）均属于单加氧酶系。本题AB均对，正确答案为C。","","N"],["1998-N126",3,"第1节 脂溶性维生素","维生素D",1998,126,"C","","存在于肝细胞微粒体中的是",[["A","25羟维生素D₃-1α-羟化酶"],["B","维生素D₃-25-羟化酶"],["C","二者都是"],["D","二者均不是"]],"B","维生素D₃的活化形式是1，25-二羟维生素D₃，维生素D₃的活化分两步进行：第一步，在肝微粒体25-羟化酶的催化下（B对），维生素D₃被羟化为25-羟维生素D₃（25-OH-D₃）；第二步，25-OH-D₃在肾小管上皮细胞线粒体1α-羟化酶的作用下，生成维生素D₃的活性形式1，25-（OH）₂-D₃。","","N"],["1998-N143",0,"第1节 蛋白质的分子组成","氨基酸的分类",1998,143,"X","","合成蛋白质后才由前体转变而成的氨基酸是",[["A","脯氨酸"],["B","羟脯氨酸"],["C","丝氨酸"],["D","赖氨酸"]],"B","肽链合成时直接掺入的氨基酸只有20种，合成后某些氨基酸残基的侧链基团发生的化学修饰显著地增加了肽链中氨基酸的种类。常见的化学修饰种类包括磷酸化、羟基化、甲基化、乙酰化等。比较常见的修饰氨基酸包括胱氨酸，羟脯氨酸，羟赖氨酸等，其中羟脯氨酸（B对）是脯氨酸在脯氨酸羟化酶的作用下转化而来的。原X型题为不定项选择题，有1-4个正确答案。","","N"],["1998-N144",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶核苷酸从头合成途径的概述",1998,144,"X","","嘌呤、嘧啶合成的共同原料是",[["A","甘氨酸"],["B","磷酸核糖焦磷酸"],["C","N¹⁰-甲酰四氢叶酸"],["D","天冬氨酸"]],"D","合成嘌呤碱的原料来自天冬氨酸、谷氨酰胺、甘氨酸、CO₂及一碳单位（由N¹⁰-甲酰四氢叶酸提供）等，其中三种氨基酸可记为：天（天冬氨酸）啊，俺家的谷子（谷氨酰胺）干（甘氨酸）了。合成嘧啶碱的原料来自谷氨酰胺、天冬氨酸、CO₂、一碳单位（由N⁵，N¹⁰-亚甲四氢叶酸提供，合成dTMP所需）等，其中两种氨基酸可记为：天（天冬氨酸）啊，俺家的谷子（谷氨酰胺）没干（没有甘氨酸）（A错）。因此天冬氨酸（D对）、谷氨酰胺和CO₂是嘌呤、嘧啶合成的共同原料，而甘氨酸、N¹⁰-甲酰四氢叶酸（C错）是嘌呤合成的特有原料，N⁵，N¹⁰-亚甲四氢叶酸则是胸腺嘧啶合成的特有原料。磷酸核糖焦磷酸（PRPP）（B错）是嘌呤核苷酸合成（十版生物化学P220）和嘧啶核苷酸合成（十版生物化学P226） 的共同原料。原X型题为不定向选择题，有1-4个正确答案。","","N"],["1998-N145",6,"第4节 个别氨基酸的代谢","一碳单位的来源及转换",1998,145,"X","","在分解代谢过程中可以产生一碳单位的氨基酸是",[["A","Gly"],["B","Ser"],["C","Tyr"],["D","Trp"]],"ABD","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的基团，包括甲基、甲烯基、甲炔基、甲酰基及亚氨甲基等。在分解代谢过程中可以产生一碳单位的氨基酸包括丝氨酸（Ser）（B对）、甘氨酸（Gly）（A对）、组氨酸（His）和色氨酸（Trp）（D对），记忆的口诀为施（丝氨酸）舍（色氨酸）一根竹（组氨酸）竿（甘氨酸），苏氨酸可通过转变成甘氨酸间接产生一碳单位。Tyr（C错）为酪氨酸，不产生一碳单位。","","N"],["1998-N146",4,"第3节 糖的有氧氧化","糖有氧氧化的协调",1998,146,"X","","细胞内ATP/AMP比值增加可以抑制",[["A","己糖激酶"],["B","6-磷酸果糖激酶-1"],["C","3-磷酸甘油醛脱氢酶"],["D","丙酮酸脱氢酶复合体"]],"BD","葡萄糖有氧氧化的主要意义在于为机体供应能量，当能量供应充足时（ATP/AMP比值增加），有氧氧化过程中的大部分关键酶如6-磷酸果糖激酶-1（B对），丙酮酸激酶，丙酮酸脱氢酶复合体（D对）和柠檬酸循环中的异柠檬酸脱氢酶等均可被抑制（被ATP变构抑制，被AMP变构激活）。己糖激酶亦为有氧氧化的关键酶，但其受反应产物6-磷酸葡萄糖（葡萄-6-磷酸）及长链脂酰CoA的别构调节，不受ATP/AMP比值的调节（A错）。3-磷酸甘油醛脱氢酶为葡萄糖有氧氧化过程中的非关键酶，不受ATP/AMP比值的影响（C错）。","","N"],["1999-N19",6,"第4节 个别氨基酸的代谢","甲硫氨酸循环",1999,19,"A","","天然蛋白质中不存在的氨基酸是",[["A","蛋氨酸"],["B","胱氨酸"],["C","羟脯氨酸"],["D","同型半胱氨酸"],["E","精氨酸"]],"D","存在于自然界的氨基酸有300余种，但存在于人体天然蛋白质中的只有20种。常见的不出现于蛋白质中的氨基酸有鸟氨酸、瓜氨酸和同型半胱氨酸（D对）。瓜氨酸和鸟氨酸是尿素合成的中间代谢产物（十版生物化学P182图9-8 尿素生成的鸟氨酸循环）。同型半胱氨酸是甲硫氨酸循环的中间代谢产物（十版生物化学P188甲硫氨酸循环）。","","N"],["1999-N20",6,"第4节 个别氨基酸的代谢","一碳单位的来源及转换",1999,20,"A","","下列氨基酸中哪一种不能提供一碳单位",[["A","甘氨酸"],["B","丝氨酸"],["C","组氨酸"],["D","色氨酸"],["E","酪氨酸"]],"E","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的基团，包括甲基、甲烯基、甲炔基、甲酰基及亚氨甲基等。可以提供一碳单位的氨基酸包括丝氨酸（B对）、甘氨酸（A对）、组氨酸（C对）和色氨酸（D对），记忆的口诀为施（丝氨酸）舍（色氨酸）一根竹（组氨酸）竿（甘氨酸）。酪氨酸（E错，为本题正确答案）不能提供一碳单位。","","N"],["1999-N21",2,"第4节 核酸的理化性质","DNA变性",1999,21,"A","","下列几种DNA分子的碱基组成比例各不相同，哪一种DNA的解链温度（Tm）最低",[["A","DNA中A+T含量占15%"],["B","DNA中G+C含量占25%"],["C","DNA中G+C含量占40%"],["D","DNA中A+T含量占60%"],["E","DNA中G+C含量占70%"]],"B","在DNA解链过程中，紫外吸光度的变化（A₂₆₀）达到最大变化值的一半时所对应的温度为DNA的解链温度（Tm），Tm值与DNA分子的GC含量有关，G+C含量越高，Tm值越高，反之亦然，这与C≡G碱基对之间有3个氢键，A=T碱基对之间仅2个氢键，破坏C≡G需要的温度更高有关。在完整的DNA双链中AT含量+CG含量=100%，所以GC含量，A为85%，B为25%（B对），C为40%，D为40%，E为70%。","","N"],["1999-N22",9,"","",1999,22,"A","","下列物质在体内氧化成CO₂和H₂O时，同时产生ATP，哪种产生ATP最多",[["A","甘油"],["B","丙酮酸"],["C","乳酸"],["D","谷氨酸"],["E","乙酰乙酸"]],"D","题中各种物质彻底氧化分解中生成ATP的情况：①甘油→3-磷酸甘油（-1ATP）→磷酸二羟丙酮（+2.5ATP）→3-磷酸甘油醛，3-磷酸甘油醛进入糖的有氧氧化的彻底氧化分解，由表6-1，3-磷酸甘油醛彻底氧化分解生成16或17分子ATP，所以甘油分解最多生成18.5分子ATP。②丙酮酸彻底氧化分解生成12.5分子ATP。③乳酸→丙酮酸（+2.5ATP），加上丙酮酸彻底氧化分解生成的12.5分子ATP，乳酸彻底氧化分解生成15分子ATP。④谷氨酸→α-酮戊二酸（+2.5ATP），α-酮戊二酸进入三羧酸循环变成草酰乙酸生成7.5分子ATP，草酰乙酸→磷酸烯醇式丙酮酸（-1ATP），磷酸烯醇式丙酮酸彻底氧化分解生成13.5分子ATP，所以谷氨酸彻底氧化分解产生22.5ATP的情况。⑤乙酰乙酸→乙酰乙酰CoA（-2ATP），乙酰乙酸硫解生成两分子乙酰CoA，2分子乙酰CoA进入三羧酸循环彻底氧化分解生成20分子ATP，所以1分子乙酰乙酸彻底氧化生成18分子ATP。综上所述，题中各种物质氧化分解生成ATP最多的是谷氨酸（D对）（一般情况下，不知道如何判断时可根据各物质所含碳原子数目的多少来作粗略估计，碳原子数目越多，氧化后释放的能量越多）。","","N"],["1999-N23",1,"第1节 酶的分子结构与功能","酶的分子组成",1999,23,"A","","酶促反应中决定酶特异性的是",[["A","作用物的类别"],["B","酶蛋白"],["C","辅基或辅酶"],["D","催化基团"],["E","金属离子"]],"B","酶按其分子组成可分为单纯酶和结合酶。结合酶是由蛋白质部分和非蛋白质部分共同组成，其中蛋白质部分称为酶蛋白，非蛋白质部分称为辅助因子，酶蛋白（B对）决定酶促反应的特异性及其催化机制，辅助因子决定酶促反应的性质和类型。例如生物素是各种羧化酶的辅酶，它决定了反应的性质，而丙酮酸羧化酶这一酶蛋白决定反应的特异性。辅基、辅酶及金属离子均属于辅助因子（CE错）。酶的特异性决定作用物的类别，而非作用物的类别决定酶的特异性。","","N"],["1999-N24",1,"第4节 酶的调节","别构调节",1999,24,"A","","下列关于酶的别构调节，错误的是",[["A","受别构调节的酶称为别构酶"],["B","别构酶多是关键酶（如限速酶），催化的反应常是不可逆反应"],["C","别构酶催化的反应，其反应动力学是符合米-曼氏方程的"],["D","别构调节是快速调节"],["E","别构调节不引起酶的构型变化"]],"C","体内一些代谢物可与某些酶的活性中心外的某个部位非共价可逆结合，引起酶的构象改变（而非构型改变，顺反异构、旋光异构等为构型，二级结构、三级结构、四级结构等空间结构为构象）（E对），从而改变酶的活性，酶的这种调节方式称为酶的别构调节，也称为变构调节。可以受别构调节的酶称为别构酶（A对），常由多亚基组成，由于多亚基之间存在正协同效应或负协同效应，因此其反应动力学不遵守米氏方程（C错，为本题正确答案）。物质代谢过程中各关键酶（催化不可逆反应）多受别构调节（B对），别构调节属于快速调节的一种（另外一种为化学修饰调节）（D对）。","","N"],["1999-N25",1,"第3节 酶促反应动力学","酶促反应动力学参数",1999,25,"A","","血糖浓度低时，脑仍可摄取葡萄糖而肝不能，是因为",[["A","胰岛素的作用"],["B","脑己糖激酶的Km值低"],["C","肝葡萄糖激酶的Km值低"],["D","葡萄糖激酶具有特异性"],["E","血脑屏障在血糖低时不起作用"]],"B","Km即米氏常数，为酶的特征性常数，在数值上等于酶促反应速率为最大反应速率一半时的底物浓度。一定条件下，Km值可以表示酶对底物的亲和力，Km越大，表示酶对底物的亲和力越小，Km越小，酶对底物的亲和力越大。低血糖时，脑可摄取葡萄糖而肝不能，因为脑中己糖激酶的Km值较低（B对C错），对葡萄糖亲和力较高，从而保证在饥饿条件下脑部的能量供应。胰岛素对肝和脑的影响是一致的（A错）。葡萄糖激酶为己糖激酶Ⅳ型同工酶，是肝脏的特异性激酶（十版生物化学P108）（D错）。特异性低血糖时可使血脑屏障葡萄糖转运体（GLUT）表达增加，降低血脑屏障的屏障作用，并不是不起作用，退一步讲，即使血脑屏障不起作用，也不能解释“脑仍可摄取葡萄糖而肝不能”的现象，因为肝脏本身就不存在类似的屏障（E错）。","","N"],["1999-N26",4,"第3节 糖的有氧氧化","糖有氧氧化的协调",1999,26,"A","","当肝细胞内ATP供应充分时，下列叙述中哪项是错误的",[["A","丙酮酸激酶被抑制"],["B","6-磷酸果糖激酶-1被抑制"],["C","异柠檬酸脱氢酶被抑制"],["D","果糖二磷酸酶被抑制"],["E","进入三羧酸循环的乙酰辅酶A减少"]],"D","当肝细胞内ATP供应充足时，糖的有氧氧化受到抑制，能量供应减少，而糖异生相对增强，因此与糖的氧化相关的酶如丙酮酸激酶（A对），磷酸果糖激酶-1（B对）和异柠檬酸脱氢酶（C对）活性降低，进入三羧酸循环的乙酰辅酶A相应减少（E对），而与糖异生相关的酶如果糖二磷酸酶（D错，为本题正确答案）活性增强，产生葡萄糖用于糖原合成。","","N"],["1999-N27",5,"第1节 脂质的构成、功能及分析","脂肪酸的生物学功能",1999,27,"A","","大鼠出生后饲以去脂膳食，结果将引起下列哪种脂质缺乏",[["A","磷脂酰胆碱"],["B","甘油三酯"],["C","鞘磷脂"],["D","胆固醇"],["E","前列腺素"]],"E","亚油酸、α-亚麻酸及花生四烯酸称为人体的必需脂肪酸，它们不能由人体合成，只能从食物中获得。前列腺素（E对）、血栓噁烷、白三烯是花生四烯酸的衍生物（七版生物化学P136-P137），因此去脂膳食的大鼠可以引起这些物质缺乏。磷脂酰胆碱（A错）、甘油三酯（B错）、鞘磷脂（C错）、胆固醇（D错）均可在体内合成。","","N"],["1999-N28",8,"第3节 嘧啶核苷酸的合成与分解代谢","dTMP的生成",1999,28,"A","","dTMP是由下列哪种核苷酸直接转变而来",[["A","TMP"],["B","TDP"],["C","dUDP"],["D","dUMP"],["E","dCMP"]],"D","脱氧核糖核苷酸的生成主要是在二磷酸核苷水平进行的，即NDP→dNDP（N代表A、G、U、C等碱基）。但脱氧胸腺嘧啶核苷酸的合成是在一磷酸核苷水平进行的：dTMP是由dUMP（D对）经甲基化而生成。","","N"],["1999-N29",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物前体RNA加工过程概的概述",1999,29,"A","","真核生物转录生成的mRNA前体的加工过程不包括",[["A","5'末端加帽"],["B","3'末端加多聚A尾"],["C","甲基化修饰"],["D","磷酸化修饰"],["E","剪接去除内含子并连接外显子"]],"D","真核生物转录生成的RNA分子是mRNA前体hnRNA，hnRNA需要经过5＇末端加帽（A对）、3＇末端加多聚A尾（B对）、剪接去除内含子并连接外显子（E对）等转录后加工过程，才能成为具有功能的成熟的mRNA。hnRNA的5'-端所加的帽子结构含7-甲基鸟嘌呤，其中的7-甲基系在加帽过程中经甲基化修饰（甲基转移酶催化）（C对）而来。磷酸化修饰（RNA聚合酶Ⅱ CTD尾的磷酸化）（十版生物化学P279，P280）在转录生成的 mRNA 前体的起始过程中（转录起始）发挥关键作用（D 错，为本题正确答案）。","","N"],["1999-N30",18,"第2节 DNA损伤修复","切除修复",1999,30,"A","","下列哪种酶不参加DNA的切除修复过程",[["A","DNA聚合酶Ⅰ"],["B","DNA聚合酶Ⅲ"],["C","AP核酸内切酶"],["D","DNA连接酶"],["E","蛋白质UvrA、UvrB等"]],"B","DNA的切除修复主要包括碱基切除修复和核苷酸切除修复两种类型。其中碱基切除修复过程主要包括四步：①识别水解：DNA 糖苷酶（八版教材名为DNA 糖基化酶）特异性识别DNA链中已受损的碱基并将其水解去除，产生一个无碱基位点（AP位点）；②切除：由 AP 核酸内切酶（C对）识别AP位点，切除受损的核苷酸；③合成：DNA聚合酶在缺口处以另一条链为模板修补合成互补序列；④连接：由DNA连接酶（D对）将切口重新连接，使DNA恢复正常结构。蛋白质UvrA、UvrB（七版生物化学P263）等（E对）与紫外线所致DNA损伤的切除修复有关，属核苷酸切除修复。DNA聚合酶Ⅰ和DNA聚合酶 Ⅲ均为原核生物的DNA聚合酶（十版生物化学P259），DNA聚合酶Ⅰ主要负责DNA复制的校对及切除修复过程（A对），DNA聚合酶 Ⅲ参与了大肠杆菌DNA复制的错配修复（十版生物化学P410）（B对）。参考答案为B，根据十版教材无正确答案。","","N"],["1999-N31",13,"第5节 蛋白质合成的干扰和抑制","影响成肽的抗生素",1999,31,"A","","氯霉素可抑制原核生物的蛋白质合成，其原因是",[["A","特异地抑制肽链延长因子2（eEF-2）的活性"],["B","与核蛋白体的大亚基结合，抑制转肽酶活性，而阻断翻译延长过程"],["C","活化一种蛋白激酶，从而影响起始因子2（eIF-2）磷酸化"],["D","间接活化一种核酸内切酶使mRNA降解"],["E","阻碍氨基酰tRNA与核蛋白体小亚基结合"]],"B","氯霉素可与原核生物核蛋白体（核糖体）的50S大亚基结合，抑制转肽酶活性，从而阻断翻译延长过程（B对）。抑制肽链延长因子2（eEF-2）活性的是白喉毒素（十版生物化学P313）（A错）。活化一种蛋白激酶，从而影响起始因子（eIF）磷酸化的是干扰素（C错）。间接活化一种核酸内切酶使mRNA降解的也是干扰素（D错）。阻碍氨基酰tRNA与核蛋白体小亚基结合（进位）的是四环素（十版生物化学P313）（E错）。","","N"],["1999-N32",22,"第3节 血细胞物质代谢","红细胞获得能量的途径",1999,32,"A","","成熟红细胞中能量主要来源于",[["A","糖有氧氧化"],["B","糖酵解"],["C","糖异生作用"],["D","脂酸氧化"],["E","氨基酸分解代谢"]],"B","成熟的红细胞没有线粒体，无法进行糖的有氧氧化，只能依靠糖酵解（B对）的方式为自身提供能量。","","N"],["1999-N97",5,"第5节 胆固醇代谢","胆固醇的转化",1999,97,"B","","在体内可转变生成胆汁酸的原料是",[["A","胆汁"],["B","胆固醇"],["C","胆绿素"],["D","血红素"],["E","胆素"]],"B","胆固醇（B对）在肝可被转化成胆汁酸，这是胆固醇在体内的主要代谢去路。血红素（十版生物化学P472）（D错）的代谢产物为胆色素，胆色素包括胆绿素（C错）、胆红素、胆素原和胆素（E错），主要随胆汁（A错）排出体外。","","N"],["1999-N98",21,"第4节 胆色素的代谢与黄疸","胆红素来源",1999,98,"B","","在体内可转变生成胆色素的原料是",[["A","胆汁"],["B","胆固醇"],["C","胆绿素"],["D","血红素"],["E","胆素"]],"D","胆色素包括胆绿素（C错）、胆红素、胆素原和胆素（E错），其中胆红素为人体内最主要的胆色素，胆红素的生成过程主要为：衰老的红细胞被单核细胞吞噬后，释放出血红蛋白，随后血红蛋白分解产生血红素，血红素（D对）由单核吞噬系统降解生成胆红素。胆固醇（B错）是体内生成胆汁酸（十版生物化学P472）的原料。","","N"],["1999-N123",4,"第5节 糖原的合成与分解","糖原合成",1999,123,"C","","糖原合成时需要的是",[["A","GTP"],["B","ATP"],["C","两者都需要"],["D","两者都不需要"]],"B","糖原合成是指由葡萄糖生成糖原的过程，主要发生在肝脏和骨骼肌。糖原合成的过程：①葡萄糖磷酸化为葡糖-6-磷酸，反应消耗1分子ATP（B对）；②葡糖-6-磷酸变构为葡糖-1-磷酸；③葡糖-1-磷酸活化为UDPG，反应消耗一份子UTP；④UDPG连接形成直链和支链。GTP（A错）可以为肽链的生物合成过程（十版生物化学P303）提供能量。","","N"],["1999-N124",13,"第2节 蛋白质合成体系","蛋白质合成所需酶类和蛋白质因子",1999,124,"C","","蛋白质生物合成时需要的是",[["A","GTP"],["B","ATP"],["C","两者都需要"],["D","两者都不需要"]],"C","蛋白质合成是一个耗能过程：氨基酸被活化为氨基酰-tRNA时需要消耗1分子ATP（B对）的2个高能磷酸键（ATP→AMP）；翻译延长过程的进位和转位各需要消耗1分子GTP（A对）的1个高能磷酸键（GTP→GDP）；翻译终止过程需要消耗1分子GTP（A对）的1个高能磷酸键（GTP→GDP）。本题AB均对，正确答案为C。","","N"],["1999-N125",5,"第3节 甘油三酯代谢","脂肪酸合成的调节",1999,125,"C","","能促进脂肪酸合成的是",[["A","柠檬酸"],["B","乙酰CoA"],["C","两者都是"],["D","两者都不是"]],"C","脂肪酸合成的关键酶是乙酰CoA羧化酶，柠檬酸（A对）是乙酰CoA羧化酶的别构激活剂，可以促进脂肪酸的合成。乙酰CoA（B对）是脂肪酸合成的原料，可促进脂肪酸合成。本题AB均对，正确答案为C。","","N"],["1999-N126",5,"第3节 甘油三酯代谢","脂肪酸合成的调节",1999,126,"C","","能抑制脂肪酸合成的是",[["A","柠檬酸"],["B","乙酰CoA"],["C","两者都是"],["D","两者都不是"]],"D","脂肪酸合成的关键酶是乙酰CoA羧化酶，柠檬酸（A错）是乙酰CoA羧化酶的别构激活剂，可以促进脂肪酸的合成。乙酰CoA（B错）是脂肪酸合成的原料，可促进脂肪酸合成。本题AB均错，正确答案为D。","","N"],["1999-N143",22,"第2节 血红素的合成","血红素的原料",1999,143,"X","","甘氨酸参与的代谢过程有",[["A","肌酸的合成"],["B","嘌呤核苷酸的合成"],["C","嘧啶核苷酸的合成"],["D","血红素的合成"]],"ABD","肌酸（A对）的合成原料包括甘氨酸、精氨酸和S-腺苷甲硫氨酸。嘌呤核苷酸（B对）的合成原料包括5-磷酸核糖、甘氨酸、天冬氨酸、谷氨酰胺、CO₂、一碳单位（由N¹⁰-甲酰四氢叶酸提供）等。血红素（D对）的合成原料包括琥珀酰CoA、甘氨酸和Fe²⁺。嘧啶核苷酸（C错）的合成原料包括5-磷酸核糖、谷氨酰胺、CO₂、天冬氨酸、一碳单位（由N⁵，N¹⁰-亚甲四氢叶酸提供，合成dTMP所需）等。","","N"],["1999-N144",7,"第1节 生物氧化与能量代谢","物质能量代谢的概述",1999,144,"X","","下列哪些化合物属于高能磷酸化合物",[["A","1，6-二磷酸果糖"],["B","磷酸烯醇式丙酮酸"],["C","三磷酸肌醇"],["D","磷酸肌酸"]],"BD","含有高能磷酸键的化合物可记忆为以下三种：①NTP、NDP；②可进行底物水平磷酸化的化合物，如1，3-二磷酸甘油酸、磷酸烯醇式丙酮酸（B对）；③磷酸肌酸（D对）。1，6二磷酸果糖（十版生物化学P108）分子中第1、6位是磷酸酯键，而不是高能磷酸键，不属于高能磷酸化合物（A错）。三磷酸肌醇（十版生物化学P394）即IP₃，为细胞内的信号转导分子，其1、4、5位是磷酸酯键，不含高能磷酸键，不属于高能磷酸化合物（C错）。","","N"],["1999-N145",5,"第3节 甘油三酯代谢","酮体的概述",1999,145,"X","","酮体是脂肪酸在肝脏氧化分解时的正常中间代谢产物，它包括",[["A","乙酰乙酸"],["B","β-羟丁酸"],["C","丙酮酸"],["D","乙酰CoA"]],"AB","酮体以脂肪酸在肝内β-氧化产生的乙酰CoA（D错）为原料合成而来，包括乙酰乙酸（A对）、β-羟丁酸（B对）和丙酮。丙酮酸（十版生物化学P108）（C错）是糖氧化分解的中间产物。","","N"],["1999-N146",17,"第2节 细胞内信号转导分子","第二信使的概述",1999,146,"X","","参与细胞内信息传递的第二信使物质有",[["A","cAMP"],["B","Ca²⁺"],["C","DG（DAG）"],["D","IP₃"]],"ABCD","第二信使是指外源信息在细胞内的信号转导分子，包括：环腺苷酸（cAMP）（A对）、Ca²⁺（B对）、甘油二酯（DAG）（C对）、三磷酸肌醇（IP₃）（D对）、环鸟苷酸（cGMP）、磷脂酰肌醇-3，4，5-三磷酸（PIP₃）等。","","N"],["2000-N19",0,"第1节 蛋白质的分子组成","氨基酸的分类",2000,19,"A","","下列哪一种氨基酸是亚氨基酸",[["A","赖氨酸"],["B","脯氨酸"],["C","组氨酸"],["D","色氨酸"],["E","异亮氨酸"]],"B","20种基本氨基酸中仅脯氨酸是亚氨基酸（B对），它所含有的α-氨基是-NH（亚氨基）而非-NH₂（氨基），该亚氨基与相邻的C原子构成环状结构，使得N在杂环中移动的自由度受限制，但仍能与另一羧基形成肽键，故其也参与蛋白质的合成，常见于β-转角的结构中。羟脯氨酸是脯氨酸修饰而来，是另一种亚氨基酸。","","N"],["2000-N20",0,"第5节 蛋白质的分离、纯化与结构分析","层析",2000,20,"A","","下列蛋白质通过凝胶过滤层析时最先被洗脱的是",[["A","马肝过氧化氢酶（相对分子质量247500）"],["B","肌红蛋白（相对分子质量16900）"],["C","人血清清蛋白（相对分子质量68500）"],["D","牛β-乳球蛋白（相对分子质量35000）"],["E","牛胰岛素（相对分子质量5733）"]],"A","凝胶过滤层析，又称为分子筛层析，是一种根据蛋白质分子大小不同对蛋白质进行分离的方法。它的层析柱中充满了不同大小孔径的凝胶颗粒，层析时，将蛋白质溶液从柱顶灌注，小分子蛋白质可以通过小孔进入颗粒中，流动较慢，而大分子分子量越大，进入凝胶颗粒的可能性越小，流动的速度也越快，因此最先被洗脱的是分子量最大的蛋白质，即马肝过氧化氢酶（A对）。","","N"],["2000-N21",2,"第2节 DNA和空间结构与功能","DNA双螺旋的相关实验",2000,21,"A","","下列关于DNA双螺旋结构模型的叙述正确的是",[["A","由两条完全相同的多核苷酸链绕同一中心轴盘旋成双螺旋"],["B","一条链是左手螺旋，另一条链为右手螺旋"],["C","A＋G与C＋T的比值为1"],["D","A＋T与G＋C的比值为1"],["E","两条链的碱基间以共价键相连"]],"C","DNA双螺旋结构由两条反向平行（A错）的多核苷酸链绕同一中心轴盘旋而成，两条链均为右手螺旋结构（B错）。两条链的碱基之间以氢键相结合（E错），碱基之间的配对方式为A-T和C-G，因此A＋G与C＋T的比值为1（C对D错）。","","N"],["2000-N22",1,"第1节 酶的分子结构与功能","酶的活性中心",2000,22,"A","","下列关于酶活性中心的叙述中正确的是",[["A","所有酶的活性中心都含有辅酶"],["B","所有酶的活性中心都含有金属离子"],["C","酶的必需基团都位于活性中心内"],["D","所有的抑制剂都作用于酶的活性中心"],["E","所有的酶都有活性中心"]],"E","酶的活性中心是指酶分子中真正起催化作用的部位，所有的酶都有活性中心（E对），没有活性中心就无法起到催化作用。只有结合酶才有辅助因子（包括辅酶和金属离子）（AB错）。酶分子中与活性密切有关的基团称为必需基团，有的必需基团位于活性中心内，有的必需基团位于活性中心外（C错）。抑制剂可与酶活性中心或活性中心之外的调节位点结合（D错），从而抑制酶的活性。","","N"],["2000-N23",1,"第3节 酶促反应动力学","米氏方程(1)",2000,23,"A","","已知某酶Km值为0.05mol/L，欲使其所催化的反应速率达最大反应速率的80%时，底物浓度应是多少",[["A","0.04mol/L"],["B","0.05mol/L"],["C","0.1mol/L"],["D","0.2mol/L"],["E","0.8mol/L"]],"D","米氏方程V=Vmax[S]/（Km+[S]），式中V为反应速率，Vmax为最大反应速率，[S]为底物浓度，Km为米氏常数，其值等于酶促反应速率为最大速率一半时的底物浓度。根据题意可知，Km=0.05mol/L，V=80%Vmax，代入米氏方程可推出底物浓度[S]为0.2mol/L（D对）。","","N"],["2000-N24",4,"第3节 糖的有氧氧化","糖分解供能的主要方式",2000,24,"A","","1mol丙酮酸被彻底氧化生成二氧化碳和水，同时可生成ATP的摩尔数是",[["A","12"],["B","13"],["C","14"],["D","15"],["E","16"]],"D","丙酮酸彻底氧化过程中的产能步骤：①丙酮酸→乙酰CoA（NADH+H⁺）；②异柠檬酸→α-酮戊二酸（NADH+H⁺）；③α-酮戊二酸→琥珀酰CoA（NADH+H⁺）；④琥珀酰CoA→琥珀酸（1个GTP或ATP，相当于1个ATP）；⑤琥珀酸→延胡索酸（FADH₂）；⑥苹果酸→草酰乙酸（NADH+H⁺）。按七、八、九、十版生物化学教材，1分子NADH+H⁺的氢传递给氧时，可生成2.5个ATP，1分子FADH₂的氢被氧化时，可生成1.5个ATP，丙酮酸彻底氧化分解共生成12.5分子ATP。六版及以前的教材认为1分子NADH+H⁺的氢传递给氧时，可生成3个ATP，1分子FADH₂的氢被氧化时，可生成2个ATP，因此原答案为15分子ATP（D对），按照最新版教材答案应为12.5分子ATP。","","N"],["2000-N25",5,"第3节 甘油三酯代谢","软脂酸合成的过程",2000,25,"A","","乙酰CoA羧化酶的别构抑制剂是",[["A","柠檬酸"],["B","异柠檬酸"],["C","AMP"],["D","乙酰CoA"],["E","长链脂酰CoA"]],"E","乙酰CoA羧化酶是脂肪酸合成的关键酶，其别构抑制剂为软脂酰CoA及其他长链脂酰CoA（E对）。柠檬酸（A错）和异柠檬酸（B错）为乙酰CoA羧化酶的别构激活剂。乙酰CoA（D错）是脂肪酸合成的原料，对乙酰CoA羧化酶也有别构激活作用。AMP（C错）可激活AMPK（一种能被AMP激活的蛋白激酶），AMPK可使乙酰CoA羧化酶磷酸化而失活（化学修饰调节）。","","N"],["2000-N26",5,"第3节 甘油三酯代谢","软脂酸的合成",2000,26,"A","","下列有关脂肪酸合成的叙述错误的是",[["A","脂肪酸合成酶系存在于胞液中"],["B","生物素是参与合成的辅助因子之一"],["C","合成时需要NADPH"],["D","合成过程中不消耗ATP"],["E","丙二酰CoA是合成的中间代谢物"]],"D","脂肪酸在胞液中合成（A对），其具体合成过程为：①乙酰CoA在乙酰CoA羧化酶的催化下羧化为丙二酸单酰CoA（E对），此反应需要消耗一分子ATP（D错，为本题正确答案），催化此反应的酶为乙酰CoA羧化酶（脂肪酸合成的关键酶），该酶以Mn²⁺为激活剂，含生物素辅基（B对），起转移羧基作用。②以丙二酸单酰CoA为基本原料，经缩合、加氢、脱水、再加氢的基本反应循环合成脂肪酸，其中加氢反应需要NADPH+H⁺参与（十版生物化学P153 图8-6 软脂酸的生物合成）（C对）。","","N"],["2000-N27",6,"第3节 氨的代谢","谷氨酰胺",2000,27,"A","","氨在血中主要是以下列哪种形式运输的",[["A","谷氨酸"],["B","天冬氨酸"],["C","谷氨酰胺"],["D","天冬酰胺"],["E","谷胱甘肽"]],"C","氨是体内的有毒物质，各组织必须以无毒的形式通过血液将氨运输到肝脏代谢。氨可以通过丙氨酸-葡萄糖循环将氨转变为丙氨酸从骨骼肌运往肝，也可以通过谷氨酰胺（C对）从脑和骨骼肌运往肝或肾。","","N"],["2000-N28",4,"第4节 戊糖磷酸途径","氧化阶段",2000,28,"A","","最直接联系核苷酸合成与糖代谢的物质是",[["A","葡萄糖"],["B","6-磷酸葡萄糖"],["C","1-磷酸葡萄糖"],["D","1，6-二磷酸果糖"],["E","5-磷酸核糖"]],"E","5-磷酸核糖是磷酸戊糖途径第一阶段的代谢产物，也是核苷酸从头合成（十版生物化学P218）必须的原料，因此最直接联系核苷酸与糖代谢的物质是5-磷酸核糖（E对）。","","N"],["2000-N29",11,"第4节 真核生物DNA复制过程","真核生物DNA复制的延长",2000,29,"A","","下列关于真核生物DNA复制特点的描述错误的是",[["A","RNA引物较小"],["B","冈崎片段较短"],["C","片段连接时由ATP供给能量"],["D","在复制单位中，DNA链的延长速度较慢"],["E","仅有一个复制起点"]],"E","真核生物DNA复制是多复制子复制，每一条DNA上都有多个复制起点（E错，为本题正确答案）。与原核生物（单复制子复制）相比，真核生物多复制子复制的复制子较小，引物和后随链的冈崎片段均较短（AB对）。片段（冈崎片段）连接由连接酶催化（生成磷酸二酯键），此过程需要ATP供给能量（C对）。真核生物DNA复制酶的催化速率远比原核生物慢，因而其DNA链的延长速度较慢（D对），但因真核生物是多复制子复制，总体速度并不比原核生物慢。","","N"],["2000-N30",13,"第2节 蛋白质合成体系","遗传密码的特点",2000,30,"A","","AUC为异亮氨酸的遗传密码，在tRNA中其相应的反密码应为",[["A","UAG"],["B","TAG"],["C","GAU"],["D","GAT"],["E","IAG"]],"C","mRNA上的遗传密码与tRNA上的反密码是互补配对且方向相反的，根据碱基配对规律（A-U、C-G）可知，遗传密码为AUC时，其相应的反密码应为GAU（C对）。","","N"],["2000-N31",14,"第2节 原核基因表达调控","乳糖操纵子的结构",2000,31,"A","","乳糖操纵子中的Ⅰ基因编码产物是",[["A","β-半乳糖苷酶"],["B","通透酶"],["C","乙酰基转移酶"],["D","一种激活蛋白"],["E","一种阻遏蛋白"]],"E","大肠杆菌（E.coli）的乳糖操纵子含Z、Y及A三个结构基因，分别编码β-半乳糖苷酶（A错）、通透酶（B错）和乙酰基转移酶（C错），此外还有一个操纵序列O、一个启动子P、及一个调节基因Ⅰ。Ⅰ基因具有独立的启动子，可以编码一种阻遏蛋白（E对D错），后者与O序列结合，使操纵子受阻遏而处于关闭状态。","","N"],["2000-N32",22,"第3节 血细胞物质代谢","红细胞内的糖无氧氧化的特殊途径",2000,32,"A","","下列关于2，3-BPG（2，3-二磷酸甘油酸）的叙述错误的是",[["A","其在红细胞中含量高"],["B","是由1，3-二磷酸甘油酸转变生成的"],["C","2，3-BPG经水解，脱去磷酸后生成3-磷酸甘油酸"],["D","2，3-BPG是一种高能磷酸化合物"],["E","它能降低Hb对氧的亲和力"]],"D","在普通细胞，糖酵解的中间产物1，3-二磷酸甘油酸（1，3-BPG）在磷酸甘油激酶催化下生成3-磷酸甘油酸，在此过程中1，3-BPG将高能磷酸键及磷酸基转移给ADP生成ATP，完成糖酵解过程中的第一次底物水平磷酸化。在红细胞，1，3-二磷酸甘油酸可在二磷酸甘油变位酶的催化下转变成2，3-二磷酸甘油酸（2，3-BPG）（B对），后者再经水解，脱去磷酸转变成3-磷酸甘油酸（C对）。2，3-BPG在红细胞内含量高（A对），是红细胞内能量的储存形式（红细胞内无糖原储存），但2，3-BPG本身不含高能磷酸键，不属于高能磷酸化合物（但1，3-BPG属于高能磷酸化合物）（D错，为本题正确答案）。2，3-BPG在红细胞内主要的功能是调节血红蛋白运氧，可以降低血红蛋白与O₂的亲和力，促进氧气的释放（E对）。","","N"],["2000-N97",8,"第3节 嘧啶核苷酸的合成与分解代谢","氨基酸及叶酸类似物",2000,97,"B","","干扰dUMP转变生成dTMP的是",[["A","6-巯基嘌呤"],["B","甲氨蝶呤"],["C","氮杂丝氨酸"],["D","别嘌呤醇"],["E","阿糖胞苷"]],"B","甲氨蝶呤（十版生物化学P226）（B对）是叶酸的类似物，可抑制二氢叶酸还原酶，使叶酸不能还原成二氢叶酸及四氢叶酸，从而阻断一碳单位的正常供应，使dUMP不能利用一碳单位甲基化而生成dTMP。6-巯基嘌呤（十版生物化学P223）（A错）是次黄嘌呤类似物，可抑制嘌呤核苷酸的合成。别嘌呤醇（十版生物化学P224） （D错）也是次黄嘌呤类似物，可抑制嘌呤核苷酸代谢产物尿酸的生成。氮杂丝氨酸（十版生物化学P223）（C错）是谷氨酰胺类似物，可抑制嘌呤核苷酸和胞嘧啶核苷酸的合成。阿糖胞苷（十版生物化学P226）（E错）是胞苷（胞嘧啶核苷）的类似物，可抑制CDP还原成dCDP。","","N"],["2000-N98",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸分解代谢的终产物",2000,98,"B","","抑制黄嘌呤氧化酶的是",[["A","6-巯基嘌呤"],["B","甲氨蝶呤"],["C","氮杂丝氨酸"],["D","别嘌呤醇"],["E","阿糖胞苷"]],"D","黄嘌呤氧化酶为催化嘌呤核苷酸分解代谢的酶，黄嘌呤氧化酶可催化次黄嘌呤生成黄嘌呤，进而可催化黄嘌呤生成尿酸排出体外。别嘌呤醇（D对）是次黄嘌呤的类似物，因此可竞争性抑制黄嘌呤氧化酶，从而抑制尿酸的生成。6-巯基嘌呤（十版生物化学P223）（A错）也是次黄嘌呤的类似物，可抑制PRPP酰胺转移酶、次黄嘌呤-鸟嘌呤磷酸核糖转移酶等多种合成次黄嘌呤或以次黄嘌呤为底物合成其他嘌呤的酶。甲氨蝶呤（十版生物化学P226）（B错）是叶酸的类似物，可抑制二氢叶酸还原酶，使叶酸不能还原成二氢叶酸及四氢叶酸。氮杂丝氨酸（十版生物化学P223）（C错）是谷氨酰胺类似物，可抑制嘌呤核苷酸和胞嘧啶核苷酸的合成。阿糖胞苷（十版生物化学P226）（E错）是胞苷（胞嘧啶核苷）的类似物，可抑制CDP还原成dCDP。","","N"],["2000-N123",11,"第4节 真核生物DNA复制过程","端粒酶参与解决染色体末端复制",2000,123,"C","","一种由RNA和蛋白质组成的酶是",[["A","核酶（ribozyme）"],["B","端粒酶"],["C","二者都是"],["D","二者都不是"]],"B","端粒酶是由RNA和蛋白质（B对）组成的复合体，由模板RNA、协同蛋白和逆转录酶三部分组成。核酶（ribozyme）（十版生物化学P71）是细胞内具有催化功能的一类小分子RNA（A错），具有催化特定RNA降解的活性，在RNA的剪接修饰中具有重要作用。","","N"],["2000-N124",11,"第4节 真核生物DNA复制过程","端粒酶参与解决染色体末端复制",2000,124,"C","","属于一种特殊的反转录酶的是",[["A","核酶（ribozyme）"],["B","端粒酶"],["C","二者都是"],["D","二者都不是"]],"B","端粒酶是一种特殊的反转录酶（逆转录酶）（B对），该酶能结合到端粒上，以自身的RNA为模板逆转录合成端粒DNA。核酶（ribozyme）（十版生物化学P71）是细胞内具有催化功能的一类小分子RNA，具有催化特定RNA降解的活性，但不具有逆转录的功能（A错）。","","N"],["2000-N125",5,"第4节 磷脂代谢","甘油二酯合成途径",2000,125,"C","","甘油三酯合成时的中间产物是",[["A","磷脂酸"],["B","CDP-甘油二酯"],["C","二者都是"],["D","二者都不是"]],"A","甘油三酯的合成途径有两条，即甘油一酯途径和甘油二酯途径。甘油一酯途径主要发生在小肠黏膜细胞，利用消化吸收的甘油一酯和脂肪酸合成甘油三酯；甘油二酯途径主要发生在肝和脂肪细胞，利用糖酵解途径生成的3-磷酸甘油，在脂酰CoA转移酶的作用下，依次加上三分子脂酰CoA合成甘油三酯，合成过程为：3-磷酸甘油→1-脂酰-3-磷酸甘油→磷脂酸（A对）→1，2-甘油二酯→甘油三酯。CDP-甘油二酯（十版生物化学P157）是肌醇磷脂、丝氨酸磷脂及心磷脂合成时的中间产物（B错）。","","N"],["2000-N126",5,"第4节 磷脂代谢","CDP-甘油二酯合成途径",2000,126,"C","","磷脂酰肌醇合成时的中间产物是",[["A","磷脂酸"],["B","CDP-甘油二酯"],["C","二者都是"],["D","二者都不是"]],"C","磷脂酰肌醇（肌醇磷脂）通过CDP-甘油二酯途径合成：葡萄糖→3-磷酸甘油→磷脂酸（+CTP）（A对）→CDP-甘油二酯（+肌醇）（B对）→磷脂酰肌醇。本题AB均对，正确答案为C。","","N"],["2000-N143",4,"第6节 糖异生","糖异生的概述",2000,143,"X","","哺乳动物肝内能进行糖异生的物质是",[["A","软脂酸"],["B","丝氨酸"],["C","甘油"],["D","亮氨酸"]],"BC","乳酸，甘油（C对），氨基酸等非糖化合物转变为糖的过程称为糖异生。根据代谢产物的不同可以将氨基酸分为三类①生酮氨基酸，包括亮氨酸、赖氨酸（口诀同样来）；②生酮兼生糖氨基酸，包括异亮氨酸、苯丙氨酸、酪氨酸、色氨酸、苏氨酸（口诀一本落色书）；③生糖氨基酸，包括除上述两类之外的所有氨基酸。因此丝氨酸是生糖氨基酸，可以异生为糖（B对），而亮氨酸是生酮氨基酸，不能异生为糖（D错）。软脂酸的主要分解产物是乙酰CoA（注意脂肪酸与甘油三酯的区别，后者的分解产物包括甘油和脂肪酸，而甘油是可以进行糖异生的），乙酰CoA不能转变为丙酮酸，因此不能进行糖异生（A错）。","","N"],["2000-N144",5,"第4节 磷脂代谢","甘油磷脂的降解",2000,144,"X","","溶血卵磷脂是由",[["A","磷脂酶A₁催化卵磷脂水解后生成"],["B","磷脂酶C催化卵磷脂水解后生成"],["C","磷脂酶D催化卵磷脂水解后生成"],["D","卵磷脂胆固醇脂酰转移酶催化卵磷脂进行脂酰基转移后生成的"]],"AD","磷脂酶A₁、A₂可分别水解甘油磷脂的1、2位酯键，并分别产生溶血磷脂2和溶血磷脂1，当甘油磷脂为卵磷脂时，水解产物为溶血卵磷脂（A对）。卵磷脂胆固醇脂酰转移酶（LCAT）存在于血浆中，可催化卵磷脂的2位脂酰基转移至胆固醇3位羟基生成溶血卵磷脂及胆固醇酯（D对）。磷脂酶C催化卵磷脂水解（水解甘油磷脂中3位磷酸酯键）后生成的是甘油二酯（B错）。磷脂酶D催化卵磷脂水解（水解甘油磷脂中磷酸取代基酯键）后生成的是磷脂酸（C错）。","","N"],["2000-N145",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸分解代谢的终产物",2000,145,"X","","尿酸是下列哪些化合物分解代谢的终产物",[["A","AMP"],["B","CMP"],["C","GMP"],["D","IMP"]],"ACD","尿酸是人体嘌呤分解代谢的终产物，故AMP（腺嘌呤核苷酸）（A对）、GMP（鸟嘌呤核苷酸）（C对）和IMP（次黄嘌呤核苷酸）（D对）最终均可分解代谢为尿酸。CMP（胞嘧啶核苷酸）（B错）分解代谢的终产物是尿素、CO₂、H₂O等（β-丙氨酸为胞嘧啶分解代谢的中间产物）（十版生物化学P227）。","","N"],["2000-N146",21,"第2节 肝的生物转化作用","肝生物转化的过程",2000,146,"X","","肝中进行生物转化时，较常见的结合物是",[["A","乙酰CoA"],["B","葡糖醛酸"],["C","谷胱甘肽"],["D","3'-磷酸腺苷5'-磷酰硫酸"]],"ABCD","肝中进行的生物转化可分为两相反应（十版生物化学P463），第一相反应包括氧化、还原和水解，第二相反应为结合反应。结合反应中最常见的结合物是葡萄糖醛酸（B对），此外乙酰CoA（A对）、3＇-磷酸腺苷5＇-磷酰硫酸（PAPS）（D对）、谷胱甘肽（C对）、甘氨酸等也为较常见的结合物。","","N"],["2001-N19",0,"第2节 蛋白质的分子结构","蛋白质三级结构的概念",2001,19,"A","","对稳定蛋白质构象通常不起作用的是",[["A","氢键"],["B","盐键"],["C","酯键"],["D","疏水键"],["E","范德华力"]],"C","蛋白质有四级结构（构象），稳定一级结构的化学键包括肽键和二硫键，稳定二级结构的化学键主要为氢键（A对），稳定三级结构主要靠疏水键（D对）、盐键（B对）、氢键（A对）和范德华力（E对）等，稳定四级结构的化学键主要为氢键（A对）和盐键（离子键）（B对）。酯键（磷酸二酯键）为连接核苷酸骨架的化学键（稳定核苷酸构象），与稳定蛋白质构象无关（C错，为本题正确答案）。","","N"],["2001-N20",0,"第5节 蛋白质的分离、纯化与结构分析","化学方法",2001,20,"A","","常用于测定多肽N末端氨基酸的试剂是",[["A","溴化氢"],["B","丹磺酰氯"],["C","β-巯基乙醇"],["D","羟胺"],["E","过甲酸"]],"B","多肽N末端即氨基端，常由丹磺酰氯来测定，丹磺酰氯可与氨基作用生成带有荧光的丹酰衍生物，从而对多肽N末端氨基酸进行分析鉴别（B对）。溴化氢用于断裂肽链中甲硫氨酸的羧基端肽链（A错）。β-巯基乙醇和过甲酸常用于拆开二硫键（CE错）。羟胺能特异性地裂解天冬酰胺和甘氨酸之间的肽键（Asn-Gly）（D错）。","","N"],["2001-N21",2,"第1节 核酸的化学组成及其一级结构","碱基",2001,21,"A","","通常不存在RNA中，也不存在DNA中的碱基是",[["A","腺嘌呤"],["B","黄嘌呤"],["C","鸟嘌呤"],["D","胸腺嘧啶"],["E","尿嘧啶"]],"B","DNA中的碱基有腺嘌呤（A），鸟嘌呤（G），胸腺嘧啶（T），胞嘧啶（C），RNA中的碱基有腺嘌呤（A），鸟嘌呤（G），胞嘧啶（C），尿嘧啶（U）。因此不存在于RNA中，也不存在于DNA中的碱基是黄嘌呤（B对），黄嘌呤为嘌呤核苷酸分解代谢的中间产物（十版生物化学P224）。","","N"],["2001-N22",1,"第1节 酶的分子结构与功能","同工酶催化相同的化学反应",2001,22,"A","","心肌中富含的LDH同工酶是",[["A","LDH1"],["B","LDH2"],["C","LDH3"],["D","LDH4"],["E","LDH5"]],"A","同工酶是指催化相同的化学反应，但酶蛋白的分子结构、理化性质乃至免疫学性质不同的一组酶。乳酸脱氢酶（LDH）的包括LDH1、LDH2、LDH3、LDH4、LDH5共五种同工酶，由“表3-3 人体各组织器官LDH同工酶谱（活性%）”可知：LDH1主要分布在心肌，心肌内含量最多的同工酶亦为LDH1（A对）。","","N"],["2001-N23",1,"第3节 酶促反应动力学","非竞争性抑制",2001,23,"A","","非竞争性抑制剂存在时，酶促反应动力学的特点是",[["A","Km值增大，Vmax不变"],["B","Km值降低，Vmax不变"],["C","Km值不变，Vmax增大"],["D","Km值不变，Vmax降低"],["E","Km值和Vmax均降低"]],"D","非竞争性抑制剂与酶活性中心外的结合位点相结合，不影响底物与酶的结合（抑制剂和底物可同时与酶结合形成抑制剂-酶-底物复合物），即不影响底物和酶的亲和力，Km值不变（D对）。但抑制剂-酶-底物复合物不能进一步释放出产物，因此反应速度会下降，Vmax变小（D对）。","","N"],["2001-N24",4,"第2节 糖的无氧氧化","磷酸果糖激酶-1",2001,24,"A","","磷酸果糖激酶-1的别构抑制剂是",[["A","6-磷酸果糖"],["B","1，6-二磷酸果糖"],["C","柠檬酸"],["D","乙酰CoA"],["E","AMP"]],"C","磷酸果糖激酶-1是调节糖酵解流量最重要的一种酶，它是一个四聚体，受多种别构效应剂的影响：ATP和柠檬酸为其别构抑制剂（C对），AMP（E错）、ADP、果糖-1，6-二磷酸（1，6-二磷酸果糖）（B错）和果糖-2，6-二磷酸为其别构激活剂。乙酰CoA为丙酮酸脱氢酶复合体的别构抑制剂（十版生物化学P113）（D错）。","","N"],["2001-N25",5,"第1节 脂质的构成、功能及分析","脂肪酸的生物学功能",2001,25,"A","","合成前列腺素F2α的前体是",[["A","软脂酸"],["B","硬脂酸"],["C","油酸"],["D","亚麻酸"],["E","花生四烯酸"]],"E","合成前列腺素F₂α的前体是花生四烯酸（E对），前列腺素、血栓烷、白三烯都是花生四烯酸的衍生物。","","N"],["2001-N26",5,"第6节 血浆脂蛋白及其代谢","超速离心法",2001,26,"A","","血浆各种脂蛋白中，按其所含胆固醇及其酯的量从多到少的排列是",[["A","CM、VLDL、LDL、HDL"],["B","HDL、LDL、VLDL、CM"],["C","VLDL、LDL、HDL、CM"],["D","LDL、HDL、VLDL、CM"],["E","LDL、VLDL、HDL、CM"]],"D","由P165表7-5可知血浆各脂蛋白胆固醇（含胆固醇酯）含量分别为：CM（乳糜微粒）为1%～4%，VLDL（极低密度脂蛋白）为15%，LDL（低密度脂蛋白）为45%～50%，HDL（高密度脂蛋白）为20%。因此，血浆脂蛋白按胆固醇及其酯含量由多到少排列为LDL>HDL>VLDL>CM（D对）。","","N"],["2001-N27",21,"第1节 肝在物质代谢中的作用","脂质代谢",2001,27,"A","","在肝细胞受损时血中呈现活性降低的酶是",[["A","LDH"],["B","LCAT"],["C","ACAT"],["D","ALT"],["E","AST"]],"B","在肝细胞受损时，血液中呈现活性降低的酶，应同时具备以下特点：第一，由肝细胞合成；第二，合成后不在肝细胞中发挥作用，而是分泌入血后发挥作用（这是因为肝细胞受损时，在肝细胞内发挥作用的酶将大量释放入血，反而会使血中酶的活性增强）。LDH（乳酸脱氢酶）（A错）、ACAT（脂酰CoA-胆固醇脂酰转移酶）（十版生物化学P165）（C错）、ALT（谷丙转氨酶）（D错）和AST（谷草转氨酶）（E错）均由肝细胞合成，且在肝细胞内发挥作用，因此在肝细胞受损时，这些酶在血中呈现的活性升高。而LCAT（血浆卵磷脂-胆固醇脂酰转移酶）（十版生物化学P460）（B对）是在肝内合成后分泌入血发挥作用的，因此在肝细胞受损时，此酶的合成减少，释放入血的量也减少，血中呈现的酶活性降低。","","N"],["2001-N28",6,"第4节 个别氨基酸的代谢","谷氨酸脱羧生成γ-氨基丁酸",2001,28,"A","","经脱羧基作用后生成γ-氨基丁酸的是",[["A","酪氨酸"],["B","半胱氨酸"],["C","天冬氨酸"],["D","谷氨酸"],["E","谷氨酰胺"]],"D","谷氨酸（D对）在谷氨酸脱羧酶的催化下可脱去羧基生成γ-氨基丁酸（GABA）。酪氨酸（十版生物化学P191）（A错）经脱羧基作用（先被羟化为多巴再脱羧基）可生成多巴胺（多巴胺可进一步生成去甲肾上腺素和肾上腺素）。半胱氨酸（十版生物化学P190）（B错）经脱羧基作用（先被氧化为磺基丙氨酸再脱羧基）后生成牛磺酸。天冬氨酸（C错）经脱羧基作用后生成β-丙氨酸，后者是维生素泛酸的组成成分。谷氨酰胺（E错）经脱羧基作用后生成的产物为4-氨基-丁酰胺。","","N"],["2001-N29",11,"第1节 DNA复制的基本规律","DNA以半保留方式进行复制",2001,29,"A","","若将1个完全被放射性标记的双链DNA分子放于无放射性标记的环境中复制三代后，所产生的全部DNA分子中，无放射性标记的DNA分子有几个？",[["A","1个"],["B","2个"],["C","4个"],["D","6个"],["E","8个"]],"D","DNA是双链结构，因此每一次复制都将产生两倍数量的DNA分子，将一个DNA分子复制三代可以产生2³个DNA分子，即8个DNA分子。由于DNA的复制是采用半保留复制的方式，在子代DNA中一股单链从亲代完整地接受过来，另一股单链则完全重新合成，故无论复制几代，有放射性标记的DNA分子均为2个，复制三代后无放射性标记的DNA分子为8-2=6个（D对）。","","N"],["2001-N30",14,"第3节 真核基因表达调控","真核生物基因组的特点",2001,30,"A","","下列有关真核细胞mRNA的叙述，错误的是",[["A","是由hnRNA经加工后生成的"],["B","5'末端有m⁷GpppNmp帽子"],["C","3'末端有多聚A尾"],["D","该mRNA为多顺反子"],["E","成熟过程中需进行甲基化修饰"]],"D","真核生物转录生成的RNA分子是mRNA前体hnRNA。hnRNA需要经过5＇-端戴帽（m⁷GpppNmp帽子）（B对）、3＇-端加尾（多聚A尾）（C对）、剪接内含子等转录后加工过程才能生成成熟的mRNA（A对）。hnRNA的5＇-端所加的帽子结构含7-甲基鸟嘌呤，其中的7-甲基系在加帽过程中经甲基化修饰（甲基转移酶催化）（E对）而来。原核细胞的一条mRNA链可携带几个多肽链的编码信息，为多顺反子（十版生物化学P319），而真核生物的一条mRNA链只编码一条多肽链，为单顺反子（D错，为本题正确答案）。","","N"],["2001-N31",11,"第5节 逆转录","逆转录病毒的相关概念及步骤",2001,31,"A","","下列有关反转录酶的叙述，错误的是",[["A","反转录酶以mRNA为模板，催化合成cDNA"],["B","催化的DNA合成反应也是5'－3'合成方向"],["C","在催化DNA合成开始进行时不需要有引物"],["D","具有RNase活性"],["E","反转录酶没有3'－5'核酸外切酶活性，因此它无校对功能"]],"C","反转录酶可以mRNA为模板催化合成cDNA（A对），构建cDNA文库（十版生物化学P271）。具体过程为：反转录酶以mRNA为模板，在适当引物存在下（C错，为本题正确答案），催化dNTP沿5＇→3＇方向聚合生成DNA互补链（B对），产物是RNA/DNA杂化双链。然后，杂化双链中的RNA被反转录酶的RNase活性组分水解（D对），RNA分解后剩下的单链DNA再作用模板，由引物引导和反转录酶催化合成第二条DNA互补链。与RNA聚合酶（十版生物化学P263）一样，反转录酶没有3＇→5＇核酸外切酶活性，因此它无校对功能（E对），错误率较高。","","N"],["2001-N32",21,"第1节 肝在物质代谢中的作用","蛋白质合成及分解",2001,32,"A","","肝功能不良时，下列哪种蛋白质的合成受影响较小",[["A","清蛋白"],["B","凝血酶原"],["C","凝血因子V、Ⅷ、Ⅸ等"],["D","免疫球蛋白"],["E","纤维蛋白原"]],"D","肝合成大部分血浆蛋白质，清蛋白（白蛋白）（A）、凝血酶原（凝血因子Ⅱ）（B）、凝血因子V（C）、凝血因子Ⅷ（C）、凝血因子Ⅸ（C）、纤维蛋白原（凝血因子Ⅰ）（E）均由肝脏合成。免疫球蛋白（γ 球蛋白）（D ）由浆细胞合成，因此肝功能不良时，免疫球蛋白（D对）的合成受影响较小。","","N"],["2001-N97",13,"第5节 蛋白质合成的干扰和抑制","影响成肽的抗生素",2001,97,"B","","对真核及原核生物的蛋白质合成都有抑制作用的是",[["A","链霉素"],["B","氯霉素"],["C","林可霉素"],["D","嘌呤霉素"],["E","白喉毒素"]],"D","由表16-6可知，对真核及原核生物的蛋白质合成都有抑制作用的抗生素包括伊短菌素和嘌呤霉素（D对）。链霉素（A错）、氯霉素（B错）、林可霉素（C错）均只对原核生物的蛋白质合成有抑制作用。白喉毒素（十版生物化学P313）（E错）只对真核生物的蛋白质合成有抑制作用。","","N"],["2001-N98",13,"第5节 蛋白质合成的干扰和抑制","毒素及抗肿瘤药物抑制真核生物蛋白质合成",2001,98,"B","","主要抑制哺乳动物蛋白质合成的是",[["A","链霉素"],["B","氯霉素"],["C","林可霉素"],["D","嘌呤霉素"],["E","白喉毒素"]],"E","主要抑制哺乳动物（真核生物）蛋白质合成的是白喉毒素（E对），白喉毒素可使真核生物细胞蛋白质合成的延长因子eEF-2发生ADP糖基化修饰而失活。链霉素（A错）、氯霉素（B错）、林可霉素（C错）均只抑制原核生物的蛋白质合成。嘌呤霉素（D错）对真核生物及原核生物的蛋白质合成都有抑制作用。","","N"],["2001-N123",11,"第2节 DNA复制的酶学和拓扑学","原核生物的DNA聚合酶",2001,123,"C","","具有3'→5'外切酶及5'→3'外切酶活性的是",[["A","DNA聚合酶Ⅰ"],["B","DNA聚合酶Ⅲ"],["C","二者都是"],["D","二者都不是"]],"A","经典的原核生物的 DNA 聚合酶有三种，分别命名为 DNA 聚合酶Ⅰ、DNA 聚合酶Ⅱ、DNA 聚合酶Ⅲ（九版教材新增DNA 聚合酶Ⅳ和DNA 聚合酶Ⅴ两种原核生物DNA聚合酶，未提及其外切酶活性）。三种 DNA 聚合酶均有 3’→ 5’核酸外切酶活性，但只有 DNA 聚合酶Ⅰ具有 5’→ 3’外切酶活性（A 对 B 错）。","","N"],["2001-N124",11,"第2节 DNA复制的酶学和拓扑学","原核生物的DNA聚合酶",2001,124,"C","","在DNA复制中，链的延长上起重要作用的是",[["A","DNA聚合酶Ⅰ"],["B","DNA聚合酶Ⅲ"],["C","二者都是"],["D","二者都不是"]],"B","DNA pol Ⅲ（B对）是原核生物DNA链延长中起重要作用的酶，它有DNA聚合酶活性和3＇→5＇核酸外切酶活性。DNA聚合酶Ⅰ（A错）主要对复制中的错误进行校对，对复制和修复中出现的空隙进行填补（十版生物化学P260）。","","N"],["2001-N125",6,"第2节 氨基酸的一般代谢","α-酮酸转变成糖和脂质",2001,125,"C","","属于生酮氨基酸的是",[["A","Leu"],["B","Gly"],["C","二者都是"],["D","二者都不是"]],"A","根据代谢产物的不同可以将氨基酸分为三类：①生酮氨基酸：亮氨酸、赖氨酸，记忆口诀为同（酮）样（亮）来（赖）；②生酮兼生糖氨基酸：异亮氨酸，苯丙氨酸，酪氨酸，色氨酸，苏氨酸，记忆口诀为一（异）本（苯）落（酪）色（色）书（苏）；③生糖氨基酸：除了上述两类的所有氨基酸。Leu即亮氨酸，属于生酮氨基酸（A对），Gly即甘氨酸，属于生糖氨基酸（B错）。","","N"],["2001-N126",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶核苷酸从头合成途径的概述",2001,126,"C","","可作为合成嘧啶原料的是",[["A","Leu"],["B","Gly"],["C","二者都是"],["D","二者都不是"]],"D","合成嘧啶的原料包括谷氨酰胺（Gln）、天冬氨酸（Asp）、CO₂等，亮氨酸（Leu）（A错）和甘氨酸（Gly）（B错）均不属于合成嘧啶的原料。本题AB均错，正确答案为D。","","N"],["2001-N143",2,"第3节 RNA和空间结构与功能","tRNA的结构及功能",2001,143,"X","","下列关于tRNA三叶草结构的叙述，正确的是",[["A","5'端第一个环是DHU环"],["B","有一个密码子环"],["C","有一个TψC环"],["D","3'端具有相同的CCA-OH结构"]],"ACD","由十版生物化学P68图3-22可知，tRNA从5’→3’依次为DHU环（A对），反密码子环（B错）和TψC环（C对）。3’端具有相同的CCA-OH结构（D对），为氨基酸的连接位点。","","N"],["2001-N144",4,"第6节 糖异生","丙酮酸羧化支路",2001,144,"X","","天冬氨酸、乳酸和甘油异生为糖时，所经历的共同反应是",[["A","磷酸烯醇式丙酮酸→2-磷酸甘油酸"],["B","3-磷酸甘油酸→1，3-二磷酸甘油酸"],["C","3-磷酸甘油醛⇆磷酸二羟丙酮"],["D","1，6-二磷酸果糖→6-磷酸果糖"]],"CD","天冬氨酸异生为糖所经历的反应过程为：天冬氨酸→草酰乙酸→磷酸烯醇式丙酮酸→磷酸二羟丙酮（3-磷酸甘油醛）→1，6-二磷酸果糖→6-磷酸果糖→葡萄糖。乳酸异生成糖所经历的反应过程为：乳酸→丙酮酸→草酰乙酸→磷酸烯醇式丙酮酸→磷酸二羟丙酮（3-磷酸甘油醛）→1，6-二磷酸果糖→6-磷酸果糖→葡萄糖。甘油异生为糖所经历的反应过程为：甘油→3磷酸甘油→3-磷酸甘油醛（磷酸二羟丙酮）→1，6-二磷酸果糖→6-磷酸果糖→葡萄糖。因此三者所经历的共同反应为3磷酸甘油醛→磷酸二羟丙酮（C对）和1，6二磷酸果糖→6-磷酸果糖（D对）。","","N"],["2001-N145",5,"第4节 磷脂代谢","甘油二酯合成途径",2001,145,"X","","下列磷脂中，哪些含有胆碱",[["A","卵磷脂"],["B","脑磷脂"],["C","心磷脂"],["D","神经鞘磷脂"]],"AD","磷脂分为甘油磷脂和鞘磷脂两类。甘油磷脂包括卵磷脂、脑磷脂、心磷脂、肌醇磷脂、丝氨酸磷脂，其中卵磷脂（A对）又称磷脂酰胆碱，含胆碱，脑磷脂（B错）、心磷脂（C错）等其他甘油磷脂不含胆碱。鞘磷脂以神经磷脂（D对）最为常见，后者由鞘氨醇、脂肪酸及磷酸胆碱构成。","","N"],["2001-N146",16,"第2节 重组DNA技术","常用工具酶",2001,146,"X","","重组DNA技术中，常用到的酶是",[["A","限制性核酸内切酶"],["B","DNA连接酶"],["C","DNA解链酶"],["D","反转录酶"]],"ABD","重组DNA技术，又称分子克隆或DNA克隆或基因工程技术，其主要过程包括：将外源性目的DNA片段与载体连接，形成重组DNA分子，进而在受体细胞中复制、扩增，从而获得单一DNA分子的大量拷贝（十版生物化学P369）。重组DNA技术常用到的工具酶包括RE（限制性核酸内切酶）（A对）、DNA连接酶（B对）、DNA聚合酶Ⅰ、Klenow片段、逆转录酶（反转录酶）（D对）、多聚核苷酸激酶、末端转移酶、碱性磷酸酶等。DNA解链酶（C错）又称DNA解旋酶（十版生物化学P261），为内源性DNA复制过程中用来解开DNA双链的酶。","","N"],["2002-N19",0,"第1节 蛋白质的分子组成","紫外线吸收",2002,19,"A","","在280nm波长附近具有最大光吸收峰的氨基酸是",[["A","天冬氨酸"],["B","丝氨酸"],["C","苯丙氨酸"],["D","色氨酸"],["E","赖氨酸"]],"D","芳香族氨基酸因含苯环，具有共轭双键，可吸收一定波长的紫外光，其中酪氨酸和色氨酸（D对）的紫外吸收峰约为280nm，苯丙氨酸的紫外吸收峰约为260nm。天冬氨酸（A错）、丝氨酸（B错）和赖氨酸（E错）不含有共轭双键，不具有紫外吸收特性。","","N"],["2002-N20",2,"第1节 核酸的化学组成及其一级结构","核酸的一级结构",2002,20,"A","","核酸中核苷酸之间的连接方式是",[["A","2＇，3＇-磷酸二酯键"],["B","3＇，5＇-磷酸二酯键"],["C","2＇，5＇-磷酸二酯键"],["D","1＇，5＇-糖苷键"],["E","氢键"]],"B","核酸中核苷酸之间的连接方式是3＇，5＇-磷酸二酯键，脱氧核苷酸之间的连接方式同样是3＇，5＇-磷酸二酯键（B对）。碱基与碱基之间的连接方式是氢键，核糖与碱基之间的连接方式是糖苷键，核苷与磷酸之间的连接方式是酯键。","","N"],["2002-N21",9,"第3节 代谢调节的主要方式","关键酶活性决定代谢途径的速率和方向",2002,21,"A","","对酶促化学修饰调节特点的叙述，错误的是",[["A","这类酶大都具有无活性和有活性形式"],["B","这种调节是由酶催化引起的共价键变化"],["C","这种调节是酶促反应，故有放大效应"],["D","酶促化学修饰调节速度较慢，难以应急"],["E","磷酸化与脱磷酸化是常见的化学修饰方式"]],"D","酶促化学修饰调节是机体内两种（另一种为别构调节）快速调节方式之一（D错，为本题正确答案），具有如下特点：①绝大多数受化学修饰调节的关键酶都具有无活性（或低活性）和有活性（或高活性）两种形式（A对），它们可分别在两种不同酶的催化下发生共价修饰（B对），互相转变。②酶的化学修饰是另一酶催化的酶促反应，一分子催化酶可催化多个底物酶分子发生共价修饰，特异性强，有放大效应（C对）。③磷酸化与去磷酸化是最常见的酶促化学修饰反应（E对）。","","N"],["2002-N22",4,"第3节 糖的有氧氧化","三羧酸循环的过程",2002,22,"A","","在三羧酸循环中，经作用物水平磷酸化生成的高能化合物是",[["A","ATP"],["B","GTP"],["C","UTP"],["D","CTP"],["E","TTP"]],"AB","底物分子中的能量直接以高能键形式转移给 ADP 或其他二磷酸核苷（GDP）生成 ATP 或其他三磷酸核苷（GTP），这个过程称为底物水平磷酸化（十版生物化学P108）。在三羧酸循环中发生一次底物水平磷酸化，即琥珀酰CoA在琥珀酰CoA合成酶催化下生成琥珀酸，该反应是发生在线粒体的可逆反应，琥珀酰CoA的高能硫脂键水解，与 GDP 或ADP的磷酸化偶联，转变为新的高能磷酸键，最终生成 GTP或ATP（AB 对）。本考点九版之后更新考点，根据最新观点，本题的正确答案应该为AB，但八版及之前版本的教材讲解三羧酸循环的底物水平磷酸化时仅提及生成GTP（八版生物化学P121），因此给出的参考答案仅为B。","","N"],["2002-N23",5,"第6节 血浆脂蛋白及其代谢","低密度脂蛋白的功能和代谢途径",2002,23,"A","","血浆中运输内源性胆固醇的脂蛋白是",[["A","CM"],["B","VLDL"],["C","LDL"],["D","HDL₂"],["E","HDL₃"]],"C","血浆中运输内源性胆固醇的脂蛋白是LDL（低密度脂蛋白）（C对）。CM（乳糜微粒）（A错）主要转运外源性甘油三酯及胆固醇。VLDL（极低密度脂蛋白）（B错）主要转运内源性甘油三酯。HDL可按密度分为HDL₁、HDL₂及HDL₃，HDL主要逆向转运胆固醇（DE错）。","","N"],["2002-N24",7,"第2节 线粒体氧化体系与呼吸链","铁硫蛋白",2002,24,"A","","下列关于呼吸链的叙述，错误的是",[["A","在传递氢和电子过程中可偶联ADP磷酸化"],["B","CO可使整个呼吸链的功能丧失"],["C","递氢体同时也是递电子体"],["D","递电子体也都是递氢体"],["E","呼吸链的组分通常按Eo值由小到大的顺序排列"]],"D","氧化磷酸化是ATP生成的主要方式，代谢物脱下的氢，经线粒体氧化呼吸链电子传递释放能量，此释放过程与驱动ADP磷酸化生成ATP相偶联，因此氧化磷酸化又称为偶联磷酸化（A对）。氧化呼吸链是由位于线粒体内膜上的4种蛋白酶复合体组成，分别称之为复合体Ⅰ、Ⅱ、Ⅲ和Ⅳ。CO是一种呼吸链抑制剂，它可与复合体Ⅳ中还原型Cyt a₃结合，阻断电子传递给O₂，使呼吸链传递中断，因而可以使整个呼吸链电子传递功能丧失，进而使整个呼吸链氧化磷酸化功能丧失（B对）。氧化呼吸链中传递氢的酶蛋白或辅助因子称为递氢体，传递电子的则称为递电子体，由于递氢的过程也需传递电子，所以递氢体同时也是递电子体（C对）。但递电子体不一定是递氢体，如铁硫蛋白无结合氢的位点，只能传递电子，为单电子传递体（D错，为本题正确答案）。标准还原电位（E₀）是指在特定条件下，参与氧化还原反应的组分对电子的亲和力大小，电位高的组分对电子的亲和力强，易接受电子，电位低的组分易于给出电子，因此呼吸链的组分通常是按E₀值大小进行电子传递的（E对）。","","N"],["2002-N25",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶核苷酸的分解代谢的终产物",2002,25,"A","","在体内能分解生成β-氨基异丁酸的是",[["A","AMP"],["B","GMP"],["C","CMP"],["D","UMP"],["E","TMP"]],"E","β-氨基异丁酸是胸腺嘧啶分解代谢的中间产物，故在体内能分解生成β-氨基异丁酸的是TMP（胸腺嘧啶核苷酸）（E对）。","","N"],["2002-N26",13,"第2节 蛋白质合成体系","遗传密码的特点",2002,26,"A","","下列有关遗传密码的叙述，正确的是",[["A","遗传密码只代表氨基酸"],["B","一种氨基酸只有一个密码子"],["C","一个密码子可代表多种氨基酸"],["D","每个tRNA上的反密码子只能识别一个密码子"],["E","从病毒到人，丝氨酸的密码子都是AGU"]],"E","遗传密码除代表氨基酸外，还可作为起始信号和终止信号存在（A错）。一个密码子只代表一种氨基酸（C错），但一种氨基酸可对应多个密码子（B错），此为遗传密码的简并性。tRNA上的反密码子能识别mRNA序列中的多个密码子（D错），此为遗传密码的摆动性。从病毒到人都使用着同一套遗传密码，例如，丝氨酸的密码子都包括 AGU（E对），此为遗传密码的通用性。","","N"],["2002-N27",11,"第2节 DNA复制的酶学和拓扑学","多种酶参与DNA解链和稳定单链状态",2002,27,"A","","参与复制起始过程的酶中，下列哪一组是正确的",[["A","DNA-polⅠ、DNA内切酶"],["B","DNA外切酶、连接酶"],["C","RNA酶、解螺旋酶"],["D","Dna蛋白、SSB"],["E","DNA拓扑异构酶、DNA-polⅠ"]],"D","由表14-4可知，参与DNA复制起始过程的酶有Dna蛋白、SSB和拓扑异构酶（D对）。DNA聚合酶Ⅰ（十版生物化学P260）（AE错）为复制延长过程中校对、修复及复制结束后填补空隙的酶。连接酶（十版生物化学P265）（B错）为复制结束后连接缺口的酶。RNA 酶（DNA pol I）（C错）为复制结束后水解 RNA 引物的酶（十版生物化学P217）。","","N"],["2002-N28",12,"第2节 原核生物的转录","RNA聚合酶全酶",2002,28,"A","","原核生物中识别DNA模板上转录起始点的是",[["A","RNA聚合酶的核心酶"],["B","RNA聚合酶的σ亚基"],["C","RNA聚合酶的α亚基"],["D","RNA聚合酶的β亚基"],["E","ρ因子"]],"B","原核生物RNA 聚合酶为由5 种亚基 α₂ββ'ωσ 组成的六聚体蛋白质（九版之后的教材更新考点，八版为4 种亚基 α₂ββ'σ 组成的五聚体蛋白质），其中5 个主要亚基（α₂ββ′ω）称为核心酶（A错），它与σ 亚基共同称为全酶（α₂ ββ′ωσ）。各亚基的功能分别是：α 亚基（C错）决定哪些基因被转录；β 亚基（D错）促进聚合反应中磷酸二酯键的生成；β′亚基结合 DNA 模板，解开双螺旋；ω亚基与β′折叠和稳定性、σ募集等有关；σ 亚基辨认 DNA 模板上的转录起始点（B 对）。ρ 因子（Rho 因子）（十版生物化学P277）（E错）是原核生物的转录终止因子，识别的是 DNA 的转录产物 RNA 上的转录终止位点。","","N"],["2002-N29",14,"第1节 基因表达调控的基本概念与特点","基因表达调控的概念",2002,29,"A","","下列关于“基因表达”概念的叙述，错误的是",[["A","基因表达具有组织特异性"],["B","基因表达具有阶段特异性"],["C","基因表达均经历基因转录及翻译过程"],["D","某些基因表达产物是蛋白质分子"],["E","有些基因表达水平受环境变化影响"]],"C","基因表达产物包括蛋白质（D对）、rRNA、tRNA等，当表达产物为蛋白质时，基因表达需经历基因转录及翻译过程，但当表达产物为rRNA、tRNA时，基因表达只需要经历基因转录过程（C错，为本题正确答案）。多细胞生物个体在特定生长发育阶段，同一基因在不同的组织器官表达不同，即基因表达具有组织特异性（空间特异性）（A对）。基因表达按一定的时间顺序发生，即基因表达具有阶段特异性（时间特异性）（B对）。有些基因（如可诱导基因和可阻遏基因）很容易受环境变化的影响（E对），随环境信号变化，这类基因表达水平可出现升高或降低的现象（十版生物化学P316）。","","N"],["2002-N30",16,"第2节 重组DNA技术","概述",2002,30,"A","","在基因工程中，将目的基因与载体DNA拼接的酶是",[["A","DNA聚合酶Ⅰ"],["B","DNA聚合酶Ⅲ"],["C","限制性内切核酸酶"],["D","DNA连接酶"],["E","反转录酶"]],"D","DNA连接酶（D对）可催化DNA中相邻的5’-磷酸基和3’-羟基末端之间形成磷酸二酯键，从而将两个DNA片段连接起来，因此可将目的基因与载体DNA进行拼接。DNA聚合酶Ⅰ（A错）和限制性内切核酸酶（C错）亦为基因工程中的常见酶，前者可催化脱氧核苷酸间的聚合，主要用于合成双链cDNA分子、片段连接等，后者主要用于识别特异序列，切割DNA。DNA聚合酶Ⅲ（十版生物化学P265）（B错）为原核生物内源性DNA复制过程中起延长作用的酶，不用于基因工程中。","","N"],["2002-N31",17,"第2节 细胞内信号转导分子","G蛋白的作用",2002,31,"A","","G蛋白是指",[["A","蛋白激酶A"],["B","鸟苷酸环化酶"],["C","蛋白激酶G"],["D","Grb2结合蛋白"],["E","鸟苷酸结合蛋白"]],"E","G蛋白即鸟苷酸结合蛋白（E对），亦称GTP结合蛋白，是具有GTP水解酶活性的一类信号转导蛋白，由α、β、γ三个不同亚基组成。","","N"],["2002-N32",5,"第6节 血浆脂蛋白及其代谢","低密度脂蛋白的功能和代谢途径",2002,32,"A","","下列哪种不是肝在脂类代谢中的特有作用",[["A","酮体的生成"],["B","LDL的生成"],["C","VLDL的生成"],["D","胆汁酸的生成"],["E","LCAT的合成"]],"B","LDL（低密度脂蛋白）是VLDL（极低密度脂蛋白）的代谢产物，其主要生成部位在血浆（B错，为本题正确答案）。胆汁酸（十版生物化学P161）（D对）、LCAT（卵磷脂胆固醇脂酰转移酶，在肝脏生成，在血浆发挥作用）（十版生物化学P168）（E对）均在肝脏内生成。酮体（A对）和VLDL（C对）的生成主要在肝，但在其他部位也可生成，如肾可生成少量酮体，小肠黏膜细胞可生成少量VLDL，因此酮体和VLDL的生成并不是肝脏所特有的作用，本题并不严谨。","","N"],["2002-N97",1,"第1节 酶的分子结构与功能","酶的基本概念",2002,97,"B","","由于基因融合，形成由一条多肽链组成却具有多种不同催化功能的酶是",[["A","单体酶"],["B","寡聚酶"],["C","结合酶"],["D","多功能酶"],["E","单纯酶"]],"D","由于基因融合，形成由一条多肽链组成却具有多种不同催化功能的酶是多功能酶（D对）。单体酶是指由一条肽链构成的酶（A错）。寡聚酶是指由多个相同或不同亚基以非共价键连接组成的酶（B错）。结合酶（亦称为缀合酶）是指由酶蛋白和辅助因子（非蛋白质部分）组成的酶（C错）。单纯酶是指仅含有蛋白质的酶（E错）。","","N"],["2002-N98",1,"第1节 酶的分子结构与功能","酶的分子组成",2002,98,"B","","由酶蛋白和辅助因子两部分组成的酶是",[["A","单体酶"],["B","寡聚酶"],["C","结合酶"],["D","多功能酶"],["E","单纯酶"]],"C","酶按其分子组成可分为单纯酶和结合酶（缀合酶）。仅含有蛋白质的酶称为单纯酶（E错），由蛋白质部分和非蛋白质部分共同组成的酶是结合酶。其中蛋白质部分称为酶蛋白，非蛋白质部分称为辅助因子（C对）。单体酶（A错）是指只具有单一亚基或蛋白质三级结构的酶，寡聚酶（B错）是指由多个相同或不同亚基以非共价键连接的酶，多功能酶（D错）是指同一条肽链上具有多种功能的酶。","","N"],["2002-N123",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤类似物",2002,123,"C","","抑制IMP→AMP的嘌呤、嘧啶核苷酸抗代谢物的是",[["A","5-氟尿嘧啶"],["B","氮杂丝氨酸"],["C","二者均是"],["D","二者均非"]],"D","抑制IMP→AMP的嘌呤、嘧啶核苷酸抗代谢物是6-巯基嘌呤（6-MP）（因6-MP是次黄嘌呤的类似物）。5-氟尿嘧啶（5-FU）（十版生物化学P226）（A错）是胸腺嘧啶的类似物，抑制的是dUMP→dTMP。氮杂丝氨酸（十版生物化学P223）（B错）是谷氨酰胺的类似物，抑制的是IMP合成、IMP→GMP、UTP→CTP等。本题AB均错，正确答案为D。","","N"],["2002-N124",8,"第3节 嘧啶核苷酸的合成与分解代谢","氨基酸及叶酸类似物",2002,124,"C","","抑制UTP→CTP的嘌呤、嘧啶核苷酸抗代谢物的是",[["A","5-氟尿嘧啶"],["B","氮杂丝氨酸"],["C","二者均是"],["D","二者均非"]],"B","氮杂丝氨酸（B对）为谷氨酰胺类似物，可以抑制UTP→CTP（UTP从谷氨酰胺接受氨基生成CTP）。5-氟尿嘧啶（A错）的代谢物为dUMP类似物，可以抑制dUMP→dTMP。","","N"],["2002-N125",18,"第1节 DNA损伤","DNA损伤的类型",2002,125,"C","","点突变（碱基错配）可导致",[["A","氨基酸置换"],["B","读码框移"],["C","二者均有"],["D","二者均无"]],"A","点突变（碱基错配）发生在编码区可引起三联体密码子发生改变，导致氨基酸被置换（A对）。如血红蛋白β基因的第6位密码子GAG点突变为GTG，可导致谷氨酸被置换为缬氨酸，造成镰形红细胞性贫血（七版生物化学P261）。读码框移（B错）由碱基缺失或插入导致（七版生物化学P262）。","","N"],["2002-N126",18,"第1节 DNA损伤","DNA损伤的类型",2002,126,"C","","缺失或插入突变可导致",[["A","氨基酸置换"],["B","读码框移"],["C","二者均有"],["D","二者均无"]],"B","碱基缺失或插入后，插入或缺失位点以后的所有碱基位置发生后移或前移，导致三联体密码的阅读方式改变，进而其编码的氨基酸的组成和排列顺序也发生变化，称为移码突变（读码框移）（B对）。氨基酸置换由点突变（碱基错配）导致（A错）。","","N"],["2002-N143",4,"第2节 糖的无氧氧化","糖酵解关键酶的概述",2002,143,"X","","糖酵解的关键酶有",[["A","6-磷酸果糖激酶-1"],["B","丙酮酸脱氢酶复合体"],["C","丙酮酸激酶"],["D","己糖激酶"]],"ACD","糖酵解的关键酶包括己糖激酶（D对）、6-磷酸果糖激酶-1（A对）和丙酮酸激酶（C对）。丙酮酸脱氢酶复合体为丙酮酸氧化脱羧的关键酶（十版生物化学P113）（B错）。","","N"],["2002-N144",22,"第2节 血红素的合成","血红素的原料",2002,144,"X","","下列关于琥珀酰辅酶A代谢去路的叙述中，正确的是",[["A","可异生为糖"],["B","可氧化供能"],["C","是合成卟啉化合物的原料"],["D","参与酮体的氧化"]],"ABCD","琥珀酰CoA（琥珀酰辅酶A）是柠檬酸循环的中间产物，因此可通过糖的有氧氧化途径氧化供能（B对）；也可转化生成草酰乙酸后，通过糖异生途径（十版生物化学P129图7-15 糖异生）异生为糖（A对）。琥珀酰CoA是合成卟啉化合物（血红素）的原料（C对）。琥珀酰CoA可参与酮体在肝外组织的氧化利用（D对），当琥珀酰CoA存在时，乙酰乙酸可在琥珀酰CoA转硫酶的作用下活化为乙酰乙酰CoA，而后经硫解作用生成乙酰CoA，最终彻底氧化。","","N"],["2002-N145",6,"第4节 个别氨基酸的代谢","酪氨酸的代谢",2002,145,"X","","酪氨酸在体内可转变为",[["A","胆色素"],["B","肾上腺素"],["C","延胡索酸"],["D","乙酰乙酸"]],"BCD","酪氨酸的代谢途径主要有三条：①酪氨酸→多巴→多巴胺→去甲肾上腺素→肾上腺素（B对）；②酪氨酸→多巴→多巴醌→吲哚醌→黑色素；③酪氨酸→羟苯丙酮酸→尿黑酸→延胡索酸（C对）+乙酰乙酸（D对）。胆色素（十版生物化学P473）（A错）是体内铁卟啉类化合物（血红蛋白、肌红蛋白、细胞色素等）的主要分解代谢产物，与酪氨酸无关。","","N"],["2002-N146",21,"第4节 胆色素的代谢与黄疸","结合",2002,146,"X","","有关游离胆红素的叙述，正确的是",[["A","又称为间接胆红素"],["B","属脂溶性物质，易通过细胞膜对脑产生毒性作用"],["C","镇痛药及抗炎药等可降低其对脑的毒性作用"],["D","不易经肾随尿排出"]],"ABD","游离胆红素即未结合胆红素，由于分子内有氢键存在，因此不能直接与重氮试剂反应，只有在加入乙醇或尿素等破坏氢键后，才能与重氮试剂反应，故又称为间接胆红素（十版生物化学P476）（A对）。游离胆红素属脂溶性物质，易通过细胞膜对脑产生毒性作用（B对），因此在血浆中常与清蛋白结合，以胆红素-清蛋白复合体形式存在和运输，以限制游离胆红素的毒性作用，而镇痛药及抗炎药等的主要成分（如水杨酸等）可与胆红素竞争性地结合清蛋白，使胆红素游离，可增强对脑的毒性作用（C错）。游离胆红素因与清蛋白结合，不能透过肾小球滤过膜，故不易随尿排出（D对）。","","N"],["2003-N19",0,"第2节 蛋白质的分子结构","蛋白质的二级结构",2003,19,"A","","稳定蛋白质分子中α-螺旋和β-折叠的化学键是",[["A","肽键"],["B","二硫键"],["C","盐键"],["D","氢键"],["E","疏水作用"]],"D","α-螺旋和β-片层（β-折叠的旧称）均蛋白质的二级结构，维系蛋白质二级结构的主要化学键是氢键（D对）。肽键（A错）和二硫键（B错）为维系蛋白质一级结构的化学键（十版生物化学P13）。盐键（C错）为维系蛋白质三级结构的化学键（十版生物化学P17）。","","N"],["2003-N20",2,"第2节 DNA和空间结构与功能","DNA的双螺旋结构",2003,20,"A","","下列关于DNA双螺旋结构模型的叙述，不正确的是",[["A","两股脱氧核苷酸链呈反向平行"],["B","两股链间存在碱基配对关系"],["C","螺旋每周包含10对碱基"],["D","螺旋的螺距为3.4nm"],["E","DNA形成的均是左手螺旋结构"]],"E","DNA双螺旋结构的两条链呈现出反向平行的特征（A对），两条链之间的碱基以氢键相结合，形成A-T和C-G的碱基配对关系（B对）。大多数情况下，DNA两条链围绕着同一个螺旋轴形成右手螺旋的结构（B型DNA）（E错，为本题正确答案），直径为2.37nm，每个螺旋包含10.5对（C错，为本题正确答案）碱基，每个螺旋之间的距离（螺距）为3.54nm（D错，为本题正确答案）。本题的数据有更新，按最新教材的数据，C选项和D选项也不准确，但原答案为E。","","N"],["2003-N21",1,"第3节 酶促反应动力学","米氏方程(1)",2003,21,"A","","已知某种酶的Km值为25mmol/L，欲使酶促反应达到最大反应速度的50％，该底物浓度应为",[["A","12.5mmol/L"],["B","25mmol/L"],["C","37.5mmol/L"],["D","50mmol/L"],["E","75mmol/L"]],"B","米氏方程V=Vmax[S]/（Km+[S]），式中V为反应速率，Vmax为最大反应速率，[S]为底物浓度，Km为米氏常数，其值等于酶促反应速率为最大速率一半时的底物浓度。根据题意可知，Km=25mmol/L，V=50%Vmax，代入米氏方程可推出底物浓度[S]为25mol/L（B对）。","","N"],["2003-N22",4,"第2节 糖的无氧氧化","糖酵解",2003,22,"A","","下列参与糖代谢的酶中，哪种酶催化的反应是可逆的",[["A","糖原磷酸化酶"],["B","己糖激酶"],["C","果糖二磷酸酶"],["D","丙酮酸激酶"],["E","磷酸甘油酸激酶"]],"E","磷酸甘油酸激酶（E对）催化1，3-二磷酸甘油酸转变成3-磷酸甘油酸，该反应是一可逆反应。糖原磷酸化酶是糖原分解过程的关键酶（A错），己糖激酶（B错）和丙酮酸激酶（D错）是糖酵解过程的关键酶，果糖二磷酸酶（C错）是糖异生过程的关键酶，关键酶催化的反应均为不可逆反应。","","N"],["2003-N23",5,"第3节 甘油三酯代谢","酮体的氧化利用",2003,23,"A","","酮体不能在肝中氧化的主要原因是肝中缺乏",[["A","HMG-CoA合成酶"],["B","HMG-CoA裂解酶"],["C","HMG-CoA还原酶"],["D","琥珀酰CoA转硫酶"],["E","β-羟丁酸脱氢酶"]],"D","酮体包括乙酰乙酸、β-羟丁酸和丙酮。丙酮生产量很少，可经肺呼出，乙酰乙酸、β-羟丁酸则在肝外组织被氧化利用，由于β-羟丁酸的利用是先在β-羟丁酸脱氢酶催化下，脱氢生成乙酰乙酸，再转变为乙酰CoA被氧化，因此酮体的氧化主要指乙酰乙酸的氧化。乙酰乙酸的氧化有两条途径：一是在心、肾、脑及骨骼肌线粒体，由琥珀酰CoA转硫酶催化生成乙酰乙酰CoA；二是在肾、心和脑线粒体，由乙酰乙酸硫激酶催化，直接活化生成乙酰乙酰CoA。肝组织因缺乏琥珀酰CoA转硫酶（D对）和乙酰乙酸硫激酶这两种利用酮体的酶，不能利用酮体。HMG-CoA合成酶为参与酮体（十版生物化学P149）及胆固醇（十版生物化学P159）合成的酶。HMG-CoA裂解酶（十版生物化学P149）为参与酮体合成的酶。HMG-CoA还原酶（C错）为参与胆固醇合成的酶（关键酶）。","","N"],["2003-N24",6,"第4节 个别氨基酸的代谢","半胱氨酸转变为牛磺酸",2003,24,"A","","经代谢转变生成牛磺酸的氨基酸是",[["A","半胱氨酸"],["B","蛋氨酸"],["C","苏氨酸"],["D","赖氨酸"],["E","缬氨酸"]],"A","牛磺酸由半胱氨酸（A对）经氧化生成磺酸丙氨酸，再脱羧基而生成。除牛磺酸外，半胱氨酸还可以代谢生成胱氨酸、硫酸根PAPS、谷胱甘肽等多种重要的生理活性物质。","","N"],["2003-N25",7,"第4节 氧化磷酸化的影响因素","毒性气体阻断电子传递过程",2003,25,"A","","氰化物中毒是由于抑制了下列哪种细胞色素（Cyt）",[["A","Cyta"],["B","Cytaa₃"],["C","Cytb"],["D","Cytc"],["E","Cytc₁"]],"B","细胞色素是氧化呼吸链的重要组成部分，广泛存在于呼吸链各复合体中，许多化合物可作用于复合体中的细胞色素而抑制电子的传递。氰化物（CN⁻）可抑制复合体Ⅳ中细胞色素a₃（而非细胞色素a）（A错），进而抑制细胞色素aa₃复合物（阻断电子由Cyt a到CuB-Cyt a₃间传递）（B对）。氰化物抑制的是细胞色素c氧化酶（复合体Ⅳ）而不是Cyt c（D错）。抗霉素A可抑制复合体Ⅲ中细胞色素b（阻断Cyt bH到泛醌间的电子传递）（C错）。十版教材中未提及Cyt c₁的抑制剂（E错）。","","N"],["2003-N26",8,"第2节 嘌呤核苷酸的合成与分解代谢","氨基酸类似物",2003,26,"A","","氮杂丝氨酸干扰核苷酸合成是因为它的结构相似于",[["A","丝氨酸"],["B","甘氨酸"],["C","天冬氨酸"],["D","天冬酰胺"],["E","谷氨酰胺"]],"E","谷氨酰胺是嘌呤核苷酸和嘧啶核苷酸合成的共同原料之一，由于氮杂丝氨酸与谷氨酰胺（E对）的结构相似，因此氮杂丝氨酸可以干扰谷氨酰胺在核苷酸合成过程中的作用，从而干扰核苷酸的合成。","","N"],["2003-N27",18,"第1节 DNA损伤","DNA损伤的类型",2003,27,"A","","下列不属于DNA分子结构改变的是",[["A","点突变"],["B","DNA重排"],["C","DNA甲基化"],["D","碱基缺失"],["E","碱基插入"]],"C","点突变（DNA分子上的碱基错配）（A对）、DNA重排（DNA分子内较大片段的交换）（B对）、碱基缺失（D对）、碱基插入（E对）均属于DNA分子结构改变（突变）。DNA甲基化（C错，为本题正确答案）只是在碱基上发生了甲基修饰，并没有改变碱基类型，因此不会影响DNA的分子结构（没有发生突变）。","","N"],["2003-N28",12,"第3节 真核生物mRNA的转录、加工和降解","不同RNA聚合酶催化不同RNA的合成",2003,28,"A","","真核生物中，催化转录产物为hnRNA的RNA聚合酶是",[["A","RNA聚合酶核心酶"],["B","RNA聚合酶Ⅰ"],["C","RNA聚合酶Ⅱ"],["D","RNA聚合酶Ⅲ"],["E","RNA聚合酶β亚基"]],"C","真核生物主要有三种不同的 RNA 聚合酶，分别为 RNA 聚合酶Ⅰ、RNA 聚合酶Ⅱ和RNA 聚合酶Ⅲ（九版后教材新提及了植物中还存在RNA 聚合酶Ⅳ）。其中催化转录产物为hnRNA的是RNA聚合酶Ⅱ（C对）。RNA聚合酶Ⅰ（B错）催化生成的产物为rRNA的前体45S rRNA，45S rRNA再加工成28S、5.8S及18S rRNA。RNA聚合酶Ⅲ（D错）催化生成的产物为tRNA，5S rRNA和snRNA。RNA聚合酶核心酶（十版生物化学P274）（A错）和RNA聚合酶β亚基（E错）为原核生物RNA聚合酶的组成部分。","","N"],["2003-N29",13,"第2节 蛋白质合成体系","遗传密码的作用",2003,29,"A","","下列属于终止密码子的是",[["A","UCA"],["B","UCG"],["C","UAC"],["D","UAA"],["E","UGC"]],"D","遗传密码中的终止密码子包括UAA（D对）、UAG和UGA。UCA（A错）和UCG（B错）均为丝氨酸的密码子。UAC（C错）为酪氨酸的密码子。UGC（E错）为半胱氨酸的密码子。","","N"],["2003-N30",14,"第1节 基因表达调控的基本概念与特点","基因表达的方式",2003,30,"A","","有些基因在一个生物个体的几乎所有细胞中持续表达，这类基因称为",[["A","可诱导基因"],["B","可阻遏基因"],["C","操纵基因"],["D","启动基因"],["E","管家基因"]],"E","在生物个体的几乎所有细胞中持续表达，不易受环境条件的影响的基因称为管家基因（E对）。可诱导基因（十版生物化学P316）（A错）是指在一定的环境中被激活，表达产物增加的基因。可阻遏基因（十版生物化学P317）（B错）是指在一定环境中被抑制，表达产物降低的基因。操纵基因（操纵元件）（C错）为原核生物操纵子结构的调控序列，启动基因（启动子）（D错）可调节真核生物和原核生物的转录过程。","","N"],["2003-N31",21,"第4节 胆色素的代谢与黄疸","结合",2003,31,"A","","下列关于游离胆红素的叙述，正确的是",[["A","胆红素与葡萄糖醛酸结合"],["B","水溶性较大"],["C","易透过生物膜"],["D","可通过肾脏随尿排出"],["E","与重氮试剂呈直接反应"]],"C","游离胆红素未与葡萄糖醛酸结合（A错），因此又称未结合胆红素。游离胆红素属脂溶性物质，易透过生物膜（C对），水溶性较小（B错），不能通过肾脏随尿排出（D错）。游离胆红素分子内有氢键存在，因此不能与重氮试剂发生直接反应（E错），只有在加入乙醇或尿素等破坏氢键后，才能与重氮试剂反应。","","N"],["2003-N32",17,"第1节 细胞信号转导概述","受体的分型",2003,32,"A","","通过胞内受体发挥作用的激素是",[["A","肾上腺素"],["B","甲状腺激素"],["C","胰高血糖素"],["D","胰岛素"],["E","促肾上腺皮质激素"]],"B","细胞接收信号时，是通过受体将信号导入细胞内。按照其在细胞内的位置，受体分为细胞内受体和细胞表面受体。脂溶性物质能通过细胞膜进入细胞内，通过胞内受体发挥作用，包括类固醇激素、甲状腺激素（B对）、维甲酸等；水溶性物质不能透过细胞膜，只能通过细胞表面受体发挥作用，包括肾上腺素（A错）、胰高血糖素（C错）、胰岛素（D错）、促肾上腺皮质激素（E错）等。","","N"],["2003-N97",2,"第3节 RNA和空间结构与功能","tRNA的结构及功能",2003,97,"B","","含稀有碱基最多的RNA是",[["A","rRNA"],["B","mRNA"],["C","tRNA"],["D","hnRNA"],["E","snRNA"]],"C","稀有碱基是指除A、C、G、U外的一些碱基，包括双氢尿嘧啶（DHU）、假尿嘧啶核苷（ψ）和甲基化的嘌呤（m⁷G，m⁷A）等。tRNA分子中含有多种稀有碱基（C对），约占所有碱基的10%-20%，它们均是转录后修饰而成的。","","N"],["2003-N98",2,"第3节 RNA和空间结构与功能","mRNA的结构及功能",2003,98,"B","","既含内含子又含外显子的RNA是",[["A","rRNA"],["B","mRNA"],["C","tRNA"],["D","hnRNA"],["E","snRNA"]],"D","既含内含子又含外显子的RNA是hnRNA（D对）：hnRNA是mRNA的未成熟前体，hnRNA与成熟mRNA之间的主要差别在于hnRNA中的一些片段将不出现于成熟mRNA中（B错），这些片段称为内含子，而那些保留于成熟mRNA中的片段则称为外显子。真核rRNA前体（十版生物化学P294）和真核tRNA前体（十版生物化学P294）亦包含内含子和外显子，但各自的成熟形式rRNA（A错）和tRNA（C错）经加工后均不含有内含子。snRNA（small nuclear RNA，核内小RNA）（十版生物化学P70）与多种蛋白形成复合体（剪接体），参与真核生物hnRNA内含子的加工剪接，但snRNA本身并不含内含子（E错）。","","N"],["2003-N115",6,"第4节 个别氨基酸的代谢","一碳单位的来源及转换",2003,115,"C","","经代谢转变能提供一碳单位的氨基酸是",[["A","甘氨酸"],["B","组氨酸"],["C","二者均是"],["D","二者均非"]],"C","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的基团，包括甲基、甲烯基、甲炔基、甲酰基及亚氨甲基等。一碳单位主要来自丝氨酸、甘氨酸（A对）、组氨酸（B对）及色氨酸的分解代谢，记忆的口诀为施（丝氨酸）舍（色氨酸）一根竹（组氨酸）竿（甘氨酸）。九、十版教材加入了苏氨酸。本题AB均对，正确答案为C。","","N"],["2003-N116",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径的概述",2003,116,"C","","参与嘌呤合成的氨基酸是",[["A","甘氨酸"],["B","组氨酸"],["C","二者均是"],["D","二者均非"]],"A","嘌呤从头合成原料包括天冬氨酸、谷氨酰胺、甘氨酸（A对）、CO₂及一碳单位（甲酰基，由N⁵，N¹⁰-甲炔四氢叶酸和N¹⁰-甲酰四氢叶酸提供）等，其中三种氨基酸可记为：天（天冬氨酸）啊，俺家的谷子（谷氨酰胺）干（甘氨酸）了。组氨酸是一碳单位N⁵，N¹⁰-甲炔四氢叶酸的来源（十版生物化学P187），后者是嘌呤合成的原料（提供C₈），但提供一碳单位来源的氨基酸本身一般不算作合成原料（B错）。","","N"],["2003-N133",6,"第3节 氨的代谢","鸟氨酸循环",2003,133,"X","","下列哪些化合物是尿素合成的中间产物",[["A","瓜氨酸"],["B","甘氨酸"],["C","精氨酸"],["D","鸟氨酸"]],"ACD","由P209图9-9可知，尿素合成的中间产物有鸟氨酸（D对）、瓜氨酸（A对）、精氨酸（C对）。鸟氨酸循环的步骤：①1分子NH₃和CO₂在氨基甲酰磷酸合成酶的催化下生成氨甲酰磷酸，反应在线粒体中进行；②氨基甲酰磷酸在鸟氨酸氨基甲酰转移酶的作用下，将氨基甲酰部分转移到鸟氨酸上生成瓜氨酸（A对），反应在线粒体中进行；③瓜氨酸由线粒体转运至胞质，与天冬氨酸在精氨酸代琥珀酸合成酶催化下生成精氨酸代琥珀酸；④精氨酸代琥珀酸在精氨酸代琥珀酸裂解酶的催化下裂解为精氨酸（C对），释放出延胡索酸，反应在胞质内进行；⑤精氨酸被精氨酸酶水解为尿素和鸟氨酸（D对），鸟氨酸进入线粒体，再次与氨甲酰磷酸合成瓜氨酸，重复述循环过程。","","N"],["2003-N134",11,"第3节 原核生物DNA复制过程","复制终止过程",2003,134,"X","","DNA复制过程中，参与冈崎片段之间连接的酶有",[["A","RNA酶"],["B","DNA-polⅢ"],["C","DnaA蛋白"],["D","连接酶"]],"AD","复制完成后，后随链的不连续片段（冈崎片段）经DNA pol Ⅰ（原核生物）或RNA酶（真核生物）（A对）水解去除引物（注意十版生物化学P265最新观点认为去除引物的酶为DNA pol Ⅰ，而非RNA酶，故A选项存在争议），经DNA pol Ⅰ（原核生物）或DNA pol δ（真核生物）填补引物留下的空隙，填补至足够长度后，留下相邻的3'-OH和5'-P的缺口，最后经连接酶（D对）连接成完整的 DNA 长链。","","N"],["2003-N135",14,"第2节 原核基因表达调控","乳糖操纵子的结构",2003,135,"X","","共同参与构成乳糖操纵子的组分有",[["A","三个结构基因"],["B","一个操纵序列"],["C","一个启动序列"],["D","一个调节基因"]],"ABCD","大肠杆菌（E.coli）的乳糖操纵子含Z、Y及A三个结构基因（A对），一个操纵序列O（B对）、一个启动子（启动序列）P（C对）、及一个调节基因Ⅰ（D对）。","","N"],["2003-N136",16,"第2节 重组DNA技术","质粒",2003,136,"X","","下列关于质粒载体的叙述，正确的是",[["A","具有自我复制能力"],["B","有些质粒常携带抗药性基因"],["C","为小分子环状DNA"],["D","含有克隆位点"]],"ABCD","质粒是存在于细菌染色体外的、能自我复制（A对）和稳定遗传的小分子环状DNA（C对）。作为克隆载体，质粒具备以下基本特点：①能够进行自我复制；②携带有选择标志，最为常见的选择标记是抗药性基因（B对）；③存在包含多个限制性内切酶酶切位点的多克隆位点（D对）。","","N"],["2004-N19",0,"第1节 蛋白质的分子组成","氨基酸的分类",2004,19,"A","","含有两个氨基的氨基酸是",[["A","Lys"],["B","Trp"],["C","Val"],["D","Glu"],["E","Leu"]],"A","含有两个氨基的氨基酸有赖氨酸（Lys）（A对）、天冬酰胺（Asn）和谷氨酰胺（Gln）和精氨酸（Arg）。按照官能团取大不取小的原则，也可认为含有两个氨基的氨基酸只有赖氨酸一种（天冬酰胺和谷氨酰胺含一个氨基和一个酰胺基，精氨酸含一个氨基和一个胍基）。Trp（色氨酸）（B错）、Val（缬氨酸）（C错）、Glu（谷氨酸）（D错）、Leu（亮氨酸）（E错）均只含有一个氨基。","","N"],["2004-N20",2,"第2节 DNA和空间结构与功能","DNA的双螺旋结构",2004,20,"A","","下列DNA双螺旋结构的叙述，正确的是",[["A","一条链是左手螺旋，另一条链是右手螺旋"],["B","双螺旋结构的稳定纵向靠氢键维系"],["C","A+T与G+C的比值为1"],["D","两条链的碱基间以共价键相连"],["E","磷酸、脱氧核糖构成螺旋的骨架"]],"E","DNA由两条多聚脱氧核苷酸链组成，围绕着同一个螺旋轴形成右手螺旋的结构（A错）。DNA结构的稳定纵向靠碱基平面间的疏水性堆积力维持（B错），横向靠两条链碱基间的氢键维系（D错）。对于一特定的生物体而言，腺嘌呤（A）与胸腺嘧啶（T）的摩尔数相等，而鸟嘌呤（G）与胞嘧啶（C）的摩尔数相等，因此A+C与T+G或A+G与T+C的比值为1，而非A+T与G+C的比值为1（C错）。在DNA双螺旋结构中，由脱氧核糖和磷酸基团构成亲水性骨架（E对），位于双螺旋结构的外侧。","","N"],["2004-N21",1,"第3节 酶促反应动力学","竞争性抑制",2004,21,"A","","磺胺类药物能竞争性抑制二氢叶酸合成酶是因为其结构相似于",[["A","对氨基苯甲酸"],["B","二氢蝶呤"],["C","苯丙氨酸"],["D","谷氨酸"],["E","酪氨酸"]],"A","竞争性抑制作用是指抑制剂和酶的底物在结构上相似，可与底物竞争结合酶的活性中心，从而阻碍酶与底物形成中间产物。磺胺类药物与对氨基苯甲酸结构类似（A对），可以竞争性地与二氢蝶酸合酶结合，抑制FH₂以至于FH₄合成，干扰细菌一碳单位的代谢，进而干扰核苷酸合成，使细菌的生长受到抑制。该题题干错误，磺胺类药物竞争性抑制二氢蝶酸合酶。","","N"],["2004-N22",4,"第2节 糖的无氧氧化","乳酸生成",2004,22,"A","","供氧不足时，3-磷酸甘油醛脱氢产生的NADH+H⁺的主要去路是",[["A","参加脂肪酸的合成"],["B","使丙酮酸还原生成乳酸"],["C","维持GSH处于还原状态"],["D","经α-磷酸甘油穿梭进入线粒体氧化"],["E","经苹果酸-天冬氨酸穿梭进入线粒体氧化"]],"B","糖的无氧氧化分为糖酵解和乳酸生成两个阶段。葡萄糖经糖酵解分解为两分子丙酮酸的过程中，3-磷酸甘油醛脱氢产生两分子NADH+H⁺，在有氧的情况下，NADH+H⁺将通过苹果酸-天冬氨酸穿梭或α-磷酸甘油穿梭，转移到线粒体进行氧化，产生2.5分子ATP或1.5分子ATP。在供氧不足时，这两分子NADH+H⁺将用于还原丙酮酸生成乳酸（B对），使NADH+H⁺重新转变成NAD⁺，糖酵解才能重复进行。","","N"],["2004-N23",4,"第6节 糖异生","糖异生的关键酶及耗能",2004,23,"A","","下列不参与糖异生作用的酶是",[["A","丙酮酸羧化酶"],["B","磷酸烯醇式丙酮酸羧激酶"],["C","果糖双磷酸酶-1"],["D","葡萄糖-6-磷酸酶"],["E","6-磷酸果糖激酶-1"]],"E","糖异生是指非糖化合物（乳酸、甘油、生糖氨基酸等）转变为葡萄糖或糖原的过程，进行糖异生的器官主要是肝。丙酮酸羧化酶（A对）、磷酸烯醇丙酮酸羧激酶（B对）、果糖双磷酸酶-1（C对）和葡萄糖-6-磷酸酶（D对）均为糖异生的关键酶。6-磷酸果糖激酶-1（E错，为本题正确答案）为糖酵解的关键酶。","","N"],["2004-N24",5,"第4节 磷脂代谢","甘油二酯合成途径",2004,24,"A","","合成脑磷脂需要的物质是",[["A","CDP-乙醇胺"],["B","CDP-胆碱"],["C","UDP-胆碱"],["D","UDP-乙醇胺"],["E","GDP-乙醇胺"]],"A","脑磷脂又称为磷脂酰乙醇胺，其合成过程为：乙醇胺在ATP供能及CTP参与下被活化为CDP-乙醇胺（A对），后者与甘油二酯缩合，生成磷脂酰乙醇胺。CDP-胆碱（B错）为合成磷脂酰胆碱（卵磷脂）所需的活性物质。UTP、GTP并不参与磷脂的合成过程，不存在UDP-胆碱（C错）、UDP-乙醇胺（D错）及GDP-乙醇胺（E错）等物质形式。","","N"],["2004-N25",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶核苷酸从头合成途径的概述",2004,25,"A","","合成嘌呤、嘧啶的共用原料是",[["A","甘氨酸"],["B","一碳单位"],["C","谷氨酸"],["D","天冬氨酸"],["E","氨基甲酰磷酸"]],"D","合成嘌呤碱的原料来自天冬氨酸、谷氨酰胺、甘氨酸、CO₂及一碳单位（由N⁵，N¹⁰-甲炔四氢叶酸和N¹⁰-甲酰四氢叶酸提供）等，其中三种氨基酸可记为：天（天冬氨酸）啊，俺家的谷子（谷氨酰胺）干（甘氨酸）了。合成嘧啶碱的原料来自谷氨酰胺、天冬氨酸、CO₂、一碳单位（由N⁵，N¹⁰-甲烯四氢叶酸提供，合成dTMP所需）等，其中两种氨基酸可巧记为：天（天冬氨酸）啊，俺家的谷子（谷氨酰胺）没干（没有甘氨酸）。因此天冬氨酸（D对）、谷氨酰胺（非谷氨酸）（C错）和CO₂是嘌呤、嘧啶合成的共同原料，而甘氨酸（A错）、N⁵，N¹⁰-甲炔四氢叶酸、N¹⁰-甲酰四氢叶酸是嘌呤合成的特有原料，N⁵，N¹⁰-甲烯四氢叶酸则是胸腺嘧啶合成的特有原料。嘌呤和胸腺嘧啶合成时均需要一碳单位，但二者所需一碳单位的类型并不相同，不能共用（B错）。氨基甲酰磷酸（E错）是尿素合成（十版生物化学P182）和嘧啶合成（十版生物化学P226）的中间产物，在嘧啶合成过程中，氨基甲酰磷酸以谷氨酰胺和CO₂为原料合成而来。","","N"],["2004-N26",6,"第3节 氨的代谢","谷氨酰胺",2004,26,"A","","脑中氨的主要去路是",[["A","合成尿素"],["B","扩散入血"],["C","合成谷氨酰胺"],["D","合成氨基酸"],["E","合成嘌呤"]],"C","氨是体内的有毒物质，各组织必须以无毒的形式通过血液将氨运输到肝脏代谢。氨可以通过丙氨酸-葡萄糖循环将氨转变为丙氨酸从骨骼肌运往肝，也可以通过谷氨酰胺（C对）从脑和骨骼肌运往肝或肾。","","N"],["2004-N27",1,"第4节 酶的调节","别构调节",2004,27,"A","","下列关于变构酶的叙述，错误的是",[["A","变构酶催化非平衡反应"],["B","多为代谢途径的关键酶"],["C","与变构效应剂呈可逆结合"],["D","都具有催化亚基和调节亚基"],["E","酶构象变化后活性可升高或降低"]],"D","体内一些代谢物可与某些酶的活性中心外的某个部位非共价可逆（C对）结合，引起酶的构象改变，从而改变酶的活性，酶的这种调节方式称为酶的变构调节，而受变构调节的酶则称为变构酶。变构酶多为代谢途径的关键酶（B对），催化非平衡反应（A对），酶构象变化后活性可升高或降低（E对）。变构酶包括调节部位和催化部位，有些酶的调节部位和催化部位存在于同一亚基，有的则分别存在于不同的亚基，只有这些酶才有调节亚基和催化亚基之分（D错，为本题正确答案）。","","N"],["2004-N28",13,"第2节 蛋白质合成体系","蛋白质合成所需酶类和蛋白质因子",2004,28,"A","","下列因子中，不参与原核生物翻译过程的是",[["A","IF"],["B","EF-1"],["C","EF-T"],["D","RF"]],"B","由表17-2 和表17-3 可知，参与原核生物蛋白质翻译过程的起始因子为IF（IF-1、IF-2、IF-3）（A对），延长因子为EF（EF-G、EF-T）（C对），释放因子为RF（RF-1、RF-2、RF-3）（D 对）；参与真核生物蛋白质翻译过程的起始因子是eIF（eIF-1、eIF-2等），延长因子是eEF（eEF-1、eEF-2）（B错，为本题正确答案），释放因子是eRF。","","N"],["2004-N29",12,"第1节 RNA的生物合成概述","以DNA为模板的RNA合成",2004,29,"A","","下列关于复制和转录过程异同点的叙述，错误的是",[["A","复制和转录的合成方向均为5'→3'"],["B","复制和转录过程均需以RNA为引物"],["C","复制的原料dNTP，转录的原料为NTP"],["D","二者的聚合酶均催化形成3'，5'-磷酸二酯键"],["E","DNA的双股链中只有一条链转录，两条链均可被复制"]],"B","DNA的复制和RNA的化学合成过程类似，二者分别以dNTP和NTP（C对）为底物，按照5’→3’的合成方向（A对），在各自聚合酶的作用下通过形成3’，5’-磷酸二酯键（D对）而合成DNA和RNA。DNA复制的起始，需要由引物酶合成的RNA引物提供3＇-OH才能合成磷酸二酯键进而延续复制过程，而转录过程的RNA聚合酶，可直接促进转录起点处的两个核苷酸间形成磷酸二酯键，因而转录起始不需要引物参与（B错，为本题正确答案）。DNA复制时，母链DNA解开为两股单链，各自作为模版，按照碱基互补配对规律，合成与模板互补的子链。转录时，DNA双链中只有一股单链作为模板链进行转录，另一股单链是编码链，不进行转录（E对）。","","N"],["2004-N30",17,"第2节 细胞内信号转导分子","环核苷酸类第二信使",2004,30,"A","","直接影响细胞内cAMP含量的酶是",[["A","磷脂酶"],["B","蛋白激酶A"],["C","腺苷酸环化酶"],["D","蛋白激酶C"],["E","酪氨酸蛋白激酶"]],"C","cAMP（环磷酸腺苷）是体内重要的第二信使物质，催化cAMP产生的酶是腺苷酸环化酶（C对），降解cAMP的酶是磷酸二酯酶，以上两种酶可直接影响细胞内cAMP含量。","","N"],["2004-N31",16,"第2节 重组DNA技术","限制性核酸内切酶",2004,31,"A","","能识别DNA特异序列并在识别位点或其周围切割双链DNA的一类酶是",[["A","核酸外切酶"],["B","核酸内切酶"],["C","限制性核酸外切酶"],["D","限制性核酸内切酶"],["E","核酸末端转移酶"]],"D","能够水解核酸（DNA和RNA）的酶称为核酸酶，根据作用的方式不同，可将核酸酶分为核酸外切酶和核酸内切酶（十版生物化学P217）。核酸外切酶仅能水解位于核酸分子链末端的磷酸二酯键，核酸内切酶则只可以在DNA或RNA分子内部切断磷酸二酯键。有些核酸内切酶要求酶切位点具有核酸序列特异性，称为限制性核酸内切酶（D对）。","","N"],["2004-N32",12,"第3节 真核生物mRNA的转录、加工和降解","不同RNA聚合酶催化不同RNA的合成",2004,32,"A","","真核生物RNA聚合酶Ⅰ转录后可产生的是",[["A","hnRNA"],["B","45S rRNA"],["C","tRNA"],["D","5S rRNA"],["E","snRNA"]],"B","真核生物主要有三种不同的 RNA 聚合酶，分别为 RNA 聚合酶Ⅰ、RNA 聚合酶Ⅱ和RNA 聚合酶Ⅲ（九版后教材新提及了植物中还存在RNA 聚合酶Ⅳ和RNA 聚合酶Ⅴ）。RNA聚合酶Ⅰ催化生成的产物为rRNA的前体45S rRNA（B对），45S rRNA再加工成28S、5.8S及18S rRNA；RNA聚合酶Ⅱ催化生成的产物为mRNA前体hnRNA（A错）、lncRNA、piRNA和miRNA；RNA聚合酶Ⅲ催化生成的产物为tRNA（C错），5S rRNA（D错）和snRNA（E错）（记忆为3个“三”：three→t，三五牌香烟→5，san→sn）。","","N"],["2004-N36",19,"第2节 癌基因","生长因子的分类及作用机制",2004,36,"A","","产物为生长因子受体的癌基因是",[["A","ras"],["B","sis"],["C","myc"],["D","cyclin D"],["E","erb-B2"]],"E","癌基因可编码生长因子、生长因子受体、信号转导蛋白、细胞周期蛋白、转录因子等产物。本题各选项中，产物为生长因子受体的癌基因是erb-B2（E对），erb-B2又名her2或neu（详见2012N49A），其编码的受体为EGF（人表皮生长因子）受体类似物。ras癌基因（A错）的编码产物为信号转导蛋白。sis癌基因（B错）的编码产物为生长因子。myc癌基因（C错）的编码产物为转录调节因子（转录因子）。cyclin D癌基因（D错）的编码产物为细胞周期蛋白。","","N"],["2004-N37",18,"第3节 DNA损伤和损伤修复的意义","DNA损伤修复系统缺陷与肿瘤",2004,37,"A","","与DNA修复调节基因突变相关的肿瘤是",[["A","遗传性非息肉病性大肠癌"],["B","家族性腺瘤性息肉病"],["C","Li-Fraumeni综合症"],["D","神经纤维瘤病"],["E","肾母细胞瘤"]],"A","生物存在DNA损伤修复机制，可以纠正碱基的错配，清除DNA链上的损伤，恢复DNA的正常结构。遗传性非息肉病性大肠癌（A对）存在DNA错配修复、转录偶联修复缺陷，造成细胞基因组的不稳定性，进而引起调控细胞生长基因的突变，发生细胞癌变。家族性腺瘤性息肉病（B错）与APC基因突变有关。Li-Fraumeni综合征（C错）与P53基因突变有关。神经纤维瘤病（D错）与NF-1基因突变有关，肾母细胞瘤（E错）与WT-1基因突变有关。","","N"],["2004-N97",13,"第2节 蛋白质合成体系","遗传密码的作用",2004,97,"B","","遗传密码中的起始密码子是",[["A","AUU"],["B","GUA"],["C","AUG"],["D","UCA"],["E","UGA"]],"C","遗传密码中的起始密码子是AUG（C对），AUG也是甲硫氨酸（蛋氨酸）的密码子。AUU（A错）为异亮氨酸的密码子。GUA（B错）为缬氨酸的密码子。UCA（D错）为丝氨酸的密码子。UGA（E错）为终止密码子。","","N"],["2004-N98",13,"第2节 蛋白质合成体系","遗传密码的作用",2004,98,"B","","遗传密码中的终止密码子是",[["A","AUU"],["B","GUA"],["C","AUG"],["D","UCA"],["E","UGA"]],"E","遗传密码中的终止密码子包括UAA、UAG和UGA（E对）。AUU（A错）为异亮氨酸的密码子。GUA（B错）为缬氨酸的密码子。AUG（C错）为起始密码子。UCA（D错）为丝氨酸的密码子。","","N"],["2004-N115",9,"第2节 代谢的相互联系","糖、脂质和蛋白质代谢联系的概述",2004,115,"C","","糖代谢和脂肪分解代谢可转变生成的是",[["A","3-磷酸甘油酸"],["B","α-酮戊二酸"],["C","二者均是"],["D","二者均非"]],"C","3-磷酸甘油酸（A对）：在糖代谢中，糖经糖酵解途径（十版生物化学P107）可转变生成3-磷酸甘油酸；在脂代谢中，脂肪在脂肪动员的作用下水解释放出甘油，甘油（十版生物化学P145）在甘油激酶的作用下生成3-磷酸甘油，而后脱氢生成磷酸二羟丙酮，磷酸二羟丙酮进入糖酵解途径后可进一步转变生成3-磷酸甘油酸。α-酮戊二酸（B对）：在糖代谢中，葡萄糖经糖酵解途径生成丙酮酸，丙酮酸脱羧可生成乙酰CoA（十版生物化学P108），丙酮酸羧化则可生成草酰乙酸（十版生物化学P130），乙酰CoA和草酰乙酸缩合生成柠檬酸，进入柠檬酸循环（十版生物化学P114）生成α-酮戊二酸；在脂代谢中，脂肪分解代谢产物之一为甘油，甘油可转变生成磷酸二羟丙酮（十版生物化学P145），后者进入糖酵解途径生成丙酮酸，丙酮酸分别生成乙酰CoA和草酰乙酸（同上），最终进入柠檬酸循环生成α-酮戊二酸。本题AB均对，正确答案为C。","","N"],["2004-N116",9,"第2节 代谢的相互联系","糖、脂质和蛋白质代谢联系的概述",2004,116,"C","","氨基酸氧化分解代谢的中间产物是",[["A","3-磷酸甘油酸"],["B","α-酮戊二酸"],["C","二者均是"],["D","二者均非"]],"B","以下分析请参考P231图 12-1：在氨基酸的分解代谢过程中，部分氨基酸可生成丙酮酸（如丙氨酸、丝氨酸），丙酮酸脱羧可生成乙酰CoA（十版生物化学P113），丙酮酸羧化则可生成草酰乙酸（十版生物化学P130），乙酰CoA和草酰乙酸缩合生成柠檬酸，进入柠檬酸循环（十版生物化学P114）生成α-酮戊二酸（B对）。部分氨基酸可经转氨基作用直接生成α-酮戊二酸（如谷氨酸、谷氨酰胺）（B对）。部分氨基酸可转变成琥珀酸（如缬氨酸、甲硫氨酸）或延胡索酸（如酪氨酸、苯丙氨酸）进入柠檬酸循环生成α-酮戊二酸（B对）。氨基酸氧化分解代谢的中间产物包括丙酮酸、乙酰辅酶A及柠檬酸循环的全部中间产物，3-磷酸甘油酸（A错）为氨基酸合成代谢的中间产物（生糖氨基酸糖异生过程可生成3-磷酸甘油酸）。","","N"],["2004-N133",7,"第1节 生物氧化与能量代谢","物质能量代谢的概述",2004,133,"X","","下列哪些化合物属于高能磷酸化合物",[["A","1，6-二磷酸果糖"],["B","磷酸烯醇式丙酮酸"],["C","三磷酸肌醇"],["D","磷酸肌酸"]],"BD","含有高能磷酸键的化合物包括NTP、NDP、 1，3- 二磷酸甘油酸、磷酸烯醇式丙酮酸（B对）、磷酸肌酸（D对）、氨基甲酰磷酸、焦磷酸、葡糖-1-磷酸等。1，6二磷酸果糖（十版生物化学P130）分子中第1、6位是磷酸酯键，而不是高能磷酸键，不属于高能磷酸化合物（A错）。三磷酸肌醇（十版生物化学P394）即IP₃，为细胞内的信号转导分子，其1、4、5位是磷酸酯键，不含高能磷酸键，不属于高能磷酸化合物（C错）。","","N"],["2004-N134",11,"第2节 DNA复制的酶学和拓扑学","原核生物的DNA聚合酶",2004,134,"X","","复制过程中具有催化3'，5'-磷酸二酯键生成的酶有",[["A","引物酶"],["B","DNA聚合酶"],["C","拓扑异构酶"],["D","解螺旋酶"]],"ABC","DNA和RNA中的核苷酸都是通过3＇，5＇-磷酸二酯键连接的，因此有聚合活性（即可以使DNA或RNA中的核苷酸发生聚合反应）的酶都可以生成3＇，5＇-磷酸二酯键。引物酶本质上是一种RNA聚合酶，因此具有催化3＇，5＇-磷酸二酯键生成的能力（A对）。DNA聚合酶的作用是沿5＇→3＇方向延长脱氧核苷酸链，这是通过催化3＇，5＇-磷酸二酯键生成而进行的（B对）。拓扑酶一方面可以切断DNA双链，达到松弛超螺旋的目的，另一方面可以将松弛的DNA双链通过3＇，5＇-磷酸二酯键重新连接起来（C对）。解螺旋酶（如原核生物的DnaB）（十版生物化学P261）（D错）的作用是解开DNA双链，方便DNA聚合酶与双链结合，此过程没有DNA双链的断裂和重新连接，不形成3＇，5＇-磷酸二酯键（D错）。","","N"],["2004-N135",2,"第3节 RNA和空间结构与功能","核酶的分类及空间构象",2004,135,"X","","下列选项中，含有RNA的酶有",[["A","核酶"],["B","端粒酶"],["C","逆转录酶"],["D","RNase"]],"AB","绝大多数酶的化学性质是蛋白质，极少数是核酸，如核酶，其本质是RNA（A对），具有催化特定RNA降解的活性。端粒酶是一种由催化蛋白和RNA模板（B对）组成的酶，可合成染色体末端的DNA，使细胞保持持续复制的能力。逆转录酶也称RNA指导的DNA聚合酶，其本质是蛋白质，不含RNA（C错）。RNase为核糖核酸酶（RNA酶），它的功能是催化RNA降解，其中RNase P属于核酶，其余均为蛋白质酶类，不含RNA，D选项略微存在争议。","","N"],["2004-N136",13,"第2节 蛋白质合成体系","遗传密码的特点",2004,136,"X","","一个tRNA上的反密码子为IAC，其可识别的密码子是",[["A","GUA"],["B","GUC"],["C","GUG"],["D","GUU"]],"ABD","tRNA上的反密码子第1位碱基与mRNA的密码子第3位碱基之间的配对并不严格，如反密码子第1位的Ⅰ（次黄嘌呤）可分别与密码子第3位的A或C或U配对，此为遗传密码的摆动性特点。因此tRNA上的反密码子为IAC时，其识别的密码子可为GUA（A对）、GUC（B对）和GUU（D对）。","","N"],["2005-N23",0,"第4节 蛋白质的理化性质","两性电离性质",2005,23,"A","","当溶液的pH与某种氨基酸的pI一致时，该氨基酸在此溶液中的存在形式是",[["A","兼性离子"],["B","非兼性离子"],["C","带单价正电荷"],["D","疏水分子"],["E","带单价负电荷"]],"A","由于所有氨基酸都含有碱性的α-氨基和酸性α-羧基，可在酸性溶液中与H⁺结合呈带正电荷的阳离子（-NH₃⁺），也可在碱性溶液中与OH⁻结合呈带负电荷的阴离子（-COO⁻），因此氨基酸是两性电解质。氨基酸的解离方式取决于其所处溶液的pH值，当pH=pI时，该氨基酸在水溶液中的存在形式是兼性离子（A对）；当pH>pI时，氨基酸解离为阴离子；当pH<pI时，氨基酸解离为阳离子。氨基酸分子中至少含有2个亲水基团（1个-NH₂和1个-COOH），因此氨基酸不是疏水分子。","","N"],["2005-N24",2,"第4节 核酸的理化性质","DNA变性",2005,24,"A","","DNA受热变性时，出现的现象是",[["A","多聚核苷酸链水解成单核苷酸"],["B","在260nm波长处的吸光度增高"],["C","碱基对以共价键连接"],["D","溶液黏度增加"],["E","最大光吸收峰波长发生转移"]],"B","DNA变性是指DNA双链互补碱基对之间的氢键发生断裂，使DNA双链解链为单链（A错），变性后，更多共轭双键暴露，使其在260nm波长处的吸光度增高（B对）。DNA变性时，碱基对间的氢键断裂，不伴有共价键的断裂或连接（C错）。DNA变性时，黏度应降低（与蛋白质相反）（D错）。变性时嘌呤和嘧啶分子未发生变化，因此最大吸收峰的波长不会发生转移（E错）。","","N"],["2005-N25",1,"第3节 酶促反应动力学","米氏方程(1)",2005,25,"A","","一个简单的酶促反应，当[S]<<Km时，出现的现象是",[["A","反应速度最大"],["B","反应速度太慢难以测出"],["C","反应速度与底物浓度成正比"],["D","增加底物浓度反应速度不变"],["E","增加底物浓度反应速度降低"]],"C","米氏方程V=Vmax[S]/（Km+[S]），式中Km为米氏常数，Vmax为最大反应速率。当[S]<<Km时，方程分母中的[S]可以忽略不计，米氏方程可以简化为V=Vmax[S]/Km，此时反应速度V与底物浓度[S]成正比关系（C对）。","","N"],["2005-N26",4,"第3节 糖的有氧氧化","丙酮酸氧化脱羧",2005,26,"A","","丙酮酸脱氢酶复合体中不包括的辅助因子是",[["A","FAD"],["B","NAD⁺"],["C","硫辛酸"],["D","辅酶A"],["E","生物素"]],"E","丙酮酸脱氢酶复合体是葡萄糖有氧氧化的关键酶之一，催化丙酮酸脱氢脱羧生成乙酰CoA。参与反应的辅酶有焦磷酸硫胺素（TPP），硫辛酸（C对），FAD（A对），NAD⁺（B对）和CoA（D对），可记忆为赴美（辅酶A）交流（TPP，焦磷酸硫胺素）时留心（硫辛酸）谎（FAD，黄素腺嘌呤二核苷酸）言（NAD⁺，烟酰胺腺嘌呤二核苷酸）（亦可记忆为SPA，即名称中带有S、P、A字母的，注：硫的化学符号为S）。生物素（十版生物化学P99）（E错，为本题正确答案）又称为维生素H、维生素B₇、辅酶R等，是多种羧化酶的辅基，参与二氧化碳的羧化。","","N"],["2005-N27",4,"第3节 糖的有氧氧化","三羧酸循环的过程",2005,27,"A","","下列代谢物经相应特异脱氢酶催化脱下的2H，不能经过NADH呼吸链氧化的是",[["A","异柠檬酸"],["B","苹果酸"],["C","α-酮戊二酸"],["D","琥珀酸"],["E","丙酮酸"]],"D","从丙酮酸进入线粒体开始，至苹果酸脱氢生成草酰乙酸结束，共发生五次脱氢反应，分别是丙酮酸→乙酰CoA、异柠檬酸→α-酮戊二酸、α-酮戊二酸→琥珀酰CoA、琥珀酸→延胡索酸、苹果酸→草酰乙酸，其中琥珀酸变成延胡索酸的过程中脱下的氢是由FAD接受（D对），而其他四次反应脱下的氢均是由NAD⁺接受，最终经NADH呼吸链氧化。","","N"],["2005-N28",1,"第3节 酶促反应动力学","酶促反应动力学参数",2005,28,"A","","血糖浓度低时，脑仍能摄取葡萄糖而肝不能是因为",[["A","脑细胞膜葡萄糖载体易将葡萄糖转运入细胞"],["B","脑己糖激酶的Km值低"],["C","肝葡萄糖激酶的Km值低"],["D","葡萄糖激酶具有特异性"],["E","血脑屏障在血糖低时不起作用"]],"B","Km即米氏常数，为酶的特征性常数，在数值上等于酶促反应速率为最大反应速率一半时的底物浓度。一定条件下，Km值可以表示酶对底物的亲和力，Km越大，表示酶对底物的亲和力越小，Km越小，酶对底物的亲和力越大。低血糖时，脑可摄取葡萄糖而肝不能，因为脑中己糖激酶的Km值较低（B对C错），对葡萄糖亲和力较高，从而保证在饥饿条件下脑部的能量供应。慢性低血糖时，脑细胞膜葡萄糖载体（GLUT1、GLUT3）表达上调，从而使更多的葡萄糖进入脑组织，与此同时，肝细胞膜葡萄糖载体（GLUT4）表达下调，阻止葡萄糖进入肝组织，因此“脑细胞膜葡萄糖载体易将葡萄糖转运入细胞”的说法本身是正确的，不过与脑中己糖激酶的Km值较低相比，其不是血糖浓度低时，脑仍能摄取葡萄糖的主要原因（A错）。葡萄糖激酶为己糖激酶Ⅳ型同工酶，是肝脏的特异性激酶（十版生物化学P108）（D错）。低血糖时可使血脑屏障葡萄糖转运体（GLUT）表达增加，降低血脑屏障的屏障作用，并不是不起作用，退一步讲，即使血脑屏障不起作用，也不能解释“脑仍可摄取葡萄糖而肝不能”的现象，因为肝脏本身就不存在类似的屏障（E错）。","","N"],["2005-N29",5,"第3节 甘油三酯代谢","脂肪酰CoA分解",2005,29,"A","","脂肪酸活化后，下列哪种酶不参与β-氧化",[["A","脂酰辅酶A脱氢酶"],["B","β-羟脂酰辅酶A脱氢酶"],["C","Δ²-烯酰辅酶A水化酶"],["D","β-酮脂酰辅酶A硫解酶"],["E","β-酮脂酰还原酶"]],"E","脂肪酸活化为脂酰CoA后，脂酰CoA进入线粒体，经脱氢（由脂酰辅酶A脱氢酶催化）（A对）、加水（由Δ²-烯酰辅酶A水化酶催化）（C对）、再脱氢（由β-羟脂酰辅酶A脱氢酶催化）（B对）、硫解（由β-酮脂酰辅酶A硫解酶催化）（D对）等四步反应完成一次β-氧化。β-酮脂酰还原酶（十版生物化学P152）为参与脂肪酸合成的酶，而非参与脂肪酸β-氧化的酶（E错，为本题正确答案）。","","N"],["2005-N30",5,"第5节 胆固醇代谢","胆固醇的合成过程",2005,30,"A","","胆固醇合成的限速酶是",[["A","鲨烯环化酶"],["B","鲨烯合酶"],["C","HMG-CoA还原酶"],["D","HMG-CoA合成酶"],["E","HMG-CoA裂解酶"]],"C","胆固醇生物合成时的限速酶（关键酶）是HMG-CoA还原酶（C对）。HMG-CoA合成酶（亦为酮体合成的非限速酶）（D错）、鲨烯环化酶（A错）和鲨烯合酶（B错）均为胆固醇生物合成时的非限速酶。HMG-CoA裂解酶（E错）为酮体合成（十版生物化学P149）的非限速酶。","","N"],["2005-N31",6,"第4节 个别氨基酸的代谢","一碳单位的概念及运载体",2005,31,"A","","体内转运一碳单位的载体是",[["A","叶酸"],["B","生物素"],["C","维生素B₁₂"],["D","四氢叶酸"],["E","S-腺苷蛋氨酸"]],"D","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的基团，包括甲基、甲烯基、甲炔基、甲酰基及亚氨甲基等，一碳单位不能游离存在，常与四氢叶酸（D对）结合而转运和参与代谢。叶酸（十版生物化学P101）（A错）还原为四氢叶酸后才能转运一碳单位。生物素（十版生物化学P99）（B错）为转运CO₂的载体，参与羧化反应。维生素B₁₂和S-腺苷蛋氨酸（S-腺苷甲硫氨酸）均为转运甲基的载体，参与甲基转移反应（十版生物化学P189），由于甲基属于一碳单位的一种，因此严格来说维生素B₁₂（C）和S-腺苷蛋氨酸（E）亦均为转运一碳单位的载体，但本题给出的参考答案仅为D。","","N"],["2005-N32",11,"第3节 原核生物DNA复制过程","引物合成和起始复合物的形成",2005,32,"A","","RNA引物在DNA复制过程中的作用是",[["A","提供起始模板"],["B","激活引物酶"],["C","提供复制所需的5'-磷酸"],["D","提供复制所需的3'-羟基"],["E","激活DNA-polⅢ"]],"D","体内DNA复制时，母链DNA解成单链后，不会立即按照模板序列将dNTP聚合为DNA子链，这是因为DNA聚合酶不具备催化两个游离dNTP形成磷酸二酯键的能力，只能催化核酸片段的3’-OH末端与dNTP间的聚合，因此在复制起始部位需要以RNA为引物（RNA引物由引物酶催化合成：引物酶可催化两个游离的NTP形成磷酸二酯键，从而合成RNA引物），RNA引物可为DNA的合成3’-OH末端（D对）。","","N"],["2005-N33",10,"第2节 真核基因的结构与功能","启动子的作用",2005,33,"A","","下列关于TATA盒的叙述，正确的是",[["A","位于操纵子的第一个结构基因处"],["B","属于负性顺式调节元件"],["C","能编码阻遏蛋白"],["D","发挥作用的方式与方向无关"],["E","能与RNA聚合酶结合"]],"E","真核生物转录起始前的-25～-30bp区域多有典型的TATA序列，称为 TATA 盒，又称 Hognest 盒（十版生物化学P280），通常认为是启动子的核心序列，可以通过转录因子TFⅡD（十版生物化学P329）与RNA聚合酶结合并控制转录（E对）。操纵子（十版生物化学P318）是原核生物的转录调控序列（A错）。真核生物的调控序列被称为顺式作用元件，其中启动子、增强子等是正性调节（B错），沉默子是负性调节。阻遏蛋白多是指原核生物乳糖操纵子中由Ⅰ基因编码的蛋白质，对原核细胞基因表达起负性调节作用（C错）。启动子发挥作用有方向性（D错），方向倒置后启动子就不能起作用，而沉默子和增强子作用均与方向无关。","","N"],["2005-N34",12,"第2节 原核生物的转录","依赖ρ因子的转录终止",2005,34,"A","","原核生物的mRNA转录终止需要下列哪种因子？",[["A","释放因子"],["B","Rho因子"],["C","信号肽"],["D","σ因子"],["E","DnaB"]],"B","原核生物的mRNA转录终止分为依赖ρ（Rho）因子（B对）与非依赖ρ因子两大类，在依赖ρ因子的转录终止中，ρ因子可以识别产物RNA富含C碱基且较有规律的终止信号，并与之结合使RNA聚合酶发生构象改变，导致RNA聚合酶停顿，转录终止。信号肽（C错）（十版生物化学P310）为蛋白质翻译终止后，新合成多肽链中用于指导蛋白质进行跨膜转移（定位）的N-末端的氨基酸序列。σ因子（十版生物化学P276）（D错）为原核生物RNA聚合酶全酶（σα₂ββ′）的亚基组分，起辨认原核生物转录起始点的作用。释放因子（RF）（十版生物化学P300）（A错）为蛋白质翻译时，识别终止密码子而进入A位，介导翻译终止的蛋白质因子。DnaB（十版生物化学P261）（E错）为DNA复制起始时的解螺旋酶，可解开待复制的DNA双链。","","N"],["2005-N35",13,"第2节 蛋白质合成体系","遗传密码的特点",2005,35,"A","","遗传密码的简并性是指",[["A","蛋氨酸密码可作起始密码"],["B","一个密码子可代表多个氨基酸"],["C","多个密码子可代表同一氨基酸"],["D","密码子与反密码子之间不严格配对"],["E","所有生物可使用同一套密码"]],"C","遗传密码的简并性是指多个密码子可代表同一氨基酸（C对）。密码子与反密码子之间不严格配对（D错）称为遗传密码的摆动性。所有生物可使用同一套密码（E错）称为遗传密码的通用性。一个密码子只能代表一个氨基酸（B错）。","","N"],["2005-N36",17,"第2节 细胞内信号转导分子","环核苷酸类第二信使",2005,36,"A","","cAMP能别构激活下列哪种酶",[["A","磷脂酶A"],["B","蛋白激酶A"],["C","蛋白激酶C"],["D","蛋白激酶G"],["E","酪氨酸蛋白激酶"]],"B","环核苷酸在细胞内可调节蛋白激酶活性，如环磷酸腺苷（cAMP）可别构激活蛋白激酶A（PKA）（B对）。蛋白激酶C（C错）的激活物为Ca²⁺和DAG（十版生物化学P389）。蛋白激酶G（D错）的激活物为cGMP（十版生物化学P389）。酪氨酸蛋白激酶（常为受体或受体结合蛋白）（E错）的激活物为表皮生长因子、血小板源生长因子等生长因子（被这些配体所激活）（九版生理学P29）。磷脂酶A（十版生物化学P158）（A错）是水解甘油磷脂的酶，本科教材未提及其激活物。","","N"],["2005-N111",5,"第3节 甘油三酯代谢","脂肪动员",2005,111,"B","","属于脂肪动员的产物是",[["A","甘油"],["B","3-磷酸甘油"],["C","3-磷酸甘油醛"],["D","1，3-二磷酸甘油酸"],["E","2，3-二磷酸甘油酸"]],"A","脂肪动员是指存在于脂肪细胞内的脂肪在脂肪酶的作用下，水解为游离脂肪酸和甘油（A对）的过程。3-磷酸甘油（P152）（B错）经糖酵解途径生成或经甘油直接磷酸化生成，主要用于甘油三酯合成。3-磷酸甘油醛（十版生物化学P108）（C错）和1，3-二磷酸甘油酸（十版生物化学P108）（D错）为糖酵解的中间产物。2，3-二磷酸甘油酸（十版生物化学P489）（E错）为2，3-二磷酸甘油酸旁路的中间产物。","","N"],["2005-N112",5,"第3节 甘油三酯代谢","甘油三酯合成的原料",2005,112,"B","","属于脂肪组织中合成甘油三酯的原料是",[["A","甘油"],["B","3-磷酸甘油"],["C","3-磷酸甘油醛"],["D","1，3-二磷酸甘油酸"],["E","2，3-二磷酸甘油酸"]],"B","甘油三酯的合成途径有两条，即甘油一酯途径和甘油二酯途径。甘油一酯途径主要发生在小肠黏膜细胞，利用消化吸收的甘油一酯和脂肪酸合成甘油三酯；甘油二酯途径主要发生在肝和脂肪细胞，利用糖酵解途径生成的3-磷酸甘油（B对），在脂酰CoA转移酶的作用下，依次加上三分子脂酰CoA合成甘油三酯。肝细胞甘油激酶活性高，可以将游离的甘油磷酸化成3-磷酸甘油用于甘油三酯合成，而脂肪细胞甘油激酶活性低（十版生物化学P145），因而不能利用游离的甘油（A错）合成甘油三酯，只能以糖酵解生成的3-磷酸甘油为原料合成甘油三酯。3-磷酸甘油醛（C错）和1，3-二磷酸甘油酸（D错）为糖酵解的中间产物。2，3-二磷酸甘油酸（E错）为糖酵解2，3-二磷酸甘油酸旁路（十版生物化学P489）的中间产物。","","N"],["2005-N113",0,"第2节 蛋白质的分子结构","结构模体",2005,113,"B","","亮氨酸拉链属于蛋白质的",[["A","一级结构"],["B","二级结构"],["C","三级结构"],["D","四级结构"],["E","模序结构"]],"E","亮氨酸拉链属于蛋白质的模序结构（E对），模序结构又称模体结构，是蛋白质分子中具有特定空间构象和特定功能的结构成分。值得注意的是，八版教材里，亮氨酸拉链这种模序结构被归在二级结构章节下，到九、十版教材，改到三级结构章节下了，但一般认为模序结构既不属于二级结构，也不属于三级结构，而是属于一种介于二级结构和三级结构之间的结构形式，这种结构形式被称为超二级结构。","","N"],["2005-N114",0,"第2节 蛋白质的分子结构","蛋白质三级结构的概念",2005,114,"B","","整条肽链中全部氨基酸残基的相对位置属于蛋白质的",[["A","一级结构"],["B","二级结构"],["C","三级结构"],["D","四级结构"],["E","模序结构"]],"C","蛋白质分子结构十分复杂，可分成四个层次，即一级、二级、三级、四级结构。一级结构是指蛋白质中从N端到C端氨基酸的排列顺序（十版生物化学P13）；二级结构是指蛋白质中某一段肽链的局部空间结构（十版生物化学P14）；三级结构（C对）是指整条肽链上全部氨基酸残基的相对空间位置（十版生物化学P16）；四级结构是指有两条或两条以上多肽链的蛋白质分子中各个亚基的空间排布及亚基接触部位的布局和相互作用（十版生物化学P18）。","","N"],["2005-N133",11,"第2节 DNA复制的酶学和拓扑学","DNA拓扑异构酶改变DNA超螺旋状态",2005,133,"X","","拓扑异构酶对DNA分子的作用有",[["A","解开DNA超螺旋"],["B","切断单链DNA"],["C","结合单链DNA"],["D","连接3'，5'-磷酸二酯键"]],"ABD","拓扑异构酶的主要作用就是解开超螺旋（A对），当DNA处于超螺旋状态时，拓扑异构酶可以切断DNA双链中的单链（B对）或双链，使超螺旋松弛，而后又可催化连接3＇，5＇-磷酸二酯键（D对）将断端连接起来，完成解开超螺旋结构的过程。结合单链DNA（C错）的为SSB（单链结合蛋白），它的作用是稳定已解开的单链DNA。","","N"],["2005-N134",13,"第2节 蛋白质合成体系","蛋白质合成所需酶类和蛋白质因子",2005,134,"X","","下列哪些因子参与蛋白质翻译延长",[["A","IF"],["B","EFG"],["C","EFT"],["D","RF"]],"BC","EF-G（B对）和EF-T（EF-Tu、EF-Ts）（C对）均为原核生物蛋白质翻译的延长因子，参与蛋白质翻译延长。IF（A错）为原核生物翻译的起始因子。RF（D错）为原核生物翻译释放因子。","","N"],["2005-N135",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径的概述",2005,135,"X","","参与嘌呤环合成的原料来自下列哪些物质",[["A","甲酰基"],["B","同型半胱氨酸"],["C","天冬氨酸"],["D","氨基甲酰磷酸"]],"AC","合成嘌呤环的原料包括天冬氨酸（C对）、谷氨酰胺、甘氨酸、CO₂及甲酰基（一碳单位）（A对）等，其中三种氨基酸可记为：天（天冬氨酸）啊，俺家的谷子（谷氨酰胺）干（甘氨酸）了。同型半胱氨酸（十版生物化学P189）（B错）是甲硫氨酸循环的中间产物，与嘌呤合成无关。氨基甲酰磷酸（D错）是尿素合成（十版生物化学P182）和嘧啶合成（十版生物化学P225）的中间产物，与嘌呤合成无关。","","N"],["2005-N136",16,"第2节 重组DNA技术","目的DNA的分离获取",2005,136,"X","","在分子克隆中，目的DNA可来自",[["A","原核细胞基因组DNA"],["B","真核细胞基因组DNA"],["C","PCR合成的DNA"],["D","真核细胞mRNA反转录获得的cDNA"]],"ABCD","在分子克隆（重组DNA技术）中，目的DNA可来自以下途径：①若已知目的DNA的全部核苷酸序列，可以用化学合成法直接合成；②若已知目的DNA两端的核苷酸序列，可根据两端的序列设计引物，利用PCR法合成（C对）；③若已知目的DNA的部分核苷酸序列，且目的DNA在基因组DNA中存在，可利用分子杂交的方法从基因组DNA文库中筛选（AB对）；④若已知目的DNA的部分核苷酸序列，且目的DNA在真核细胞的cDNA中存在，可利用分子杂交的方法从cDNA（从真核细胞mRNA反转录获得）文库中筛选（D对）。","","N"],["2006-N23",6,"第1节 营养必需氨基酸与氨基酸代谢概述","蛋白质营养价值的决定因素",2006,23,"A","","下列哪种氨基酸体内不能合成，必需靠食物供给",[["A","缬氨酸"],["B","精氨酸"],["C","半胱氨酸"],["D","组氨酸"],["E","丝氨酸"]],"AD","本知识点在九版后的教材有重大更新，八版教材人体必需氨基酸（体内不能合成，必须靠食物供给）为八种，分别为亮氨酸、异亮氨酸、苏氨酸、缬氨酸、赖氨酸、甲硫氨酸、苯丙氨酸和色氮酸，九版之后的教材将组氨酸也列入了人体必需氨基酸的范畴。故根据最新教材，人体必需氨基酸为九种，分别为亮氨酸、异亮氨酸、苏氨酸、缬氨酸（A对）、赖氨酸、甲硫氨酸、苯丙氨酸、色氮酸和组氨酸（D对）。可记忆为“一家族人来写两三本书”，一（异亮氨酸）家（甲硫氨酸）族（组氨酸）人来（赖氨酸）写（缬氨酸）两（亮氨酸）三（色氨酸）本（苯丙氨酸）书（苏氨酸）。或“写一两本淡色书出来”，写（缬氨酸）一（异亮氨酸）两（亮氨酸）本（苯丙氨酸）淡（蛋氨酸/甲硫氨酸）色（色氨酸）书（苏氨酸）出（组氨酸）来（赖氨酸）。或“组队来写一两本淡色书”，组（组氨酸）队来（赖氨酸）写（缬氨酸）一（异亮氨酸）两（亮氨酸）本（苯丙氨酸）淡（蛋氨酸/甲硫氨酸）色（色氨酸）书（苏氨酸）。本题当年依照旧教材给出的参考答案为A，根据最新教材，本题的正确答案应为AD。","","N"],["2006-N24",2,"第3节 RNA和空间结构与功能","mRNA的结构及功能",2006,24,"A","","下列关于mRNA的叙述，错误的是",[["A","在细胞核内由hnRNA剪接而成"],["B","真核生物mRNA有“帽子”和“多聚A尾”结构"],["C","生物体中各种mRNA的长短不同，相差很大"],["D","是各种RNA分子中半衰期最长的一类"],["E","其功能是作为蛋白质合成的模板"]],"D","mRNA即信使RNA（messenger RNA），mRNA是在核内以DNA为模板合成而来，但其合成的初级产物为mRNA的前体hnRNA，hnRNA经过戴帽、加尾和剪接（A对）等加工过程才能生成具有“帽子”和“多聚A尾”结构的成熟mRNA（B对）。成熟的mRNA可作为蛋白质合成的模板（E对）。在生物体内，mRNA的丰度（相对含量）最小，但是mRNA的种类最多，并且各种mRNA的长短不同，相差很大（C对）。在所有的RNA中，mRNA的寿命最短（半衰期最短）（D错，为本题正确答案）。","","N"],["2006-N25",1,"第1节 酶的分子结构与功能","同工酶催化相同的化学反应",2006,25,"A","","肝中富含的LDH同工酶是",[["A","LDH1"],["B","LDH2"],["C","LDH3"],["D","LDH4"],["E","LDH5"]],"E","同工酶是指催化相同的化学反应，但酶蛋白的分子结构、理化性质乃至免疫学性质不同的一组酶。乳酸脱氢酶（LDH）的包括LDH1、LDH2、LDH3、LDH4、LDH5共五种同工酶，由“表3-3 人体各组织器官LDH同工酶谱（活性%）”可知肝中富含的LDH同工酶为LDH5（E对）。","","N"],["2006-N26",5,"第3节 甘油三酯代谢","软脂酸合成的过程",2006,26,"A","","柠檬酸是下列哪种酶的变构激活剂",[["A","6-磷酸果糖激酶-1"],["B","丙酮酸激酶"],["C","丙酮酸羧化酶"],["D","乙酰CoA羧化酶"],["E","丙酮酸脱氢酶复合体"]],"D","乙酰CoA羧化酶是脂肪酸合成的关键酶，接受柠檬酸和异柠檬酸的变构激活（D对），从而促进脂肪酸的合成（柠檬酸和异柠檬酸是三羧酸循环的中间产物，含量较多表明机体能量充足，因此对脂肪酸合成具有促进作用）。6-磷酸果糖激酶-1（十版生物化学P108）（A错）为糖酵解的关键酶，柠檬酸为其变构抑制剂，其变构激活剂为AMP、ADP、1，6-二磷酸果糖和2，6-二磷酸果糖等。丙酮酸激酶（十版生物化学P108）（B错）亦为糖酵解的关键酶，其变构激活剂为1，6-二磷酸果糖。丙酮酸羧化酶（十版生物化学P130）（C错）为糖异生的关键酶，其变构激活剂为乙酰辅酶A。丙酮酸脱氢酶复合体（十版生物化学P113）（E错）为丙酮酸氧化脱羧的关键酶，其变构激活剂为AMP和ADP。","","N"],["2006-N27",5,"第5节 胆固醇代谢","胆固醇的转化",2006,27,"A","","胆固醇在体内不能转变生成的是",[["A","维生素D₃"],["B","胆汁酸"],["C","胆色素"],["D","雌二醇"],["E","睾酮"]],"C","胆固醇的去路：①被肝转化为胆汁酸，这是胆固醇的主要去路（B对）；②在肾上腺皮质、睾丸、卵巢等合成类固醇激素，包括醛固酮、皮质醇、雄激素（E对）、雌激素（D对）、孕激素等；③在皮肤被氧化为7-脱氢胆固醇，经紫外线照射转变为维生素D₃（A对）。胆色素包括胆绿素、胆红素、胆素原和胆素，是体内铁卟啉类化合物（血红蛋白、肌红蛋白、细胞色素等）的主要分解代谢产物，与胆固醇代谢无关（C错，为本题正确答案）。","","N"],["2006-N28",6,"第4节 个别氨基酸的代谢","酪氨酸的代谢",2006,28,"A","","酪氨酸在体内不能转变生成的是",[["A","肾上腺素"],["B","黑色素"],["C","延胡索酸"],["D","苯丙氨酸"],["E","乙酰乙酸"]],"D","酪氨酸的代谢途径主要有三条：①酪氨酸→多巴→多巴胺→去甲肾上腺素→肾上腺素（A对）；②酪氨酸→多巴→多巴醌→吲哚醌→黑色素（B对）；③酪氨酸→羟苯丙酮酸→尿黑酸→延胡索酸（C对）+乙酰乙酸（E对）。苯丙氨酸可在苯丙氨酸羟化酶催化下转变为酪氨酸，该反应不可逆，酪氨酸不能转变为苯丙氨酸（因此苯丙氨酸为必需氨基酸，而酪氨酸不是）（D错，为本题正确答案）。","","N"],["2006-N29",7,"第2节 线粒体氧化体系与呼吸链","细胞色素蛋白",2006,29,"A","","下列关于细胞色素的叙述，正确的是",[["A","是一类以铁卟啉为辅基的酶"],["B","都紧密结合在线粒体内膜上"],["C","是呼吸链中的递氢体"],["D","在呼吸链中按Cytb-Cytc-Cytc₁-Cytaa₃排列"],["E","又称为细胞色素氧化酶"]],"A","细胞色素是一类以血红素（化学结构上，由卟啉环和Fe²⁺鳌合而成）作为辅基的电子传递蛋白（A对），它通过其血红素辅基中铁原子的还原态（Fe²⁺）和氧化态（Fe³⁺）之间的可逆变化传递电子，因而它是氧化呼吸链中的单电子传递体（C错）。根据吸收光谱和最大吸收波长的不同，可将线粒体细胞色素分为细胞色素a、b、c，其中细胞色素a、b与线粒体内膜结合紧密（十版生物化学P200），镶嵌于线粒体内膜中，而Cyt c属于水溶性蛋白，与线粒体内膜外表面疏松结合（B错），它不包含在任何一种复合体中。在呼吸链中，细胞色素的排列顺序（电子传递的顺序）为Cyt b→Cyt c₁→Cyt c→Cytaa₃（D错）。九版教材观点氧化呼吸链是由位于线粒体内膜、具有电子传递功能的4种蛋白酶复合体组成，分别称之为复合体Ⅰ、Ⅱ、Ⅲ和Ⅳ。复合体Ⅲ、Ⅳ又分别称之为泛醌-细胞色素c还原酶、细胞色素氧化酶（E错）。","","N"],["2006-N30",11,"第1节 DNA复制的基本规律","DNA复制以半不连续方式进行",2006,30,"A","","冈崎片段是指",[["A","复制起始时，RNA聚合酶合成的片段"],["B","两个复制起始点之间的DNA片段"],["C","DNA半不连续复制时出现的DNA片段"],["D","DNA连续复制时出现的DNA片段"],["E","E.coli复制起始点oriC的跨度为245bp的片段"]],"C","DNA的复制是半不连续的，前导链（领头链）的解链方向与复制叉前进的方向相同，子链可以沿5＇→3＇方向连续合成，而后随链（随从链）的解链方向与复制叉前进的方向相反，只能随着模板链的解开，间断地（不连续）沿5'-3'方向进行合成，合成的新的DNA片段称冈崎片段（以发现此片段的日本科学家冈崎而命名）（C对D错）。复制起始时，RNA聚合酶合成的片段为引物（十版生物化学P260）（A错）。两个复制起始点之间的DNA片段称为复制子（十版生物化学P257）（B错）。E.coli复制起始点oriC的跨度为245bp的片段（十版生物化学P263），如其本身所描述的，为原核生物E.coli（大肠杆菌）的复制起始位点，与冈崎片段无关（E错）。","","N"],["2006-N31",10,"第2节 真核基因的结构与功能","启动子的作用",2006,31,"A","","下列关于TATA盒的叙述，正确的是",[["A","是与RNA-pol稳定结合的序列"],["B","是蛋白质翻译的起始点"],["C","是DNA复制的起始点"],["D","是与核蛋白体稳定结合的序列"],["E","是远离转录起始点，增强转录活性的序列"]],"A","真核生物转录起始前的-25～-30bp区域多有典型的TATA序列，称为 TATA 盒，又称 Hognest 盒十版生物化学P280），通常认为是启动子的核心序列，可以通过转录因子TFⅡD（十版生物化学P329）与RNA聚合酶（RNA-pol）结合并控制转录（A对）。蛋白质翻译起始密码子AUG位于转录起始点下游，而TATA盒位于转录起始点上游（B错）。原核生物DNA复制的起始点是oriC（十版生物化学P263），真核生物复制的起始点被称为自主复制序列ARS（十版生物化学P266），均与TATA盒无关（C错）。在蛋白质合成时，与核蛋白体（核糖体）稳定结合的是mRNA（十版生物化学P302），而不是DNA序列上的TATA盒（D错）。远离转录起始点，增强转录活性的序列是增强子（十版生物化学P247）（E错）。","","N"],["2006-N32",2,"第3节 RNA和空间结构与功能","rRNA的结构及功能",2006,32,"A","","下列关于核蛋白体的叙述，正确的是",[["A","是遗传密码的携带者"],["B","由rRNA与蛋白质构成"],["C","由snRNA与hnRNA构成"],["D","由DNA与蛋白质构成"],["E","由引物、DNA和蛋白质构成"]],"B","核蛋白体又称为核糖体，由大小亚基组成，大小亚基又分别由一定种类的蛋白质和rRNA组成（B对）。遗传密码的携带者是mRNA（A错）。由snRNA与hnRNA构成的是剪接hnRNA的剪接体（十版生物化学P70）（C错）。由DNA与蛋白质构成的是染色体（D错）。由引物、DNA和蛋白质构成的是正在合成引物的引发体（十版生物化学P264）（E错）。","","N"],["2006-N33",16,"第2节 重组DNA技术","克隆载体概述",2006,33,"A","","下列DNA中，一般不用作克隆载体的是",[["A","质粒DNA"],["B","大肠杆菌DNA"],["C","病毒DNA"],["D","噬菌体DNA"],["E","酵母人工染色体"]],"B","载体按功能分为克隆载体和表达载体两大类，其中克隆载体用于外源DNA片段在受体细胞中的克隆扩增。常用的克隆载体主要有质粒DNA（A对）、噬菌体DNA（D对）和病毒DNA（C对），为了增加克隆载体插入外源基因的容量，还设计有柯斯质粒、细菌人工染色体、酵母人工染色体（E对）等载体。大肠杆菌的基因组包括染色体DNA和质粒DNA两个部分，染色体DNA（即选项中的大肠杆菌DNA）不具备克隆载体的基本特点（自主复制、选择标志及单一酶切位点），一般不用作克隆载体（B错，为本题正确答案）。","","N"],["2006-N34",14,"第2节 原核基因表达调控","乳糖操纵子的结构",2006,34,"A","","下列哪种乳糖操纵子序列能与RNA聚合酶结合",[["A","P序列"],["B","O序列"],["C","CAP结合位点"],["D","I基因"],["E","Z基因"]],"A","启动子是RNA聚合酶结合的DNA序列，也是控制转录的关键部位。乳糖操纵子中的启动子是P序列，即P序列（A对）能与RNA聚合酶结合。O序列（B错）是操纵序列，能与阻遏蛋白结合。CAP结合位点（C错）能与分解代谢物基因激活蛋白（CAP）结合。I基因（D错）是调节基因，它有独立的启动子PI，可以编码一种阻遏蛋白，后者可与O序列结合，使操纵子受阻遏而处于关闭状态。Z基因（E错）是乳糖操纵子的结构基因。","","N"],["2006-N35",21,"第4节 胆色素的代谢与黄疸","结合",2006,35,"A","","下列哪种物质是结合胆红素",[["A","胆红素-清蛋白"],["B","胆红素-Y蛋白"],["C","胆红素-Z蛋白"],["D","双葡糖醛酸胆红素"],["E","胆红素-结合珠蛋白"]],"D","结合胆红素主要是指在肝细胞的滑面内质网内，胆红素经UDP-葡糖醛酸基转移酶的催化，与2分子葡糖醛酸结合生成的双葡糖醛酸胆红素（D对）。胆红素-清蛋白（A错）是游离胆红素（未结合胆红素）在血液中的运输形式。胆红素-Y蛋白（B错）和胆红素-Z蛋白（C错）是游离胆红素在肝细胞内的运输形式。结合珠蛋白（十版生物化学P461）不与游离胆红素结合（E错），而与游离血红蛋白结合形成血红蛋白-结合珠蛋白，介导血红蛋白在血液中的运输，避免游离血红蛋白直接从肾小球滤过。","","N"],["2006-N36",17,"第2节 细胞内信号转导分子","环核苷酸类第二信使",2006,36,"A","","下列哪种酶激活后会直接引起cAMP浓度降低",[["A","蛋白激酶A"],["B","蛋白激酶C"],["C","磷酸二酯酶"],["D","磷脂酶C"],["E","蛋白激酶G"]],"C","磷酸二酯酶（PDE）（C对）能催化环核苷酸水解，激活后会直接引起cAMP浓度降低。如在脂肪细胞中，胰高血糖素在升高cAMP水平的同时会增加PDE活性，促进cAMP的水解，使其浓度下降，这是调节cAMP浓度的重要机制。","","N"],["2006-N111",8,"第2节 嘌呤核苷酸的合成与分解代谢","脱氧核苷酸的生成",2006,111,"B","","能直接转变生成dUDP的化合物是",[["A","UTP"],["B","UDP"],["C","UMP"],["D","IMP"],["E","dUMP"]],"B","脱氧核糖核苷酸主要通过相应的核糖核苷酸的直接还原生成，这种还原作用主要在二磷酸核苷水平进行，即NDP→dNDP（N代表A、G、U、C等碱基），因此dUDP由UDP（B对）直接转变而生成。","","N"],["2006-N112",8,"第3节 嘧啶核苷酸的合成与分解代谢","dTMP的生成",2006,112,"B","","能直接转变生成dTMP的化合物是",[["A","UTP"],["B","UDP"],["C","UMP"],["D","IMP"],["E","dUMP"]],"E","脱氧核糖核苷酸的生成主要是在二磷酸核苷水平进行的，即NDP→dNDP（N代表A、G、U、C等碱基）。但脱氧胸腺嘧啶核苷酸的合成是在一磷酸核苷水平进行的：dTMP是由dUMP（E对）经甲基化而生成。","","N"],["2006-N113",13,"第5节 蛋白质合成的干扰和抑制","引起读码错误的抗生素",2006,113,"B","","能与原核生物核蛋白体小亚基结合，改变其构象，引起读码错误的抗菌素是",[["A","四环素"],["B","氯霉素"],["C","链霉素"],["D","嘌呤霉素"],["E","放线菌酮"]],"C","链霉素（C对）能与原核生物核蛋白体小亚基（30S亚基）结合，改变其构象，影响A位上氨基酰-tRNA与其对应的密码子配对的精确性，引起读码错误。四环素（A错）能与原核生物核蛋白体小亚基的A位结合，抑制氨基酰-tRNA的进位。氯霉素（B错）能与原核生物核蛋白体的大亚基结合，抑制转肽酶活性，从而阻断原核生物翻译延长过程。嘌呤霉素（D错）的结构与酪氨酰-tRNA相似，在翻译中可取代酪氨酰-tRNA而进入核糖体A位，中断肽链合成。放线菌酮（E错）则能与真核生物核蛋白体的大亚基结合，抑制转肽酶活性，阻断真核生物翻译延长过程。","","N"],["2006-N114",13,"第5节 蛋白质合成的干扰和抑制","影响成肽的抗生素",2006,114,"B","","能与原核生物的核蛋白体大亚基结合的抗菌素是",[["A","四环素"],["B","氯霉素"],["C","链霉素"],["D","嘌呤霉素"],["E","放线菌酮"]],"B","氯霉素（B对）能与原核生物核蛋白体的大亚基（50S亚基）结合，抑制转肽酶活性，从而阻断原核生物翻译延长过程。四环素（A错）能与原核生物核蛋白体小亚基的A位结合，抑制氨基酰-tRNA的进位。链霉素（C错）能与原核生物核蛋白体小亚基结合，改变其构象，影响A位上氨基酰-tRNA与其对应的密码子配对的精确性，引起读码错误。嘌呤霉素（D错）的结构与酪氨酰-tRNA相似，在翻译中可取代酪氨酰-tRNA而进入核糖体A位，中断肽链合成。放线菌酮（E错）则能与真核生物核蛋白体的大亚基结合，抑制转肽酶活性，阻断真核生物翻译延长过程。","","N"],["2006-N133",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径的概述",2006,133,"X","","嘌呤碱的合成原料有",[["A","甘氨酸"],["B","天冬酰胺"],["C","谷氨酸"],["D","CO₂"]],"AD","嘌呤碱的合成原料包括天冬氨酸（非天冬酰胺）（B错）、谷氨酰胺（非谷氨酸）（C错）、甘氨酸（A对）、CO₂（D对）及甲酰基（一碳单位）等。","","N"],["2006-N134",6,"第2节 氨基酸的一般代谢","α-酮酸转变成糖和脂质",2006,134,"X","","谷氨酰胺在体内的代谢去路是",[["A","参与血红素的合成"],["B","参与嘌呤嘧啶核苷酸合成"],["C","异生成糖"],["D","氧化供能"]],"BCD","谷氨酰胺在体内既可参与嘌呤核苷酸的合成，又可参与嘧啶核苷酸的合成（B对）。谷氨酰胺是生糖氨基酸，因此可以异生成糖（C对）。谷氨酰胺可在谷氨酰胺酶（十版生物化学P180）催化下水解为谷氨酸和氨，进一步谷氨酸可在谷氨酸脱氢酶（十版生物化学P178）催化下水解为α-酮戊二酸和氨，最终α-酮戊二酸可进入三羧酸循环和生物氧化过程彻底氧化为CO₂和H₂O，并释放能量（D对）。血红素合成（A错）的基本原料是琥珀酰CoA、甘氨酸和Fe²⁺，与谷氨酰胺无关。","","N"],["2006-N135",11,"第2节 DNA复制的酶学和拓扑学","多种酶参与DNA解链和稳定单链状态",2006,135,"X","","参与DNA复制起始的有",[["A","Dna蛋白"],["B","SSB"],["C","解螺旋酶"],["D","RNA酶"]],"ABC","由表15-2可知，参与DNA复制起始的有Dna蛋白（A对）、SSB（单链结合蛋白）（B对）和拓扑异构酶，其中Dna蛋白可进一步分为辨认复制起始位点的DnaA、解开DNA双链的DnaB（解旋酶）（C对）、运送和协同DnaB的DnaC、催化RNA引物生成的DnaG（引物酶）。RNA酶（十版生物化学P217）（D错）为DNA复制结束后水解RNA引物的酶。","","N"],["2006-N136",14,"第3节 真核基因表达调控","转录起始的关键调节部位",2006,136,"X","","下列选项中，属于顺式作用元件的有",[["A","启动子"],["B","增强子"],["C","沉默子"],["D","操纵子"]],"ABC","顺式作用元件是真核生物的一段具有特定功能的DNA，当这段DNA可以和RNA pol结合并形成转录起始复合体时，我们将这段DNA称之为启动子（A对），大部分的启动子位于转录起始点的上游；而当这一段DNA序列可以提高启动子的工作效率，我们称之为增强子（B对），增强子的定位相对宽松，可以在上游也可以在下游；和前两种DNA序列功能相反的是沉默子（C对），它是可以抑制基因转录的一段DNA序列。操纵子（D错）是原核生物的转录调控序列，如乳糖操纵子（十版生物化学P319）。","","N"],["2007-N23",0,"第4节 蛋白质的理化性质","变性",2007,23,"A","","蛋白质变性是由于",[["A","蛋白质空间构象的破坏"],["B","氨基酸组成的改变"],["C","肽键的断裂"],["D","蛋白质的水解"]],"A","在某些物理和化学因素作用下，其特定的空间构象被破坏（A对），也即有序的空间结构变成无序的空间结构，从而导致其理化性质的改变和生物学活性丧失，称为蛋白质变性。蛋白质的变性主要是空间结构（即二三四级结构）的破坏，不涉及一级结构的改变，即氨基酸的组成不会发生改变（B错），维系蛋白质一级结构的肽键也不会断裂（C错）。","","N"],["2007-N24",2,"第4节 核酸的理化性质","紫外吸收",2007,24,"A","","核酸的最大紫外光吸收值一般在哪一波长附近",[["A","280nm"],["B","260nm"],["C","240nm"],["D","220nm"]],"B","核苷酸紫外光最大吸收值位于260nm（B对）附近。280nm（十版生物化学P29）（A错）为蛋白质的紫外光最大吸收值。","","N"],["2007-N25",2,"第4节 核酸的理化性质","DNA变性",2007,25,"A","","核酸变性后，可产生的效应是",[["A","增色效应"],["B","最大吸收波长发生转移"],["C","失去对紫外线的吸收能力"],["D","溶液黏度增加"]],"A","某些理化因素（温度、pH、离子强度）会导致DNA双链互补碱基对之间的氢键发生断裂，使DNA双链解链为单链，这种现象称为DNA变性。变性破坏了DNA的空间结构，但是没有改变核苷酸序列和性质，因此核酸紫外光吸收的能力和波长不发生变化（BC错）。在DNA解链过程中，有更多的共轭双键得以暴露，含有DNA的溶液在260nm处的吸光度随之增加，这种现象称为DNA的增色效应（A对）。DNA双链变性后解离成单链，分子的对称性消失，故溶液黏度降低（D错）。","","N"],["2007-N26",2,"第3节 RNA和空间结构与功能","核酶的分类及空间构象",2007,26,"A","","下列关于ribozyme的叙述，正确的是",[["A","即核酸酶"],["B","本质是蛋白质"],["C","本质是核糖核酸"],["D","其辅酶是辅酶A"]],"C","核酶（ribozyme）是具有催化作用的RNA，它的本质是核糖核酸（C对B错）。核酸酶（十版生物化学P51）是所有可以水解核酸的酶（根据核酸酶的定义，核酶属于核酸酶的一种特殊类型）（A错），绝大部分核酸酶的化学本质为蛋白质，依据核酸酶底物的不同可以将其分为DNA酶（DNase）和RNA酶（RNase）两类。辅酶A为酰基转移酶的辅酶（十版生物化学P35）（D错），广泛参与糖、脂类、蛋白质代谢及肝的生物转化作用。","","N"],["2007-N27",4,"第6节 糖异生","糖异生的关键酶及耗能",2007,27,"A","","在糖酵解和糖异生中均起作用的酶是",[["A","丙酮酸羧化酶"],["B","磷酸甘油酸激酶"],["C","果糖二磷酸酶"],["D","丙酮酸激酶"]],"B","糖异生与糖酵解的多数反应是可逆的，但糖异生不完全是糖酵解的逆反应，糖酵解中3个关键酶催化的限速步骤所对应的逆反应需要糖异生特有的关键酶来催化。糖酵解的关键酶是己糖激酶、磷酸果糖激酶-1、丙酮酸激酶（D错）。糖异生的关键酶是丙酮酸羧化酶（A错）、磷酸烯醇式丙酮酸羧激酶、果糖二磷酸酶-1（C错）、葡萄糖-6-磷酸酶。除了上述几种酶外，其余的酶均催化可逆反应，在糖异生和糖酵解中均起作用。磷酸甘油酸激酶（B对）可以催化1，3-二磷酸甘油酸与3-磷酸甘油酸的互变反应，在糖异生和糖酵解中均起作用。","","N"],["2007-N28",5,"第3节 甘油三酯代谢","酮体的生成",2007,28,"A","","脂肪酸β氧化，酮体生成及胆固醇合成的共同中间产物是",[["A","乙酰乙酰辅酶A"],["B","甲基二羟戊酸"],["C","HMG-CoA"],["D","乙酰乙酸"]],"A","胆固醇合成和酮体合成的前两个步骤是相同的：第一步，2分子乙酰CoA在乙酰乙酰CoA硫解酶作用下，缩合成乙酰乙酰CoA；第二步，乙酰乙酰CoA在HMG-CoA（羟甲基戊二酸单酰CoA）合酶作用下，再与1分子乙酰CoA缩合成HMG-CoA。进入第三步之后，在线粒体中，HMG-CoA在HMG-CoA裂解酶作用下生成酮体之一的乙酰乙酸（十版生物化学P149）（D错），在胞质中，HMG-CoA在HMG-CoA还原酶作用下生成胆固醇的前体甲基二羟戊酸（十版生物化学P159）（B错）。因此，酮体生成及胆固醇合成拥有共同的中间产物乙酰乙酰CoA和HMG-CoA。本题还需要考虑脂肪酸β-氧化的情况，脂肪酸活化为脂酰CoA之后进入线粒体进行β-氧化，脂酰CoA每进行一次β-氧化将生成少两个碳原子的新的脂酰CoA，当新脂酰CoA还剩4个碳原子时为丁酰CoA，丁酰CoA再进行“脱氢”→“水化”→“再脱氢”后即生成乙酰乙酰CoA。因此，脂肪酸β氧化，酮体生成及胆固醇合成的共同中间产物是乙酰乙酰CoA（A对）。","","N"],["2007-N29",7,"第4节 氧化磷酸化的影响因素","解耦联剂阻断ADP的磷酸化过程",2007,29,"A","","下列关于线粒体氧化磷酸化解偶联的叙述，正确的是",[["A","ADP磷酸化作用加速氧的利用"],["B","ADP磷酸化作用继续，但氧利用停止"],["C","ADP磷酸化停止，但氧利用继续"],["D","ADP磷酸化无变化，但氧利用停止"]],"C","解偶联是指氧化与磷酸化的偶联脱离，即物质脱下的氢仍可通过递氢递电子体传给O₂生成H₂0（氧化过程在继续），但在递氢递电子过程中所释放的能量不能用于ADP磷酸化合成ATP（磷酸化过程停止）（C对）。","","N"],["2007-N30",6,"第2节 氨基酸的一般代谢","氨基酸氧化脱氨基",2007,30,"A","","肌肉中氨基酸脱氨基作用的主要方式是",[["A","嘌呤核苷酸循环"],["B","谷氨酸氧化脱氨基作用"],["C","转氨基作用"],["D","转氨基与谷氨酸氧化脱氨基的联合"]],"A","机体大多组织器官是通过联合脱氨基作用脱去氨基，联合脱氨基作用是指转氨基作用与谷氨酸的氧化脱氨基作用偶联进行，把氨基酸转变为NH₃及相应α-酮酸。但在心肌和骨骼肌中L-谷氨酸脱氢酶的活性很弱，氨基酸很难通过联合脱氨基作用（D错）脱去氨基。这些组织中，氨基酸主要通过嘌呤核苷酸循环脱去氨基（A对）（记忆为漂亮（嘌呤）的耳机（二肌））。此外，在肝肾组织中还存在L-氨基酸氧化酶，也可以进行脱氨基作用。转氨基作用（C错）仅有氨基的转移，并没有氨基的真正脱落。谷氨酸氧化脱氨基作用（B错）仅使谷氨酸的氨基脱落。","","N"],["2007-N31",6,"第3节 氨的代谢","丙氨酸-葡萄糖循环",2007,31,"A","","氨由肌肉组织通过血液向肝进行转运的机制是",[["A","三羧酸循环"],["B","鸟氨酸循环"],["C","丙氨酸-葡萄糖循环"],["D","甲硫氨酸循环"]],"C","氨是体内的有毒物质，各组织必须以无毒的形式通过血液将氨运输到肝脏代谢。氨可以通过丙氨酸-葡萄糖循环（C对）将氨转变为丙氨酸从骨骼肌运往肝，也可以通过谷氨酰胺从脑和骨骼肌运往肝或肾。三羧酸循环（十版生物化学P114） （A错）又称柠檬酸循环，是三大营养物质代谢的最终代谢通路。鸟氨酸循环（十版生物化学P182）（B错）又称尿素循环，参与尿素的生成。甲硫氨酸循环（十版生物化学P189）（D错）参与甲硫氨酸的转甲基作用，为机体提供活性甲基。","","N"],["2007-N32",8,"第3节 嘧啶核苷酸的合成与分解代谢","dTMP的生成",2007,32,"A","","合成dTMP的直接前体是",[["A","dUMP"],["B","dCDP"],["C","dUDP"],["D","dCMP"]],"A","脱氧核糖核苷酸的生成主要是在二磷酸核苷水平进行的，即NDP→dNDP（N代表A、G、U、C等碱基）。但脱氧胸腺嘧啶核苷酸的合成是在一磷酸核苷水平进行的：dTMP是由dUMP（A对）经甲基化而生成。","","N"],["2007-N33",4,"第3节 糖的有氧氧化","三羧酸循环的关键酶",2007,33,"A","","三羧酸循环中的不可逆反应是",[["A","草酰乙酸→柠檬酸"],["B","琥珀酰CoA→琥珀酸"],["C","琥珀酸→延胡索酸"],["D","延胡索酸→苹果酸"]],"A","三羧酸的三个关键酶分别是柠檬酸合酶，异柠檬酸脱氢酶和α-酮戊二酸脱氢酶复合体，它们催化的反应分别是乙酰辅酶A与草酰乙酸缩合成柠檬酸（A对）、异柠檬酸氧化脱羧转变为α-酮戊二酸、α-酮戊二酸氧化脱羧生成琥珀酰CoA。","","N"],["2007-N34",19,"第2节 癌基因","原癌基因",2007,34,"A","","下列关于细胞原癌基因的叙述，正确的是",[["A","存在于DNA病毒中"],["B","存在于正常真核生物基因组中"],["C","存在于RNA病毒中"],["D","正常细胞含有即可导致肿瘤的发生"]],"B","癌基因虽然最早在可导致肿瘤发生的病毒中被鉴定，但这些基因原本就存在于大部分生物的正常基因组中，人们把存在于病毒中的能够使靶细胞发生恶性转化的基因称为病毒癌基因（AC错），把存在于生物正常细胞基因组中的癌基因称为原癌基因（B对）。原癌基因在正常细胞内处于静止或低表达状态，不仅对细胞无害，而且对于维持细胞正常生理功能具有重要意义，只有受到致癌因素作用而被活化时，才引起细胞癌变，导致肿瘤的发生（D错）。","","N"],["2007-N35",14,"第2节 原核基因表达调控","操纵子",2007,35,"A","","基因启动子是指",[["A","编码mRNA的DNA序列的第一个外显子"],["B","开始转录生成mRNA的那段DNA序列"],["C","阻遏蛋白结合的DNA序列"],["D","RNA聚合酶最初与DNA结合的那段DNA序列"]],"D","启动子是RNA聚合酶与DNA分子结合并形成转录起始复合体的序列，该序列也是RNA聚合酶最初与DNA结合的序列（D对）。外显子为真核生物编码序列中出现在成熟mRNA分子上的序列，而启动子为原核生物和真核生物均存在的非编码序列（A错）。在mRNA转录中，启动子序列本身不被转录（但编码tRNA基因的启动子可以被转录）（十版生物化学P246）（B错）。阻遏蛋白是原核生物操纵子的负性调控蛋白，其结合的DNA序列称为操纵元件（C错）。","","N"],["2007-N36",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物的转录终止和加尾修饰",2007,36,"A","","RNA转录与DNA复制中的不同点是",[["A","遗传信息储存于碱基排列的顺序中"],["B","新生链的合成以碱基配对的原则进行"],["C","合成方向为5'-3'"],["D","RNA聚合酶缺乏校正功能"]],"D","DNA复制与RNA转录都是酶促的核苷酸聚合过程，有许多相似之处：它们的遗传信息均是储存在DNA的碱基排列顺序中（以DNA为模板）（A错）；都需依赖DNA的聚合酶；聚合过程都是核苷酸之间生成3’，5’-磷酸二酯键；都是按照碱基互补配对的原则进行合成（B错）；合成方向均为5’-3’方向（C错）。当然，DNA复制与RNA转录毕竟为两种不同的合成过程，二者之间相似之中又有区别（详见P312 表16-1），如复制和转录虽然都需要依赖DNA的聚合酶，但前者需要的是依赖DNA的DNA聚合酶，后者需要的是依赖DNA的RNA聚合酶，DNA聚合酶除了有5’→3’聚合作用外，还有3’→5’外切酶活性，因此DNA 聚合酶有校正功能，而RNA聚合酶没有3’→5’外切酶活性，缺乏校正功能（D对）。","","N"],["2007-N109",6,"第4节 个别氨基酸的代谢","酪氨酸的代谢",2007,109,"B","","去甲肾上腺素合成的原料是",[["A","甘氨酸"],["B","色氨酸"],["C","酪氨酸"],["D","谷氨酸"]],"C","酪氨酸（C对）经羟化（生成多巴）、脱羧（生成多巴胺）、再羟化等步骤即可生成去甲肾上腺素。","","N"],["2007-N110",6,"第4节 个别氨基酸的代谢","谷氨酸脱羧生成γ-氨基丁酸",2007,110,"B","","γ-氨基丁酸合成的原料是",[["A","甘氨酸"],["B","色氨酸"],["C","酪氨酸"],["D","谷氨酸"]],"D","谷氨酸（D对）在谷氨酸脱羧酶的催化下可脱去羧基生成γ-氨基丁酸（GABA）。甘氨酸（A错）是糖异生（十版生物化学P128）、一碳单位生成（十版生物化学P187）、肌酸合成（十版生物化学P189）、嘌呤碱合成、生物转化结合反应（如合成结合胆汁酸）、血红素合成（十版生物化学P485）等生物合成反应的原料。色氨酸（十版生物化学P186）（B错）是神经递质5-羟色胺的合成原料。酪氨酸（十版生物化学P191）（C错）是多巴胺、去甲肾上腺素、肾上腺素等儿茶酚胺类神经递质及黑色素的合成原料。","","N"],["2007-N111",19,"第3节 抑癌基因","抑癌基因对细胞增殖起负性调控作用",2007,111,"B","","p53基因是一种",[["A","细胞原癌基因"],["B","抑癌基因"],["C","病毒癌基因"],["D","操纵子调节基因"]],"B","p53基因是迄今为止发现的与人类肿瘤相关性最高的基因。过去一直把它当成一种癌基因（AC错），后来证实起癌基因作用的是突变后的p53基因，而p53基因本身是一种抑癌基因（B对）。操纵子调节基因（十版生物化学P320）（D错）为原核生物操纵子结构内编码调控蛋白（与操纵序列结合的蛋白）的基因。","","N"],["2007-N112",19,"第2节 癌基因","生长因子的概述",2007,112,"B","","正常细胞内可以编码生长因子的基因是",[["A","细胞原癌基因"],["B","抑癌基因"],["C","病毒癌基因"],["D","操纵子调节基因"]],"A","细胞原癌基因（A对）的表达产物包括生长因子、生长因子受体、细胞信号转导分子以及与生长有关的转录调节因子等，是正常细胞生理功能的重要组成部分。抑癌基因（十版生物化学P441）（B错）是一类抑制细胞过度生长、增殖从而遏制肿瘤形成的基因，其基因编码产物包括转录因子（如Rb、p53）、信号通路抑制因子（如PTEN、NF1）等（P441表23-3 常见的抑癌基因及其编码产物）。正常细胞内不存在病毒癌基因（病毒癌基因大多数位于逆转录病毒内）（C错）。操纵子调节基因（十版生物化学P320）（D错）为原核生物操纵子结构内编码调控蛋白（与操纵序列结合的蛋白）的基因。","","N"],["2007-N113",4,"第3节 糖的有氧氧化","三羧酸循环的概念",2007,113,"B","","糖异生和三羧酸循环共同的代谢场所是",[["A","溶酶体"],["B","内质网"],["C","线粒体"],["D","细胞液"]],"C","三羧酸循环发生的部位是线粒体。糖异生大部分过程发生在细胞液，但糖异生的关键酶之一丙酮酸羧化酶只存在于线粒体，胞液中的丙酮酸必须进入线粒体，才能羧化生成草酰乙酸。因此三羧酸循环和糖异生共同的代谢场所是线粒体（C对）。","","N"],["2007-N114",5,"第5节 胆固醇代谢","胆固醇的合成场所",2007,114,"B","","胆固醇合成和磷脂合成的共同代谢场所是",[["A","溶酶体"],["B","内质网"],["C","线粒体"],["D","细胞液"]],"B","胆固醇合成发生在细胞质（细胞液）和内质网，磷脂合成发生在内质网，故它们共同的代谢场所是内质网（B对）。溶酶体（十版生物化学P175）（A错）内含大量组织蛋白酶，可通过ATP非依赖途径降解蛋白质。线粒体（C错）是细胞有氧氧化及能量生成的主要场所。细胞液（D错）参与胆固醇的合成，但不参与磷脂的合成。","","N"],["2007-N133",1,"第2节 酶的工作原理","酶不同于一般催化剂的特点",2007,133,"X","","酶与一般催化剂相比，不同点有",[["A","反应条件温和，可在常温、常压下进行"],["B","加速化学反应速度，可改变反应平衡点"],["C","专一性强，一种酶只作用一种或一类物质"],["D","在化学反应前后酶本身不发生质和量的改变"]],"AC","酶与一般催化剂一样，在化学反应前后都没有质和量的改变（D错）。它们都只能催化热力学允许的化学反应；只能加速反应的进程，而不改变反应的平衡点（B错），即不改变反应的平衡常数。由于酶的化学本质是蛋白质，因此酶促反应又具有不同于一般催化剂催化反应的特点和反应机制：①对底物具有极高的催化效率，比一般的催化剂高10⁷～10¹³倍。②酶对底物具有高度的特异性，即一种酶只作用于一种或一类物质（C对）。③酶的活性与酶量具有可调节性。④酶具有不稳定性，在某些理化因素作用下酶会发生变性而失活，因此它所要求的反应条件比较温和，往往在常温，常压的条件下进行（A对）。","","N"],["2007-N134",4,"第4节 戊糖磷酸途径","戊糖磷酸途径的意义",2007,134,"X","","磷酸戊糖途径的重要生理功能有",[["A","是糖、脂、氨基酸的代谢枢纽"],["B","为脂肪酸合成提供NADPH"],["C","为核酸合成提供原料"],["D","为胆固醇合成提供NADPH"]],"BCD","磷酸戊糖途径是指从糖酵解的中间产物葡糖-6-磷酸开始形成旁路，通过氧化、基团转移两个阶段生成果糖-6-磷酸和3-磷酸甘油醛，从而返回糖酵解的代谢途径。磷酸戊糖途径虽然不能提供ATP，但是可以生成NADPH和磷酸核糖。NADPH是许多合成代谢如脂肪酸（B对）和胆固醇（D对）合成的供氢体，磷酸核糖则可以为核苷酸从头合成（十版生物化学P218）提供原料（C对）。糖、脂、氨基酸的代谢枢纽是柠檬酸循环（三羧酸循环）（十版生物化学P117）（A错）。","","N"],["2007-N135",12,"第4节 真核生物非编码RNA的生物合成","真核前体tRNA的加工",2007,135,"X","","tRNA的前体加工包括",[["A","剪切5'和3'末端的多余核苷酸"],["B","去除内含子"],["C","3'末端加CCA"],["D","化学修饰"]],"ABCD","tRNA的前体需要多种转录后加工才能成为成熟的tRNA：①tRNA前体分子5’和3’端多余核苷酸被切除（A对）；②3’端多余核苷酸被切除后，再由核苷酸转移酶加上特有的CCA末端（C对）；③tRNA茎-环结构中的部分核苷酸碱基经化学修饰为稀有碱基（D对）；④剪接去除茎-环结构中的内含子（B对）。","","N"],["2007-N136",10,"第2节 真核基因的结构与功能","真核基因结构的特点",2007,136,"X","","真核基因的结构特点有",[["A","基因不连续性"],["B","单顺反子"],["C","含重复序列"],["D","一个启动基因后接有几个编码基因"]],"ABC","真核生物基因是由内含子和外显子组成，其编码基因被内含子分隔开，具有不连续性（十版生物化学P244）（A对），被称为断裂基因。真核生物一个结构基因转录生成一条mRNA，即mRNA是单顺反子（十版生物化学P324）（B对）。真核基因组中存在大量重复序列（十版生物化学P248）（C对），这些序列按重复频率的不同可分为高度重复序列、中度重复序列和低度重复序列三种。一个启动基因后接有几个编码基因（D错）被称为多顺反子（十版生物化学P319），多顺反子是原核基因的结构特点。","","N"],["2007-N163-J",13,"第4节 蛋白质合成后的加工和靶向输送","新生肽链折叠需要分子伴侣",2007,163,"A","B","分子伴侣可以协助蛋白质形成正确的空间构象。下列分子中，属于分子伴侣的是",[["A","胰岛素原"],["B","热休克蛋白"],["C","组蛋白"],["D","DNA结合蛋白"]],"B","分子伴侣是一系列指导新生肽链按照特定方式正确折叠的辅助性蛋白质，常见的分子伴侣包括热激蛋白（又称热休克蛋白）（B对）和伴侣蛋白等。胰岛素原（十版生物化学P308）（A错）为成熟胰岛素的前体。组蛋白（十版生物化学P325）（C错）为核小体的组成成分。DNA结合蛋白（十版生物化学P261）（D错）又称单链结合蛋白（SSB），可在DNA复制中稳定已解开的单链DNA。","","N"],["2007-N164-J",2,"第2节 DNA和空间结构与功能","DNA双螺旋的相关实验",2007,164,"A","B","按照Chargaff规则，下列关于DNA碱基组成的叙述，正确的是",[["A","A与C的含量相等"],["B","A+T=G+C"],["C","同一生物体，不同组织的DNA碱基的组成不同"],["D","不同生物体来源的DNA，碱基组成不同"]],"D","按照Chargaff规则，对于不同生物个体，由于基因序列不同，因此其碱基组成也是不同的（D对）。对于DNA双链来说，A与T的含量相等，C与G的含量相等（A错），所以A+T不一定等于C+G（B错）。对于同一生物体，不同组织的基因序列是相同的（但是不同组织的基因表达具有时间特异性和空间特异性），因此不同组织的DNA碱基的组成也是相同的（C错）。","","N"],["2007-N165-J",5,"第3节 甘油三酯代谢","酮体的氧化利用",2007,165,"A","B","先天缺乏琥珀酰CoA转硫酶的患者若长期摄取低糖膳食，将会产生的代谢障碍是",[["A","酮血症"],["B","高脂血症"],["C","低血糖"],["D","苯丙酮尿症"]],"A","心、肾、脑及骨骼肌线粒体内含琥珀酰CoA转硫酶，该酶可催化乙酰乙酸生成乙酰乙酰CoA，促进酮体的氧化利用。低糖膳食的患者脂肪动员加强，酮体生成增加，若缺乏琥珀酰CoA转硫酶，将导致酮体利用障碍，造成酮血症（A对）。正常人体内存在一整套精细调节糖代谢的机制，高糖膳食时血糖水平不会持续升高，低糖膳食时也不会出现低血糖现象（C错），低血糖多因糖代谢障碍引起（十版生物化学P134）。高脂血症（十版生物化学P168）（B错）常因血浆脂蛋白代谢紊乱引起。苯丙酮尿症（十版生物化学P191）（D错）见于先天性苯丙氨酸羟化酶缺乏患者。","","N"],["2007-N166-J",11,"第2节 DNA复制的酶学和拓扑学","真核细胞DNA聚合酶",2007,166,"A","B","真核细胞中主要的复制酶是",[["A","DNA-polα"],["B","DNA-polβ"],["C","DNA-polγ"],["D","DNA-polδ"]],"D","真核细胞中主要的复制酶（DNA聚合酶）有5种：①DNA pol α（A错）具有引物酶活性；②DNA pol β（B错）复制的保真度低，可能是参与应急修复的酶；③DNA pol γ（C错）是线粒体DNA复制的酶；④ DNA pol δ 负责合成后随链；⑤ DNA pol ε 负责合成前导链。本考点在九版教材有重大更新，八版教材中前导链和后随链均由DNA pol δ负责合成，故认为DNA pol δ（D对）是真核生物 DNA 链延长中起主要作用的复制酶。九版后教材指出DNA pol δ 负责合成后随链，而DNA pol ε 负责合成前导链，即按照最新教材观点，DNA pol δ 和DNA pol ε 均可认为是真核生物延长过程中主要的复制酶。","","N"],["2007-N167-J",16,"第2节 重组DNA技术","常用工具酶",2007,167,"A","B","在重组DNA技术中常用的工具酶是",[["A","拓扑酶"],["B","逆转录酶"],["C","解螺旋酶"],["D","RNA聚合酶"]],"B","重组DNA技术，又称分子克隆或DNA克隆或基因工程技术，其主要过程包括：将外源性目的DNA片段与载体连接，形成重组DNA分子，进而在受体细胞中复制、扩增，从而获得单一DNA分子的大量拷贝（十版生物化学P369）。重组DNA技术常用到的工具酶包括RE（限制性核酸内切酶）、DNA连接酶、DNA聚合酶Ⅰ、Klenow片段、逆转录酶（B对）、多聚核苷酸激酶、末端转移酶、碱性磷酸酶等。拓扑酶（十版生物化学P262）（A错）和解螺旋酶（十版生物化学P261）（C错）为参与内源性DNA复制的酶。RNA聚合酶（十版生物化学P274）（D错）为参与内源性DNA转录的酶。","","N"],["2007-N168-J",10,"第1节 概述","基因与基因组的概念",2007,168,"A","B","基因组是指",[["A","以转录组学为基础的研究领域"],["B","一种生物体具有的所有遗传信息的总和"],["C","研究基因的结构，功能及表达产物的学科领域"],["D","包括转录组学和蛋白质组学等内容的学科领域"]],"B","基因组是一个生物体内所有的遗传信息的总和（B对），对真核生物而言包括细胞核染色体DNA以及线粒体DNA所携带的所有遗传物质。基因组学（P251）研究基因的结构和功能，但不研究表达产物（C错），基因的表达产物是转录组学和蛋白质组学的研究任务。转录组学及蛋白质组学是以基因组学为基础发展而来（AD错），是与基因组学平行的学科领域。","","N"],["2007-N169-J",17,"第5节 细胞信号转导异常与疾病","信号转导分子的异常激活与失活",2007,169,"A","B","下列关于GTP结合蛋白（G蛋白）的叙述，错误的是",[["A","膜受体通过G蛋白与腺苷酸环化酶偶联"],["B","可催化GTP水解为GDP"],["C","霍乱毒素可使其失活"],["D","有三种亚基α、β、γ"]],"C","G蛋白是指能与鸟苷酸结合，具有GTP水解酶活性的一类信号转导蛋白。G蛋白由α、β、γ三种亚基组成（D对），其中α亚基具有GTP酶活性，可催化GTP水解为GDP（B对）。膜受体（G蛋白偶联受体）可激活G蛋白，活化的G蛋白进而可激活腺苷酸环化酶（AC）、磷脂酶C（PLC）等G蛋白效应分子（A对）。霍乱毒素能与G蛋白的α亚基结合，使其发生ADP-核糖化修饰，抑制其GTP酶活性，导致G蛋白被持续激活而致病（C错，为本题正确答案）。","","N"],["2007-N170-J",17,"第3节 细胞受体介导的细胞内信号转导","酶耦联受体的作用",2007,170,"A","B","下列因素中，与Ras蛋白活性无关的是",[["A","GTP"],["B","Grb2"],["C","鸟苷酸交换因子"],["D","鸟苷酸环化酶"]],"D","Ras蛋白（十版生物化学P390）与三聚体G蛋白一样具有鸟苷酸的结合位点和GTP酶活性，但该蛋白只有一条多肽链，分子量为21kDa，小于G蛋白，因此也称为低分子量G蛋白或小G蛋白。Ras 蛋白是酪氨酸激酶受体（PTK）信号通路中的信号分子，酪氨酸激酶受体属于酶联型受体，自身具有酪氨酸激酶活性，当酪氨酸激酶受体与配体（生长因子）结合后，发生自身磷酸化，磷酸化的酪氨酸激酶受体依次结合生长因子结合蛋白Grb2（growth factor binding protein 2）（B对）、鸟苷酸交换因子SOS（Son of Sevenless）（C对）和Ras蛋白，促进Ras蛋白释放GDP、结合GTP（A对）而被激活，活化的Ras蛋白进而激活MAPKKK及下游的信号通路（Ras→MAPKKK→MAPKK→MAPK）。鸟苷酸环化酶（GC）（九版生理学P30）又称鸟苷酸环化酶受体，与酪氨酸激酶受体同属于酶联型受体，与配体（心房钠尿肽、脑钠尿肽）结合后，可催化生成第二信使cGMP，与 Ras蛋白活性无关（D错，为本题正确答案）。","","N"],["2007-N171-J",15,"第2节 聚合酶链反应技术","PCR技术的工作原理",2007,171,"A","B","利用聚合酶链反应扩增特异DNA序列的重要原因之一是反应体系内存在",[["A","DNA聚合酶"],["B","特异RNA模板"],["C","特异DNA引物"],["D","特异RNA引物"]],"C","聚合酶链反应（PCR）是一种在体外大量扩增特异DNA序列（目的基因片段）的分子生物学技术。聚合酶链反应以拟扩增的DNA分子为模板，以1对与模板互补的特异核苷酸片段（DNA片段）为引物，以dNTP为基本原料，在耐热性DNA聚合酶作用下，扩增出大量特异DNA序列（目的基因片段）。扩增出的DNA序列的特异性取决于DNA引物的特异性，由于有特异DNA引物（C对D错）的存在，才能扩增出特异的DNA片段。DNA聚合酶为所有PCR反应所共有，不能决定反应特异性（A错）。PCR的模板是DNA而不是RNA（B错）。","","N"],["2008-N25",0,"第1节 蛋白质的分子组成","氨基酸的分类",2008,25,"A","","下列氨基酸中，属于酸性氨基酸的是",[["A","精氨酸"],["B","甘氨酸"],["C","亮氨酸"],["D","天冬氨酸"]],"D","酸性氨基酸包括天冬氨酸（D对）和谷氨酸，它们都含有两个羧基，可记忆为三（酸）伏（谷氨酸）天（天冬氨酸）。甘氨酸（B错）和亮氨酸（C错）为中性氨基酸（属于非极性脂肪族氨基酸），精氨酸（A错）为碱性氨基酸。","","N"],["2008-N26",2,"第3节 RNA和空间结构与功能","rRNA的结构及功能",2008,26,"A","","下列RNA中，参与形成原核生物50S大亚基的是",[["A","28SrRNA"],["B","23SrRNA"],["C","16SrRNA"],["D","hnRNA"]],"B","参与形成原核生物50S大亚基的是23SrRNA（B对）和5SrRNA。28SrRNA参与真核生物60S大亚基形成（A错）。16SrRNA参与原核生物30S小亚基形成（C错）。hnRNA为真核生物mRNA未成熟的前体，与原核生物大亚基无关（D错）。","","N"],["2008-N27",1,"第3节 酶促反应动力学","酶促反应动力学参数",2008,27,"A","","下列关于酶的Km值的叙述，正确的是",[["A","是反应速度达到最大速度时的底物浓度"],["B","不能反映酶对底物的亲和力"],["C","对有多个底物的酶，其Km值相同"],["D","对同一底物，不同的酶有不同的Km值"]],"D","Km即米氏常数，为酶的特征性常数，在数值上等于酶促反应速率为最大反应速率一半时的底物浓度（A错）。一定条件下，Km值可以表示酶对底物的亲和力（B错），Km越大，表示酶对底物的亲和力越小，Km越小，酶对底物的亲和力越大。Km的值并非固定不变，它与酶的结构、底物结构、反应环境的pH值和离子强度有关，因此同一底物，不同的酶有不同的Km值（D对），而同一种酶，不同的底物也有不同的Km值（C错）。","","N"],["2008-N28",4,"第3节 糖的有氧氧化","三羧酸循环的过程",2008,28,"A","","三羧酸循环中发生底物水平磷酸化的反应是",[["A","柠檬酸→异柠檬酸"],["B","异柠檬酸→α-酮戊二酸"],["C","α-酮戊二酸→琥珀酰辅酶A"],["D","琥珀酰辅酶A→琥珀酸"]],"D","底物分子中的能量直接以高能键形式转移给 ADP 或其他二磷酸核苷（GDP）生成 ATP 或其他三磷酸核苷（GTP），这个过程称为底物水平磷酸化（十版生物化学P108）。在三羧酸循环中发生一次底物水平磷酸化，即琥珀酰CoA在琥珀酰CoA合成酶催化下生成琥珀酸（D对），该反应是发生在线粒体的可逆反应，琥珀酰CoA的高能硫酯键水解，与GDP或 ADP 的磷酸化偶联，转变为新的高能磷酸键，最终生成 GTP或ATP。除此以外，三羧酸循环过程中发生四次氧化脱氢，分别是异柠檬酸→α-酮戊二酸（B错），α-酮戊二酸→琥珀酰辅酶A（C错），琥珀酸→延胡索酸，苹果酸→草酰乙酸。除琥珀酸→延胡索酸脱下的氢由 FAD 接受外，其余步骤脱下的氢均由 NAD⁺接受。","","N"],["2008-N29",4,"第6节 糖异生","糖异生的关键酶及耗能",2008,29,"A","","下列酶中，与丙酮酸生成糖无关的是",[["A","丙酮酸激酶"],["B","丙酮酸羧化酶"],["C","果糖双磷酸酶-1"],["D","葡萄糖-6-磷酸酶"]],"A","丙酮酸能够逆着糖酵解反应方向生成葡萄糖，乳酸和一些生糖氨基酸就是通过丙酮酸进入糖异生途径的。丙酮酸羧化酶（B对）、果糖双磷酸酶-1（C对）和葡萄糖-6-磷酸酶（D对）均为丙酮酸糖异生过程中的关键酶。丙酮酸激酶（A错，为本题正确答案）为糖酵解的关键酶。","","N"],["2008-N30",5,"第1节 脂质的构成、功能及分析","脂肪酸的生物学功能",2008,30,"A","","如果食物中长期缺乏植物油，将导致人体内减少的物质是",[["A","软油酸"],["B","油酸"],["C","花生四烯酸"],["D","胆固醇"]],"C","人体可以合成软油酸（A错）和油酸（B错）等单不饱和脂肪酸，但不能合成亚油酸、α-亚麻酸及花生四烯酸（C对）等多不饱和脂肪酸。植物因含有Δ⁹，Δ¹²及Δ¹⁵去饱和酶，能合成Δ⁹以上多不饱和脂肪酸，如果食物中长期缺乏植物油，将导致人体内多不饱和脂肪酸减少。人体可以乙酰CoA、NADPH及ATP为原料合成胆固醇（十版生物化学P159）（D错）。","","N"],["2008-N31",5,"第6节 血浆脂蛋白及其代谢","极低密度脂蛋白的功能和代谢途径",2008,31,"A","","下列脂蛋白形成障碍与脂肪肝的形成密切相关的是",[["A","CM"],["B","VLDL"],["C","LDL"],["D","HDL"]],"B","VLDL（极低密度脂蛋白）主要由肝细胞合成，主要功能是运输来源于肝、小肠等组织合成的内源性甘油三酯，是运输内源性甘油三酯的主要形式。VLDL（B对）形成障碍时，肝合成的甘油三酯无法转运出肝，将继续留在肝细胞浆中，可导致脂肪肝的形成。CM（乳糜微粒）主要转运外源性甘油三酯及胆固醇，若CM（A错）形成障碍时，体内的甘油三酯和胆固醇含量下降，不会导致脂肪肝形成。LDL（低密度脂蛋白）主要转运内源性胆固醇，HDL（高密度脂蛋白）主要逆向转运胆固醇，LDL（C 错）和HDL（D 错）均与动脉粥样硬化形成密切有关（前者促进后者抑制），而与脂肪肝形成无关。","","N"],["2008-N32",7,"第2节 线粒体氧化体系与呼吸链","甘油-3-磷酸穿梭",2008,32,"A","","胞质NADH经α-磷酸甘油穿梭后氧化磷酸化产生的ATP数是",[["A","1"],["B","2"],["C","3"],["D","4"]],"B","NADH不能自由透过线粒体内膜，细胞质中NADH进入线粒体有两种穿梭机制：①α-磷酸甘油穿梭机制，该机制主要存在于脑和骨骼肌中，1分子NADH经此穿梭产生1.5分子ATP（旧版教材为2分子ATP）（B对）；②苹果酸-天冬氨酸穿梭机制，该机制主要存在于肝和心肌中（记忆为心肝宝贝，因此产生的能量较高），1分子NADH经此穿梭产生2.5分子ATP（旧版教材为3分子ATP）。按照最新教材观点，为1.5分子ATP，无正确答案，但原答案选B。","","N"],["2008-N33",6,"第3节 氨的代谢","谷氨酰胺",2008,33,"A","","脑中氨的主要解毒方式是生成",[["A","尿素"],["B","丙氨酸"],["C","谷氨酰胺"],["D","天冬酰胺"]],"C","氨是体内的有毒物质，各组织必须以无毒的形式通过血液将氨运输到肝脏代谢。氨可以通过丙氨酸-葡萄糖循环将氨转变为丙氨酸（B错）从骨骼肌运往肝，也可以通过谷氨酰胺（C对）从脑和骨骼肌运往肝或肾。","","N"],["2008-N34",8,"第3节 嘧啶核苷酸的合成与分解代谢","dTMP的生成",2008,34,"A","","下列核苷酸可直接转变成dTMP的是",[["A","dUMP"],["B","dUDP"],["C","dCMP"],["D","dCDP"]],"A","脱氧核糖核苷酸的生成主要是在二磷酸核苷水平进行的，即NDP→dNDP（N代表A、G、U、C等碱基）。但脱氧胸腺嘧啶核苷酸的合成是在一磷酸核苷水平进行的：dTMP是由dUMP（A对）经甲基化而生成。","","N"],["2008-N35",11,"第2节 DNA复制的酶学和拓扑学","多种酶参与DNA解链和稳定单链状态",2008,35,"A","","下列复制起始相关蛋白质中，具有合成RNA引物作用的是",[["A","DnaA"],["B","DnaB"],["C","DnaC"],["D","DnaG"]],"D","由表14-4可知，原核生物复制中参与DNA解链的相关蛋白质中，DnaG（D对）为引物酶，具有合成RNA引物的作用（记忆技巧：Guide<引导>）。DnaA（A错）具有辨认复制起始位点的作用（记忆技巧：A为起始字母）。DnaB（B错）为解旋酶，具有解开DNA双链的作用（记忆技巧：掰<Bai>开双链，另B字母本身为螺旋状）。DnaC（C错）具有运送和协同DnaB的作用（记忆技巧：Carry<运送>/Cooperate<协同>）。","","N"],["2008-N36",12,"第3节 真核生物mRNA的转录、加工和降解","前体mRNA的剪接",2008,36,"A","","下列RNA中，参与形成小分子核糖核蛋白体的是",[["A","hnRNA"],["B","mRNA"],["C","snRNA"],["D","tRNA"]],"C","小分子核糖核蛋白体即剪接体，是剪接hnRNA（A错）内含子并生成mRNA（B错）的场所，由5种snRNA（核小RNA）（C对）和100种以上的蛋白质装配而成。tRNA（D错）具有转运功能，在蛋白质合成过程中作为各种氨基酸的载体，将氨基酸转呈递给mRNA。","","N"],["2008-N37",13,"第2节 蛋白质合成体系","遗传密码的作用",2008,37,"A","","下列氨基酸中，无相应遗传密码的是",[["A","异亮氨酸"],["B","天冬酰胺"],["C","脯氨酸"],["D","羟赖氨酸"]],"D","羟赖氨酸（D对）没有遗传密码，它是在蛋白质加工过程中，经赖氨酸羟基化修饰而来（七版生物化学P311）。异亮氨酸（A错）的遗传密码为AUU、AUC、AUA。天冬酰胺（B错）的遗传密码为AAU、AAC。脯氨酸（C错）的遗传密码为CCU、CCC、CCA、CCG。","","N"],["2008-N38",14,"第3节 真核基因表达调控","真核生物基因组的特点",2008,38,"A","","下列关于真核基因结构特点的叙述，错误的是",[["A","基因不连续"],["B","基因组结构庞大"],["C","含大量重复序列"],["D","转录产物为多顺反子"]],"D","真核生物一个结构基因转录生成一条mRNA，即其转录产物是单顺反子（十版生物化学P324）（D错，为本题正确答案）。真核生物基因是由内含子和外显子组成，其编码基因被内含子分隔开，具有不连续性（十版生物化学P244）（A对），被称为断裂基因。真核基因组结构庞大（B对），结构庞大的表现之一就是存在大量重复序列（十版生物化学P248）（C对），这些序列按重复频率的不同可分为高度重复序列、中度重复序列和低度重复序列三种。","","N"],["2008-N39",9,"第3节 代谢调节的主要方式","关键酶活性决定代谢途径的速率和方向",2008,39,"A","","变构调节和化学修饰调节的共同特点是",[["A","引起酶蛋白构象变化"],["B","酶蛋白发生共价修饰"],["C","属于快速调节方式"],["D","有放大效应"]],"C","变构调节（十版生物化学P49）又称别构调节，是指小分子化合物与酶蛋白分子活性中心以外的某一部位特异结合，引起酶蛋白分子构象变化（A错）、从而改变酶活性的调节方式。化学修饰调节（十版生物化学P49）是指酶蛋白肽链上的某些氨基酸残基可在另一酶的催化下，发生可逆的共价修饰（B错），从而改变酶活性的调节方式。变构调节和化学修饰调节均属于快速调节方式（C对）。有放大效应（D错）是化学修饰调节的特点。","","N"],["2008-N40",21,"第4节 胆色素的代谢与黄疸","血液中胆红素的运输形式",2008,40,"A","","下列血浆蛋白中，具有运输胆红素作用的是",[["A","白蛋白"],["B","α₁球蛋白"],["C","α₂球蛋白"],["D","β球蛋白"]],"A","胆红素在单核吞噬系统细胞生成以后释放入血，在血浆中与清蛋白（白蛋白）（A对）结合，以胆红素-清蛋白复合体形式存在和运输。","","N"],["2008-N127",16,"第2节 重组DNA技术","常用工具酶",2008,127,"B","","常用于合成cDNA第二链的酶是",[["A","Klenow片段"],["B","连接酶"],["C","碱性磷酸酶"],["D","末端转移酶"]],"A","Klenow片段即DNA聚合酶Ⅰ的大片段，保留了5'→3'聚合酶活性及3'→5'外切酶活性，常用于合成cDNA第二链（A对）和对双链DNA的3'端进行填补、标记。DNA连接酶（B错）用于催化DNA中相邻的5'-磷酸基和3'-羟基末端之间形成磷酸二酯键，使DNA切口封合或使两个DNA分子或片段连接。碱性磷酸酶（C错）常用于切除核酸分子5'末端的磷酸基。末端转移酶（D错）常用于在核酸分子3'-羟基末端进行同质多聚物加尾。","","N"],["2008-N128",16,"第2节 重组DNA技术","常用工具酶",2008,128,"B","","常用于标记双链DNA 3'端的酶是",[["A","Klenow片段"],["B","连接酶"],["C","碱性磷酸酶"],["D","末端转移酶"]],"A","Klenow片段（A对）即DNA聚合酶Ⅰ的大片段，保留了5'→3'聚合酶活性及3'→5'外切酶活性，常用于合成cDNA第二链和对双链DNA的3'端进行填补、标记。DNA连接酶（B错）用于催化DNA中相邻的5'-磷酸基和3'-羟基末端之间形成磷酸二酯键，使DNA切口封合或使两个DNA分子或片段连接。碱性磷酸酶（C错）常用于切除核酸分子5'末端的磷酸基。末端转移酶（D错）常用于在核酸分子3'-羟基末端进行同质多聚物加尾。","","N"],["2008-N129",12,"第2节 原核生物的转录","RNA聚合酶全酶",2008,129,"B","","原核生物中识别DNA模板转录起始点的亚基是",[["A","RNA聚合酶的α亚基"],["B","RNA聚合酶的σ亚基"],["C","RNA聚合酶的β亚基"],["D","RNA聚合酶的β＇亚基"]],"B","原核生物RNA 聚合酶为由5 种亚基 α₂ββ'ωσ 组成的六聚体蛋白质（九版之后的教材更新考点，八版为4 种亚基 α₂ββ'σ 组成的五聚体蛋白质）。各亚基的功能分别是：α 亚基（A错）决定哪些基因被转录；β 亚基（C错）促进聚合反应中磷酸二酯键的生成；β′亚基（D错）结合 DNA 模板，解开双螺旋；ω亚基与β′折叠和稳定性、σ募集等有关；σ 亚基（B 对）辨认 DNA 模板上的转录起始点，结合启动子。","","N"],["2008-N130",12,"第2节 原核生物的转录","RNA聚合酶全酶",2008,130,"B","","原核生物中决定转录基因类型的亚基是",[["A","RNA聚合酶的α亚基"],["B","RNA聚合酶的σ因子"],["C","RNA聚合酶的β亚基"],["D","RNA聚合酶的β＇亚基"]],"A","原核生物RNA 聚合酶为由5 种亚基 α₂ββ'ωσ 组成的六聚体蛋白质（九版之后的教材更新考点，八版为4 种亚基 α₂ββ'σ 组成的五聚体蛋白质）。各亚基的功能分别是：α 亚基（A对）决定哪些基因被转录；β 亚基（C错）促进聚合反应中磷酸二酯键的生成；β′亚基（D错）结合 DNA 模板，解开双螺旋；ω亚基与β′折叠和稳定性、σ募集等有关；σ 亚基（B错）辨认 DNA 模板上的转录起始点，结合启动子。","","N"],["2008-N131",14,"第2节 原核基因表达调控","乳糖操纵子的双重调节",2008,131,"B","","分解（代谢）物激活蛋白在DNA的结合部位是",[["A","CAP结合位点"],["B","启动序列"],["C","操纵序列"],["D","结构基因编码序列"]],"A","分解（代谢）物激活蛋白（catabolite gene activator protein，CAP）是一种典型的激活蛋白，它可与启动子P上游的CAP结合位点（A对）结合，提高RNA聚合酶与启动序列的结合能力，从而增强RNA聚合酶的转录活性（十版生物化学P319）。启动序列（启动子）（B错）是与RNA聚合酶和各种调控蛋白结合的部位（十版生物化学P319）。操纵序列（操纵元件）（C错）是与阻遏蛋白结合的部位（十版生物化学P320）。以上CAP结合位点、启动序列、操纵序列均为调控序列，各自存在与之结合的调控蛋白。结构基因编码序列（D错）为结构基因，不与任何调控蛋白结合。","","N"],["2008-N132",14,"第2节 原核基因表达调控","操纵子",2008,132,"B","","阻遏蛋白在DNA的结合部位是",[["A","CAP结合位点"],["B","启动序列"],["C","操纵序列"],["D","结构基因编码序列"]],"C","阻遏蛋白在DNA的结合部位是操纵序列（操纵元件）（C对）。CAP结合位点（A错）是与分解代谢物激活蛋白（CAP）结合的部位。启动序列（启动子）（B错）是与RNA聚合酶和各种调控蛋白结合的部位（十版生物化学P319）。以上CAP结合位点、启动序列、操纵序列均为调控序列，各自存在与之结合的调控蛋白。结构基因编码序列（D错）为结构基因，不与任何调控蛋白结合。","","N"],["2008-N157",5,"第3节 甘油三酯代谢","脂肪酸氧化产能",2008,157,"X","","下列化合物中，参与脂酸β-氧化的有",[["A","NAD⁺"],["B","NADP⁺"],["C","CoASH"],["D","FAD"]],"ACD","脂肪酸活化为脂酰CoA后，脂酰CoA进入线粒体，经脱氢（需要FAD）（D对）、加水、再脱氢（需要NAD⁺）（A对）、硫解（需要CoASH）（C对）等四步反应完成一次β-氧化。","","N"],["2008-N158",6,"第2节 氨基酸的一般代谢","α-酮酸转变成糖和脂质",2008,158,"X","","下列选项中，属于生酮兼生糖的氨基酸有",[["A","异亮氨酸"],["B","苯丙氨酸"],["C","酪氨酸"],["D","赖氨酸"]],"ABC","根据代谢产物的不同可以将氨基酸分为三类：①生酮氨基酸：亮氨酸、赖氨酸（D错），记忆口诀为同（酮）样（亮）来（赖）；②生酮兼生糖氨基酸：异亮氨酸（A对）、苯丙氨酸（B对）、酪氨酸（C对）、色氨酸、苏氨酸，记忆口诀为一（异）本（苯）落（酪）色（色）书（苏）；③生糖氨基酸：除了上述两类的所有氨基酸。","","N"],["2008-N159",17,"第3节 细胞受体介导的细胞内信号转导","酶耦联受体的作用",2008,159,"X","","与细胞生长、增殖和分化有关的信号转导途径主要有",[["A","cAMP-蛋白激酶途径"],["B","cGMP-蛋白激酶途径"],["C","受体型TPK-Ras-MAPK途径"],["D","JAK-STAT途径"]],"CD","酶偶联受体主要是生长因子和细胞因子的受体，此类受体介导的信号转导主要是调节蛋白质的功能和表达水平，与细胞生长、增殖和分化有关。受体型TPK-Ras-MAPK途径（MAPK通路）（C对）和JAK-STAT途径（JAK-STAT通路）（D对）均为常见的酶偶联受体介导的信号转导通路，前者的配体一般为EGF（表皮生长因子）等生长因子，后者的配体一般为IFN-γ（γ干扰素）等细胞因子，以上两条途径均与细胞生长、增殖和分化有关。cGMP-蛋白激酶途径（B错）亦属于酶偶联受体介导的信号转导通路（九版生理学 P30），但其配体主要为心房钠尿肽、脑钠尿肽或一氧化氮，主要调节机体水盐平衡和血压稳定（九版生理学 P138）。cAMP-蛋白激酶途径（A错）为G蛋白偶联受体介导的信号转导途径，其配体一般为肾上腺素、胰高血糖素、促肾上腺皮质激素等神经递质或激素，主要调节物质代谢和基因表达。","","N"],["2008-N160",21,"第3节 胆汁与胆汁酸的代谢","胆汁酸的分类",2008,160,"X","","肝脏合成的初级胆汁酸有",[["A","胆酸"],["B","鹅脱氧胆酸"],["C","甘氨胆酸"],["D","牛磺胆酸"]],"ABCD","胆汁酸按其来源可分为初级胆汁酸和次级胆汁酸。其中初级胆汁酸是指在肝细胞内以胆固醇为原料直接合成的胆汁酸，包括胆酸（A对）、鹅脱氧胆酸（B对）及其与甘氨酸或牛磺酸的结合产物（CD对）。次级胆汁酸是指初级胆汁酸在肠细菌作用下，第7位α羟基脱氧生成的胆汁酸，包括脱氧胆酸和石胆酸及其与甘氨酸或牛磺酸的结合产物。","","N"],["2008-N161",19,"第2节 癌基因","生长因子的分类及作用机制",2008,161,"X","","下列基因中，属于原癌基因的有",[["A","c-jun"],["B","c-fos"],["C","c-erb B"],["D","p16"]],"ABC","原癌基因又称细胞癌基因（cellular oncogene，c-onc）。原癌基因是基因组内正常存在的基因，其编码产物通常作为正调控信号促进细胞的增殖和生长，包括生长因子、生长因子受体、信号转导蛋白、细胞周期蛋白、转录因子等。c-jun（A对）和c-fos（B对）为转录因子，c-erb B（C对）为生长因子受体，三者均为原癌基因。p16（十版生物化学P441）（D错）为抑癌基因。","","N"],["2008-N162",15,"第1节 印迹法和探针技术","RNA印迹法的作用",2008,162,"X","","常用于研究基因表达的分子生物学技术有",[["A","Northern blotting"],["B","Southern blotting"],["C","Western blotting"],["D","RT-PCR"]],"ACD","基因表达产物包括RNA和蛋白质/多肽，因此检测基因表达水平就是检测RNA和蛋白质水平（九版生物化学P462）。Northern blotting（十版生物化学P348）（A对）即RNA印迹，用于检测RNA的表达水平。Western blotting（十版生物化学P338）（C对）即蛋白质印迹，用于检测蛋白质的表达水平。RT-PCR（十版生物化学P342）（D对）即逆转录PCR，可用于获取目的基因或检测RNA表达水平。Southern blotting（十版生物化学P348）（B错）即DNA印迹，用于检测DNA的表达水平。","","N"],["2009-N25",0,"第1节 蛋白质的分子组成","氨基酸的基本结构单位",2009,25,"A","","在天然蛋白质的组成中，不含有的氨基酸是",[["A","精氨酸"],["B","瓜氨酸"],["C","半胱氨酸"],["D","脯氨酸"]],"B","存在于自然界的氨基酸有300余种，但存在于人体天然蛋白质中的只有20种。常见的不出现于蛋白质中的氨基酸有鸟氨酸、瓜氨酸（B对）、同型半胱氨酸和精氨酸代琥珀酸。瓜氨酸和鸟氨酸是尿素合成的中间代谢产物（十版教材P182图9-8 尿素生成的鸟氨酸循环）。同型半胱氨酸是甲硫氨酸循环的中间代谢产物（十版教材P189甲硫氨酸循环）。","","N"],["2009-N26",0,"第4节 蛋白质的理化性质","变性",2009,26,"A","","蛋白质变性后的主要表现是",[["A","相对分子质量变小"],["B","粘度降低"],["C","溶解度降低"],["D","不易被蛋白酶水解"]],"C","蛋白质变性是指某些物理和化学因素作用下，其特定的空间构象被破坏，即有序的空间结构变为无序的空间结构，从而导致其理化性质的改变和生物学活性的丧失。蛋白质变性后：溶解度降低（C对），黏度增加（B错），结晶能力消失，生物学活性丧失，易被蛋白酶水解（D错）。蛋白质变性仅涉及空间结构的改变，其一级结构即氨基酸的组成没有变化，因而相对分子质量不变（A错）。","","N"],["2009-N27",2,"第4节 核酸的理化性质","DNA变性",2009,27,"A","","下列DNA分子中，可以使Tm值达到最高的是",[["A","腺嘌呤和胸腺嘧啶含量为20%"],["B","腺嘌呤和胸腺嘧啶含量为60%"],["C","鸟嘌呤和胞嘧啶含量为30%"],["D","鸟嘌呤和胞嘧啶含量为50%"]],"A","在DNA解链过程中，紫外吸光度的变化（A₂₆₀）达到最大变化值的一半时所对应的温度为DNA的解链温度（Tm），Tm值与DNA分子的GC含量有关，G+C含量越高，Tm值越高，反之亦然，这与C≡G碱基对之间有3个氢键，A=T碱基对之间仅2个氢键，破坏C≡G需要的温度更高有关。在完整的DNA双链中AT含量+CG含量=100%，所以GC含量，A为80%（A对），B为40%，C为30%，D为50%。","","N"],["2009-N28",1,"第1节 酶的分子结构与功能","酶的分子组成",2009,28,"A","","下列关于辅酶与辅基叙述错误的是",[["A","属于结合酶类的酶分子组成中才含有辅基或辅酶"],["B","维生素B族多参与辅酶或辅基的组成"],["C","辅酶或辅基直接参与酶促反应"],["D","一种辅酶或辅基只能与一种酶蛋白结合成一种全酶"]],"D","酶按其组成成分可以分为单纯酶和结合酶（缀合酶），仅含有蛋白质的酶称为单纯酶，属于结合酶类的酶分子组成中才含有辅基或辅酶（A对）。B族维生素如核黄素（维生素B₂）和烟酰胺（维生素PP）分别是氧化还原反应中重要的辅酶（B对）。在酶促反应中辅酶作为底物接受质子或基团后离开酶蛋白，参加另一酶促反应并将所携带的质子或基团转移出去，或者相反，所以它们直接参与酶促反应（C对）。每种酶都有自己特定的酶蛋白，故酶的种类很多，但辅基或辅酶的种类却不多，这是因为一种辅酶或辅基可与几种不同的酶蛋白结合成不同的酶，如生物素是丙酮酸羧化酶和乙酰辅酶A羧化酶的辅酶（D错，为本题正确答案）。","","N"],["2009-N29",4,"第6节 糖异生","糖异生的过程",2009,29,"A","","草酰乙酸不能直接转变生成的物质是",[["A","乙酰乙酸"],["B","柠檬酸"],["C","天冬氨酸"],["D","苹果酸"]],"A","草酰乙酸不能直接变成乙酰乙酸（酮体），后者是由脂肪酸β-氧化产生的乙酰CoA合成而来（A错，为本题正确答案）。草酰乙酸与乙酰CoA在柠檬酸合酶的催化下生成柠檬酸（B对），这是三羧酸循环的第一步反应。草酰乙酸经氨基化可生成天冬氨酸（C对），此反应可发生在嘌呤核苷酸循环中其他氨基酸将氨基转移给天冬氨酸的过程，还可发生在糖异生过程中草酰乙酸以天冬氨酸的形式转运出线粒体的过程。草酰乙酸在苹果酸脱氢酶作用下生成苹果酸（D对），该反应见于草酰乙酸经苹果酸由线粒体转运至胞质的过程，还见于三羧酸循环最后一步的逆反应。","","N"],["2009-N30",5,"第3节 甘油三酯代谢","软脂酸合成的过程",2009,30,"A","","乙酰CoA羧化酶的变构激活剂是",[["A","AMP"],["B","柠檬酸"],["C","ADP"],["D","2，6-二磷酸果糖"]],"B","乙酰CoA羧化酶是脂肪酸合成的关键酶，接受柠檬酸（B对）和异柠檬酸的变构激活，从而促进脂肪酸的合成。AMP（A错）和ADP（C错）是糖有氧氧化过程大部分关键酶（磷酸果糖激酶-1、丙酮酸激酶、丙酮酸脱氢酶复合体、异柠檬酸脱氢酶、α-酮戊二酸脱氢酶复合体等）的变构激活剂（十版生物化学P110）。2，6-二磷酸果糖（D错）是磷酸果糖激酶-1的变构激活剂（十版生物化学P110）。","","N"],["2009-N31",6,"第2节 氨基酸的一般代谢","α-酮酸转变成糖和脂质",2009,31,"A","","下列氨基酸中，属于生糖兼生酮的是",[["A","亮氨酸"],["B","组氨酸"],["C","赖氨酸"],["D","苏氨酸"]],"D","根据代谢产物的不同可以将氨基酸分为三类：①生酮氨基酸：亮氨酸（A错）、赖氨酸（C错），记忆口诀为同（酮）样（亮）来（赖）；②生酮兼生糖氨基酸：异亮氨酸、苯丙氨酸、酪氨酸、色氨酸、苏氨酸（D对），记忆口诀为一（异）本（苯）落（酪）色（色）书（苏）；③生糖氨基酸：除了上述两类的所有氨基酸。","","N"],["2009-N32",7,"第1节 生物氧化与能量代谢","物质能量代谢的概述",2009,32,"A","","下列物质中，不属于高能化合物的是",[["A","二磷酸腺苷"],["B","乙酰CoA"],["C","3-磷酸甘油酸"],["D","磷酸肌酸"]],"C","在生物代谢中，高能化合物主要包括高能磷酸键化合物和高能硫酯键化合物两大类。其中高能磷酸键化合物包括NTP、NDP（A对）、 1，3- 二磷酸甘油酸、磷酸烯醇式丙酮酸、磷酸肌酸（D对）、氨基甲酰磷酸、焦磷酸、葡糖-1-磷酸等。高能硫酯键化合物包括乙酰CoA（B对）、琥珀酰 CoA等。3- 磷酸甘油酸（十版生物化学P108）（C错，为本题正确答案）为糖酵解的中间产物，其磷酸键是普通酯键，而不是高能磷酸键，不属于高能化合物。","","N"],["2009-N33",8,"第2节 嘌呤核苷酸的合成与分解代谢","脱氧核苷酸的生成",2009,33,"A","","下列核苷酸经核糖核苷酸还原酶催化能转化生成脱氧核苷酸的是",[["A","NMP"],["B","NDP"],["C","NTP"],["D","dNTP"]],"B","脱氧核糖核苷酸主要在核糖核苷酸还原酶催化下，通过直接还原相应的核糖核苷酸而生成，这种还原作用主要在二磷酸核苷（NDP）（B对）水平进行，即NDP→dNDP（N代表A、G、U、C等碱基）。唯一例外的是脱氧胸腺嘧啶核苷酸（dTMP）的合成是在一磷酸水平进行的（由dUMP经甲基化而生成）。","","N"],["2009-N34",11,"第5节 逆转录","逆转录病毒的相关概念及步骤",2009,34,"A","","下列关于逆转录酶的叙述，正确的是",[["A","以mRNA为模板催化合成RNA的酶"],["B","其催化合成的方向是3'→5'"],["C","催化合成时需要先合成冈崎片段"],["D","此酶具有RNase活性"]],"D","逆转录酶可以 mRNA 为模板催化合成 cDNA（A 错），构建 cDNA 文库（十版生物化学P271）具体过程为：逆转录酶以 mRNA 为模板，在适当引物存在下，催化 dNTP 沿 5 ＇→ 3 ＇方向聚 合生成 DNA 互补链（B 错），产物是 RNA/DNA 杂化双链。然后，杂化双链中的 RNA 被逆转 录酶的 RNase 活性组分水解（D 对），RNA 分解后剩下的单链 DNA 再用作模板，由引物引导 和反转录酶催化合成第二条 DNA 互补链。冈崎片段是 DNA 复制过程中的中间产物，与逆转录无关（C 错）。","","N"],["2009-N35",12,"第3节 真核生物mRNA的转录、加工和降解","不同RNA聚合酶催化不同RNA的合成",2009,35,"A","","真核生物RNA聚合酶Ⅱ催化转录后的产物是",[["A","tRNA"],["B","hnRNA"],["C","5.8S rRNA"],["D","5S rRNA"]],"B","真核生物主要有三种不同的 RNA 聚合酶，分别为 RNA 聚合酶Ⅰ、RNA 聚合酶Ⅱ和RNA 聚合酶Ⅲ（十版教材P279提及了植物中还存在RNA 聚合酶Ⅳ）。RNA聚合酶Ⅰ催化生成的产物为rRNA的前体45S rRNA，45S rRNA再加工成28S、5.8S（C错）及18S rRNA；RNA聚合酶Ⅱ催化生成的产物为mRNA前体hnRNA（B对）、lncRNA、piRNA和miRNA；RNA聚合酶Ⅲ催化生成的产物为tRNA（A错），5S rRNA（D错）和snRNA（记忆为3个“三”：three→t，三五牌香烟→5，san→sn）。","","N"],["2009-N36",13,"第5节 蛋白质合成的干扰和抑制","影响成肽的抗生素",2009,36,"A","","对真核和原核生物翻译过程均有干扰作用，故难用作抗菌药物的是",[["A","四环素"],["B","链霉素"],["C","卡那霉素"],["D","嘌呤霉素"]],"D","嘌呤霉素的结构与酪氨酰-tRNA相似，在翻译中可取代酪氨酰-tRNA而进入核糖体A位，中断肽链合成。由于酪氨酰-tRNA是原核生物和真核生物蛋白质合成的共同原料，因此嘌呤霉素对真核和原核生物翻译过程均有干扰作用，一般用作抗肿瘤药物，而不用作抗菌药物（D对）。四环素（A错）、链霉素（B错）、卡那霉素（与链霉素同属氨基糖苷类抗生素）（C错）均只对原核生物翻译过程有干扰作用，为常见的抗菌药物。","","N"],["2009-N37",13,"第2节 蛋白质合成体系","遗传密码的特点",2009,37,"A","","一个tRNA的反密码为5'UGC3'，它可识别的密码是",[["A","5'GCA3'"],["B","5'ACG3'"],["C","5'GCU3'"],["D","5'GGC3'"]],"A","tRNA上的反密码与mRNA上的遗传密码mRNA上的遗传密码是互补配对且方向相反的，根据碱基配对规律（A-U、C-G）可知反密码为5’UGC3’时，其识别的密码为5’GCA3’（A对）。","","N"],["2009-N38",14,"第1节 基因表达调控的基本概念与特点","基因表达调控呈现多层次和复杂性",2009,38,"A","","基因表达调控的基本控制点是",[["A","mRNA从细胞核转移到细胞质"],["B","转录的起始"],["C","转录后加工"],["D","蛋白质翻译及翻译后加工"]],"B","基因表达调控是在多级水平上进行的复杂事件，它可以发生在遗传信息传递过程的任何环节，但发生在转录水平，尤其是转录起始（B对）水平的调节，对基因表达起着至关重要的作用，是基因表达的基本控制点。","","N"],["2009-N39",16,"第2节 重组DNA技术","常用工具酶",2009,39,"A","","下列选项中不属于重组DNA的工具酶的是",[["A","拓扑异构酶"],["B","DNA连接酶"],["C","逆转录酶"],["D","限制性核酸内切酶"]],"A","重组DNA技术，又称分子克隆或DNA克隆或基因工程技术，其主要过程包括：将外源性目的DNA片段与载体连接，形成重组DNA分子，进而在受体细胞中复制、扩增，从而获得单一DNA分子的大量拷贝（十版生物化学P369）。重组DNA技术常用到的工具酶包括RE（限制性核酸内切酶）（D对）、DNA连接酶（B对）、DNA聚合酶Ⅰ、Klenow片段、逆转录酶（C对）、多聚核苷酸激酶、末端转移酶、碱性磷酸酶等。拓扑异构酶（十版生物化学P262）（A错，为本题正确答案）为内源性DNA复制过程中用来解开DNA超螺旋的酶。","","N"],["2009-N40",21,"第4节 胆色素的代谢与黄疸","血液中胆红素的运输形式",2009,40,"A","","血浆中能够转运胆红素和磺胺等多种物质的蛋白质是",[["A","清蛋白"],["B","运铁蛋白"],["C","铜蓝蛋白"],["D","纤维蛋白"]],"A","血浆中的清蛋白（A对）能与脂肪酸、Ca²⁺、胆红素、磺胺等多种物质结合（十版生物化学P484），发挥物质运输的作用。运铁蛋白（B错）是Fe³⁺的转运蛋白（十版生物化学P88）。铜蓝蛋白（C错）是铜的转运蛋白（十版生物化学P89）。纤维蛋白（D错）由纤维蛋白原转变而来，参与凝血过程，无运输作用。","","N"],["2009-N127",4,"第2节 糖的无氧氧化","丙酮酸激酶",2009,127,"B","","糖酵解的关键酶",[["A","磷酸甘油酸激酶"],["B","丙酮酸激酶"],["C","丙酮酸羧化酶"],["D","异柠檬酸脱氢酶"]],"B","糖酵解的关键酶包括己糖激酶（葡糖激酶），磷酸果糖激酶-1和丙酮酸激酶（B对）。磷酸甘油酸激酶为糖酵解途径的非关键酶（A错）。丙酮酸羧化酶是糖异生的关键酶（十版生物化学P128）（C错）。异柠檬酸脱氢酶为三羧酸循环的关键酶（十版生物化学P115）（D错）。","","N"],["2009-N128",4,"第3节 糖的有氧氧化","三羧酸循环的关键酶",2009,128,"B","","三羧酸循环的关键酶",[["A","磷酸甘油酸激酶"],["B","丙酮酸激酶"],["C","丙酮酸羧化酶"],["D","异柠檬酸脱氢酶"]],"D","三羧酸循环中的关键酶包括柠檬酸合酶、异柠檬酸脱氢酶（D对）和α-酮戊二酸脱氢酶复合体。磷酸甘油酸激酶（十版生物化学P108）是糖酵解中的非关键酶（A错）。丙酮酸激酶（十版生物化学P108）是糖酵解中的关键酶（B错）。丙酮酸羧化酶（P111）是糖异生的关键酶（C错）。","","N"],["2009-N129",7,"第2节 线粒体氧化体系与呼吸链","呼吸链传递电子_氢",2009,129,"B","","下述呼吸链氧化还原对中，氧化还原电位最高的是",[["A","NADH⁺/NADH+H⁺"],["B","FAD/FADH₂"],["C","Cytb Fe³⁺/Fe²⁺"],["D","Cyta Fe³⁺/Fe²⁺"]],"D","氧化呼吸链的电子传递顺序是NADH⁺/NADH+H⁺（或FAD/FADH₂）→Cytb Fe³⁺/Fe²⁺→Cyta Fe³⁺/Fe²⁺，而氧化呼吸链的电子是从电位低的组分向电位高的组分传递（电位高的组分对电子的亲和力强，易接受电子），因此氧化还原电位最高的是Cyta Fe³⁺/Fe²⁺（D对）。","","N"],["2009-N130",7,"第2节 线粒体氧化体系与呼吸链","复合体Ⅱ",2009,130,"B","","下述呼吸链氧化还原对中，参与构成呼吸链复合体Ⅱ的是",[["A","NADH⁺/NADH+H⁺"],["B","FAD/FADH₂"],["C","Cytb Fe³⁺/Fe²⁺"],["D","Cyta Fe³⁺/Fe²⁺"]],"B","复合体Ⅱ在氧化呼吸链中的功能是将电子从琥珀酸传递给泛醌，此过程与构成呼吸链复合体Ⅱ的氧化还原对FAD/FADH₂（B对）密切相关：琥珀酸脱氢将H和电子由FAD传递至FADH₂，然后再传递给泛醌，完成从琥珀酸至泛醌的电子传递过程。NADH⁺/NADH+H⁺（A错）不参与构成氧化呼吸链中任何复合体类型，但参与复合体Ⅰ（又称NADH-泛醌还原酶）的递氢递电子过程。Cytb Fe³⁺/Fe²⁺（C错）参与构成复合体Ⅲ。Cyta Fe³⁺/Fe²⁺（D错）参与构成复合体Ⅳ。","","N"],["2009-N131",11,"第2节 DNA复制的酶学和拓扑学","多种酶参与DNA解链和稳定单链状态",2009,131,"B","","具有辨认复制起始点功能的蛋白是",[["A","DnaA蛋白"],["B","DnaB蛋白"],["C","DnaC蛋白"],["D","DnaG蛋白"]],"A","由表14-4可知，具有辨认复制起始点功能的是DnaA蛋白（记忆技巧：A为起始字母）（A对）。DnaB蛋白（B错）又称解旋酶，具有解开DNA双链的功能（记忆技巧：掰<Bai>开双链，另B字母本身为螺旋状）。DnaC蛋白（C错）具有运送和协同DnaB的功能（记忆技巧：Carry<运送>/Cooperate<协同>）。DnaG蛋白（D错）又称引物酶，具有合成RNA引物的功能（记忆技巧：Guide<引导>）。","","N"],["2009-N132",11,"第2节 DNA复制的酶学和拓扑学","多种酶参与DNA解链和稳定单链状态",2009,132,"B","","具有解螺旋酶活性的蛋白是",[["A","DnaA蛋白"],["B","DnaB蛋白"],["C","DnaC蛋白"],["D","DnaG蛋白"]],"B","由表14-4可知，具有解螺旋酶活性的蛋白是DnaB蛋白（又称解旋酶）（B对）","","N"],["2009-N157",6,"第3节 氨的代谢","尿素生成障碍",2009,157,"X","","体内氨基酸脱氨基作用产生的氨可参与合成的物质有",[["A","尿酸"],["B","肌酸"],["C","谷氨酸"],["D","谷氨酰胺"]],"CD","体内氨基酸脱氨基作用产生的氨与α-酮戊二酸结合可合成谷氨酸（C对），与谷氨酸进一步结合可合成谷氨酰胺（D对）。尿酸（十版生物化学P224）（A错）是嘌呤分解的终产物。肌酸（B错）由精氨酸、甘氨酸及甲硫氨酸合成，所含的氮元素并非来自氨基酸脱氨基作用产生的氨。","","N"],["2009-N158",11,"第2节 DNA复制的酶学和拓扑学","原核生物的DNA聚合酶",2009,158,"X","","下列有关DNA聚合酶Ⅲ的叙述正确的有",[["A","是复制延长中起主要催化作用的酶"],["B","5'-3'聚合酶活性"],["C","3'-5'外切酶活性"],["D","5'-3'外切酶活性"]],"ABC","DNA聚合酶 Ⅲ是在DNA的复制延长中发挥着关键作用的酶（A对），它可以在5＇→3＇方向上催化子链DNA的合成，即具有5＇→3＇聚合酶活性（B对），还可以及时识别合成过程中错配的DNA并进行剪切，即具有3＇→5＇外切酶活性（C对）。原核生物经典的三种DNA聚合酶中只有DNA聚合酶Ⅰ具有5＇→3＇外切酶活性（十版生物化学P260）（D错），DNA聚合酶Ⅰ的功能是复制过程中校读、修复、填补缺口。","","N"],["2009-N159",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物的转录由转录起始前复合物引发",2009,159,"X","","参与真核生物hnRNA转录前起始复合物形成的因子有",[["A","TFⅡD"],["B","TFⅡA"],["C","TBP"],["D","TFⅢ"]],"ABC","与原核生物一样，真核生物转录起始也需要RNA pol（转录hnRNA需要的是RNA pol Ⅱ）对起始点上游DNA序列进行辨认和结合，生成转录前起始复合物（PIC）。转录起始时，真核生物的RNA pol不直接识别和结合模板的起始区，而是依靠转录因子（RNA pol Ⅱ对应是TFⅡ）（D错）识别并结合起始序列，故其起始复合物的装配过程比原核生物复杂的多：①由TFⅡD（A对）中的TBP（C对）识别TATA盒，并在TAFs的协助下结合到启动子区，然后TFⅡB与TBP结合，同时TFⅡB也能与DNA结合，TFⅡA（B对）可以稳定与DNA结合的TFⅡB-TBP复合体；②TFⅡB-TBP复合体与RNA pol Ⅱ-TFⅡF复合体结合，此举可降低RNA pol Ⅱ与DNA的非特异部位的结合，协助RNA pol Ⅱ靶向结合启动子；③TFⅡE和TFⅡH加入，形成起始复合物，装配完成。","","N"],["2009-N160",13,"第4节 蛋白质合成后的加工和靶向输送","蛋白质合成后的加工和靶向输送的概述",2009,160,"X","","下列选项中，属于蛋白质生物合成后加工的有",[["A","亚基聚合"],["B","辅基连接"],["C","个别氨基酸的羟化"],["D","去除N-甲酰基或N-甲硫氨酸"]],"ABCD","新生蛋白质不具备生物学活性，必须经过复杂的合成后加工过程才能转变为具有天然构象的功能蛋白质，这一加工过程称为翻译后修饰。翻译后修饰包括多肽链折叠为天然的三维构象及肽链一级结构修饰、空间结构的修饰等（七版生物化学P307）。个别氨基酸的羟化（C对）包括赖氨酸羟化为羟赖氨酸、脯氨酸羟化为羟脯氨酸等（七版生物化学P311），属于一级结构修饰。新生肽链的第一个氨基酸总是N-甲酰甲硫氨酸（原核生物）或甲硫氨酸（真核生物），但多数天然蛋白质不以N-甲酰甲硫氨酸或甲硫氨酸为N-端第一位氨基酸，需要在细胞内脱甲酰基酶或氨基肽酶的作用下去除N-甲酰基或N-甲硫氨酸（D对）才能成为有活性的蛋白质（七版生物化学P311），属于一级结构修饰。亚基聚合（A对）是指两条或两条以上肽链（亚基）通过非共价键聚合，形成具有四级结构的蛋白质的过程（七版生物化学P312），属于空间结构修饰。辅基连接（B对）是指新生肽链与辅基结合后形成结合蛋白质的过程（七版生物化学P312），属于空间结构修饰。","","N"],["2009-N161",16,"第2节 重组DNA技术","目的DNA的分离获取",2009,161,"X","","重组DNA技术中，可用于获取目的基因的方法有",[["A","化学合成法"],["B","PCR"],["C","Western blotting"],["D","基因敲除"]],"AB","重组DNA技术中，可用于获取目的基因的方法有化学合成法、从基因组DNA文库和cDNA文库中获取目的DNA、PCR法等。化学合成法（A对）是通过人工直接合成DNA片段的方法。PCR（B对）是利用特异性引物引导及耐热性DNA聚合酶催化，经变性、退火、延伸等步骤循环扩增DNA片段的方法。Western blotting（十版生物化学P338）（C错）即蛋白质印迹，是一种定性及半定量检测蛋白质的方法（C 错）。基因敲除（九版生物化学P468）（D错）是一种用基因剔除策略鉴定基因功能的方法。","","N"],["2009-N162",17,"第2节 细胞内信号转导分子","第二信使的概述",2009,162,"X","","细胞内信息传递中，能作为第二信使的有",[["A","cGMP"],["B","AMP"],["C","DAG"],["D","TPK"]],"AC","第二信使是指外源信息在细胞内的信号转导分子，环核苷酸（cAMP、cGMP）是第二信使（A对），但核苷酸（AMP、GMP）不是第二信使（B错）。DAG（甘油二酯）也属于第二信使（C对）。TPK（蛋白质酪氨酸激酶）（十版生物化学P397）属于蛋白激酶（并且多以受体或受体结合蛋白的形式存在），不属于第二信使（D错）。","","N"],["2010-N25",0,"第2节 蛋白质的分子结构","结构域",2010,25,"A","","下列选项中，属于蛋白质三级结构的是",[["A","α-螺旋"],["B","无规卷曲"],["C","结构域"],["D","锌指结构"]],"C","蛋白质分子结构十分复杂，可分成四个层次，即一级、二级、三级、四级结构。一级结构是指蛋白质中从N端到C端氨基酸的排列顺序（十版生物化学P13）；二级结构是指蛋白质中某一段肽链的局部空间结构（十版生物化学P14）；三级结构是指整条肽链上全部氨基酸残基的相对空间位置（十版生物化学P16），结构域（C对）是三级结构层次上的独立功能区，是一种特殊的三级结构；四级结构是指有两条或两条以上多肽链的蛋白质分子中各个亚基的空间排布及亚基接触部位的布局和相互作用（十版生物化学P19）。α-螺旋（A错）和无规卷曲（B错）均为二级结构，锌指结构（D错）为超二级结构（九、十版教材锌指结构位列三级结构章节下，但它并不属于三级结构）。","","N"],["2010-N26",2,"第3节 RNA和空间结构与功能","tRNA的结构及功能",2010,26,"A","","下列选项中，符合tRNA结构特点的是",[["A","5'末端的帽子"],["B","3'末端多聚A尾"],["C","反密码子"],["D","开放阅读框"]],"C","tRNA结构特点包括：二级结构形似三叶草，具有四个茎和三个环结构（P68 图3-22），其中三个环分别为DHU环、TψC环和反密码环（含反密码子）（C对），此外，3’端则具有相同的CCA-OH结构，为氨基酸的连接位点。5’-末端的帽子（A错），3’-末端多聚A尾（B错）和开放阅读框（D错）均为mRNA的结构特点。","","N"],["2010-N27",1,"第2节 酶的工作原理","多元催化",2010,27,"A","","酶活性中心的某些基团可以参与质子的转移，这种作用称为",[["A","亲核催化作用"],["B","共价催化作用"],["C","多元催化作用"],["D","—般酸-碱催化作用"]],"D","酶的催化机制呈多元化催化作用（C错）：①酸-碱催化作用（D对），是指起催化作用的酶（活性中心的某些基团）是质子受体或供体，可以参与质子的转移；②亲核催化作用和共价催化作用（AB错），亲核催化是酶活性中心亲核基团释出的电子攻击过渡态底物上具有部分正电性的原子或基团，形成瞬时共价键。瞬时共价键形成后，底物被激活，并很容易进一步水解形成产物和游离的酶，此时又表现出共价催化；③亲电子催化作用，是指酶活性中心内亲电子基团与富含电子的底物形成共价键。","","N"],["2010-N28",4,"第3节 糖的有氧氧化","各组织的糖氧化产能方式",2010,28,"A","","糖有氧氧化抑制糖酵解的作用称为",[["A","别构效应"],["B","巴斯德效应"],["C","表面效应"],["D","邻近效应"]],"B","糖酵解产生的丙酮酸，有无氧氧化和有氧氧化两种代谢途径，缺氧时，丙酮酸接受NADH+H⁺的氢而还原生成乳酸，氧供充足时，NADH+H⁺进入线粒体氧化，丙酮酸彻底分解成CO₂和H₂O，此时因丙酮酸和NADH+H⁺被利用，体内的无氧氧化受到抑制，这种有氧氧化抑制无氧氧化（糖酵解）的现象称为巴斯德效应（B对）。需要解释的是，在七版及更早版本教材中，糖酵解在概念上等同于无氧氧化，即糖酵解是指葡萄糖转化成丙酮酸进而还原生成乳酸的过程，而由葡萄糖转化生成丙酮酸的过程被称为糖酵解途径，糖酵解包括糖酵解途径和乳酸生成两个阶段。从八版教材开始，糖酵解的概念有所变化，仅指由葡萄糖转化生成丙酮酸的过程（原糖酵解途径），重新定义后的“糖酵解”成为葡萄糖无氧氧化和有氧氧化的共同起始途径。故按新版教材的概念，题干应改为“糖有氧氧化抑制无氧氧化的作用称为”。别构效应又称为变构效应，是体内代谢产物与蛋白质结合改变蛋白质的构象，导致蛋白质生物活性改变的现象（A错）。表面效应（十版生物化学P40）见于酶促反应中，表面效应能够使底物分子去溶剂化，排除周围大量水分子对酶和底物分子中功能基团的干扰性吸引和排斥，防止水化膜的形成，利于底物与酶分子的密切接触和结合（C错）。邻近效应（十版生物化学P40）亦见于酶促反应中，酶在反应中将诸多底物结合到活性中心，使他们相互接近并形成有利于反应的正确定向关系，从而提高反应速率，称邻近效应（D错）。","","N"],["2010-N29",5,"第5节 胆固醇代谢","胆固醇的合成过程",2010,29,"A","","体内胆固醇生物合成的限速酶是",[["A","HMG-CoA合酶"],["B","HMG-CoA还原酶"],["C","HMG-CoA裂解酶"],["D","ALA合酶"]],"B","胆固醇生物合成时的限速酶（关键酶）是HMG-CoA还原酶（B对）。HMG-CoA合酶（A错）为胆固醇合成（十版生物化学P159）和酮体合成（十版生物化学P149）的非限速酶。HMG-CoA裂解酶（C错）为酮体合成（十版生物化学P149）的非限速酶。ALA合酶（十版生物化学P334）（D错）为血红素合成的限速酶。","","N"],["2010-N30",7,"第4节 氧化磷酸化的影响因素","毒性气体阻断电子传递过程",2010,30,"A","","CO抑制呼吸链的部位是",[["A","复合体Ⅰ"],["B","复合体Ⅱ"],["C","复合体Ⅲ"],["D","复合体Ⅳ"]],"D","呼吸链抑制剂有四种：①抑制复合体Ⅰ：粉蝶霉素A、鱼藤酮、异戊巴比妥（可记忆为一群动物：鱼、蝶、蚁，或可记忆为一条粉红色的鱼尾巴）（A错）；②抑制复合体Ⅱ：萎锈灵（可记忆为二位伟人）（B错）；③抑制复合体Ⅲ：抗霉素A、黏噻唑菌醇（可记忆为三年抗战）（C错）；④抑制复合体Ⅳ：CN⁻、N³⁻、CO（记忆为都是化学式）（D对），CN⁻、N³⁻紧密结合复合体Ⅳ中氧化型Cyt a₃，阻断电子由Cyt a到CuB-Cyt a₃间传递，而CO与还原型Cyt a₃结合，阻断电子传递给O₂。","","N"],["2010-N31",6,"第1节 营养必需氨基酸与氨基酸代谢概述","真核细胞内蛋白质的降解途径",2010,31,"A","","下列选项中，符合蛋白酶体降解蛋白质特点的是",[["A","不需泛素参与"],["B","主要降解外来的蛋白质"],["C","需要消耗ATP"],["D","是原核生物蛋白质降解的主要途径"]],"C","真核细胞内蛋白质的降解有两条重要途径：①在溶酶体通过ATP非依赖途径被降解。蛋白质通过此途径降解时选择性较差，主要降解细胞外来的蛋白质、膜蛋白和胞内长寿蛋白，不需要消耗ATP；②在蛋白酶体通过ATP依赖途径被降解。蛋白质通过此途径降解时需泛素的参与（A错），主要降解异常蛋白和短寿蛋白（B错），需要消耗ATP（C对）。原核生物胞浆中仅有核糖体而无蛋白酶体等其他细胞器，不能通过蛋白酶体途径降解（D错）。","","N"],["2010-N32",6,"第3节 氨的代谢","鸟氨酸循环",2010,32,"A","","在鸟氨酸循环中，直接生成尿素的中间产物是",[["A","精氨酸"],["B","瓜氨酸"],["C","鸟氨酸"],["D","精氨酸代琥珀酸"]],"A","由P183 图8-8可知，直接生成尿素的中间产物是精氨酸（A对）。鸟氨酸循环的大致步骤：①NH₃、CO₂和ATP缩合成氨基甲酰磷酸；②氨基甲酰磷酸与鸟氨酸（C错）反应生成瓜氨酸；③瓜氨酸（B错）与天冬氨酸反应生成精氨酸代琥珀酸；④精氨酸代琥珀酸（D错）裂解生成精氨酸与延胡索酸；⑤精氨酸（A对）水解释放尿素并生成鸟氨酸，鸟氨酸再次进入线粒体参与合成瓜氨酸，如此反复，进行鸟氨酸循环。","","N"],["2010-N33",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径的概述",2010,33,"A","","从头合成嘌呤的直接原料是",[["A","谷氨酸"],["B","甘氨酸"],["C","天冬酰胺"],["D","氨基甲酰磷酸"]],"B","嘌呤从头合成原料包括天冬氨酸（非天冬酰胺）（C错）、谷氨酰胺（非谷氨酸）（A错）、甘氨酸（B对）、CO₂及甲酰基（一碳单位）等。氨基甲酰磷酸（D错）是尿素合成（十版生物化学P183）和嘧啶合成（P204）的中间产物，与嘌呤合成无关。","","N"],["2010-N34",0,"第3节 蛋白质结构与功能的关系","蛋白质一级结构是高级结构与功能的基础",2010,34,"A","","造成镰刀型红细胞贫血的基因突变原因是",[["A","DNA重排"],["B","碱基缺失"],["C","碱基插入"],["D","碱基错配"]],"D","镰形红细胞贫血因血红蛋白β基因的第6位碱基T被错配为A（碱基错配/点突变）（D对），密码子由正常的GAG突变为GUG，导致其编码的谷氨酸被缬氨酸所代替而致病。","","N"],["2010-N35",12,"第3节 真核生物mRNA的转录、加工和降解","不同RNA聚合酶催化不同RNA的合成",2010,35,"A","","真核生物RNA聚合酶Ⅱ的作用是",[["A","合成45S rRNA"],["B","合成hnRNA"],["C","合成5S rRNA"],["D","合成tRNA"]],"B","真核生物主要有三种不同的 RNA 聚合酶，分别为 RNA 聚合酶Ⅰ、RNA 聚合酶Ⅱ和RNA 聚合酶Ⅲ（十版教材P279提及了植物中还存在RNA 聚合酶Ⅳ）。RNA聚合酶Ⅰ催化生成的产物为rRNA的前体45S rRNA（A错），45S rRNA再加工成28S、5.8S及18S rRNA；RNA聚合酶Ⅱ催化生成的产物为mRNA前体hnRNA（B对）、lncRNA、piRNA和miRNA；RNA聚合酶Ⅲ催化生成的产物为tRNA（D错），5S rRNA（C错）和snRNA（记忆为3个“三”：three→t，三五牌香烟→5，san→sn）。","","N"],["2010-N36",13,"第2节 蛋白质合成体系","核糖体是蛋白质合成的场所",2010,36,"A","","蛋白质生物合成过程中，能在核蛋白体E位上发生的反应是",[["A","氨基酰tRNA进位"],["B","转肽酶催化反应"],["C","卸载tRNA"],["D","与释放因子结合"]],"C","真核、原核生物的核糖体上都有A位、P位和E位这3个重要的功能部位（十版生物化学P299）。在肽链合成中，分别作为氨基酰-tRNA进位（A错）、肽酰-tRNA结合和tRNA卸载排出（C对）的位置。转肽酶（肽酰转移酶）催化的是成肽反应，成肽反应在A位进行（十版生物化学P304）（B错）。与释放因子（RF）结合的亦为A位（终止密码子出现在A位，释放因子通过识别终止密码子与A位结合）（D错）。","","N"],["2010-N37",14,"第1节 基因表达调控的基本概念与特点","基因表达的方式",2010,37,"A","","组成性基因表达的正确含义是",[["A","在大多数细胞中持续恒定表达"],["B","受多种机制调节的基因表达"],["C","可诱导基因表达"],["D","空间特异性基因表达"]],"A","基因的表达方式存在多样性。有些基因在生物体各个生长阶段、大多数细胞中持续恒定表达（A对），这种基因通常被称为管家基因，这类基因表达则被称为组成性基因表达。有些基因的表达则受到环境变化的诱导和阻遏，这些基因被称为可诱导基因（C错）和可阻遏基因可阻遏基因（十版生物化学P317）。组成性基因表达只受启动序列或启动子与RNA聚合酶相互作用的影响，基本不受其他调节机制的影响（B错）。基因表达具有时间特异性和空间特异性，空间特异性基因表达（D错）表现为同一基因在不同的组织器官表达水平不同可阻遏基因（十版生物化学P316）。","","N"],["2010-N38",16,"第2节 重组DNA技术","限制性核酸内切酶",2010,38,"A","","下列选项中，符合Ⅱ类限制性内切核酸酶特点的是",[["A","识别的序列是回文结构"],["B","没有特异酶解位点"],["C","同时有连接酶活性"],["D","可切割细菌体内自身DNA"]],"A","限制性内切核酸酶（限制性核酸内切酶）是指能识别双链DNA分子内部的特异位点并裂解磷酸二酯键的一类内切核酸酶，不具有连接酶活性（连接酶生成磷酸二酯键）（C错）。该酶主要存在于细菌内，可限制外源DNA，保护细菌体内自身DNA（十版生物化学P370）（D错），对维持细菌遗传性状的稳定性具有重要意义。根据酶的组成、所需因子及裂解DNA方式的不同，可将限制性内切核酸酶分为Ⅰ、Ⅱ、Ⅲ三种类型。Ⅰ类酶和Ⅲ类酶不在所识别的位点切割DNA（即特异性不强），故在重组DNA技术中应用价值不大。而Ⅱ类酶能在DNA回文结构序列内（A对）的特异酶解位点（B错）识别并切割DNA，在重组DNA技术中被广泛应用。","","N"],["2010-N39",17,"第2节 细胞内信号转导分子","G蛋白的作用",2010,39,"A","","下列关于Ras蛋白特点的叙述，正确的是",[["A","具有GTP酶活性"],["B","能使蛋白质酪氨酸磷酸化"],["C","具有7个跨膜螺旋结构"],["D","属于蛋白质丝／苏氨酸激酶"]],"A","Ras蛋白与G蛋白一样具有鸟核苷酸的结合位点和GTP酶活性（A对），但该蛋白只有一条多肽链，分子量小于G蛋白，因此也称为小G蛋白。能使蛋白质酪氨酸磷酸化（B错）的是蛋白酪氨酸激酶（PTK）（十版生物化学P390）。具有7个跨膜螺旋结构（C错）的是G蛋白偶联受体（GPCR）（十版生物化学P392）。活化的Ras蛋白可启动其下游的MAPK级联激活过程：Ras→MAPKKK（Raf蛋白）→MAPKK（MEK蛋白）→MAPK（ERK1蛋白），MAPKKK、MAPKK和MAPK均属于蛋白质丝／苏氨酸激酶，但Ras不属于（D错）。","","N"],["2010-N40",19,"第2节 癌基因","原癌基因",2010,40,"A","","下列关于原癌基因的叙述，正确的是",[["A","只存在于哺乳动物中"],["B","进化过程中高度变异"],["C","维持正常细胞生理功能"],["D","Rb基因是最早发现的原癌基因"]],"C","原癌基因（细胞癌基因）在进化过程中高度保守（B错），从单细胞酵母、无脊椎生物到脊椎动物乃至人类的正常细胞都存在着这些基因（A错）。原癌基因的表达产物对细胞正常生长、繁殖、发育和分化起着精确的调控作用（C对）。Rb是最早被发现的抑癌基因（D错）。","","N"],["2010-N127",4,"第2节 糖的无氧氧化","磷酸果糖激酶-1",2010,127,"B","","肌肉组织中，糖酵解途径的关键酶是",[["A","葡萄糖激酶"],["B","6-磷酸果糖激酶-1"],["C","丙酮酸羧化酶"],["D","柠檬酸合酶"]],"B","糖酵解的关键酶包括己糖激酶（葡糖激酶），磷酸果糖激酶-1（B对）和丙酮酸激酶。其中己糖激酶有四种同工酶，存在于肝组织的称为葡糖激酶（十版生物化学P109），而肌肉和其他组织中称为己糖激酶（A错）。丙酮酸羧化酶是糖异生的关键酶（十版生物化学P128）（C错）。柠檬酸合酶是三羧酸循环的关键酶（十版生物化学P114）（D错）。","","N"],["2010-N128",4,"第6节 糖异生","糖异生的关键酶及耗能",2010,128,"B","","糖异生过程的关键酶是",[["A","葡萄糖激酶"],["B","6-磷酸果糖激酶-1"],["C","丙酮酸羧化酶"],["D","柠檬酸合酶"]],"C","糖异生是非糖物质转变为葡萄糖的过程。糖异生的关键酶有丙酮酸羧化酶（C对）、磷酸烯醇丙酮酸羧激酶、果糖二磷酸酶-1和葡萄糖-6-磷酸酶。葡萄糖激酶（A错）、磷酸果糖激酶-1（B错）是糖酵解的关键酶。柠檬酸合酶是三羧酸循环的关键酶（D错）。","","N"],["2010-N129",5,"第3节 甘油三酯代谢","脂肪酸活化",2010,129,"B","","脂肪酸β-氧化途径中，脂肪酸的活化形式是",[["A","丙二酰CoA"],["B","脂肪酰CoA"],["C","β-羟丁酸"],["D","乙酰乙酰CoA"]],"B","脂肪酸被氧化前必须先活化，由内质网、线粒体外膜上的脂酰CoA合成酶催化生成脂酰CoA（B对），再进入线粒体被氧化。丙二酰CoA（十版生物化学P152）（A错）是脂酸合成的中间产物。β-羟丁酸（十版生物化学P148）（C错）为酮体的一种。乙酰乙酰CoA（D错）是酮体合成（十版生物化学P149）和胆固醇合成（十版生物化学P159）的中间产物。","","N"],["2010-N130",5,"第5节 胆固醇代谢","胆固醇的合成过程",2010,130,"B","","胆固醇合成的重要中间产物是",[["A","丙二酰CoA"],["B","脂肪酰CoA"],["C","β-羟丁酸"],["D","乙酰乙酰CoA"]],"D","胆固醇合成过程：2分子乙酰辅酶A→乙酰乙酰辅酶A→HMG-CoA→MVA→鲨烯→胆固醇。因此乙酰乙酰CoA（D对）是胆固醇合成的重要中间产物。丙二酰CoA即丙二酸单酰CoA，是脂肪酸合成时的中间产物（十版生物化学P152）（A错）。脂酰CoA（十版生物化学P147）（B错）是脂肪酸β-氧化的中间产物。β-羟丁酸（十版生物化学P148）（C错）是酮体的一种，是脂肪酸氧化分解的中间产物。","","N"],["2010-N131",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物转录需要转录因子的参与",2010,131,"B","","TFⅡD的结合位点是",[["A","TATA盒"],["B","GC盒"],["C","CAAT盒"],["D","CCAAT盒"]],"A","TFⅡD是协助真核生物RNA pol Ⅱ的基本转录因子，TFⅡD不是一种单一蛋白质，它实际上是由TATA结合蛋白（TBP）和8～10个TBP相关因子（TAFs）共同组成的复合物。在转录起始过程中，TFⅡD中的TBP可在TAFs的协助下，结合至真核生物启动子的核心功能组件TATA盒（A对）。与TATA盒一样，GC盒和CAAT盒（P280）也属于启动子的功能组件，与GC盒（B错）结合的是转录因子SP1，与CAAT盒（C错）结合的是转录因子C/EBP。","","N"],["2010-N132",14,"第3节 真核基因表达调控","启动子",2010,132,"B","","转录因子Sp1的结合位点是",[["A","TATA盒"],["B","GC盒"],["C","CAAT盒"],["D","CCAAT盒"]],"B","真核生物的启动子（十版生物化学P327）一般包括转录起始点及其上游约100～200bp序列，包含若干具有独立功能的DNA功能组件，这些功能组件中最具典型意义的是TATA盒（TATAAAA），与之结合的是基本转录因子TFⅡD（A错）。除TATA盒外，GC盒（GGGCGG）和CAAT盒（GCCAAT）也是很多基因启动子中的常见功能组件，与GC盒（B对）结合的是转录因子SP1（十版生物化学P281），与CAAT盒（C错）结合的是转录因子C/EBP（十版生物化学P281）。","","N"],["2010-N157",2,"第2节 DNA和空间结构与功能","DNA的双螺旋结构",2010,157,"X","","下列关于DNA二级结构模型的叙述，正确的是",[["A","是右手双螺旋结构"],["B","两股脱氧核苷酸链呈同向平行"],["C","两股链间存在碱基配对关系"],["D","螺旋每周含10对碱基"]],"AC","大多数DNA为B型DNA（P37），其二级结构是右手双螺旋结构（A对），A型也为右手螺旋，Z型为左手螺旋。DNA两条链的核糖和磷酸在外侧游离，碱基则位于内侧，遵循碱基互补配对原则相互配对（C对），构成DNA双链的反向平行结构（B错）。DNA双螺旋结构的直径是2.37nm，螺距是3.54nm，每个螺距有10.5对碱基（D错）。本题的数据有更新，按最新教材的数据D选项并不准确，但原答案为ACD。","","N"],["2010-N158",6,"第4节 个别氨基酸的代谢","酪氨酸的代谢",2010,158,"X","","体内酪氨酸分解代谢的产物有",[["A","四氢生物蝶呤"],["B","肾上腺素"],["C","尿黑酸"],["D","多巴胺"]],"BCD","酪氨酸的分解代谢途径主要有三条：①酪氨酸→多巴→多巴胺（D对）→去甲肾上腺素→肾上腺素（B对）；②酪氨酸→多巴→多巴醌→吲哚醌→黑色素；③酪氨酸→羟苯丙酮酸→尿黑酸（C对）→延胡索酸+乙酰乙酸。四氢生物蝶呤（十版生物化学P191）（A错）是参与酪氨酸分解代谢的苯丙氨酸羟化酶、酪氨酸羟化酶等单加氧酶的辅酶，而不是酪氨酸的分解代谢产物。","","N"],["2010-N159",13,"第4节 蛋白质合成后的加工和靶向输送","新生肽链折叠需要分子伴侣",2010,159,"X","","能促使蛋白质多肽链折叠成天然构象的蛋白质有",[["A","解螺旋酶"],["B","拓扑酶"],["C","热休克蛋白70"],["D","伴侣蛋白"]],"CD","能促使蛋白质多肽链折叠成天然构象的蛋白质被称为分子伴侣。常见的分子伴侣包括热激蛋白（又称热休克蛋白）（C对）和伴侣蛋白等（D对）。解螺旋酶（十版生物化学P261）（A错）为DNA复制起始时解开DNA双螺旋结构的酶。拓扑酶（十版生物化学P261）（B错）为DNA复制起始时解开DNA超螺旋结构的酶。","","N"],["2010-N160",16,"第2节 重组DNA技术","重组体的筛选与鉴定的方法",2010,160,"X","","DNA重组技术中，用来筛选重组体的方法有",[["A","标志补救"],["B","分子杂交"],["C","特异性抗体与产物结合"],["D","紫外分光光度计分析"]],"ABC","用来筛选重组体的方法主要有遗传标记筛选法、序列特异性筛选法和亲和筛选法：①遗传标记筛选法利用载体上的遗传标记进行筛选，包括利用抗生素抗性标志筛选、利用基因的插入失活/插入表达特性筛选、利用标志补救筛选（A对）、利用噬菌体的包装特性进行筛选等；②序列特异性筛选法利用目的DNA的序列特异性进行筛选，包括RE酶切法、PCR法、核酸杂交法（分子杂交法）（B对）、DNA测序法等；③亲和筛选法利用特异性抗体与产物结合（C对）进行筛选。紫外分光光度计可测定DNA分子的紫外吸收光值，对DNA分子进行定性和定量分析，但不能对重组体DNA分子与非重组体DNA分子作出区分，因此不能用来筛选重组体（D错）。","","N"],["2010-N161",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物转录需要转录因子的参与",2010,161,"X","","下列关于转录因子Ⅱ（TFⅡ）的叙述，正确的有",[["A","属于基本转录因子"],["B","参与真核生物mRNA的转录"],["C","在真核生物进化中高度保守"],["D","是原核生物转录调节的重要物质"]],"ABC","转录因子是转录调控的关键分子，依据功能特性，可将真核生物的转录因子分为基本（通用）转录因子和特异转录因子两大类（十版生物化学P280）。基本转录因子是RNA聚合酶介导基因转录时所必需的一类辅助蛋白质，帮助聚合酶与启动子结合并起始转录，对所有基因都是必需的，因此其在进化中高度保守（C对）。转录因子Ⅱ即为真核生物（B对D错）RNA聚合酶Ⅱ介导基因转录时所必需的基本转录因子（A对），能够帮助RNA聚合酶Ⅱ与启动子结合并起始转录。","","N"],["2010-N162",19,"第2节 癌基因","生长因子的分类及作用机制",2010,162,"X","","细胞癌基因的产物有",[["A","生长因子受体"],["B","转录因子"],["C","p53蛋白"],["D","酪氨酸蛋白激酶"]],"ABD","细胞癌基因是基因组内正常存在的基因，其编码产物通常作为正调控信号促进细胞的增殖和生长，包括生长因子、生长因子受体（A对）、信号转导分子、转录因子（B对）等，其中生长因子受体（如EGFR、HER-2）和部分信号转导分子（如Src、Abl）属于酪氨酸蛋白激酶（D对），可催化蛋白质分子中的酪氨酸残基磷酸化。p53蛋白（十版生物化学P443）（C错）为抑癌基因p53（TP53）的产物。","","N"],["2011-N25",0,"第5节 蛋白质的分离、纯化与结构分析","蛋白质沉淀",2011,25,"A","","盐析法沉淀蛋白质的原理是",[["A","改变蛋白质的一级结构"],["B","使蛋白质变性，破坏空间结构"],["C","使蛋白质的等电点发生变化"],["D","中和蛋白质表面电荷并破坏水化膜"]],"D","蛋白质是生物大分子化合物，具有胶体性质，维持其胶体稳定的主要因素是蛋白质表面电荷和水化膜。盐析法沉淀蛋白质的原理为将硫酸铵、硫酸钠或氯化钠等无机盐加入蛋白质溶液，使蛋白质表面电荷被中和以及水化膜被破坏（D对），从而破坏其稳定因素，导致蛋白质沉淀。","","N"],["2011-N26",2,"第2节 DNA和空间结构与功能","DNA双螺旋的相关实验",2011,26,"A","","一个DNA分子中，若G所占的摩尔比是32.8%，则A的摩尔比应是",[["A","0.672"],["B","0.656"],["C","0.328"],["D","0.172"]],"D","DNA双链之间的碱基以氢键相结合，形成A-T和C-G的碱基配对关系，若G所占的摩尔比是32.8%，则C的摩尔比也应为32.8%。由于C、G、A、T的总和应为100%，故A+T的摩尔比为100%-（G+C）=34.4%，又因A=T，故A的摩尔比应是17.2%（D对）。","","N"],["2011-N27",2,"第3节 RNA和空间结构与功能","tRNA的结构及功能",2011,27,"A","","下列关于tRNA的叙述，错误的是",[["A","分子中含稀有碱基较多"],["B","分子序列中含有遗传密码"],["C","tRNA分子具有三叶草型二级结构"],["D","所有tRNA的3'端均为-CCA-OH"]],"B","tRNA结构特点包括：二级结构形似三叶草（C对），具有四个茎和三个环结构（P68 图3-22），其中三个环分别为DHU环、TψC环和反密码环，DHU环和TψC环内含稀有碱基（A对），反密码环内含反密码子（而非身为遗传密码的密码子，密码子位于mRNA中）（B错，为本题正确答案）。此外，所有tRNA的3’端均为-CCA-OH结构（D对），此为氨基酸的连接位点。","","N"],["2011-N28",1,"第3节 酶促反应动力学","非竞争性抑制",2011,28,"A","","非竞争性抑制剂存在，酶促反应的动力学特点是",[["A","Km值不变Vmax降低"],["B","Km值不变Vmax增加"],["C","Km值增高Vmax不变"],["D","Km值降低Vmax不变"]],"A","非竞争性抑制剂与酶活性中心外的结合位点相结合，不影响底物与酶的结合（抑制剂和底物可同时与酶结合形成抑制剂-酶-底物复合物），即不影响底物和酶的亲和力，Km值不变（A对）。但抑制剂-酶-底物复合物不能进一步释放出产物，因此反应速度会下降，Vmax变小（A对）。","","N"],["2011-N29",4,"第6节 糖异生","糖异生的过程",2011,29,"A","","下列化合物中，不能由草酰乙酸转变生成的是",[["A","柠檬酸"],["B","苹果酸"],["C","天冬氨酸"],["D","乙酰乙酸"]],"D","草酰乙酸不能直接变成乙酰乙酸（酮体），后者是由脂肪酸β-氧化产生的乙酰CoA合成而来（D错，为本题正确答案）。草酰乙酸与乙酰CoA在柠檬酸合酶的催化下生成柠檬酸（A对），这是三羧酸循环的第一步反应。草酰乙酸经氨基化可生成天冬氨酸（C对），此反应可发生在嘌呤核苷酸循环中其他氨基酸将氨基转移给天冬氨酸的过程，还可发生在糖异生过程中草酰乙酸以天冬氨酸的形式转运出线粒体的过程。草酰乙酸在苹果酸脱氢酶作用下生成苹果酸（B对），该反应见于草酰乙酸经苹果酸由线粒体转运至胞质的过程，还见于三羧酸循环最后一步的逆反应。","","N"],["2011-N30",4,"第6节 糖异生","糖异生的概述",2011,30,"A","","下列选项中，可以转变为糖的化合物的是",[["A","硬脂酸"],["B","油酸"],["C","β-羟丁酸"],["D","α-磷酸甘油"]],"D","硬脂酸（A错）和油酸（B错）均为18C脂肪酸，经β-氧化代谢为乙酰CoA，乙酰CoA可进入柠檬酸循环被彻底氧化，也可进一步生成酮体，但不能进行糖异生（乙酰CoA不能转变成丙酮酸）。β-羟丁酸为酮体，它可转变为乙酰乙酸，后者可在肝外组织裂解为乙酰CoA，经柠檬酸循环氧化供能，但不能异生为糖（C错）。α-磷酸甘油在甘油磷酸脱氢酶作用下脱氢转变成磷酸二羟丙酮，磷酸二羟丙酮是糖无氧酵解的中间产物，可经其逆反应转变为葡萄糖（D对）。","","N"],["2011-N31",5,"第3节 甘油三酯代谢","甘油三酯合成的原料",2011,31,"A","","脂肪细胞合成甘油三酯所需的3-磷酸甘油主要来源于",[["A","糖酵解"],["B","糖异生"],["C","脂肪动员"],["D","氨基酸转化"]],"A","肝、肾等组织含有甘油激酶，可催化游离甘油磷酸化生成3-磷酸甘油，供甘油三酯合成。脂肪细胞甘油激酶含量很低，不能直接利用甘油合成甘油三酯，脂肪细胞只能以葡萄糖酵解途径（A对）生成3-磷酸甘油为起始物，先合成1，2-甘油二酯，最后通过酯化甘油二酯羟基生成甘油三酯。脂肪动员（十版生物化学P144）（C错）指储存在脂肪细胞内的甘油三酯被分解为游离脂肪酸和甘油，供其他组织细胞氧化利用的过程，因此脂肪动员为甘油三酯合成的逆反应，主要目的是为组织细胞氧化供能，而不是为其逆反应（甘油三酯合成）提供合成原料，并且脂肪细胞内甘油激酶很低，不能将游离甘油磷酸化成3-磷酸甘油供甘油三酯合成所用。生糖氨基酸（D错）可以转化成糖酵解或三羧酸循环的中间产物，如丙酮酸、草酰乙酸、α-酮戊二酸，它们都可进入糖异生途径（B错）转化成糖，最终可为甘油三酯合成提供3-磷酸甘油，但不构成3-磷酸甘油的主要来源。","","N"],["2011-N32",7,"第1节 生物氧化与能量代谢","物质能量代谢的概述",2011,32,"A","","下列化合物中，不含高能磷酸键的是",[["A","1，3-二磷酸甘油酸"],["B","1，6-二磷酸果糖"],["C","二磷酸胞苷"],["D","二磷酸鸟苷"]],"B","含有高能化学键的化合物可记忆为以下四类：① NTP、NDP，如CDP（C对）和GDP（D 对）；②含有CoA 的化合物，如乙酰CoA、琥珀酰 CoA；③可进行底物水平磷酸化的化合物，如 1，3- 二磷酸甘油酸（A 对）、磷酸烯醇式丙酮酸；④其他，如磷酸肌酸、氨基甲酰磷酸、焦磷酸、葡糖-1-磷酸等。以上分类中，除②含有CoA的化合物（高能硫酯键）外，其余类型均含高能磷酸键。1，6 二磷酸果糖（十版生物化学P108）分子中第 1、6 位的磷酸键是普通酯键，而不是高能磷酸键（B 错，为本题正确答案）。","","N"],["2011-N33",6,"第4节 个别氨基酸的代谢","一碳单位的来源及转换",2011,33,"A","","经分解代谢可产生一碳单位的氨基酸是",[["A","谷氨酸"],["B","酪氨酸"],["C","苏氨酸"],["D","组氨酸"]],"D","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的基团，包括甲基、甲烯基、甲炔基、甲酰基及亚氨甲基等。一碳单位主要来自丝氨酸、甘氨酸、组氨酸（D对）及色氨酸的分解代谢，记忆的口诀为施（丝氨酸）舍（色氨酸）一根竹（组氨酸）竿（甘氨酸）。本题答案略有争议，苏氨酸（C对）通过间接转变成为甘氨酸也可以产生一碳单位。","","N"],["2011-N34",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶核苷酸的分解代谢的终产物",2011,34,"A","","胸腺嘧啶分解代谢的产物为",[["A","β-羟基丁酸"],["B","β-氨基异丁酸"],["C","β-丙氨酸"],["D","尿酸"]],"B","β-氨基异丁酸（B对）是胸腺嘧啶分解代谢的中间产物。β-羟基丁酸（十版生物化学P148）A错）为酮体，是脂肪酸分解代谢的中间产物。β-丙氨酸（十版生物化学P227）（C错）是胞嘧啶和尿嘧啶分解代谢的中间产物。尿酸（十版生物化学P223）（D错）是所有嘌呤分解代谢的终产物。","","N"],["2011-N35",12,"第1节 RNA的生物合成概述","以DNA为模板的RNA合成",2011,35,"A","","下列关于转录作用的叙述，正确的是",[["A","以RNA为模板合成cDNA"],["B","需要4种dNTP为原料"],["C","合成反应的方向为3'-5'"],["D","转录起始不需要引物参与"]],"D","转录是生物体以DNA为模板，以4种NTP为原料（B错），按照5’→3’方向（C错）合成RNA的过程。转录所需的酶为RNA聚合酶，该酶可直接促进转录起点处的两个核苷酸间形成磷酸二酯键，因而转录起始不需要引物参与（D对）。以RNA为模板合成cDNA（A错）属于逆转录过程。","","N"],["2011-N36",11,"第2节 DNA复制的酶学和拓扑学","原核生物的DNA聚合酶",2011,36,"A","","下列关于原核生物DNA聚合酶Ⅲ的叙述，错误的是",[["A","是复制延长中真正起作用的酶"],["B","由多亚基组成的不对称异聚合体"],["C","具有5'-3'聚合酶活性"],["D","具有5'-3'核酸外切酶活性"]],"D","DNA聚合酶 Ⅲ是原核生物DNA的复制延长中真正起作用的酶（A对），它是由10种亚基组成的不对称异聚合体（B对）。它可以在5’→3’方向上催化子链DNA的合成，即具有5’→3’聚合酶活性（C对），还可以及时识别合成过程中错配的DNA并进行剪切，即具有3’→5’外切酶活性。原核生物经典的三种DNA聚合酶中，只有DNA聚合酶Ⅰ具有5’→3’外切酶活性（D错，为本题正确答案）。","","N"],["2011-N37",13,"第5节 蛋白质合成的干扰和抑制","引起读码错误的抗生素",2011,37,"A","","下列选项中，属于蛋白质生物合成抑制剂的是",[["A","5-氟尿嘧啶"],["B","卡那霉素"],["C","甲氨蝶呤"],["D","别嘌呤醇"]],"B","卡那霉素是一种氨基糖苷类抗生素，它可与原核生物核蛋白体30S亚基（小亚基）结合，影响翻译准确性，从而抑制蛋白质生物合成（B对）。5-氟尿嘧啶（十版生物化学P226）（A错）、甲氨蝶呤（十版生物化学P226）（C错）均属于核苷酸生物合成抑制剂。别嘌呤醇（十版生物化学P224）（D错）为嘌呤核苷酸分解代谢抑制剂。","","N"],["2011-N38",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物前体RNA加工过程概的概述",2011,38,"A","","hnRNA转变成mRNA的过程是",[["A","转录起始"],["B","转录终止"],["C","转录后加工"],["D","翻译起始"]],"C","hnRNA（十版生物化学P65，P284）又称为不均一核RNA、杂化核RNA、前体mRNA等，为真核生物转录生成的初级mRNA转录物，需要经过戴帽、加尾和剪接内含子等转录后加工过程（C对）才能成为具有功能的成熟的mRNA。","","N"],["2011-N39",16,"第2节 重组DNA技术","克隆载体概述",2011,39,"A","","作为克隆载体的最基本条件是",[["A","DNA分子量较小"],["B","环状双链DNA分子"],["C","有自我复制功能"],["D","有一定遗传标志"]],"C","克隆载体可携带外源DNA片段，并利用载体的自我复制功能实现外源DNA片段在受体细胞中的无性繁殖和扩增，因此作为克隆载体的最基本条件就是具有自我复制功能（C对），放宽至基本条件，还应包括至少有一个选择标志（遗传标志）（D错）、有适宜的限制性核酸内切酶的单一切点等。常用的克隆载体包括质粒DNA、噬菌体DNA、病毒DNA、柯斯质粒、细菌人工染色体、酵母人工染色体等（十版生物化学P372），而环状双链DNA分子（B错）只是质粒DNA的形态特点。细菌人工染色体、酵母人工染色体及部分质粒的DNA分子量并不小（A错），可达100kb以上。","","N"],["2011-N40",21,"第4节 胆色素的代谢与黄疸","胆红素来源",2011,40,"A","","体内血红素代谢的终产物是",[["A","CO₂和H₂O"],["B","乙酰CoA"],["C","胆色素"],["D","胆汁酸"]],"C","化学结构上，血红素属于铁卟啉化合物，由卟啉环和Fe²⁺螯合而成，其代谢终产物是胆色素（C对）。乙酰辅酶A（B错）是体内能源物质氧化分解的重要中间产物。CO₂及H₂O（A错）是体内能源物质氧化分解的终产物。胆汁酸（D错）是胆固醇的主要代谢产物（十版生物化学P472）。","","N"],["2011-N127",6,"第4节 个别氨基酸的代谢","半胱氨酸转变为牛磺酸",2011,127,"B","","体内经代谢可转变生成牛磺酸的氨基酸的是",[["A","酪氨酸"],["B","脯氨酸"],["C","半胱氨酸"],["D","缬氨酸"]],"C","牛磺酸由半胱氨酸（C对）经氧化生成磺酸丙氨酸，再脱羧基而生成。除牛磺酸外，半胱氨酸还可以代谢生成胱氨酸、硫酸根PAPS、谷胱甘肽等多种重要的生理活性物质。","","N"],["2011-N128",6,"第1节 营养必需氨基酸与氨基酸代谢概述","蛋白质营养价值的决定因素",2011,128,"B","","属营养必需氨基酸的是",[["A","酪氨酸"],["B","脯氨酸"],["C","半胱氨酸"],["D","缬氨酸"]],"D","本知识点在九版后的教材有重大更新，八版教材人体必需氨基酸（体内不能合成，必须靠食物供给）为八种，分别为亮氨酸、异亮氨酸、苏氨酸、缬氨酸、赖氨酸、甲硫氨酸、苯丙氨酸和色氮酸，九版后教材将组氨酸也列入了人体必需氨基酸的范畴。故根据最新教材观点，人体必需氨基酸为九种，分别为亮氨酸、异亮氨酸、苏氨酸、缬氨酸（D对）、赖氨酸、甲硫氨酸、苯丙氨酸、色氮酸和组氨酸。可记忆为“一家族人来写两三本书”，一（异亮氨酸）家（甲硫氨酸）族（组氨酸）人来（赖氨酸）写（缬氨酸）两（亮氨酸）三（色氨酸）本（苯丙氨酸）书（苏氨酸）。或“写一两本淡色书出来”，写（缬氨酸）一（异亮氨酸）两（亮氨酸）本（苯丙氨酸）淡（蛋氨酸/甲硫氨酸）色（色氨酸）书（苏氨酸）出（组氨酸）来（赖氨酸）。或“组队来写一两本淡色书”，组（组氨酸）队来（赖氨酸）写（缬氨酸）一（异亮氨酸）两（亮氨酸）本（苯丙氨酸）淡（蛋氨酸/甲硫氨酸）色（色氨酸）书（苏氨酸）。","","N"],["2011-N129",11,"第2节 DNA复制的酶学和拓扑学","多种酶参与DNA解链和稳定单链状态",2011,129,"B","","在DNA复制时，能与DNA单链结合的蛋白质是",[["A","SSB"],["B","DnaB蛋白"],["C","DNA-polⅠ"],["D","DnaG蛋白"]],"A","由表14-4可知，原核生物DNA复制时，能与DNA单链结合的蛋白质是SSB（single stranded binding，单链结合蛋白）（A对）。DnaB蛋白（B错）又称解旋酶，在DNA复制时，能解开DNA双链（记忆技巧：掰<Bai>开双链，另B字母本身为螺旋状）。DnaG蛋白（D错）又称引物酶，在DNA复制时，能合成RNA引物（记忆技巧：Guide<引导>）。DNA-polⅠ（C错）即DNA聚合酶Ⅰ，在DNA复制时，能对复制中的错误进行校对，对复制和修复中出现的空隙进行填补（十版生物化学P260）。","","N"],["2011-N130",11,"第2节 DNA复制的酶学和拓扑学","多种酶参与DNA解链和稳定单链状态",2011,130,"B","","具有催化短链RNA分子合成能力的蛋白质是",[["A","SSB"],["B","DnaB蛋白"],["C","DNA-polⅠ"],["D","DnaG蛋白"]],"D","由表14-4可知，原核生物DNA复制时，具有催化短链RNA分子（即RNA引物）合成能力的蛋白质是DnaG蛋白（又称引物酶）（记忆技巧：Guide<引导>）（D对）。DnaB蛋白（B错）又称解旋酶，具有解开DNA双链的功能（记忆技巧：掰<Bai>开双链，另B字母本身为螺旋状）。SSB（A错）又称单链结合蛋白，具有稳定已解开的单链DNA的功能。DNA-pol Ⅰ（C错）即DNA聚合酶Ⅰ，具有对复制中的错误进行校对，对复制和修复中出现的空隙进行填补的功能（十版生物化学P260）。","","N"],["2011-N131",2,"第3节 RNA和空间结构与功能","非编码RNA的功能",2011,131,"B","","能对外源侵入的双链RNA进行切割的核酸是",[["A","hnRNA"],["B","siRNA"],["C","snoRNA"],["D","5SrRNA"]],"B","能对外源侵入的双链RNA进行切割的核酸是siRNA（小干扰RNA）（B对）。hnRNA（不均一核RNA、杂化核RNA）（A错）由DNA直接转录生成，为成熟mRNA的前体。SnoRNA（核仁小RNA）（C错）主要功能为参与rRNA的加工修饰。5SrRNA（D错）为核糖体的组成成分之一，参与构成原核生物和真核生物的大亚基。","","N"],["2011-N132",2,"第3节 RNA和空间结构与功能","rRNA的结构及功能",2011,132,"B","","能与核内蛋白质组成核蛋白体的是",[["A","hnRNA"],["B","siRNA"],["C","snoRNA"],["D","5S rRNA"]],"D","核蛋白体又称为核糖体，由大小亚基组成，大小亚基又分别由一定种类的蛋白质和rRNA组成，其中5S rRNA参与构成真核和原核生物核糖体大亚基（D对）。hnRNA（A错）是mRNA未成熟的前体物质，经加工修饰可形成mRNA。snoRNA（核仁小RNA）（C错）定位于核仁，主要参与rRNA的加工和修饰。siRNA（小干扰RNA）（十版生物化学P334）（B错）参与外源性基因mRNA的降解。","","N"],["2011-N157",0,"第1节 蛋白质的分子组成","氨基酸的分类",2011,157,"X","","下列氨基酸中，属于疏水性的有",[["A","缬氨酸"],["B","精氨酸"],["C","亮氨酸"],["D","脯氨酸"]],"ACD","常考的几类氨基酸：①非极性脂肪族氨基酸即疏水性氨基酸：亮氨酸（C对），甘氨酸，缬氨酸（A对），丙氨酸，异亮氨酸，脯氨酸（D 对）和甲硫氨酸（九版后教材新增），可记忆为用衣架（甲硫氨酸）晾（亮氨酸）干（甘氨酸）鞋（缬氨酸）和（与并同义，丙氨酸）衣（异亮氨酸）服（脯氨酸）。②极性中性氨基酸：苏氨酸，谷氨酰胺，丝氨酸，半胱氨酸，天冬酰胺，可记忆为苏（苏氨酸）姑（谷氨酰胺）娘死（丝氨酸）半（半胱氨酸）天（天冬酰胺）。③芳香族氨基酸：酪氨酸，苯丙氨酸，色氨酸，记忆为芳香老（酪氨酸）本（苯丙氨酸）色（色氨酸）。④酸性氨基酸：天冬氨酸，谷氨酸，记忆为三（酸）伏（谷氨酸）天（天冬氨酸）。⑤碱性氨基酸：赖氨酸，精氨酸，组氨酸，记忆为捡（碱）来（赖氨酸）精（精氨酸）读（组氨酸）。⑥支链氨基酸：缬氨酸，异亮氨酸，亮氨酸，记忆为致（支）谢（缬氨酸）良（亮氨酸）医（异亮氨酸）。⑦修饰氨基酸：胱氨酸，羟脯氨酸，羟赖氨酸。⑧不参与转氨基的氨基酸：羟脯氨酸，脯氨酸，苏氨酸，赖氨酸。","","N"],["2011-N158",2,"第1节 核酸的化学组成及其一级结构","核苷酸",2011,158,"X","","下列辅酶或辅基中，含腺嘌呤的有",[["A","FMN"],["B","FAD"],["C","NADP⁺"],["D","CoA"]],"BCD","FAD（B对）为黄素（F）腺嘌呤（A）二核苷酸（D），NADP⁺（C对）为烟酰胺（N）腺嘌呤（A）二核苷酸（D）磷酸（P），CoA（D对）由泛酸、腺嘌呤（A）、核糖核酸、磷酸等组成，三者均含腺嘌呤（A）。FMN为黄素（F）单核苷酸（MN），不含腺嘌呤（A）（A错）。","","N"],["2011-N159",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径的概述",2011,159,"X","","天冬氨酸在体内参与的代谢途径有",[["A","尿素生成"],["B","血红素合成"],["C","嘌呤核苷酸合成"],["D","嘧啶核苷酸合成"]],"ACD","在尿素生成中，天冬氨酸提供了尿素分子中的第二个氮原子（A对）。在嘌呤核苷酸合成中，天冬氨酸提供了1号位氮原子（N₁）（C对）。在嘧啶核苷酸合成中，构成嘧啶环的N₁、C₄、C₅及C₆均由天冬氨酸提供（D对）。血红素合成（十版生物化学P485）（B错）的基本原料为琥珀酰CoA、甘氨酸和Fe²⁺。","","N"],["2011-N160",11,"第4节 真核生物DNA复制过程","真核生物DNA复制的延长",2011,160,"X","","下列真核生物与原核生物复制特点的比较中，正确的有",[["A","真核生物的复制可能需要端粒酶参与"],["B","真核生物的冈崎片段短于原核生物"],["C","真核生物的复制起始点少于原核生物"],["D","真核生物DNA聚合酶的催化速率低于原核生物"]],"ABD","端粒是真核生物染色体线性DNA分子末端的结构，在维持染色体的稳定性和DNA复制的完整性中有着重要作用，它是由端粒酶催化生成的（A对）。原核生物的基因组一般为单个环状DNA分子，只有一个复制起点（单复制子复制），而真核生物的基因组庞大而复杂，由多个染色体组成，每个染色体均有多个复制起点（多复制子复制）（C错）。与原核生物相比，真核生物的复制子较小，引物和后随链的冈崎片段均较短（B对）。真核生物DNA聚合酶的催化速率远低于原核生物（D对），因而其DNA链的延长速度较慢，但因真核生物是多复制子复制，总体速度并不比原核生物慢。","","N"],["2011-N161",19,"第2节 癌基因","生长因子的概述",2011,161,"X","","下列关于生长因子的叙述，正确的有",[["A","其化学本质属于多肽"],["B","其受体定位于胞核中"],["C","主要以旁分泌和自分泌方式起作用"],["D","具有调节细胞生长与增殖功能"]],"ACD","生长因子是一种具有调节细胞生长与增殖功能（D 对）的多肽类（含蛋白质）物质（A 对）。多数生长因子受体定位于细胞膜上（B错）。生长因子的作用方式包括内分泌方式、旁分泌方式和自分泌方式，但以旁分泌和自分泌方式为主（C对）。","","N"],["2011-N162",20,"第2节 基因治疗","基因治疗的基本策略",2011,162,"X","","目前基因治疗所采用的方法有",[["A","基因矫正"],["B","基因置换"],["C","基因增补"],["D","基因失活"]],"ABCD","基因治疗是通过一定方式将人正常基因或有治疗作用的DNA片段导入人体靶细胞以矫正或置换致病基因的治疗方法。目前基因治疗所采用的方法有：①缺陷基因精确的原位修复，包括对致病基因的突变碱基进行纠正的基因矫正（A对）和用正常基因通过重组原位替换致病基因的基因置换（B对）；②基因增补（C对），该方法不删除突变的致病基因，而在基因组的某一位点额外插入正常基因，使体内表达出功能正常的蛋白质，从而达到治疗疾病的目的，基因增补是目前临床上主要采用的基因治疗方法；③基因沉默或失活（D对），该方法向患者体内导入有抑制基因表达作用的核酸，阻断致病基因的异常表达，从而达到治疗疾病的目的。","","N"],["2012-N25",0,"第2节 蛋白质的分子结构","结构模体",2012,25,"A","","下列结构中，属于蛋白质模体结构的是",[["A","α-螺旋"],["B","β-折叠"],["C","锌指结构"],["D","结构域"]],"C","模体结构是蛋白质分子中具有特定空间构象和特定功能的结构成分，其中的一类就是具有特殊功能的超二级结构（2个或2个以上具有二级结构的肽段在空间上相互接近，形成一个有规则的二级结构组合），如锌指结构（C对）为典型的模体结构，它由1个α-螺旋和2个反平行的β-折叠三个肽段组成，形似手指，具有结合锌离子功能。α-螺旋（A错）和β-折叠（B错）均为二级结构，结构域（D错）为三级结构。","","N"],["2012-N26",2,"第2节 DNA和空间结构与功能","DNA双螺旋结构的多样性",2012,26,"A","","具有左手螺旋的DNA结构是",[["A","G-四链体DNA"],["B","A型DNA"],["C","B型DNA"],["D","Z型DNA"]],"D","DNA双螺旋结构有三种类型：A型DNA（右手螺旋）、B型DNA（右手螺旋）、Z型DNA（左手螺旋）。最常见的由Watson和Crick提出的右手双螺旋结构称为B型DNA，当环境相对湿度下降后，DNA的空间结构参数发生变化，但仍是右手螺旋，此时称为A型DNA，除此以外人们还发现有左手螺旋结构的DNA称为Z型DNA（D对）。G-四链体DNA（十版生物化学P61）见于端粒结构中，呈四联体螺旋结构（而非右手螺旋或左手螺旋）（A错）。","","N"],["2012-N27",1,"第3节 酶促反应动力学","竞争性抑制",2012,27,"A","","竞争性抑制时，酶促反应表现Km值的变化是",[["A","增大"],["B","不变"],["C","减小"],["D","无规律"]],"A","竞争性抑制作用是抑制剂与酶作用的一种方式，由于抑制剂和酶的底物在结构上相似，可与底物竞争结合酶的活性中心，使实际与底物结合的酶量减少，底物与酶的亲和力下降，Km值增大（A对）。","","N"],["2012-N28",4,"第2节 糖的无氧氧化","糖酵解",2012,28,"A","","属于肝己糖激酶的同工酶类型是",[["A","Ⅰ型"],["B","Ⅱ型"],["C","Ⅲ型"],["D","Ⅳ型"]],"D","葡萄糖磷酸化生成葡糖-6-磷酸是糖酵解的第一个限速步骤，催化此反应的是己糖激酶。己糖激酶有四种同工酶，其中位于肝脏是Ⅳ型（D对），称为葡糖激酶。","","N"],["2012-N29",5,"第1节 脂质的构成、功能及分析","脂肪酸的生物学功能",2012,29,"A","","可以作为合成前列腺素原料的物质是",[["A","软脂酸"],["B","硬脂酸"],["C","花生四烯酸"],["D","棕榈油酸"]],"C","可以作为合成前列腺素原料的物质是花生四烯酸（C对），是合成前列腺素F₂α的前体，前列腺素、血栓烷、白三烯都是花生四烯酸的衍生物。","","N"],["2012-N30",7,"第4节 氧化磷酸化的影响因素","解耦联剂阻断ADP的磷酸化过程",2012,30,"A","","2，4-二硝基苯酚抑制氧化磷酸化的机制是",[["A","解偶联"],["B","抑制电子传递"],["C","抑制ATP合酶"],["D","与复合体Ⅰ结合"]],"A","阻断氧化磷酸化过程的抑制剂分为三种：①呼吸链抑制剂，此类抑制剂可阻断各复合体内的电子传递过程，如鱼藤酮、粉蝶霉素A、异戊巴比妥可阻断复合体Ⅰ内从铁硫中心到泛醌的电子传递（BD错）；②解偶联剂，此类抑制剂可使氧化与磷酸化的偶联脱离，电子可沿呼吸链正常传递并建立跨内膜的质子电化学梯度储存能量，但不能使ADP磷酸化合成ATP，如二硝基苯酚阻断ADP的磷酸化过程（A对）；③ATP合酶抑制剂，此类抑制剂既可抑制电子传递，又可抑制ADP的磷酸化，如寡霉素、二环己基碳二亚胺同时抑制电子传递和ADP的磷酸化过程（C错）。","","N"],["2012-N31",6,"第3节 氨的代谢","丙氨酸-葡萄糖循环",2012,31,"A","","氨的运输所涉及的机制是",[["A","丙氨酸-葡萄糖循环"],["B","三羧酸循环"],["C","核蛋白体循环"],["D","甲硫氨酸循环"]],"A","氨是体内的有毒物质，各组织必须以无毒的形式通过血液将氨运输到肝脏代谢。氨可以通过丙氨酸-葡萄糖循环（A对）将氨转变为丙氨酸从骨骼肌运往肝，也可以通过谷氨酰胺从脑和骨骼肌运往肝或肾。三羧酸循环（十版生物化学P117）（B错）又称柠檬酸循环，是三大营养物质代谢的最终代谢通路。甲硫氨酸循环（十版生物化学P189）（D错）参与甲硫氨酸的转甲基作用，为机体提供活性甲基。核蛋白体循环（C错）又称核糖体循环，介导肽链合成的延长过程。","","N"],["2012-N32",8,"第2节 嘌呤核苷酸的合成与分解代谢","氨基酸类似物",2012,32,"A","","谷氨酰胺类似物所拮抗的反应是",[["A","脱氧核糖核苷酸的生成"],["B","dUMP的甲基化"],["C","嘌呤核苷酸的从头合成"],["D","黄嘌呤氧化酶催化的反应"]],"C","谷氨酰胺是嘌呤核苷酸（十版生物化学P220）和嘧啶核苷酸（十版生物化学P225）的合成原料，因此谷氨酰胺类似物可拮抗嘌呤核苷酸（C对）和嘧啶核苷酸的从头合成途径。拮抗脱氧核糖核苷酸的生成的是阿糖胞苷（十版生物化学P226）（A错），它是胞苷（胞嘧啶核苷）的类似物，可抑制CDP还原成dCDP。拮抗dUMP甲基化（生成dTMP）（B错）的是甲氨蝶呤（十版生物化学P226）和5-氟尿嘧啶（十版生物化学P226）。拮抗黄嘌呤氧化酶催化作用的是别嘌呤醇（十版生物化学P224）（D错），它是次黄嘌呤的类似物，可抑制嘌呤分解为尿酸。","","N"],["2012-N33",9,"第3节 代谢调节的主要方式","化学修饰调节对酶活性的调节",2012,33,"A","","下列反应中属于酶化学修饰的是",[["A","强酸使酶变性失活"],["B","加入辅酶使酶具有活性"],["C","肽链苏氨酸残基磷酸化"],["D","小分子物质使酶构象改变"]],"C","酶化学修饰调节（十版生物化学P49）是指酶蛋白肽链上的某些氨基酸残基可在另一酶的催化下，发生可逆的共价修饰，从而改变酶活性的调节方式。最常见的化学修饰调节类型是磷酸化与去磷酸化，磷酸化位点一般是酶蛋白肽链中的苏氨酸残基（C对），酪氨酸残基和丝氨酸残基。小分子物质使酶构象改变（D错）属于变构调节。辅酶与酶结合形成具有活性的全酶（十版生物化学P34）不属于酶的化学修饰（B错），亦未归类于酶的其他任何调节方式。强酸使酶变性失活（A错）属于酶的变性。","","N"],["2012-N34",11,"第2节 DNA复制的酶学和拓扑学","真核细胞DNA聚合酶",2012,34,"A","","真核生物DNA复制的主要酶是",[["A","DNA聚合酶β"],["B","DNA聚合酶γ"],["C","DNA聚合酶δ"],["D","DNA聚合酶ε"]],"C","常见的真核生物DNA聚合酶有5种：①DNA pol α具有引物酶活性；②DNA pol β（A错）复制的保真度低，可能是参与应急修复的酶；③DNA pol γ（B错）是线粒体DNA复制的酶；④ DNA pol δ （C）负责合成后随链；⑤ DNA pol ε（D） 负责合成前导链。本考点在九版后教材有重大更新，八版教材中前导链和后随链均由DNA pol δ负责合成，故认为DNA pol δ（D）是真核生物 DNA 链延长中起主要作用的复制酶。九版之后的教材则指出DNA pol δ 负责合成后随链，而DNA pol ε 负责合成前导链，即按照最新教材观点，DNA pol δ （C对）和DNA pol ε （D对）均可认为是真核生物延长过程中主要的复制酶。本题依照旧版教材给出的参考答案为C。","","N"],["2012-N35",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物转录需要转录因子的参与",2012,35,"A","","RNA聚合酶Ⅱ所识别的DNA结构是",[["A","内含子"],["B","外显子"],["C","启动子"],["D","增强子"]],"C","RNA聚合酶Ⅱ是真核生物的一种RNA聚合酶，它通过转录因子的辅助作用（十版生物化学P278），间接与DNA模板上的启动子（C对）结合而启动转录，合成hnRNA。内含子（A错）和外显子（B错）分别代表基因的非编码序列和编码序列，是转录合成产物RNA上的核酸序列，不是DNA结构。增强子（十版生物化学P247）（D错）是能够被特异基因调节蛋白所识别，促进邻近或远隔特定基因表达的DNA结构。","","N"],["2012-N36",13,"第4节 蛋白质合成后的加工和靶向输送","新生肽链折叠需要分子伴侣",2012,36,"A","","参与新生多肽链正确折叠的蛋白质是",[["A","分子伴侣"],["B","G蛋白"],["C","转录因子"],["D","释放因子"]],"A","分子伴侣（A对）是一系列指导新生肽链按照特定方式正确折叠的辅助性蛋白质，包括热激蛋白、伴侣蛋白等。G蛋白（十版生物化学P393）（B错）为鸟苷酸结合蛋白的简称，是一种能与鸟苷酸结合，具有GTP水解酶活性的信号转导蛋白。转录因子（十版生物化学P280）（C错）又称反式作用因子，是真核细胞内能够识别和结合各类顺式作用元件，参与调控靶基因转录效率的蛋白质。释放因子（十版生物化学P300）（D错），又称为终止因子，具有特异识别终止密码子的功能，参与蛋白质的生物合成过程。","","N"],["2012-N37",14,"第1节 基因表达调控的基本概念与特点","基因表达的特点",2012,37,"A","","基因表达的细胞特异性是指",[["A","基因表达按一定的时间顺序发生"],["B","同一基因在不同细胞表达不同"],["C","基因表达因环境不同而改变"],["D","基因在所有细胞中持续表达"]],"B","基因表达的细胞特异性（空间特异性）是指多细胞生物在特定生长发育阶段，同一基因在不同的细胞（组织器官）表达不同（B对）。基因表达按一定的时间顺序发生（A错）体现的是基因表达的时间特异性（阶段特异性）。有些基因几乎在所有细胞中持续表达（D错），有些基因的表达则因环境不同而改变（C错），体现了基因表达方式的多样性（十版生物化学P316）。","","N"],["2012-N38",15,"第2节 聚合酶链反应技术","逆转录PCR技术",2012,38,"A","","可以利用逆转录酶作为工具酶的作用是",[["A","质粒的构建"],["B","细胞的转染"],["C","重组体的筛选"],["D","目的基因的合成"]],"D","利用cDNA法进行目的基因合成（D对）需要利用逆转录酶作为工具酶：逆转录酶以mRNA为模板合成cDNA，再以cDNA为模板通过PCR反应来合成目的基因。以cDNA为模板合成的目的基因不含内含子（以基因组DNA为模板合成的目的基因含内含子），可直接转入大肠杆菌等原核生物中进行基因表达。质粒的构建（十版生物化学P374）（A错）涉及质粒和基因片段的剪切和重组，主要利用限制性核酸内切酶、碱性磷酸酶、DNA连接酶等作为工具酶，无需利用逆转录酶。细胞的转染（十版生物化学P375）（B错）方法包括化学方法和物理方法，不涉及逆转录酶。重组体的筛选（十版生物化学P376）（C错）方法包括遗传标志筛选法、序列特异性筛选法和亲和筛选法，亦不涉及逆转录酶。","","N"],["2012-N39",17,"第3节 细胞受体介导的细胞内信号转导","G蛋白耦联受体的概述",2012,39,"A","","与7次跨膜结构受体偶联的蛋白质是",[["A","蛋白激酶A"],["B","小G蛋白"],["C","酪氨酸蛋白激酶"],["D","异源三聚体结构的G蛋白"]],"D","7次跨膜结构受体通过与异源三聚体结构（由α、β和γ三个不同亚基组成）的G蛋白偶联（D对）向下游传递信号，因此又称G蛋白偶联受体。蛋白激酶A（十版生物化学P387）（A错）又称依赖cAMP的蛋白激酶，为G蛋白偶联受体信号转导途径的下游效应分子。酪氨酸蛋白激酶（十版生物化学P389）（C错）为酶联型受体信号转导途径的受体（属单次跨膜受体）或受体偶联蛋白。小G蛋白（十版生物化学P390）（B错）又称低分子量G蛋白，与异源三聚体G蛋白一样具有鸟核苷酸的结合位点和GTP酶活性，是多种细胞信号转导通路中的信号转导分子。","","N"],["2012-N40",19,"第3节 抑癌基因","抑癌基因在癌症发生发展中具有重要作用",2012,40,"A","","下列关于PTEN的叙述正确的是",[["A","细胞内受体"],["B","抑癌基因产物"],["C","作为第二信使"],["D","具有丝/苏氨酸激酶活性"]],"B","PTEN基因是近年来新发现的一种抑癌基因（B对），其产物PTEN蛋白具有磷酸酶（催化去磷酸化反应）活性，即具有与丝/苏氨酸激酶（催化磷酸化反应）相反的催化活性（D错）。PTEN可催化PI-3K/Akt信号通路中的第二信使PIP₃去磷酸化生成PIP₂，PIP₂则可在磷脂酶C的催化下生成IP₃/DAG-PKC信号通路中的第二信使IP₃和DAG（十版生物化学P396），因此PTEN与第二信使PIP₃的分解和第二信使DAG、IP₃的生成有关，但其自身并不是第二信使（C错）。PTEN为位于细胞内的非受体分子（P415图22-4 PTEN通过阻断PI3K/AKT信号通路抑制细胞的生长增殖）（A错）。","","N"],["2012-N127",4,"第2节 糖的无氧氧化","丙酮酸激酶",2012,127,"B","","糖的无氧酵解涉及的关键酶是",[["A","丙酮酸激酶"],["B","乳酸脱氢酶"],["C","琥珀酸脱氢酶"],["D","异柠檬酸脱氢酶"]],"A","糖的无氧酵解即糖酵解，其关键酶包括己糖激酶（葡糖激酶），磷酸果糖激酶-1和丙酮酸激酶（A对）。乳酸脱氢酶为无氧氧化的非关键酶（B错）。琥珀酸脱氢酶为三羧酸循环的非关键酶（十版生物化学P116）（C错）。异柠檬酸脱氢酶为三羧酸循环的关键酶（十版生物化学P115）（D错）。","","N"],["2012-N128",4,"第3节 糖的有氧氧化","三羧酸循环的关键酶",2012,128,"B","","三羧酸循环的关键酶是",[["A","丙酮酸激酶"],["B","乳酸脱氢酶"],["C","琥珀酸脱氢酶"],["D","异柠檬酸脱氢酶"]],"D","三羧酸循环又称柠檬酸循环，其关键酶有：柠檬酸合酶、异柠檬酸脱氢酶（D对）和α-酮戊二酸脱氢酶复合体。丙酮酸激酶（十版生物化学P110）是糖酵解的关键酶（A错）。乳酸脱氢酶（十版生物化学P108）为无氧氧化过程中（催化丙酮酸变成乳酸）的非关键酶（B错）。琥珀酸脱氢酶（十版生物化学P116）参与三羧酸循环，但不是关键酶（C错）。","","N"],["2012-N129",4,"第4节 戊糖磷酸途径","戊糖磷酸途径的意义",2012,129,"B","","与G6PD缺陷有关的疾病是",[["A","蚕豆病"],["B","苯丙酮尿症"],["C","帕金森病"],["D","镰刀型红细胞贫血症"]],"A","还原型谷胱甘肽是体内重要的抗氧化剂，可以保护一些含巯基的蛋白质免受氧化，这种作用在红细胞尤其重要，可以保证细胞膜的完整性。NADPH的功能之一就是使被氧化的谷胱甘肽还原，便于其在体内重复利用。G6PD（葡糖-6-磷酸脱氢酶）是磷酸戊糖途径中的关键酶，G6PD缺乏的患者，NADPH生成减少，谷胱甘肽的还原状态难以维持，因此红细胞膜易受攻击发生破裂，出现溶血性黄疸，这种现象常出现于食用蚕豆后，因此称为蚕豆病（A对）。苯丙酮尿症（十版生物化学P191）（B错）与苯丙氨酸羟化酶缺陷有关。帕金森病（十版生物化学P191）（C错）与多巴胺生成减少有关。镰刀型红细胞贫血症（十版生物化学P25）（D错）与血红蛋白发生点突变有关（β亚基第6位的谷氨酸被缬氨酸取代）。","","N"],["2012-N130",6,"第4节 个别氨基酸的代谢","酪氨酸的代谢",2012,130,"B","","与多巴胺生成障碍有关的疾病是",[["A","蚕豆病"],["B","苯丙酮尿症"],["C","帕金森病"],["D","镰刀形红细胞贫血症"]],"C","多巴胺是脑内一种重要的神经递质，与多巴胺生成障碍有关的疾病是帕金森病（C对）。蚕豆病（十版生物化学P106）（A错）与葡糖-6-磷酸脱氢酶缺陷有关。苯丙酮尿症（十版生物化学P192）（B错）与苯丙氨酸羟化酶缺陷有关。镰刀形红细胞贫血（七版生物化学P261）（D错）由碱基错配（点突变）引起。","","N"],["2012-N131",14,"第3节 真核基因表达调控","启动子",2012,131,"B","","常见的参与真核生物基因转录调控的DNA结构是",[["A","终止子"],["B","外显子"],["C","TATA盒"],["D","操纵基因"]],"C","TATA盒（C对）是真核生物启动子的核心功能组件，通常位于转录起始点上游-25～-30bp区域，控制转录起始的准确性及频率。终止子注意与终止密码子区分，终止子（A对）是原核生物和真核生物均具有的给予RNA聚合酶转录终止信号的DNA序列，参与基因转录调控，而终止密码子为蛋白质翻译过程中终止肽链合成的mRNA序列，与转录调控无关。外显子（B错）指出现在真核生物成熟mRNA分子上的序列（十版生物化学P287）。操纵基因（D错）又称操作元件，是原核生物操纵子中能与阻遏蛋白结合的DNA序列（十版生物化学P320）。故本题AC均对，参考答案为C。","","N"],["2012-N132",14,"第2节 原核基因表达调控","操纵子",2012,132,"B","","常见的参与原核生物基因转录调控的DNA的结构是",[["A","终止子"],["B","外显子"],["C","TATA盒"],["D","操纵基因"]],"D","原核生物基因转录调控是以操纵子为单位进行的，操纵子由结构基因、调控序列和调节基因组成，而调控序列主要包括启动子和操纵元件（操纵基因）（D对）。终止子注意与终止密码子区分，终止子（A对）是原核生物和真核生物均具有的给予RNA聚合酶转录终止信号的DNA序列，参与基因转录调控，而终止密码子为蛋白质翻译过程中终止肽链合成的mRNA序列，与转录调控无关。TATA盒（十版生物化学P280）（C错）为真核生物Ⅱ类启动子的核心组成部分，决定着RNA合成的起始位点。外显子（十版生物化学P287）（B错）是真核生物基因中最终出现在成熟mRNA分子上的序列。本题的答案应为AD，原参考答案为D。","","N"],["2012-N157",5,"第6节 血浆脂蛋白及其代谢","低密度脂蛋白的功能和代谢途径",2012,157,"X","","下列关于LDL的叙述，正确的有",[["A","LDL主要由VLDL在血浆中转变而来"],["B","LDL的主要功能是运输内源性甘油三酯"],["C","LDL受体广泛存在于各种细胞膜表面"],["D","LDL的密度大于HDL"]],"AC","LDL即低密度脂蛋白，LDL主要由VLDL（极低密度脂蛋白）在血浆中转变而来（A对），其主要功能是运输内源性胆固醇（B错）。LDL受体广泛分布于全身，特别是肝、肾上腺皮质、卵巢、睾丸、动脉壁等组织的细胞膜表面（C对）。血浆脂蛋白的密度从大到小依次为高密度脂蛋白（HDL）>低密度脂蛋白（LDL）>极低密度脂蛋白（VLDL）>乳糜微粒（CM）（D错）。","","N"],["2012-N158",9,"第3节 代谢调节的主要方式","化学修饰调节对酶活性的调节",2012,158,"X","","属于酶化学修饰调节的反应有",[["A","乙酰化"],["B","磷酸化"],["C","腺苷化"],["D","泛素化"]],"ABC","酶化学修饰调节是指酶蛋白肽链上的某些氨基酸残基可在另一酶的催化下，发生可逆的共价修饰，从而改变酶活性的调节方式。酶的化学修饰主要有磷酸化与去磷酸化（B对）、乙酰化与去乙酰化（A对）、甲基化与去甲基化、腺苷化与去腺苷化（C对）及SH与—S—S—互变等。泛素化（十版生物化学P175）（D错）介导真核生物蛋白质在蛋白酶体内的降解过程，不属于酶的化学修饰调节。","","N"],["2012-N159",11,"第5节 逆转录","逆转录的意义",2012,159,"X","","逆转录酶的生物学意义有",[["A","补充了中心法则"],["B","进行基因操作制备cDNA"],["C","细菌DNA复制所必需的酶"],["D","加深了对RNA病毒致癌致病的认识"]],"ABD","中心法则认为DNA兼有遗传信息的传代和表达功能，因此DNA处于生命活动的中心位置。逆转录现象说明：至少在某些生物，RNA同样兼有遗传信息传代与表达功能。这是对中心法则的补充（A对）。逆转录酶可以以mRNA为模板催化合成cDNA（B对），cDNA不包含内含子等调控序列，是基因工程研究中获取目的基因的重要来源。对逆转录酶的研究，加深了对逆转录病毒（RNA病毒）致癌理论的认识（D对），如HIV就是一种逆转录病毒。细菌DNA复制所必需的酶为DNA聚合酶（十版生物化学P260）（C错）。","","N"],["2012-N160",13,"第4节 蛋白质合成后的加工和靶向输送","蛋白质合成后的加工和靶向输送的概述",2012,160,"X","","蛋白质多肽链生物合成后的加工过程有",[["A","二硫键形成"],["B","氨基端修饰"],["C","多肽链折叠"],["D","辅基的结合"]],"ABCD","新生蛋白质不具备生物学活性，必须经过复杂的合成后加工过程才能转变为具有天然构象的功能蛋白质，这一加工过程称为翻译后修饰。翻译后修饰包括多肽链折叠为天然的三维构象（C对）及肽链一级结构修饰、空间结构的修饰等（七版生物化学P307）。氨基端修饰（B对）是指氨基端的氨基酸残基发生糖基化、羟基化、甲基化或磷酸化等化学修饰的过程（七版生物化学P331），属于一级结构修饰。二硫键形成（A对）是指两个半胱氨酸残基侧链上的巯基（SH基）经氧化后进行硫-硫（S-S）共价键的过程，属于一级结构修饰。辅基的结合（D对）是指新生肽链与辅基结合后形成结合蛋白质，属于空间结构的修饰。","","N"],["2012-N161",22,"第3节 血细胞物质代谢","红细胞获得能量的途径",2012,161,"X","","成熟红细胞糖酵解的生物学意义有",[["A","是红细胞获得能量的唯一途径"],["B","代替磷酸戊糖途径提供NADPH"],["C","为三羧酸循环提供更多的产能物质"],["D","糖酵解支路产物可调节血红蛋白运氧功能"]],"AD","成熟红细胞无线粒体，糖有氧氧化、脂肪酸氧化、氨基酸的分解代谢的某些步骤需要在线粒体中进行，因此这些反应在成熟红细胞内无法完成。糖酵解在胞液中进行，红细胞内存在催化糖酵解反应所需要的酶和中间代谢产物，因此糖酵解成为成熟红细胞获得能量的唯一途径（A对）。糖酵解可提供NADH，但不提供NADPH（B错）。成熟红细胞糖酵解产物不进入三羧酸循环过程（C错）。糖酵解的支路产物2，3-二磷酸甘油酸（2，3-BPG）可调节血红蛋白运氧功能（D对）。","","N"],["2012-N162",3,"第1节 脂溶性维生素","维生素D",2012,162,"X","","下列关于维生素D的叙述，正确的有",[["A","调节体内钙、磷代谢"],["B","代谢产物可与核受体结合"],["C","作为辅酶参与糖有氧氧化"],["D","构成视觉细胞内的感光物质"]],"AB","维生素D是体内的一种脂溶性维生素，其代谢产物1，25-（OH）₂-D₃是一种类固醇类激素。1，25-（OH）₂-D₃在靶细胞内与特异的核受体结合（B对），进入细胞核，调节相关基因表达。1，25-（OH）₂-D₃还可通过信号转导系统使钙通道开放，发挥其对钙磷代谢的快速调节作用（A对）。作为辅酶参与糖有氧氧化的是B族维生素（C错），构成视觉细胞内的感光物质的是维生素A（D错）。","","N"],["2013-N25",0,"第3节 蛋白质结构与功能的关系","蛋白质一级结构是高级结构与功能的基础",2013,25,"A","","“不同蛋白质有不同的空间构象”所指的含义是",[["A","蛋白质的变性与复性"],["B","多肽链的折叠机制"],["C","一级结构决定高级结构"],["D","结合蛋白质有多种辅基"]],"C","不同蛋白质有不同的空间构象，是因为不同蛋白质之间的一级结构各不相同，而蛋白质一级结构决定高级结构（空间构象）（C对）。","","N"],["2013-N26",2,"第4节 核酸的理化性质","DNA变性",2013,26,"A","","DNA理化性质中的“Tm”值所表达的含义是",[["A","复制时的温度"],["B","复性时的温度"],["C","50%双链被打开的温度"],["D","由B型转变成A型的温度"]],"C","解链温度（Tm）又称为融解温度，是指DNA解链过程中，溶液在260nm处的吸光度达到最大值一半时所对应的温度，在此温度时，50%的DNA双链解离成单链（C对）。一般来讲，DNA的Tm值与DNA分子的长短以及碱基的GC含量有关，分子的G+C含量越高，Tm值越高。","","N"],["2013-N27",1,"第3节 酶促反应动力学","酶促反应动力学参数",2013,27,"A","","酶Km值的大小所代表的含义是",[["A","酶对底物的亲和力"],["B","最适的酶浓度"],["C","酶促反应的速度"],["D","酶抑制剂的类型"]],"A","Km即米氏常数，为酶的特征性常数，在数值上等于酶促反应速率为最大反应速率一半时的底物浓度。一定条件下，Km值可以表示酶对底物的亲和力（A对），Km越大，表示酶对底物的亲和力越小，Km越小，酶对底物的亲和力越大。","","N"],["2013-N28",4,"第2节 糖的无氧氧化","糖的无氧氧化的概述",2013,28,"A","","糖酵解途径所指的反应过程是",[["A","葡萄糖转化成磷酸二羟丙酮"],["B","葡萄糖转化成乙酰辅酶A"],["C","葡萄糖转化成乳酸"],["D","葡萄糖转化成丙酮酸"]],"D","根据七版教材的说法，糖酵解途径是指由葡萄糖转化成丙酮酸的过程（D对），糖酵解（又称无氧氧化）是指葡萄糖转化成丙酮酸进而还原生成乳酸的过程（即糖酵解包括糖酵解途径和乳酸生成两个阶段）（C错）。八版后的教材对此知识点有更新，明确指出葡萄糖转化成丙酮酸的过程为糖酵解，而无氧氧化（不再与糖酵解同义）包括糖酵解和乳酸生成两个阶段（P91）。葡萄糖转化为磷酸二羟丙酮属于糖酵解途径的一部分（A错）。葡萄糖经糖酵解途径生成丙酮酸，丙酮酸进一步脱羧才能生成乙酰CoA（B错）。","","N"],["2013-N29",5,"第6节 血浆脂蛋白及其代谢","高密度脂蛋白的功能和代谢途径",2013,29,"A","","能够逆向转运胆固醇到肝的脂蛋白是",[["A","CM"],["B","LDL"],["C","VLDL"],["D","HDL"]],"D","不同来源脂蛋白具有不同功能：①乳糜微粒（CM）（A错）主要转运外源性甘油三酯及胆固醇；②极低密度脂蛋白（VLDL）（C错）主要转运内源性甘油三酯；③低密度脂蛋白（LDL）（B错）主要转运内源性胆固醇；④高密度脂蛋白（HDL）（D对）主要逆向转运胆固醇。","","N"],["2013-N30",4,"第3节 糖的有氧氧化","三羧酸循环的过程",2013,30,"A","","下列物质中，能够在底物水平上生成 GTP的是",[["A","乙酰 CoA"],["B","琥珀酰 CoA"],["C","脂肪酰 CoA"],["D","丙二酸单酰 CoA"]],"B","底物分子中的能量直接以高能键形式转移给ADP或其他二磷酸核苷（GDP）生成ATP或其他三磷酸核苷（GTP），这个过程称为底物水平磷酸化（十版生物化学P108）。在三羧酸循环中发生一次底物水平磷酸化，即琥珀酰CoA在琥珀酰CoA合成酶催化下生成琥珀酸，该反应是发生在线粒体的可逆反应，琥珀酰CoA的高能硫酯键水解（B对），与GDP或 ADP 的磷酸化偶联，转变为新的高能磷酸键，最终生成 GTP或ATP。","","N"],["2013-N31",6,"第4节 个别氨基酸的代谢","一碳单位的来源及转换",2013,31,"A","","可以作为一碳单位来源的氨基酸是",[["A","丝氨酸"],["B","丙氨酸"],["C","亮氨酸"],["D","甲硫氨酸"]],"A","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的基团，包括甲基、甲烯基、甲炔基、甲酰基及亚氨甲基等。一碳单位主要来自丝氨酸（A对）、甘氨酸、组氨酸及色氨酸的分解代谢，记忆的口诀为施（丝氨酸）舍（色氨酸）一根竹（组氨酸）竿（甘氨酸）。解释一下D选项，甲硫氨酸通过S-腺苷甲硫氨酸（SAM）提供“活性甲基”（一碳单位），但甲硫氨酸的甲基来源于直接生成一碳单位的氨基酸（由同型半胱氨酸接受其他氨基酸产生的一碳单位而生成），因此甲硫氨酸只是转移一碳单位（与四氢叶酸和维生素B₁₂类似），并不能算是一碳单位的来源（D错）。","","N"],["2013-N32",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸分解代谢的终产物",2013,32,"A","","别嘌呤醇治疗痛风的可能机制是",[["A","抑制黄嘌呤氧化酶"],["B","促进dUMP的甲基化"],["C","促进尿酸生成的逆反应"],["D","抑制脱氧核糖核苷酸的生成"]],"A","痛风因血中尿酸的含量升高而引起，尿酸来自于黄嘌呤氧化酶催化的嘌呤核苷酸的分解代谢。别嘌呤醇可抑制黄嘌呤氧化酶（A对），从而抑制尿酸的生成，达到治疗痛风的目的。","","N"],["2013-N33",9,"第3节 代谢调节的主要方式","关键酶活性决定代谢途径的速率和方向",2013,33,"A","","下列物质代谢调节方式中，属于快速调节的是",[["A","产物对酶合成的阻遏作用"],["B","酶蛋白的诱导合成"],["C","酶蛋白的降解作用"],["D","酶的别构调节"]],"D","细胞水平的物质代谢调节主要调节关键酶活性，根据调节速度不同可分为快速调节和迟缓调节。快速调节通过别构效应（D对）和化学修饰作用进行调节，作用较快，在数秒及数分内即可发生。迟缓调节则通过调节酶蛋白分子的合成（AB错）或降解（C错）以改变细胞内酶的含量来调节酶促反应速率，作用较慢，一般需数小时或几天才能实现。","","N"],["2013-N34",18,"第2节 DNA损伤修复","跨越损伤DNA合成",2013,34,"A","","对广泛DNA损伤进行紧急、粗糙、高错误率的修复方式是",[["A","光修复"],["B","切除修复"],["C","重组修复"],["D","SOS修复"]],"D","DNA损伤修复包括直接修复（如光修复）、切除修复、重组修复和SOS修复。光修复（A错）又称嘧啶二聚体的直接修复，是利用光修复酶直接识别并结合到DNA嘧啶二聚体位置，进行修复的过程。切除修复（B错）是一种最普遍的DNA损伤的修复方式，是通过将不正常的碱基或者核苷酸片段除去并准确替换的精确、高效的修复方式。重组修复（十版生物化学P411）（C错）是指依靠重组酶系，将另一段未受损伤的DNA移到损伤部位，提供正确的模板，进行修复的过程。SOS修复（十版生物化学P413）（D对）是一种紧急状态下的修复方式（因海空紧急呼救信号SOS而得名），此种修复方式比较粗糙，错误率极高。","","N"],["2013-N35",12,"第3节 真核生物mRNA的转录、加工和降解","mRNA编辑",2013,35,"A","","RNA编辑所涉及的过程是",[["A","RNA合成后的加工过程"],["B","RNA聚合酶识别模板的过程"],["C","DNA指导的RNA合成过程"],["D","tRNA反密码对密码的识别过程"]],"A","RNA编辑是指对RNA的编码序列进行合成（转录）后加工的过程（A对）。DNA指导的RNA合成过程（C错）为转录（十版生物化学P272）。tRNA反密码对密码的识别过程（D错）发生于蛋白质合成时的肽链延长阶段（进位）（十版生物化学P304），RNA聚合酶识别模板的过程（B错）发生于转录起始阶段（十版生物化学P274），二者均与RNA编辑无关。","","N"],["2013-N36",14,"第2节 原核基因表达调控","操纵子",2013,36,"A","","下列关于原核生物蛋白质合成的叙述，正确的是",[["A","一条mRNA编码几种蛋白质"],["B","释放因子是eRF"],["C","80S核蛋白体参与合成"],["D","核内合成，胞液加工"]],"A","原核生物大多数基因表达调控是通过操纵子机制实现的。操纵子由结构基因与调控序列组成。结构基因通常共用一个启动子和1个转录终止信号序列，共同编码数个功能关联基因，因此其转录出来的一条mRNA可编码几种蛋白质（A对）。原核生物蛋白质合成的释放因子是RF，真核生物的是eRF（B错）（十版生物化学P301）。80S核蛋白体参与真核生物蛋白质合成（八版生物化学P343），70S核蛋白体参与原核生物蛋白质合成（C错）。原核生物没有核膜包被的细胞核，蛋白质的合成和加工均在胞质中完成（D错）。","","N"],["2013-N37",14,"第2节 原核基因表达调控","操纵子",2013,37,"A","","原核生物基因组的特点是",[["A","核小体是其基本组成单位"],["B","转录产物是多顺反子"],["C","基因的不连续性"],["D","线粒体DNA为环状结构"]],"B","原核生物的转录产物为多顺反子（B对），可以编码几种不同的蛋白质。核小体是真核生物染色质的基本组成单位（A错）（P325）。基因的不连续性（C错）是真核生物基因组的特点（十版生物化学P244）。原核生物没有线粒体（D错）。","","N"],["2013-N38",17,"第3节 细胞受体介导的细胞内信号转导","cAMP-PKA通路",2013,38,"A","","下列涉及G蛋白偶联受体信号的主要途径是",[["A","cAMP-PKA信号途径"],["B","酪氨酸激酶受体信号途径"],["C","雌激素-核受体信号途径"],["D","丝/苏氨酸激酶受体信号途径"]],"A","不同的G蛋白偶联受体可通过不同的通路（信号途径）传递信号（十版生物化学P396），其中常见的有3种：①cAMP-PKA通路（信号途径）（A对）；②IP₃/DAG-PKC通路（信号途径）；③Ca²⁺/钙调蛋白依赖的蛋白激酶通路（信号途径）。酪氨酸激酶受体信号途径（十版生物化学P396）（B错）和丝/苏氨酸激酶受体信号途径（十版生物化学P389）（D错）涉及的均是酶联型受体信号。雌激素-核受体信号途径（C错）涉及的是细胞内受体信号（十版生物化学P392）。","","N"],["2013-N39",19,"第2节 癌基因","原癌基因的活化机制",2013,39,"A","","下列可以导致原癌基因激活的机制是",[["A","获得启动子"],["B","转录因子与RNA结合"],["C","抑癌基因的过表达"],["D","p53蛋白诱导细胞凋亡"]],"A","从正常的原癌基因转变为具有使细胞转化功能的癌基因的过程称为原癌基因的激活，原癌基因激活将导致肿瘤的发生。原癌基因的激活机制主要有以下四种：①获得启动子（A对）或增强子；②染色体易位；③基因扩增；④点突变。转录因子与RNA结合（十版生物化学P328）（B错）可调控真核基因的表达。抑癌基因的过表达（C错）可抑制细胞生长和肿瘤发生。p53蛋白（由抑癌基因p53编码）诱导细胞凋亡（D错）亦可抑制细胞生长和肿瘤发生。","","N"],["2013-N40",20,"第2节 基因治疗","治疗基因导入",2013,40,"A","","目前基因治疗主要采用的方式是",[["A","对患者缺陷基因进行重组"],["B","提高患者的DNA合成能力"],["C","调整患者DNA修复的酶类"],["D","将表达目的基因的细胞输入患者体内"]],"D","目前基因治疗所采用的基本方法有基因矫正、基因置换（对患者缺陷基因进行重组）（A错）、基因增补和基因失活等，其中基因增补是目前临床上主要采用的方法。基因增补不删除突变的致病基因，而在靶细胞基因组的某一位点额外插入正常基因（目的基因），使体内表达出功能正常的蛋白质，从而达到治疗疾病的目的。基因增补的具体实施方案为：先将需要接受目的基因的细胞从体内取出，在体外培养，然后将携带有目的基因的载体导入细胞内，最后筛选出表达目的基因的细胞，经过繁殖扩大后输入患者体内（D对）。提高患者的DNA合成能力（B错）和调整患者DNA修复的酶类（C错）不属于目前基因治疗的方法。","","N"],["2013-N127",5,"第3节 甘油三酯代谢","脂肪酰CoA进入线粒体",2013,127,"B","","脂肪酸β-氧化的关键酶是",[["A","脂酰CoA脱氢酶"],["B","脂酰CoA合成酶"],["C","HMG-CoA还原酶"],["D","肉碱脂酰转移酶Ⅰ"]],"D","脂酰CoA进入线粒体是脂肪酸β-氧化的限速步骤，而脂酰CoA进入线粒体需要肉碱脂酰转移酶I的作用，因此肉碱脂酰转移酶I（D对）是脂肪酸β-氧化的关键酶。脂酰CoA合成酶（十版生物化学P146）（B错）和脂酰CoA脱氢酶（十版生物化学P147）（A错）均为催化脂肪酸β-氧化的非关键酶，前者将脂肪酸活化为脂酰CoA，后者催化β-氧化的第一次脱氢反应。HMG-CoA还原酶（十版生物化学P159）（C错）为胆固醇合成的关键酶。","","N"],["2013-N128",5,"第5节 胆固醇代谢","胆固醇的合成过程",2013,128,"B","","胆固醇合成的关键酶是",[["A","脂酰CoA脱氢酶"],["B","脂酰CoA合成酶"],["C","HMG-CoA还原酶"],["D","肉碱脂酰转移酶Ⅰ"]],"C","胆固醇合成的关键酶是HMG-CoA还原酶（C对）。脂酰CoA脱氢酶（十版生物化学P146）（A错）及脂酰CoA合成酶（十版生物化学P146）（B错）为脂肪酸β-氧化的非关键酶。肉碱脂酰转移酶Ⅰ（十版生物化学P146）（D错）为脂肪酸β-氧化的关键酶。","","N"],["2013-N129",21,"第1节 肝在物质代谢中的作用","蛋白质合成及分解",2013,129,"B","","主要在肝外组织合成的蛋白质是",[["A","白蛋白"],["B","α球蛋白"],["C","β球蛋白"],["D","γ球蛋白"]],"D","大部分血浆蛋白质都在肝内合成，白蛋白（A错）、α球蛋白（B错）、β球蛋白（C错）均由肝脏合成。γ球蛋白（D对）又称免疫球蛋白，主要在浆细胞内（肝外）合成。","","N"],["2013-N130",5,"第3节 甘油三酯代谢","脂肪动员",2013,130,"B","","能够运输脂肪酸的蛋白质是",[["A","白蛋白"],["B","α球蛋白"],["C","β球蛋白"],["D","γ球蛋白"]],"A","血浆蛋白质分子的表面上分布众多的亲脂性结合位点，脂溶性物质可与其结合而被运输，此为血浆蛋白质的运输作用。众多发挥运输作用的血浆蛋白质中最重要的是白蛋白（清蛋白），白蛋白（A对）能与脂肪酸、Ca²⁺、胆红素、水杨酸、磺胺药等多种难溶于水的物质结合，便于其在血液中运输。（10版生物化学与分子生物学P145：血浆清蛋白具有结合游离脂肪酸的能力（每分子清蛋白可结合7分子游离脂肪酸），能将脂肪酸运送至全身，主要由心、肝、骨骼肌等摄取利用。）","","N"],["2013-N131",15,"第4节 生物分子相互作用研究技术","酵母双杂交技术",2013,131,"B","","用于分析蛋白质-蛋白质相互作用的技术是",[["A","蛋白质印迹分析"],["B","酵母双杂交技术"],["C","电泳迁移率变动测定"],["D","基因剔除技术"]],"B","目前常用的分析蛋白质-蛋白质相互作用的技术包括酵母双杂交（B对）、各种亲和分离层析（亲和色谱、免疫共沉淀、标签蛋白沉淀等）、FRET（荧光能量共振转移）效应分析、噬菌体显示系统筛选等（十版生物化学P347）。蛋白质印迹分析（Western blotting）（A对），是一种用于定性及半定量检测蛋白质表达水平的技术，也可用于蛋白质分子的相互作用研究等（十版生物化学P338）。电泳迁移率变动测定（EMSA）（C错）是一种用于分析DNA-蛋白质相互作用的技术（十版生物化学P349）。基因剔除技术（九版生物化学P468）（D错）是一种用基因剔除策略鉴定基因功能的技术。本题正确答案为AB，但官方参考答案为B。","","N"],["2013-N132",15,"第1节 印迹法和探针技术","蛋白质印迹法的作用",2013,132,"B","","用于检测基因表达水平的测定技术是",[["A","蛋白质印迹分析"],["B","酵母双杂交技术"],["C","电泳迁移率变动测定"],["D","基因剔除技术"]],"A","基因表达产物包括RNA和蛋白质/多肽，因此检测基因表达水平就是检测RNA和蛋白质水平（P462）。蛋白质印迹分析（十版生物化学P338）（A对）也被称为Western blotting，是一种常见的定性及半定量检测蛋白质表达水平的实验技术。酵母双杂交技术（十版生物化学P348）（B错）用于分析蛋白质-蛋白质之间的相互作用。电泳迁移率变动测定（十版生物化学P349）（C错）主要用于分析DNA-蛋白质之间的相互作用。基因剔除技术（九版生物化学P468）（D错）主要用于分析基因的功能。","","N"],["2013-N156",17,"第2节 细胞内信号转导分子","第二信使的概述",2013,156,"X","","在激素作用的机制中发挥第二信使作用的物质有",[["A","cGMP"],["B","Ca²⁺"],["C","cAMP"],["D","DG"]],"ABCD","第二信使是指外源信息在细胞内的信号转导分子，cGMP（环鸟苷酸）（A对）、Ca²⁺（B对）、cAMP（环腺苷酸）（C对）、DG（二酰甘油）（D对）均属于第二信使物质。","","N"],["2013-N157",4,"第2节 糖的无氧氧化","糖酵解",2013,157,"X","","6-磷酸葡萄糖直接参与的代谢途径有",[["A","糖酵解"],["B","磷酸戊糖途径"],["C","三羧酸循环"],["D","糖原分解"]],"ABD","糖酵解（A对）途径中，葡萄糖在己糖激酶的催化下生成6-磷酸葡萄糖（十版生物化学P108）。磷酸戊糖途径（B对）从糖酵解生成的6-磷酸葡萄糖开始形成旁路（十版生物化学P121）。糖原分解（D对）的产物即为6-磷酸葡萄糖。6-磷酸葡萄糖可经分解代谢生成乙酰CoA，间接参与（C错）三羧酸循环过程。","","N"],["2013-N158",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径的概述",2013,158,"X","","谷氨酰胺的生物学作用有",[["A","储存和运输氨"],["B","参与脂肪酸的生物合成"],["C","参与嘧啶核苷酸的从头合成"],["D","参与嘌呤核苷酸的从头合成"]],"ACD","谷氨酰胺是脑、骨骼肌等组织储存氨及向肝、肾运输氨的形式（A对），亦参与嘌呤核苷酸（D对）和嘧啶核苷酸（C对）的从头合成过程。脂肪酸生物合成（十版生物化学P151）（B错）的基本原料为乙酰CoA、ATP、NADPH、HCO₃⁻（CO₂）、Mn²⁺等，十版生物化学P232指出，体内的氨基酸均能分解生成乙酰CoA，经还原缩合反应合成脂肪酸，按照最新观点，该题B选项存在争议。","","N"],["2013-N159",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物前体RNA加工过程概的概述",2013,159,"X","","真核生物前体mRNA合成后的加工有",[["A","mRNA编辑"],["B","3'-末端加多聚A"],["C","前体mRNA剪接去除内含子"],["D","在分子伴侣协助下折叠成天然构象"]],"ABC","真核生物前体mRNA合成后的加工包括：①在5＇-端加入“帽”结构；②在3＇-端加上多聚A（腺苷酸）尾结构（B对）；③剪接去除不能作为模板指导蛋白质翻译的内含子序列（C对）；④部分基因的mRNA序列在转录后发生改变（mRNA编辑）（A对）。在分子伴侣协助下折叠成天然构象（十版生物化学P307）（D错）为蛋白质合成后的加工过程。","","N"],["2013-N160",13,"第5节 蛋白质合成的干扰和抑制","抗生素通过抑制蛋白质合成发挥作用",2013,160,"X","","能够影响蛋白质生物合成的物质有",[["A","毒素"],["B","泛素"],["C","抗生素"],["D","干扰素"]],"ACD","毒素（A对）能影响蛋白质生物合成，如白喉毒素可使真核生物延长因子eEF-2发生ADP糖基化修饰而失活，阻止肽链延长，从而影响蛋白质的生物合成过程。抗生素（C对），如四环素、链霉素、氯霉素、红霉素等均可通过各种机制影响原核生物蛋白质合成，发挥抗菌作用。干扰素（D对）可活化一种特异的蛋白激酶，使蛋白质翻译的起始因子eIF-2磷酸化而失活，也可活化一种特异的核酸内切酶（RNase L），使蛋白质翻译的模板mRNA被降解，以上两种机制均可影响蛋白质的生物合成，发挥抗病毒作用。泛素（十版生物化学P175）（B错）可使蛋白质在蛋白酶体通过ATP依赖途径被降解，即泛素影响的是蛋白质的降解。","","N"],["2013-N161",21,"第4节 胆色素的代谢与黄疸","结合",2013,161,"X","","未结合胆红素同义名称还有",[["A","直接胆红素"],["B","间接胆红素"],["C","游离胆红素"],["D","肝胆红素"]],"BC","未结合胆红素是指未与葡萄糖醛酸结合转化的胆红素，其同义名称还包括游离胆红素（C对）、间接胆红素（B对）、血胆红素、肝前胆红素。直接胆红素（A错）和肝胆红素（D错）均为结合胆红素的同义名称。","","N"],["2013-N162",3,"第1节 脂溶性维生素","维生素A",2013,162,"X","","下列关于维生素A的叙述，正确的有",[["A","有效的抗氧化剂"],["B","化学本质是类固醇"],["C","代谢产物可与核受体结合"],["D","缺乏后对弱光的敏感性降低"]],"ACD","维生素A是一种脂溶性维生素，它的作用包括维持视觉功能（它参与组成视紫红质，主要与暗视觉有关）（D对）、调节基因表达和组织分化（这是通过其活化形式全反式维甲酸作用于核受体影响转录而发挥的）（C对）、抗氧化作用（A对）、抑制肿瘤生长等。维生素A是由1分子β-白芷酮环和2-分子异戊二烯构成的不饱和一元醇，不属于类固醇。化学本质为类固醇（B错）的维生素是维生素D。","","N"],["2014-N25",0,"第3节 蛋白质结构与功能的关系","蛋白质一级结构是高级结构与功能的基础",2014,25,"A","","蛋白质的空间构象主要取决于肽链中的结构是",[["A","二硫键位置"],["B","β-折叠"],["C","α-螺旋"],["D","氨基酸序列"]],"D","蛋白质的空间构象（高级结构）决定于其一级结构，而蛋白质的一级结构主要指蛋白质中氨基酸的排列顺序（D对）。二硫键的位置（A错）也属于一级结构的范畴，但不决定蛋白质的空间构象。β-折叠（B错）和α-螺旋（C错）为蛋白质的二级结构。","","N"],["2014-N26",2,"第2节 DNA和空间结构与功能","DNA双螺旋的相关实验",2014,26,"A","","如果一个新分离的核酸成分碱基组成为A=27%，G=30%，T=21%，C=22%，这一核酸分子最可能的结构是",[["A","双链DNA"],["B","DNA-RNA杂交双链"],["C","单链RNA"],["D","单链DNA"]],"D","组成DNA的碱基为A、T、C、G，组成RNA的碱基有A、U、C、G，因此该核酸分子不可能为单链RNA（C错）或DNA-RNA杂交双链（B错），而A≠T，C≠G，不符合双链DNA的特点（A错）。考虑A+C+T+G恰好为100%，该核酸分子最可能的结构是单链DNA（D对）。","","N"],["2014-N27",1,"第3节 酶促反应动力学","竞争性抑制",2014,27,"A","","丙二酸对琥珀酸脱氢酶的抑制作用属于",[["A","不可逆抑制"],["B","非竞争性抑制"],["C","反竞争性抑制"],["D","竞争性抑制"]],"D","竞争性抑制作用是指抑制剂和酶的底物在结构上相似，可与底物竞争结合酶的活性中心，从而阻碍酶与底物形成中间产物。丙二酸（HOOC-CH₂-COOH）与琥珀酸（HOOC-CH₂-CH₂-COOH）结构类似，可与其竞争性结合琥珀酸脱氢酶，故丙二酸对琥珀酸脱氢酶的抑制作用是竞争性抑制作用（D对）。","","N"],["2014-N28",4,"第3节 糖的有氧氧化","三羧酸循环的关键酶",2014,28,"A","","调节三羧酸循环的关键酶是",[["A","苹果酸脱氢酶"],["B","丙酮酸脱氢酶"],["C","异柠檬酸脱氢酶"],["D","顺乌头酸酶"]],"C","三羧酸循环又称柠檬酸循环，有三个关键酶：柠檬酸合酶、异柠檬酸脱氢酶（C对）和α-酮戊二酸脱氢酶复合体。苹果酸脱氢酶（A错）和顺乌头酸酶（D错）参与三羧酸循环，但不是关键酶。丙酮酸脱氢酶复合体（十版生物化学P113）（B错）为丙酮酸氧化脱羧的关键酶，不属于三羧酸循环。","","N"],["2014-N29",4,"第3节 糖的有氧氧化","丙酮酸氧化脱羧",2014,29,"A","","丙酮酸脱氢酶复合体中不包括的物质是",[["A","FAD"],["B","生物素"],["C","NAD⁺"],["D","辅酶A"]],"B","丙酮酸脱氢酶复合体是葡萄糖有氧氧化的关键酶之一，催化丙酮酸脱氢脱羧生成乙酰CoA。参与反应的辅酶有焦磷酸硫胺素（TPP），硫辛酸，FAD（A对），NAD⁺（C对）和CoA（辅酶A），可记忆为赴美（辅酶A）交流（TPP，焦磷酸硫胺素）时留心（硫辛酸）谎（FAD，黄素腺嘌呤二核苷酸）言（NAD⁺，烟酰胺腺嘌呤二核苷酸）（亦可记忆为SPA，即名称中带有S、P、A字母的，注：硫的化学符号为S）。生物素（十版生物化学P99）（B错，为本题正确答案）又称为维生素H、维生素B₇、辅酶R等，是多种羧化酶的辅基，参与二氧化碳的羧化。","","N"],["2014-N30",5,"第3节 甘油三酯代谢","软脂酸合成的原料",2014,30,"A","","乙酰CoA出线粒体的机制是",[["A","三羧酸循环"],["B","苹果酸-天冬氨酸穿梭"],["C","柠檬酸-丙酮酸循环"],["D","α-磷酸甘油穿梭"]],"C","在脂肪酸合成代谢过程中，用于脂肪酸合成的乙酰CoA主要由葡萄糖分解供给，在线粒体内产生，不能自由通过线粒体内膜，需要通过柠檬酸-丙酮酸循环（十版生物化学P151 图8-5）（C对）进入胞质：乙酰CoA首先在线粒体内与草酰乙酸缩合生成柠檬酸，柠檬酸通过线粒体内膜上的载体转运进入胞质，最后胞质中ATP-柠檬酸裂解酶使柠檬酸裂解释出乙酰CoA和草酰乙酸。苹果酸-天冬氨酸穿梭（十版生物化学P206）（B错）和α-磷酸甘油穿梭（十版生物化学P205）（D错）为生物氧化过程中胞质内NADH进线粒体的机制。三羧酸循环（十版生物化学P117）（A错）是三大营养物质（糖、脂肪、氨基酸）有氧氧化的最终代谢通路及代谢联系的枢纽，不参与任何物质进出线粒体的过程。","","N"],["2014-N31",5,"第3节 甘油三酯代谢","脂肪酰CoA进入线粒体",2014,31,"A","","下列物质中，促进脂肪酸β-氧化的是",[["A","柠檬酸"],["B","丙二酰CoA"],["C","肉碱"],["D","丙酮酸"]],"C","催化脂肪酸氧化的酶系存在于线粒体基质，活化的脂酰CoA必须进入线粒体才能被氧化。长链脂酰CoA不能直接透过线粒体内膜，需要肉碱协助转运，因此肉碱可促进脂肪酸β-氧化（C对）。柠檬酸（A错）、丙二酰CoA（B错）、丙酮酸（D错）分别是三羧酸循环、脂酸合成、糖酵解的中间产物，它们含量充足说明机体能量过量，脂肪β-氧化会受到抑制。","","N"],["2014-N32",7,"第4节 氧化磷酸化的影响因素","甲状腺激素促进氧化磷酸化和产热",2014,32,"A","","甲状腺功能亢进患者基础代谢率增高的原因是",[["A","解耦联蛋白基因表达增强"],["B","ATP合成增加"],["C","ATP-ADP转位酶活性降低"],["D","细胞膜Na⁺，K⁺-ATP酶活性降低"]],"A","基础代谢率（九版生理学P215）指的是人在清醒和极端安静的情况下，不受精神紧张，肌肉活动，食物和环境温度等因素影响时的能量代谢率。甲状腺功能亢进患者基础代谢率增高是因为：①甲状腺激素诱导细胞膜Na⁺，K⁺-ATP酶的生成，使其活性增加（D错），加速ATP分解为ADP和Pi，ADP增多促进氧化磷酸化，导致机体耗氧量增加；②甲状腺激素可诱导解耦联蛋白基因表达（A对），氧化呼吸链电子传递产生的能量不能用于ATP生成（B错），而导致机体产热增加。ATP-ADP转位酶（十版生物化学P211）富含于线粒体内膜，可协调转运ADP进入和ATP移出线粒体，ATP-ADP转位酶活性降低时ADP进入线粒体的数量降低，基础代谢率降低（C错）。","","N"],["2014-N33",6,"第2节 氨基酸的一般代谢","氨基酸氧化脱氨基",2014,33,"A","","在肌肉中氨基酸脱氨基作用的主要方式",[["A","谷氨酸氧化脱氨基作用"],["B","谷氨酰胺酶参与的脱氨基作用"],["C","转氨基作用"],["D","嘌呤核苷酸循环"]],"D","机体大多组织器官是通过联合脱氨基作用脱去氨基，联合脱氨基作用包括转氨酶介导的转氨基作用和L-谷氨酸脱氢酶介导的谷氨酸氧化脱氨基作用两个方面。但在心肌和骨骼肌中L-谷氨酸脱氢酶的活性很弱（谷氨酸氧化脱氨基作用弱）（A错），氨基酸很难通过联合脱氨基作用脱去氨基。这些组织中，氨基酸主要通过嘌呤核苷酸循环脱去氨基（D对）。谷氨酰胺酶（十版生物化学P181）（B错）参与的脱氨基作用在肝或肾中发生，可介导氨从脑和骨骼肌等组织运往肝或肾的过程。转氨基作用（十版生物化学P177）（C错）在肌肉中存在，但转氨基作用与脱氨基作用为两种截然不同的过程（联合脱氨基作用即包括转氨基作用和脱氨基作用两个方面）。","","N"],["2014-N34",8,"第3节 嘧啶核苷酸的合成与分解代谢","CTP的合成",2014,34,"A","","在嘧啶合成途径中，合成CTP的直接前体是",[["A","GMP"],["B","UTP"],["C","UMP"],["D","ATP"]],"B","嘧啶核苷酸从头合成直接生成的是UMP，UMP通过尿苷酸激酶和二磷酸核苷激酶的连续作用，生成UTP（三磷酸尿苷），并在CTP合成酶催化下，消耗一分子ATP，从谷氨酰胺接受氨基而成为CTP（三磷酸胞苷），因此，合成CTP的直接前体是UTP（B对）。","","N"],["2014-N35",11,"第1节 DNA复制的基本规律","DNA复制从起点双向进行",2014,35,"A","","真核生物体为解决庞大基因组复制问题的适应性机制是",[["A","双向复制"],["B","半不连续复制"],["C","多复制子复制"],["D","滚环复制"]],"C","从一个DNA复制起始点起始的DNA复制区域称为复制子。真核生物基因组庞大而复杂，由多个染色体组成，每个染色体有多个起点，呈多复制子复制特征（C对）。真核生物和原核生物DNA复制都有双向复制、半不连续复制的特征（AB错）。滚环复制（七版教材P258）（D错）为噬菌体DNA的复制方式。","","N"],["2014-N36",12,"第1节 RNA的生物合成概述","以DNA为模板的RNA合成",2014,36,"A","","在DNA双链中，能够转录生成RNA的核酸链是",[["A","领头链"],["B","编码链"],["C","随从链"],["D","模板链"]],"D","在DNA双链中，能够转录生成RNA的核酸链是模板链（D对），相对应的与之互补配对的另一股单链被称为编码链（B错）。领头链（前导链）（A错）为DNA复制时沿解链方向生成的子链DNA，随从链（后随链）（C错）为DNA复制时逆解链方向所生成的子链DNA（十版生物化学P257）。","","N"],["2014-N37",13,"第2节 蛋白质合成体系","遗传密码的特点",2014,37,"A","","反密码子摆动性的生物学意义是",[["A","维持生物表型稳定"],["B","有利于遗传变异"],["C","生物通用性"],["D","遗传特异性"]],"A","反密码子摆动性是指tRNA的反密码子与mRNA的密码子配对并不严格（不严格遵循Watson-Crick碱基配对原则）的现象。这种摆动配对发生于反密码子第1位碱基与密码子第3位碱基之间，如反密码子第1位的I（次黄嘌呤）可分别与密码子第3位的A或C或U配对、反密码子第1位的U可分别与密码子第3位的A或G配对、反密码子第1位的G可分别与密码子第3位的C或U配对等。摆动性能使一种tRNA识别mRNA序列中的多种简并性密码子，有利于维持生物表型的稳定（A对），避免有害突变的发生。","","N"],["2014-N38",14,"第3节 真核基因表达调控","转录因子的DNA结合结构域",2014,38,"A","","下列蛋白质中，具有锌指模序的是",[["A","酶"],["B","细胞转运蛋白"],["C","转录因子"],["D","膜受体"]],"C","大多数转录因子是DNA结合蛋白，至少包括两个不同的结构域：DNA结合域和转录激活域。转录因子（C对）的DNA结合结构域主要有三种：锌指模体（模序）结构、碱性螺旋-环-螺旋模体（模序）结构和碱性亮氨酸拉链模体（模序）结构。","","N"],["2014-N39",17,"第3节 细胞受体介导的细胞内信号转导","GPCR介导的信号转导途径具有相同模式",2014,39,"A","","在经典的信号转导途径中，受G蛋白激活直接影响的酶是",[["A","PKC"],["B","MAPK"],["C","JAK"],["D","AC"]],"D","在经典的信号转导途径（G蛋白偶联受体介导的信号转导途径）中，受G蛋白激活直接影响的酶称为G蛋白效应器，主要包括腺苷酸环化酶（AC）（D对）、磷脂酶C（PLC）、磷脂酶A₂（PLA₂）和磷酸二酯酶（PDE）等（九版生理学P27）。PKC（蛋白激酶C）（A错）也受G蛋白激活的影响，但非直接影响，对其有直接影响的是第二信使DAG和Ca²⁺（G蛋白→PLC→DAG/Ca²⁺→PKC）（十版生物化学P396）。MAPK（丝裂原激活的蛋白激酶）（B错）为酶联型受体信号转导途径的下游效应分子，对其有直接影响的是MAPKK（Ras→MAPKKK→MAPKK→MAPK）（十版生物化学P397）。JAK（Janus Kinase）（C错）是一种非受体型酪氨酸蛋白激酶，与细胞因子受体结合而存在，对其有直接影响的是细胞因子（十版生物化学P396）。","","N"],["2014-N40",22,"第1节 血浆蛋白质","血浆蛋白质的功能",2014,40,"A","","下列血浆蛋白中，主要维持血浆胶体渗透压的是",[["A","α球蛋白"],["B","β球蛋白"],["C","γ球蛋白"],["D","白蛋白"]],"D","白蛋白（D对）分子量小，其分子数量远远多于血浆中其他蛋白，因此血浆胶体渗透压的75%～80%来自白蛋白（九版生理学P59）。α球蛋白（A错）、β球蛋白（B错）、γ球蛋白（C错）数量相对少，占胶体渗透压比例较小。","","N"],["2014-N127",0,"第3节 蛋白质结构与功能的关系","蛋白质的功能依赖特定空间结构",2014,127,"B","","与疯牛病发病相关的机制是",[["A","蛋白质构象改变"],["B","DNA缺失突变"],["C","DNA点突变"],["D","蛋白质表达水平改变"]],"A","疯牛病是由朊病毒蛋白引起的一组人和动物神经退行性病变。人体感染朊病毒以后，由机体染色体基因编码的PrP蛋白发生构象改变（A对）：富含α-螺旋结构的PrP蛋白（PrPC型）在某种未知蛋白质的作用下转变成富含β-折叠结构的PrP蛋白（PrPSC型），使蛋白最终形成淀粉样纤维沉淀而致病。","","N"],["2014-N128",0,"第3节 蛋白质结构与功能的关系","蛋白质一级结构是高级结构与功能的基础",2014,128,"B","","与镰形红细胞贫血发病相关的机制是",[["A","蛋白质构象改变"],["B","DNA缺失突变"],["C","DNA点突变"],["D","蛋白质表达水平改变"]],"C","镰形红细胞贫血是一种常见的隐性遗传性疾病，其血红蛋白β链基因上的CTC突变成了CAC（C对），此突变转录到mRNA上为GAG变成了GUG，导致该部位的谷氨酸被缬氨酸所代替，使红细胞变成镰刀状而易于破碎，导致贫血发生。因蛋白质构象改变（A错）而发病的典型疾病为疯牛病（十版生物化学P27）。","","N"],["2014-N129",6,"第3节 氨的代谢","氨基甲酰磷酸合成酶Ⅰ",2014,129,"B","","鸟氨酸循环启动的限速酶是",[["A","氨基甲酰磷酸合成酶Ⅰ"],["B","氨基甲酰磷酸合成酶Ⅱ"],["C","精氨酸代琥珀酸裂解酶"],["D","腺苷酸代琥珀酸合成酶"]],"A","鸟氨酸循环受两种限速酶的调节。氨基甲酰磷酸合成酶Ⅰ（CPS-Ⅰ）（A对）是鸟氨酸循环启动的限速酶，它催化NH₃和CO₂生成氨基甲酰磷酸。精氨酸代琥珀酸合成酶是尿素合成启动以后的限速酶，它催化瓜氨酸与天冬氨酸生成精氨酸代琥珀酸。精氨酸代琥珀酸裂解酶（十版生物化学P183）（C错）为鸟氨酸循环的非限速酶。氨基甲酰磷酸合成酶Ⅱ（CPS-Ⅱ）（十版生物化学P225）（B错）是参与嘧啶核苷酸合成的酶。腺苷酸代琥珀酸合成酶（十版生物化学P249）（D错）为IMP（次黄嘌呤核苷酸）转化为AMP（腺嘌呤核苷酸）过程中所需要的酶。","","N"],["2014-N130",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶核苷酸从头合成的调节",2014,130,"B","","嘧啶核苷酸合成的限速酶是",[["A","氨基甲酰磷酸合成酶Ⅰ"],["B","氨基甲酰磷酸合成酶Ⅱ"],["C","精氨酸代琥珀酸裂解酶"],["D","腺苷酸代琥珀酸合成酶"]],"B","嘧啶环和尿素的合成都开始于氨基甲酰磷酸的生成，但尿素合成中所需的氨基甲酰磷酸是在肝线粒体中由尿素合成的限速酶氨基甲酰磷酸合成酶Ⅰ（十版生物化学P183）（A错）催化生成的，而嘧啶合成所用的氨基甲酰磷酸则是细胞质中用谷氨酰胺为氮源，由嘧啶核苷酸合成的限速酶氨基甲酰磷酸合成酶Ⅱ（哺乳类动物细胞的限速酶）（B对）催化生成的。精氨酸代琥珀酸裂解酶（十版生物化学P183）（C错）为尿素合成的非限速酶。腺苷酸代琥珀酸合成酶（D错）为由IMP合成AMP（十版生物化学P220）及嘌呤核苷酸循环（本质上仍为IMP合成AMP的过程）所需的酶。","","N"],["2014-N131",5,"第3节 甘油三酯代谢","酮体的生成",2014,131,"B","","参与酮体合成的酶是",[["A","HMG-CoA合酶"],["B","琥珀酰CoA转硫酶"],["C","乙酰乙酸硫激酶"],["D","乙酰CoA羧化酶"]],"A","酮体的合成过程：2分子乙酰CoA在乙酰乙酰CoA硫解酶作用下，缩合成乙酰乙酰CoA，乙酰乙酰CoA再在羟甲基戊二酸单酰CoA合酶（HMG-CoA合酶）（A对）作用下，与1分子乙酰CoA缩合成HMG-CoA，最后，HMG-CoA在HMG-CoA裂解酶作用下被裂解生成酮体之一的乙酰乙酸。琥珀酰CoA转硫酶（B错）和乙酰乙酸硫激酶（C错）均为参与酮体氧化分解的酶。乙酰CoA羧化酶（十版生物化学P152）（D错）为参与脂肪酸合成的酶（关键酶）。","","N"],["2014-N132",5,"第5节 胆固醇代谢","胆固醇的合成过程",2014,132,"B","","参与胆固醇合成的酶是",[["A","HMG-CoA合酶"],["B","琥珀酰CoA转硫酶"],["C","乙酰乙酸硫激酶"],["D","乙酰CoA羧化酶"]],"A","胆固醇合成过程十分复杂，有近30步酶促反应，其中前2步反应与酮体合成（十版生物化学P149、P159）是相同的：第一步，2分子乙酰CoA在乙酰乙酰CoA硫解酶作用下，缩合成乙酰乙酰CoA；第二步，乙酰乙酰CoA在HMG-CoA合酶（A对）作用下，与1分子乙酰CoA缩合成HMG-CoA。琥珀酰CoA转硫酶（十版生物化学P149）（B错）和乙酰乙酸硫激酶（十版生物化学P149）（C错）均为参与酮体氧化分解的酶。乙酰CoA羧化酶（十版生物化学P152）（D错）为参与脂肪酸合成的酶（关键酶）。","","N"],["2014-N157",5,"第3节 甘油三酯代谢","脂肪酰CoA分解",2014,157,"X","","下列反应步骤中，参与脂肪酸β氧化的有",[["A","脂酰CoA合成"],["B","脂酰CoA经肉碱进入线粒体"],["C","脂酰CoA经硫解酶硫解"],["D","脂酰CoA氧化生成乙酰CoA"]],"ABCD","脂肪酸β-氧化分三步进行：①脂肪酸活化为脂酰CoA（A对）；②脂酰CoA在肉碱的协助下进入线粒体（B对）；③脂酰CoA进入线粒体后，经脱氢、加水、再脱氢、硫解（C对）等四步循环反应，彻底氧化生成 NADH、FADH2和乙酰 CoA（D对）。本题的C选项原为“脂酰CoA经硫解酶水解”，根据官方给出的正确答案ABCD来看，C选项应为“脂酰CoA经硫解酶硫解”。","","N"],["2014-N158",2,"第3节 RNA和空间结构与功能","mRNA的结构及功能",2014,158,"X","","真核生物的mRNA结构包括",[["A","TATA盒"],["B","5'-末端7甲基鸟嘌呤核苷"],["C","3'-末端多聚腺苷酸"],["D","开放阅读框"]],"BCD","从5’-端到3’-端，真核生物的mRNA结构依次包括5’-末端-7-甲基鸟嘌呤核苷（B对）、开放阅读框（可读框）（D对）和3’-末端多聚腺苷酸（C对）。TATA盒又称Hogness盒，是真核生物启动子的核心序列，参与转录起始，存在于DNA模版链中，而不存在于mRNA中（A错）。","","N"],["2014-N159",17,"第3节 细胞受体介导的细胞内信号转导","酶耦联受体的作用",2014,159,"X","","参与受体型TPK-Ras-MAPK途径的分子有",[["A","Ras蛋白"],["B","Grb2"],["C","EGF受体"],["D","Raf蛋白"]],"ABCD","PTK-Ras-MAPK途径是表皮生长因子（EGF）的主要作用途径，其具体过程为：①EGF与EGF受体（C对）结合后形成二聚体，激活受体的蛋白酪氨酸激酶（PTK）活性；②受体自身酪氨酸残基磷酸化，形成SH2结合位点，从而能够结合含有SH2结构域的接头蛋白Grb2（B对）；③Grb2的两个SH3结构域与SOS分子中的富含脯氨酸序列结合，将SOS活化；④活化的SOS结合Ras蛋白（A对），促进Ras释放GDP、结合GTP；⑤活化的Ras蛋白（Ras-GTP）可激活MAPKKK（Raf蛋白）（七版生物化学P385）（D对），活化的MAPKKK可磷酸化MAPKK（MEK蛋白）而将其激活，活化的MAPKK将MAPK（ERK1蛋白）磷酸化而激活；⑥活化的MAPK蛋白可以转位至细胞核内，通过磷酸化作用激活多种效应蛋白，从而使细胞对外来信号产生生物学应答。","","N"],["2014-N160",21,"第3节 胆汁与胆汁酸的代谢","胆汁酸的生理功能",2014,160,"X","","胆囊中胆汁浓缩后胆固醇沉淀析出形成胆结石，其原因有",[["A","胆汁酸肠肝循环减少"],["B","消化道丢失胆汁酸过多"],["C","肝合成胆汁酸的功能降低"],["D","排入胆汁中的胆固醇过多"]],"ABCD","人体内约99%的胆固醇随胆汁经肠道排出体外，由于胆固醇难溶于水，在浓缩后的胆囊胆汁中胆固醇较易沉淀析出。胆固醇是否从胆汁沉淀析出主要取决于胆汁酸盐和卵磷脂与胆固醇之间的比例（胆汁中的胆汁酸盐与卵磷脂协同作用，使胆固醇分散形成可溶性微团，使之不易结晶沉淀）。肝合成胆汁酸的能力下降（C对）、消化道丢失胆汁酸过多（B对）或胆汁酸肠肝循环减少（A对），以及排入胆汁中的胆固醇过多（高胆固醇血症）（D对）等均可造成胆汁中胆汁酸和卵磷脂与胆固醇的比例下降（小于10：1），胆固醇析出沉淀。","","N"],["2014-N161",19,"第2节 癌基因","生长因子的分类及作用机制",2014,161,"X","","编码的产物属于转录因子的癌基因有",[["A","c-fos"],["B","c-sis"],["C","c-myc"],["D","c-jun"]],"ACD","癌基因又称细胞癌基因（cellular oncogene，c-onc）或原癌基因（十版生物化学P435）。癌基因是基因组内正常存在的基因，其编码产物通常作为正调控信号促进细胞的增殖和生长，包括生长因子、生长因子受体、信号转导蛋白、细胞周期蛋白、转录因子等。c-fos、c-sis、c-myc、c-jun均为癌基因，其中c-fos（A对）、c-myc（C对）、c-jun（D对）编码的产物属于转录因子，可促进增殖相关基因表达；c-sis（B错）编码的产物属于生长因子。","","N"],["2014-N162",15,"第2节 聚合酶链反应技术","PCR技术的作用",2014,162,"X","","PCR及其衍生技术主要应用于",[["A","目的基因克隆"],["B","基因表达检测"],["C","DNA序列分析"],["D","基因的体外突变"]],"ABCD","PCR（聚合酶链反应）是一种在体外大量扩增目的基因片段的分子生物学技术。PCR的主要用途包括：①目的基因的克隆（A对），应用PCR技术可将人们感兴趣的DNA片段进行大量扩增、克隆；②基因的体外突变（D对），利用PCR技术可以随意设计引物在体外对目的基因片段进行嵌合、缺失、点突变等改造；③DNA和RNA的微量分析，PCR技术高度敏感，对模板DNA的量的要求很低，是DNA和RNA微量分析（RNA微量分析利用RT-PCR技术，属于基因表达检测范畴）（B对）最好的方法；④DNA的序列测定（C对），将PCR技术引入DNA序列测定，使得测定工序大为简单，也提高了测序的速度；⑤基因的突变分析，PCR与其他技术结合可以大大提高基因突变检测的敏感性，例如单链构象多态性分析、等位基因特异的寡核苷酸探针分析等。","","N"],["2015-N25",0,"第4节 蛋白质的理化性质","两性电离性质",2015,25,"A","","使血清白蛋白（pI为4.7）带正电荷的溶液pH值是",[["A","4"],["B","5"],["C","6"],["D","7"]],"A","当蛋白质溶液处于某一pH时，蛋白质解离成正、负离子的趋势相等，成为兼性离子，此时溶液的pH称为蛋白质的等电点（pI）。溶液的pH大于某一蛋白质的等电点时，该蛋白质解离出氢离子而带负电荷；反之，溶液的pH小于某一蛋白质的等电点时，该蛋白质结合氢离子而带正电荷。因此，使pI为4.7的蛋白质带正电荷的pH值应小于4.7，即pH值为4.0（A对）时，血清白蛋白带正电荷。","","N"],["2015-N26",2,"第3节 RNA和空间结构与功能","非编码RNA的功能",2015,26,"A","","能使外源性侵入基因表达的mRNA降解的核酸是",[["A","snRNA"],["B","hnRNA"],["C","siRNA"],["D","scRNA"]],"C","能使外源性侵入基因表达的mRNA降解的核酸是siRNA（小干扰RNA）（C对）。snRNA（核小RNA）主要参与hnRNA的剪接和转运（十版生物化学P70）（A错）。hnRNA（不均一核RNA、杂化核RNA）为mRNA前体，经加工修饰（十版生物化学P65）可变成mRNA（B错）。scRNA（胞质小RNA）是信号肽识别体的组成部分，参与信号转导（十版生物化学P70）（D错）。","","N"],["2015-N27",1,"第3节 酶促反应动力学","非竞争性抑制",2015,27,"A","","酶促动力学特点为表观Km值不变， Ⅴmax降低，其抑制作用属于",[["A","竞争性抑制"],["B","非竞争性抑制"],["C","反竞争性抑制"],["D","不可逆抑制"]],"B","可逆性抑制剂对酶的抑制作用可以分为三种：竞争性抑制、非竞争性抑制和反竞争性抑制。竞争性抑制时Km值增大，Vmax不变，非竞争性抑制时（B对）Km不变，Vmax变小，反竞争性抑制时Km值和Vmax均变小。","","N"],["2015-N28",4,"第3节 糖的有氧氧化","丙酮酸氧化脱羧",2015,28,"A","","下列维生素中，其衍生物参与形成丙酮酸脱氢酶复合体的是",[["A","磷酸吡哆醛"],["B","生物素"],["C","叶酸"],["D","泛酸"]],"D","丙酮酸脱氢酶复合体的辅酶有焦磷酸硫胺素（TPP），硫辛酸，FAD，NAD⁺和CoA（泛酸）（D对），可记忆为赴美（辅酶A）交流（TPP，焦磷酸硫胺素）时留心（硫辛酸）谎（FAD，黄素腺嘌呤二核苷酸）言（NAD⁺，烟酰胺腺嘌呤二核苷酸）（亦可记忆为SPA，即名称中带有S、P、A字母的，注：硫的化学符号为S）。磷酸吡哆醛（十版生物化学P100）（A错）是体内百余种酶的辅酶，参与氨基酸脱氨与转氨作用、鸟氨酸循环、血红素的合成和糖原分解等。生物素（十版生物化学P99）（B错）又称为维生素H、维生素B₇、辅酶R等，是多种羧化酶的辅基，参与二氧化碳的羧化。叶酸（四氢叶酸）（十版生物化学P101）参与一碳单位的转运（C错）。","","N"],["2015-N29",4,"第4节 戊糖磷酸途径","戊糖磷酸途径的意义",2015,29,"A","","体内提供NADPH的主要代谢途径是",[["A","糖酵解途径"],["B","磷酸戊糖途径"],["C","糖的有氧氧化"],["D","糖异生"]],"B","磷酸戊糖途径是体内不产能的代谢途径，它总的反应为：3×葡糖-6-磷酸+6NADP⁺→2×果糖-6-磷酸+3-磷酸甘油醛+6NADPH+6H⁺+3CO₂，其主要意义是生成NADPH（B对）和磷酸核糖。除磷酸戊糖途径外，柠檬酸-丙酮酸循环也可以产生少量NADPH（十版生物化学P151）。糖酵解途径（A错）和糖的有氧氧化（C错）代谢产生的是NADH+H⁺。糖异生（十版生物化学P130）为合成代谢，不但不提供NADPH，反而要消耗NADH+H⁺（D错）。","","N"],["2015-N30",5,"第4节 磷脂代谢","甘油二酯合成途径",2015,30,"A","","下列磷脂中，合成代谢过程需进行甲基化的是",[["A","磷脂酰乙醇胺"],["B","磷脂酰胆碱"],["C","磷脂酰丝氨酸"],["D","磷脂酸"]],"B","各种甘油磷脂的合成过程：磷脂酰乙醇胺（A错）—丝氨酸脱羧变成乙醇胺，乙醇胺活化为CDP-乙醇胺，后者与甘油二酯缩合，生成磷脂酰乙醇胺；磷脂酰胆碱（B对）—丝氨酸脱羧变成乙醇胺，乙醇胺从S-腺苷甲硫氨酸获得3个甲基生成胆碱，胆碱活化为CDP-胆碱，后者与甘油二酯缩合生成磷脂酰胆碱。磷脂酰丝氨酸（丝氨酸磷脂）（C错）—丝氨酸与CDP-甘油二酯结合生成磷脂酰丝氨酸。磷脂酸（十版生物化学P155）（D错）是由3-磷酸甘油酯酰化而来，合成过程中无需甲基化。","","N"],["2015-N31",5,"第6节 血浆脂蛋白及其代谢","低密度脂蛋白的功能和代谢途径",2015,31,"A","","可被巨噬细胞和血管内皮细胞吞噬和清除的脂蛋白是",[["A","LDL"],["B","VLDL"],["C","CM"],["D","HDL"]],"A","不同来源的脂蛋白具有不同的代谢途径。正常人血浆LDL（低密度脂蛋白），每天约45%被清除，其中2/3经LDL受体途径，1/3经单核-吞噬细胞系统（单核-吞噬细胞系统包含巨噬细胞和血管内皮细胞，清除的是氧化修饰过的LDL）（A对）。VLDL（极低密度脂蛋白）（B错）和CM（乳糜微粒）（C错）均可被脂蛋白脂肪酶LPL降解（降解各自运载的甘油三酯）。HDL（高密度脂蛋白）（D错）可被肝细胞清除。","","N"],["2015-N32",7,"第4节 氧化磷酸化的影响因素","呼吸链抑制剂阻断电子传递过程",2015,32,"A","","氧化磷酸化抑制剂鱼藤酮存在时，1分子琥珀酸经呼吸链传递生成的ATP数是",[["A","0"],["B","1"],["C","1.5"],["D","2.5"]],"C","（1）氧化呼吸链电子传递有两条途径：①NADH→复合体Ⅰ→CoQ→复合体Ⅲ→Cyt c→复合体Ⅳ→O₂；②琥珀酸→复合体Ⅱ→CoQ→复合体Ⅲ→Cyt c→复合体Ⅳ→O₂。（2）氧化呼吸链的抑制剂有四种：①复合体Ⅰ抑制剂：鱼藤酮、粉蝶霉素A、异戊巴比妥（可记忆为一群动物：鱼、蝶、蚁，或可记忆为一条粉红色的鱼尾巴）；②复合体Ⅱ抑制剂：萎锈灵（可记忆为二位伟人）；③复合体Ⅲ抑制剂：抗霉素A、黏噻唑菌醇（可记忆为三年抗战）；④复合体Ⅳ抑制剂：CN⁻、N³⁻、CO（可记忆为都是化学式）。（3）一对电子经NADH氧化呼吸链传递可生成2.5分子的ATP，经琥珀酸氧化呼吸链传递可生成1.5分子的ATP。（4）1分子琥珀酸脱氢生成的FADH₂，经复合体Ⅱ进入琥珀酸氧化呼吸链，不需要复合体Ⅰ参与，而鱼藤酮是复合体Ⅰ的抑制剂，因此其生成的ATP仍是1.5个（C对）。","","N"],["2015-N33",6,"第3节 氨的代谢","鸟氨酸循环过程",2015,33,"A","","在尿素生成过程中，直接提供氨基的氨基酸是",[["A","天冬氨酸"],["B","谷氨酸"],["C","精氨酸"],["D","鸟氨酸"]],"A","尿素的分子式为H₂N-CO-NH₂，尿素分子中第一个氮原子（氨基）来源于NH₃，第二个氮原子（氨基）来源于天冬氨酸（A对）。鸟氨酸循环的大致步骤：①NH₃（第一个氨基来源）、CO₂和ATP缩合成氨基甲酰磷酸；②氨基甲酰磷酸与鸟氨酸反应生成瓜氨酸；③瓜氨酸与天冬氨酸（第二个氨基来源）反应生成精氨酸代琥珀酸；④精氨酸代琥珀酸裂解生成精氨酸与延胡索酸，反应产物精氨酸中保留了来自游离NH₃和天冬氨酸分子中的氮；⑤精氨酸水解释放尿素并生成鸟氨酸，鸟氨酸再次进入线粒体参与合成瓜氨酸，如此反复，进行鸟氨酸循环。","","N"],["2015-N34",8,"第2节 嘌呤核苷酸的合成与分解代谢","IMP的合成",2015,34,"A","","嘌呤核苷酸从头合成时首先生成的核苷酸中间产物是",[["A","UMP"],["B","GMP"],["C","AMP"],["D","IMP"]],"D","嘌呤核苷酸从头合成途径是指：利用磷酸核糖、氨基酸、一碳单位及CO₂等简单物质为原料，经过一系列酶促反应，合成嘌呤核苷酸的过程。其反应步骤可分为两个阶段：首先合成次黄嘌呤核苷酸（IMP）（D对），然后IMP再转变成腺嘌呤核苷酸（AMP）（C错）与鸟嘌呤核苷酸（GMP）（B错）。UMP（尿嘧啶核苷酸）属于嘧啶核苷酸，与嘌呤核苷酸的合成无关（A错）。","","N"],["2015-N35",11,"第2节 DNA复制的酶学和拓扑学","DNA聚合酶的校读功能",2015,35,"A","","参与维持DNA复制保真性的因素是",[["A","密码的简并性"],["B","DNA的SOS 修复"],["C","DNA聚合酶的核酸外切酶活性"],["D","氨基酰tRNA合成酶对氨基酸的高度特异性"]],"C","DNA复制的保真性是遗传信息稳定传代的保证，它主要是依靠DNA聚合酶来实现的。DNA聚合酶主要通过正确的碱基选择和即时的校对来实现DNA复制的保真性。原核生物的DNApol Ⅰ、真核生物的DNApolδ和DNApolε都有3’→5’核酸外切酶活性，可以在复制过程中辨认并切除错配的碱基，对复制错误进行校正（C对）。密码的简并性（十版生物化学P298）是指一个氨基酸可以由多个密码子编码的现象，它有助于降低基因表达过程中基因突变的生物学效应，与DNA复制无关（A错）。SOS修复（十版生物化学P413）是DNA双链发生大片段、高频率的损伤时由DNA 聚合酶 Ⅳ 或 Ⅴ所介导的修复，因这两种酶特异性低，识别碱基精确度差，一般无校对功能，所以这种合成的出错率大大增加，不利于DNA保真性（B），但十版生物化认为：SOS等修复系统与碱基互补配对原则、延长过程中的碱基选择、复制叉等机制协同提高了复制的保真性，因此B选项存在争议。氨基酰tRNA合成酶对氨基酸的高度特异性是正确合成蛋白质的基础，与DNA复制无关（D错）。","","N"],["2015-N36",12,"第2节 原核生物的转录","RNA聚合酶识别模板的特殊碱基序列",2015,36,"A","","原核生物转录起始点上游-10区的一致性序列是",[["A","Pribnow盒"],["B","GC盒"],["C","UAA"],["D","TTATTT"]],"A","原核生物转录起始点上游-10区的一致性序列是TATAAT（D错），又称Pribnow盒（A对），RNA聚合酶通过辨认并稳定结合在此区，解开双链DNA，进行转录。GC盒（B错）、CAAT盒是真核生物的启动子上游元件（十版生物化学P280）。UAA（C错）、UAG、UGA是翻译过程终止的信号（十版生物化学P297），称终止密码子。","","N"],["2015-N37",18,"第1节 DNA损伤","DNA损伤的类型",2015,37,"A","","镰刀形红细胞贫血患者血红蛋白β基因链上CTC转变成CAC，这种突变是",[["A","移码突变"],["B","错义突变"],["C","无义突变"],["D","同义突变"]],"B","镰刀形红细胞贫血患者血红蛋白β基因模板链上的CTC发生点突变（碱基置换），突变成CAC（编码链或mRNA上则为GAG突变成GUG），导致其编码的谷氨酸变成缬氨酸，因此这种点突变属于改变氨基酸编码的错义突变（B对）。导致氨基酸编码变成终止密码子的点突变称为无义突变（C错）。不改变氨基酸编码的点突变称为同义突变（D错）。移码突变（十版生物化学P297）（A错）由碱基的插入或缺失引起。","","N"],["2015-N38",14,"第2节 原核基因表达调控","乳糖操纵子的双重调节",2015,38,"A","","原核生物乳糖操纵子受CAP调节，结合并活化 CAP 的分子是",[["A","阻遏蛋白"],["B","RNA聚合酶"],["C","cAMP"],["D","cGMP"]],"C","原核生物乳糖操纵子受阻遏蛋白（负性调节）和CAP（分解代谢物激活蛋白）（正性调节）的双重调节。CAP正性调节乳糖操纵子的机制如下：当培养基中缺乏葡萄糖时，cAMP浓度增高，cAMP（C对D错）进而结合并活化CAP，促进CAP与CAP位点结合，刺激乳糖操纵子RNA的转录活性。阻遏蛋白（A错）由调节基因I编码，结合操纵序列（操纵元件）。RNA聚合酶（B错）结合启动子，启动基因转录。","","N"],["2015-N39",17,"第2节 细胞内信号转导分子","G蛋白的作用",2015,39,"A","","下列蛋白质中，属于小G蛋白的是",[["A","异三聚体G蛋白"],["B","Grb2"],["C","MAPK"],["D","Ras"]],"D","Ras蛋白与异三聚体G蛋白一样具有鸟核苷酸的结合位点和GTP酶活性，但该蛋白只有一条多肽链，分子量为21kDa，小于异三聚体G蛋白，因此也称为低分子量G蛋白或小G蛋白（D对A错）。Ras蛋白是受体型PTK-Ras-MAPK途径中的信号分子，Grb2（B错）是该途径中位于Ras蛋白上游的信号分子，MAPK（C错）是该途径中位于Ras蛋白下游的信号分子。","","N"],["2015-N40",5,"第5节 胆固醇代谢","胆固醇的转化",2015,40,"A","","胆固醇在体内的主要代谢去路是",[["A","合成初级胆汁酸"],["B","直接排出体外"],["C","转化为类固醇激素"],["D","转化为维生素D₃的前体"]],"A","在肝内转化为初级胆汁酸（A对）是胆固醇的主要去路。转化为类固醇激素（C错）及转化为维生素D₃的前体（D错）均为胆固醇的代谢去路，但非主要去路。胆固醇是脂溶性的，因此不能通过汗液和尿液等直接排出体外（B错）。","","N"],["2015-N127",7,"第3节 氧化磷酸化与ATP的生成","氧化磷酸化耦联部位的概述",2015,127,"B","","在呼吸链中氧化磷酸化偶联位点",[["A","复合体 Ⅱ"],["B","复合体 Ⅲ"],["C","FAD"],["D","Cytc"]],"B","氧化磷酸化是指由代谢物脱下的氢，经线粒体氧化呼吸链电子传递释放能量的过程，此释能过程与驱动ADP磷酸化生成ATP相偶联。氧化磷酸化偶联位点是指理论推测的呼吸链中偶联生成ATP的部位，根据相关实验方法及数据可以确定（具体推导过程详见P128-P129）氧化磷酸化偶联位点分别位于复合体Ⅰ（NADH→泛醌）、复合体Ⅲ（泛醌→Cyt c）（B对）和复合体Ⅳ（Cyt c→O₂）。","","N"],["2015-N128",7,"第2节 线粒体氧化体系与呼吸链","细胞色素蛋白",2015,128,"B","","呼吸链中仅作为递电子体的是",[["A","复合体 Ⅱ"],["B","复合体 Ⅲ"],["C","FAD"],["D","Cyt c"]],"D","呼吸链又称氧化呼吸链，其主要功能是通过具有电子传递功能的复合体（复合体Ⅰ、Ⅱ、Ⅲ和Ⅳ）传递电子，最终使氢质子与氧结合生成水，同时释放出能量供给机体生命活动所需。传递电子的复合体由各种酶蛋白或辅助因子组成，这些酶蛋白或辅助因子中，有的既递电子又递氢，称为递氢体，有的仅递电子，称为递电子体。呼吸链中的递氢体的包括NAD⁺、NADP⁺、FAD（C错）、辅酶Q和FMN等，递电子体包括铁硫蛋白和细胞色素（Cyt）（D对）。复合体Ⅱ（A错）和复合体Ⅲ（B错）是由各种递氢体和递电子体组成的复合体。","","N"],["2015-N129",6,"第3节 氨的代谢","精氨酸代琥珀酸合成酶",2015,129,"B","","鸟氨酸循环启动后的限速酶是",[["A","精氨酸代琥珀酸合成酶"],["B","精氨酸代琥珀酸裂解酶"],["C","腺苷酸代琥珀酸合成酶"],["D","IMP脱氢酶"]],"A","鸟氨酸循环，又称为尿素循环，是体内氨代谢的主要去路。鸟氨酸循环受两种限速酶的调节。氨基甲酰磷酸合成酶Ⅰ是鸟氨酸循环启动的限速酶，它催化NH₃和CO₂生成氨基甲酰磷酸。精氨酸代琥珀酸合成酶（A对）是尿素合成启动后的限速酶，它催化瓜氨酸与天冬氨酸生成精氨酸代琥珀酸。精氨酸代琥珀酸裂解酶（十版生物化学P183）（B错）为鸟氨酸循环的非限速酶。腺苷酸代琥珀酸合成酶（十版生物化学P249）（C错）为IMP（次黄嘌呤核苷酸）转化为AMP（腺嘌呤核苷酸）所需要的酶。IMP脱氢酶（十版生物化学P249）（D错）为IMP转化为GMP（鸟嘌呤核苷酸）所需要的酶。","","N"],["2015-N130",8,"第2节 嘌呤核苷酸的合成与分解代谢","IMP转变为AMP和GMP",2015,130,"B","","参与嘌呤核苷酸循环脱氨基机制的酶是",[["A","精氨酸代琥珀酸合成酶"],["B","精氨酸代琥珀酸裂解酶"],["C","腺苷酸代琥珀酸合成酶"],["D","IMP 脱氢酶"]],"C","嘌呤核苷酸循环是心肌和骨骼肌中脱去氨基主要方式。嘌呤核苷酸循环的主要过程为：L-谷氨酸通过转氨基作用将氨基转移给草酰乙酸，生成天冬氨酸，天冬氨酸与IMP反应生成腺苷酸代琥珀酸（此反应由腺苷酸代琥珀酸合成酶催化）（C对），后者裂解释放延胡索酸并生成AMP。AMP在腺苷酸脱氨酶的催化下脱去氨基生成IMP，IMP再次与天冬氨酸结合进入下一轮循环，完成氨基酸的脱氨基作用。精氨酸代琥珀酸合成酶（十版生物化学P183）（A错）、精氨酸代琥珀酸裂解酶（十版生物化学P183）（B错）均为参与尿素循环的酶。IMP脱氢酶（十版生物化学P218）（D错）为参与IMP向GMP转化的酶。","","N"],["2015-N131",5,"第3节 甘油三酯代谢","酮体的氧化利用",2015,131,"B","","参与酮体分解的酶",[["A","HMG-CoA合酶"],["B","HMG-CoA还原酶"],["C","乙酰乙酸硫激酶"],["D","乙酰CoA羧化酶"]],"C","酮体包括乙酰乙酸、β-羟丁酸和丙酮。丙酮生成量很少，可经肺呼出，β-羟丁酸可以转变成乙酰乙酸，乙酰乙酸则可在肝外组织被氧化利用：乙酰乙酸在肝外组织的利用要先活化为乙酰乙酰CoA，它的活化有两条途径，在心、肾、脑及骨骼肌线粒体，由琥珀酰CoA转硫酶催化生成乙酰乙酰CoA，在肾、心和脑线粒体，由乙酰乙酸硫激酶（C对）催化直接活化生成乙酰乙酰CoA。活化后的乙酰乙酰CoA在乙酰乙酰CoA硫解酶催化下生成乙酰CoA，后者可进入三羧酸循环氧化分解为机体提供能量。HMG-CoA合酶（A错）为参与酮体合成（十版生物化学P149）及胆固醇合成（十版生物化学P159）的酶。HMG-CoA还原酶（十版生物化学P159）（B错）为参与胆固醇合成的酶（关键酶）。乙酰CoA羧化酶（十版生物化学P152）（D错）为参与脂肪酸合成的酶（关键酶）。","","N"],["2015-N132",5,"第5节 胆固醇代谢","胆固醇的合成过程",2015,132,"B","","胆固醇合成的关键酶是",[["A","HMG-CoA合酶"],["B","HMG-CoA还原酶"],["C","乙酰乙酸硫激酶"],["D","乙酰 CoA羧化酶"]],"B","胆固醇合成的关键酶是HMG-CoA还原酶（B对）。HMG-CoA合酶（A错）为胆固醇合成（十版生物化学P159）和酮体合成（十版生物化学P149）的非关键酶。乙酰乙酸硫激酶（十版生物化学P149） （C错）为参与酮体氧化分解的酶。乙酰CoA羧化酶（十版生物化学P152）（D错）为脂肪酸合成的关键酶。","","N"],["2015-N157",5,"第3节 甘油三酯代谢","脂肪酸的分解过程",2015,157,"X","","参与脂肪酸β-氧化的酶有",[["A","肉碱脂酰转移酶Ⅰ"],["B","肉碱脂酰转移酶Ⅱ"],["C","脂酰 CoA脱氢酶"],["D","乙酰乙酸 CoA硫激酶"]],"ABC","肉碱脂酰转移酶Ⅰ（关键酶）（A对）、肉碱脂酰转移酶Ⅱ（B对）、脂酰CoA脱氢酶（C对）均为参加脂肪酸β-氧化的酶。乙酰乙酸 CoA 硫激酶应为乙酰乙酸硫激酶（体内无乙酰乙酸 CoA 硫激酶），乙酰乙酸硫激酶（D 错）可将乙酰乙酸（酮体）直接活化成乙酰乙酰CoA，乙酰乙酰CoA再经乙酰乙酰 CoA 硫解酶催化，转变成乙酰 CoA 被氧化，故乙酰乙酸硫激酶与酮体的氧化利用有关，而与 β- 氧化无关。","","N"],["2015-N158",14,"第3节 真核基因表达调控","小分子RNA对基因表达的调节",2015,158,"X","","能参与切割mRNA的生物分子包括",[["A","miRNA"],["B","siRNA"],["C","5.8S rRNA"],["D","tRNA"]],"AB","miRNA（microRNA）中译名微RNA（十版生物化学P70），siRNA（small interfering RNA）中译名小干扰RNA（十版生物化学P70），二者均属于真核生物的非编码小分子RNA，它们具有一些共同的特点：均由一种名为Dicer的特异性核酸内切酶切割产生；长度均在22个碱基左右；均与一种名为RISC（RNA诱导的沉默复合体）的复合体结合，通过碱基互补配对的方式识别靶mRNA，最终利用RISC切割降解靶mRNA（AB对），阻断翻译过程。miRNA和siRNA参与切割降解mRNA的详细过程见二版八年制生物化学P432 图21-13。5.8S rRNA为真核生物核糖体（蛋白质合成的场所）大亚基的rRNA组分之一（十版生物化学P69），tRNA为蛋白质合成过程中氨基酸的转运载体（十版生物化学P67），二者均不参与切割mRNA的过程（CD错）。","","N"],["2015-N159",17,"第3节 细胞受体介导的细胞内信号转导","cAMP-PKA通路",2015,159,"X","","参与GPCR通路的分子有",[["A","G蛋白"],["B","cAMP"],["C","FAD"],["D","AC"]],"ABD","GPCR即G蛋白偶联受体（G protein-coupled receptor）（十版生物化学P394），GPCR通路即G蛋白偶联受体介导的信号转导通路（十版生物化学P395）。GPCR通路包括受体-G蛋白-AC-cAMP-PKA通路（ABD对）、受体-G蛋白-PLC-IP₃/DAG-PKC通路、Ca²⁺/钙调蛋白依赖的蛋白激酶通路等不同类型。FAD（十版生物化学P56）即黄素腺嘌呤二核苷酸，是体内氧化还原酶（如脂酰CoA脱氢酶、琥珀酸脱氢酶）的辅基，主要起递氢体的作用，与信号转导通路无关。","","N"],["2015-N160",22,"第3节 血细胞物质代谢","成熟红细胞代谢特点的概述",2015,160,"X","","下列符合红细胞物质代谢特点的有",[["A","葡萄糖可经 2，3 -二磷酸甘油酸旁路代谢"],["B","葡萄糖可经磷酸戊糖途径代谢"],["C","可进行脂肪酸β-氧化"],["D","可从头合成脂肪酸"]],"AB","成熟红细胞无线粒体，而脂肪酸β-氧化（C错）及从头合成脂肪酸（D错）的某些步骤需要在线粒体中进行，因此这些反应在成熟红细胞内无法完成。2，3-二磷酸甘油酸旁路（糖酵解的侧支循环）（A对）、磷酸戊糖途径（B对）均在胞液中进行，可见于成熟的红细胞。","","N"],["2015-N161",19,"第2节 癌基因","生长因子的分类及作用机制",2015,161,"X","","编码的产物属于生长因子受体的癌基因有",[["A","ERB-B"],["B","HER-2"],["C","SIS"],["D","JUN"]],"AB","癌基因又称细胞癌基因或原癌基因（十版生物化学P435）。癌基因是基因组内正常存在的基因，其编码产物通常作为正调控信号促进细胞的增殖和生长，包括生长因子、生长因子受体、信号转导蛋白、细胞周期蛋白、转录因子等。ERB-B（A对）是一个编码生长因子受体的基因家族的名称，ERB-B家族包括ERB-B1（又称EGFR或HER-1）、ERB-B2（又称HER-2，详见2012N49A）（B对）、ERB-B3（HER-3）、ERB-B4（HER-4）四个家族成员。SIS基因编码的产物属于生长因子（C错）。JUN基因编码产物属于转录因子（D错）。","","N"],["2015-N162",21,"第4节 胆色素的代谢与黄疸","胆色素代谢的概述",2015,162,"X","","人体内的胆色素包括",[["A","胆绿素"],["B","胆红素"],["C","胆素原"],["D","胆素"]],"ABCD","胆色素是体内铁卟琳类化合物的主要分解代谢产物，人体内的胆色素包括胆绿素（A对）、胆红素（B对）、胆素原（C对）和胆素（D对）。其中胆红素位于胆色素代谢的中心，是人体胆汁的主要色素。胆绿素是胆红素合成过程中的中间产物。胆素原是结合胆红素在肠道细菌作用下还原生成的，包括d-尿胆素原、中胆素原和粪胆素原。胆素是胆素原接触空气后被氧化而成的，包括d-尿胆素、i-尿胆素和粪胆素。","","N"],["2016-N25",0,"第2节 蛋白质的分子结构","结构模体",2016,25,"A","","“α-螺旋-β-转角-α-螺旋”属于的蛋白质结构是",[["A","一级结构"],["B","三级结构"],["C","模体"],["D","结构域"]],"C","α- 螺旋 -β- 转角 -α-螺旋为典型的模体结构（C对）。模体是蛋白质分子中具有特定空间构象和特定功能的结构成分，一个模体总有其特征性的氨基酸序列，并发挥特殊的功能。一般而言，常见的模体结构可以有以下几种形式： α-螺旋-β-转角（或环） -α-螺旋模体（见于多种DNA 结合蛋白） ； 链－β转角－链（见于反平行β-折叠的蛋白质）；链-β-转角-α-螺旋-β-转角－链模体（见于多种α-螺旋/β-折叠蛋白质）。值得注意的是α- 螺旋 -β- 转角 -α-螺旋在九、十版教材是放在三级结构下讲解的，但它并不属于三级结构，而是属于一种介于二级结构和三级结构之间的结构形式，这种结构形式被称为超二级结构。","","N"],["2016-N26",2,"第2节 DNA和空间结构与功能","DNA的双螺旋结构",2016,26,"A","","下列关于DNA双螺旋结构，错误的是",[["A","碱基平面与螺旋轴相垂直"],["B","碱基配对发生在嘧啶与嘌呤之间"],["C","疏水作用力和氢键维持结构的稳定"],["D","脱氧核糖和磷酸在内侧"]],"D","脱氧核糖和磷酸基团构成的亲水性骨架位于双螺旋结构的外侧，而疏水的碱基位于内侧（D错，为本题正确答案）。一条链上的腺嘌呤与另一条链上的胸腺嘧啶形成了两个氢键，一条链上的鸟嘌呤与另一条链上的胞嘧啶形成了三个氢键，这种发生在嘧啶与嘌呤之间的碱基配对（B对）是DNA双螺旋结构的基础。碱基对平面与双螺旋结构的螺旋轴垂直（A对）。相邻的两个碱基对平面在旋进过程中会彼此重叠由此产生了疏水性的碱基堆积力，这种碱基堆积力和互补链之间碱基对的氢键共同维系着DNA双螺旋结构的稳定（C对）。","","N"],["2016-N27",2,"第3节 RNA和空间结构与功能","tRNA的结构及功能",2016,27,"A","","如果tRNA的反密码子为GAU，其识别的密码子是",[["A","AUC"],["B","CUA"],["C","CAU"],["D","AAG"]],"A","tRNA反密码子与mRNA密码子碱基互补配对方式为A-U和G-C，DNA、RNA书写原则均为5＇端到3＇端，tRNA的反密码子为5＇GAU3＇时，其识别的密码子为3＇CUA5＇，即5＇AUC3＇（A对）。","","N"],["2016-N28",3,"第2节 水溶性维生素","叶酸",2016,28,"A","","下列辅酶中，不参与递氢的是",[["A","NAD⁺"],["B","FAD"],["C","FH₄"],["D","CoQ"]],"C","氧化呼吸链中，传递氢的酶蛋白或辅助因子称之为递氢体，传递电子的则称之为电子传递体，递氢体包括NAD（A对）、NADP、FAD（B对）、FMN、CoQ（D对）等。FH₄（四氢叶酸）为一碳单位的载体（十版生物化学P187），参与嘌呤、嘧啶的合成过程（十版生物化学P188）（C错，为本题正确答案）。","","N"],["2016-N29",4,"第3节 糖的有氧氧化","各组织的糖氧化产能方式",2016,29,"A","","糖代谢中“巴斯德效应”结果是",[["A","乳酸生成增加"],["B","三羧酸循环减慢"],["C","糖原生成增加"],["D","糖酵解受到抑制"]],"D","巴斯德效应是指有氧氧化抑制无氧氧化（糖酵解）的现象（D对）。巴斯德效应的机制：无氧条件下，糖酵解过程产生的NADH+H⁺留在胞质将丙酮酸还原成乳酸；有氧条件下，NADH+H⁺可进入线粒体内氧化，丙酮酸进入有氧氧化途径被彻底分解成CO₂和H₂O，此时胞质中的糖无氧氧化途径受到抑制。需要解释的是，在七版及更早版本教材中，糖酵解在概念上等同于无氧氧化，即糖酵解是指葡萄糖转化成丙酮酸进而还原生成乳酸的过程，而由葡萄糖转化生成丙酮酸的过程被称为糖酵解途径，糖酵解包括糖酵解途径和乳酸生成两个阶段。从八版教材开始，糖酵解的概念有所变化，仅指由葡萄糖转化生成丙酮酸的过程（原糖酵解途径），重新定义后的“糖酵解”成为葡萄糖无氧氧化和有氧氧化的共同起始途径。故按新版教材的概念，D选项“糖酵解受到抑制”应改为“无氧氧化受到抑制”。","","N"],["2016-N30",4,"第6节 糖异生","第一个底物循环",2016,30,"A","","胰高血糖素促进糖异生的机制是",[["A","抑制6-磷酸果糖激酶-2的活性"],["B","激活6-磷酸果糖激酶-1"],["C","激活丙酮酸激酶"],["D","抑制磷酸烯醇式丙酮酸羧激酶的合成"]],"A","胰高血糖素促进糖异生的机制包括：①抑制6-磷酸果糖激酶-2的活性（A对），降低肝细胞内果糖-2，6-二磷酸水平；②抑制6-磷酸果糖激酶-1的活性（B错），降低肝细胞内果糖-1，6-二磷酸水平；③抑制丙酮酸激酶（C错）；④诱导磷酸烯醇式丙酮酸羧激酶的合成（D错）。","","N"],["2016-N31",5,"第3节 甘油三酯代谢","脂肪酰CoA进入线粒体",2016,31,"A","","脂肪酸β-氧化的限速酶是",[["A","肉碱脂酰转移酶Ⅰ"],["B","肉碱-脂酰肉碱转位酶"],["C","肉碱脂酰转移酶Ⅱ"],["D","脂酰CoA脱氢酶"]],"A","脂酰CoA进入线粒体是脂肪酸β-氧化的限速步骤，而脂酰CoA进入线粒体需要肉碱脂酰转移酶Ⅰ的作用，因此肉碱脂酰转移酶Ⅰ（A对）是脂肪酸β-氧化的关键酶。","","N"],["2016-N32",7,"第2节 线粒体氧化体系与呼吸链","苹果酸-天冬氨酸穿梭",2016,32,"A","","直接参与苹果酸-天冬氨酸穿梭的重要中间产物",[["A","草酰乙酸"],["B","丙酮酸"],["C","磷酸二羟丙酮"],["D","磷酸甘油"]],"A","苹果酸-天冬氨酸穿梭介导胞质内NADH+H⁺向线粒体内转运，其转运过程需要草酰乙酸（A对）的参与：胞质内的NADH+H⁺将草酰乙酸还原成苹果酸，苹果酸可自由通过线粒体内膜，进入线粒体后，苹果酸再转变成草酰乙酸，生成NADH+H⁺。磷酸二羟丙酮（C错）、α-磷酸甘油（D错）是α-磷酸甘油穿梭的中间产物。丙酮酸（B错）是丙酮酸-柠檬酸穿梭（丙酮酸-柠檬酸循环）（十版生物化学P151）的中间产物。","","N"],["2016-N33",6,"第3节 氨的代谢","氨基甲酰磷酸合成酶Ⅰ",2016,33,"A","","AGA是尿素合成限速酶的激活剂。可以通过促进AGA合成而加快尿素合成的氨基酸是",[["A","瓜氨酸"],["B","鸟氨酸"],["C","精氨酸"],["D","谷氨酸"]],"C","AGA（N-乙酰谷氨酸）是尿素合成限速酶CPS-Ⅰ（氨基甲酰磷酸合成酶Ⅰ）的别构激活剂。精氨酸（C对）是AGA合成酶的激活剂，可以通过促进AGA合成而加快尿素合成。本题略有争议，谷氨酸（D）作为AGA的合成原料，理应也可促进AGA合成及加快尿素合成。","","N"],["2016-N34",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸合成的概述",2016,34,"A","","嘌呤核苷酸补救合成途径的底物是",[["A","甘氨酸"],["B","谷氨酰胺"],["C","天冬氨酸"],["D","腺嘌呤"]],"D","细胞可利用现成的嘌呤碱（D对）作为底物合成嘌呤核苷酸，这是嘌呤核苷酸补救合成的途径之一。甘氨酸（A错）、谷氨酰胺（B错）及天冬氨酸（C错）均为嘌呤核苷酸从头合成途径的底物。","","N"],["2016-N35",11,"第2节 DNA复制的酶学和拓扑学","DNA拓扑异构酶改变DNA超螺旋状态",2016,35,"A","","在DNA复制过程中，拓扑异构酶的作用是",[["A","辨认起始点"],["B","催化RNA引物合成"],["C","解开DNA双链"],["D","松弛DNA链"]],"D","在DNA复制过程中，拓扑异构酶的作用是松弛DNA链（D对），改变DNA的超螺旋状态。辨认起始点（A错）的是DnaA（记忆技巧：A为起始字母）。催化 RNA 引物合成（B错）的是DnaG蛋白（又称引物酶）（记忆技巧：Guide<引导>）。解开DNA双链（C错）的是DnaB蛋白（又称解螺旋酶）（记忆技巧：掰<Bai>开双链，另B字母本身为螺旋状）。","","N"],["2016-N36",0,"第3节 蛋白质结构与功能的关系","蛋白质一级结构是高级结构与功能的基础",2016,36,"A","","在下列DNA突变中，可能仅改变一个氨基酸的是",[["A","缺失"],["B","插入"],["C","点突变"],["D","重排"]],"C","点突变（C对）是指DNA分子上的碱基错配，若发生在基因的编码区，可导致某一个氨基酸的改变，如镰刀形红细胞贫血患者血红蛋白β基因第6位密码子发生点突变，CTC→CAC（mRNA上的密码子GAG→GUG），导致其编码的氨基酸由谷氨酸变成缬氨酸。缺失（A错）和插入（B错）均导致框移突变，造成氨基酸序列整体发生改变。重排（D错）指DNA分子较大片段的交换，亦导致氨基酸序列整体发生改变。","","N"],["2016-N37",12,"第2节 原核生物的转录","依赖ρ因子的转录终止",2016,37,"A","","在原核生物转录中，ρ因子的作用是",[["A","辨认起始点"],["B","终止转录"],["C","参与转录全过程"],["D","决定基因转录的特异性"]],"B","原核生物的mRNA转录终止分为依赖ρ（Rho）因子与非依赖ρ因子两大类，在依赖ρ因子的转录终止中，ρ因子可以识别产物RNA富含C碱基且较有规律的终止信号，并与之结合使RNA聚合酶发生构象改变，导致RNA聚合酶停顿，终止转录（B对）。辨认原核生物转录起始点（A错）的是RNA聚合酶全酶（α 2 ββ′ωσ）的σ亚基（σ因子）（十版生物化学P276）。参与原核生物转录全过程（C错）的是RNA聚合酶的核心酶（α₂ββ′ω）（十版生物化学P276）。决定原核生物基因转录特异性（决定哪些基因被转录）（D错）的是RNA聚合酶核心酶的ɑ亚基（十版生物化学P274）。","","N"],["2016-N38",13,"第2节 蛋白质合成体系","遗传密码的特点",2016,38,"A","","下列密码子的特点中，与移码突变有关的是",[["A","通用性"],["B","简并性"],["C","连续性"],["D","摇摆性"]],"C","由于密码子的连续性（C对），在可读框（开放阅读框）中发生插入或缺失1个或2个碱基的基因突变，都会引起mRNA阅读框架发生移动，从而发生移码突变。通用性（A错）指从简单的病毒到高等动物的人类，几乎使用同一套遗传密码。简并性（B错）指有的氨基酸可由多个密码子编码。摇摆性（D错）指密码子与反密码子配对时，出现不严格遵守Watson-Crick碱基配对原则的现象。","","N"],["2016-N39",14,"第2节 原核基因表达调控","乳糖操纵子的双重调节",2016,39,"A","","在乳糖操纵子中，分解物基因激活蛋白结合的结构是",[["A","启动序列"],["B","操纵序列"],["C","编码序列"],["D","CAP结合序列"]],"D","在乳糖操纵子中，与分解代谢基因结合蛋白（CAP）结合的是CAP结合序列（D对）。启动序列（启动子）（A错）结合RNA聚合酶。操纵序列（操纵元件）（B错）结合阻遏蛋白。编码序列是可直接编码β-半乳糖苷酶（Z）、通透酶（Y）和乙酰基转移酶（A）的结构基因序列（十版生物化学P320）（C错）。","","N"],["2016-N40",3,"第2节 水溶性维生素","维生素PP",2016,40,"A","","构成脱氢酶辅酶的维生素是",[["A","维生素A"],["B","维生素K"],["C","维生素PP"],["D","维生素B₁₂"]],"C","维生素PP参与组成NAD⁺和NADP⁺，而NAD⁺和NADP⁺是多种脱氢酶的辅酶，所以维生素PP是构成脱氢酶辅酶的维生素（C对）。维生素A（A错）不构成任何酶的辅酶。维生素K（B错）为γ-羧化酶的辅酶（十版生物化学P96）。维生素B₁₂（D错）为甲硫氨酸合成酶的辅酶（十版生物化学P101）。","","N"],["2016-N127",5,"第3节 甘油三酯代谢","酮体的生成",2016,127,"B","","酮体合成重要中间产物",[["A","脂酰CoA"],["B","烯酰CoA"],["C","HMG-CoA"],["D","丙二酰CoA"]],"C","酮体的合成过程：2分子乙酰CoA在乙酰乙酰CoA硫解酶作用下，缩合成乙酰乙酰CoA，乙酰乙酰CoA再在HMG-CoA合酶作用下，与1分子乙酰CoA缩合成HMG-CoA（C对），最后，HMG-CoA在HMG-CoA裂解酶作用下被裂解生成酮体之一的乙酰乙酸。脂酰CoA（十版生物化学P146）（A错）是脂肪酸β-氧化前的活化形式。烯酰CoA（十版生物化学P147）B错）是脂肪酸β-氧化过程中的中间产物。丙二酰CoA（十版生物化学P152）（D错）是脂肪酸合成的中间产物。","","N"],["2016-N128",5,"第5节 胆固醇代谢","胆固醇的合成过程",2016,128,"B","","胆固醇合成重要中间产物",[["A","脂酰CoA"],["B","烯酰CoA"],["C","HMG-CoA"],["D","丙二酰CoA"]],"C","HMG-CoA（羟基甲基戊二酸单酰CoA）是胆固醇合成（十版生物化学P159）和酮体合成（十版生物化学P149）的共同中间产物（C对）。脂酰CoA（十版生物化学P147）为脂肪酸的活化形式，是脂肪酸β-氧化的中间产物（A错）。丙二酰CoA（十版生物化学P152）是脂肪酸合成的中间产物（D错）。烯（脂）酰CoA（十版生物化学P152）为脂肪酸β-氧化的中间产物（B错）。","","N"],["2016-N129",11,"第4节 真核生物DNA复制过程","端粒酶参与解决染色体末端复制",2016,129,"B","","参与端粒合成的酶是",[["A","限制性内切酶"],["B","RNA聚合酶"],["C","核酶"],["D","逆转录酶"]],"D","参与端粒合成的酶是由RNA和蛋白质组成的复合体，由模板RNA、协同蛋白和逆转录酶（D对）三部分组成。限制性内切酶（十版生物化学P369）（A错）能识别DNA分子内部的特异序列，准确切割DNA，是基因工程中提取目的基因常用的工具酶。RNA聚合酶（十版生物化学P274）（B错）能从头启动RNA链的合成，参与RNA的转录过程。核酶（十版生物化学P71）（C错）为具有催化活性的小分子RNA，能催化特定RNA降解，参与RNA的剪接修饰过程。","","N"],["2016-N130",15,"第2节 聚合酶链反应技术","逆转录PCR技术",2016,130,"B","","具有合成cDNA功能的酶",[["A","限制性内切酶"],["B","RNA聚合酶"],["C","核酶"],["D","逆转录酶"]],"D","cDNA（complementary DNA）的中文名称为互补DNA，其是以RNA为模板，利用逆转录酶（D对）合成的与RNA互补的DNA。限制性内切酶（十版生物化学P370）（A错）可识别特异序列，切割DNA，是重组DNA技术中来切割目的DNA与载体的工具酶。RNA聚合酶（十版生物化学P274）（B错）为催化内源性DNA转录的酶。核酶（十版生物化学P71）（C错）为具有自我剪切功能的小分子RNA。","","N"],["2016-N131",5,"第3节 甘油三酯代谢","软脂酸合成的原料",2016,131,"B","","参与脂肪酸合成代谢的途径是",[["A","乳酸循环"],["B","柠檬酸-丙酮酸循环"],["C","丙氨酸-葡萄糖循环"],["D","鸟氨酸循环"]],"B","在脂肪酸合成代谢过程中，用于脂肪酸合成的乙酰CoA主要由葡萄糖分解供给，在线粒体内产生，不能自由通过线粒体内膜，需要通过柠檬酸-丙酮酸循环（十版生物化学P151 图8-5 柠檬酸-丙酮酸循环）（B对）进入胞质。肌收缩（尤其是氧供应不足时）通过糖无氧氧化生成乳酸，乳酸透过细胞膜弥散进入血液后，再入肝异生为葡萄糖。葡萄糖释入血液后又可被肌摄取，由此构成了一个循环，称为乳酸循环（十版生物化学P132）。乳酸循环（A错）的意义在于利用乳酸，防止因乳酸堆积而引起酸中毒，与脂肪酸合成代谢无关。丙氨酸-葡萄糖循环（十版生物化学P181）（C错）介导骨骼肌与肝脏之间氨的转运，与脂肪酸合成代谢无关。鸟氨酸循环（十版生物化学P182）（D错）即尿素循环，为尿素合成过程。","","N"],["2016-N132",6,"第3节 氨的代谢","丙氨酸-葡萄糖循环",2016,132,"B","","参与血氨转运的代谢途径",[["A","乳酸循环"],["B","柠檬酸-丙酮酸循环"],["C","丙氨酸-葡萄糖循环"],["D","鸟氨酸循环"]],"C","氨是体内的有毒物质，各组织必须以无毒的形式通过血液将氨运输到肝脏代谢。氨可以通过丙氨酸-葡萄糖循环（C对）将氨转变为丙氨酸从骨骼肌运往肝，也可以通过谷氨酰胺从脑和骨骼肌运往肝或肾。乳酸循环（十版生物化学P132）（A错）参与骨骼肌中乳酸的转移和利用。柠檬酸-丙酮酸循环（十版生物化学P151）（B错）参与脂酸合成，作用是将乙酰CoA从线粒体运送到胞质。鸟氨酸循环（十版生物化学P182）（D错）又称尿素循环，参与尿素的生成。","","N"],["2016-N157",12,"第3节 真核生物mRNA的转录、加工和降解","脱腺苷酸化",2016,157,"X","","下列核酸中，具有降解mRNA功能的包括",[["A","hnRNA"],["B","siRNA"],["C","miRNA"],["D","snoRNA"]],"BC","siRNA（小干扰RNA）和miRNA（微RNA）均属于真核生物的非编码小分子RNA，二者能通过相似的机制降解mRNA：siRNA和miRNA均由一种名为Dicer的特异性核酸内切酶切割产生，又均与一种名为RISC（RNA诱导的沉默复合体）的复合体结合，通过碱基互补配对的方式识别靶mRNA，最终利用RISC降解靶mRNA（BC对），阻断翻译过程。miRNA和siRNA参与降解mRNA的详细过程见二版八年制生物化学P432图21-13。hnRNA（不均一核RNA）是mRNA的未成熟前体（十版生物化学P284），snoRNA（核仁小RNA）主要参与rRNA的加工和修饰（十版生物化学P70），二者均不能降解mRNA（D错）。","","N"],["2016-N158",4,"第8节 血糖及其调节","升高血糖的激素",2016,158,"X","","下列激素能升高血糖的是",[["A","胰高血糖素"],["B","糖皮质激素"],["C","肾上腺素"],["D","雌激素"]],"ABC","胰高血糖素（A对）、糖皮质激素（B对）、肾上腺素（C对）均能升高血糖。雌激素（D错）对蛋白质、脂肪代谢及水盐平衡有一定影响（九版生理学P409），但糖代谢的影响较小。","","N"],["2016-N159",5,"第6节 血浆脂蛋白及其代谢","超速离心法",2016,159,"X","","以下哪些脂蛋白在肝脏中合成",[["A","CM"],["B","HDL"],["C","LDL"],["D","VLDL"]],"BD","四种主要的血浆脂蛋白中，主要由肝脏合成的是HDL（高密度脂蛋白）（B对）和VLDL（极低密度脂蛋白）（D对）。CM（乳糜微粒）（A错）主要由小肠黏膜细胞合成。LDL（低密度脂蛋白）（C错）主要在血浆中合成。","","N"],["2016-N160",17,"第3节 细胞受体介导的细胞内信号转导","G蛋白耦联受体的概述",2016,160,"X","","参与G蛋白偶联受体介导信号转导通路的分子有",[["A","7次跨膜受体"],["B","G蛋白"],["C","腺苷酸环化酶"],["D","CMP"]],"ABC","G蛋白偶联受体介导的信号转导通路的基本过程如下：①细胞外信号分子结合7次跨膜受体（A对），通过别构效应将其激活；②受体激活G蛋白（B对）；③G蛋白激活腺苷酸环化酶（AC）（C对）、磷脂酶C（PLC）等G蛋白效应分子；④G蛋白效应分子催化产生第二信使物质，如AC催化产生cAMP，PLC催化产生DAG和IP₃；⑤第二信使物质作用于相应的靶分子（主要是蛋白激酶），使之构象改变而激活；⑥蛋白激酶通过磷酸化作用激活一些与代谢相关的酶、与基因表达相关的转录因子以及一些与细胞运动相关的蛋白，从而产生各种细胞应答反应。CMP（D错）即胞苷一磷酸（十版生物化学P57），为构成RNA的核苷酸，不参与信号转导过程。","","N"],["2016-N161",22,"第1节 血浆蛋白质","血浆蛋白质的功能",2016,161,"X","","血浆蛋白的功能有",[["A","维持血浆胶体渗透压"],["B","维持血浆pH"],["C","运输作用"],["D","免疫作用"]],"ABCD","血浆蛋白能够维持血浆胶体渗透压（A对），调节血管内外的水平衡。血浆蛋白盐与相应蛋白形成缓冲对，参与维持血浆正常的pH（B对）。血浆蛋白可以运输脂质、离子、维生素、代谢废物以及一些异物（包括药物）等（C对）。血浆中的免疫球蛋白（抗体）在体液免疫中发挥重要作用（D对）。","","N"],["2016-N162",21,"第3节 胆汁与胆汁酸的代谢","初级胆汁酸",2016,162,"X","","胆汁酸浓度升高时可抑制的酶有",[["A","胆固醇7α羟化酶"],["B","HMG-CoA还原酶"],["C","UDP-葡糖醛酸基转移酶"],["D","硫酸基转移酶"]],"AB","机体内胆固醇的主要去路是转化为胆汁酸后排出体外，胆汁酸浓度升高时可同时抑制胆汁酸和胆固醇的生物合成。合成胆汁酸和胆固醇的关键酶分别为胆固醇7α羟化酶（十版生物化学P472）和HMG-CoA还原酶（十版生物化学P159），两者均可受到胆汁酸浓度升高的负反馈调节（AB对），使酶活性被抑制。UDP-葡糖醛酸基转移酶（十版生物化学P467）和硫酸基转移酶（十版生物化学P467）均为参与生物转化结合反应的酶，与胆汁酸的合成代谢无关（CD错）。","","N"],["2016-N166",19,"第3节 抑癌基因","抑癌基因在癌症发生发展中具有重要作用",2016,166,"X","","细胞DNA损伤时，p53的主要作用是",[["A","使细胞停在G₁期"],["B","活化Ras"],["C","诱导Rb磷酸化"],["D","启动细胞凋亡程序"]],"AD","p53在细胞内时刻监控着染色体DNA的完整性，一旦DNA遭到损害，p53将与特定基因的DNA序列结合，起到转录因子的作用，激活P21等相关基因转录，使细胞停滞于G₁期（A对）；抑制解链酶活性，并与复制因子A相互作用，参与DNA的修复与复制。如果修复失败，p53即启动凋亡过程诱导细胞自杀（D对），阻止有癌变倾向突变细胞的生成，从而防止细胞恶变。","","N"],["2017-N17",0,"第2节 蛋白质的分子结构","蛋白质的二级结构",2017,17,"A","","蛋白质α-螺旋的特点",[["A","多为左手螺旋"],["B","螺旋方向与长轴垂直"],["C","靠盐键维持稳定性"],["D","氨基酸侧链伸向螺旋外侧"]],"D","蛋白质α-螺旋为常见的蛋白质二级结构之一，在α-螺旋结构中，多肽链的主链围绕中心轴（长轴）呈螺旋式上升，螺旋式上升方向与长轴是平行的（B错），螺旋的走向为顺时钟方向，呈右手螺旋（A错），氨基酸侧链伸向螺旋外侧（D对）。螺旋力靠氢键维持（C错），氢键由位于螺旋内侧的肽键中的羰基氧（O）与氨基氢结合而形成。","","N"],["2017-N18",4,"第5节 糖原的合成与分解","糖原合成",2017,18,"A","","下列酶中属于糖原合成的关键酶是",[["A","UDPG焦磷酸化酶"],["B","分支酶"],["C","糖原合酶"],["D","糖原磷酸化酶"]],"C","糖原的合成始于糖酵解的中间产物葡糖-6-磷酸。首先，葡糖-6-磷酸变构生成葡糖-1-磷酸。后者再与尿苷三磷酸（UTP）反应生成尿苷二磷酸葡萄糖（UDPG）和焦磷酸，此反应可逆，由UDPG焦磷酸化酶（A错）催化。在糖原合酶作用下，UDPG的葡萄糖基转移到糖原引物的非还原性末端，形成α-1，4-糖苷键，此反应不可逆，催化该反应的糖原合酶是糖原合成过程中的关键酶（C对）。但是，糖原合酶只能使糖链不断延长，不能形成分支，当糖链长度达到12～18个葡萄糖基时，分支酶（B错）将一段糖链转移到邻近的糖链上，以α-1，6-糖苷键相连，从而形成分支。糖原磷酸化酶（十版生物化学P125）（D错）为糖原分解过程中的关键酶。","","N"],["2017-N19",5,"第5节 胆固醇代谢","胆固醇的合成调节",2017,19,"A","","甲状腺功能亢进时，患者血清胆固醇含量降低的原因是",[["A","胆固醇合成原料减少"],["B","类固醇激素合成减少"],["C","胆汁酸的生成增加"],["D","HMG-CoA还原酶受到抑制"]],"C","甲状腺功能亢进时，患者血中甲状腺激素浓度升高，甲状腺激素能促进胆固醇在肝转变为胆汁酸（C对），因此甲状腺功能亢进患者血清胆固醇含量降低。甲亢时，肠黏膜吸收葡萄糖增加、糖代谢速率增加，胆固醇的合成原料（乙酰CoA、ATP、NADPH等）增加（A错），促进胆固醇合成（甲状腺激素既促进胆固醇合成，又促进胆固醇分解，对糖和脂类物质也有类似效果，这是甲亢患者基础代谢率高的重要原因）（P163）。类固醇激素包括皮质醇、醛固酮、雌激素、孕激素及雄激素等，合成类固醇激素增加（B错）也可降低血清中胆固醇的含量（合成类固醇激素胆固醇的另一去路）。甲亢时，血清胆固醇含量减少，对于HMG-CoA还原酶的反馈性抑制降低，HMG-CoA还原酶活性应增加（D错）。","","N"],["2017-N20",7,"第3节 氧化磷酸化与ATP的生成","根据P_O比值确定氧化磷酸化耦联部位",2017,20,"A","","生物氧化中P/O比值的含义是",[["A","生成ATP数与消耗1/2O₂的比值"],["B","分解蛋白质与需要的1/2O₂的比值"],["C","需要的磷酸与生成的1/2O₂的比值"],["D","氧化的磷脂与消耗的1/2O₂的比值"]],"A","P/O比值是指氧化磷酸化过程中，每消耗1/2摩尔O₂所需磷酸的摩尔数，即所能合成ATP的摩尔数（或一对电子通过氧化呼吸链传递给氧所生成ATP分子数）。转化过来即是生成ATP数与消耗的1/2O₂的比值（A对）。","","N"],["2017-N21",6,"第1节 营养必需氨基酸与氨基酸代谢概述","蛋白质营养价值的决定因素",2017,21,"A","","食物蛋白质营养价值指的是",[["A","蛋白质的含量"],["B","蛋白质与脂肪的比值"],["C","蛋白质的吸收速率"],["D","蛋白质在体内的利用率"]],"D","食物蛋白质营养价值指的是蛋白质在体内的利用率（D对），蛋白质营养价值的高低主要取决于必需氨基酸的种类及比例。一般来说，含必需氨基酸的种类多、比例高的蛋白质，其营养价值高。","","N"],["2017-N22",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径的概述",2017,22,"A","","直接参与嘌呤、嘧啶和尿素生物合成的氨基酸是",[["A","谷氨酰胺"],["B","天冬氨酸"],["C","丙氨酸"],["D","亮氨酸"]],"B","参与嘌呤生物合成的氨基酸有天冬氨酸（B）、甘氨酸、谷氨酰胺（A）；参与嘧啶生物合成（十版生物化学P226）的氨基酸有天冬氨酸（B）、谷氨酰胺（A）；参与尿素生物合成（十版生物化学P182）的氨基酸有鸟氨酸、天冬氨酸（B）、瓜氨酸、精氨酸。因此，直接参与嘌呤、嘧啶、尿素生物合成的氨基酸是天冬氨酸（B对）。","","N"],["2017-N23",11,"第4节 真核生物DNA复制过程","端粒酶参与解决染色体末端复制",2017,23,"A","","端粒酶的组成成分是",[["A","DNA修复酶＋引物"],["B","RNA聚合酶＋辅基"],["C","逆转录酶＋RNA"],["D","DNA聚合酶＋底物"]],"C","端粒酶由RNA、逆转录酶（C对）和协同蛋白三部分组成，因此端粒酶兼有提供RNA模板和催化逆转录的功能。","","N"],["2017-N24",12,"第1节 RNA的生物合成概述","以DNA为模板的RNA合成",2017,24,"A","","真核生物与原核生物转录的相同点是",[["A","都以操纵子模式进行调控"],["B","RNA合成酶相同"],["C","转录都具有不对称性"],["D","产物都需要在胞核加工"]],"C","在DNA分子双链上，按碱基配对规律能指导转录生成RNA的一股链作为模板指导转录，另一股链则不转录，这种模板选择性称为不对称转录，即转录具有不对称性，这是真核生物转录与原核生物转录的共同特点（C对）。与之形成对比的是，DNA复制时DNA双链的两股链均可作为模板指导复制，即复制具有对称性，是真核生物复制与原核生物复制的共同特点。操纵子指启动基因、操纵基因和多个紧密连锁的结构基因的总称，可介导多顺反子转录，原核生物转录是以操纵子模式进行；真核生物基因不组成操纵子（A错），每个结构基因都有其自身的基本启动子和调节元件，单独进行转录，为单顺反子转录。原核生物的RNA聚合酶只有一种，以大肠杆菌为例，其 RNA 聚合酶为由5 种亚基 α₂ββ'ωσ 组成的六聚体蛋白质（十版生物化学P274）；而真核生物 RNA 聚合酶主要有三种，分别为 RNA 聚合酶Ⅰ、RNA 聚合酶Ⅱ和 RNA 聚合酶Ⅲ（十版教材P279提及了植物中还存在RNA 聚合酶Ⅳ和RNA 聚合酶Ⅴ），三种 RNA 聚合酶均由 两个不同的大亚基和十几个小亚基组成（十版生物化学P279）。因此，真核生物转录与原核生物转录的聚合酶并不相同（B错）。原核生物mRNA的原始转录产物一般不需要加工（D错）就能直接作为翻译蛋白质的模板，又由于原核生物没有核膜将转录过程和翻译过程分隔在细胞内的不同区域，因此会出现转录和翻译同步进行的现象。而真核生物mRNA转录后，其原始转录产物（hnRNA）不能直接作为翻译蛋白质的模板，需要在胞核内进行5’-端和3’-端的修饰以及对hnRNA内的内含子进行剪接，才能成为成熟的mRNA，然后被转运到胞质内的核糖体，指导蛋白质翻译。","","N"],["2017-N25",13,"第4节 蛋白质合成后的加工和靶向输送","新生肽链折叠需要分子伴侣",2017,25,"A","","热激蛋白（热休克蛋白）的生理功能",[["A","作为酶参与蛋白合成"],["B","促进新生多肽链的折叠"],["C","参与蛋白靶向输送"],["D","肽链合成起始的关键分子"]],"B","热激蛋白（热休克蛋白）属于应激反应性蛋白，高温刺激可诱导其合成，故名。热激蛋白主要在蛋白质翻译后的加工过程中起作用，可促进需要折叠的新生肽链折叠为有天然构象的蛋白质（B对）。","","N"],["2017-N26",16,"第2节 重组DNA技术","目的DNA与载体连接",2017,26,"A","","基因工程中的黏性末端连接指的是",[["A","PCR引物与DNA模板连接"],["B","氨基酸之间的肽键形成"],["C","同一限制酶酶切位点的连接"],["D","cDNA与RNA形成杂交体"]],"C","多数Ⅱ型RE（限制性核酸内切酶）错位切割双链DNA，产生5’或3’突出末端，称为黏性末端。黏性末端连接是指同一限制性酶切位点产生的两条黏性末端DNA片段一起退火时，黏性末端单链间进行碱基配对，然后在DNA连接酶催化作用下形成共价结合的重组DNA分子的过程（C对）。","","N"],["2017-N27",17,"第2节 细胞内信号转导分子","蛋白质激酶和蛋白质磷酸酶的作用",2017,27,"A","","下列关于蛋白激酶叙述，正确的是",[["A","底物可以是脂类物质"],["B","可使亮氨酸残基磷酸化"],["C","蛋白质磷酸化后活性改变"],["D","属于第二信使物质"]],"C","蛋白激酶的底物是蛋白质（A错），可催化蛋白质内特定的氨基酸残基发生磷酸化反应，蛋白质磷酸化后活性发生改变（C对）。可发生磷酸化的氨基酸残基包括丝氨酸（羟基磷酸化）、苏氨酸（羟基磷酸化）、酪氨酸（酚羟基磷酸化）、组氨酸（咪唑环磷酸化）、赖氨酸（胍基磷酸化）、精氨酸（ε-氨基磷酸化）、半胱氨酸（巯基磷酸化）、天冬氨酸（酰基磷酸化）和谷氨酸（酰基磷酸化）等，但不包括亮氨酸（B错）。蛋白质激酶为第二信使的下游信号分子（D错），可在第二信使作用下被激活，如在cAMP-PKA通路（十版生物化学P395）中，蛋白激酶A（PKA）可被其上游的第二信使分子cAMP所激活。","","N"],["2017-N28",22,"第3节 血细胞物质代谢","红细胞内的糖无氧氧化的特殊途径",2017,28,"A","","能够调节血红蛋白运氧功能的物质是",[["A","三羧酸循环产物"],["B","2，3-二磷酸甘油酸旁路产物"],["C","磷酸戊糖途径产物"],["D","丙酮酸脱氢酶复合体催化产物"]],"B","红细胞内的糖酵解存在侧支循环—2，3-二磷酸甘油酸旁路，即在1，3-二磷酸甘油酸处形成分支，生成中间产物2，3-二磷酸甘油酸，再转变成3-磷酸甘油酸而返回糖酵解。2，3-二磷酸甘油酸的主要生理功能是调节血红蛋白的运氧功能（B对），当2，3-二磷酸甘油酸与脱氧血红蛋白结合时，可使脱氧血红蛋白的空间构象趋于稳定，从而降低血红蛋白对O₂的亲和力，促使O₂和血红蛋白解离。","","N"],["2017-N120",2,"第3节 RNA和空间结构与功能","核酶的分类及空间构象",2017,120,"B","","核酶的生物学作用是",[["A","RNA编辑"],["B","RNA自身剪接"],["C","RNA加帽"],["D","RNA加多聚A尾"]],"B","核酶是具有催化功能的小RNA，可在RNA自身剪接（B对）中起重要作用。RNA编辑（十版生物化学P289）（A错）是对基因的编码序列进行转录后加工，与核酶无关。RNA加帽（十版生物化学P284）（C错）由加帽酶（鸟苷酸转移酶）和甲基转移酶催化。RNA多聚A尾（D错）（十版生物化学P285）由多聚腺苷酸聚合酶催化。","","N"],["2017-N121",12,"第3节 真核生物mRNA的转录、加工和降解","mRNA编辑",2017,121,"B","","蛋白质氨基酸序列与hnRNA序列不完全对应的可能原因",[["A","RNA编辑"],["B","RNA自身剪接"],["C","RNA加帽"],["D","RNA加多聚A尾"]],"A","遗传信息从DNA分子转录到RNA分子中的过程称为转录。在真核生物中，最初转录生成的RNA称为不均一核RNA（即hnRNA）。经过RNA编辑（A对）后的一些序列会发生改变，导致最终翻译的蛋白质氨基酸序列与hnRNA序列不完全对应。RNA自身剪接（B错）是由核酶剪切掉hnRNA序列中的内含子，内含子对翻译产物（氨基酸序列）的结构无意义，不会造成蛋白质氨基酸序列与hnRNA序列不对应。RNA加帽（C错）和RNA加多聚A尾（D错）是RNA转录后加工修饰过程，不改变hnRNA序列，不会造成蛋白质氨基酸序列与hnRNA序列不对应。","","N"],["2017-N122",15,"第4节 生物分子相互作用研究技术","酵母双杂交技术",2017,122,"B","","测定蛋白质-蛋白质相互作用的实验是",[["A","酵母双杂交技术"],["B","聚合酶链反应"],["C","DNA链末端合成终止法"],["D","染色质免疫沉淀法"]],"A","分析蛋白质与蛋白质相互作用的技术是酵母双杂交法（A对）。聚合酶链反应（PCR）（十版生物化学P340）（B错）用于扩增目的DNA。DNA末端合成终止法（C错）即Sanger双脱氧测序法（十版生物化学P344），用于测定目的DNA的碱基序列。染色质免疫沉淀法（十版生物化学P349）（D错）用于研究DNA与蛋白质的相互作用。","","N"],["2017-N123",15,"第4节 生物分子相互作用研究技术","染色质免疫沉淀技术",2017,123,"B","","研究DNA-蛋白质相互作用的实验是",[["A","酵母双杂交技术"],["B","聚合酶链反应"],["C","DNA链末端合成终止法"],["D","染色质免疫沉淀法"]],"D","研究DNA与蛋白质相互作用的技术是染色质免疫沉淀法（D对）。酵母双杂交法（十版生物化学P348）（A错）用于分析蛋白质-蛋白质相互作用。聚合酶链反应（PCR）（十版生物化学P340）（B错）用于扩增目的DNA。DNA末端合成终止法（C错）即Sanger双脱氧测序法（十版生物化学P344），用于测定目的DNA的碱基序列。","","N"],["2017-N142",2,"第4节 核酸的理化性质","DNA变性",2017,142,"X","","能够导致核酸分子Tm值升高的因素有",[["A","GC含量升高"],["B","温度提高"],["C","溶液离子强度高"],["D","缓冲液浓度改变"]],"AC","解链温度（Tm）又称为融解温度，是指DNA解链过程中，溶液在260nm处的吸光度达到最大值一半时所对应的温度，在此温度时，50%的DNA双链解离成单链。一般来讲，DNA的Tm值与DNA分子的长短以及碱基的GC含量有关，分子的GC含量升高（A对），Tm值升高。溶液离子强度高（C对），Tm值越高。温度升高（B错）可促进DNA解链，但不改变核酸分子的Tm值。缓冲液浓度升高会导致溶液离子强度高从而Tm值升高，但并不代表缓冲液浓度改变（D错）会使Tm值升高。","","N"],["2017-N143",4,"第6节 糖异生","糖异生的关键酶及耗能",2017,143,"X","","糖异生反应涉及的酶",[["A","磷酸烯醇式丙酮酸羧激酶"],["B","丙酮酸羧化酶"],["C","葡萄糖激酶"],["D","6-磷酸果糖激酶"]],"AB","糖异生是非糖化合物（乳酸、甘油、生糖氨基酸等）转变为葡萄糖或糖原的过程，糖异生与糖酵解的多数反应是可逆的，但糖酵解中3个限速步骤（由3个关键酶催化）所对应的逆反应需要由糖异生特有的关键酶来催化。糖异生的关键酶有4个，分别为丙酮酸羧化酶（B对）、磷酸烯醇式丙酮酸羧激酶（A对）、果糖二磷酸酶-1和葡萄糖-6-磷酸酶。葡糖激酶（C错）和6-磷酸果糖激酶（D错）均为糖酵解的关键酶。","","N"],["2017-N144",6,"第4节 个别氨基酸的代谢","甲硫氨酸循环",2017,144,"X","","需要S-腺苷甲硫氨酸参与的反应有",[["A","磷脂酰胆碱生物合成"],["B","各种不同形式一碳单位的转换"],["C","肌酸的生物合成"],["D","去甲肾上腺素转变为肾上腺素"]],"ACD","S-腺苷甲硫氨酸（SAM）为甲硫氨酸的活性形式，S-腺苷甲硫氨酸中的甲基为活性甲基，是体内甲基最重要的直接供体，可以通过各种转甲基作用生成多种含甲基的生理活性物质，如肾上腺素（由去甲肾上腺素甲基化而来）（D对）、肉碱、胆碱（可合成磷脂酰胆碱）（A对）及肌酸（C对）等。各种一碳单位的转变通过氧化还原反应即可完成，不需要S-腺苷甲硫氨酸参与（B错）。相反，S-腺苷甲硫氨酸的转变需要一碳单位的参与，在甲硫氨酸循环（十版生物化学P189）中，同型半胱氨酸接受一碳单位N₅-CH₃-FH₄上的甲基，生成甲硫氨酸。","","N"],["2017-N145",6,"第1节 营养必需氨基酸与氨基酸代谢概述","真核细胞内蛋白质的降解途径",2017,145,"X","","下列属于蛋白质体内降解代谢途径的有",[["A","溶酶体降解"],["B","氨基酸脱氨基"],["C","甲硫氨酸循环"],["D","泛素化"]],"AD","蛋白质的降解是通过蛋白酶和肽酶完成的，蛋白质被蛋白酶水解成肽，然后肽被肽酶降解成游离氨基酸。蛋白质在体内的降解有两条重要途径，一条是在溶酶体（A对）内通过ATP非依赖途径降解，该通路一般降解细胞外来的蛋白质、膜蛋白和胞内长寿蛋白；第二条是通过泛素化（D对）使目标蛋白被标记从而使其降解，该通路主要降解异常蛋白质和短寿蛋白。氨基酸脱氨基（P181）（B错）为氨基酸分解代谢过程。甲硫氨酸循环（十版生物化学P189）（C错）参与甲硫氨酸的甲基转移过程。","","N"],["2017-N146",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物转录需要转录因子的参与",2017,146,"X","","能够与TATA盒结合的蛋白质有",[["A","RNA聚合酶Ⅱ"],["B","TFIID"],["C","拓扑异构酶"],["D","组蛋白"]],"AB","TATA盒是真核生物启动子（Ⅱ类启动子）元件，可与TFIID（B对）结合，RNA聚合酶Ⅱ（A对）在TF的帮助下与TATA盒结合，启动转录。","","N"],["2017-N147",17,"第2节 细胞内信号转导分子","蛋白质酪氨酸激酶的作用",2017,147,"X","","下列具有酪氨酸激酶活性的转导信号分子有",[["A","MAPK"],["B","G蛋白"],["C","Src蛋白激酶"],["D","表皮生长因子受体"]],"CD","蛋白酪氨酸激酶（PTK）可催化蛋白质分子中的酪氨酸残基磷酸化。蛋白酪氨酸激酶可分为跨膜的受体型和胞浆内的非受体型两种，前者包括表皮生长因子受体（D对）、血小板源生长因子受体等生长因子受体，后者的典型代表是Src蛋白激酶（C对）、JAK蛋白激酶等。MAPK（A错）即丝裂原激活的蛋白激酶（十版生物化学P389），具有丝氨酸-苏氨酸蛋白激酶活性。G蛋白（九版生理学P26）是鸟苷酸结合蛋白的简称，能与鸟嘌呤核苷酸结合，具有GTP水解酶活性，但不具有蛋白激酶活性。","","N"],["2018-N17",0,"第1节 蛋白质的分子组成","肽键和肽",2018,17,"A","","蛋白质肽键的化学本质是",[["A","氢键"],["B","盐键"],["C","酰胺键"],["D","疏水键"]],"C","肽键的化学本质是α-羧酸与α-氨基缩合而成的酰胺键（C对）。","","N"],["2018-N18",2,"第4节 核酸的理化性质","DNA变性",2018,18,"A","","DNA在融解温度时的变化是",[["A","280nm处的吸光度增加"],["B","容易与RNA形成杂化双链"],["C","CG之间的氢键全部断裂"],["D","50%的双链被打开"]],"D","对DNA加热时，两条链的氢键（A＝T、G≡C）逐渐解离成为单链状态，这种现象称为DNA变性，在DNA变性过程中，260nm（A错）处的紫外吸光度逐渐增加，当紫外吸光度达到最大变化值一半时所对应的温度定义为DNA的解链温度（Tm）或熔解温度。在此温度时，50%的氢键断裂（C错），即50%的DNA双链被打开（D对）。变性的DNA经缓慢冷却后可以复性，复性过程中将不同种类的DNA单链或RNA放在同一溶液中，只要两种核酸单链之间存在一定程度的碱基配对关系，它们就有可能形成杂化双链（B错）。","","N"],["2018-N19",1,"第3节 酶促反应动力学","竞争性抑制",2018,19,"A","","磺胺药对二氢叶酸还原酶的抑制性质是",[["A","不可逆抑制"],["B","竞争性抑制"],["C","反竞争性抑制"],["D","非竞争性抑制"]],"B","磺胺类药物与对氨基苯甲酸的化学结构相似，竞争性（B对）结合二氢蝶酸合酶的活性中心，抑制二氢叶酸以至于四氢叶酸的合成。不可逆抑制（A错）可见于有机磷、重金属离子和路易士气等对酶的抑制作用（十版生物化学P45）。反竞争性抑制（C错）可见于苯丙氨酸对胎盘型碱性磷酸酶的抑制（十版生物化学P48）。非竞争性抑制（D错）可见于亮氨酸对精氨酸酶的抑制、毒毛花苷G（哇巴因）对钠泵的抑制及麦芽糖对α淀粉酶的抑制等（十版生物化学P47）。本题题干为“二氢叶酸还原酶”表述有误。","","N"],["2018-N20",4,"第2节 糖的无氧氧化","糖无氧氧化的生理意义",2018,20,"A","","糖酵解的生理意义是",[["A","提供葡萄糖进入血液"],["B","为糖异生提供原料"],["C","加快葡萄糖氧化速率"],["D","缺氧时快速提供能量"]],"D","糖酵解的生理意义是缺氧时为机体快速提供能量（D对）。提供葡萄糖进入血液（A错）是糖异生和肝糖原分解的主要作用。为糖异生提供原料（B错）可为多种代谢通路的作用之一。","","N"],["2018-N21",7,"第3节 氧化磷酸化与ATP的生成","质子顺梯度回流需要ATP合酶转运",2018,21,"A","","能够促进ATP合酶合成ATP的因素是",[["A","物质还原速度的加快"],["B","质子顺浓度梯度向基质回流"],["C","寡霉素与ATP合酶相互作用"],["D","电子从Cyt b向Cyt c1的传递减慢"]],"B","质子顺浓度梯度向基质回流时，存储的能量被ATP合酶用于合成ATP（B对）。物质氧化的速度加快（A错）和电子从Cyt b向Cyt c₁的传递加快（D错）可促进ATP合酶合成ATP。寡霉素（C错）为ATP合酶的抑制剂，能够阻断ATP的合成。","","N"],["2018-N22",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径",2018,22,"A","","能直接以甘氨酸为原料合成的化合物是",[["A","二氢乳清酸"],["B","磷酸核糖焦磷酸"],["C","一磷酸腺苷"],["D","二磷酸尿苷"]],"C","在嘌呤核苷酸的从头合成途径中，机体可以直接利用甘氨酸（原料之一）合成次黄嘌呤核苷酸（IMP），后者可以进一步转变成一磷酸腺苷（C对）。甘氨酸不参与嘧啶核苷酸的合成代谢，故与二氢乳清酸（A错）及二磷酸尿苷（D错）无关。磷酸核糖焦磷酸（B错）可与谷氨酰胺合成磷酸核糖胺，再进一步与甘氨酸合成甘氨酰胺核苷酸，非甘氨酸的合成产物。","","N"],["2018-N23",1,"第4节 酶的调节","化学修饰调节",2018,23,"A","","体内快速调节代谢的方式是",[["A","酶蛋白生物合成"],["B","酶蛋白泛素化降解"],["C","酶蛋白化学修饰"],["D","同工酶亚基的聚合"]],"C","酶蛋白的化学修饰调节（C对）和别构调节（表现为别构酶的亚基聚合或解聚）（D错）可以改变酶的活性，属于对酶促反应速率的快速调节。酶蛋白的合成（P73）（A错）和酶蛋白泛素化降解（P73）（B错）可以改变酶的含量，属于对酶促反应的缓慢调节。","","N"],["2018-N24",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物转录需要转录因子的参与",2018,24,"A","","RNA生物合成时，转录因子TFⅡ D结合的部位是",[["A","TATA盒"],["B","ATG"],["C","GC盒"],["D","poly A"]],"A","转录因子TFⅡD是由TATA结合蛋白（TBP）和8～10个TBP相关因子（TAFs）共同组成的复合物，其中TATA结合蛋白可与TATA盒（A对）结合。","","N"],["2018-N25",13,"第2节 蛋白质合成体系","蛋白质合成所需酶类和蛋白质因子",2018,25,"A","","蛋白质生物合成时具有GTP酶活性的物质是",[["A","23S rRNA"],["B","EF-G"],["C","EF-Tu"],["D","RF-2"]],"C","原核生物蛋白质的生物合成可分为起始、延长和终止3个阶段，其中延长阶段又包括进位、成肽、转位3个步骤。延长阶段的进位需要延长因子EF-Tu和EF-Ts，其中EF-Tu（C对）具有GTP酶活性，能够结合并分解GTP，促进氨基酰-tRNA进入A位。EF-G（B错）与EF-Tu同为延长因子，参与延长阶段的转位，具有转位酶活性（十版生物化学P300）。23S rRNA（A错）为原核生物核糖体大亚基的组成成分，参与延长阶段的成肽，具有肽酰转移酶的活性。RF-2（D错）为释放因子，在蛋白质合成的终止阶段能够特异识别终止密码子UAA、UGA并诱导转肽酶转变为酯酶（十版生物化学P300）。","","N"],["2018-N26",14,"第1节 基因表达调控的基本概念与特点","基因表达的方式",2018,26,"A","","在生物个体中，几乎所有细胞都表达的基因是",[["A","管家基因"],["B","阻遏基因"],["C","可诱导基因"],["D","突变基因"]],"A","有些基因，在一个生物个体的几乎所有细胞中均有持续表达，不易受环境条件影响，其产物对生命的全过程是必需的，这些基因通常被称为管家基因（A对）。还有一些基因，只在特定的细胞中表达，并且其表达很容易受环境变化的诱导和阻遏，这些基因通常被称为可诱导基因（C错）和可阻遏基因（B错）。突变基因（D错）是指在结构上发生碱基对组成或排列顺序改变的基因。","","N"],["2018-N27",16,"第2节 重组DNA技术","目的DNA的分离获取",2018,27,"A","","可获得目的基因的方法是",[["A","质粒降解"],["B","外切核酸酶水解"],["C","核酸变性"],["D","逆转录合成"]],"D","逆转录PCR（RT-PCR）（D对）是将RNA的逆转录反应和PCR反应联合应用的一种技术。即首先以RNA为模板，在逆转录酶作用下合成cDNA，再以cDNA为模板通过PCR反应来扩增目的基因。质粒（十版生物化学P370）是主要存在于细菌染色体外的、能自主复制和稳定遗传的DNA分子，在重组DNA技术中，质粒是重要的克隆载体，可与目的基因连接重组，实现对目的基因的克隆扩增，但质粒本身并不含目的基因，故质粒降解不能获得目的基因（A错）。核酸变性（十版生物化学P73）（C错）是指在物理和化学因素的作用下，维系核酸二级结构的氢键发生断裂，使DNA由双链解离为单链的过程，不能获得目的基因。核酸外切酶（十版生物化学P217）（B错）降解是将核酸分子链末端的核苷酸水解成单个核苷酸的过程，亦不能获得目的基因。","","N"],["2018-N28",17,"第2节 细胞内信号转导分子","第二信使的概述",2018,28,"A","","可作为信号转导第二信使的物质是",[["A","一磷酸腺苷"],["B","腺苷酸环化酶"],["C","甘油二酯"],["D","生长因子"]],"C","细胞信号传导是通过多分子相互作用的一系列有序反应，将细胞外的信息传递到细胞内各种效应分子的过程。能够传递信号的分子称为信号转导分子，包括第二信使、酶、调节蛋白。第二信使包括环腺苷酸（cAMP）、环鸟苷酸（cGMP）、甘油二酯（DAG）（C对）、三磷酸肌醇（IP₃）、磷脂酰肌醇-3，4，5-三磷酸（PIP₃）、Ca²⁺等。","","N"],["2018-N120",0,"第1节 蛋白质的分子组成","氨基酸的分类",2018,120,"B","","蛋白质生物合成后经修饰形成的氨基酸是",[["A","羟脯氨酸"],["B","苏氨酸"],["C","硒代半胱氨酸"],["D","亮氨酸"]],"A","羟脯氨酸（A对）为蛋白质合成后由脯氨酸经羟化修饰而成。苏氨酸（B错）、亮氨酸（D错）和硒代半胱氨酸（C错）均为蛋白质合成过程中直接掺入的氨基酸。解释一下硒代半胱氨酸，在此前已知所有的氨基酸中，只有遗传密码表内的20种基本氨基酸才能在蛋白质合成过程中直接掺入肽链，而硒代半胱氨酸并不属于20种基本氨基酸之一，但新近的研究已经发现并确认硒代半胱氨酸为遗传密码正常编码的第21个氨基酸，其密码子为UGA，故硒代半胱氨酸属于在蛋白质合成过程中直接掺入的氨基酸，而非合成后经修饰形成的氨基酸。","","N"],["2018-N121",13,"第4节 蛋白质合成后的加工和靶向输送","氨基酸残基的化学修饰",2018,121,"B","","可以被磷酸化修饰的氨基酸是",[["A","羟脯氨酸"],["B","苏氨酸"],["C","硒代半胱氨酸"],["D","亮氨酸"]],"B","肽链合成时直接掺入的氨基酸只有20种（硒代半胱氨酸已经被确认为第21种，其密码子为UGA），合成后某些氨基酸残基的侧链基团发生的化学修饰显著增加了肽链中的氨基酸种类。常见的化学修饰种类包括磷酸化、糖基化、羟基化、甲基化和乙酰化等，其中磷酸化修饰常见于苏氨酸（B对）、丝氨酸和酪氨酸（由蛋白激酶催化，P386）。","","N"],["2018-N122",13,"第4节 蛋白质合成后的加工和靶向输送","新生肽链折叠需要分子伴侣",2018,122,"B","","参与合成多肽链正确折叠的蛋白质是",[["A","泛素"],["B","热激（休克）蛋白"],["C","逆转录酶"],["D","蛋白激酶"]],"B","蛋白质在合成时，一些辅助性蛋白质可以指导新生肽链按特定方式正确折叠，它们被称为分子伴侣，常见的分子伴侣包括热激蛋白（热休克蛋白）（B对）、伴侣蛋白等。泛素（A错）主要介导蛋白质在蛋白酶体内的降解过程（ATP依赖途径）。逆转录酶（C错）参与以RNA为模板合成DNA的逆转录过程。蛋白激酶（D错）参与催化苏氨酸、丝氨酸、酪氨酸等氨基酸残基的磷酸化修饰过程。","","N"],["2018-N123",17,"第2节 细胞内信号转导分子","蛋白质激酶和蛋白质磷酸酶的作用",2018,123,"B","","可作为信号传递分子开关的蛋白质是",[["A","泛素"],["B","热激（休克）蛋白"],["C","逆转录酶"],["D","蛋白激酶"]],"D","在信号转导过程中，细胞内的许多信号转导分子都是酶。作为信号转导分子的酶均可发挥“信号传递分子开关”的作用，主要有两大类：一是催化小分子信使生成和转化的酶，如腺苷酸环化酶、鸟苷酸环化酶、磷脂酶等；二是蛋白激酶（D对），如蛋白酪氨酸激酶、蛋白丝/苏氨酸激酶等。热激蛋白（十版生物化学P307）（B错）主要参与新生肽链的折叠与装配过程。泛素（十版生物化学P175）（A错）主要介导蛋白质在蛋白酶体内的降解过程（ATP依赖途径）。逆转录酶（十版生物化学P269）（C错）参与以RNA为模板合成DNA的逆转录过程。","","N"],["2018-N142",6,"第3节 氨的代谢","氨转运的概述",2018,142,"X","","参与血液中氨运输的主要氨基酸有",[["A","丙氨酸"],["B","鸟氨酸"],["C","谷氨酰胺"],["D","谷氨酸"]],"AC","氨通过丙氨酸（A对）-葡萄糖循环从骨骼肌运往肝，通过谷氨酰胺（C对）从脑和骨骼肌等组织运往肝或肾。","","N"],["2018-N143",7,"第4节 氧化磷酸化的影响因素","氧化磷酸化影响因素的概述",2018,143,"X","","能够影响氧化磷酸化的因素有",[["A","[ADP]/[ATP]"],["B","甲状腺激素增加"],["C","线粒体突变"],["D","CO阻断Cyt a3"]],"ABCD","氧化磷酸化是机体合成能量载体ATP的最主要的途径，凡是能影响ATP产生的因素均可以影响氧化磷酸化。ATP/ADP比值（A对）可以直接影响ATP的产生，影响氧化磷酸化。甲状腺激素（B对）诱导细胞膜上Na⁺，K⁺-ATP酶的生成，使ATP加速分解为ADP和Pi，ADP增多促进氧化磷酸化。线粒体DNA突变（C对）可直接影响电子的传递过程或ADP的磷酸化。CO通过与还原型Cyt a₃结合（D对），阻断电子传递给O₂，影响氧化磷酸化。","","N"],["2018-N144",13,"第2节 蛋白质合成体系","蛋白质合成所需酶类和蛋白质因子",2018,144,"X","","参与蛋白质生物合成的能量物质有",[["A","ATP"],["B","CTP"],["C","GTP"],["D","UTP"]],"AC","蛋白质合成是一个耗能过程：氨基酸被活化为氨基酰-tRNA时需要消耗1分子ATP（A对）的2个高能磷酸键（ATP→AMP）；翻译延长过程的进位和转位各需要消耗1分子GTP（C对）的1个高能磷酸键（GTP→GDP）；翻译终止过程需要消耗1分子GTP（C对）的1个高能磷酸键（GTP→GDP）。UTP（P124）（D错）为参与糖原合成的能量物质。CTP（十版生物化学P155）（B错）为参与磷脂合成的能量物质（磷脂合成由ATP供能，CTP参与乙醇胺、胆碱、甘油二酯活化）。","","N"],["2018-N145",14,"第2节 原核基因表达调控","操纵子",2018,145,"X","","参与基因转录调控的主要结构有",[["A","启动子"],["B","衰减子"],["C","增强子"],["D","密码子"]],"ABC","启动子（A对）是原核生物及真核生物的共有序列，可与各种调控蛋白（原核生物）和转录因子（真核生物）结合，参与基因转录调控。增强子是真核生物顺式作用元件的一种，与增强子结合蛋白（十版生物化学P329）结合，提高基因转录效率。衰减子是原核生物色氨酸操纵子（也见于其他氨基酸操纵子）中的一段调控序列，能够通过相关机制降低基因转录效率（转录衰减，十版生物化学P322）。密码子（D错）是指信使 RNA 链上决定氨基酸种类的相邻的三个碱基，与基因转录调控无关。","","N"],["2018-N146",21,"第2节 肝的生物转化作用","生物转化的概念及特点",2018,146,"X","","肝生物转化的作用有",[["A","使多数非营养物质活性降低"],["B","使某些激素灭活"],["C","使多数非营养物质的水溶性降低"],["D","对毒物既可解毒也可加大毒性"]],"ABD","肝是机体内生物转化最重要的器官，生物转化作用的生理意义在于：一则通过生物转化可对体内的大部分非营养物质如激素（B对）、神经递质等进行代谢转化，使其生物学活性降低（A对）或丧失（灭活）；或使有毒物质的毒性减低或消除（D对），也称解毒作用。另则通过生物转化作用可增加这些非营养物质的水溶性和极性（C错），从而易于从胆汁或尿排出体外。但应该指出的是，有些非营养物质经过肝的生物转化作用后，虽然溶解性增加，但其毒性反而增强（D对）；有的还可能溶解性下降，不易排出体外。","","N"],["2018-N147",15,"第4节 生物分子相互作用研究技术","电泳迁移率变动分析",2018,147,"X","","能够测定DNA-蛋白质相互作用的实验技术有",[["A","电泳迁移率变动测定"],["B","酵母双杂交"],["C","染色质免疫沉淀法"],["D","酶联免疫法"]],"AC","能测定DNA-蛋白质相互作用的试验方法是电泳迁移率变动分析（A对）和染色质免疫沉淀法（C对）。酵母双杂交法（B错）为测定蛋白质-蛋白质相互作用的试验方法。酶联免疫法（D错）是一种建立在抗原-抗体反应（蛋白质-蛋白质相互作用）基础上的蛋白质/多肽的定性及定量分析方法。","","N"],["2019-N17",13,"第4节 蛋白质合成后的加工和靶向输送","新生肽链折叠需要分子伴侣",2019,17,"A","","参与蛋白质折叠的蛋白质分子是",[["A","细胞膜上受体"],["B","伴侣蛋白"],["C","细胞内骨架蛋白"],["D","组蛋白"]],"B","细胞中大多数天然蛋白质折叠并不是自发完成的，其折叠过程需要其他酶或蛋白质的辅助，这些辅助性蛋白质可以指导新生肽链按特定方式正确折叠，它们被称为分子伴侣。最经典的分子伴侣有两种：热激蛋白（又称热休克蛋白）和伴侣蛋白（B对）。细胞膜受体（十版生物化学P385）（A错）是细胞膜上能特异识别生物活性分子并与之结合，进而引起生物学效应的特殊蛋白质。细胞内骨架蛋白（九版生物化学P465）（C错）是由蛋白质与蛋白质搭建起的骨架网络结构，主要作用是维持细胞的一定形态。组蛋白（十版生物化学P62）（D错）是构成染色质基本组成单位核小体的成分之一。","","N"],["2019-N18",1,"第2节 酶的工作原理","酶不同于一般催化剂的特点",2019,18,"A","","酶通过选择特异结构的底物进行催化，但不包括的底物是",[["A","同类底物"],["B","立体异构体的底物"],["C","特定底物"],["D","特定离子键的底物"]],"D","酶通过选择特异性结构的底物进行催化体现的是酶的绝对特异性，是指有的酶仅对一种特定结构的底物（C对）起催化作用，产生具有特定结构的产物。有些具有绝对特异性的酶甚至对同一种底物的不同光学异构体或立体异构体（B对）有选择性，例如，乳酸脱氢酶仅催化L-乳酸脱氢生成丙酮酸，而对D-乳酸无作用。对特定离子键的底物（D错，为本题正确答案）有选择性的催化体现的是酶的相对特异性，是指有些酶对底物的专一性不是依据整个分子的结构，而是依据底物分子中特定的化学键或特定的基团，可以作用于含有相同化学键或化学集团的一类化合物的特性。A选项同类底物本身的定义并不明确（同类结构底物还是同类化学键底物），但根据教材对酶的特异性的定义，同类底物应指具有同类结构的底物（A对）。","","N"],["2019-N19",2,"第2节 DNA和空间结构与功能","DNA双螺旋结构的多样性",2019,19,"A","","DNA双螺旋结构中，每一螺旋的碱基对数目为10.5的结构是",[["A","A-DNA"],["B","B-DNA"],["C","D-DNA"],["D","Z-DNA"]],"B","B-DNA是最经典的DNA双螺旋结构（J. Watson和F. Crick提出的双螺旋结构），是DNA在水性环境下和生理条件下最稳定的结构，螺旋旋向为右手螺旋，每一螺旋碱基对数为10.5（B对）。A-DNA仍然保存着右手螺旋的结构，但其空间参数不同，每一螺旋碱基对数为11（A错）。Z-DNA螺旋旋向为左手螺旋，每一螺旋碱基对数为12（D错）。D-DNA（C错）也是DNA分子构象的一种，但以目前现有的生物系统来说，自然界中可见的只有A-DNA、B-DNA与Z-DNA，D-DNA在教材中未明确说明。","","N"],["2019-N20",4,"第3节 糖的有氧氧化","丙酮酸氧化脱羧",2019,20,"A","","丙酮酸进入线粒体，氧化脱羧生成的产物是",[["A","草酰乙酸"],["B","柠檬酸"],["C","乙酰CoA"],["D","延胡索酸"]],"C","糖的有氧氧化反应分为三个阶段：第一阶段葡萄糖经糖酵解途径分解为丙酮酸；第二阶段丙酮酸进入线粒体内氧化脱羧生成乙酰CoA（C对）；第三阶段为柠檬酸循环（三羧酸循环），并偶联进行氧化磷酸化。草酰乙酸（A错）、柠檬酸（B错）和延胡索酸（D错）均为第三阶段柠檬酸循环的中间产物。","","N"],["2019-N21",7,"第2节 线粒体氧化体系与呼吸链","复合体Ⅲ",2019,21,"A","","在下列氧化呼吸链复合物中，Q循环存在的复合体是",[["A","复合体Ⅰ"],["B","复合体Ⅱ"],["C","复合体Ⅲ"],["D","复合体IV"]],"C","呼吸链中有四个蛋白复合体，“Q循环”存在的复合体是复合体Ⅲ（C对）。“Q循环”是为了实现双电子传递体泛醌（辅酶Q，CoQ，Q）与单电子传递体细胞色素之间的电子传递，是一个复杂的电子传递过程，最终将电子从泛醌经铁硫蛋白传递给细胞色素c1（Cyt c1）。","","N"],["2019-N22",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶类似物",2019,22,"A","","下列参与核苷酸合成的酶中，受5-氟尿嘧啶抑制的是",[["A","胸苷酸合酶"],["B","尿苷激酶"],["C","CPSⅡ"],["D","PRPP合成酶"]],"A","在核苷酸合成过程中，常用的抗代谢物多为其代谢过程中重要的底物或辅酶的类似物，5-氟尿嘧啶的结构与胸腺嘧啶相似，在体内可转变成一磷酸脱氧氟尿嘧啶核苷（FdUMP）及三磷酸氟尿嘧啶核苷（FUTP），FdUMP是胸苷酸合酶（A对）的抑制剂，胸苷酸合酶参与的是嘧啶核苷酸的从头合成途径（脱氧胸腺嘧啶核苷酸的生成），故5-氟尿嘧啶可使dTMP合成受阻，进而影响DNA合成。CPSⅡ（氨基甲酰磷酸合成酶Ⅱ）（C错）参与的是尿嘧啶核苷酸的合成，是其主要的调节酶，受其最终催化产物UMP的反馈抑制（十版生物化学P226）。尿苷激酶（B错）是一种嘧啶核苷酸的补救合成酶，可催化尿苷生成尿苷酸（十版生物化学P226）。PRPP合成酶（磷酸核糖焦磷酸合成酶）（D错）参与嘌呤核苷酸的从头合成，可被其催化产物次黄嘌呤核苷酸（IMP）、腺嘌呤核苷酸（AMP）、鸟嘌呤核苷酸（GMP）等抑制（十版生物化学P221）。","","N"],["2019-N23",11,"第1节 DNA复制的基本规律","DNA复制从起点双向进行",2019,23,"A","","DNA复制双向性的含义是",[["A","复制方向既可5′→3′，亦可3′→5′"],["B","一个复制起始点，形成两个复制叉"],["C","亲代DNA的5′→3′链和3′→5′链均可作为复制模板"],["D","两个起始点，两个生长点"]],"B","DNA复制的主要特征为：①半保留复制；②双向复制；③半不连续复制。其中，DNA双向复制的含义是复制从起点开始，向两个方向解链，复制中的模板是DNA形成2个延伸方向相反的开链区（复制叉），原核生物基因组是环状DNA，只有一个复制起点，进行的是简单的单点起始双向复制，真核生物基因组由多个染色体组构成，全部染色体均需复制，每个染色体又有多个起点，呈多起点双向复制特征（B对D错）。在DNA复制过程中，DNA合成酶只催化DNA链5’→3'方向的合成（A错），故子链沿着模板复制时，只能从5’→3'方向延伸，在同一复制叉上，解链方向只有一个，此时一条子链的合成方向与解链方向相同，另一条子链的复制方向则与解链方向相反。亲代DNA的5’→3’链和3’→5’链均可作为复制模板（C错）体现的是DNA复制中半保留复制的特征。","","N"],["2019-N24",12,"第3节 真核生物mRNA的转录、加工和降解","前体mRNA的剪接",2019,24,"A","","构成剪接体的RNA是",[["A","siRNA"],["B","snRNA"],["C","miRNA"],["D","snoRNA"]],"B","剪接体是在前体mRNA剪接过程中形成的剪接复合物。剪接体的主要组成是蛋白质和snRNA（核小RNA）（B对），前体mRNA的剪接在剪接体中完成。干扰小RNA（siRNA）（P334）（A错）参与RNA诱导的沉默复合体（RISC）组成，与特异的靶mRNA完全互补结合，导致靶mRNA降解，阻断翻译过程。微RNA（miRNA）（P334）（C错）与其他蛋白质一起组成RNA诱导的沉默复合体（RISC）。核仁小RNA（snoRNA）（十版生物化学P70）（D错）定位于核仁，主要参与rRNA的加工。","","N"],["2019-N25",14,"第2节 原核基因表达调控","乳糖操纵子的双重调节",2019,25,"A","","在乳糖操纵子模型中cAMP-CAP结合的序列是",[["A","启动子"],["B","启动子上游"],["C","操纵序列"],["D","A基因"]],"B","原核生物大多数基因表达调控是通过操纵子机制实现的。大肠杆菌的乳糖操纵子由结构基因（Z、Y、A）（D错）、操纵序列O（C错）、一个启动子P（A错）及一个调节基因I组成，I基因具有独立的启动子（PI），编码一种阻遏蛋白，后者与操纵序列O结合，使操纵子受阻遏而处于关闭状态。在启动子P上游（B对）还有一个CAP（分解代谢物基因激活蛋白）结合位点，可在葡萄糖缺乏时与cAMP-CAP结合，刺激乳糖操纵子RNA的转录活性。由P序列、O序列和CAP结合位点共同构成乳糖操纵子的调控区，三个酶的编码基因即由同一调控区调节，实现基因表达产物的协同表达。","","N"],["2019-N26",16,"第2节 重组DNA技术","质粒",2019,26,"A","","在DNA重组技术中使用质粒的目的是",[["A","促进宿主DNA复制"],["B","携带目的DNA进入受体细胞"],["C","使宿主基因发生重组"],["D","携带工具酶对宿主RNA剪接"]],"B","质粒是细菌染色体外的，能自主复制和稳定遗传的双链环状DNA分子，是DNA重组技术中最常用的克隆载体，其目的是携带外源DNA（目的基因）进入受体细胞中复制扩增（B对）。","","N"],["2019-N27",17,"第3节 细胞受体介导的细胞内信号转导","cAMP-PKA通路",2019,27,"A","","参与糖原合成与分解的主要信号途径是",[["A","Raf-MEK-ERK"],["B","JAK-STAT"],["C","G蛋白-PLC-IP₃"],["D","G蛋白-cAMP-PKA"]],"D","参与糖原合成与分解主要信号途径是G蛋白-cAMP-PKA（D对），以胰高血糖素调节肝糖原分解（十版生物化学P124）为例：①胰高血糖素与胰高血糖素受体（G蛋白偶联型受体）结合，激活与之偶联的G蛋白，G蛋白继而激活G蛋白效应器腺苷酸环化酶，催化ATP生成cAMP 。②当cAMP存在时，蛋白激酶A被激活。③活化的蛋白激酶A对磷酸化酶b激酶进行磷酸化修饰，使之活化。④在活化的磷酸化酶b激酶作用下，糖原磷酸化酶发生磷酸化修饰而激活，最终促进糖原分解。Raf-MEK-ERK途径（Ras-MAPK途径）（十版生物化学P397）（A错）和JAK-STAT途径（三版八年制生物化学P476）（B错）是目前已知大多数细胞中存在的两条传导细胞因子刺激信号的基本途径。前者在研究多种生长因子的信号传导中发现，可能主要与传递细胞增殖信号有关；后者发现于干扰素的信号传导研究中，现在已知在几乎所有细胞因子信号的传递中，该途径都发挥着重要的作用。G蛋白-PLC-IP₃（C错）是G蛋白-cAMP-PKA之外G蛋白偶联受体介导的另一条经典的信号传递途径，主要介导促甲状腺素释放激素、去甲肾上腺素、抗利尿激素等激素的跨膜信号转导。","","N"],["2019-N28",21,"第2节 肝的生物转化作用","氧化反应",2019,28,"A","","肝细胞中氧化非营养物质的主要酶是",[["A","葡糖醛酸转移酶"],["B","羟化酶"],["C","谷胱甘肽过氧化物酶"],["D","细胞色素氧化酶"]],"B","非营养物质是指既不是构建组织细胞的成分，又不能氧化供能的物质，有些非营养物质对人体有一定的生物学效应或者毒性，水溶性较低，需要经过一定的代谢途径（肝的生物转化作用）转变成水溶性较强的衍生物排出体外，以保持内环境的稳定，其中单加氧酶系是肝细胞中氧化非营养物质最重要的酶，该酶又称羟化酶（B对），能催化多种脂溶性物质从氧分子中接受1个氧原子生成羟化物或环氧化物，另一个氧原子则被NADPH还原成水。","","N"],["2019-N120",5,"第3节 甘油三酯代谢","酮体的生成",2019,120,"B","","合成酮体的酶是",[["A","HMG CoA合酶"],["B","乙酰CoA羧化酶"],["C","HMG CoA还原酶"],["D","脂酰CoA合成酶"]],"A","酮体是肝向肝外组织输出能量的重要形式，包括乙酰乙酸（30%）、β羟丁酸（70%）和丙酮（微量）。当葡萄糖供应不足或利用障碍时，酮体是脑的主要能源物质，酮体的生成以脂肪酸β-氧化产生的CoA为原料，在肝脏线粒体由酮体合成酶系催化完成，基本过程为：①2乙酰CoA→乙酰乙酰CoA+CoASH（乙酰乙酰CoA硫解酶催化）；②乙酰乙酰CoA+乙酰CoA→HMG-CoA+CoASH（HMG-CoA合酶催化）（A对）；③HMG-CoA→乙酰乙酸+乙酰CoA（HMG-CoA裂解酶催化）；④部分乙酰乙酸→β-羟丁酸或丙酮。乙酰CoA羧化酶（B错）是合成脂肪酸的关键酶（十版生物化学P152）。HMG-CoA还原酶（C错）是胆固醇合成的关键酶（十版生物化学P159）。脂酰CoA合成酶（D错）参与脂肪酸的β-氧化过程，脂肪酸被氧化前必须先活化，由脂酰CoA合成酶催化（十版生物化学P146）。","","N"],["2019-N121",5,"第3节 甘油三酯代谢","软脂酸合成的过程",2019,121,"B","","合成脂肪酸的关键酶是",[["A","HMG CoA合酶"],["B","乙酰CoA羧化酶"],["C","HMG CoA还原酶"],["D","脂酰CoA合成酶"]],"B","内源性脂肪酸的合成需要首先合成软脂酸再加工，合成软脂酸的基本原料为乙酰CoA，主要的合成场所是肝细胞的胞质。乙酰CoA 转化成丙二酸单酰CoA是软脂酸合成的第一步反应，催化此反应的乙酰CoA羧化酶（B对）是脂肪酸合成的关键酶。HMG-CoA合酶（A错）参与酮体的合成（十版生物化学P149）。HMG-CoA还原酶（C错）是胆固醇合成的关键酶（十版生物化学P159）。脂酰CoA合成酶（D错）参与脂肪酸的β-氧化过程，脂肪酸被氧化前必须先活化，由脂酰CoA合成酶催化（十版生物化学P150）。","","N"],["2019-N122",6,"第4节 个别氨基酸的代谢","一碳单位的来源及转换",2019,122,"B","","作为一碳单位原料的氨基酸是",[["A","丙氨酸"],["B","丝氨酸"],["C","天冬氨酸"],["D","酪氨酸"]],"B","一碳单位是指某些氨基酸在分解代谢过程中产生的含有一个碳原子的有机基团，包括甲基（—CH3）、亚甲基（—CH2—）、次甲基（＝CH—）、甲酰基（—CHO）及亚氨甲基（—CH＝NH）等。一碳单位主要来自丝氨酸（B对）、甘氨酸、组氨酸及色氨酸的分解代谢，苏氨酸通过间接转变成为甘氨酸也可以产生一碳单位。","","N"],["2019-N123",6,"第3节 氨的代谢","鸟氨酸循环过程",2019,123,"B","","在鸟氨酸循环中作为氨直接供体的氨基酸是",[["A","丙氨酸"],["B","丝氨酸"],["C","天冬氨酸"],["D","酪氨酸"]],"C","肝细胞是通过鸟氨酸循环途径合成尿素的，该循环从鸟氨酸开始，通过逐步加入基团将其转变为精氨酸，精氨酸水解成鸟氨酸和尿素，产生的鸟氨酸又用于下一个循环，此过程也称为尿素循环，在此循环中，尿素分子（H₂N-CO-NH₂）的2个氮原子，一个来自游离的氨（NH₃），另一个来自天冬氨酸（C对）。","","N"],["2019-N142",7,"第4节 氧化磷酸化的影响因素","氧化磷酸化影响因素的概述",2019,142,"X","","影响氧化磷酸化的因素有",[["A","线粒体ADP浓度增高"],["B","甲状腺激素增加"],["C","线粒体DNA突变"],["D","ATP合酶抑制"]],"ABCD","ATP是机体最主要的能量载体，机体根据自身能量需求，通过调节氧化磷酸化的速率来调节ATP的合成，凡是能够影响NADH、FADH2的产生、影响呼吸链组分和ATP合酶功能的因素，都会影响氧化磷酸化进而影响ATP的生成。氧化磷酸化的影响因素包括：①体内能量状态可调节氧化磷酸化的速率：细胞内ADP 的浓度以及ATP/ADP 的比值能够迅速感应机体能量状态的变化，ADP的含量是调节机体氧化磷酸化的主要因素（A对）。②抑制剂通过不同机制阻断氧化磷酸化的过程：呼吸链抑制剂可阻断电子传递过程、解偶联抑制剂阻断ADP的磷酸化过程、ATP合酶抑制剂同时抑制电子传递和ATP的生成（D对）。③甲状腺激素可促进ATP分解，使ADP浓度增加而促进氧化磷酸化，另外甲状腺激素可诱导解偶联蛋白基因表达，使氧化释能和产热比率均增加（B对）。④线粒体DNA突变会影响氧化磷酸化的功能（C对）。","","N"],["2019-N143",5,"第4节 磷脂代谢","甘油磷脂的合成原料",2019,143,"X","","合成甘油磷脂的直接原料有",[["A","胆碱"],["B","丝氨酸"],["C","肌醇"],["D","谷氨酸"]],"ABC","磷脂由甘油或鞘氨醇、脂肪酸、磷酸和含氮化合物组成。含甘油的磷脂称为甘油磷脂。因取代基团－X不同，形成不同的甘油磷脂，胆碱（A对）、丝氨酸（B对）和肌醇（C对）均为取代基团－X的合成原料。此题题干不严谨，根据官方给出的参考答案ABC来看，改成合成甘油磷脂的原料有更佳。","","N"],["2019-N144",18,"第2节 DNA损伤修复","DNA损伤的修复途径概述",2019,144,"X","","DNA损伤修复方式包括",[["A","直接修复"],["B","碱基切除修复"],["C","核苷酸切除修复"],["D","重组修复"]],"ABCD","DNA损伤修复是指纠正DNA两条单链间错配的碱基、清除DNA链上受损的碱基或糖基、修补DNA断裂，恢复DNA正常结构的过程，是维持机体DNA结构稳定、完整，保证生命延续和物种稳定的重要环节。DNA的损伤修复方式有直接修复（A对）、切除修复、重组修复（D对）和损伤跨越修复等，其中切除修复可分为碱基切除修复（B对）和核苷酸切除修复（C对）。","","N"],["2019-N145",10,"第2节 真核基因的结构与功能","启动子的作用",2019,145,"X","","下列物质的基因受真核启动子调控的有",[["A","microRNA"],["B","rRNA"],["C","tRNA"],["D","DNApolⅡ"]],"ABC","真核启动子属于真核生物对基因表达起调控作用的区域，能够介导RNA聚合酶结合并形成转录起始复合体。真核生物主要有3 类启动子，分别对应于细胞内存在的三种不同的RNA聚合酶和相关蛋白质。Ⅰ类启动子富含GC碱基对，具有Ⅰ类启动子的基因主要是编码rRNA（B对）的基因。Ⅱ类启动子具有TATA 盒特征结构，具有Ⅱ类启动子的基因主要是能转录出mRNA、microRNA（A对）和一些snRNA基因。Ⅲ类启动子包括A盒、B和C盒，具有Ⅲ类启动子的基因包括5S rRNA、tRNA（C对）、U6 snRNA等RNA分子的编码基因。DNApol-Ⅱ（DNA聚合酶Ⅱ）（D错）是原核生物的DNA聚合酶（十版生物化学P260），与启动子调控（转录调控）无关。","","N"],["2019-N146",13,"第4节 蛋白质合成后的加工和靶向输送","氨基酸残基的化学修饰",2019,146,"X","","蛋白质翻译后氨基酸的化学修饰方式有",[["A","乙酰化"],["B","甲基化"],["C","形成硒代半胱氨酸"],["D","形成二硫键"]],"ABD","蛋白质翻译后加工修饰有多种形式，包括肽链的折叠和二硫键的形成（D对）、肽链的剪切、肽链中某些氨基酸残基的化学修饰、肽链聚合及连接辅基等。其中氨基酸化学修饰是较为常见的一种，这种修饰对调节蛋白质的溶解度、活性、稳定性、亚细胞定位以及细胞中其他蛋白质的相互作用等具有重要作用，常见的氨基酸化学修饰调节有磷酸化、糖基化、羟基化、甲基化（B对）、乙酰化（A对）、硒化（C）（十版生物化学P309）等。需要注意的是，在十版生物化学与分子生物学（P306）及3版八年制生物化学与分子生物学（P397）中对蛋白质翻译后加工的定义，都将二硫键的形成与氨基酸的化学修饰并列，并未将前者归于后者。同时，对于硒代半胱氨酸的形成，它与甲基化、乙酰化等翻译后修饰不同的是，硒化修饰属于翻译前修饰（C错），硒代半胱氨酸在翻译过程中就已经存在，因为已有文献表明，硒代半胱氨酸被确认为第21种氨基酸，其密码子为UGA。本题的官方参考答案为ABD。","","N"],["2019-N147",21,"第4节 胆色素的代谢与黄疸","黄疸形成的原因",2019,147,"X","","增加尿胆原排泄的因素有",[["A","酸性尿液"],["B","胆红素生成增加"],["C","肝脏功能损伤"],["D","胆道梗阻"]],"BC","尿胆素原的排出受到多种因素的影响，如胆红素的生成量、肝细胞功能、胆道通畅程度及尿液pH值。胆红素生成增加时，经肝脏摄取、转化与排泄入肠道，转变成胆素原的量也增加，经重吸收并进入体循环、随尿液排出尿胆素原的量也随之增加（B对）。肝脏功能损伤时，经肠肝循环入肝的胆素原可经损伤的肝细胞进入体循环（正常应直接随胆汁排出），并从尿中排出，使尿胆素原升高（C对）。胆道梗阻时，排入肠道的结合胆红素减少，导致肠菌生成胆素原减少，经重吸收并进入体循环、随尿液排出尿胆素原的量也随之减少（D错）。酸性尿液时，尿胆素原可生成脂溶性分子，易被肾小管吸收，从尿液中排出量减少（A错）。","","N"],["2020-N17",2,"第2节 DNA和空间结构与功能","DNA的高级结构",2020,17,"A","","不参与构成核小体核心颗粒的组蛋白是",[["A","H1"],["B","H2A"],["C","H3"],["D","H4"]],"A","核小体是由DNA和组蛋白形成的染色质基本结构单位。核小体颗粒由146bp的DNA缠绕组蛋白八聚体1.75圈形成。组蛋白八聚体由2个H2A（B对）、2个H2B，2个H3（C对）和2个H4（D对）组成的。组蛋白H1（A错，为本题正确答案）结合在盘绕在核心组蛋白上的DNA双链的进出入口，发挥着稳定核小体的功能，并不参与核小体核心颗粒构成。","","N"],["2020-N18",1,"第1节 酶的分子结构与功能","酶的分子组成",2020,18,"A","","下列可作为辅酶转移氢原子的化合物是",[["A","TPP"],["B","FAD"],["C","FH₄"],["D","CoASH"]],"B","辅酶是一大类有机辅助因子的总称，它们在酶催化反应中承担传递电子、原子或基团的功能。在酶促反应中，可以传递H+的辅酶包括NAD+（烟酰胺腺嘌呤二核苷酸）、NADP+（烟酰胺腺嘌呤二核苷酸磷酸）、FMN（黄素单核苷酸）和FAD（黄素腺嘌呤二核苷酸）（B对）。TPP（焦磷酸硫胺素）（A错）在酶促反应中传递醛基。FH4（四氢叶酸）（C错）在酶促反应中传递一碳单位。CoA（辅酶A）（D错）在酶促反应中传递酰基。","","N"],["2020-N19",4,"第2节 糖的无氧氧化","磷酸果糖激酶-1",2020,19,"A","","在糖无氧酵解代谢调节中，磷酸果糖激酶-1的最强别构激活剂是",[["A","ATP"],["B","柠檬酸"],["C","AMP"],["D","果糖-2,6-二磷酸"]],"D","磷酸果糖激酶-1 的别构激活剂有AMP（C错）、ADP、果糖-1，6-二磷酸和果糖-2，6-二磷酸，其中活性最强的是果糖-2，6-二磷酸（D对）ATP（A错）和柠檬酸（B错）是磷酸果糖激酶-1的别构抑制剂。","","N"],["2020-N20",4,"第3节 糖的有氧氧化","三羧酸循环的过程",2020,20,"A","","在三羧酸循环中有一次底物水平磷酸化，其生成的分子是",[["A","ATP"],["B","GTP"],["C","磷酸肌酸"],["D","NADH+H⁺"]],"B","三羧酸循环中唯一的底物水平磷酸化反应发生在琥珀酰CoA水解生成琥珀酸的过程中。琥珀酰CoA含有高能硫酯键，它水解生成琥珀酸的同时，可与GDP的磷酸化偶联，生成GTP（B对）。以上为八版教材观点，九版后的教材认为催化该水解反应的琥珀酰CoA合成酶在哺乳动物体内有两种同工酶，分别以GDP或ADP作为辅因子，生成GTP（B对）或ATP（A对），因此，按照最新教材观点，A选项也是正确的。","","N"],["2020-N21",5,"第3节 甘油三酯代谢","酮体的氧化利用",2020,21,"A","","导致糖尿病酮症的主要脂代谢紊乱是",[["A","脂肪动员减弱"],["B","三酰甘油合成增加"],["C","脂肪酸β-氧化减弱"],["D","乙酰乙酸和β-羟丁酸增加"]],"D","糖尿病时，糖利用障碍，脂肪动员增加（三酰甘油分解增加）（AB错），脂肪酸β氧化增强（C错），生成乙酰CoA增加，糖利用障碍同时使草酰乙酸生成减少，进而使乙酰CoA进入三羧酸循环受阻，导致乙酰CoA大量堆积，使酮体合成增加（D对）。","","N"],["2020-N22",7,"第3节 氧化磷酸化与ATP的生成","呼吸链复合体质子泵产生跨膜的质子梯度",2020,22,"A","","下列线粒体呼吸链成分中，不具有质子泵功能的是",[["A","复合体Ⅰ"],["B","复合体Ⅱ"],["C","复合体Ⅲ"],["D","复合体Ⅳ"]],"B","线粒体呼吸链成分中，复合体Ⅰ（A对）、复合体Ⅲ（C对）和复合体IV（D对）均具有质子泵的功能：电子传递过程中，一对电子经复合体Ⅰ、Ⅲ、IV传递分别向膜间隙侧泵出 4H⁺、4H⁺和 2H⁺，共10个H⁺，由于线粒体内膜的不通透性，导致内膜两侧的H⁺浓度和电荷的差异，因此，呼吸链蛋白质复合体的质子泵功能形成线粒体内膜两侧的质子梯度，储存了电子传递过程释放的部分能量。复合体Ⅱ是琥珀酸-泛醌还原酶，即三羧酸循环中的琥珀酸脱氢酶，其功能是将电子从琥珀酸传递给Q，此过程释放的自由能较小，不足以将H⁺泵出线粒体内膜，因此复合体Ⅱ（B错，为本题正确答案）没有H⁺泵的功能。","","N"],["2020-N23",6,"第3节 氨的代谢","丙氨酸-葡萄糖循环",2020,23,"A","","血液中氨基运输的机制是",[["A","乳酸循环"],["B","甲硫氨酸循环"],["C","葡萄糖-丙氨酸循环"],["D","柠檬酸-丙酮酸循环"]],"C","氨在血液中以丙氨酸和谷氨酰胺两种形式转运，前者通过“葡萄糖-丙氨酸循环”的机制实现：在骨骼肌内，肌肉蛋白质、氨基酸以丙酮酸作为氨基受体，经转氨基作用生成丙氨酸，丙氨酸进入血液后被运往肝。在肝中，丙氨酸通过联合脱氨基作用生成丙酮酸，并释放氨。氨用于合成尿素，丙酮酸经糖异生途径生成葡萄糖。葡萄糖经血液运往肌肉，沿糖酵解转变成丙酮酸，后者再接受氨基生成丙氨酸。丙氨酸和葡萄糖周而复始的转变，完成骨骼肌和肝之间氨的转运，这一途径称为丙氨酸-葡萄糖循环（C对）。乳酸循环（十版生物化学P132）（A错）为肌肉收缩产生的乳酸运输到肝内进行糖异生的机制。甲硫氨酸循环（十版生物化学P189）（B错）为甲硫氨酸参与甲基转移反应的机制。柠檬酸-丙酮酸循环（十版生物化学P151）（D错）为脂肪酸合成过程中乙酰 CoA跨线粒体内膜转运的机制。","","N"],["2020-N24",12,"第3节 真核生物mRNA的转录、加工和降解","真核生物转录需要转录因子的参与",2020,24,"A","","真核生物转录前起始复合物中，识别TATA盒的转录因子是",[["A","TFⅡA"],["B","TFⅡB"],["C","TFⅡD"],["D","TFⅡF"]],"C","真核生物转录起始复合物中识别TATA盒转录因子的是TFⅡD（C对），TFⅡD含TBP（TATA binding protein，TATA盒结合蛋白质）亚基，可以结合启动子的TATA盒DNA序列。TFⅡA（A错）的功能是辅助和加强TFⅡD的TBP亚基与DNA的结合。TFⅡB（B错）的功能是结合TFⅡD稳定TFⅡD-DNA 复合物，介导RNA pol Ⅱ的募集等。TFⅡF（D错）的功能是结合RNA pol Ⅱ并随其进入转录延长阶段，防止其与 DNA 的接触。","","N"],["2020-N25",13,"第2节 蛋白质合成体系","核糖体是蛋白质合成的场所",2020,25,"A","","在肽链合成中，原核生物核糖体具有结合新进入的氨基酰-tRNA的位点是",[["A","A位"],["B","P位"],["C","E位"],["D","核糖体结合位点"]],"A","原核生物和真核生物的核糖体上均存在A位、P位和E位这3个重要的功能部位。A位（A对）结合新进入的氨基酰- tRNA，称氨酰位；P位（B错）结合肽酰- tRNA，称肽酰位；E位（C错）释放已经卸载了氨基酸的tRNA，称排出位。核糖体结合位点（十版生物化学P302）（D错）是原核生物 mRNA 起始密码子AUG及其上游的一段序列。该序列距AUG上游约10个核苷酸处通常为-AGGAGG-（也称Shine-Dalgamo序列，S-D序列），可被16S rRNA通过碱基互补而精确识别，从而将核糖体小亚基准确定位于mRNA。","","N"],["2020-N26",14,"第2节 原核基因表达调控","操纵子",2020,26,"A","","在乳糖操纵子负性调节机制中，阻遏蛋白结合的结构是",[["A","启动子"],["B","操纵序列"],["C","CAP位点"],["D","Z基因"]],"B","乳糖操纵子的结构包括一个操纵序列O，一个CAP结合位点，一个启动子P，一个调节基因I ，还有三个结构基因Z、Y及A。乳糖操纵子受到阻遏蛋白和CAP的双重调节：1. 阻遏蛋白的负性调节——在没有乳糖存在时，调节基因I编码一种阻遏蛋白，后者与操纵序列O（B对）结合，使乳糖操纵子受阻遏而处于关闭状态。2.CAP的正性调节——在没有葡萄糖存在时，cAMP 浓度增高，cAMP与CAP结合，进而促进CAP与CAP结合位点结合，刺激乳糖操纵子RNA聚合酶的转录活性。","","N"],["2020-N27",17,"第3节 细胞受体介导的细胞内信号转导","酶耦联受体的作用",2020,27,"A","","下列属于酶偶联受体的配体是",[["A","乙酰胆碱"],["B","γ干扰素"],["C","肾上腺素"],["D","甲状腺素"]],"B","酶偶联型受体是指其本身就具有酶的活性或与酶相结合的膜受体。这类受体的结构特征是每个受体分子只有单跨膜区段，其胞外结构域含有可结合配体的部位，而胞内结构域则具有酶的活性或能与酶结合的位点。这类受体的主要类型有酪氨酸激酶受体、酪氨酸激酶结合型受体、鸟苷酸环化酶受体和丝氨酸／苏氨酸激酶受体。酪氨酸激酶受体也称为受体酪氨酸激酶，其特征是胞内结构域具有酪氨酸激酶活性。激活这类受体的配体主要是各种生长因子，包括表皮生长因子、血小板源生长因子、成纤维细胞生长因子、肝细胞生长因子和胰岛素等。酪氨酸激酶结合型受体与酪氨酸激酶受体不同，其本身没有酶的活性，而是在激活后才在胞内侧与胞质中的酪氨酸激酶结合，并使之激活，进而磷酸化下游信号蛋白的酪氨酸残基，产生生物效应。通常激活该类受体的配体是各种生长因子和肽类激素，如促红细胞生成素、干扰素（B对）、白细胞介素、生长激素、催乳素和瘦素等。鸟苷酸环化酶受体是一种胞外N末端为配体结合域而胞内C末端为G活性结构域的单跨膜α螺旋分子。激活该受体的配体主要是心房钠尿肽和脑钠尿肽。另外，作为气体信使分子的一氧化氮，其作用的受体也是一种游离于胞质中的可溶性鸟苷酸环化酶。丝氨酸／苏氨酸激酶受体的胞内结构域具有丝氨酸／苏氨酸激酶活性，如转化生长因子-β受体等，该受体被激活后再使Smad蛋白的丝氨酸／苏氨酸残基磷酸化而激活，并转位到细胞核中，调控特定蛋白质基因的表达。","","N"],["2020-N28",15,"第1节 印迹法和探针技术","蛋白质印迹法的作用",2020,28,"A","","分析蛋白质表达量的实验技术是",[["A","Southernblotting"],["B","Westernblotting"],["C","Northernblotting"],["D","PCR"]],"B","蛋白质在电泳之后可以从胶中转移并固定到膜型材料上，再依靠与溶液中相应的蛋白质分子相互结合来进行定性定量分析，这种蛋白质印迹技术称为Western blotting（B对）。Southern blotting（A错）为DNA印迹技术，主要用于基因组DNA的定性和定量分析。Northern blotting（C错）为RNA印迹技术，主要用于检测特定组织或细胞中已知的特异性mRNA和非编码RNA的表达水平，也可以比较不同组织和细胞中的同一基因的表达情况。PCR（十版生物化学P340）（D错）主要用于扩增特定的DNA片段。","","N"],["2020-N120",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成调节",2020,120,"B","","参与嘌呤核苷酸从头合成途径的主要关键酶是",[["A","酰胺转移酶"],["B","天冬氨酸氨基甲酰基转移酶"],["C","次黄嘌呤-鸟嘌呤磷酸核糖转移酶"],["D","尿苷/胞苷激酶"]],"A","嘌呤核苷酸从头合成是指利用磷酸核糖、氨基酸、一碳单位及CO2等简单物质为原料，经过一系列酶促反应，合成嘌呤核苷酸的过程。其主要调控环节是第一步生成PRPP（5′-磷酸核糖-1′-焦磷酸）和第二步生成PRA（5′-磷酸核糖胺）的反应，催化这两步反应的PRPP合成酶和PRPP酰胺转移酶（A对）即为嘌呤核苷酸从头合成的关键酶。天冬氨酸氨基甲酰转移酶（十版生物化学P225）（B错）是参加细菌嘧啶核苷酸从头合成的关键酶。次黄嘌呤-鸟嘌呤磷酸核糖转移酶（十版生物化学P221）（C错）是参加嘌呤核苷酸补救合成的酶。尿苷/胞苷激酶（十版生物化学P226）（D错）是参加嘧啶核苷酸补救合成的酶。","","N"],["2020-N121",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶核苷酸从头合成的调节",2020,121,"B","","参与嘧啶核苷酸从头合成途径的主要关键酶是",[["A","酰胺转移酶"],["B","天冬氨酸氨基甲酰基转移酶"],["C","次黄嘌呤-鸟嘌呤磷酸核糖转移酶"],["D","尿苷/胞苷激酶"]],"B","在细菌中，参加嘧啶核苷酸从头合成的关键酶是天冬氨酸氨基甲酰转移酶（B对）；在哺乳类动物细胞中，参加嘧啶核苷酸从头合成的关键酶则是氨基甲酰磷酸合成酶Ⅱ。酰胺转移酶（十版生物化学P220）（A错）是参加嘌呤核苷酸从头合成的关键酶。次黄嘌呤-鸟嘌呤磷酸核糖转移酶（十版生物化学P221）（C错）是参加嘌呤核苷酸补救合成的酶。尿苷/胞苷激酶（P226）（D错）是参加嘧啶核苷酸补救合成的酶。","","N"],["2020-N122",5,"第6节 血浆脂蛋白及其代谢","低密度脂蛋白的功能和代谢途径",2020,122,"B","","转运肝合成的内源性胆固醇至全身组织的脂蛋白是",[["A","CM"],["B","VLDL"],["C","LDL"],["D","HDL"]],"C","转运肝内合成的内源性胆固醇至全身组织的脂蛋白是LDL（低密度脂蛋白）（C对）。CM（乳糜微粒）（A错）主要转运外源性甘油三酯及胆固醇至全身组织。VLDL（极低密度脂蛋白）（B错）主要转运肝内合成的内源性甘油三酯至全身组织。HDL（高密度脂蛋白）（D错）主要转运全身组织（肝外组织）的胆固醇至肝内（逆向转运胆固醇）。","","N"],["2020-N123",5,"第6节 血浆脂蛋白及其代谢","高密度脂蛋白的功能和代谢途径",2020,123,"B","","将肝外组织细胞的胆固醇转运至肝脏的脂蛋白是",[["A","CM"],["B","VLDL"],["C","LDL"],["D","HDL"]],"D","转运肝外组织的胆固醇至肝内的脂蛋白是HDL（高密度脂蛋白）（D对）。CM（乳糜微粒）（A错）主要转运外源性甘油三酯及胆固醇至全身组织。VLDL（极低密度脂蛋白）（B错）主要转运肝内合成的内源性甘油三酯至全身组织。LDL（低密度脂蛋白）（C错）转运肝内合成的内源性胆固醇至全身组织。","","N"],["2020-N142",11,"第1节 DNA复制的基本规律","DNA复制特征",2020,142,"X","","真核生物染色体DNA的复制方式有",[["A","半保留复制"],["B","半不连续复制"],["C","双向复制"],["D","D-环复制"]],"ABC","DNA复制的主要特征包括：半保留复制（A对）、双向复制（C对）和半不连续复制（B对），D-环复制（十版生物化学P269）（D错）是线粒体DNA复制的特征。","","N"],["2020-N143",12,"第3节 真核生物mRNA的转录、加工和降解","前体mRNA的剪接",2020,143,"X","","真核生物mRNA前体剪接部位的结构有",[["A","5’-剪接位点为GU"],["B","3’-剪接位点为AG"],["C","终止密码的3’端"],["D","切割信号序列5’-AAUAAA-3’"]],"AB","mRNA前体含有可被剪接体所识别的特殊序列，其内含子两端存在一定的序列保守性，大多数内含子都以GU为5'-端的起始序列（A对），以AG为3'-端的终末序列（B对），5'-GU…… AG-OH-3' 称为内含子的剪接接口。5’-AAUAAA-3’为前体mRNA在3'-端加入 poly（A）过程中的信号识别序列（D错）。","","N"],["2020-N144",13,"第4节 蛋白质合成后的加工和靶向输送","氨基酸残基的化学修饰",2020,144,"X","","蛋白质常发生磷酸化的氨基酸残基有",[["A","丝氨酸"],["B","苏氨酸"],["C","酪氨酸"],["D","苯丙氨酸"]],"ABC","丝氨酸（A对）、苏氨酸（B对）和酪氨酸（C对）的氨基酸残基常发生磷酸化。","","N"],["2020-N145",14,"第3节 真核基因表达调控","转录因子的DNA结合结构域",2020,145,"X","","转录因子的DNA结合结构域有",[["A","锌指模体"],["B","螺旋-环-螺旋"],["C","脯氨酸富含结构域"],["D","亮氨酸拉链"]],"ABD","转录因子是DNA结合蛋白，至少包括两个不同的结构域：DNA结合结构域和转录激活结构域。常见的DNA结合结构域包括锌指模体结构（A对）、碱性螺旋-环-螺旋模体结构（B对）、碱性亮氨酸拉链模体结构（D对）等。转录激活结构域则包括酸性激活结构域、富含谷氨酰胺结构域和富含脯氨酸结构域（C错）三类。","","N"],["2020-N146",10,"第3节 真核基因组的结构与功能","中度重复序列",2020,146,"X","","下列属于真核生物基因组结构中的中度重复序列的有",[["A","短散在核元件（SINEs）"],["B","长散在核元件（LINEs）"],["C","反向重复序列"],["D","卫星DNA"]],"AB","真核细胞基因组存在着大量重复序列，人基因组中，重复序列占基因组长度的 50%以上。重复序列的长度不等，短的仅含两个碱基，长的多达数百乃至上千个碱基。重复序列的重复频率也不尽相同，可以分为高度重复序列、中度重复序列和低度重复序列等3种。高度重复序列是真核基因组中存在的有数千到几百万个拷贝的DNA重复序列，高度重复序列按其结构特点分为反向重复序列（C错）和卫星DNA（D错）。中度重复序列指在真核基因组中重复数十至数千次的核苷酸序列，依据重复序列的长度，中度重复序列可分短散在核元件（SINEs）（A对）和长散在核元件（LINEs）（B对）两种类型。低度重复序列又称单拷贝序列，是指在单倍体基因组中只出现一次或数次，大多数编码蛋白质的基因属于这一类。","","N"],["2020-N147",21,"第3节 胆汁与胆汁酸的代谢","胆汁酸的分类",2020,147,"X","","下列胆汁酸中，属于初级胆汁酸的有",[["A","胆酸"],["B","牛磺胆酸"],["C","鹅脱氧胆酸"],["D","甘氨鹅脱氧胆酸"]],"ABCD","胆汁酸按其来源可分为初级胆汁酸和次级胆汁酸两类。在肝细胞以胆固醇为原料直接合成的胆汁酸称为初级胆汁酸，包括胆酸、鹅脱氧胆酸及其与甘氨酸或牛磺酸的结合产物，即胆酸（A对）、鹅脱氧胆酸（C对）、甘氨胆酸、甘氨鹅脱氧胆酸（D对）、牛磺胆酸（B对）和牛磺鹅脱氧胆酸均属于初级胆汁酸。","","N"],["2021-N17",0,"第2节 蛋白质的分子结构","结构模体",2021,17,"A","","“亮氨酸拉链” 属于的蛋白质结构是",[["A","一级结构"],["B","β-转角"],["C","模体"],["D","结构域"]],"C","亮氨酸拉链是一种蛋白质结构模体（C对），常见于许多转录因子的DNA结合结构域，与基因的表达调控有关。","","N"],["2021-N18",1,"第2节 酶的工作原理","邻近效应与定向排列",2021,18,"A","","酶促反应中“邻近效应”的含义是",[["A","底物在酶活性中心相互靠近"],["B","酶与辅酶之间相互靠近"],["C","酶必需基团之间相互靠近"],["D","酶与抑制剂之间相互靠近"]],"A","酶在反应中将底物结合到酶的活性中心，使它们相互接近，并形成有利于反应的正确定向关系，这种作用称为“邻近效应”。","","N"],["2021-N19",7,"第3节 氧化磷酸化与ATP的生成","质子顺梯度回流需要ATP合酶转运",2021,19,"A","","寡霉素与ATP合酶结合部位是",[["A","α亚基"],["B","β亚基"],["C","γ亚基"],["D","c亚基"]],"D","ATP合酶是多蛋白组成的蘑菇样结构，含F₁和F₀两个功能结构域。F₁和F₀均含有与寡霉素结合的部位，F₁主要由α₃β₃γδε亚基复合体和寡霉素敏感蛋白组成，后者可与寡霉素结合。F₀由a、b2、c9-12亚基组成，其中c亚基（D对）可与寡霉素结合。","","N"],["2021-N20",6,"第3节 氨的代谢","丙氨酸-葡萄糖循环",2021,20,"A","","肌肉组织氨基酸脱氨基的方式是",[["A","甲硫氨酸循环"],["B","三羧酸循环"],["C","乳酸循环"],["D","丙氨酸-葡萄糖循环"]],"D","肌肉组织氨基酸脱氨基的方式是丙氨酸-葡萄糖循环（D对）：骨骼肌主要以丙酮酸作为氨基受体，经转氨基作用生成丙氨酸，丙氨酸进入血液后被运往肝。在肝中，丙氨酸通过联合脱氨基作用生成丙酮酸，并释放氨。氨用于合成尿素，丙酮酸经糖异生途径生成葡萄糖。葡萄糖经血液运往肌肉，沿糖酵解转变成丙酮酸，后者再接受氨基生成丙氨酸。 丙氨酸和葡萄糖周而复始的转变，完成骨骼肌和肝之间氨的转运，这一途径称为丙氨酸-葡萄糖循环。通过这个循环，骨骼肌组织中氨基酸的氨基(“氨”)以丙氨酸形式运往肝，同时，肝又为骨骼肌提供了生成丙酮酸的葡萄糖。甲硫氨酸循环（十版生物化学P189）（A错）与甲硫氨酸的转甲基作用有关。三羧酸循环（十版生物化学P117）（B错）是三大营养物质（糖类、脂类、氨基酸）分解产能的共同通路及代谢联系的枢纽。乳酸循环（十版生物化学P132）（C错）是肌肉收缩产生的乳酸在肝内糖异生的转运方式。本题不严谨，题干提问“脱氨基的方式”，氨基酸脱氨基的方式应为转氨基、氧化脱氨基及非氧化脱氨基等方式（十版生物化学P177）。本题的答案“丙氨酸 - 葡萄糖循环”应为转运氨基的方式。","","N"],["2021-N21",8,"第3节 嘧啶核苷酸的合成与分解代谢","dTMP的生成",2021,21,"A","","一碳单位直接参与生成的物质是",[["A","dCMP"],["B","dAMP"],["C","dGMP"],["D","dTMP"]],"D","dTMP（D对）是由脱氧尿嘧啶核苷酸（dUMP）经一碳单位甲基化而生成的，反应由胸苷酸合酶催化，N⁵，N¹⁰-亚甲四氢叶酸作为甲基供体。除dTMP是从dUMP转变而来以外，其他脱氧核苷酸都是在二磷酸核苷（NDP）水平上进行（N代表A、G、U、C等碱基）（ABC错），由核苷酸还原酶催化而来。","","N"],["2021-N22",11,"第4节 真核生物DNA复制过程","端粒酶参与解决染色体末端复制",2021,22,"A","","下列酶中具有逆转录活性的是",[["A","光复活酶"],["B","DNA聚合酶δ"],["C","端粒酶"],["D","RNA聚合酶Ⅱ"]],"C","端粒酶（C对）由端粒酶RNA、端粒酶协同蛋白-1和端粒酶逆转录酶三部分组成，该酶兼有提供RNA模板和催化逆转录的功能。光复活酶（十版生物化学P407）（A错）是用来修复由于暴露在紫外光照射下的DNA损伤的酶，DNA聚合酶δ（十版生物化学P260）（B错）是真核生物DNA复制过程中催化后随链合成的酶，RNA聚合酶Ⅱ（十版生物化学P331）（D错）是真核生物RNA转录过程中催化前体mRNA合成的酶。","","N"],["2021-N23",14,"第3节 真核基因表达调控","真核生物基因组的特点",2021,23,"A","","真核生物转录生成单顺反子mRNA的含义是",[["A","一个DNA生成一个mRNA"],["B","一个mRNA编码一条多肽链"],["C","一个mRNA逆转录生成一个cDNA"],["D","不同细胞合成同一条多肽链"]],"B","真核生物转录生成单顺反子mRNA的含义是：真核生物一个结构基因转录生成一条mRNA， 编码一条多肽链（B对）的初级转录物。","","N"],["2021-N24",13,"第3节 肽链的合成过程","成肽",2021,24,"A","","下列由RNA发挥催化作用的酶是",[["A","氨基酰-tRNA合成酶"],["B","脱甲酰基酶"],["C","二硫键异构酶"],["D","肽酰转移酶"]],"D","由RNA发挥催化作用的酶是肽酰转移酶（D对），肽酰转移酶是在蛋白质合成过程中催化肽键形成（成肽）的酶，该酶的化学本质不是蛋白质，而是rRNA，在原核生物中为23s rRNA，在真核生物为28s rRNA。氨基酰-tRNA合成酶（十版生物化学P301）（A错）、脱甲酰基酶（十版生物化学P308）（B错）和二硫键异构酶（十版生物化学P307）（C错）的化学本质均为蛋白质。","","N"],["2021-N25",14,"第3节 真核基因表达调控","增强子",2021,25,"A","","下列能够调控真核生物转录的DNA元件是",[["A","增强子"],["B","操纵子"],["C","CAP结合位点"],["D","阻遏蛋白基因"]],"A","增强子（A对）是真核生物顺式作用元件中可以增强启动子工作效率的特定DNA序列，是真核生物转录调控的重要元件。操纵子（十版生物化学P318）（B错）是原核生物转录调控的基本单位。CAP 结合位点（十版生物化学P320）（C 错）和阻遏蛋白基因（十版生物化学P320）（D 错）均为原核生物乳糖操纵子的调控序列。","","N"],["2021-N26",16,"第2节 重组DNA技术","重组DNA转入宿主细胞",2021,26,"A","","下列符合“转染”的技术操作是",[["A","利用电穿孔技术将外源DNA转入大肠埃希菌"],["B","利用质粒将外源DNA转入动物细胞"],["C","利用病毒载体将外源DNA转入大肠埃希菌"],["D","利用转基因技术克隆动物"]],"B","转染是指将外源DNA直接导入真核细胞（酵母除外）的过程（B对），常用的转染方法包括化学方法（如磷酸钙共沉淀法、脂质体融合法等）和物理方法（如显微注射法、电穿孔法等）。此外，将噬菌体DNA直接导入受体细菌的过程也称作转染。利用电穿孔技术将外源DNA转入大肠埃希菌（A错）属于转化（十版生物化学P375）。利用病毒载体将外源DNA转入大肠埃希菌（C错）属于感染（十版生物化学P375）。","","N"],["2021-N27",17,"第2节 细胞内信号转导分子","衔接蛋白和支架蛋白的作用",2021,27,"A","","能与富含脯氨酸的蛋白质结合的分子结构域是",[["A","SH2"],["B","SH3"],["C","PH"],["D","PTB"]],"B","能与富含脯氨酸的蛋白质（富含脯氨酸模体）结合的分子结构域是SH3（B对）。SH2（A错）为能与“含磷酸化酪氨酸模体”结合的分子结构域。PH（C错）为能与“磷脂衍生物模体”结合的分子结构域。PTB（D错）为能与“含磷酸化酪氨酸模体”结合的分子结构域。","","N"],["2021-N28",14,"第3节 真核基因表达调控","沉默子",2021,28,"A","","基因上游插入外源性沉默子后可能出现的结果是",[["A","编码的肽链缩短"],["B","终止密码提前"],["C","基因转录减慢"],["D","点突变可能性增加"]],"C","沉默子是一类基因表达的负性调控元件，当其结合特异蛋白因子时，对基因转录起阻遏作用，使基因转录减慢（C对）。","","N"],["2021-N120",4,"第3节 糖的有氧氧化","三羧酸循环的过程",2021,120,"B","","参与三羧酸循环的酶是",[["A","琥珀酰CoA合成酶"],["B","HMG CoA还原酶"],["C","乙酰CoA羧化酶"],["D","HMG CoA裂解酶"]],"A","参与三羧酸循环的酶是琥珀酰CoA合成酶（A对），琥珀酰CoA合成酶催化琥珀酰CoA水解生成琥珀酸，同时偶联核苷二磷酸的磷酸化，生成高能磷酸键，是三羧酸循环过程中唯一的底物水平磷酸化反应。HMG-CoA还原酶（十版生物化学P159）（B错）为胆固醇合成过程中的关键酶，细胞质生成的HMG-CoA在内质网HMG­-CoA还原酶作用下，由NADPH供氢，还原生成甲羟戊酸。乙酰CoA羧化酶（十版生物化学P152）（C错）是脂肪酸合成过程中的关键酶，催化软脂酸合成的第一步反应——乙酰CoA转化成丙二酸单酰CoA的过程。HMG-CoA裂解酶（十版生物化学P149）（D错）参与酮体的生成，在肝细胞线粒体中，HMG-CoA裂解酶催化HMG-CoA裂解产生乙酰乙酸和乙酰CoA。","","N"],["2021-N121",5,"第3节 甘油三酯代谢","酮体的生成",2021,121,"B","","产物是酮体的酶是",[["A","琥珀酰CoA合成酶"],["B","HMGCoA还原酶"],["C","乙酰CoA羧化酶"],["D","HMGCoA裂解酶"]],"D","产物是酮体的酶是HMG-CoA裂解酶（D对），在肝细胞线粒体中，HMG-CoA裂解酶催化HMG-CoA裂解产生乙酰乙酸和乙酰CoA，乙酰乙酸进而可转变为β-羟丁酸和丙酮，乙酰乙酸、β-羟丁酸和丙酮均属于酮体。琥珀酰CoA合成酶（十版生物化学P115）（A错）参与三羧酸循环，琥珀酰CoA合成酶可催化琥珀酰CoA水解生成琥珀酸，同时偶联核苷二磷酸的磷酸化，生成高能磷酸键，该步骤是三羧酸循环中唯一的底物水平磷酸化反应。HMG-CoA还原酶（十版生物化学P159）（B错）为胆固醇合成过程中的关键酶，细胞质生成的HMG-CoA在内质网HMG­CoA还原酶作用下，由NADPH供氢，还原生成甲羟戊酸。乙酰CoA羧化酶（十版生物化学P152）（C错）是脂肪酸合成过程中的关键酶，催化软脂酸合成的第一步反应——乙酰CoA转化成丙二酸单酰CoA的过程。","","N"],["2021-N122",2,"第3节 RNA和空间结构与功能","非编码RNA的功能",2021,122,"B","","长度大于200nt的RNA分子是",[["A","tRNA"],["B","lncRNA"],["C","scRNA"],["D","miRNA"]],"B","长度大于200nt（nt表示核苷酸数目）的RNA分子是lncRNA（长非编码RNA）（B对），lncRNA属于调控性非编码RNA，长度在200～100000nt之间。tRNA（A错）即转运RNA，属于组成性非编码RNA，目前已知的tRNA长度在74～95nt之间。miRNA（D错）即微RNA，属于调控性非编码RNA中的非编码小RNA，长度在20～25nt之间，广泛存在于真核生物中。ScRNA（十版生物化学P70）（C错）即胞质小RNA，属于组成性非编码RNA，长度小于200nt，存在细胞质中，与蛋白质结合形成复合体后发挥生物学功能。","","N"],["2021-N123",2,"第3节 RNA和空间结构与功能","非编码RNA的功能",2021,123,"B","","能与mRNA 3’-端非翻译区结合抑制翻译的RNA是",[["A","tRNA"],["B","lncRNA"],["C","scRNA"],["D","miRNA"]],"D","一条成熟的真核mRNA包括5'-非翻译区、编码区和3'-非翻译区，编码区是编码蛋白质多肽链的核苷酸序列，非翻译区通过与调节因子或非编码RNA的相互作用调控蛋白质生物合成。能与mRNA3’端非翻译区结合抑制翻译的RNA是miRNA（D对），即微RNA，属于调控性非编码RNA中的非编码小RNA，当miRNA与靶基因mRNA不完全互补，则miRNA将与靶基因mRNA的3’-非翻译区的序列形成非完全互补的杂交双链，miRISC紧紧地结合在杂交双链上，特异性地抑制基因表达。tRNA（十版生物化学P67）（A错）即转运RNA，tRNA的反密码子环上的反密码子能与mRNA编码区上的密码子结合，起到转运氨基酸的作用，该过程为翻译。lncRNA（十版生物化学P71）（B错）即长非编码RNA，属于调控性非编码RNA，其调控基因表达的机制多样，如能与DNA序列上游启动子区（一般情况下转录后对应mRNA5’-端非翻译区）结合，干扰下游DNA序列的表达；能与编码蛋白质基因的mRNA结合，形成互补双链，干扰mRNA的剪切，形成不同的剪切形式，或者在Dicer酶的作用下产生内源性siRNA（干扰小RNA）等多种机制实现对基因的调控。scRNA（十版生物化学P70）（C错）即胞质小RNA，属于组成性非编码RNA，与蛋白质结合形成复合体后发挥生物学功能。","","N"],["2021-N142",6,"第3节 氨的代谢","鸟氨酸循环过程",2021,142,"X","","胞质和线粒体共同涉及的代谢途径是",[["A","天冬氨酸-精氨酸代琥珀酸穿梭"],["B","α-磷酸甘油穿梭"],["C","鸟氨酸循环"],["D","三羧酸循环"]],"ABC","α-磷酸甘油穿梭（B对）为脑和骨骼肌细胞胞质内NADH进入线粒体呼吸链的穿梭机制。鸟氨酸循环（C对）又称尿素循环，大体可分为五步，其中前两步在线粒体中完成（①NH₃、CO₂和ATP缩合生成氨基甲酰磷酸；②氨基甲酰磷酸与鸟氨酸反应生成瓜氨酸），后三步在胞质中完成（③瓜氨酸与天冬氨酸反应生成精氨酸代琥珀酸；④精氨酸代琥珀酸裂解生成精氨酸与延胡索酸；⑤精氨酸水解释放尿素并再生成鸟氨酸）。鸟氨酸循环的第三步反应为天冬氨酸与瓜氨酸生成精氨酸代琥珀酸，此过程在胞质内进行。三版生物化学认为精氨酸代琥珀酸裂解产生的延胡索酸可经过线粒体三羧酸循环的中间步骤转变成草酰乙酸，后者与谷氨酸进行转氨基反应，又重新生成天冬氨酸，因此将此过程称为三羧酸循环的天冬氨酸-精氨酸代琥珀酸穿梭，其可使尿素循环与三羧酸循环联系起来，该过程同时涉及胞质和线粒体（A对）。三羧酸循环为糖的有氧氧化的第三个阶段，全程在线粒体内完成（D错）。按照十版生物化学该题存在争议，本题的官方参考答案为ABC。","","N"],["2021-N143",6,"第1节 营养必需氨基酸与氨基酸代谢概述","蛋白质营养价值的决定因素",2021,143,"X","","下列属于营养必需氨基酸的是",[["A","赖氨酸"],["B","色氨酸"],["C","亮氨酸"],["D","组氨酸"]],"ABCD","人体内有9种氨基酸不能合成，必须由食物提供的氨基酸，在营养学上称为必需氨基酸，包括赖氨酸（A对）、色氮酸（B对）、亮氨酸（C对）、组氨酸（D对）异亮氨酸、苏氨酸、缬氨酸、甲硫氨酸、苯丙氨酸。记忆口诀为“组队来写一两本淡色书”，组（组氨酸）队来（赖氨酸）写（缬氨酸）一（异亮氨酸）两（亮氨酸）本（苯丙氨酸）淡（蛋氨酸/甲硫氨酸）色（色氨酸）书（苏氨酸）。精氨酸虽然能够在人体内合成，但合成量不多，若长期供应不足或需要量增加也可造成负氮平衡。因此，有人将精氨酸也归为营养必需氨基酸。","","N"],["2021-N144",8,"第3节 嘧啶核苷酸的合成与分解代谢","嘧啶核苷酸从头合成途径的概述",2021,144,"X","","参与嘧啶核苷酸和嘌呤核苷酸从头合成途径的共同原料有",[["A","天冬氨酸"],["B","甘氨酸"],["C","CO₂"],["D","磷酸核糖焦磷酸（PRPP）"]],"ACD","参与嘧啶核苷酸和嘌呤核苷酸从头合成途径的共同原料有天冬氨酸（A对）、CO₂（C对）、谷氨酰胺和磷酸核糖焦磷酸（PRPP）（D对）。甘氨酸（B错）为嘌呤核苷酸从头合成途径的原料。","","N"],["2021-N145",17,"第3节 细胞受体介导的细胞内信号转导","酶耦联受体的作用",2021,145,"X","","具有酶催化活性的受体有哪些",[["A","G蛋白偶联受体"],["B","表皮生长因子受体"],["C","核受体"],["D","转化生长因子受体"]],"BD","表皮生长因子受体（B对）和转化生长因子受体（D对）均属于酶联型受体，具有酶催化活性。G蛋白偶联受体（A错）不具有酶活性，其被配体激活后，通过改变分子构象而结合并激活G蛋白。核受体实质上是激素调控特定蛋白质转录的一大类转录调节因子，不具有酶催化活性（C错）。","","N"],["2021-N146",21,"第4节 胆色素的代谢与黄疸","胆红素来源",2021,146,"X","","能够经代谢生成胆红素的化合物有",[["A","血红蛋白"],["B","肌红蛋白"],["C","细胞色素"],["D","过氧化物酶"]],"ABCD","胆红素是铁卟啉类化合物的降解产物，体内铁卟啉类化合物包括血红蛋白（A对）、肌红蛋白（B对）、细胞色素（C对）、过氧化物酶（D对）和过氧化氢酶等。","","N"],["2021-N147",22,"第1节 血浆蛋白质","血浆蛋白质的性质",2021,147,"X","","血浆蛋白的特性",[["A","大多数在肝合成"],["B","大多数是糖蛋白"],["C","均为分泌型蛋白质"],["D","均为球蛋白"]],"ABC","绝大多数血浆蛋白质在肝合成（A对）。除白蛋白（清蛋白）外，几乎所有的血浆蛋白质均为糖蛋白（B对）。分泌型蛋白是指在细胞内合成后，分泌到细胞外起作用的蛋白质，血浆蛋白在肝细胞内或浆细胞（γ球蛋白）内合成后分泌入血，均为分泌型蛋白质（C对）。血浆蛋白是血浆中各种蛋白质成分的总称，除球蛋白外，血浆蛋白还包括白蛋白和纤维蛋白原等（D错）。","","N"],["2022-N17",0,"第3节 蛋白质结构与功能的关系","蛋白质一级结构是高级结构与功能的基础",2022,17,"A","","能够说明蛋白质一级结构是空间构象基础的例子是",[["A","血红蛋白与氧结合的正协同效应"],["B","肌红蛋白与血红素的结合"],["C","尿素对核糖核酸酶结构的影响"],["D","蛋白质构象改变引起疾病"]],"C","用尿素处理核糖核酸酶时（C对），核糖核酸酶的二、三级结构（空间构象）遭到破坏，但一级结构（氨基酸序列）仍存在，此时酶活性丧失殆尽。当用透析方法去除尿素后，该酶的空间构象可以一级结构为基础恢复至原来的结构，酶活性也能逐渐恢复至原来水平。","","N"],["2022-N18",2,"第4节 核酸的理化性质","紫外吸收",2022,18,"A","","通常用来鉴定核酸样品纯度的指标是",[["A","260nm/280nm吸光度比值"],["B","Tm值大小"],["C","DNA变性所需时间"],["D","样品中GC含量"]],"A","260nm是嘌呤和嘧啶所含共轭双键的最大紫外吸收光值，根据260nm处的吸光度（A₂₆₀），可以判断出溶液中的DNA或RNA的含量。280nm是色氨酸、酪氨酸所含共轭双键的最大紫外吸收光值，根据280nm处的吸光度（A₂₈₀），可以判断出溶液中蛋白质的含量。利用260nm与280nm的吸光度比值（A₂₆₀ / A₂₈₀）（A对）可以判断从生物样品中提取的核酸样品的纯度。DNA纯品的A₂₆₀ / A₂₈₀的比值应为1.8；而RNA纯品的A₂₆₀ / A₂₈₀的比值应为2.0。","","N"],["2022-N19",4,"第3节 糖的有氧氧化","糖有氧氧化的协调",2022,19,"A","","糖有氧氧化的调控机制是",[["A","无氧酵解对有氧氧化的抑制效应"],["B","NADH含量增加可促进有氧氧化"],["C","ATP/ADP比值影响调节酶的活性"],["D","糖异生与糖酵解底物循环的平衡"]],"C","糖有氧氧化的调节是为了适应机体对能量的需要，为此，细胞内ATP/ADP比值（C对）或ATP/AMP比值同时调节糖的有氧氧化各阶段中诸多关键酶的活性，使其流量调控始终保持协调一致。当细胞消耗ATP时，引起ADP和AMP浓度升高，别构激活磷酸果糖激酶-1、丙酮酸激酶、丙酮酸脱氢酶复合体、柠檬酸合酶、异柠檬酸脱氢酶以及氧化磷酸化的相关酶，加速进行有氧氧化以补充ATP。反之，当细胞内ATP充足时，上述酶的活性降低，从而减弱有氧氧化以避免浪费。","","N"],["2022-N20",5,"第1节 脂质的构成、功能及分析","脂肪酸的生物学功能",2022,20,"A","","体内花生四烯酸的生物学作用是",[["A","促进鞘氨醇代谢"],["B","成为脂肪酸合成酶的辅酶"],["C","抑制胆固醇转化"],["D","作为慢反应物质的前体"]],"D","花生四烯酸为二十碳多不饱和脂肪酸，前列腺素、血栓噁烷和白三烯均为其衍生物。慢反应物质为白三烯的混合物（LTC₄、LTD₄、LTE₄），因其促进平滑肌收缩的作用较组胺更加缓慢及持久而得名。故花生四烯酸的生物学作用之一是作为慢反应物质的前体（D对）。","","N"],["2022-N21",6,"第1节 营养必需氨基酸与氨基酸代谢概述","真核细胞内蛋白质的降解途径",2022,21,"A","","泛素化所涉及反应是",[["A","多肽链的生物合成"],["B","蛋白质亚基的聚合"],["C","消化道蛋白质的分解"],["D","体内蛋白质的降解"]],"D","真核细胞内蛋白质降解生成氨基酸有两条重要途径——溶酶体ATP非依赖途径和蛋白酶体ATP依赖途径。蛋白质经过蛋白酶体ATP依赖途径降解需要泛素的参与。泛素是一种由76个氨基酸组成的小分子蛋白质，因其广泛存在于真核细胞中而得名。泛素共价结合需要降解的蛋白质，对其进行标记——此过程即为泛素化（需消耗ATP），蛋白质经泛素化标记后，在蛋白酶体内被降解（D对）。消化道蛋白质的分解在机体分泌的各种消化酶作用下完成，不涉及泛素化（C错）。","","N"],["2022-N22",6,"第4节 个别氨基酸的代谢","甲硫氨酸循环",2022,22,"A","","维生素Ｂ₁₂直接参与的反应是",[["A","N⁵-甲基四氢叶酸的转甲基"],["B","色氨酸生成一碳单位"],["C","不同形式一碳单位相互转换"],["D","二氢叶酸转变为四氢叶酸"]],"A","维生素Ｂ₁₂是N⁵甲基四氢叶酸转甲基酶（甲硫氨酸合成酶）的辅酶（A对），可催化同型半胱氨酸甲基化生成甲硫氨酸，后者在腺苷转移酶的作用下生成活性甲基供体——S-腺苷甲硫氨酸。","","N"],["2022-N23",8,"第2节 嘌呤核苷酸的合成与分解代谢","利用腺嘌呤核苷生成嘌呤核苷酸",2022,23,"A","","次黄嘌呤-鸟嘌呤磷酸核糖转移酶缺乏导致的疾病是",[["A","阿尔兹海默症"],["B","帕金森病"],["C","Lesch-Nyhan综合征"],["D","镰状细胞贫血"]],"C","嘌呤核苷酸的合成途径包括从头合成和补救合成两条途径，次黄嘌呤-鸟嘌呤磷酸核糖转移酶（HGPRT）参与了IMP和GMP的补救合成途径。嘌呤核苷酸补救合成一方面可以节省从头合成时能量和一些氨基酸的消耗；另一方面，体内某些组织器官，例如脑、骨髓等由于缺乏从头合成嘌呤核苷酸的酶体系，它们只能进行嘌呤核苷酸的补救合成。因此，对这些组织器官来说，补救合成途径具有更重要的意义。例如，由于基因缺陷而导致次黄嘌呤-鸟嘌呤磷酸核糖转移酶（HGPRT）完全缺失的患儿，表现为莱施-奈恩综合征或称Lesch-Nyhan综合征（C对），这是一种遗传代谢病。阿尔茨海默病属于蛋白质构象疾病，为海马体淀粉样变所致（A错）。帕金森病是一种常见于中老年人的神经系统变性疾病，由于黑质多巴胺能神经元变性所致（B错）。镰状细胞贫血为遗传性血红蛋白病，因β链第6位氨基酸谷氨酸被缬氨酸代替（点突变），形成了异常的血红蛋白S（HbS），取代了正常血红蛋白（HbA）所致（D错）。","","N"],["2022-N24",11,"第3节 原核生物DNA复制过程","引物合成和起始复合物的形成",2022,24,"A","","原核DNA生物合成中引物酶的性质是",[["A","RNA聚合酶"],["B","DNA聚合酶"],["C","逆转录酶"],["D","解螺旋酶"]],"A","原核DNA生物合成起始时需要先合成引物， 引物是由引物酶催化合成的短链 RNA分子，可为DNA的合成提供3'-OH末端。故原核DNA生物合成中引物酶的性质是RNA聚合酶（A对）。","","N"],["2022-N25",13,"第3节 肽链的合成过程","成肽",2022,25,"A","","蛋白质生物合成时的肽酰转移酶的化学本质是",[["A","脂肪酸"],["B","RNA"],["C","DNA"],["D","多糖"]],"B","在肽链合成的延长过程中，核糖体上重复进行着进位、成肽和转位的循环过程，每循环1次，肽链上即可增加1个氨基酸残基。肽酰转移酶参与了其中的成肽过程，该酶的化学本质不是蛋白质，而是RNA（B对），在原核生物为23S rRNA，在真核生物为28S rRNA。因此，肽酰转移酶属于核酶的范畴。","","N"],["2022-N26",16,"第2节 重组DNA技术","质粒",2022,26,"A","","质粒的结构特点是",[["A","环状单链DNA分子"],["B","环状单链RNA分子"],["C","环状双链DNA分子"],["D","环状双链RNA分子"]],"C","质粒是细菌染色体外的、能自主复制和稳定遗传的双链环状DNA分子（C对），是重组DNA技术中最常用的克隆载体。","","N"],["2022-N27",17,"第3节 细胞受体介导的细胞内信号转导","细胞内受体的作用",2022,27,"A","","细胞内受体的性质是",[["A","转录因子"],["B","激素反应元件"],["C","酪氨酸激酶"],["D","表皮生长因子"]],"A","按照在细胞内的位置，受体分为细胞内受体和细胞表面受体两大类。其中位于细胞内的受体多为转录因子（A对）。当与相应配体结合后，能与DNA的顺式作用元件结合，在转录水平调节基因表达。","","N"],["2022-N28",22,"第2节 血红素的合成","在线粒体内合成ALA",2022,28,"A","","以磷酸吡哆醛作为辅酶参与血红素合成的酶是",[["A","ALA脱水酶"],["B","ALA合酶"],["C","亚铁螯合酶"],["D","胆色素原脱氨酶"]],"B","磷酸吡哆醛是体内百余种酶的辅酶，参与氨基酸脱氨基与转氨基作用、鸟氨酸循环、血红素的合成和糖原分解等，在代谢中发挥着重要作用。在血红素的合成过程中，以磷酸吡哆醛作为辅酶的是ALA合酶（B对），ALA合酶可催化由琥珀酰CoA与甘氨酸缩合生成 δ-氨基-γ-酮戊酸（ALA）的反应。","","N"],["2022-N120",5,"第3节 甘油三酯代谢","软脂酸合成的原料",2022,120,"B","","柠檬酸裂解酶催化生成的产物是",[["A","乙酰辅酶A"],["B","丙二酰辅酶A"],["C","异柠檬酸"],["D","α-酮戊二酸"]],"A","软脂酸和胆固醇的合成部位在细胞质，但用于软脂酸和胆固醇合成的乙酰CoA主要由葡萄糖分解供给，在线粒体内产生。乙酰CoA不能自由透过线粒体内膜，需通过柠檬酸-丙酮酸循环（十版生物化学P151）进入细胞质。在此循环中，乙酰 CoA 首先在线粒体内柠檬酸合酶催化下，与草酰乙酸缩合生成柠檬酸；后者通过线粒体内膜载体转运进入细胞质，被柠檬酸裂解酶裂解重新生成乙酰 CoA（A对）及草酰乙酸。","","N"],["2022-N121",4,"第3节 糖的有氧氧化","丙酮酸氧化脱羧",2022,121,"B","","丙酮酸脱氢酶复合体催化生成的产物是",[["A","乙酰辅酶A"],["B","丙二酰辅酶A"],["C","异柠檬酸"],["D","α-酮戊二酸"]],"A","丙酮酸脱氢酶复合体是一种位于线粒体基质的多酶复合物，由多种酶（丙酮酸脱氢酶、二氢硫辛酰胺转乙酰酶和二氢硫辛酰胺脱氢酶）及辅助因子（焦磷酸硫胺素、硫辛酸、FAD、NAD⁺、CoA）组成，可催化丙酮酸氧化脱羧生成乙酰CoA（A对）和CO₂。","","N"],["2022-N122",17,"第2节 细胞内信号转导分子","脂类衍生出的细胞内第二信使",2022,122,"B","","能与内质网Ca²⁺库受体结合的第二信使是",[["A","DAG"],["B","IP₃"],["C","cAMP"],["D","cGMP"]],"B","IP₃（B对）是水溶性分子，可在细胞内扩散至内质网或肌质网膜上，并与Ca²⁺库受体结合，结合IP3后开放，促进细胞钙库内的Ca²⁺迅速释放，细胞中局部Ca²⁺浓度迅速升高。","","N"],["2022-N123",17,"第2节 细胞内信号转导分子","环核苷酸类第二信使",2022,123,"B","","能激活蛋白质激酶A的第二信使是",[["A","DAG"],["B","IP₃"],["C","cAMP"],["D","cGMP"]],"C","cAMP（环腺苷酸）的下游分子是蛋白激酶A，即激活蛋白激酶A的第二信使是cAMP（C对）。DAG（甘油二酯）（A错）和IP₃（通过促使细胞质钙库释放Ca²⁺）（B错）能激活的是蛋白激酶C。cGMP（环鸟苷酸）（D错）能激活的是蛋白激酶G。","","N"],["2022-N142",1,"第2节 酶的工作原理","降低反应的活化能",2022,142,"X","","酶学中涉及的活化能的含义有",[["A","底物的自由能"],["B","底物从初态转变到过渡态所需的能量"],["C","底物转变为产物所需的能量"],["D","过渡态中间物比基态反应物高出的能量"]],"BD","活化能是指在一定温度下，1mol反应物从基态转变成过渡态所需要的自由能（B对C错），即过渡态中间物比基态反应物高出的那部分能量（D对）。底物的自由能（A错）是底物本身的特性，含自由能较低的反应物分子，很难发生化学反应。","","N"],["2022-N143",9,"第3节 代谢调节的主要方式","关键酶活性决定代谢途径的速率和方向",2022,143,"X","","下列关于代谢调节的叙述，正确的有",[["A","活性低的酶决定整个反应的速度"],["B","受别构调节的酶决定反应的类型"],["C","被化学修饰的酶决定反应的部位"],["D","催化单向反应的酶决定反应的方向"]],"AD","每条代谢途径由一系列酶促反应组成，其反应速率和方向由其中一个或具有调节作用的关键酶活性决定。这些关键酶的特点包括：①常催化第一步反应或分支点上的反应，活性低，决定整个反应的速度（A对）；②常催化单向反应或非平衡反应，其活性能决定整个代谢途径的方向（D对）；③酶活性除受底物控制外，还受多种代谢物或效应剂调节。别构调节（B错）和化学修饰调节（C错）可以改变酶的分子结构和酶的活性，影响酶促反应速度，不能决定酶促反应的类型或部位。","","N"],["2022-N144",0,"第1节 蛋白质的分子组成","氨基酸的基本结构单位",2022,144,"X","","可以作为蛋白质生物合成原料掺入多肽链中的氨基酸有",[["A","羟脯氨酸"],["B","半胱氨酸"],["C","硒代半胱氨酸"],["D","甲硫氨酸"]],"BCD","人体内的蛋白质是以20种基本氨基酸为原料合成的多聚体，半胱氨酸（B对）和甲硫氨酸（D对）均属于这20种基本氨基酸之一。除了20种基本的氨基酸外，近年发现硒代半胱氨酸（C对）在某些情况下也可用于合成蛋白质。羟脯氨酸（A错）是在蛋白质生物合成完成后，在脯氨酸的基础上，经羟化修饰而形成的。","","N"],["2022-N145",21,"第4节 胆色素的代谢与黄疸","胆红素来源",2022,145,"X","","体内含有铁卟啉并可以生成胆红素的物质有",[["A","血红蛋白"],["B","肌红蛋白"],["C","过氧化氢酶"],["D","过氧化物酶"]],"ABCD","胆红素是铁卟啉类化合物的降解产物，体内铁卟啉类化合物包括血红蛋白（A对）、肌红蛋白（B对）、红细胞色素、过氧化氢酶（C对）和过氧化氢物酶（D对）。","","N"],["2022-N146",3,"第1节 脂溶性维生素","脂溶性维生素的概述",2022,146,"X","","已知可以调节基因转录的维生素或其代谢产物有",[["A","维生素A"],["B","维生素D"],["C","维生素E"],["D","维生素K"]],"ABC","维生素A、维生素D、维生素E和维生素K均为脂溶性维生素。其中维生素A（视黄酸）（A对）能调节细胞生长、发育和分化相关基因的表达；维生素D（B对）可以调节钙结合蛋白基因和骨钙蛋白基因的表达；维生素E（C对）能调节生育酚相关基因、动脉硬化相关基因、细胞黏附与炎症的相关基因等众多基因的表达，以上均参与基因转录的调节。维生素K（D错）的生物学功能为参与凝血、骨代谢、减少动脉钙化，各版本教材未提及其是否参与基因转录调节，维生素K虽为脂溶性维生素，但是否存在对应的核受体，根据目前相关研究的进展无确定结果，有文献报道维生素K可能参与细胞凋亡，调节凋亡基因的表达，但机制尚不清楚。","","N"],["2022-N147",15,"第2节 聚合酶链反应技术","PCR技术的作用",2022,147,"X","","PCR技术的用途有",[["A","基因表达的检测"],["B","基因变异的分析"],["C","基因片段的获得"],["D","基因序列的突变"]],"ABCD","PCR中文名聚合酶链式反应，是一种用于放大扩增特定的DNA片段的分子生物学技术，PCR技术的主要用途有：①基因片段的获得（C对）；②DNA和RNA的微量分析；③DNA序列分析；④基因变异的分析（B对）；⑤基因的体外突变（D对）。PCR技术与其他分子生物学技术的结合，形成多种PCR 衍生技术，如逆转录PCR技术、原位PCR 技术、实时PCR技术等，其中实时PCR技术可对基因表达水平进行检测（A对）。该题默认PCR技术包括PCR衍生技术，故ABCD均正确。","","N"],["2023-N17",0,"第2节 蛋白质的分子结构","结构域",2023,17,"A","","蛋白质结构域的结构层次是",[["A","一级结构"],["B","α螺旋"],["C","β折叠"],["D","三级结构"]],"D","分子量较大的蛋白质常可折叠成多个结构较为紧密且稳定的区域，并各行其功能，称为结构域。结构域是三级结构（D对）层次上具有独立结构与功能的区域。α螺旋（B错）和β折叠（C错）为常见的蛋白质二级结构。","","N"],["2023-N18",1,"第4节 酶的调节","酶含量的调节",2023,18,"A","","下列关于酶促反应调节的叙述，错误的是",[["A","酶蛋白质可通过构象变化被调节"],["B","酶蛋白质可通过共价修饰被调节"],["C","酶原通过激活过程产生有活性的酶"],["D","酶蛋白质合成属于酶的快速调节"]],"D","根据对酶促反应的调节速率不同，酶促反应调节可分为快速调节和慢速调节两种。快速调节主要通过调节酶活性实现，酶蛋白质通过构象变化被调节（变构调节）（A对）和通过共价修饰被调节（化学修饰）（B对），属于对酶活性的快速调节。慢速调节主要通过调节酶含量实现，细胞可通过改变酶蛋白合成与降解的速率来调节酶的含量，故酶蛋白合成属于酶的慢速调节（D错，为本题正确答案）。有些酶在细胞内合成或初分泌、或在其发挥催化功能前处于无活性状态，这种无活性的酶的前体称作酶原，酶原需要通过激活过程才能转变为有活性的酶（C对）。","","N"],["2023-N19",1,"第1节 酶的分子结构与功能","酶的分子组成",2023,19,"A","","NAD⁺和NADP⁺所含的维生素是",[["A","维生素B₁"],["B","维生素B₂"],["C","维生素PP"],["D","维生素K"]],"C","酶按其分子组成可分为单纯酶和缀合酶，单纯酶只含酶蛋白，缀合酶由酶蛋白和辅因子组成，辅因子按其与酶蛋白结合的紧密程度与作用特点不同又可分为辅酶和辅基。辅因子多为小分子的有机化合物或金属离子。作为辅因子的有机化合物多为B族维生素的衍生物（维生素B₁、维生素B₂、维生素PP、泛酸、生物素、维生素B₆、叶酸与维生素B₁₂），它们在酶促反应中主要参与传递电子、质子（或基团）或起运载体作用。NAD⁺（烟酰胺腺嘌呤二核苷酸，辅酶Ⅰ）和NADP⁺（烟酰胺腺嘌呤二核苷酸磷酸，辅酶Ⅱ）主要作为脱氢酶的辅酶，在酶促反应中起递氢体（传递质子）的作用，所含的维生素为维生素PP（C对）。含维生素B₁的辅酶是焦磷酸硫胺素（TPP）（A错）。含维生素B₂的辅酶是黄素单核苷酸（FMN）和黄素腺嘌呤二核苷酸（FAD）（B错）。维生素K（十版生物化学P96）为凝血因子合成所必需的γ-谷氨酰羧化酶的辅酶（D错）。","","N"],["2023-N20",4,"第2节 糖的无氧氧化","丙酮酸激酶",2023,20,"A","","催化磷酸烯醇式丙酮酸转变为丙酮酸并产生ATP的酶是",[["A","醛缩酶"],["B","磷酸甘油酸激酶"],["C","丙酮酸激酶"],["D","丙酮酸脱氢酶"]],"C","糖酵解的最后一步反应为磷酸烯醇式丙酮酸在丙酮酸激酶（C对）的催化下，发生底物水平磷酸化，生成丙酮酸和ATP。醛缩酶（A错）催化果糖-1，6-二磷酸裂解成磷酸二羟丙酮和3-磷酸甘油醛。磷酸甘油酸激酶（B错）催化1，3-二磷酸甘油酸转变成3-磷酸甘油酸。丙酮酸脱氢酶（D错）催化丙酮酸脱羧生成乙酰 CoA。","","N"],["2023-N21",5,"第3节 甘油三酯代谢","脂肪酰CoA进入线粒体",2023,21,"A","","脂肪酸β氧化途径的限速酶是",[["A","脂酰CoA合成酶"],["B","肉碱脂酰转移酶Ⅰ"],["C","脂酰CoA脱氢酶"],["D","β-酮脂酰CoA硫解酶"]],"B","脂肪酸被氧化前必须先活化为脂酰CoA，活化过程在胞液中进行。活化的脂酰CoA必须从胞液进入线粒体才能被氧化，长链脂酰CoA不能直接透过线粒体内膜，需要肉碱 协助转运。存在于线粒体外膜的肉碱脂酰转移酶Ⅰ催化长链脂酰CoA与肉碱合成脂酰肉碱，后者在线粒体内膜肉碱-脂酰肉碱转位酶作用下，通过内膜进入线粒体基质，同时将等分子肉碱转运出线粒体。进入线粒体的脂酰肉碱，在线粒体内膜内侧肉碱脂酰转移酶Ⅱ作用下，转变为脂酰CoA并释出肉碱。脂酰CoA进入线粒体是脂肪酸β-氧化的限速步骤，肉碱脂酰转移酶Ⅰ（B对）是脂肪酸β-氧化的关键酶。当饥饿、高脂低糖膳食或糖尿病时，机体没有充足的糖供应，或不能有效利用糖，需脂肪酸供能，肉碱脂酰转移酶Ⅰ活性增加，脂肪酸氧化增强。相反，饱食后脂肪酸合成加强，丙二酸单酰CoA含量增加，抑制肉碱脂酰转移酶Ⅰ活性，使脂肪酸的氧化被抑制。脂酰CoA合成酶（A错）为在胞液中催化脂肪酸活化成脂酰CoA的酶。脂酰CoA脱氢酶（C错）和β-酮脂酰CoA硫解酶（D错）为催化脂酰CoA在线粒体中进行β-氧化的酶。","","N"],["2023-N22",7,"第3节 氧化磷酸化与ATP的生成","氧化磷酸化耦联部位的概述",2023,22,"A","","呼吸链复合体中不存在氧化磷酸化偶联部位的是",[["A","复合体Ⅰ"],["B","复合体Ⅱ"],["C","复合体Ⅲ"],["D","复合体Ⅳ"]],"B","氧化磷酸化在线粒体中进行，包含两个关键过程，一是电子传递，二是将电子传递过程中释放的能量用于产生ATP，使能量通过ATP被储存起来供机体使用。呼吸链中能够产生足够的能量使ADP磷酸化的部位称为氧化磷酸化偶联部位，也就是能够生成 ATP 的部位。根据实验测算，复合体Ⅰ（A对）、Ⅲ（C对）、Ⅳ（D对）中可能存在氧化磷酸化的偶联部位，用于产生ATP，而复合体Ⅱ（B错，为本题正确答案）中不存在氧化磷酸化偶联部位。","","N"],["2023-N23",6,"第3节 氨的代谢","精氨酸代琥珀酸合成酶",2023,23,"A","","下列酶中，调节尿素合成的关键酶是",[["A","鸟氨酸氨基甲酰转移酶"],["B","精氨酸代琥珀酸合成酶"],["C","精氨酸代琥珀酸裂解酶"],["D","精氨酸酶"]],"B","调节尿素合成的关键酶是精氨酸代琥珀酸合成酶（B对），该酶可催化瓜氨酸与天冬氨酸反应生成精氨酸代琥珀酸。鸟氨酸氨基甲酰转移酶（A错）、精氨酸代琥珀酸裂解酶（C错）和精氨酸酶（D错）均为参与尿素合成的非关键酶。","","N"],["2023-N24",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成途径的概述",2023,24,"A","","不直接参与合成嘌呤核苷酸的物质是",[["A","谷氨酰胺"],["B","天冬氨酸"],["C","丝氨酸"],["D","一碳单位"]],"C","直接参与合成嘌呤核苷酸的物质包括谷氨酰胺（A对）、甘氨酸、天冬氨酸（B对）、CO₂和一碳单位（D对）。丝氨酸（C错，为本题正确答案）是甘油磷脂（十版生物化学P155）和鞘磷脂（十版生物化学P158）的重要合成原料。","","N"],["2023-N25",18,"第2节 DNA损伤修复","DNA损伤的修复途径概述",2023,25,"A","","具有修复双链断裂DNA损伤的修复系统是",[["A","错配修复"],["B","直接修复"],["C","重组修复"],["D","碱基切除修复"]],"C","双链DNA分子中的一条链断裂，可被模板依赖的DNA修复系统修复，不会给细胞带来严重后果。然而，DNA分子的双链断裂是一种极为严重的损伤。与其他修复方式不同的是，双链断裂修复由于没有互补链可言，因此难以直接提供修复断裂所必需的互补序列信息。为此，需要另外一种更为复杂的机制，即重组修复（C对）来完成DNA双链断裂的修复。重组修复是指依靠重组酶系，将另一段未受损伤的DNA移到损伤部位，提供正确的模板，进行修复的过程，依据机制的不同，重组修复可分为同源重组修复和非同源末端连接重组修复。","","N"],["2023-N26",13,"第2节 蛋白质合成体系","遗传密码的特点",2023,26,"A","","下列遗传密码特点中，与移码突变密切相关的是",[["A","通用性"],["B","方向性"],["C","连续性"],["D","摆动性"]],"C","与移码突变有关的是密码子的连续性（C对），密码子的连续性是指在mRNA上，从起始密码子到终止密码子，密码子的排列是连续的，既没有重叠也没有间隔。因密码子具有连续性，若可读框中插入或缺失了非3的倍数的核苷酸，将会引起mRNA可读框发生移动，称为移码，移码导致后续氨基酸编码序列改变，使得其编码的蛋白质彻底丧失或改变原有功能，称为移码突变。","","N"],["2023-N27",14,"第3节 真核基因表达调控","转录因子的DNA结合结构域",2023,27,"A","","真核生物转录因子结构中，属于转录激活结构域的是",[["A","锌指结构"],["B","螺旋-环-螺旋"],["C","亮氨酸拉链"],["D","富含谷氨酰胺结构域"]],"D","转录因子是DNA结合蛋白，至少包括两个不同的结构域：DNA结合结构域和转录激活结构域。常见的转录因子的DNA结合结构域包括锌指结构（A错）、螺旋-环-螺旋（B错）和亮氨酸拉链（C错）。常见的转录激活结构域包括酸性激活结构域、富含谷氨酰胺结构域（D对）和富含脯氨酸结构域。","","N"],["2023-N28",15,"第4节 生物分子相互作用研究技术","电泳迁移率变动分析",2023,28,"A","","目前常用于分析体内DNA与蛋白质相互作用的分子生物学技术是",[["A","标签蛋白沉淀"],["B","凝胶迁移变动分析"],["C","蛋白质印迹技术"],["D","酵母双杂交"]],"B","目前常用于分析体内DNA与蛋白质相互作用的分子生物学技术包括电泳迁移率变动分析（凝胶迁移变动分析）（B对）和染色质免疫沉淀技术。标签蛋白沉淀（十版生物化学P348） （A错）和酵母双杂交（十版生物化学P348）（D错）是研究蛋白质与蛋白质相互作用的技术。蛋白质印迹技术（十版生物化学P338）（C错）主要用于蛋白质的定性及半定量检测，也可以用于研究蛋白质与蛋白质相互作用。","","N"],["2023-N120",4,"第6节 糖异生","果糖-1，6-二磷酸水解为果糖-6-磷酸",2023,120,"B","","糖异生途径的重要中间产物是",[["A","6-磷酸葡萄糖酸"],["B","磷酸戊糖"],["C","果糖-6-磷酸"],["D","尿苷二磷酸葡萄糖"]],"C","糖异生有3个限速步骤，其中一个限速步骤为果糖二磷酸酶-1催化果糖-1，6-二磷酸生成果糖-6-磷酸，因此果糖-6-磷酸（C对）是糖异生的重要中间产物。6-磷酸葡萄糖酸（A错）和磷酸戊糖（B错）是磷酸戊糖途径的中间产物。尿苷二磷酸葡萄糖（D错）是糖原合成的中间产物。","","N"],["2023-N121",4,"第5节 糖原的合成与分解","糖原合成",2023,121,"B","","糖原合成的重要中间产物是",[["A","6-磷酸葡萄糖酸"],["B","磷酸戊糖"],["C","果糖-6-磷酸"],["D","尿苷二磷酸葡萄糖"]],"D","糖原合成起始于糖酵解的中间产物葡糖-6-磷酸。首先，葡糖-6-磷酸变构生成葡糖-1-磷酸。后者再与尿苷三磷酸（UTP）反应生成尿苷二磷酸葡萄糖（UDPG）（D对）和焦磷酸。6-磷酸葡萄糖酸（A错）和磷酸戊糖（B错）是磷酸戊糖途径的中间产物。果糖-6-磷酸（C错）是糖酵解和糖异生的重要中间产物。","","N"],["2023-N122",5,"第3节 甘油三酯代谢","酮体的氧化利用",2023,122,"B","","参与酮体分解的酶是",[["A","HMG CoA合酶"],["B","HMG CoA裂解酶"],["C","HMG CoA还原酶"],["D","琥珀酰CoA转硫酶"]],"D","在心、肾、脑及骨骼肌线粒体，酮体之一的乙酰乙酸可由琥珀酰CoA转硫酶（D对）催化生成乙酰乙酰CoA，乙酰乙酰CoA再由乙酰乙酰CoA硫解酶催化生成乙酰 CoA完成分解过程。HMG CoA合酶（A错）是参与酮体合成（十版生物化学P149）和胆固醇合成（十版生物化学P159）的酶。HMG CoA裂解酶（B错）是参与酮体合成的酶。HMG CoA还原酶（C错）是参与胆固醇合成的酶。","","N"],["2023-N123",5,"第5节 胆固醇代谢","胆固醇的合成过程",2023,123,"B","","内源性胆固醇合成的关键酶是",[["A","HMG CoA合酶"],["B","HMG CoA裂解酶"],["C","HMG CoA还原酶"],["D","琥珀酰CoA转硫酶"]],"C","内源性胆固醇合成第一个阶段为甲羟戊酸的合成：2分子乙酰 CoA 在乙酰乙酰CoA硫解酶作用下，缩合成乙酰乙酰CoA；再在HMG-CoA合酶（A错）作用下，与1分子乙酰CoA缩合成羟基甲基戊二酸单酰CoA（HMG-CoA）。在线粒体中，HMG CoA经HMG CoA裂解酶（B错）催化生成酮体；在细胞质中，HMG CoA则在HMG CoA还原酶催化下，生成胆固醇的前体甲羟戊酸，而HMG CoA还原酶（C对）正是内源性胆固醇合成的关键酶。琥珀酰CoA转硫酶（十版生物化学P149）（D错）是参与酮体乙酰乙酸分解的酶。","","N"],["2023-N142",22,"第3节 血细胞物质代谢","成熟红细胞代谢特点的概述",2023,142,"X","","成熟红细胞内的代谢途径有",[["A","糖酵解"],["B","磷酸戊糖旁路"],["C","脂肪酸β氧化"],["D","尿素生成"]],"AB","哺乳动物的成熟红细胞除质膜和胞质外，无细胞核和线粒体等细胞器，其代谢比一般细胞单纯。葡萄糖是成熟红细胞的主要能量物质，血液循环中的红细胞每天从血浆中摄取的葡萄糖中，大部分经糖酵解（A对）和2， 3-二磷酸甘油酸支路（2， 3-BPG）进行代谢，小部分通过磷酸戊糖旁路（B对）进行代谢。","","N"],["2023-N143",21,"第2节 肝的生物转化作用","肝生物转化的过程",2023,143,"X","","参与肝生物转化Ⅰ相反应的酶有",[["A","细胞色素P₄₅₀单加氧酶"],["B","醇脱氢酶"],["C","单胺氧化酶"],["D","UDP-葡萄糖醛酸基转移酶"]],"ABC","肝的生物转化涉及多种酶促反应，但总体上可分为两相反应。第一相反应包括氧化、还原和水解。许多物质通过第一相反应，其分子中的某些非极性基团转变为极性基团，水溶性增加，即可排出体外。但有些物质经过笫一相反应后水溶性和极性改变不明显，还需要结合极性更强的物质或基团，以进一步增加其水溶性而促进排泄，这些结合反应属于第二相反应。细胞色素P₄₅₀单加氧酶（A对）、醇脱氢酶（B对）和单胺氧化酶（C对）均属于参与肝生物转化第一相反应的氧化酶。UDP-葡萄糖醛酸基转移酶（D错）是参与肝生物转化第二相反应最重要的酶，可以尿苷二磷酸葡糖醛酸（UDPGA）为葡糖醛酸的活性供体，催化代谢物与葡糖醛酸的结合反应。","","N"],["2023-N144",14,"第2节 原核基因表达调控","乳糖操纵子的双重调节",2023,144,"X","","原核生物基因表达调控的方式有",[["A","阻遏蛋白封闭启动子的负调控"],["B","cAMP-CAP介导的正调控"],["C","转录衰减调控"],["D","RNA编辑"]],"ABC","原核生物大多数基因表达调控是通过操纵子机制实现的。阻遏蛋白封闭启动子的负调控（A对）和cAMP-CAP介导的正调控（B对）存在于大肠杆菌乳糖操纵子的表达调控中。转录衰减调控（C对）见于大肠杆菌色氨酸操纵子的表达调控中。RNA编辑（十版生物化学P289）（D错）是真核生物对基因的编码序列进行转录后加工的过程。","","N"],["2023-N145",17,"第3节 细胞受体介导的细胞内信号转导","酶耦联受体的作用",2023,145,"X","","下列属于蛋白质激酶偶联受体介导的信号转导通路有",[["A","MAPK通路"],["B","JAK-STAT通路"],["C","PI-3K通路"],["D","经典核受体通路"]],"ABC","信号转导通路有两种基本类型。一种是膜受体介导（受体位于细胞膜中）的信号通路，包括离子通道型受体介导的信号通路、G 蛋白耦联受体介导的信号通路、酶联型受体介导的信号通路和招募型受体介导的信号通路等多种类型。其中酶联型受体（蛋白质激酶偶联受体，受体本身具有酶的活性或与酶相结合）介导的信号通路，目前已发现的有十几条，最常见的是MAPK通路（A对），此外还包括JAK-STAT通路（B对）、Smad通路、PI-3K通路（C对）、NF-κB通路等。除膜受体介导的信号通路外，另外一种信号通路为核受体介导的信号通路（受体位于胞质内或胞核内）（D错）。","","N"],["2023-N146",19,"第2节 癌基因","生长因子的分类及作用机制",2023,146,"X","","下列原癌基因中，编码的蛋白质属于转录因子的有",[["A","MYC"],["B","FOS"],["C","HER-2"],["D","EGFR"]],"AB","原癌基因编码的蛋白质与生长因子的信号转导密切相关，依据在细胞信号转导过程中发挥的作用不同分为四类，分别为细胞外生长因子、跨膜生长因子受体、细胞内信号转导分子和核内转录因子。MYC（A对）和FOS（B对）属于核内转录因子。HER-2（C错）和EGFR（D错）属于跨膜生长因子受体。","","N"],["2023-N147",16,"第2节 重组DNA技术","常用工具酶",2023,147,"X","","重组DNA技术中常用的工具酶有",[["A","限制性核酸内切酶"],["B","DNA聚合酶Ⅰ"],["C","DNA连接酶"],["D","逆转录酶"]],"ABCD","重组DNA技术中常用的工具酶包括限制性核酸内切酶（RE）（A对）、DNA连接酶（C对）、DNA聚合酶Ⅰ（B对）、Klenow片段、逆转录酶（D对）、多聚核苷酸激酶、末端转移酶、碱性磷酸酶等。","","N"],["2024-N17",0,"第2节 蛋白质的分子结构","结构模体",2024,17,"A","","下列蛋白质结构中，不属于蛋白质模体的是",[["A","α-螺旋-β-转角-α-螺旋"],["B","α-螺旋"],["C","亮氨酸拉链"],["D","锌指结构"]],"B","蛋白质结构模体是蛋白质分子中具有特定空间构象和特定功能的结构成分，由2个或2个以上具有二级结构的肽段在空间上相互接近，形成一个有规则的二级结构组合，属于超二级结构。α-螺旋-β-折叠-α-螺旋（A对）、亮氨酸拉链（C对）、锌指结构（D对）均属于结构模体，而α-螺旋属于蛋白质的二级结构（B错，为本题正确答案）。","","N"],["2024-N18",2,"第3节 RNA和空间结构与功能","非编码RNA的功能",2024,18,"A","","下列RNA中，属于长链非编码RNA的是",[["A","tRNA"],["B","siRNA"],["C","miRNA"],["D","lncRNA"]],"D","非编码RNA包括组成性非编码RNA和调控性非编码RNA，其中调控性非编码RNA按大小可分为非编码小RNA（sncRNA）、长非编码RNA（lncRNA）和环状RNA（circRNA）。lncRNA（D对）是一类长度200～100000个核苷酸的RNA分子，属于长非编码RNA，它不编码任何蛋白质，可从染色质重构、转录调控以及转录后加工等多个层面实现对基因表达的调控。tRNA（A错）属于组成性非编码RNA，由74～94个核苷酸组成，它的主要功能是在蛋白质合成过程中将氨基酸输送到核糖体。siRNA（干扰小RNA）（B错）和miRNA（微RNA）（C错）均属于非编码小RNA，siRNA可以诱导mRNA的降解，也可以抑制转录；miRNA可在转录后水平调节靶基因的表达。","","N"],["2024-N19",1,"第1节 酶的分子结构与功能","酶的分子组成",2024,19,"A","","在酰基转移酶类中的辅酶A所含的维生素是",[["A","维生素B₁"],["B","泛酸"],["C","生物素"],["D","叶酸"]],"B","酶按其分子组成可分为单纯酶和缀合酶，单纯酶只含酶蛋白，缀合酶由酶蛋白和辅因子组成，辅因子多为小分子的有机化合物或金属离子。作为辅因子的有机化合物多为B族维生素的衍生物或卟啉化合物（维生素B₁、维生素B₂、维生素PP、泛酸、生物素、维生素B₆、叶酸与维生素B₁₂），它们在酶促反应中主要参与传递电子、质子（或基团）或起运载体作用。辅酶A（CoA）在酶促反应中传递酰基，所含的维生素为泛酸（B对），即维生素B₅。含维生素B₁（A错）的辅酶是焦磷酸硫胺素（TPP）。含生物素（C错）的辅酶是为生物素，主要参与二氧化碳的羧化。叶酸（D错）为四氢叶酸的辅酶，主要转移一碳单位，参与氨基酸的分解代谢和嘌呤、嘧啶的合成。","","N"],["2024-N20",1,"第4节 酶的调节","酶含量的调节",2024,20,"A","","下列酶调节方式中，属于缓慢调节的是",[["A","别构调节"],["B","酶磷酸化修饰调节"],["C","酶原激活"],["D","酶泛素化修饰调节"]],"D","根据对酶促反应的调节速率不同，酶促反应调节可分为快速调节和慢速调节两种。慢速调节主要通过调节酶含量实现，细胞可通过改变酶蛋白合成与降解的速率来调节酶的含量，酶的泛素化修饰（D对）为酶的降解方式之一，可以改变酶的含量，属于缓慢调节。快速调节主要通过调节酶活性实现，别构调节（A错）、酶的磷酸化修饰调节（B错）及酶原激活（C错）均可调节酶的活性，属于快速调节。","","N"],["2024-N21",4,"第3节 糖的有氧氧化","三羧酸循环的过程",2024,21,"A","","下列参与三羧酸循环的酶中，催化脱羧的酶是",[["A","琥珀酸脱氢酶"],["B","延胡索酸酶"],["C","异柠檬酸脱氢酶"],["D","苹果酸脱氢酶"]],"C","三羧酸循环在三大营养物质代谢中占核心地位，共包括八步反应，涉及多种酶促反应。脱羧基反应是从有机酸上移除羧基（-COOH）的反应，三羧酸循环过程中共有两次脱羧基反应，第一次为异柠檬酸在异柠檬酸脱氢酶（C对）催化下氧化脱羧转变为α-酮戊二酸，第二次为α-酮戊二酸在α-酮戊二酸脱氢酶复合体催化下氧化脱羧生成琥珀酰CoA。","","N"],["2024-N22",5,"第3节 甘油三酯代谢","酮体的生成",2024,22,"A","","下列代谢途径中，提供酮体合成原料乙酰CoA的是",[["A","糖酵解"],["B","糖有氧氧化"],["C","脂肪酸β氧化"],["D","鸟氨酸循环"]],"C","乙酰CoA是三大营养物质的终产物，也是代谢的共同中间产物。在长时间禁食的情况下，机体以脂肪酸β氧化（C对）生成的乙酰CoA为原料生成酮体。正常进食情况下，经“糖酵解”（A错）和“糖有氧氧化”（B错）也可以产生乙酰CoA，但这些乙酰CoA主要用于三羧酸循环彻底氧化生成能量或合成其他生物分子，如脂肪酸和胆固醇，而不是用于酮体合成。鸟氨酸循环（D错）是氨的代谢途径之一，与乙酰CoA生成无关。","","N"],["2024-N23",7,"第2节 线粒体氧化体系与呼吸链","苹果酸-天冬氨酸穿梭",2024,23,"A","","下列化合物中，参与肝细胞质NADH转运至线粒体呼吸链的分子是",[["A","戊糖磷酸"],["B","磷酸二羟丙酮"],["C","丙氨酸"],["D","天冬氨酸"]],"D","胞质中的NADH通过两种穿梭机制进入线粒体的氧化呼吸链：①α-磷酸甘油穿梭（3-磷酸甘油-磷酸二羟丙酮穿梭），该穿梭机制主要存在于脑和骨骼肌中，磷酸二羟丙酮（B错）参与该途径。②苹果酸-天冬氨酸穿梭，该穿梭机制主要存在于肝和心肌中，苹果酸和天冬氨酸（D对）参与该途径。丙氨酸（C错）可通过丙氨酸-葡萄糖循环（十版生物化学P181）参与从骨骼肌向肝转运氨的过程。磷酸戊糖（A错）为磷酸戊糖途径生成的代谢产物，为合成核苷酸的原料，与NADH转运无关。","","N"],["2024-N24",6,"第4节 个别氨基酸的代谢","苯丙氨酸的代谢",2024,24,"A","","导致苯丙酮尿症的原因是",[["A","酪氨酸转氨酶缺陷"],["B","酪氨酸羟化酶缺陷"],["C","苯丙氨酸转氨酶缺陷"],["D","苯丙氨酸羟化酶缺陷"]],"D","正常情况下，苯丙氨酸的主要代谢途径是在苯丙氨酸羟化酶的催化下生成酪氨酸，仅有少量苯丙氨酸可在苯丙氨酸转氨酶的催化下化生成苯丙酮酸。体内苯丙氨酸羟化酶缺陷（D对）时，苯丙氨酸不能被羟化为酪氨酸，只能在苯丙氨酸转氨酶催化下生成苯丙酮酸，大量苯丙酮酸及其部分代谢产物由尿排出，称为苯丙酮酸尿症。","","N"],["2024-N25",8,"第2节 嘌呤核苷酸的合成与分解代谢","IMP转变为AMP和GMP",2024,25,"A","","嘌呤核苷酸合成中，IMP转变生成AMP的重要中间产物是",[["A","XMP"],["B","GMP"],["C","腺苷酸代琥珀酸"],["D","S-腺苷甲硫氨酸"]],"C","嘌呤核苷酸的从头合成途径主要包括两个阶段：①合成次黄嘌呤核苷酸（IMP）；②IMP再转变成腺嘌呤核苷酸（AMP）与鸟嘌呤核苷酸（GMP）。第二个阶段的反应为IMP→腺苷酸代琥珀酸→AMP或IMP→XMP→GMP。因此，腺苷酸代琥珀酸（C对）是IMP转变生成AMP的中间产物，而XMP（A错）为IMP转变生成GMP（B错）的中间产物。S-腺苷甲硫氨酸（十版生物化学P189）（D错）为体内甲基最重要的直接供体，不参与IMP转变生成AMP的过程。","","N"],["2024-N26",11,"第2节 DNA复制的酶学和拓扑学","真核细胞DNA聚合酶",2024,26,"A","","参与真核生物线粒体DNA复制的酶是",[["A","DNA聚合酶α"],["B","DNA聚合酶β"],["C","DNA聚合酶γ"],["D","DNA聚合酶δ"]],"C","真核细胞中主要的复制酶（DNA聚合酶）有5种：①DNA聚合酶α（A错）具有引物酶活性；②DNA聚合酶β（B错）复制的保真度高，可能是参与应急修复的酶；③DNA聚合酶γ（C对）是线粒体DNA复制的酶；④DNA聚合酶δ负责合成后随链（D错）；⑤DNA聚合酶ε负责合成前导链。","","N"],["2024-N27",12,"第3节 真核生物mRNA的转录、加工和降解","前体mRNA的剪接",2024,27,"A","","某基因的外显子1编码蛋白质A，外显子1～2、4编码蛋白质B，蛋白质B的转录后加工机制不同于蛋白质A的是",[["A","前体mRNA剪切"],["B","前体mRNA的选择性剪接"],["C","mRNA编辑"],["D","无义介导的mRNA降解"]],"B","本题涉及的是基因转录后加工过程中前体mRNA的选择性剪接。在这个过程中，前体mRNA中的内含子被去除，外显子被保留并按照特定的顺序连接在一起。编码蛋白质A的外显子只有1个（外显子1），因此在转录后的加工过程中，只需要去除两端的内含子，不需要进行外显子之间的选择性剪接。而编码蛋白质B的外显子有3个（外显子1～2、4），在转录后的加工过程中，除了去除两端的内含子外，还需要进行外显子之间的选择性剪接，将外显子1～2、4按照正确的顺序连接在一起。因此，蛋白质B的转录后加工过程与蛋白质A相比，主要的差异在于前体mRNA的选择性剪接（B对）。剪切指（十版生物化学P289）（A错）的是剪去某些内含子后，在上游的外显子3’-端再进行多聚腺苷酸化，不进行相邻外显子之间的连接反应。mRNA编辑（十版生物化学P289）（C错）是指有些基因的蛋白质产物的氨基酸序列与基因的初级转录物序列并不完全对应，mRNA上的一些序列在转录后发生了改变。无义介导的mRNA降解（十版生物化学P291）（D错）是指机体可以通过识别和降解含有提前终止密码子（PTC）的转录产物，防止有潜在毒性的截短蛋白的产生。","","N"],["2024-N28",17,"第3节 细胞受体介导的细胞内信号转导","IP₃_DAG-PKC通路",2024,28,"A","","下列属于G蛋白偶联受体信号传递途径的是",[["A","Smad途径"],["B","JAK-STAT途径"],["C","IP₃/DAG-PKC途径"],["D","NF-κB途径"]],"C","G蛋白偶联受体可通过不同的信号传导途径传递信号，其中常见的有3种：①cAMP-PKA途径；②IP₃/DAG-PKC途径（C对）；③Ca²⁺/钙调蛋白依赖的蛋白激酶途径。Smad途径（A错）、JAK-STAT途径（B错）、NF-κB途径（D错）途径属于蛋白激酶偶联受体介导的信号转导途径（十版生物化学P397）。","","N"],["2024-N120",4,"第2节 糖的无氧氧化","糖酵解",2024,120,"B","","糖酵解和戊糖磷酸途径共同的重要中间产物是",[["A","果糖-6-磷酸"],["B","果糖-1，6-二磷酸"],["C","葡萄糖-6-磷酸"],["D","6-磷酸葡萄糖酸内酯"]],"C","糖酵解与磷酸戊糖途径的共同中间产物是葡萄糖-6-磷酸（C对）：在糖酵解途径中，葡萄糖-6-磷酸经磷酸己糖异构酶催化生成果糖-6-磷酸（十版生物化学P108）；在磷酸戊糖途径中，葡萄糖-6-磷酸经葡糖-6磷酸脱氢酶催化生成6-磷酸葡萄糖内酯（十版生物化学P121）。","","N"],["2024-N121",4,"第5节 糖原的合成与分解","糖原合成",2024,121,"B","","糖原合成和糖原分解途径共同的重要中间产物是",[["A","果糖-6-磷酸"],["B","果糖-1，6-二磷酸"],["C","葡萄糖-6-磷酸"],["D","6-磷酸葡萄糖酸内酯"]],"C","糖原合成与糖原分解途径共同的重要中间产物是葡萄糖-6-磷酸（C对）：在糖原合成过程中，葡萄糖-6-磷酸经磷酸葡萄糖变位酶催化生成1-磷酸葡萄糖（十版生物化学P124）；在糖原分解过程中，葡萄糖-6-磷酸在肝内经葡萄糖-6-磷酸酶催化生成葡萄糖释放到血液中（十版生物化学P125），在肌组织中经磷酸己糖异构酶催化生成果糖-6-磷酸进入糖酵解途径产生能量（十版生物化学P126）。","","N"],["2024-N122",5,"第3节 甘油三酯代谢","软脂酸合成的原料",2024,122,"B","","脂肪酸合成的原料是",[["A","乙酰CoA"],["B","脂肪酰CoA"],["C","甲羟戊酸"],["D","乙酰乙酸"]],"A","脂肪酸合成过程中，乙酰CoA（A对）是主要的原料，它通常由葡萄糖代谢产生,乙酰CoA随后在脂肪酸合酶复合体的作用下，经过一系列反应逐步合成长链脂肪酸。脂肪酰CoA（B错）是脂肪酸β-氧化的中间产物，而不是脂肪酸合成的原料。甲羟戊酸（C错）是胆固醇合成的中间产物，与脂肪酸合成无关。乙酰乙酸（D错）是酮体的一种，由脂肪酸β-氧化产生，并不参与脂肪酸的合成。","","N"],["2024-N123",5,"第5节 胆固醇代谢","胆固醇的合成调节",2024,123,"B","","HMG-CoA还原酶的别构抑制剂是",[["A","乙酰CoA"],["B","脂肪酰CoA"],["C","甲羟戊酸"],["D","乙酰乙酸"]],"C","HMG-CoA还原酶是胆固醇合成途径中的关键酶，它催化HMG-CoA还原生成甲羟戊酸，这是胆固醇合成的重要步骤。甲羟戊酸是HMG-CoA还原酶的直接产物，在胆固醇合成途径中起着重要作用，当细胞内胆固醇水平升高时，甲羟戊酸（C对）可以作为一种别构抑制剂，与HMG-CoA还原酶结合并改变其构象，从而降低酶的活性，这种负反馈调节机制有助于维持细胞内胆固醇水平的稳定。乙酰CoA（A错）是胆固醇合成的原料，它可以通过一系列反应生成HMG-CoA，进而参与胆固醇的合成，但它本身不调节HMG-CoA还原酶的活性。脂肪酰CoA（B错）是脂肪酸β-氧化的中间产物，乙酰乙酸（D错）是酮体的一种，二者均与胆固醇合成途径无直接关联。","","N"],["2024-N142",22,"第2节 血红素的合成","在线粒体内合成ALA",2024,142,"X","","参与血红素合成调节的酶有",[["A","血红素加氧酶"],["B","ALA合酶"],["C","亚铁螯合酶"],["D","谷胱甘肽还原酶"]],"BC","血红素合成是一个复杂的生物化学过程，涉及多个酶的参与。ALA合酶（B对）催化琥珀酰CoA和甘氨酸的缩合反应生成δ-氨基-γ-酮戊酸（ALA），这是血红素生物合成的第一步反应，也是限速步骤。ALA合酶的活性受多种因素调节，包括其基因表达的转录水平调节和通过血红素对其活性的负反馈调节。血红素水平升高会抑制ALA合酶的活性，这是一种负反馈机制，防止过量的血红素合成。亚铁螯合酶（C对）催化原卟啉Ⅸ与Fe²⁺螯合生成血红素。亚铁螯合酶的活性也受到血红素的反馈抑制，当细胞内血红素水平升高时，亚铁螯合酶的活性降低，从而减少血红素的合成。血红素加氧酶（十版生物化学P474）（A错）是血红素降解途径中的关键酶，它催化血红素降解为胆绿素、Fe²⁺和一氧化碳。谷胱甘肽还原酶（十版生物化学P12）（D错）参与维持细胞内谷胱甘肽的还原状态。","","N"],["2024-N143",15,"第4节 生物分子相互作用研究技术","酵母双杂交技术",2024,143,"X","","用于研究蛋白质-蛋白质相互作用的技术有",[["A","酵母双杂交"],["B","免疫共沉淀"],["C","GST Pull-down"],["D","ChIP"]],"ABC","酵母双杂交技术（A对）是一种在酵母细胞内研究蛋白质-蛋白质相互作用的方法。其原理是利用酵母的转录因子作为“诱饵”蛋白与目的蛋白融合，通过检测报告基因的表达来判断两种蛋白之间是否存在相互作用。免疫共沉淀技术（B对）是利用抗原和抗体之间的特异性结合来研究蛋白质-蛋白质相互作用的方法。通过将目标蛋白与特异性抗体结合形成免疫复合物，然后利用蛋白A/G等试剂将免疫复合物沉淀下来，从而分离出与目标蛋白相互作用的蛋白质。GST Pull-down技术（C对）是一种利用谷胱甘肽S转移酶（GST）融合蛋白来研究蛋白质-蛋白质相互作用的方法。通过将目标蛋白与GST标签融合表达，然后利用GST标签与固定在珠子上的谷胱甘肽特异性结合的特性，将目标蛋白及其相互作用的蛋白质一起拉下来，从而实现对蛋白质相互作用的检测。ChIP（D错）即染色质免疫共沉淀技术，是一种研究蛋白质与DNA相互作用的方法，而不是研究蛋白质-蛋白质相互作用的技术。","","N"],["2024-N144",15,"第5节 基因表达分析技术","鉴定基因的功能区域的作用",2024,144,"X","","可应用于基因启动子结构分析的技术有",[["A","PCR结合测序技术"],["B","核酸-蛋白质相互作用技术"],["C","标签蛋白质沉淀"],["D","生物信息学预测"]],"ABD","基因启动子是位于基因上游区域的DNA序列，对基因的表达起着关键的调控作用。启动子区域通常包含多个特定的序列元件，这些元件可以被不同的转录因子识别和结合，从而调节基因的转录活性。分析基因启动子结构对于理解基因表达调控机制至关重要。PCR结合测序技术（A对）是分析基因启动子结构的重要手段之一。通过PCR技术可以特异性地扩增出目的基因的启动子区域，然后利用测序技术对扩增产物进行测序，从而得到启动子区域的核苷酸序列信息。这些信息对于分析启动子的结构、转录因子结合位点以及调控机制具有重要意义。核酸-蛋白质相互作用技术（B对）也是研究基因启动子结构的有效方法。启动子是转录因子结合的位点，转录因子通过与启动子的相互作用来调控基因的表达。因此，利用核酸-蛋白质相互作用技术可以分析转录因子与启动子的结合情况，从而揭示启动子的结构和功能。生物信息学预测（D对）在基因启动子结构分析中发挥着重要作用。通过利用生物信息学工具和数据库，可以对启动子区域进行序列分析、转录因子结合位点预测以及功能注释等。这些预测结果可以为实验验证提供有价值的线索和指导，从而加速对启动子结构和功能的研究进程。标签蛋白沉淀技术（十版生物化学P348）（C错）通常用于研究蛋白质-蛋白质相互作用，而不应用于基因启动子结构分析。","","N"],["2024-N145",19,"第3节 抑癌基因","抑癌基因对细胞增殖起负性调控作用",2024,145,"X","","具有细胞周期抑制作用的分子有",[["A","RB"],["B","p53"],["C","p16"],["D","EGF"]],"ABC","抑癌基因（肿瘤抑制基因）是防止或阻止癌症发生的基因，部分抑癌基因可以通过抑制细胞周期对细胞增殖起负性调控作用。RB基因编码的RB（A对）蛋白在低磷酸化状态下通过与E2F-1结合发挥活性，使之失活，导致细胞周期的进展受到抑制。TP53基因是目前研究最多的、也是迄今发现在人类肿瘤中发生突变最广泛的抑癌基因，其编码蛋白p53（B对）可阻止细胞通过G₁/S期检查点，使其停滞于G₁期，阻碍DNA受损的细胞继续分裂。P16基因编码p16（C对）蛋白，也可对细胞周期检查点进行负调节。EGF（表皮生长因子）可通过Ras/MAPK途径促进细胞周期的活化，进而促进表皮与上皮细胞的生长，并不能抑制细胞周期（十版生物化学P438）（D错）。","","N"],["2024-N146",21,"第2节 肝的生物转化作用","肝生物转化的过程",2024,146,"X","","在生物转化结合反应中，常见的结合基团有",[["A","葡萄糖醛酸基"],["B","硫酸根"],["C","乙酰基"],["D","甘氨酰基"]],"ABCD","生物转化作用是指机体在排出有毒性的非营养物质前对他们进行代谢转变，使其水溶性提高，极性增强，易于通过胆汁或尿排出。肝中进行的生物转化可分为两相反应（十版生物化学P463），第一相反应包括氧化、还原和水解，第二相反应为结合反应。结合反应中最常见的结合物是活性葡萄糖醛酸提供的葡萄糖醛酸基（A对），此外活性硫酸（PAPS）提供的硫酸根（B对）、乙酰CoA提供的乙酰基（C对）、甘氨酸提供的甘氨酰基（D对）等也为较常见的结合物。","","N"],["2024-N147",5,"第4节 磷脂代谢","甘油二酯合成途径",2024,147,"X","","通过甘油二酯途径合成的磷脂有",[["A","卵磷脂"],["B","脑磷脂"],["C","肌醇磷脂"],["D","心磷脂"]],"AB","甘油磷脂合成有两条途径，一条是磷脂酰胆碱和磷脂酰乙醇胺通过甘油二酯途径合成，胆碱和乙醇胺被活化成CDP-胆碱和CDP-乙醇胺后，分别与甘油二酯缩合，生成磷脂酰胆碱（卵磷脂）（A对）和磷脂酰乙醇胺（脑磷脂）（B对）；另一条是肌醇磷脂、丝氨酸磷脂及心磷脂通过CDP-甘油二酯途径合成，CDP­甘油二酯与丝氨酸、肌醇或磷脂酰甘油缩合，生成肌醇磷脂（C错）、丝氨酸磷脂及心磷脂（D错）。","","N"],["2024-N148",19,"第2节 癌基因","生长因子的分类及作用机制",2024,148,"X","","在下列基因中，属于原癌基因的有",[["A","RAS"],["B","MYC"],["C","PTEN"],["D","RB"]],"AB","细胞癌基因是基因组内正常存在的基因，其编码产物涉及生长因子信号转导的多个环节，通过正调控信号促进细胞的增殖和生长。RAS基因编码的蛋白质为细胞内信号转导分子，通过MAPK通路促进细胞生长（A对）。MYC基因编码的蛋白质为核内转录因子，通过促进增殖相关基因表达，促进细胞增殖（B对）。PTEN基因属于抑癌基因，主要通过抑制PI3K-AKT信号通路而发挥抑癌功能（十版生物化学P444）（C错）。RB基因也属于抑癌基因，在低磷酸化状态下与E2F-1结合发挥活性，抑制细胞周期（十版生物化学P442），阻碍细胞增殖（D错）。","","N"],["2025-N17",0,"第2节 蛋白质的分子结构","结构模体",2025,17,"A","","关于蛋白质结构的叙述，正确的是",[["A","肌红蛋白有四个亚基"],["B","模体属于蛋白质的超二级结构"],["C","蛋白质空间结构决定一级结构"],["D","一个氨基酸改变不会影响蛋白质空间结构"]],"B","肌红蛋白是由153个氨基酸残基构成的单一肽链蛋白质，含有1个血红素辅基，并不包含四个亚基（A错）。模体是蛋白质分子中具有特定空间构象和特定功能的结构成分，可由2个或2个以上具有二级结构的肽段在空间上相互接近，形成一个有规则的二级结构组合，属于超二级结构（B对）。蛋白质的一级结构是指蛋白质分子中从N端至C端的氨基酸排列顺序，它决定了蛋白质的空间结构，而不是蛋白质空间结构决定一级结构（C错）。氨基酸的排列顺序决定蛋白质的一级结构，一个氨基酸的改变可能会导致其空间结构发生显著变化（D错）。","","N"],["2025-N18",4,"第6节 糖异生","糖异生的关键酶及耗能",2025,18,"A","","葡萄糖-6-磷酸酶的作用是",[["A","使葡萄糖磷酸化"],["B","促进糖异生"],["C","催化NADPH的生成"],["D","糖酵解的关键酶"]],"B","肝细胞内含有葡萄糖-6-磷酸酶，在饥饿状态下可将肝糖原分解生成的葡萄糖-6-磷酸水解成葡萄糖以补充血糖，因此葡萄糖-6-磷酸酶的作用是促进糖异生（B对）。葡萄糖磷酸化（A错）发生在糖酵解阶段，由己糖激酶催化，生成葡萄糖-6-磷酸。葡萄糖-6-磷酸酶并不催化NADPH的生成（C错），而是由葡萄糖-6-磷酸脱氢酶催化葡萄糖-6-磷酸氧化成6-磷酸葡萄糖酸内酯，脱下的氢由NADP⁺接受，然后生成NADPH。葡萄糖-6-磷酸酶不是糖酵解的关键酶（D错），糖酵解的关键酶包括己糖激酶、磷酸果糖激酶-1和丙酮酸激酶。","","N"],["2025-N19",5,"第3节 甘油三酯代谢","酮体的生成的意义",2025,19,"A","","酮体的特点是",[["A","脂溶性"],["B","中性物质"],["C","肌组织产生"],["D","易透过血脑屏障"]],"D","酮体生成是以脂肪酸β-氧化生成的乙酰CoA为原料，在肝线粒体（C错）由酮体合成酶系催化完成，包括乙酰乙酸、β-羟基丁酸和丙酮。酮体分子小，溶于水，具有水溶性（A错），呈酸性（B错），在体内大量堆积时可造成酸中毒，能在血液中运输，还能通过血脑屏障（D对）、肌组织的毛细血管壁，很容易被运输到肝外组织利用。","","N"],["2025-N20",7,"第2节 线粒体氧化体系与呼吸链","甘油-3-磷酸穿梭",2025,20,"A","","甘油-3-磷酸穿梭的生理意义是",[["A","糖异生中间环节"],["B","有利于脂肪酸合成"],["C","促使胞质溶胶中2H进入线粒体"],["D","抑制底物水平磷酸化"]],"C","在脑和肌组织中，细胞质的NADH主要通过甘油-3-磷酸（α-磷酸甘油）穿梭方式进入线粒体呼吸链进行氧化。细胞质中的NADH+H⁺在磷酸甘油脱氢酶催化下，将2H传递给磷酸二羟丙酮，使其还原成甘油-3-磷酸，后者通过线粒体外膜到达线粒体内膜的膜间隙侧，在线粒体内膜的膜间隙侧结合着磷酸甘油脱氢酶的同工酶，含FAD辅基，接受甘油-3-磷酸的2H生成FADH₂和磷酸二羟丙酮，然后FADH₂直接将2H传递给泛醌进入氧化呼吸链（C对）。甘油-3-磷酸穿梭是ATP生成过程中的一个阶段，不是糖异生的中间环节（A错）。因为NADH不能自由穿过线粒体内膜，所以在细胞质中经糖酵解等生成的NADH需通过甘油-3-磷酸穿梭机制进入线粒体的呼吸链进行氧化，不涉及脂肪酸的合成（B错）。底物水平磷酸化发生在糖的无氧氧化的糖酵解阶段和糖的有氧氧化的三羧酸循环阶段，甘油-3-磷酸穿梭与这两个阶段无关（D错）。","","N"],["2025-N21",3,"第2节 水溶性维生素","叶酸",2025,21,"A","","作为叶酸类似物起到抗肿瘤作用的物质是",[["A","6-巯基嘌呤"],["B","氮杂丝氨酸"],["C","阿糖胞苷"],["D","甲氨蝶呤"]],"D","甲氨蝶呤（D对）为叶酸的类似物，能抑制二氢叶酸还原酶的活性，使FH₄合成减少，进而抑制体内胸腺嘧啶核苷酸的合成，起到抗肿瘤的作用。6-巯基嘌呤（6-MP）（A错）是次黄嘌呤的类似物，6-MP在体内经磷酸核糖化生成6-MP核苷酸，并以这种形式抑制次黄嘌呤核苷酸转变为腺嘌呤核苷酸及鸟嘌呤核苷酸的反应，主要用于治疗儿童急性淋巴细胞白血病。氮杂丝氨酸（B错）为谷氨酰胺的类似物，可干扰谷氨酰胺在嘌呤核苷酸合成中的作用，从而抑制嘌呤核苷酸的合成。阿糖胞苷（C错）为嘧啶核苷的类似物，影响DNA多聚酶功能进而抑制DNA合成，用于成人和儿童急性非淋巴细胞白血病的诱导缓解和维持治疗。","","N"],["2025-N22",11,"第3节 原核生物DNA复制过程","引物合成和起始复合物的形成",2025,22,"A","","DNA复制时催化引物合成的酶是",[["A","DNA聚合酶"],["B","RNA聚合酶"],["C","解旋酶"],["D","拓扑异构酶"]],"B","DNA复制起始过程需要先合成引物，引物是由引物酶催化合成的短链RNA分子，而引物酶属于RNA聚合酶（B对）。DNA聚合酶（A错）全称是依赖DNA的DNA聚合酶，催化脱氧核糖核苷酸间的聚合。解旋酶（C错）是复制起始利用ATP供能来解开DNA双链的酶，其中DnaB在原核生物中起解旋酶的作用。拓扑异构酶（D错）是调控DNA的拓扑状态和催化拓扑异构体相互转换，以理顺DNA链结构来配合复制进程。","","N"],["2025-N23",12,"第3节 真核生物mRNA的转录、加工和降解","顺式作用元件在真核基因转录起始中的作用",2025,23,"A","","RNA聚合酶可以识别的DNA位点是",[["A","TATA盒"],["B","起始密码ATG"],["C","沉默子"],["D","增强子"]],"A","DNA分子上能够介导RNA聚合酶结合并形成转录起始复合体的序列的是启动子，真核生物主要有3类启动子，其中TATA盒（A对）是Ⅱ类启动子的核心序列，是RNA聚合酶可识别的DNA位点。起始密码子ATG（B错）是mRNA上的序列，用于指示翻译的起始。沉默子（C错）是可抑制基因转录的特定DNA序列，当其结合一些反式作用因子时对基因的转录起阻遏作用，使基因沉默。增强子（D错）可以增强真核启动子工作效率的顺式作用元件，决定着每一个基因在细胞内的表达水平，能够在相对于启动子的任何方向和任何位置（上游或者下游）上发挥这种增强作用。","","N"],["2025-N24",13,"第3节 肽链的合成过程","转位",2025,24,"A","","多肽链合成时延长因子EF-G所起的作用是",[["A","分子伴侣"],["B","转录因子"],["C","辅酶"],["D","转位"]],"D","在多肽链合成过程中，延长因子EF-G发挥着至关重要的作用，其有转位酶活性，促进mRNA-肽酰-tRNA由A位移至P位，促进tRNA卸载与释放（D对），确保合成中的多肽链能够持续延长。分子伴侣（A错）参与蛋白质的折叠过程，辅助合成中的蛋白质折叠成正确的空间构象。转录因子（B错）主要参与RNA的合成，在RNApolⅡ启动转录时，与其形成具有活性的转录复合体。辅酶（C错）主要参与构成酶的活性中心，参与催化反应。","","N"],["2025-N25",2,"第3节 RNA和空间结构与功能","非编码RNA的功能",2025,25,"A","","siRNA的生物学作用是",[["A","参与多肽链的合成"],["B","逆转录的模板"],["C","介导mRNA降解"],["D","核糖体的一部分"]],"C","siRNA（干扰小RNA）属于调控性非编码小RNA，参与RNA诱导的沉默复合体的组成，与特异的靶mRNA完全互补结合，导致靶mRNA降解，阻断翻译过程（C对）。参与多肽链的合成（A错）是tRNA的功能，tRNA是蛋白质合成中氨基酸的载体，为合成中的多肽链提供活化的氨基酸。逆转录是RNA病毒的复制方式，逆转录酶催化以RNA为模板合成双链DNA（B错）。核糖体是细胞内蛋白质合成的场所，由rRNA和蛋白质组成（D错）。","","N"],["2025-N26",16,"第3节 重组DNA技术在医学中的应用","重组DNA技术应用于生物医学",2025,26,"A","","重组DNA技术目前在医学上主要应用于",[["A","中药有效成分的提取"],["B","影像技术的改进"],["C","基因工程药物的研发"],["D","药物在体内的示踪"]],"C","重组DNA技术指通过体外操作将不同来源的两个或两个以上DNA分子重新组合，并在适当细胞中扩增形成新功能DNA分子的方法，已广泛应用于生命科学和医学研究、疾病诊断与防治等领域，目前在医学领域中的应用主要是基因工程药物的研发（C对）。中药有效成分的提取（A错）主要涉及到化学分离技术，并不直接关联到重组DNA技术。影像技术的改进（B错），如CT、MRI等医疗设备和技术的发展，属于医学影像领域，而非重组DNA技术的应用范畴。药物在人体内的示踪（D错）主要是药理学和药物代谢动力学的研究内容，与重组DNA技术不相关。","","N"],["2025-N27",17,"第2节 细胞内信号转导分子","G蛋白的作用",2025,27,"A","","下列属于小G蛋白的分子是",[["A","钙调蛋白"],["B","RAS"],["C","异三聚体G蛋白"],["D","PKC"]],"B","属于小G蛋白的是RAS（B对），RAS是第一个被发现的低分子量G蛋白，分子量为21kDa，与异三聚体G蛋白相似，有鸟苷酸结合位点和GTP酶活性，在细胞内分别参与不同的信号转导途径。钙调蛋白（A错）是一种钙结合蛋白，其本身无活性，当与钙离子形成复合物时，可调节钙调蛋白依赖性蛋白激酶的活性。异三聚体G蛋白（C错）具备鸟苷酸结合位点和GTP酶活性，但其由α、β和γ三个亚基构成，分子量较大且结构复杂，不属于小G蛋白。PKC（D错），即蛋白激酶C，属于蛋白激酶家族，是一类在细胞信号转导中重要的丝氨酸/苏氨酸蛋白激酶，能够催化多种蛋白质底物的磷酸化。","","N"],["2025-N28",19,"第3节 抑癌基因","抑癌基因在癌症发生发展中具有重要作用",2025,28,"A","","抑癌基因PTEN产物的酶活性类型是",[["A","激酶"],["B","乙酰化酶"],["C","磷酸酶"],["D","硫解酶"]],"C","抑癌基因PTEN是迄今发现的第一个具有双特异磷酸酶活性的抑癌基因，其产物酶活性类型是磷酸酶（C对），使酶发生去磷酸化。激酶（A错）是催化磷酸基团转移到其他分子的酶，如蛋白激酶A可将糖原合酶的多个丝氨酸残基磷酸化。乙酰化酶（B错）是催化乙酰化反应的酶，例如可以对组蛋白中的赖氨酸、精氨酸、组氨酸等带有正电荷的碱性氨基酸进行乙酰化。硫解酶（D错）主要参与脂肪酸的β-氧化过程，硫解产生乙酰CoA。","","N"],["2025-N120",13,"第4节 蛋白质合成后的加工和靶向输送","氨基酸残基的化学修饰",2025,120,"B","","被磷酸化修饰的常见氨基酸残基是",[["A","半胱氨酸残基"],["B","丝氨酸残基"],["C","亮氨酸残基"],["D","甲硫氨酸残基"]],"B","酶蛋白肽链上某些氨基酸残基侧链可在另一酶的催化下发生可逆的共价修饰，从而改变酶活性，以磷酸化与去磷酸化最多见，其中被磷酸化修饰的常见氨基酸残基是丝氨酸残基（B对），以及苏氨酸残基和酪氨酸残基。半胱氨酸残基（A错）的侧链含有一个硫原子，2个半胱氨酸通过脱氢后以二硫键相连接，形成胱氨酸。亮氨酸残基（C错）可以参与形成亮氨酸拉链，与癌基因表达调控功能有关。甲硫氨酸残基（D错）含有S-甲基，可通过各种转甲基作用生成多种含甲基的生理活性物质，如肾上腺素、肉碱、胆碱及肌酸等。","","N"],["2025-N121",0,"第1节 蛋白质的分子组成","氨基酸的分类",2025,121,"B","","能够形成二硫键的氨基酸残基是",[["A","半胱氨酸残基"],["B","丝氨酸残基"],["C","亮氨酸残基"],["D","甲硫氨酸残基"]],"A","能形成二硫键的氨基酸残基是半胱氨酸残基（A对），半胱氨酸残基的侧链含有一个硫原子，2个半胱氨酸通过脱氢后以二硫键相连接，形成胱氨酸。丝氨酸残基（B错）是可被磷酸化修饰的常见氨基酸残基，从而改变酶活性，此外还包括苏氨酸残基和酪氨酸残基。亮氨酸残基（C错）可以参与形成亮氨酸拉链，与癌基因表达调控功能有关。甲硫氨酸残基（D错）含有S-甲基，可通过各种转甲基作用生成多种含甲基的生理活性物质，如肾上腺素、肉碱、胆碱及肌酸等。","","N"],["2025-N122",22,"第3节 血细胞物质代谢","红细胞内的糖无氧氧化的特殊途径",2025,122,"B","","能够调节血红蛋白运氧功能的物质是",[["A","2，3-BPG"],["B","ALA"],["C","MHb"],["D","NADPH"]],"A","2，3-BPG（A对）即2，3-二磷酸甘油酸，是红细胞内糖酵解的中间产物，可以与血红蛋白结合，调节血红蛋白运氧功能，升高的2，3-BPG可降低Hb与O₂的亲和力，使组织中氧的释放量增加。ALA（B错）即δ-氨基-γ-酮戊酸，是血红素合成的中间产物，并不参与血红蛋白运氧功能的调节。MHb（C错）即高铁血红蛋白，是血红蛋白的一种氧化形式，该变化导致血红蛋白失去与氧气结合的能力。NADPH（D错）能维持红细胞内还原型谷胱甘肽（GSH）的含量，维持血红蛋白还原状态，使红细胞免遭外源性和内源性氧化剂的损害。","","N"],["2025-N123",22,"第3节 血细胞物质代谢","戊糖磷酸途径提供NADPH维持红细胞完整",2025,123,"B","","能够保护血红蛋白处于还原状态的物质是",[["A","2，3-BPG"],["B","ALA"],["C","MHb"],["D","NADPH"]],"D","NADPH（D对）能维持红细胞内还原型谷胱甘肽（GSH）的含量，维持血红蛋白还原状态，使红细胞免遭外源性和内源性氧化剂的损害。2，3-BPG（A错）即2，3-二磷酸甘油酸，是红细胞内糖酵解的中间产物，可以与血红蛋白结合，调节血红蛋白运氧功能，升高的2，3-BPG可降低Hb与O₂的亲和力，使组织中氧的释放量增加。ALA（B错）即δ-氨基-γ-酮戊酸，是血红素合成的中间产物，并不参与血红蛋白运氧功能的调节。MHb（C错）即高铁血红蛋白，是血红蛋白的一种氧化形式，该变化导致血红蛋白失去与氧气结合的能力。","","N"],["2025-N142",2,"第4节 核酸的理化性质","DNA变性",2025,142,"X","","DNA变性后的理化性质改变有",[["A","黏度降低"],["B","碱基对之间氢键断裂"],["C","密度增加"],["D","260nm吸光度增加"]],"ABCD","DNA变性指在某些极端的理化条件（温度、pH、离子强度等）可以断裂DNA双链互补碱基对之间的氢键（B对）以及破坏碱基堆积力，使一条DNA双链解离成为两条单链的现象。DNA变性后，其双螺旋结构解开，由原本紧密有序的状态变为松散无序的单链状态，因此其溶液的黏度降低（A对）。DNA变性后，双链解开成单链，空间结构变得松散，分子内部的堆积方式发生改变，使得DNA分子的密度增加（C对）。DNA变性后原本隐藏在双链内部的碱基暴露出来，由于嘌呤和嘧啶环中均含有共轭双键，使得DNA分子在260nm处的吸光度增加（D对）。","","N"],["2025-N143",5,"第1节 脂质的构成、功能及分析","脂肪酸的生物学功能",2025,143,"X","","花生四烯酸可以转变成的生物活性物质有",[["A","前列腺素"],["B","血栓素"],["C","白三烯"],["D","泛素"]],"ABC","花生四烯酸是一种多不饱和脂肪酸，单核巨噬细胞可将花生四烯酸转变成前列腺素（A对）和血栓素（B对），而在脂氧化酶的作用下，粒细胞和单核巨噬细胞可将花生四烯酸转变成白三烯（C对）。泛素（D错）并不是由花生四烯酸转化的生物活性物质，它是一种由76个氨基酸组成的小分子蛋白质，可以介导蛋白质的降解过程。","","N"],["2025-N144",6,"第4节 个别氨基酸的代谢","甲硫氨酸循环",2025,144,"X","","参与甲硫氨酸循环代谢途径的维生素有",[["A","维生素B₁₂"],["B","维生素D"],["C","叶酸"],["D","泛酸"]],"AC","甲硫氨酸循环指S-腺苷甲硫氨酸经甲基转移酶催化，将甲基转移至另一种物质，使其发生甲基化反应，而S-腺苷甲硫氨酸失去甲基后生成 S-腺苷同型半胱氨酸，后者脱去腺苷生成同型半胱氨酸，同型半胱氨酸若再接受 N⁵-CH₃-FH₄ 提供的甲基，则可重新生成甲硫氨酸。维生素B₁₂（A对）参与甲硫氨酸循环代谢途径，是甲硫氨酸循环中的甲硫氨酸合成酶的辅酶。叶酸（C对），也被称为蝶酰谷氨酸，活性形式是四氢叶酸，通过一碳单位的转移来参与甲硫氨酸循环代谢途径。维生素D（B错）主要参与钙和磷的代谢，与骨骼健康密切相关，并不参与甲硫氨酸循环。泛酸（D错）又称遍多酸、维生素 B₅，其活性形式是辅酶A和酰基载体蛋白质，广泛参与糖、脂质、蛋白质代谢及肝的生物转化作用，与甲硫氨酸循环没有直接关系。","","N"],["2025-N145",14,"第3节 真核基因表达调控","表观遗传机制对基因表达的作用",2025,145,"X","","表观遗传修饰的种类有",[["A","激酶磷酸化修饰"],["B","DNA甲基化修饰"],["C","RAS棕榈酰化修饰"],["D","组蛋白乙酰化修饰"]],"BD","表观遗传是指染色质结构对基因表达的影响可以遗传给子代细胞，其机制是细胞内存在着具有维持甲基化作用的DNA甲基转移酶，可以在DNA复制后，依照亲本DNA链的甲基化位置催化子链DNA在相同位置上发生甲基化的现象。表观遗传的修饰种类包括DNA甲基化（B对）、组蛋白的乙酰化（D对）等。而激酶磷酸化修饰（A错）和RAS棕榈酰化修饰（C错）虽然都是蛋白质修饰的常见方式，分别涉及蛋白质功能的调控和蛋白质的定位及功能，但它们并不直接属于表观遗传修饰的范畴，因为它们不直接涉及基因表达的调控。","","N"],["2025-N146",21,"第2节 肝的生物转化作用","肝生物转化的过程",2025,146,"X","","属于肝生物转化第一相反应的有",[["A","氧化反应"],["B","还原反应"],["C","水解反应"],["D","结合反应"]],"ABC","肝生物转化的第一相反应包括氧化反应（A对）、还原反应（B对）和水解反应（C对）。其中，氧化反应是最多见的第一相反应，是物质在肝脏中加氧或脱氢的过程，这一反应可以由单加氧酶系、单胺氧化酶类和脱氢酶类催化。还原反应涉及加氢或去氧的过程，主要依靠硝基还原酶和偶氮还原酶。水解反应在肝生物转化中也非常关键，涉及酯类、酰胺类等的分解，主要依靠酯酶、酰胺酶和糖苷酶。结合反应（D错）是肝生物转化的第二相反应，主要涉及物质与极性更强的物质结合，以便增加水溶性，便于排泄。","","N"],["2025-N147",16,"第2节 重组DNA技术","常用工具酶",2025,147,"X","","能够作为重组DNA技术的工具酶有",[["A","DNA连接酶"],["B","逆转录酶"],["C","RNA聚合酶"],["D","限制性核酸内切酶"]],"ABD","参与DNA重组过程的酶包括DNA连接酶（A对）、DNA聚合酶Ⅰ、逆转录酶（B对）、Ⅱ型限制性核酸内切酶（D对）、多聚核苷酸激酶、碱性磷酸酶等。DNA连接酶是在DNA重组过程中起着关键作用的酶之一，负责在DNA片段之间形成磷酸二酯键，从而连接DNA断裂的末端。逆转录酶是以RNA为模板的DNA 聚合酶，用于合成cDNA，也用于替代DNA聚合酶Ⅰ进行缺口填补、标记或DNA序列分析等。限制性核酸内切酶能识别并切割特定DNA序列，是DNA重组技术的关键工具。RNA聚合酶（C错）负责催化不同RNA的合成，并不直接参与DNA重组。","","N"],["2026-N17",14,"第3节 真核基因表达调控","小分子RNA对基因表达的调节",2026,17,"A","","能引起靶细胞mRNA特异降解的双链小RNA分子是",[["A","核小RNA"],["B","核仁小RNA"],["C","干扰小RNA"],["D","催化小RNA"]],"C","能引起靶细胞mRNA特异降解的双链小RNA分子是干扰小RNA（C对），因为干扰小RNA通过RNA干扰机制，与靶mRNA互补结合并招募RISC复合体，导致mRNA的特异性降解。核小RNA（A错）参与核内pre-mRNA的剪接加工，不引起mRNA降解。核仁小RNA（B错）定位于核仁，主要参与rRNA的加工。催化小RNA（D错）也称为核酶，是细胞内具有催化功能的一类小分子RNA统称，具有催化特定RNA降解的活性，但非双链结构。","","N"],["2026-N18",1,"第3节 酶促反应动力学","非竞争性抑制",2026,18,"A","","能够使酶表现Kₘ值不变、Vₘₐₓ降低的抑制性质是",[["A","竞争性抑制"],["B","非竞争性抑制"],["C","反竞争性抑制"],["D","不可逆性抑制"]],"B","在酶抑制机制中，Kₘ值反映酶与底物的亲和力，Vₘₐₓ表示最大反应速度。非竞争性抑制（B对）时，抑制剂与酶-底物复合物结合，不影响酶对底物的亲和力，因此Kₘ值不变，但降低酶的催化效率，导致Vₘₐₓ降低。竞争性抑制（A错）中抑制剂与底物竞争活性位点，增加Kₘ值，亲和力降低，Vₘₐₓ不变。反竞争性抑制（C错）中抑制剂仅结合酶-底物复合物，降低Kₘ值和Vₘₐₓ。不可逆性抑制（D错）通过共价键灭活酶，不遵守米式方程。","","N"],["2026-N19",4,"第5节 糖原的合成与分解","糖原分解",2026,19,"A","","肌糖原不能转变成葡萄糖的原因是",[["A","缺乏糖原磷酸化酶"],["B","缺乏葡萄糖-6-磷酸酶"],["C","缺乏葡萄糖激酶"],["D","缺乏脱支酶"]],"B","在糖原分解过程中，肌糖原首先被糖原磷酸化酶分解为葡萄糖-1-磷酸，再转化为葡萄糖-6-磷酸，只有当葡萄糖-6-磷酸酶存在时，葡萄糖-6-磷酸才能水解为游离葡萄糖释放入血。然而，肌肉组织中缺乏葡萄糖-6-磷酸酶（B对），因此葡萄糖-6-磷酸无法转变为葡萄糖，只能进入糖酵解途径供能。肝糖原和肌糖原分解的起始阶段一样，肝脏和肌肉中都有糖原磷酸化酶（A错）。缺乏葡萄糖激酶（C错）影响葡萄糖的磷酸化过程，与糖原分解成葡萄糖无关。缺乏脱支酶（D错）虽可能导致糖原分解中断，但并非肌糖原无法转葡萄糖的根本原因。","","N"],["2026-N20",7,"第3节 氧化磷酸化与ATP的生成","质子顺梯度回流需要ATP合酶转运",2026,20,"A","","ATP合酶由F₁和F₀组成，其中F₀的含义是",[["A","首先发现的氧化磷酸化因子"],["B","催化ATP合成的部位"],["C","寡霉素结合部位"],["D","递氢递电子体"]],"C","ATP合酶由F₁（催化亚基）和F₀（膜嵌入亚基）组成。其中，F₀嵌入线粒体内膜形成离子通道，是寡霉素结合的部位（C对），因为寡霉素作为一种抑制剂特异性结合F₀的c亚基，阻断质子流从而抑制ATP合成。首先发现的氧化磷酸化因子（A错）是F₁，而非F₀。催化ATP合成的活性部位位于F₁（B错）。递氢递电子体（D错）指呼吸链中传递电子和质子的复合物（如复合体Ⅰ或Ⅱ），与F₀的质子转运功能不同。","","N"],["2026-N21",6,"第4节 个别氨基酸的代谢","一碳单位的来源及转换",2026,21,"A","","下列关于组氨酸的叙述，正确的是",[["A","分子结构中含有苯环"],["B","代谢产生一碳单位"],["C","活性形式可作为甲基供体"],["D","代谢障碍可引起白化病"]],"B","组氨酸分子结构中不含有苯环（A错），含苯环的氨基酸是苯丙氨酸、酪氨酸和色氨酸。组氨酸可作为一碳单位的来源（B对），因为组氨酸在代谢途径中可被分解为谷氨酸和甲酰谷氨酸，后者参与一碳单位循环。组氨酸活性形式不能作为甲基供体（C错），甲基供体主要由甲硫氨酸或S-腺苷甲硫氨酸提供。组氨酸代谢障碍不会引起白化病（D错），白化病是由酪氨酸代谢中酪氨酸酶缺乏导致。","","N"],["2026-N22",11,"第3节 原核生物DNA复制过程","引物合成和起始复合物的形成",2026,22,"A","","能够催化RNA链3'末端和NTP形成磷酸二酯键的酶是",[["A","DAN聚合酶"],["B","逆转录酶"],["C","连接酶"],["D","引物酶"]],"D","能催化RNA链3'末端和核糖核苷三磷酸（NTP）形成磷酸二酯键的酶是引物酶（D对），因为引物酶在DNA复制中负责合成RNA引物，通过将NTP添加到RNA链的3'羟基端形成磷酸二酯键。DAN聚合酶（A错）催化DNA合成使用脱氧核糖核苷三磷酸（dNTP），作用于DNA链而非RNA。逆转录酶（B错）以RNA为模板但合成DNA链，使用dNTP而非NTP。连接酶（C错）催化两个核酸片段的末端连接形成磷酸二酯键，但不涉及新NTP的添加或RNA链的延伸。","","N"],["2026-N23",11,"第4节 真核生物DNA复制过程","端粒酶参与解决染色体末端复制",2026,23,"A","","端粒酶RNA具有的特点是",[["A","自身具有转录模板的功能"],["B","具有特定启动子结构"],["C","属于催化性RNA"],["D","新发现的小RNA分子"]],"A","端粒酶是由催化蛋白和RNA模板组成的酶，可合成染色体末端的DNA，因此端粒酶RNA具有转录模板的功能（A对），此功能是指提供RNA模板以进行逆转录。启动子结构（B错）通常与DNA转录起始调控相关。催化性RNA（C错）指具有催化活性的RNA分子，与端粒酶RNA无关。端粒酶RNA并非新发现的小RNA分子（D错），而是已被深入研究数十年的经典RNA类型。","","N"],["2026-N24",13,"第2节 蛋白质合成体系","遗传密码的特点",2026,24,"A","","密码子第3位碱基与反密码子第1位碱基不严格配对是因为",[["A","密码子的连续性"],["B","密码子的简并性"],["C","密码子的摆动性"],["D","密码子的通用性"]],"C","反密码子的第1位碱基与密码子的第3位碱基配对有时存在摆动现象（C对），并不严格遵循Watson-Crick碱基配对原则。密码子的连续性（A错）指密码子作为三联体连续读取的特性。密码子的简并性（B错）指一个氨基酸可由多个密码子编码。密码子的通用性（D错）指密码子在大多数生物中编码相同氨基酸的特征。","","N"],["2026-N25",19,"第3节 抑癌基因","抑癌基因有多种失活机制",2026,25,"A","","基因启动子CpG岛高度甲基化可导致的结果是",[["A","DNA聚合酶活性改变"],["B","沉默子失去作用"],["C","转录受到抑制"],["D","产物肽链不能成熟"]],"C","基因启动子区域CpG岛的甲基化修饰对于调节基因转录活性至关重要，甲基化程度与基因表达呈负相关，所以高度甲基化会使基因转录受到抑制（C对）。DNA聚合酶活性改变（A错）涉及DNA复制的调控，与转录过程无关。沉默子是可抑制基因转录的特定DNA序列，基因启动子CpG岛高度甲基化不涉及沉默子（B错）。肽链合成不成熟（D错）是翻译阶段的问题，不受转录抑制影响。","","N"],["2026-N26",17,"第3节 细胞受体介导的细胞内信号转导","cAMP-PKA通路",2026,26,"A","","可作为G蛋白偶联受体配体的是",[["A","肾上腺素"],["B","维生素D₃"],["C","生长因子"],["D","维甲酸"]],"A","G蛋白偶联受体是一类跨膜受体，通过G蛋白介导细胞内信号转导，肾上腺素可以作为G蛋白偶联受体的配体（A对），肾上腺素结合肾上腺素受体激活cAMP-PKA途径。维生素D₃（B错）进入细胞后与细胞核内的维生素D₃受体结合，该受体属于核受体。生长因子（C错）通常作用于受体酪氨酸激酶，触发激酶级联反应。维甲酸（D错）是通过结合核受体调控基因表达。","","N"],["2026-N27",21,"第2节 肝的生物转化作用","结合反应",2026,27,"A","","属于肝生物转化第二相反应的是",[["A","酰基水杨酸水解成水杨酸"],["B","乙醇氧化成乙醛"],["C","苯酚转化为苯β-葡萄糖醛酸"],["D","硝基苯还原成亚硝基苯"]],"C","肝生物转化的第二相反应主要是结合反应，其核心是将内源性或外源性物质与极性基团结合以增加水溶性便于排泄，苯酚转化为苯β-葡萄糖醛酸（C对）属于肝生物转化的第二相反应。酰基水杨酸水解成水杨酸（A错）发生的是水解反应，属于肝的第一相反应。乙醇氧化成乙醛（B错）属于氧化反应，属于肝的第一相反应。硝基苯还原成亚硝基苯（D错）发生的是还原反应，属于第一相反应。","","N"],["2026-N28",22,"第2节 血红素的合成","血红素合成的调节步骤",2026,28,"A","","影响血红素合成的主要因素是",[["A","ALA合酶活性调节"],["B","清蛋白结构改变"],["C","维生素B₁缺乏"],["D","2，3-BPG与血红蛋白结合"]],"A","影响血红素合成的主要因素是ALA合酶活性调节（A对），ALA合酶是血红素合成体系的限速酶，受血红素的反馈抑制。清蛋白（B错）参与血浆渗透压和运输功能，与血红素合成无关联。维生素B₁缺乏（C错）主要导致能量代谢障碍，可以导致脚气病。2，3-BPG与血红蛋白结合（D错）调节血红蛋白氧亲和力，属于功能调节，而非合成过程的影响因素。","","N"],["2026-N120",0,"第1节 蛋白质的分子组成","氨基酸的基本结构单位",2026,120,"B","","能作为蛋白质生物合成原料的氨基酸是",[["A","鸟氨酸"],["B","硒代半胱氨酸"],["C","瓜氨酸"],["D","胱氨酸"]],"B","能作为蛋白质生物合成原料的氨基酸是硒代半胱氨酸（B对）。硒代半胱氨酸是天然存在的第21种参与蛋白质合成的氨基酸，通过UGA密码子的特殊机制（SECIS元件调控）直接掺入多肽链，存在于人体含硒酶（如谷胱甘肽过氧化物酶）的活性中心。鸟氨酸（A错）、瓜氨酸（C错）属于非蛋白质氨基酸，仅参与尿素循环，不直接作为蛋白质生物合成原料。胱氨酸（D错）是两分子半胱氨酸通过二硫键连接的产物，需先分解为半胱氨酸才能作为原料，本身并非直接原料。","","N"],["2026-N121",6,"第4节 个别氨基酸的代谢","半胱氨酸与胱氨酸的互相转变",2026,121,"B","","含有二硫键的氨基酸是",[["A","鸟氨酸"],["B","硒代半胱氨酸"],["C","瓜氨酸"],["D","胱氨酸"]],"D","胱氨酸（D对）由两分子半胱氨酸通过二硫键（-S-S-）连接形成，是含硫氨基酸的氧化形式。鸟氨酸（A错）、瓜氨酸（C错）均不含硫元素，无形成二硫键的结构基础。硒代半胱氨酸（B错）含硒原子（-SeH），而非巯基（-SH），无法形成二硫键。","","N"],["2026-N122",16,"第2节 重组DNA技术","重组DNA转入宿主细胞",2026,122,"B","","与转染有关的过程是",[["A","遗传物质在细菌之间转移的过程"],["B","质粒携带外源DNA进入细菌的过程"],["C","质粒携带外源DNA进入真核细胞的过程"],["D","病毒携带外源DNA进入靶细胞的过程"]],"C","与转染有关的过程是质粒携带外源DNA进入真核细胞的过程（C对）。遗传物质在细菌之间转移的过程（A错）是接合作用。质粒携带外源DNA进入细菌的过程（B错）是转化。病毒携带外源DNA进入靶细胞的过程（D错）是感染。","","N"],["2026-N123",16,"第2节 重组DNA技术","重组DNA转入宿主细胞",2026,123,"B","","与转化有关的过程是",[["A","遗传物质在细菌之间转移的过程"],["B","质粒携带外源DNA进入细菌的过程"],["C","质粒携带外源DNA进入真核细胞的过程"],["D","病毒携带外源DNA进入靶细胞的过程"]],"B","与转化有关的过程是质粒携带外源DNA进入细菌的过程（B对）。遗传物质在细菌之间转移的过程（A错）是接合作用。质粒携带外源DNA进入真核细胞的过程是转染（C错）。病毒携带外源DNA进入靶细胞的过程（D错）是感染。","","N"],["2026-N142",0,"第2节 蛋白质的分子结构","蛋白质的二级结构",2026,142,"X","","具有蛋白质超二级结构特点的有",[["A","亮氨酸拉链"],["B","锌指结构"],["C","α螺旋"],["D","β折叠"]],"AB","超二级结构是指由2个或2个以上具有二级结构的肽段在空间上相互接近，形成一个有规则的二级结构组合。具有蛋白质超二级结构特点的有亮氨酸拉链（A对）、锌指结构（B对）。α螺旋（C错）、β折叠（D错）属于二级结构基本单元，是构成超二级结构的组件，非超二级结构。","","N"],["2026-N143",5,"第5节 胆固醇代谢","胆固醇的转化",2026,143,"X","","胆固醇在体内可转化成的物质有",[["A","胆红素"],["B","胆汁酸"],["C","维生素D₃"],["D","胆素原"]],"BC","胆固醇在肝脏可转变为胆汁酸（B对），在皮肤可转化为维生素D₃（C对），其中转化为胆汁酸是主要去路。胆红素（A错）的来源是血红素的分解，它主要来自衰老红细胞中血红蛋白的降解，少部分来自肌红蛋白、细胞色素等含血红素蛋白的分解。胆素原（D错）是结合胆红素进入肠道后，在细菌作用下脱去葡萄糖醛酸基并被还原生成的化合物。","","N"],["2026-N144",8,"第2节 嘌呤核苷酸的合成与分解代谢","嘌呤核苷酸从头合成调节",2026,144,"X","","嘌呤核苷酸从头合成中，受反馈调节的酶有",[["A","PRPP合成酶"],["B","PRPP酰胺转移酶"],["C","IMP脱氢酶"],["D","CPS-Ⅱ"]],"ABC","嘌呤核苷酸从头合成途径中，主要调控环节是第一步生成PRPP和第二步生成5-磷酸核糖胺（PRA）的反应，催化反应的PRPP合成酶（A对）和PRPP酰胺转移酶（B对）是关键调控酶，均可被合成的产物IMP、AMP及GMP等反馈抑制。IMP脱氢酶（C对）可以催化IMP氧化生成黄嘌呤核苷酸（XMP)，受反馈调节。哺乳类动物细胞中，嘧啶核苷酸合成的调节酶主要是CPS-Ⅱ（D错），受UMP抑制。","","N"],["2026-N145",9,"第3节 代谢调节的主要方式","化学修饰调节对酶活性的调节",2026,145,"X","","酶化学修饰的特点",[["A","修饰的基团与酶共价连接"],["B","酶活性变化有级联放大效应"],["C","修饰反应是由另一酶催化"],["D","酶构象变化引起酶活性改变"]],"ABCD","酶的化学修饰是指酶蛋白肽链上的某些小分子基团可以共价结合到被修饰酶的特定氨基酸残基上（A对），引起酶分子构象变化，从而调节酶活性变化（D对）。酶的化学修饰调节具有级联放大效应（B对）。酶的化学修饰是由另一酶催化的酶促反应（C对），一分子催化酶可催化多个底物酶分子发生共价修饰，特异性强，有放大效应。","","N"],["2026-N146",19,"第3节 抑癌基因","抑癌基因有多种失活机制",2026,146,"X","","p53抑癌基因发挥作用的机制是",[["A","激活BAX基因"],["B","使细胞凋亡"],["C","使细胞分化停滞于G₁期"],["D","使原癌基因获得启动子"]],"ABC","p53的靶基因之一p21可阻止细胞通G₁/S期检查点，使其停滞于G₁期（C对）。另一靶基因GADD45的产物是DNA修复蛋白，使DNA受损的细胞不再分裂，并且修复损伤以维持基因组的稳定性，如果修复失败，p53蛋白会通过激活一些靶基因如BAX（A对）的转录而启动细胞凋亡（B对），阻止有癌变倾向的突变细胞的生成。逆转录病毒的前病毒 DNA整合到原癌基因上，可以使原癌基因获得启动子，导致原癌基因的活化和过量表达（D错），进而使细胞发生恶性转化，与p53抑癌基因发挥的作用相反。","","N"],["2026-N147",17,"第3节 细胞受体介导的细胞内信号转导","细胞内信号转导的概述",2026,147,"X","","以下在细胞内发挥作用的是",[["A","甲状腺激素"],["B","类固醇激素"],["C","转化生长因子β"],["D","乙酰胆碱"]],"AB","细胞内受体包括位于细胞质或胞核内的受体，其相应配体是脂溶性信号分子，能与细胞内受体结合的信号分子有类固醇激素（B对）、甲状腺激素（A对）、维甲酸和维生素D等。水溶性信号分子和膜结合性信号分子（如生长因子、细胞因子、水溶性激素分子、黏附分子等）不能进入靶细胞，其受体位于靶细胞的细胞质膜表面，转化生长因子β（C错）是常见的生长因子。乙酰胆碱（D错）可以作为离子通道型受体、G蛋白耦联受体的配体，这两类受体均是膜受体。","","N"]];
